// Initialize the dynamic array of UE contexts
ContextArray* init_context_array(size_t initial_capacity) {
    ContextArray *array = malloc(sizeof(ContextArray));
    if (!array) return NULL;

    array->contexts = calloc(initial_capacity, sizeof(UEContext *));
    if (!array->contexts) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;

    return array;
