// Resize the context array when capacity is reached
static int resize_context_array(ContextArray *array) {
    size_t new_capacity = array->capacity * 2;
    UEContext **new_contexts = realloc(array->contexts, new_capacity * sizeof(UEContext *));
    if (!new_contexts) return -1;

    array->contexts = new_contexts;
    array->capacity = new_capacity;
    return 0;
}

// Add a UE context to the array
