    if (!validate_imsi(imsi) || !validate_mme_identifier(mmeIdentifier)) {
        return -1; // Validation failed
    }

    if (array->size >= array->capacity) {
        if (resize_context_array(array) != 0) {
            return -2; // Memory allocation failure
        }
    }

    UEContext *context = malloc(sizeof(UEContext));
    if (!context) return -3;

    strncpy(context->imsi, imsi, sizeof(context->imsi));
    context->imsi[sizeof(context->imsi) - 1] = '\0';

    strncpy(context->mmeIdentifier, mmeIdentifier, sizeof(context->mmeIdentifier));
    context->mmeIdentifier[sizeof(context->mmeIdentifier) - 1] = '\0';

    context->nasMessageSequenceNumber = 0;
    context->nasMessages = NULL;
    context->nasMessageCount = 0;

    array->contexts[array->size++] = context;
    return 0; // Success
}

// Retrieve a UE context based on IMSI
UEContext* get_ue_context(ContextArray *array, const char* imsi) {
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->contexts[i]->imsi, imsi) == 0) {
            return array->contexts[i];
        }
    }
    return NULL; // Not found
}

