    char nasMessageId[64];
    snprintf(nasMessageId, sizeof(nasMessageId), "NAS-%u", context->nasMessageSequenceNumber + 1);

    NasMessage *new_message = realloc(context->nasMessages, (context->nasMessageCount + 1) * sizeof(NasMessage));
    if (!new_message) return -1;

    strncpy(new_message[context->nasMessageCount].nasMessageId, nasMessageId, sizeof(new_message[0].nasMessageId));
    new_message[context->nasMessageCount].nasMessageData[0] = '\0'; // Placeholder for real data
    context->nasMessages = new_message;
    context->nasMessageSequenceNumber++;
    context->nasMessageCount++;

    return 0; // Success
}

// Free the context array and all associated UE contexts
void free_context_array(ContextArray *array) {
