#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <openssl/rand.h>

typedef struct {
    int value;
    char stringKey[256];
    long *dynamicPointer;
} Record;

void initialize_memory(
    size_t num_records,
    long **offsets,
    int **keys,
    Record ***records,
    unsigned int seed,
    void (*callback)(Record*),
    pthread_mutex_t *mutex
) {
    if (num_records == 0 || offsets == NULL || keys == NULL || records == NULL || mutex == NULL) return;

    // Initialize RNG with a custom seed
    RAND_seed(&seed, sizeof(seed));

    // Allocate and initialize 'offsets' array
    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate offsets");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = (long)i;
    }

    // Allocate and initialize 'keys' array
    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        perror("Failed to allocate keys");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_records; ++i) {
        (*keys)[i] = (int)i;
    }

    // Allocate 'records' array
    *records = (Record **)malloc(num_records * sizeof(Record *));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(mutex);

    for (size_t i = 0; i < num_records; ++i) {
        // Allocate each record
        (*records)[i] = (Record *)malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*records);
            free(*keys);
            free(*offsets);
            pthread_mutex_unlock(mutex);
            perror("Failed to allocate record");
            exit(EXIT_FAILURE);
        }

        // Initialize each record
        unsigned char randBuffer[4];
        if (!RAND_bytes(randBuffer, sizeof(randBuffer))) {
            for (size_t j = 0; j <= i; ++j) free((*records)[j]);
            free(*records);
            free(*keys);
            free(*offsets);
            pthread_mutex_unlock(mutex);
            fprintf(stderr, "Random number generation failed\n");
            exit(EXIT_FAILURE);
        }
        (*records)[i]->value = (int)((randBuffer[0] << 24) | (randBuffer[1] << 16) | (randBuffer[2] << 8) | randBuffer[3]) % 100;

        snprintf((*records)[i]->stringKey, sizeof((*records)[i]->stringKey), "Record_%zu", i);

        // Allocate dynamic pointer in each record
        (*records)[i]->dynamicPointer = malloc(sizeof(long));
        if ((*records)[i]->dynamicPointer == NULL) {
            for (size_t j = 0; j <= i; ++j) free((*records)[j]);
            free(*records);
            free(*keys);
            free(*offsets);
            pthread_mutex_unlock(mutex);
            perror("Failed to allocate dynamic pointer");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(mutex);

    // Execute callback function on each record
    if (callback != NULL) {
        for (size_t i = 0; i < num_records; ++i) {
            callback((*records)[i]);
        }
    }
}

void free_memory(
    size_t num_records,
    long *offsets,
    int *keys,
    Record **records
) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i] != NULL) {
            if (records[i]->dynamicPointer != NULL) free(records[i]->dynamicPointer);
            free(records[i]);
        }
    }

    if (records != NULL) free(records);
}

void sample_callback(Record *record) {
    printf("Processing record with value: %d, stringKey: %s\n", record->value, record->stringKey);
}
