    FILE *file = fopen(file_name, "rb");
    if (!file) {
        log_message("Failed to open input file.");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    rewind(file);

    unsigned char *data = (unsigned char *)malloc(*size);
    if (fread(data, 1, *size, file) != *size) {
        free(data);
        log_message("Failed to read input file.");
        return NULL;
