    char temp_filename[] = "/tmp/outputXXXXXX";
    int fd = mkstemp(temp_filename);

    if (fd == -1) {
        log_message("Failed to create temporary file.");
        return 0;
    }

    if (write(fd, data, size) != size) {
        close(fd);
        unlink(temp_filename);
        log_message("Failed to write to temporary file.");
        return 0;
    }

    close(fd);
    if (rename(temp_filename, file_name)) {
        unlink(temp_filename);
        log_message("Failed to rename temporary file.");
        return 0;
    }

    return 1;
