#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <time.h>

#define DNS_CACHE_SIZE 100

typedef struct {
    char *hostname;
    u_char ip[16];
} dns_cache_entry;

dns_cache_entry dns_cache[DNS_CACHE_SIZE];
int cache_count = 0;

// Simple hash function for caching
unsigned int hash_hostname(const char *hostname) {
    unsigned long hash = 5381;
    int c;
    while ((c = *hostname++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % DNS_CACHE_SIZE;
}

// Check if hostname is in cache
int check_cache(const char *hostname, u_char *ip) {
    unsigned int index = hash_hostname(hostname);
    for (int i = 0; i < DNS_CACHE_SIZE; ++i) {
        int actual_index = (index + i) % DNS_CACHE_SIZE;
        if (dns_cache[actual_index].hostname && strcmp(dns_cache[actual_index].hostname, hostname) == 0) {
            memcpy(ip, dns_cache[actual_index].ip, sizeof(u_char) * 16);
            return 1; // Found in cache
        }
    }
    return 0;
}

// Add hostname to cache
void add_to_cache(const char *hostname, const u_char *ip) {
    if (cache_count < DNS_CACHE_SIZE) {
        unsigned int index = hash_hostname(hostname);
        for (int i = 0; i < DNS_CACHE_SIZE; ++i) {
            int actual_index = (index + i) % DNS_CACHE_SIZE;
            if (!dns_cache[actual_index].hostname) {
                dns_cache[actual_index].hostname = strdup(hostname);
                memcpy(dns_cache[actual_index].ip, ip, sizeof(u_char) * 16);
                cache_count++;
                break;
            }
        }
    }
}

// DNS resolution function
int resolve_dns(const char *hostname, u_char *ip) {
    if (check_cache(hostname, ip)) return 0; // Success from cache

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1; // Error
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), sizeof(u_char) * 16);
        add_to_cache(hostname, ip);
        break;
    }

    freeaddrinfo(res);

    if (p == NULL) return -2; // No address found

    return 0; // Success
}

// Function to process CSV records
void process_records(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open file");
        exit(EXIT_FAILURE);
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *token;
        char *line_copy = strdup(line);
        char *last_numeric = NULL;

        u_char ip_address[16] = {0};
        int dns_error = resolve_dns("example.com", ip_address); // Example hostname

        if (dns_error != 0) {
            fprintf(stderr, "DNS resolution failed with error code: %d\n", dns_error);
            free(line_copy);
            continue;
        }

        token = strtok(line_copy, ",");
        int num_fields = 0;
        double last_two_sum = 0.0;
        int last_numeric_count = 0;

        while (token) {
            if (last_numeric_count == 1) {
                last_numeric = token;
            }
            char *endptr;
            strtod(token, &endptr);
            if (*endptr == '\0' && strcmp(endptr, token) != 0) { // Check if token is numeric
                last_two_sum += atof(token);
                last_numeric_count++;
                if (last_numeric_count == 2) break; // Only consider the last two numeric fields
            }
            num_fields++;
            token = strtok(NULL, ",");
        }

        if (last_numeric && last_numeric_count == 2) {
            fprintf(stdout, "%s,%f\n", line, last_two_sum / 2.0);
        } else {
            fprintf(stderr, "Insufficient numeric fields in record: %s\n", line);
        }

        free(line_copy);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_records(argv[1]);

    for (int i = 0; i < DNS_CACHE_SIZE; ++i) {
        free(dns_cache[i].hostname);
    }

    return EXIT_SUCCESS;
}
