### C# Function: `FindElementByXPath`

```csharp
using System;
using System.Xml;
using System.Xml.XPath;

public class XPathErrors : Exception {}

public class NotFoundError : XPathErrors { public NotFoundError() : base("Element not found.") {} }
public class MultipleElementsFoundError : XPathErrors { public MultipleElementsFoundError() : base("Multiple elements found.") {} }

public static XmlNode FindElementByXPath(XmlDocument xmlDoc, string xpathQuery, string elementName)
{
    try
    {
        var nodes = xmlDoc.SelectNodes(xpathQuery);
        ValidateSingleMatch(nodes);

        foreach (XmlNode node in nodes)
        {
            if (node.Name == elementName)
                return node;
        }

        throw new NotFoundError();
    }
    catch (XPathException) 
    { 
        // Handle malformed XPath gracefully
        throw new XPathErrors("Invalid XPath query.");
    }
    catch (XmlException)
    {
        // Handle malformed XML gracefully
        throw new XPathErrors("Malformed XML document.");
    }

    static void ValidateSingleMatch(XmlNodeList nodes)
    {
        if (nodes.Count == 0) 
            throw new NotFoundError();
        if (nodes.Count > 1) 
            throw new MultipleElementsFoundError();
    }
}
```

### Rust Function: `CreateDirectoryWithEnvVar`

```rust
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use log::warn;

pub fn create_directory_with_env_var(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut directory_path = env::var("DIRECTORY_PATH").ok();

    if directory_path.is_none() {
        // Determine the new path for the directory
        let current_dir = env::current_dir()?;
        let new_directory_path = current_dir.join(dir_name);

        // Ensure parent directories exist or create them.
        fs::create_dir_all(&new_directory_path)?;

        // Set environment variable to the newly created directory
        directory_path = Some(new_directory_path.to_str().unwrap().to_string());
    } else {
        let existing_path = PathBuf::from(directory_path.unwrap());

        if !existing_path.exists() || !existing_path.is_dir() {
            warn!("Existing DIRECTORY_PATH is not a valid directory. Creating new one.");
            fs::create_dir_all(existing_path)?;
        }

        // Ensure parent directories exist or create them.
        fs::create_dir_all(&existing_path.join(dir_name))?;
    }

    if let Some(path) = directory_path {
        env::set_var("DIRECTORY_PATH", path);
    }

    Ok(())
}
```

