<?php

function manageUserAccount($request) {
    session_start();

    // Sample database connection setup
    $db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');

    function logAction($userId, $actionType) {
        $timestamp = date('Y-m-d H:i:s');
        file_put_contents('user_logs.txt', "User ID: $userId, Action: $actionType, Timestamp: $timestamp\n", FILE_APPEND);
    }

    function validateData($data) {
        return isset($data['name'], $data['email'], $data['password']) &&
               strlen($data['name']) >= 3 && strlen($data['name']) <= 50 &&
               filter_var($data['email'], FILTER_VALIDATE_EMAIL) &&
               strlen($data['password']) >= 8;
    }

    function saveToDatabase($db, $userData) {
        if (isset($userData['id'])) {
            // Update user
            $stmt = $db->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
            $result = $stmt->execute([$userData['name'], $userData['email'], password_hash($userData['password'], PASSWORD_BCRYPT), $userData['id']]);
        } else {
            // Create new user
            $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
            $result = $stmt->execute([$userData['name'], $userData['email'], password_hash($userData['password'], PASSWORD_BCRYPT)]);
        }

        return $result;
    }

    function deleteUserFromDatabase($db, $userId) {
        $stmt = $db->prepare("DELETE FROM users WHERE id = ?");
        return $stmt->execute([$userId]);
    }

    // Check request
    if (!validateData($_REQUEST)) {
        return json_encode(['message' => 'error', 'data' => 'Invalid input data.']);
    }

    // Prepare user data from request
    $userData = [
        'id' => isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null,
        'name' => $_REQUEST['name'],
        'email' => $_REQUEST['email'],
        'password' => $_REQUEST['password']
    ];

    // Determine action
    if (isset($userData['id'])) {
        $stmt = $db->prepare("SELECT id FROM users WHERE id = ?");
        $stmt->execute([$userData['id']]);

        if ($stmt->rowCount() > 0) {
            $_SESSION['user_data'] = $userData;
            saveToDatabase($db, $userData);

            // Clear session data post write
            unset($_SESSION['user_data']);

            logAction($userData['id'], 'update');
            return json_encode(['message' => 'success', 'data' => 'User updated successfully.']);
        } else {
            return json_encode(['message' => 'error', 'data' => 'User not found for update.']);
        }
    }

    if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
        if ($userData['id']) {
            $stmt = $db->prepare("SELECT id FROM users WHERE id = ?");
            $stmt->execute([$userData['id']]);

            if ($stmt->rowCount() > 0) {
                deleteUserFromDatabase($db, $userData['id']);
                logAction($userData['id'], 'delete');
                return json_encode(['message' => 'success', 'data' => 'User deleted successfully.']);
            } else {
                return json_encode(['message' => 'error', 'data' => 'User not found for deletion.']);
            }
        } else {
            return json_encode(['message' => 'error', 'data' => 'ID required to delete user.']);
        }
    }

    // If no id and sub_action is not 'delete', assume creation
    $_SESSION['user_data'] = $userData;
    saveToDatabase($db, $userData);

    unset($_SESSION['user_data']);

    logAction(null, 'create');
    return json_encode(['message' => 'success', 'data' => 'User created successfully.']);
}

// Example usage
echo manageUserAccount($_REQUEST);

?>
```

