const axios = require('axios');
const moment = require('moment');

async function processWeatherReports(reports) {
    const phenomenaRegexes = [
        { name: 'hurricane', regex: /\bhurricane\b/i },
        { name: 'tornado', regex: /\btornado\b/i },
        { name: 'blizzard', regex: /\bblizzard\b/i },
        { name: 'thunderstorm', regex: /\b(thunderstorm|severe thunderstorms)\b/i },
        // Add more phenomena as needed
    ];

    const frequencyReport = {};

    reports.forEach(report => {
        if (typeof report !== 'string') return;

        phenomenaRegexes.forEach(({ name, regex }) => {
            let match;
            while ((match = regex.exec(report)) !== null) {
                frequencyReport[name] = (frequencyReport[name] || 0) + 1;
            }
        });
    });

    await validateWithAPI(frequencyReport);

    return frequencyReport;
}

async function validateWithAPI(frequencyReport) {
    const apiKey = 'YOUR_API_KEY'; // Replace with your API key
    const apiEndpoint = 'https://api.weather.com/v3/wx/conditions/historical';

    for (const [phenomenon, count] of Object.entries(frequencyReport)) {
        try {
            const response = await axios.get(`${apiEndpoint}?q=${phenomenon}&apiKey=${apiKey}`);
            // Validate the phenomenon using the API data
            if (!response.data.phenomena.includes(phenomenon)) {
                frequencyReport[phenomenon] = 0; // Reset count if not validated
            }
        } catch (error) {
            console.error(`Error validating ${phenomenon}:`, error);
            await retryAPICall(() => axios.get(`${apiEndpoint}?q=${phenomenon}&apiKey=${apiKey}`));
        }
    }
}

async function retryAPICall(apiCall, retries = 3, delay = 1000) {
    try {
        return await apiCall();
    } catch (error) {
        if (retries > 1) {
            console.warn(`Retrying API call... Attempts left: ${retries - 1}`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryAPICall(apiCall, retries - 1, delay * 2);
        } else {
            throw error;
        }
    }
}

