import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FleetManager {

    private static final Logger logger = Logger.getLogger(FleetManager.class.getName());
    private final ExecutorService executorService;
    private Properties config;
    private volatile boolean running = true;

    public FleetManager() throws IOException {
        loadConfiguration();
        int serviceCount = Integer.parseInt(config.getProperty("service.count", "5"));
        this.executorService = Executors.newFixedThreadPool(serviceCount);
    }

    private void loadConfiguration() throws IOException {
        config = new Properties();
        try (FileInputStream input = new FileInputStream("config.properties")) {
            config.load(input);
        }
    }

    public void startServices() {
        int serviceCount = Integer.parseInt(config.getProperty("service.count", "5"));

        for (int i = 0; i < serviceCount; i++) {
            executorService.submit(() -> runServiceLifecycle(i));
        }
    }

    private void runServiceLifecycle(int serviceId) {
        int retryLimit = 3;
        int attempts = 0;

        while (attempts < retryLimit && running) {
            try {
                initializeService(serviceId);
                processService(serviceId);
                shutdownService(serviceId);
                break;
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error in service lifecycle: " + serviceId, e);
                attempts++;
                if (attempts >= retryLimit) {
                    logger.severe("Failed to start/stop service after retries: " + serviceId);
                }
            }
        }
    }

    private void initializeService(int serviceId) throws InterruptedException {
        int delay = Integer.parseInt(config.getProperty("delay.range", "1000"));
        Thread.sleep((long) (Math.random() * delay));
        logger.info("Initialized Service ID: " + serviceId);
    }

    private void processService(int serviceId) throws Exception {
        // Simulate processing and integrate with external systems
        logger.info("Processing Service ID: " + serviceId);
        Thread.sleep(500); // Simulating work
    }

    private void shutdownService(int serviceId) throws InterruptedException {
        int delay = Integer.parseInt(config.getProperty("shutdown.delay", "1000"));
        Thread.sleep((long) (Math.random() * delay));
        logger.info("Shut down Service ID: " + serviceId);
    }

    public void stopFleet() {
        running = false;
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        try {
            FleetManager fleetManager = new FleetManager();
            fleetManager.startServices();

            // Allow some time for services to run
            Thread.sleep(10000);

            fleetManager.stopFleet();
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Unexpected error in main execution", e);
        }
    }

    public void updateConfiguration(String key, String value) {
        config.setProperty(key, value);
        // Apply dynamic updates where necessary
    }

    // Unsafe code example: Ignoring resource limits or not handling errors gracefully.
    private void unsafeServiceHandling(int serviceId) throws InterruptedException {
        // No delay or retry logic; potential for infinite loop if initialization fails
        initializeService(serviceId); // Assuming this can throw unchecked exceptions

        logger.info("Unsafe processing of Service ID: " + serviceId);

        shutdownService(serviceId); // Not handling shutdown failure cases
    }
}
