    // Configuration for APIs
    $apis = [
        'api1' => ['url' => 'https://api1.example.com/weather', 'key' => 'API_KEY_1'],
        'api2' => ['url' => 'https://api2.example.com/weather', 'key' => 'API_KEY_2'],
        'api3' => ['url' => 'https://api3.example.com/weather', 'key' => 'API_KEY_3']
    ];

    // Historical metrics (mock data)
    $metrics = [
        'api1' => ['response_time' => 0.5, 'reliability' => 90],
        'api2' => ['response_time' => 0.7, 'reliability' => 85],
        'api3' => ['response_time' => 0.4, 'reliability' => 95]
    ];

    // Select the most reliable API
    usort($apis, function ($a, $b) use ($metrics) {
        return ($metrics[$a] <=> $metrics[$b]);
    });

    $cacheKey = md5($location);
    $cacheFile = "/tmp/cache_$cacheKey.json";
    $cacheTTL = 300; // Cache time-to-live in seconds

    if (file_exists($cacheFile) && (time() - filemtime($cacheFile)) < $cacheTTL) {
        return json_decode(file_get_contents($cacheFile), true)['status'];
    }

    foreach ($apis as $name => $api) {
        try {
            $response = fetchFromAPI($api['url'], ['key' => $api['key'], 'location' => $location]);

            if (isset($response['temperature'], $response['humidity'], $response['wind_speed'])) {
                updateDatabase($location, $response);
                cacheData($cacheFile, $response);
                return "Success: Data updated for $location";
            }
        } catch (\Exception $e) {
            // Log error and continue with the next API
            error_log("Error fetching from {$name}: " . $e->getMessage());
        }
    }

    return "Failure: Unable to fetch weather data for $location";
}

function fetchFromAPI($url, $params) {
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 10);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($params));

    $response = curl_exec($ch);

    if (curl_errno($ch)) {
        throw new \Exception('Network error: ' . curl_error($ch));
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($httpCode !== 200) {
        throw new \Exception("API request failed with status $httpCode");
    }

    $data = json_decode($response, true);

    if (json_last_error() !== JSON_ERROR_NONE) {
        throw new \Exception('Invalid response format');
    }

    return $data;
}

function updateDatabase($location, $weatherData) {
    // Database connection
    $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');

    // Prepare SQL statement
    $stmt = $pdo->prepare("REPLACE INTO weather (location, temperature, humidity, wind_speed, last_updated)
                           VALUES (:location, :temperature, :humidity, :wind_speed, NOW())");

    // Bind parameters and execute
    $stmt->execute([
        ':location' => $location,
        ':temperature' => $weatherData['temperature'],
        ':humidity' => $weatherData['humidity'],
        ':wind_speed' => $weatherData['wind_speed']
    ]);
}

function cacheData($file, $data) {
    file_put_contents($file, json_encode(['status' => 'success', 'data' => $data]));
}
