function generateRandomHashedString(length, characterSet, password, sourceFile) {
  // Function to generate a random string of specified length using character set
  const getRandomString = (length, charSet) => 
    Array.from({ length }, () => charSet[Math.floor(Math.random() * charSet.length)]).join('');

  // Hash the password using default hash function
  const hashedPassword = crypto.createHash('sha256').update(password).digest('hex');

  try {
    // Read file content synchronously
    const fileContent = readFileContentsSync(sourceFile);
    return { randomString: getRandomString(length, characterSet), hashedPassword, fileContent };
  } catch (error) {
    console.error(`Error reading the file: ${error.message}`);
    return { error: 'Failed to read file' };
  }
}

function readFileContentsSync(filePath) {
  // Validate file path and ensure it exists
  if (!filePath || typeof filePath !== 'string') throw new Error('Invalid file path');

  try {
    // Read the file synchronously
    const content = fs.readFileSync(filePath, { encoding: 'utf8' });
    return content;
  } catch (error) {
    console.error(`Error accessing the file: ${error.message}`);
    throw error; // Re-throw to handle in calling function
  }
}
