async function fetchCertificateData(certPath) {
  if (cache.certificates.has(certPath)) {
    return cache.certificates.get(certPath);
  }

  const certData = fs.readFileSync(certPath, 'utf8');
  cache.certificates.set(certPath, certData);

  // Simulate fetching metadata from an external source
  const [cert, key] = await Promise.all([
    fetchMetadata(certData),
    fetchPrivateKey(certPath.replace('.crt', '.key'))
  ]);

  return { cert, key };
}

async function fetchMetadata(cert) {
  if (cache.metadata.has(cert)) {
    return cache.metadata.get(cert);
  }

  // Simulate network latency
  await new Promise(resolve => setTimeout(resolve, 100));

  const metadata = {}; // Replace with actual metadata retrieval logic

  cache.metadata.set(cert, metadata);

  return metadata;
}

async function fetchPrivateKey(keyPath) {
  if (cache.certificates.has(keyPath)) {
    return cache.certificates.get(keyPath);
  }

  const keyData = fs.readFileSync(keyPath, 'utf8');
  cache.certificates.set(keyPath, keyData);

  return keyData;
}

function validateCertificateChain(certChains, caRoots) {
  // Implement validation logic here
  certChains.forEach(chain => {
    chain.forEach(cert => {
      const certObj = crypto.createCertificate(cert);
      if (!caRoots.some(root => root.verify(certObj))) {
        throw new Error(`Invalid certificate: ${cert}`);
      }
    });
  });
}

async function generateCombinedCertificate(certPaths, caRoots) {
  const certChainPromises = certPaths.map(fetchCertificateData);

  // Fetch all certificates and keys concurrently
  const certChains = await Promise.all(certChainPromises);

  validateCertificateChain(certChains, caRoots);

  return certChains.flatMap(({ cert, key }) => [cert, key]).join('\n');
}

function processOAuthRequest(oauthRequest) {
  const { certPaths, caRoots } = oauthRequest;

  // Simulate fetching CA roots
  const caRootsData = fetchCaRoots();

  return generateCombinedCertificate(certPaths, caRootsData)
    .then(combinedCert => combinedCert + '\n')
    .catch(error => {
      console.error('Error processing OAuth request:', error);
      throw error;
    });
}

function fetchCaRoots() {
  // Simulate fetching CA roots from a trusted source
  return [
    crypto.createCertificate(fs.readFileSync(path.join(__dirname, 'rootCA1.crt'), 'utf8')),
    crypto.createCertificate(fs.readFileSync(path.join(__dirname, 'rootCA2.crt'), 'utf8'))
  ];
}

