### C Component

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_IP_LENGTH 16

void handle_signal(int sig) {
    // Handle cleanup and resource management
    printf("Signal %d received. Cleaning up...\n", sig);
    exit(1);
}

u_char* dns_resolve_c(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char ip[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return false;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ip, sizeof(ip));
        printf("Resolved IP: %s\n", ip);

        // Return IP as u_char array
        u_char* result = (u_char*)malloc(INET6_ADDRSTRLEN);
        strncpy((char*)result, ip, INET6_ADDRSTRLEN - 1);
        freeaddrinfo(res);
        return result;
    }

    freeaddrinfo(res);
    return false;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);

    u_char* ip = dns_resolve_c(argv[1]);
    if (ip) {
        // Use the IP address
        free(ip);
    } else {
        fprintf(stderr, "Failed to resolve hostname.\n");
    }

    return 0;
}
```

### Notes

- The PHP component handles OAuth 2.0 authentication and DNS resolution using a simple cache.
- The C component resolves DNS queries and includes signal handling for graceful shutdowns.
- Error handling and rate limiting are not fully implemented in this example but should be considered in production code.
- Ensure secure storage of sensitive information like client secrets and access tokens.']

