class UserDAO {
    private $dbConnection;

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function updateUserPassword($userId, $newHashedPassword) {
        try {
            $this->dbConnection->beginTransaction();

            // Update the user's password in the database
            $stmt = $this->dbConnection->prepare("UPDATE users SET password = :password WHERE id = :id");
            if (!$stmt->execute([':password' => $newHashedPassword, ':id' => $userId])) {
                throw new PasswordUpdateException('Failed to update user password in database.');
