#include <stdlib.h>
#include <pthread.h>

typedef struct FSA {
    int states_count;
    // Other FSA-specific fields...
} FSA;

typedef struct StateNode {
    int *states;
    size_t num_states;
    struct StateNode *next;
} StateNode;

// Mutex for thread safety
static pthread_mutex_t state_list_mutex = PTHREAD_MUTEX_INITIALIZER;

StateNode* manage_state_list(int *state_array, int states_count, const FSA *fsa, int last_state_index, 
                             bool clear_list, double performance_threshold) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&state_list_mutex);

    StateNode *new_node = (StateNode *)malloc(sizeof(StateNode));
    if (!new_node) {
        pthread_mutex_unlock(&state_list_mutex);
        return NULL;  // Insufficient memory
    }

    if (clear_list) {
        new_node->states = (int *)calloc(states_count, sizeof(int));
    } else {
        new_node->states = (int *)malloc(states_count * sizeof(int));
    }

    if (!new_node->states) {
        free(new_node);
        pthread_mutex_unlock(&state_list_mutex);
        return NULL;  // Insufficient memory
    }

    for (int i = 0; i < states_count; ++i) {
        new_node->states[i] = state_array[i];
    }

    new_node->num_states = states_count;
    new_node->next = NULL;

    // Locate the last node in the existing list and update its 'next' pointer
    StateNode *current = (StateNode *)fsa;  // Assuming the FSA points to the head of the state list
    if (last_state_index >= 0) {
        while (last_state_index > 0 && current->next != NULL) {
            current = current->next;
            --last_state_index;
        }
        current->next = new_node;
    } else {
        // Assuming -1 means we're adding to the head
        new_node->next = (StateNode *)fsa;
        *fsa = *new_node;  // Update FSA pointer
    }

    // Consider performance threshold and additional logic if needed...

    pthread_mutex_unlock(&state_list_mutex);

    return new_node;
}
