['```cpp
#include <iostream>
#include <memory>
#include <vector>
#include <stdexcept>

class OctreeNode {
public:
    std::unique_ptr<OctreeNode> children[8];
    bool isLeaf;
};

using Octree = std::unique_ptr<OctreeNode>;

enum class ErrorCode {
    Success,
    InvalidParameters,
    MemoryAllocationFailed,
    DepthLimitExceeded
};

ErrorCode initializeOctree(double featureSize, size_t numLeafNodes, int maxDepth, Octree& octree) {
    if (featureSize <= 0 || numLeafNodes == 0 || maxDepth < 0) {
        return ErrorCode::InvalidParameters;
    }

    const int fullDepthCapacity = 1 << maxDepth; // Maximum number of leaf nodes at given depth
    if ((size_t)fullDepthCapacity < numLeafNodes) {
        return ErrorCode::DepthLimitExceeded;
    }

    octree = std::make_unique<OctreeNode>();
    OctreeNode* current = octree.get();

    size_t allocatedLeaves = 0;

    std::vector<std::unique_ptr<OctreeNode>> nodeStack;
    nodeStack.push_back(std::move(octree));

    while (!nodeStack.empty() && allocatedLeaves < numLeafNodes) {
        current = nodeStack.back().get();
        if (current->isLeaf || (allocatedLeaves + 8 > numLeafNodes)) {
            // All remaining nodes should be leaf nodes
            for (auto& child : current->children) {
                if (!child && allocatedLeaves < numLeafNodes) {
                    child = std::make_unique<OctreeNode>();
                    child->isLeaf = true;
                    ++allocatedLeaves;
                }
            }
            nodeStack.pop_back();
        } else {
            bool allChildrenAllocated = true;
            for (auto& child : current->children) {
                if (!child) {
                    child = std::make_unique<OctreeNode>();
                    allChildrenAllocated = false;
                }
            }
            if (allChildrenAllocated) {
                nodeStack.pop_back();
            } else {
                for (int i = 0; i < 8; ++i) {
                    if (!current->children[i]) break;
                    nodeStack.push_back(std::move(current->children[i]));
                }
            }
        }
    }

    return allocatedLeaves == numLeafNodes ? ErrorCode::Success : ErrorCode::MemoryAllocationFailed;
}

int main() {
    Octree octree;
    ErrorCode result = initializeOctree(1.0, 64, 6, octree);

    if (result == ErrorCode::Success) {
        std::cout << "Octree initialized successfully." << std::endl;
    } else {
        std::cerr << "Failed to initialize octree: " << static_cast<int>(result) << std::endl;
    }

    return 0;
}
```

This code defines a function `initializeOctree` that attempts to build an octree structure with specified constraints. It uses dynamic memory allocation through `std::unique_ptr` and includes checks for input validation, depth limits, and potential memory overflow situations. The function manages the tree's growth dynamically and supports incremental node addition up to the defined maximum depth and number of leaf nodes.']

