#define MAX_READINGS 5000
#define WINDOW_SIZE 1000

typedef struct {
    double *values;
    int count;
    time_t timestamp;
} SlidingWindow;

typedef struct {
    double signal_to_noise_ratio;
    int sensor_id;
} Result;

// Global variables for running average and standard deviation
double global_running_avg = 0.0;
double global_std_dev = 0.0;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Placeholder function to fetch calibration constants
void fetch_calibration_constants(double *calibration_constant) {
    // Simulate fetching delay or failure
    *calibration_constant = 1.0; // Example constant value
}

// Function to calculate standard deviation
double calculate_std_dev(double *values, int count, double mean) {
    double sum = 0.0;
    for (int i = 0; i < count; ++i) {
        sum += pow(values[i] - mean, 2);
    }
    return sqrt(sum / count);
}

// Function to update running average and standard deviation
void update_running_metrics(double new_value) {
    pthread_mutex_lock(&mutex);

    // Update running average
    global_running_avg = ((global_running_avg * (MAX_READINGS - 1)) + new_value) / MAX_READINGS;

    // Maintain a buffer of the last MAX_READINGS values for std deviation calculation
    static double value_buffer[MAX_READINGS] = {0};
    static int buffer_count = 0;

    if (buffer_count < MAX_READINGS) {
        value_buffer[buffer_count++] = new_value;
    } else {
        // Shift buffer to make room for the new value
        memmove(&value_buffer[0], &value_buffer[1], sizeof(double) * (MAX_READINGS - 1));
        value_buffer[MAX_READINGS - 1] = new_value;
    }

    // Calculate standard deviation
    global_std_dev = calculate_std_dev(value_buffer, buffer_count, global_running_avg);

    pthread_mutex_unlock(&mutex);
}

// Main function to process sensor data stream
Result process_sensor_data_stream(double *sensor_values, int sensor_ids[], size_t length) {
    SlidingWindow window = {malloc(WINDOW_SIZE * sizeof(double)), 0, time(NULL)};
    double calibration_constant;

    fetch_calibration_constants(&calibration_constant);

    double highest_snr = -INFINITY;
    int corresponding_sensor_id = -1;

    for (size_t i = 0; i < length; ++i) {
        double value = sensor_values[i];
        int id = sensor_ids[i];

        // Update sliding window
        if (window.count >= WINDOW_SIZE || difftime(time(NULL), window.timestamp) > 60) {
            memmove(&window.values[0], &window.values[1], sizeof(double) * (WINDOW_SIZE - 1));
            window.timestamp = time(NULL);
            window.count--;
        }

        window.values[window.count++] = value;

        // Calculate signal-to-noise ratio
        double mean = calculate_std_dev(window.values, window.count, global_running_avg);
        double snr = fabs(value - mean) / (mean + calibration_constant);

        if (snr > highest_snr) {
            highest_snr = snr;
            corresponding_sensor_id = id;
        }

        // Update running metrics
        update_running_metrics(value);
    }

    free(window.values);

    Result result = {highest_snr, corresponding_sensor_id};
    return result;
}

int main() {
    double sensor_values[] = {/* Populate with test data */};
    int sensor_ids[] = {/* Corresponding sensor IDs */};

    size_t length = sizeof(sensor_values) / sizeof(sensor_values[0]);

    Result result = process_sensor_data_stream(sensor_values, sensor_ids, length);

    printf("Highest SNR: %f\n", result.signal_to_noise_ratio);
    printf("Corresponding Sensor ID: %d\n", result.sensor_id);
    printf("Running Average: %f\n", global_running_avg);
    printf("Standard Deviation: %f\n", global_std_dev);

    return 0;
}
