#include <stdio.h>
#include <stdlib.h>
#include <string.h>

const char* checkStringSize(const char* str, int sizeLimit) {
    if (str == NULL) return "Input string is null.";

    int length = strlen(str);

    // Static buffer for success case; ensure it fits the maximum possible modified string.
    static char modifiedStr[256]; // Assumes that `sizeLimit + 1` will not exceed 255.

    if (length > sizeLimit) {
        const char* message = "String is too large.";
        return message;
    }

    // Append a forward slash and null-terminate
    snprintf(modifiedStr, sizeof(modifiedStr), "%s/", str);

    return modifiedStr;
}

// JavaScript Portion

function recursiveDomTraversal(node, selector, callback) {
    if (!node || typeof node !== 'object') return [];

    const matches = [];
    function traverse(currentNode) {
        if (currentNode.matches && currentNode.matches(selector)) {
            matches.push(currentNode);
            if (typeof callback === 'function') {
                callback(currentNode);
            }
        }

        // Traverse child nodes
        for (let i = 0; i < currentNode.childNodes.length; i++) {
            traverse(currentNode.childNodes[i]);
        }
    }

    traverse(node);
    return matches;
}

// Example usage of the JavaScript function:
/*
const elements = recursiveDomTraversal(document.body, '.target-class', element => {
    console.log('Visited:', element);
});
console.log(elements);
*/
```

### Explanation for C Function:

- The `checkStringSize` function first checks if the input string is null.
- It calculates the length of the input string and checks it against the size limit.
- If within limits, it appends a forward slash to a static buffer (ensuring no memory allocation failures).
- If exceeding the limit, it returns a pointer to a static message.

### Explanation for JavaScript Function:

- The `recursiveDomTraversal` function traverses nodes starting from the given node using recursion.
- It checks each node against the selector and applies the callback if provided.
- Matches are collected in an array which is returned at the end.']

