#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <tiffio.h>
#include <openssl/md5.h>

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char md5_hash[33];
    int error_code; // 0 for success, non-zero for specific errors
} ImageProcessingResult;

ImageProcessingResult processImageAndComputeHash(const char *image_path, const char *string_to_hash) {
    TIFF *tiff = TIFFOpen(image_path, "r");
    ImageProcessingResult result = {0};

    if (!tiff) {
        result.error_code = 1; // Error opening file
        return result;
    }

    uint32 width, height;
    TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &height);

    uint16 samples_per_pixel, bits_per_sample;
    if (!TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel)) {
        result.error_code = 2; // Error reading number of samples per pixel
        TIFFClose(tiff);
        return result;
    }

    int bit_depth_error = 0;
    for (int i = 0; i < samples_per_pixel && !bit_depth_error; ++i) {
        if (!TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE + i, &bits_per_sample)) {
            bit_depth_error = 1;
        }
        if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 &&
            bits_per_sample != 8 && bits_per_sample != 16) {
            result.error_code = 3; // Unsupported bit depth
            TIFFClose(tiff);
            return result;
        }
    }

    if (bit_depth_error) {
        result.error_code = 2; // Error reading bit depth
        TIFFClose(tiff);
        return result;
    }

    uint16 extra_samples;
    if (!TIFFGetFieldDefaulted(tiff, TIFFTAG_EXTRASAMPLES, &extra_samples)) {
        result.extra_samples = -1; // No extra samples information available
    } else {
        result.extra_samples = extra_samples;
    }

    result.bits_per_sample = bits_per_sample;
    result.samples_per_pixel = samples_per_pixel;

    if (string_to_hash) {
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)string_to_hash, strlen(string_to_hash), hash);
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            sprintf(result.md5_hash + i * 2, "%02x", hash[i]);
        }
    }

    TIFFClose(tiff);
    result.error_code = 0;
    return result;
}
