#define MAX_FILENAME_LENGTH 256
#define ALPHANUMERIC_CHARS "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123459"
#define RANDFILETYPELEN 3

typedef struct {
    char *filename;
    int length;
} Result;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int is_valid_filename(const char *filename) {
    while (*filename) {
        if (!isalnum(*filename) && !strchr("_ .", *filename)) {
            return 0;
        }
        filename++;
    }
    return 1;
}

char* generate_random_string(int length) {
    char *random_str = (char *)malloc(length + 1);
    if (!random_str) return NULL;

    for (int i = 0; i < length; i++) {
        random_str[i] = ALPHANUMERIC_CHARS[rand() % strlen(ALPHANUMERIC_CHARS)];
    }
    random_str[length] = '\0';
    return random_str;
}

char* fetch_file_type(void) {
    const char *file_types[] = {".txt", ".log", ".dat"};
    int index = rand() % (sizeof(file_types) / sizeof(file_types[0]));
    size_t len = strlen(file_types[index]);

    char *type = (char *)malloc(len + 1);
    if (!type) return NULL;

    strncpy(type, file_types[index], len + 1);
    return type;
}

Result generate_unique_filename(const char *base_filename) {
    Result result = {NULL, 0};

    pthread_mutex_lock(&lock);

    // Validate base filename
    if (!is_valid_filename(base_filename)) {
        result.filename = strdup("Error: Invalid characters in filename.");
        goto cleanup;
    }

    // Check and truncate length if necessary
    size_t len = strlen(base_filename);
    char *truncated = (char *)malloc(MAX_FILENAME_LENGTH + 1);
    if (!truncated) {
        result.filename = strdup("Error: Memory allocation failure.");
        goto cleanup;
    }

    strncpy(truncated, base_filename, MAX_FILENAME_LENGTH - RANDFILETYPELEN - 20); // Reserve space
    truncated[MAX_FILENAME_LENGTH - RANDFILETYPELEN - 20] = '\0';

    // Generate a timestamp string
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_info);

    // Random alphanumeric part
    int random_length = rand() % 10 + 1;
    char *random_part = generate_random_string(random_length);

    if (!random_part) {
        result.filename = strdup("Error: Memory allocation failure.");
        goto cleanup;
    }

    // File type retrieval (simulated latency)
    char *file_type = fetch_file_type();
    if (!file_type) {
        free(random_part);
        result.filename = strdup("Error: Unsupported file type or memory allocation failure.");
        goto cleanup;
    }

    size_t final_length = snprintf(NULL, 0,
                                   "%s_%s_%s%s", truncated, timestamp, random_part, file_type);

    // Allocate and construct the new filename
    char *new_filename = (char *)malloc(final_length + 1);
    if (!new_filename) {
        free(random_part);
        free(file_type);
        result.filename = strdup("Error: Memory allocation failure.");
        goto cleanup;
    }

    snprintf(new_filename, final_length + 1,
             "%s_%s_%s%s", truncated, timestamp, random_part, file_type);

    // Free intermediate allocations
    free(truncated);
    free(random_part);
    free(file_type);

    result.filename = new_filename;
    result.length = (int)final_length;

cleanup:
    pthread_mutex_unlock(&lock);
    return result;
}

// Usage example
