```c
// crypto_lib.c

#include "crypto_lib.h"
#include <stdlib.h>
#include <string.h>

CryptoConfig *initialize_crypto_library() {
    CryptoConfig *config = (CryptoConfig *)malloc(sizeof(CryptoConfig));
    if (!config) return NULL;

    // Load settings from environment variables or defaults
    load_config_from_env(config);

    return config;
}

void load_config_from_env(CryptoConfig *config) {
    if (!config) return;

    const char *aes_flag = getenv("ENABLE_AES");
    const char *camellia_flag = getenv("ENABLE_CAMELLIA");
    const char *md5_flag = getenv("ENABLE_MD5");
    const char *sha1_flag = getenv("ENABLE_SHA1");
    const char *rsa_flag = getenv("ENABLE_RSA");

    config->aes_enabled = (aes_flag && strcmp(aes_flag, "1") == 0) ? 1 : 0;
    config->camellia_enabled = (camellia_flag && strcmp(camellia_flag, "1") == 0) ? 1 : 0;
    config->md5_enabled = (md5_flag && strcmp(md5_flag, "1") == 0) ? 1 : 0;
    config->sha1_enabled = (sha1_flag && strcmp(sha1_flag, "1") == 0) ? 1 : 0;
    config->rsa_enabled = (rsa_flag && strcmp(rsa_flag, "1") == 0) ? 1 : 0;
}

void unload_crypto_library(CryptoConfig *config) {
    if (!config) return;
    free(config);
}

int encrypt_aes(const unsigned char *plaintext, size_t plaintext_len,
                const unsigned char *key, size_t key_len,
                unsigned char *ciphertext, size_t *ciphertext_len) {
    if (!plaintext || !key || !ciphertext || !ciphertext_len || key_len != 16 && key_len != 24 && key_len != 32)
        return -1;

    AES_KEY enc_key;
    if (AES_set_encrypt_key(key, key_len * 8, &enc_key) < 0)
        return -1;

    size_t num_blocks = (plaintext_len + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE;
    *ciphertext_len = num_blocks * AES_BLOCK_SIZE;

    AES_cbc_encrypt(plaintext, ciphertext, plaintext_len, &enc_key,
                    NULL, AES_ENCRYPT);

    // Padding the last block if necessary
    size_t padding_len = AES_BLOCK_SIZE - (plaintext_len % AES_BLOCK_SIZE);
    for (size_t i = 0; i < padding_len; ++i) {
        ciphertext[plaintext_len + i] = (unsigned char)padding_len;
    }

    return 0;
}

int decrypt_aes(const unsigned char *ciphertext, size_t ciphertext_len,
                const unsigned char *key, size_t key_len,
                unsigned char *plaintext, size_t *plaintext_len) {
    if (!ciphertext || !key || !plaintext || !plaintext_len || key_len != 16 && key_len != 24 && key_len != 32)
        return -1;

    AES_KEY dec_key;
    if (AES_set_decrypt_key(key, key_len * 8, &dec_key) < 0)
        return -1;

    size_t num_blocks = ciphertext_len / AES_BLOCK_SIZE;
    *plaintext_len = num_blocks * AES_BLOCK_SIZE;

    AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &dec_key,
                    NULL, AES_DECRYPT);

    // Remove padding
    unsigned char last_byte = plaintext[*plaintext_len - 1];
    if (last_byte > 0 && last_byte <= AES_BLOCK_SIZE) {
        *plaintext_len -= last_byte;
    }

    return 0;
}

// Implement similar functions for Camellia, MD5, SHA1, and RSA

