#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_LENGTH 32   // AES-256 requires a 32-byte key
#define IV_LENGTH   16  // AES block size is 16 bytes for CBC mode

typedef struct {
    EVP_CIPHER_CTX *ctx;
} CipherContext;

CipherContext* initialize_cipher(const char *password, unsigned int salt_length) {
    if (salt_length < 8) {  // Ensure minimum salt length
        return NULL;
    }

    CipherContext *cipher_context = malloc(sizeof(CipherContext));
    if (!cipher_context) {
        perror("Failed to allocate memory for cipher context");
        return NULL;
    }

    unsigned char key[KEY_LENGTH];
    unsigned char iv[IV_LENGTH];
    unsigned char salt[salt_length];

    // Generate a random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating random bytes for IV\n");
        free(cipher_context);
        return NULL;
    }

    // Generate a random salt
    if (!RAND_bytes(salt, salt_length)) {
        fprintf(stderr, "Error generating random bytes for salt\n");
        EVP_CIPHER_CTX_free(cipher_context->ctx);
        free(cipher_context);
        return NULL;
    }

    // Derive key using PBKDF2 and SHA-256
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), 
                          salt, salt_length,
                          100000,             // Iterations
                          EVP_sha256(),       // Hash function
                          KEY_LENGTH,         // Key length
                          key) != 1) {
        fprintf(stderr, "Error deriving key with PBKDF2\n");
        EVP_CIPHER_CTX_free(cipher_context->ctx);
        free(cipher_context);
        return NULL;
    }

    cipher_context->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_context->ctx) {
        perror("Failed to create cipher context");
        free(cipher_context);
        return NULL;
    }

    // Initialize the AES-256-CBC encryption context
    if (EVP_EncryptInit_ex(cipher_context->ctx, 
                          EVP_aes_256_cbc(), 
                          NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(cipher_context->ctx);
        free(cipher_context);
        return NULL;
    }

    return cipher_context;
}

void cleanup_cipher(CipherContext *cipher_context) {
    if (cipher_context && cipher_context->ctx) {
        EVP_CIPHER_CTX_free(cipher_context->ctx);
    }
    free(cipher_context);
}

int main() {
    const char *password = "secure_password";
    CipherContext *context = initialize_cipher(password, 16);

    if (!context) {
        fprintf(stderr, "Failed to initialize cipher\n");
        return EXIT_FAILURE;
    }

    // Use the context for encryption/decryption...

    cleanup_cipher(context);
    return EXIT_SUCCESS;
}
