public class NetworkDiagnosticsApp {

    private static final Logger logger = Logger.getLogger(NetworkDiagnosticsApp.class.getName());
    private static final int MAX_RETRIES = 5; // Configurable
    private static final long INITIAL_BACKOFF_MS = 1000L; // Initial backoff interval in milliseconds

    public static void main(String[] args) {
        List<NetworkInterface> networkInterfaces = getSortedNetworkInterfaces();

        for (NetworkInterface ni : networkInterfaces) {
            if (executeWithRetry(() -> isInterfaceAvailable(ni), MAX_RETRIES)) {
                logger.info("Executing diagnostics on interface: " + ni.getName());
                executeNetworkDiagnosticsCommand(ni);
                break; // Break after successful execution
            } else {
                logger.warning("Interface not available, checking next priority: " + ni.getName());
            }
        }
    }

    private static List<NetworkInterface> getSortedNetworkInterfaces() {
        List<NetworkInterface> interfaces = new ArrayList<>();

        for (NetworkInterface networkInterface : NetworkInterface.getNetworkInterfaces()) {
            if (!networkInterface.isLoopback() && isUp(networkInterface)) {
                interfaces.add(networkInterface);
            }
        }

        // Custom sorting logic based on criteria like speed, usage etc.
        Collections.sort(interfaces, (ni1, ni2) -> compareNetworkInterfaces(ni1, ni2));

        return interfaces;
    }

    private static boolean executeWithRetry(Runnable networkCheck, int maxRetries) {
        long backoff = INITIAL_BACKOFF_MS;

        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                networkCheck.run();
                return true;
            } catch (IOException e) {
                logger.log(Level.WARNING, "Attempt {0} failed: {1}", new Object[]{attempt + 1, e.getMessage()});

                if (attempt < maxRetries - 1) {
                    try {
                        Thread.sleep(backoff);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return false;
                    }
                    backoff *= 2; // Exponential backoff
                }
            }
        }

        return false;
    }

    private static boolean isInterfaceAvailable(NetworkInterface ni) throws IOException {
