['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <jansson.h>

#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3
#define CRITICAL 4

bool is_valid_directory(const char *path) {
    struct stat st;
    return (stat(path, &st) == 0 && S_ISDIR(st.st_mode));
}

bool validate_log_level(const char *log_level) {
    const char *levels[] = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"};
    for (int i = 0; i < 5; ++i) {
        if (strcmp(log_level, levels[i]) == 0) {
            return true;
        }
    }
    return false;
}

bool validate_logging_frequency(int frequency) {
    return frequency > 0;
}

bool validate_environment_directories(const char *env, json_t *config) {
    const char *dir_key = malloc(strlen(env) + strlen("logging_directory_") + 1);
    sprintf(dir_key, "logging_directory_%s", env);

    if (!json_is_string(config)) return false;

    const char *directory_path = json_string_value(json_object_get(config, dir_key));
    free(dir_key);

    return directory_path && is_valid_directory(directory_path);
}

bool process_json_config(const char *config_content) {
    json_error_t error;
    json_t *root = json_loads(config_content, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return false;
    }

    bool valid = true;

    // Check for required fields
    const char *log_level = json_string_value(json_object_get(root, "log_level"));
    const char *log_file_path = json_string_value(json_object_get(root, "log_file_path"));
    int logging_frequency = json_integer_value(json_object_get(root, "logging_frequency"));

    if (!log_level || !validate_log_level(log_level)) {
        valid = false;
    }

    if (!log_file_path || !is_valid_directory(log_file_path)) {
        valid = false;
    }

    if (json_is_null(logging_frequency) || !validate_logging_frequency(logging_frequency)) {
        valid = false;
    }

    const char *envs[] = {"development", "staging", "production"};
    for (int i = 0; i < 3 && valid; ++i) {
        if (!validate_environment_directories(envs[i], json_object_get(root, envs[i]))) {
            valid = false;
        }
    }

    json_decref(root);
    return valid;
}
```

