['```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class TripleDesDecryptor
{
    private readonly string _logFilePath = "encryption.log";
    private readonly ConcurrentDictionary<string, Tuple<byte[], byte[]>> _cache;
    private readonly int _cacheSizeLimit;

    public TripleDesDecryptor(int cacheSizeLimit)
    {
        if (cacheSizeLimit <= 0) throw new ArgumentException("Cache size limit must be greater than zero.", nameof(cacheSizeLimit));
        _cache = new ConcurrentDictionary<string, Tuple<byte[], byte[]>>();
        _cacheSizeLimit = cacheSizeLimit;
    }

    public async Task<string> DecryptMessageAsync(string encodedMessage, byte[] key, byte[] iv)
    {
        ValidateKeyAndIV(key, iv);
        var cacheKey = GenerateCacheKey(key, iv);

        if (_cache.TryGetValue(cacheKey, out var cachedValues))
        {
            return await PerformDecryptionAsync(encodedMessage, cachedValues.Item1, cachedValues.Item2);
        }

        _cache.TryAdd(cacheKey, Tuple.Create(key, iv));
        ManageCacheSize();

        return await PerformDecryptionAsync(encodedMessage, key, iv);
    }

    private void ValidateKeyAndIV(byte[] key, byte[] iv)
    {
        if (key.Length != 24) throw new ArgumentException("Encryption key must be exactly 24 bytes long.");
        if (iv.Length != 24) throw new ArgumentException("Initialization vector must be exactly 24 bytes long.");
    }

    private string GenerateCacheKey(byte[] key, byte[] iv)
    {
        using var sha256 = SHA256.Create();
        return Convert.ToBase64String(sha256.ComputeHash(key.Concat(iv).ToArray()));
    }

    private async Task<string> PerformDecryptionAsync(string encodedMessage, byte[] key, byte[] iv)
    {
        try
        {
            if (!IsBase64Encoded(encodedMessage))
                throw new FormatException("Invalid Base64 encoding.");

            var encryptedBytes = Convert.FromBase64String(encodedMessage);
            using var des = TripleDES.Create();
            des.Key = key;
            des.IV = iv;

            using var decryptor = des.CreateDecryptor(des.Key, des.IV);

            byte[] decryptedBytes;
            await Task.Run(() => 
                decryptedBytes = TransformData(decryptor, encryptedBytes));

            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            LogError(encodedMessage, ex.Message);
            throw new InvalidOperationException("Decryption failed.", ex);
        }
    }

    private byte[] TransformData(ICryptoTransform transform, byte[] data)
    {
        using var ms = new MemoryStream();
        using (var cryptoStream = new CryptoStream(ms, transform, CryptoStreamMode.Write))
        {
            cryptoStream.Write(data, 0, data.Length);
            cryptoStream.FlushFinalBlock();
        }
        return ms.ToArray();
    }

    private bool IsBase64Encoded(string s)
    {
        s = s.Trim();
        return (s.Length % 4 == 0) && 
               !s.Contains(Base64RegexInvalidChars) &&
               int.TryParse($"-1{Convert.ToBase64String(Encoding.UTF8.GetBytes(s))}-1", out _) && 
               Convert.FromBase64String(s) != null;
    }

    private void LogError(string message, string error)
    {
        var logEntry = $"{DateTime.Now}: Failed to decrypt message '{message}'. Error: {error}";
        File.AppendAllText(_logFilePath, logEntry + Environment.NewLine);
    }

    private void ManageCacheSize()
    {
        if (_cache.Count > _cacheSizeLimit)
        {
            foreach (var kvp in _cache)
            {
                _cache.TryRemove(kvp.Key, out _);
                break;
            }
        }
    }
}
```

This class includes mechanisms for caching key-IV pairs using a concurrent dictionary to handle multiple threads safely. It manages cache size through an eviction policy, logs errors with minimal information exposure, and uses asynchronous processing for decryption tasks to enhance scalability.']

