using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FilePathProcessor
{
    private readonly string _apiBaseUrl;
    private static readonly ConcurrentDictionary<string, FileMetadata> MetadataCache = new();

    public FilePathProcessor(string apiBaseUrl)
    {
        _apiBaseUrl = apiBaseUrl;
    }

    // Asynchronous version of the function.
    public async Task ProcessFilesAsync(IEnumerable<string> filePaths, bool logErrors = true)
    {
        var tasks = filePaths.Select(async path =>
        {
            try
            {
                if (IsValidPath(path))
                {
                    var metadata = await GetFileMetadataAsync(path);
                    string hash = await ComputeHashAsync(path);

                    // Use the computed hash and metadata as needed.
                }
            }
            catch (Exception ex)
            {
                if (logErrors) LogError(ex, path);
            }
        });

        await Task.WhenAll(tasks);
    }

    // Synchronous version of the function.
    public void ProcessFiles(IEnumerable<string> filePaths, bool logErrors = true)
    {
        foreach (var path in filePaths)
        {
            try
            {
                if (IsValidPath(path))
                {
                    var metadata = GetFileMetadata(path);
                    string hash = ComputeHash(path);

                    // Use the computed hash and metadata as needed.
                }
            }
            catch (Exception ex)
            {
                if (logErrors) LogError(ex, path);
            }
        }
    }

    private bool IsValidPath(string path)
    {
        return File.Exists(path);
    }

    private async Task<FileMetadata> GetFileMetadataAsync(string path)
    {
        if (MetadataCache.TryGetValue(path, out var metadata))
        {
            return metadata;
        }

        // Simulate API call.
        await Task.Delay(100);

        // Example response from the external API:
        metadata = new FileMetadata
        {
            Path = path,
            Size = new FileInfo(path).Length,
            LastModified = File.GetLastWriteTimeUtc(path)
        };

        MetadataCache[path] = metadata;
        return metadata;
    }

    private FileMetadata GetFileMetadata(string path)
    {
        if (MetadataCache.TryGetValue(path, out var metadata))
        {
            return metadata;
        }

        // Simulate API call.
        Task.Delay(100).Wait();

        // Example response from the external API:
        metadata = new FileMetadata
        {
            Path = path,
            Size = new FileInfo(path).Length,
            LastModified = File.GetLastWriteTimeUtc(path)
        };

        MetadataCache[path] = metadata;
        return metadata;
    }

    private async Task<string> ComputeHashAsync(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 8192, useAsync: true);

        var hashBytes = await sha256.ComputeHashAsync(stream);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private string ComputeHash(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 8192);

        var hashBytes = sha256.ComputeHash(stream);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private void LogError(Exception ex, string filePath)
    {
        Console.WriteLine($"Error processing file '{filePath}': {ex.Message}");
    }
}

public class FileMetadata
{
    public string Path { get; set; }
    public long Size { get; set; }
    public DateTime LastModified { get; set; }
}
