```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesDecryptor
{
    private const int DefaultIvSize = 16; // Default IV size in bytes (AES block size)
    private const int SaltSize = 16; // Size of the salt for PBKDF2

    public static byte[] DecryptAesCbc(
        string password,
        byte[] ciphertext,
        byte[] iv = null,
        bool usePkcs7Padding = true,
        int iterations = 10000, // Iterations for PBKDF2
        int keySize = 32, // Key size in bytes (256 bits)
        Action<string> logError = null) // Logging function
    {
        if (password == null || ciphertext == null)
            throw new ArgumentNullException("Password and ciphertext cannot be null.");

        try
        {
            using var aesAlg = Aes.Create();
            aesAlg.Mode = CipherMode.CBC;

            // Derive key from password using PBKDF2
            byte[] salt = ExtractSalt(ciphertext);
            byte[] key = DeriveKey(password, salt, iterations, keySize);

            // Set IV size and extract/initialize IV
            int ivSize = iv?.Length ?? DefaultIvSize;
            if (iv != null && iv.Length != ivSize)
                throw new ArgumentException("IV length does not match the expected size.");
            aesAlg.IV = iv ?? ExtractIv(ciphertext, ivSize);

            // Set key and remove salt
            aesAlg.Key = key;

            // Decrypt the ciphertext
            using var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            using var msDecrypt = new MemoryStream();
            using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
            {
                csDecrypt.Write(ciphertext, SaltSize + ivSize, ciphertext.Length - SaltSize - ivSize);
                csDecrypt.FlushFinalBlock();

                byte[] decryptedBytes = msDecrypt.ToArray();

                if (usePkcs7Padding)
                {
                    // Remove PKCS#7 padding
                    int paddingLength = decryptedBytes[decryptedBytes.Length - 1];
                    if (paddingLength < 1 || paddingLength > aesAlg.BlockSize / 8)
                        throw new PaddingException("Invalid PKCS#7 padding.");

                    for (int i = decryptedBytes.Length - paddingLength; i < decryptedBytes.Length - 1; i++)
                    {
                        if (decryptedBytes[i] != paddingLength)
                            throw new PaddingException("Invalid PKCS#7 padding.");
                    }

                    return decryptedBytes[..^paddingLength];
                }
                else
                {
                    return decryptedBytes;
                }
            }
        }
        catch (Exception ex) when (!(ex is CryptographicException || ex is ArgumentException))
        {
            logError?.Invoke($"Decryption failed: {ex.Message}");
            throw new InvalidOperationException("Failed to decrypt data.", ex);
        }
    }

    private static byte[] DeriveKey(string password, byte[] salt, int iterations, int keySize)
    {
        using var deriveBytes = new Rfc2898DeriveBytes(password, salt, iterations);
        return deriveBytes.GetBytes(keySize);
    }

    private static byte[] ExtractSalt(byte[] ciphertext)
    {
        if (ciphertext.Length < SaltSize)
            throw new ArgumentException("Ciphertext is too short to contain a valid salt.");

        byte[] salt = new byte[SaltSize];
        Buffer.BlockCopy(ciphertext, 0, salt, 0, SaltSize);
        return salt;
    }

    private static byte[] ExtractIv(byte[] ciphertext, int ivSize)
    {
        if (ciphertext.Length < SaltSize + ivSize)
            throw new ArgumentException("Ciphertext is too short to contain a valid IV.");

        byte[] iv = new byte[ivSize];
        Buffer.BlockCopy(ciphertext, SaltSize, iv, 0, ivSize);
        return iv;
    }
}
```

### Key Points:
- **Key Derivation**: Uses PBKDF2 for deriving the key from a password.
- **IV Handling**: Extracts IV and salt from the ciphertext or defaults to AES's recommended size if not provided.
- **Padding**: Supports PKCS7 padding, which can be enabled/disabled as needed.
- **Error Handling**: Logs errors using an external logging service (if provided) and throws informative exceptions.
- **Thread Safety**: Ensures thread safety by avoiding shared state. Each call operates independently on its input data.

This function is designed to handle decryption securely and efficiently while providing flexibility for different use cases.']

