        offsets[i] = static_cast<long>(i);
        keys[i] = static_cast<int>(i);
    }
}

void initializeRecords(std::vector<Record>& records, int minValue, int maxValue, unsigned int seed, std::function<void(Record&)> callback) {
    std::lock_guard<std::mutex> lock(allocationMutex);

    if (records.empty()) return;

    std::random_device rd;
    std::mt19937 gen(seed ? seed : rd());
    std::uniform_int_distribution<> dis(minValue, maxValue);

    for (auto& record : records) {
        record.value = dis(gen);
        snprintf(record.key, sizeof(record.key), "Key_%ld", static_cast<long>(&record - &records[0]));
        try {
            record.dynamicValue = new long(dis(gen));
        } catch (const std::bad_alloc&) {
            throw std::runtime_error("Memory allocation failed for dynamicValue");
        }

        if (callback) {
            callback(record);
        }
    }
}

void deallocateRecords(std::vector<Record>& records) {
    std::lock_guard<std::mutex> lock(allocationMutex);
    records.clear();
}

int main() {
    try {
        size_t recordSize = 100;
        int minValue = 1, maxValue = 1000;
        unsigned int seed = 42;

        std::vector<long> offsets;
        std::vector<int> keys;
        std::vector<Record> records(recordSize);

        initializeArrays(offsets, keys, recordSize);
        initializeRecords(records, minValue, maxValue, seed, [](Record& r) {
            // Custom processing logic
            std::cout << "Processing Record: Value=" << r.value << ", Key=" << r.key << std::endl;
        });

        deallocateRecords(records);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
