private:
    boost::asio::io_context ioContext;
    std::unique_ptr<InterfaceTable> interfaceTable;

public:
    explicit GraphServiceClient(std::unique_ptr<InterfaceTable> table)
        : interfaceTable(std::move(table)) {}

    void addVertex(const std::string& vertexId) {
        if (!interfaceTable->queryMetadata(vertexId)) {
            logError("Invalid metadata for vertex: " + vertexId);
            return;
        }
        // Simulate API call to add a vertex
        logOperation("Added vertex: " + vertexId);
    }

    void addEdge(const std::string& fromVertex, const std::string& toVertex) {
        if (!interfaceTable->queryMetadata(fromVertex) || !interfaceTable->queryMetadata(toVertex)) {
            logError("Invalid metadata for edge creation");
            return;
        }
        // Simulate API call to add an edge
        logOperation("Added edge: " + fromVertex + " -> " + toVertex);
    }

private:
