        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[INFO] " << message << std::endl;
    }

    void logError(const std::string& message) const {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cerr << "[ERROR] " << message << std::endl;
    }

    mutable std::mutex logMutex;
};

void handleGraphOperations(GraphServiceClient& client, const std::vector<std::pair<std::string, std::string>>& operations) {
    for (const auto& [operationType, data] : operations) {
        try {
            if (operationType == "vertex") {
                client.addVertex(data);
            } else if (operationType == "edge") {
                std::vector<std::string> vertices = split(data, '->');
                if (vertices.size() != 2) continue;
                client.addEdge(vertices[0], vertices[1]);
            }
        } catch (const std::exception& e) {
            client.logError("Operation failed: " + std::string(e.what()));
        }
    }
}

std::vector<std::string> split(const std::string& str, char delimiter) {
    std::vector<std::string> tokens;
    size_t start = 0, end = 0;
    while ((end = str.find(delimiter, start)) != std::string::npos) {
        if (end > start) {
            tokens.push_back(str.substr(start, end - start));
        }
        start = end + 1;
    }
    if (start < str.size()) {
        tokens.push_back(str.substr(start));
    }
    return tokens;
}

int main() {
    MockInterfaceTable mockTable;
    GraphServiceClient client(std::make_unique<MockInterfaceTable>(mockTable));

    std::vector<std::pair<std::string, std::string>> operations = {
        {"vertex", "1"},
        {"vertex", "2"},
        {"edge", "1->2"}
    };

    handleGraphOperations(client, operations);

    return 0;
}
