use tokio::runtime::Runtime;
use std::ffi::CString;
use std::os::raw::c_char;

extern "C" {
    fn log_message(format: *const c_char, ...) -> i32;
}

fn main() {
    let rt = Runtime::new().unwrap();

    rt.block_on(async {
        let args: Vec<String> = std::env::args().collect();

        if args.len() < 2 {
            eprintln!("Usage: {} <function_name>", args[0]);
            return;
        }

        match args[1].as_str() {
            "log" => log_message_async("Hello from Rust!".to_string()).await,
            _ => eprintln!("Unknown function"),
        }
    });
}

async fn log_message_async(message: String) {
    let c_message = CString::new(message).unwrap();

    unsafe {
        let args: Vec<c_char> = vec![c_message.as_ptr() as c_char];
        std::thread::spawn(move || {
            libc::va_list(args.len());
            log_message(c_message.as_ptr(), &args);
        });
    }
}
```

