#include <stdio.h>
#include <stdarg.h>

int log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Asynchronous logging simulation
    printf("Async Log: ");
    vprintf(format, args);
    printf("\n");

    va_end(args);
    return 0;
}
