} record;

// Forward declarations
void resizeArray(void **array, size_t *size, size_t element_size, size_t new_capacity);
int findMax(const int *arr, size_t size);

void processAndAnalyzeRecords(size_t initial_offset_count, size_t initial_key_count,
                              void (*callback)(record*), unsigned long seed) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize arrays for 'long' offsets and 'int' keys
    size_t offset_size = initial_offset_count;
    size_t key_size = initial_key_count;
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < offset_size; ++i) offsets[i] = i;
    for (size_t i = 0; i < key_size; ++i) keys[i] = i;

    // Array of records
    size_t record_count = initial_offset_count;
    record *records = malloc(record_count * sizeof(record));

    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator with the provided seed
    external_library_seed(seed);

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = external_library_secure_random(1, 100);  // Assume this function is thread-safe and returns a value in [1, 100]
        sprintf(records[i].key, "Key_%zu", i);
        pthread_mutex_lock(&lock);
        records[i].ptr = malloc(sizeof(long));
        if (!records[i].ptr) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        *records[i].ptr = offsets[i];
        pthread_mutex_unlock(&lock);

        // Invoke the callback if provided
        if (callback) callback(&records[i]);
    }

    // Handle input of integers from standard input
    int *integers = NULL;
    size_t integer_count = 0;
    size_t capacity = 10;

    while (!feof(stdin)) {
        if (integer_count == capacity) {
            resizeArray((void**)&integers, &capacity, sizeof(int), capacity * 2);
        }

        int value;
        if (fscanf(stdin, "%d", &value) == 1) {
            integers = realloc(integers, (integer_count + 1) * sizeof(int));
            if (!integers) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            integers[integer_count++] = value;
        } else {
            break; // Break on non-integer input
        }
    }

    int max_value = (integer_count > 0) ? findMax(integers, integer_count) : INT_MIN;

    printf("Maximum integer: %d\n", max_value);

    // Free allocated memory
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].ptr);
    }
    free(records);
    free(offsets);
    free(keys);
    free(integers);
}

void resizeArray(void **array, size_t *size, size_t element_size, size_t new_capacity) {
    if (!(*array)) {
        *array = malloc(new_capacity * element_size);
        if (!*array) exit(EXIT_FAILURE);
    } else {
        *array = realloc(*array, new_capacity * element_size);
        if (!*array) exit(EXIT_FAILURE);
    }
    *size = new_capacity;
}

int findMax(const int *arr, size_t size) {
    if (size == 0) return INT_MIN;

    int max_value = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max_value) {
            max_value = arr[i];
        }
    }
    return max_value;
}
