#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} record_t;

#define MAX_KEYS 1000

// Hash map to track used keys
typedef struct {
    int* keys;
    pthread_mutex_t lock;
} hashmap_t;

hashmap_t* create_hashmap(size_t size) {
    hashmap_t* hm = (hashmap_t*)malloc(sizeof(hashmap_t));
    if (!hm) return NULL;
    hm->keys = (int*)calloc(size, sizeof(int));
    if (!hm->keys) {
        free(hm);
        return NULL;
    }
    pthread_mutex_init(&hm->lock, NULL);
    return hm;
}

void destroy_hashmap(hashmap_t* hm) {
    if (hm) {
        free(hm->keys);
        pthread_mutex_destroy(&hm->lock);
        free(hm);
    }
}

int is_key_used(hashmap_t* hm, int key) {
    pthread_mutex_lock(&hm->lock);
    int used = (key >= 0 && key < MAX_KEYS) ? hm->keys[key] : 0;
    pthread_mutex_unlock(&hm->lock);
    return used;
}

void mark_key_as_used(hashmap_t* hm, int key) {
    if (key >= 0 && key < MAX_KEYS) {
        pthread_mutex_lock(&hm->lock);
        hm->keys[key] = 1;
        pthread_mutex_unlock(&hm->lock);
    }
}

void initialize_records(record_t** records, size_t size, int value_min, int value_max, hashmap_t* hm) {
    if (!records || !hm) return;

    for (size_t i = 0; i < size; ++i) {
        long offset;
        int key;
        do {
            offset = rand();
            key = rand() % MAX_KEYS;
        } while (is_key_used(hm, key));

        mark_key_as_used(hm, key);

        (*records)[i].offset = offset;
        (*records)[i].key = key;
        (*records)[i].value = ((double)rand() / RAND_MAX) * (value_max - value_min) + value_min;
    }
}

record_t* allocate_and_initialize_records(size_t size, int value_min, int value_max) {
    record_t* records = (record_t*)malloc(size * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    hashmap_t* hm = create_hashmap(MAX_KEYS);
    if (!hm) {
        free(records);
        fprintf(stderr, "Hash map initialization failed\n");
        exit(EXIT_FAILURE);
    }

    initialize_records(&records, size, value_min, value_max, hm);

    destroy_hashmap(hm);
    return records;
}

int main() {
    srand((unsigned int)time(NULL));
    size_t num_records = 100;
    int value_min = 0.0;
    int value_max = 10.0;

    record_t* records = allocate_and_initialize_records(num_records, value_min, value_max);

    // Example usage
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu: Offset = %ld, Key = %d, Value = %.2f\n", i, records[i].offset, records[i].key, records[i].value);
    }

    free(records);
    return 0;
}
```

This code provides a thread-safe function to initialize an array of `record` structures with unique keys and random values. It uses a hash map to track used keys and ensures memory allocation is handled gracefully. The function is designed to be integrated into larger frameworks, considering performance, resource management, and scalability.']

