#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_RETRY_ATTEMPTS 3

typedef struct {
    char imsi[16];
    int mmeIdentifier;
    int nasMessageSequenceNumber;
} UEContext;

typedef struct {
    size_t capacity;
    size_t count;
    UEContext *contexts;
    pthread_mutex_t lock;
} ContextManager;

// Simulated external messaging service
int sendMessage(const char *messageId, const char *messageData);

// Logging function
void logInfo(const char *info) {
    printf("[INFO] %s\n", info);
}

// Initialize the context manager
ContextManager* initContextManager() {
    ContextManager *manager = malloc(sizeof(ContextManager));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->contexts = malloc(manager->capacity * sizeof(UEContext));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new UE context
int addUEContext(ContextManager *manager, const char *imsi, int mmeIdentifier) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        UEContext *newContexts = realloc(manager->contexts, newCapacity * sizeof(UEContext));
        if (!newContexts) {
            pthread_mutex_unlock(&manager->lock);
            return 0; // Memory allocation failed
        }
        manager->contexts = newContexts;
        manager->capacity = newCapacity;
    }

    strncpy(manager->contexts[manager->count].imsi, imsi, sizeof(manager->contexts[manager->count].imsi));
    manager->contexts[manager->count].mmeIdentifier = mmeIdentifier;
    manager->contexts[manager->count].nasMessageSequenceNumber = rand() % 1000; // Random sequence number
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 1;
}

// Update an existing UE context
int updateUEContext(ContextManager *manager, const char *imsi, int mmeIdentifier) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i].imsi, imsi) == 0) {
            manager->contexts[i].mmeIdentifier = mmeIdentifier;
            logInfo("UEContext updated.");
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Context not found
}

// Remove a UE context
int removeUEContext(ContextManager *manager, const char *imsi) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i].imsi, imsi) == 0) {
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->count - i - 1) * sizeof(UEContext));
            manager->count--;
            logInfo("UEContext removed.");
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Context not found
}

// Simulate NAS message transmission with retry and backoff strategy
int transmitNASMessage(ContextManager *manager, const char *imsi) {
    int attempt = 0;
    while (attempt < MAX_RETRY_ATTEMPTS) {
        pthread_mutex_lock(&manager->lock);

        for (size_t i = 0; i < manager->count; ++i) {
            if (strcmp(manager->contexts[i].imsi, imsi) == 0) {
                char messageId[16];
                snprintf(messageId, sizeof(messageId), "MSG-%d", rand() % 10000);
                char nasMessageData[] = "Sample NAS Data";

                int success = sendMessage(messageId, nasMessageData);
                if (success) {
                    logInfo("NAS message transmitted successfully.");
                    pthread_mutex_unlock(&manager->lock);
                    return 1;
                } else {
                    logInfo("Failed to transmit NAS message. Retrying...");
                    attempt++;
                    sleep(1 << attempt); // Exponential backoff
                }
            }
        }

        pthread_mutex_unlock(&manager->lock);
    }

    logInfo("NAS message transmission failed after retries.");
    return 0;
}

// Clean up context manager resources
void freeContextManager(ContextManager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    srand(time(NULL));
    ContextManager *manager = initContextManager();

    addUEContext(manager, "123456789012345", 1);
    updateUEContext(manager, "123456789012345", 2);
    transmitNASMessage(manager, "123456789012345");
    removeUEContext(manager, "123456789012345");

    freeContextManager(manager);

    return 0;
}
```']

