#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEY_SIZE 256

typedef struct {
    int value;
    char key[MAX_KEY_SIZE];
    long *dynamicData;
} Record;

// Function prototypes for callback
typedef void (*RecordCallback)(Record*);

void initializeRecords(int offsetSize, int keysSize, int recordSize, uint64_t seed,
                       RecordCallback callback) {

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Step 1: Initialize the 'offset' and 'key' arrays with sequential numbers
    long *offsets = (long*)malloc(offsetSize * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate offsets");
        return;
    }
    int *keys = (int*)malloc(keysSize * sizeof(int));
    if (!keys) {
        perror("Failed to allocate keys");
        free(offsets);
        return;
    }

    for (int i = 0; i < offsetSize; ++i) {
        offsets[i] = i;
    }

    for (int i = 0; i < keysSize; ++i) {
        keys[i] = i;
    }

    // Step 2: Secure random number generator initialization
    pthread_mutex_lock(&lock);
    srand48(seed);

    Record *records = (Record*)malloc(recordSize * sizeof(Record));
    if (!records) {
        perror("Failed to allocate records");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Step 3: Initialize record array
    for (int i = 0; i < recordSize; ++i) {
        records[i].value = lrand48() % 100 + 1; // Random number between 1 and 100

        snprintf(records[i].key, MAX_KEY_SIZE, "Key_%d", keys[i % keysSize]);

        // Allocate dynamic long for each record
        records[i].dynamicData = (long*)malloc(sizeof(long));
        if (!records[i].dynamicData) {
            perror("Failed to allocate dynamic data");
            free(records[i].dynamicData);
            continue;
        }
        *records[i].dynamicData = lrand48();
    }

    // Step 4: Process each record with a callback, if provided
    if (callback != NULL) {
        for (int i = 0; i < recordSize; ++i) {
            callback(&records[i]);
        }
    }

    pthread_mutex_unlock(&lock);

    // Free allocated memory in case of early exit or when no longer needed.
    free(offsets);
    free(keys);

    for (int i = 0; i < recordSize; ++i) {
        if (records[i].dynamicData != NULL) {
            free(records[i].dynamicData);
        }
    }

    free(records);
}
