#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_KEY_LENGTH 256
#define RANDOM_RANGE 1000

typedef struct {
    int value;
    char key[MAX_KEY_LENGTH];
    long *dynamicLongPtr;
} Record;

void secureRandomInt(int *result, int lower, int upper) {
    unsigned int range = (upper - lower + 1);
    unsigned int buffer;
    RAND_bytes((unsigned char*)&buffer, sizeof(buffer));
    *result = (int)(lower + (buffer % range));
}

void findMaxHelper(const int* array, size_t size, int *maxValue) {
    if (!array || size == 0) return;
    *maxValue = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > *maxValue) {
            *maxValue = array[i];
        }
    }
}

void processRecordsAndFindMax(size_t offsetSize, size_t keySize, size_t recordSize, void (*callback)(Record*)) {
    pthread_mutex_t lock;
    int maxInt = 0;
    long *offsets = malloc(offsetSize * sizeof(long));
    int *keys = malloc(keySize * sizeof(int));
    Record *records = malloc(recordSize * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < offsetSize; ++i) offsets[i] = i;

    for (size_t i = 0; i < keySize; ++i) keys[i] = i;

    for (size_t i = 0; i < recordSize; ++i) {
        int randomValue;
        secureRandomInt(&randomValue, 1, RANDOM_RANGE);

        records[i].value = randomValue;
        snprintf(records[i].key, MAX_KEY_LENGTH, "Key_%zu", i);

        records[i].dynamicLongPtr = malloc(sizeof(long));
        if (!records[i].dynamicLongPtr) {
            fprintf(stderr, "Memory allocation failed for dynamic long\n");
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j].dynamicLongPtr);
            }
            free(records);
            pthread_mutex_destroy(&lock);
            return;
        }

        pthread_mutex_lock(&lock);
        if (callback) callback(&records[i]);
        pthread_mutex_unlock(&lock);
    }

    int *inputArray = NULL;
    size_t inputSize = 0, capacity = 10;
    inputArray = realloc(inputArray, capacity * sizeof(int));

    printf("Enter integers (-1 to stop):\n");
    while (1) {
        int num;
        scanf("%d", &num);
        if (num == -1) break;

        if (inputSize >= capacity) {
            capacity *= 2;
            inputArray = realloc(inputArray, capacity * sizeof(int));
            if (!inputArray) {
                fprintf(stderr, "Memory allocation failed during resizing\n");
                free(offsets);
                free(keys);
                for (size_t i = 0; i < recordSize; ++i) {
                    free(records[i].dynamicLongPtr);
                }
                free(records);
                pthread_mutex_destroy(&lock);
                return;
            }
        }

        inputArray[inputSize++] = num;
    }

    findMaxHelper(inputArray, inputSize, &maxInt);
    printf("The largest integer is: %d\n", maxInt);

    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i].dynamicLongPtr);
    }
    free(offsets);
    free(keys);
    free(inputArray);
    free(records);
    pthread_mutex_destroy(&lock);
}

void sampleCallback(Record *record) {
    // Example callback function for custom processing
    printf("Processed Record with value: %d and key: %s\n", record->value, record->key);
}
```

