use reqwest::Client;
use std::error::Error;

// Define a RequestBuilder struct for building requests
pub struct RequestBuilder {
    client: Client,
    url: String,
}

impl RequestBuilder {
    // Create a new instance of the RequestBuilder
    pub fn new(url: &str) -> Self {
        RequestBuilder {
            client: Client::new(),
            url: url.to_string(),
        }
    }

    // Allow optional disabling of SSL/TLS certificate validation
    pub async fn build_request(self, verify_ssl: bool) -> Result<(), Box<dyn Error>> {
        let client = if !verify_ssl {
            self.client.dangerous().disable_ssl_verification()
        } else {
            self.client
        };

        let response = client.get(&self.url).send().await?;
        println!("Response status: {}", response.status());

        Ok(())
    }
}

// Entry point for the Rust HTTP client example
#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let builder = RequestBuilder::new("https://httpbin.org/get");

    // Example usage of disabling SSL verification (for testing purposes only)
    builder.build_request(false).await?;

    Ok(())
}
```

