```java
import java.util.*;

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    public int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]);
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);

        if (rootP == rootQ) return;

        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
        } else if (rank[rootP] < rank[rootQ]) {
            parent[rootP] = rootQ;
        } else {
            parent[rootQ] = rootP;
            rank[rootP]++;
        }
    }

    public boolean connected(int p, int q) {
        return find(p) == find(q);
    }
}

public class DisjointPairsCounter {
    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);

        int disjointCount = 0;

        for (int i = 0; i < array.length; i++) {
            long startTime = System.nanoTime();

            for (int j = i + 1; j < array.length; j++) {
                if (!uf.connected(i, j)) {
                    uf.union(i, j);
                    disjointCount++;
                }
            }

            long endTime = System.nanoTime();
            System.out.println("Time taken to compute pairs for element " + i + ": " + (endTime - startTime) + " ns");
        }

        return disjointCount;
    }

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};
        System.out.println("Number of disjoint pairs: " + countDisjointPairs(array));
    }
}
```

