['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define entry structure
typedef struct {
    time_t timestamp;
    int status_code;
    int key_reference;
} Entry;

// Memory management module
typedef struct {
    long *offsets;
    int *keys;
    Entry **entries;
    size_t capacity;
    size_t count;
} MemoryManager;

// Function prototypes
MemoryManager* initialize_memory_manager(size_t initial_capacity);
void cleanup_memory_manager(MemoryManager *manager);
int add_entry(MemoryManager *manager, long offset, int key, int status_code);
Entry* get_entry_by_key(MemoryManager *manager, int key);
void periodic_cleanup(MemoryManager *manager);

// Initialize memory manager
MemoryManager* initialize_memory_manager(size_t initial_capacity) {
    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->count = 0;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->entries = (Entry**)malloc(initial_capacity * sizeof(Entry*));

    if (!manager->offsets || !manager->keys || !manager->entries) {
        cleanup_memory_manager(manager);
        return NULL;
    }

    return manager;
}

// Cleanup memory manager
void cleanup_memory_manager(MemoryManager *manager) {
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->entries[i]);
        }
        free(manager->entries);
        free(manager);
    }
}

// Add entry to memory manager
int add_entry(MemoryManager *manager, long offset, int key, int status_code) {
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        long *new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
        Entry **new_entries = (Entry**)realloc(manager->entries, new_capacity * sizeof(Entry*));

        if (!new_offsets || !new_keys || !new_entries) {
            return -1; // Memory allocation failure
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    manager->offsets[manager->count] = offset;
    manager->keys[manager->count] = key;

    Entry *new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) {
        return -1; // Memory allocation failure
    }

    new_entry->timestamp = time(NULL);
    new_entry->status_code = status_code;
    new_entry->key_reference = key;

    manager->entries[manager->count] = new_entry;
    manager->count++;

    return 0;
}

// Get entry by key
Entry* get_entry_by_key(MemoryManager *manager, int key) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->keys[i] == key) {
            return manager->entries[i];
        }
    }
    return NULL;
}

// Periodic cleanup of unused entries
void periodic_cleanup(MemoryManager *manager) {
    time_t current_time = time(NULL);
    size_t new_count = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        Entry *entry = manager->entries[i];
        if ((current_time - entry->timestamp) < (60 * 60 * 24)) { // Keep entries from the last 24 hours
            manager->offsets[new_count] = manager->offsets[i];
            manager->keys[new_count] = manager->keys[i];
            manager->entries[new_count] = entry;
            new_count++;
        } else {
            free(entry);
        }
    }

    manager->count = new_count;

    // Optionally shrink the arrays if too much space is unused
}

// Main function for testing purposes
int main() {
    MemoryManager *manager = initialize_memory_manager(1000);
    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return EXIT_FAILURE;
    }

    add_entry(manager, 12345L, 1, 200);
    Entry *entry = get_entry_by_key(manager, 1);
    if (entry) {
        printf("Entry found: Timestamp=%ld, Status Code=%d\n", entry->timestamp, entry->status_code);
    } else {
        printf("Entry not found\n");
    }

    periodic_cleanup(manager);

    cleanup_memory_manager(manager);
    return EXIT_SUCCESS;
}
```

### Rationale for Design Choices:

1. **Dynamic Array Allocation**: The use of dynamic arrays allows the system to scale efficiently by reallocating memory as needed, doubling capacity when full. This approach balances performance and memory usage.

2. **Periodic Cleanup**: Entries older than 24 hours are removed during cleanup to maintain a manageable memory footprint without impacting recent entries' access speed.

3. **Error Handling**: Comprehensive error handling ensures the system remains stable even if memory allocation fails, with proper resource deallocation in such cases.

4. **Modularity and Maintainability**: The code is structured into functions for initialization, adding entries, cleanup, and retrieval, making it easier to understand and extend.

5. **Trade-offs**: Doubling array capacity during expansion may lead to temporary overhead but ensures amortized constant time complexity for insertions. This trade-off is acceptable given the need for scalability and performance.']

