#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <openssl/evp.h>

#define LOG_FILE "process_cipher_command.log"
#define CACHE_SIZE 10

typedef struct {
    char *cipher_type;
    EVP_CIPHER_CTX *ctx;
} CipherCacheEntry;

CipherCacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int cache_usage = 0;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

EVP_CIPHER_CTX* get_cipher_context(const char *cipher_type) {
    pthread_mutex_lock(&cache_lock);

    for (int i = 0; i < cache_usage; ++i) {
        if (strcmp(cache[i].cipher_type, cipher_type) == 0 && cache[i].ctx != NULL) {
            pthread_mutex_unlock(&cache_lock);
            return cache[i].ctx;
        }
    }

    EVP_CIPHER_CTX *new_ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(new_ctx, EVP_get_cipherbyname(cipher_type), NULL, NULL, NULL)) {
        log_message("Failed to initialize cipher context");
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    for (int i = 0; i < cache_usage && cache_usage < CACHE_SIZE; ++i) {
        if (cache[i].ctx == NULL) {
            cache[i].cipher_type = strdup(cipher_type);
            cache[i].ctx = new_ctx;
            pthread_mutex_unlock(&cache_lock);
            return new_ctx;
        }
    }

    // Evict the oldest entry if cache is full
    EVP_CIPHER_CTX_free(cache[0].ctx);
    free(cache[0].cipher_type);
    memmove(&cache[0], &cache[1], sizeof(CipherCacheEntry) * (cache_usage - 1));
    cache[--cache_usage].cipher_type = strdup(cipher_type);
    cache[cache_usage].ctx = new_ctx;

    pthread_mutex_unlock(&cache_lock);
    return new_ctx;
}

void free_cipher_context(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

int processCipherCommand(const char *input_file_path, const char *cipher_option) {
    struct stat file_stat;
    if (stat(input_file_path, &file_stat) != 0 || !S_ISREG(file_stat.st_mode)) {
        log_message("File does not exist or is not readable");
        return -1;
    }

    FILE *input_file = fopen(input_file_path, "r");
    if (!input_file) {
        char err_msg[256];
        snprintf(err_msg, sizeof(err_msg), "Failed to open file: %s", strerror(errno));
        log_message(err_msg);
        return -1;
    }
    fclose(input_file);

    EVP_CIPHER_CTX *cipher_ctx = get_cipher_context(cipher_option);
    if (!cipher_ctx) {
        log_message("Cipher initialization failed");
        return -1;
    }

    pid_t pid = fork();
    if (pid == 0) {
        // Child process: execute a background command
        execlp("some_command", "some_command", NULL);
        _exit(1); // Exit child if exec fails
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            log_message("Background command failed");
            free_cipher_context(cipher_ctx);
            return -1;
        }
    } else {
        char err_msg[256];
        snprintf(err_msg, sizeof(err_msg), "Fork failed: %s", strerror(errno));
        log_message(err_msg);
        free_cipher_context(cipher_ctx);
        return -1;
    }

    // Signal handling setup
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Replace with appropriate handler if needed
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    log_message("Cipher command processed successfully");
    return (int)cipher_ctx;
}

// Example usage
/*
#include <stdio.h>

int main() {
    const char *input_file = "example.txt";
    const char *cipher_option = "AES-256-CBC";

    int cipher_ptr = processCipherCommand(input_file, cipher_option);
    if (cipher_ptr != -1) {
        printf("Cipher context pointer: %p\n", (void *)cipher_ptr);
    } else {
        printf("Failed to process cipher command.\n");
    }

    return 0;
}
*/

// Compile with:
// gcc -o program yourfile.c -lssl -lcrypto -lpthread
```']

['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StringProcessor {

    private static final Logger logger = Logger.getLogger(StringProcessor.class.getName());
    private Configuration config;

    public StringProcessor(Configuration configuration) {
        this.config = configuration;
    }

    public Report processStrings(String... inputs) {
        List<String> concatenatedResult = new ArrayList<>();
        int validCount = 0, totalProcessed = 0, errorCount = 0;

        for (String input : inputs) {
            try {
                totalProcessed++;

                if (!input.matches("[a-zA-Z0-9]*")) {
                    logger.log(Level.WARNING, "Invalid string detected: " + input);
                    continue;
                }

                String hashResult = getMd5Hash(input);
                concatenatedResult.add(hashResult);

                validCount++;

                if (concatenatedResult.size() > 0) {
                    String combinedResult = new StringBuilder(concatenatedResult).toString();

                    if (combinedResult.length() > config.getMaxStringLength()) {
                        logger.log(Level.SEVERE, "Concatenated string exceeds maximum length.");
                        errorCount++;
                        break;
                    }
                }
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error processing string: " + input, e);
                errorCount++;
            }
        }

        return new Report(validCount, totalProcessed, errorCount, 
                          concatenatedResult.toString(), config.getStatus());
    }

    private String getMd5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());

            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "MD5 Algorithm not found", e);
            return null;
        }
    }

    public static class Report {
        private final int validRequests;
        private final int totalProcessed;
        private final int errorsEncountered;
        private final String concatenatedHashes;
        private final ConfigurationStatus configStatus;

        public Report(int validRequests, int totalProcessed, int errorsEncountered,
                      String concatenatedHashes, ConfigurationStatus configStatus) {
            this.validRequests = validRequests;
            this.totalProcessed = totalProcessed;
            this.errorsEncountered = errorsEncountered;
            this.concatenatedHashes = concatenatedHashes;
            this.configStatus = configStatus;
        }

        @Override
        public String toString() {
            return "Valid Requests: " + validRequests +
                   ", Total Processed: " + totalProcessed +
                   ", Errors Encountered: " + errorsEncountered +
                   ", Concatenated Hashes: " + concatenatedHashes +
                   ", Configuration Status: " + configStatus;
        }
    }

    public interface Configuration {
        int getMaxStringLength();
        ConfigurationStatus getStatus();
    }

    public static class ConfigurationStatus {
        private final boolean isConnected;

        public ConfigurationStatus(boolean isConnected) {
            this.isConnected = isConnected;
        }

        @Override
        public String toString() {
            return "Connection Status: " + (isConnected ? "Healthy" : "Unhealthy");
        }
    }
}
```

