```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
    int key;
    double measurement;
} record;

void initialize_arrays(long *offsets, int offsets_count,
                       int *keys, int keys_count,
                       double *measurements, int measurements_count,
                       record *records, int records_count,
                       long min_val, long max_val,
                       double mean, double stddev) {
    // Seed random number generator
    srand(time(NULL));

    for (int i = 0; i < records_count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        int offset_index = rand() % offsets_count;
        int key_index = rand() % keys_count;

        records[i].offset = offsets[offset_index];
        records[i].key = keys[key_index];

        // Generate a Gaussian distributed measurement
        double u1 = ((double) rand()) / RAND_MAX;
        double u2 = ((double) rand()) / RAND_MAX;
        double z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
        records[i].measurement = mean + stddev * z0;

        // Store the measurement for reuse
        measurements[i] = records[i].measurement;
    }
}

int main() {
    int offsets_count = 10; // Example count, adjust as needed
    int keys_count = 10;    // Example count, adjust as needed
    int records_count = 1000;

    long *offsets = (long *)malloc(offsets_count * sizeof(long));
    int *keys = (int *)malloc(keys_count * sizeof(int));
    double *measurements = (double *)malloc(records_count * sizeof(double));
    record *records = (record *)malloc(records_count * sizeof(record));

    if (!offsets || !keys || !measurements || !records) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    // Initialize offsets and keys with some values
    for (int i = 0; i < offsets_count; ++i) {
        offsets[i] = i * 100L;
    }
    for (int i = 0; i < keys_count; ++i) {
        keys[i] = i * 10;
    }

    initialize_arrays(offsets, offsets_count,
                      keys, keys_count,
                      measurements, records_count,
                      records, records_count,
                      1, 100, 5.0, 2.0);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(measurements);
    free(records);

    return EXIT_SUCCESS;
}
