    private $db;
    private $logFile = 'weather_update_log.txt';

    public function __construct(PDO $pdo) {
        $this->db = $pdo;
    }

    public function updateWeather($locationId, $latitude, $longitude) {
        if (!$this->shouldFetchData($locationId)) {
            return; // Skip fetching if within cache duration
        }

        try {
            $weatherData = $this->fetchWeatherData($latitude, $longitude);
            if ($weatherData && $this->isSignificantChange($locationId, $weatherData)) {
                $this->updateDatabase($locationId, $weatherData);
                $this->cacheData($locationId, $weatherData);
                $this->log("Updated weather data for location ID: $locationId");
            } else {
                $this->log("No significant change for location ID: $locationId");
            }
        } catch (Exception $e) {
            $this->log("Error updating weather for location ID: $locationId - " . $e->getMessage());
        }
    }

    private function fetchWeatherData($latitude, $longitude) {
        $url = "{$this->apiUrl}?geocode={$latitude},{$longitude}&format=json&apiKey={$this->apiKey}";

        try {
            $response = file_get_contents($url);
            if ($response === FALSE) throw new Exception("Network failure");

            $data = json_decode($response, true);
            if (json_last_error() !== JSON_ERROR_NONE || !$data['current']) {
                throw new Exception("Invalid API response");
            }

            return [
                'temperature' => $data['current']['temp'],
                'humidity' => $data['current']['relativeHumidity'],
                'windSpeed' => $data['current']['windSpeed'],
                'uvIndex' => $data['current']['uvIndex']
            ];
        } catch (Exception $e) {
            throw new Exception("Failed to fetch weather data: " . $e->getMessage());
        }
    }

    private function isSignificantChange($locationId, $newData) {
        $stmt = $this->db->prepare("SELECT temperature, humidity, windSpeed, uvIndex FROM weather WHERE location_id = :locationId");
        $stmt->execute([':locationId' => $locationId]);
        $existingData = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$existingData) return true;

        // Define a threshold for significant change
        $thresholds = ['temperature' => 2, 'humidity' => 5, 'windSpeed' => 1, 'uvIndex' => 1];

        foreach ($newData as $key => $value) {
            if (abs($existingData[$key] - $value) > $thresholds[$key]) {
                return true;
            }
        }

        return false;
    }

    private function updateDatabase($locationId, $data) {
        $stmt = $this->db->prepare(
            "INSERT INTO weather (location_id, temperature, humidity, wind_speed, uv_index, last_updated)
             VALUES (:locationId, :temperature, :humidity, :windSpeed, :uvIndex, NOW())
             ON DUPLICATE KEY UPDATE
             temperature = VALUES(temperature),
             humidity = VALUES(humidity),
             wind_speed = VALUES(windSpeed),
             uv_index = VALUES(uvIndex),
             last_updated = NOW()"
        );
        $stmt->execute([
            ':locationId' => $locationId,
            ':temperature' => $data['temperature'],
            ':humidity' => $data['humidity'],
            ':windSpeed' => $data['windSpeed'],
            ':uvIndex' => $data['uvIndex']
        ]);
    }

    private function cacheData($locationId, $data) {
        $cacheFile = sys_get_temp_dir() . "/weather_cache_{$locationId}.json";
        file_put_contents($cacheFile, json_encode(['timestamp' => time(), 'data' => $data]));
    }

    private function shouldFetchData($locationId) {
        $cacheFile = sys_get_temp_dir() . "/weather_cache_{$locationId}.json";

        if (!file_exists($cacheFile)) return true;

        $cacheContent = json_decode(file_get_contents($cacheFile), true);
        return (time() - $cacheContent['timestamp']) > $this->cacheDuration;
    }

    private function log($message) {
        file_put_contents($this->logFile, date('Y-m-d H:i:s') . " - $message" . PHP_EOL, FILE_APPEND);
    }
}

// Example usage
try {
    $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
    $weatherUpdater = new WeatherUpdater($pdo);

    // Update weather data for multiple locations
    $locations = [
        ['id' => 1, 'latitude' => 40.7128, 'longitude' => -74.0060],
        ['id' => 2, 'latitude' => 34.0522, 'longitude' => -118.2437]
    ];

    foreach ($locations as $location) {
        $weatherUpdater->updateWeather($location['id'], $location['latitude'], $location['longitude']);
    }
} catch (PDOException $e) {
    echo "Database error: " . $e->getMessage();
}
```

This code provides a robust solution for fetching, caching, and updating weather data from an external API while minimizing unnecessary database writes. It includes error handling, logging, and a basic caching mechanism to reduce API load. The function is designed to handle multiple locations concurrently and can adapt to changes in the API response format with minimal intervention.']

