using System;
using System.Threading;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private static readonly object lockObject = new object();

    // Thread-safe counters for method call tracking
    private int randomFloatInRangeCount = 0;
    private int randomFloatStrictRangeCount = 0;
    private int randomFloatRoundedRangeCount = 0;
    private int randomIntInRangeCount = 0;
    private int randomIntRoundedDownCount = 0;

    // Random instance for number generation
    private readonly Random random = new Random();

    public RandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = (minValue < maxValue) ? minValue : 0f;
        this.maxValue = (minValue < maxValue) ? maxValue : 100f;
    }

    public float GenerateRandomFloatInRange()
    {
        lock (lockObject)
        {
            randomFloatInRangeCount++;
        }

        return (float)(random.NextDouble() * (maxValue - minValue)) + minValue;
    }

    public float GenerateRandomFloatStrictlyInRange()
    {
        lock (lockObject)
        {
            randomFloatStrictRangeCount++;
        }

        if (minValue == maxValue) return 0f;

        return (float)((random.NextDouble() * (maxValue - minValue - 1e-6f)) + minValue + 1e-6f);
    }

    public float GenerateRandomFloatRoundedInRange()
    {
        lock (lockObject)
        {
            randomFloatRoundedRangeCount++;
        }

        return MathF.Round(GenerateRandomFloatInRange(), 2);
    }

    public int GenerateRandomIntInRange()
    {
        lock (lockObject)
        {
            randomIntInRangeCount++;
        }

        if (minValue > maxValue || minValue == maxValue) 
            throw new InvalidOperationException("Invalid range for integer generation.");

        int minInt = Math.Max(int.MinValue, (int)MathF.Floor(minValue));
        int maxInt = Math.Min(int.MaxValue, (int)MathF.Ceiling(maxValue));

        return random.Next(minInt, maxInt + 1);
    }

    public int GenerateRandomIntRoundedDown()
    {
        lock (lockObject)
        {
            randomIntRoundedDownCount++;
        }

        if (minValue > maxValue || minValue == maxValue) 
            throw new InvalidOperationException("Invalid range for integer generation.");

        return (int)MathF.Floor(GenerateRandomFloatInRange());
    }

    public float CalculateMidpoint()
    {
        return (minValue + maxValue) / 2f;
    }

    public bool IsWithinRange(float value)
    {
        return value >= minValue && value <= maxValue;
    }

    public override string ToString()
    {
        return $"[{MathF.Round(minValue, 2)}, {MathF.Round(maxValue, 2)}]";
    }

    // Additional methods to retrieve method call counts for logging purposes
    public int GetRandomFloatInRangeCount() => randomFloatInRangeCount;
    public int GetRandomFloatStrictRangeCount() => randomFloatStrictRangeCount;
    public int GetRandomFloatRoundedRangeCount() => randomFloatRoundedRangeCount;
    public int GetRandomIntInRangeCount() => randomIntInRangeCount;
    public int GetRandomIntRoundedDownCount() => randomIntRoundedDownCount;
}

// Example integration within an application
public class UserInputSimulator
{
    private readonly RandomValueGenerator generator;

    public UserInputSimulator(float minValue, float maxValue)
    {
        this.generator = new RandomValueGenerator(minValue, maxValue);
    }

    public void SimulateUserInputs(int frequency)
    {
        for (int i = 0; i < frequency; i++)
        {
            // Example simulation of user input generation
            Console.WriteLine(generator.GenerateRandomFloatInRange());
        }
    }
}
```

This implementation ensures thread safety with `lock` statements around the increment of counters and handles edge cases like when `minValue` equals `maxValue`. It provides a comprehensive logging mechanism to track method usage, making it suitable for high-concurrency conditions. The integration example demonstrates how this class can simulate user inputs flexibly within an application context.']

