// Structure to hold version information for each file type
typedef struct {
    char extension[10];
    int version;
} FileTypeVersion;

// Global variables
FileTypeVersion *fileTypeVersions = NULL;
int fileTypeCount = 0;
pthread_mutex_t lock;

// Function prototypes
void processDirectory(const char *directoryPath);
void *processFile(void *arg);
char *determineFileType(const char *filePath);
int validateAndGetMetadata(const char *filePath, char *metadata);

void processDirectory(const char *directoryPath) {
    DIR *dir;
    struct dirent *entry;
    pthread_t threads[1024];
    int threadCount = 0;

    if ((dir = opendir(directoryPath)) == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        // Skip "." and ".." entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char filePath[1024];
        snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, entry->d_name);

        // Create a new thread for each file
        if (threadCount < 1024) {
            pthread_create(&threads[threadCount++], NULL, processFile, strdup(filePath));
        }
    }

    closedir(dir);

    // Wait for all threads to complete
    for (int i = 0; i < threadCount; i++) {
        pthread_join(threads[i], NULL);
    }

    free(fileTypeVersions);
}

void *processFile(void *arg) {
    char *filePath = (char *)arg;
    free(arg);

    char fileType[10];
    strcpy(fileType, determineFileType(filePath));

    if (strcmp(fileType, "unknown") == 0) {
        return NULL;
    }

    pthread_mutex_lock(&lock);
    int found = 0;

    for (int i = 0; i < fileTypeCount; i++) {
        if (strcmp(fileTypeVersions[i].extension, fileType) == 0) {
            found = 1;
            fileTypeVersions[i].version++;
            break;
        }
    }

    if (!found) {
        strcpy(fileTypeVersions[fileTypeCount].extension, fileType);
        fileTypeVersions[fileTypeCount++].version = 1;
    }

    pthread_mutex_unlock(&lock);

    // Retrieve the file metadata
    char metadata[256];
    if (validateAndGetMetadata(filePath, metadata)) {
        // Implement additional logic based on retrieved metadata if needed
    }

    return NULL;
}

char *determineFileType(const char *filePath) {
    // Dummy implementation for determining file type
    // In a real scenario, read the file's contents and determine its type

