    if (!file) {
        perror("fopen");
        return "unknown";
    }

    char fileType[10] = "unknown";
    // Example: Check for specific byte patterns to determine file type
    unsigned char buffer[4];
    fread(buffer, 1, sizeof(buffer), file);

    if (buffer[0] == 0x89 && buffer[1] == 0x50 && buffer[2] == 0x4E && buffer[3] == 0x47) {
        strcpy(fileType, "png");
    } else if (buffer[0] == 0xFF && buffer[1] == 0xD8 && buffer[2] == 0xFF) {
        strcpy(fileType, "jpg");
    }

    fclose(file);
    return fileType;
}

int validateAndGetMetadata(const char *filePath, char *metadata) {
    // Dummy implementation for validating and getting metadata
    // In a real scenario, integrate with an external service

    strcpy(metadata, "dummy_metadata");
    return 1; // Return success
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_mutex_init(&lock, NULL);
    fileTypeVersions = malloc(1024 * sizeof(FileTypeVersion));
    fileTypeCount = 0;

    processDirectory(argv[1]);

    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
