```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>

EVP_CIPHER_CTX* initialize_aes_cipher(const char *password, unsigned char iv[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const int key_len = 32; // AES-256
    unsigned char salt[8];
    unsigned char key[key_len];

    // Generate a random salt
    if (!RAND_bytes(salt, sizeof(salt))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive the key using PBKDF2 with SHA256
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                          10000, EVP_sha256(), key_len, key) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher context
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
