    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return NULL;
    }

    // Initialize the keys array with a specific pattern.
    for (size_t i = 0; i < num_offsets; ++i) {
        keys[i] = i * 5 + 7;
    }

    return keys;
}

/**
 * Allocates and initializes an array of records. Returns NULL on allocation failure,
 * along with ensuring that already allocated resources are freed.
 */
Record* allocate_records(size_t num_records, long *offsets, int *keys) {
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the records with offsets and random values.
    srand(time(NULL));  // Seed for random number generation.
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i % num_records]; // Assuming num_offsets == num_records
        records[i].key_value = rand() % 201 - 100;
    }

    // Update the long integer field by adding corresponding keys.
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset += keys[i % num_records]; // Assuming num_offsets == num_records
    }

    return records;
}

/**
 * Function to manage memory allocation and initialization of offsets, keys,
 * and records. Returns a pointer to the allocated records array on success or NULL on failure.
 */
Record* manage_memory(size_t num_offsets, size_t num_records) {
    // Allocate and initialize offsets and keys
    long *offsets = allocate_offsets(num_offsets);
    if (!offsets) return NULL;

    int *keys = allocate_keys(num_offsets);
    if (!keys) {
        free(offsets);  // Free already allocated memory on failure.
        return NULL;
    }

    // Allocate and initialize records based on offsets and keys
    Record *records = allocate_records(num_records, offsets, keys);

    // Free intermediate allocations in case of failure to avoid memory leaks.
    if (!records) {
        free(offsets);
        free(keys);
    }

    return records;
}

int main() {
    size_t num_offsets = 10;   // Example input for number of offsets
    size_t num_records = 10;   // Example input for number of records

    Record *records = manage_memory(num_offsets, num_records);
    if (records) {
        printf("Records allocated and initialized successfully.\n");
        free(records); // Free the memory after use to avoid leaks.
    } else {
        printf("Failed to allocate and initialize records.\n");
    }

    return 0;
}
