import os
import jinja2
import smtplib
from email.message import EmailMessage
import logging
import requests

# Configure logging
logging.basicConfig(filename='error.log', level=logging.ERROR)

def load_template(template_path):
    try:
        with open(template_path, 'r') as file:
            template_content = file.read()
        return jinja2.Template(template_content)
    except Exception as e:
        logging.error(f"Error loading template {template_path}: {e}")
        raise

def render_template(template, context):
    try:
        return template.render(context)
    except Exception as e:
        logging.error(f"Error rendering template: {e}")
        raise

def save_config(file_path, content):
    try:
        if not os.path.exists(os.path.dirname(file_path)):
            os.makedirs(os.path.dirname(file_path))

        with open(file_path, 'w') as file:
            file.write(content)

        os.chmod(file_path, 0o644)  # Set permissions to avoid overwriting existing settings
    except Exception as e:
        logging.error(f"Error saving configuration {file_path}: {e}")
        raise

def notify_admin(subject, body):
    try:
        msg = EmailMessage()
        msg.set_content(body)
        msg['Subject'] = subject
        msg['From'] = 'admin@example.com'
        msg['To'] = 'sysadmin@example.com'

        with smtplib.SMTP('localhost') as server:
            server.send_message(msg)
    except Exception as e:
        logging.error(f"Error sending notification email: {e}")
        raise

def report_to_monitoring_api(success, config_file):
    try:
        api_url = "https://monitoring.example.com/api/report"
        payload = {
            'success': success,
            'config_file': config_file
        }
        response = requests.post(api_url, json=payload)
        if response.status_code != 200:
            logging.error(f"Error reporting to monitoring API for {config_file}: {response.text}")
    except Exception as e:
        logging.error(f"API failure: {e}")

def monitor_changes(config_files):
    # Placeholder for real-time monitoring logic
    pass

def main():
    config_files = ["config1.yaml", "config2.yaml"]
    environment_context = {
        'ENV': os.getenv('ENV', 'production'),
        'INSTANCE_COUNT': os.getenv('INSTANCE_COUNT', 3),
        'RESOURCE_POLICY': os.getenv('RESOURCE_POLICY', 'balanced')
    }

    for config_file in config_files:
        template = load_template(config_file + ".tmpl")
        rendered_content = render_template(template, environment_context)

        # Validate required parameters
        if '{{' in rendered_content or '}}' in rendered_content:
            logging.error(f"Missing parameters in {config_file}")
            raise ValueError("Template rendering failed due to missing parameters.")

        save_config(config_file, rendered_content)
        report_to_monitoring_api(True, config_file)

    try:
        monitor_changes(config_files)
    except Exception as e:
        logging.error(f"Monitoring setup error: {e}")

if __name__ == "__main__":
    main()
```

