typedef struct {
    int value;
    char *key;
    long *dynamic_data;
} record;

// Assume external library function signature is like this:
extern unsigned long secure_random(unsigned long min, unsigned long max);

void initialize_graph(
    size_t offset_size,
    size_t key_size,
    size_t record_size,
    int rand_min_value,
    int rand_max_value,
    size_t min_vertices,
    size_t max_vertices,
    size_t min_edges,
    size_t max_edges,
    void (*record_callback)(const record *),
    void (*pre_add_vertex_edge_callback)(),
    unsigned long (*random_func)(unsigned long, unsigned long)
) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate and initialize offset array
    long *offsets = malloc(offset_size * sizeof(long));
    if (!offsets) goto cleanup;

    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }

    // Allocate and initialize key array
    int *keys = malloc(key_size * sizeof(int));
    if (!keys) goto cleanup;

    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = i;
    }

    // Allocate and initialize record array
    record *records = malloc(record_size * sizeof(record));
    if (!records) goto cleanup;

    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = random_func(rand_min_value, rand_max_value);
        records[i].key = strdup("default_key");
        records[i].dynamic_data = malloc(sizeof(long));
        if (!records[i].dynamic_data) goto cleanup;

        *records[i].dynamic_data = random_func(0, 100);

        if (record_callback) {
            record_callback(&records[i]);
        }
    }

    // Add vertices and edges to the graph
    size_t num_vertices = random_func(min_vertices, max_vertices);
    size_t num_edges = random_func(min_edges, max_edges);

    for (size_t i = 0; i < num_vertices; ++i) {
        if (pre_add_vertex_edge_callback) {
            pre_add_vertex_edge_callback();
        }
        // Add vertex logic here
    }

    for (size_t i = 0; i < num_edges; ++i) {
        if (pre_add_vertex_edge_callback) {
            pre_add_vertex_edge_callback();
        }
        // Add edge logic here
    }

    printf("Vertices added: %zu, Edges added: %zu\n", num_vertices, num_edges);

cleanup:
    pthread_mutex_lock(&lock);
    free(offsets);
    free(keys);
    for (size_t i = 0; i < record_size; ++i) {
        if (records && records[i].key) free(records[i].key);
        if (records && records[i].dynamic_data) free(records[i].dynamic_data);
    }
    free(records);
    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}
