typedef struct {
    long timestamp;
    EventType type;
    char *payload;
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventArray;

// Function to initialize the dynamic array of network events
void init_event_array(EventArray *array, size_t initial_capacity) {
    array->events = malloc(initial_capacity * sizeof(NetworkEvent *));
    if (!array->events) {
        perror("Failed to allocate memory for event array");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

// Function to resize the dynamic array
void resize_event_array(EventArray *array) {
    size_t new_capacity = array->capacity * 2;
    NetworkEvent **new_events = realloc(array->events, new_capacity * sizeof(NetworkEvent *));
    if (!new_events) {
        perror("Failed to reallocate memory for event array");
        exit(EXIT_FAILURE);
    }
    array->events = new_events;
    array->capacity = new_capacity;
}

// Function to add a new event
void add_event(EventArray *array, long timestamp, EventType type, const char *payload_data, size_t payload_size) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_event_array(array);
    }

    NetworkEvent *new_event = malloc(sizeof(NetworkEvent));
    new_event->timestamp = timestamp;
    new_event->type = type;
    new_event->payload = malloc(payload_size + 1);
    memcpy(new_event->payload, payload_data, payload_size);
    new_event->payload[payload_size] = '\0';

    array->events[array->count++] = new_event;

    pthread_mutex_unlock(&array->lock);
}

// Function to update an existing event by timestamp
void update_event(EventArray *array, long timestamp, EventType type, const char *payload_data, size_t payload_size) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i]->timestamp == timestamp) {
            free(array->events[i]->payload);
            array->events[i]->type = type;
            array->events[i]->payload = malloc(payload_size + 1);
            memcpy(array->events[i]->payload, payload_data, payload_size);
            array->events[i]->payload[payload_size] = '\0';
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Function to iterate over all events
void iterate_events(EventArray *array, void (*callback)(NetworkEvent *)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        callback(array->events[i]);
    }

    pthread_mutex_unlock(&array->lock);
}

// Function to free resources used by the event array
void free_event_array(EventArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->events[i]->payload);
        free(array->events[i]);
    }
    free(array->events);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Example callback function for iterating over events
void print_event(NetworkEvent *event) {
    printf("Timestamp: %ld, Type: %d, Payload: %s\n", event->timestamp, event->type, event->payload);
}

// Function to simulate periodic upload of aggregated data to an external logging service
void periodic_upload(EventArray *array) {
    // Simulate aggregation and upload logic here
    printf("Uploading aggregated data...\n");

    // Handle potential transient failures in the logging service
    int success = 0;
    while (!success) {
        // Attempt to upload data
        success = 1; // Simulate successful upload

        if (!success) {
            printf("Upload failed, retrying...\n");
            // Implement backoff strategy or other failure handling here
        }
    }
}

int main() {
    EventArray event_array;
    init_event_array(&event_array, 10);

    add_event(&event_array, 1234567890, EVENT_TYPE_A, "Payload A", 8);
    add_event(&event_array, 1234567891, EVENT_TYPE_B, "Payload B", 9);

    iterate_events(&event_array, print_event);

    periodic_upload(&event_array);

    free_event_array(&event_array);

    return 0;
}
