            fprintf(stderr, "Failed to validate IMSI and MME after %d attempts\n", API_RETRY_LIMIT);
            free(offsets);
            free(keys);
            for (size_t n = 0; n < initialSize; ++n) {
                free(records[n].pointerData);
            }
            free(records);
            free(*ueContexts);
            pthread_mutex_destroy(&lock);
            return -1;
        }

        if (callback) {
            callback(&records[m]);
        }
    }

    // Thread-safe operations example
    pthread_mutex_lock(&lock);

    // Example of adding a UE context thread-safely
    strcpy((*ueContexts)[0].imsi, "123456789012345");
    snprintf((*ueContexts)[0].mmeIdentifier, sizeof((*ueContexts)[0].mmeIdentifier), "mme-identifier");
    (*ueContexts)[0].nasMessageSequenceNumber = 1;

    pthread_mutex_unlock(&lock);

    // Cleanup
    free(offsets);
    free(keys);
    for (size_t n = 0; n < initialSize; ++n) {
        free(records[n].pointerData);
    }
    free(records);
    pthread_mutex_destroy(&lock);

    return 0;
}

// Example callback function
int exampleCallback(Record *record) {
    printf("Processing record with value: %d and key: %s\n", record->value, record->stringKey);
    *(record->pointerData) = record->value * 2; // Arbitrary processing
    return 0;
}

// Usage Example
int main() {
    UEContext *ueContexts = NULL;

    if (initializeUEContextCollection(&ueContexts, 10, exampleCallback, 42) != 0) {
        fprintf(stderr, "Initialization failed\n");
        free(ueContexts);
        return EXIT_FAILURE;
    }

    // Use ueContexts...

    free(ueContexts);
    return EXIT_SUCCESS;
}
