Record* get_record_by_index(RecordManager *rm, int index);
void resize_contexts(ContextManager *cm);
void resize_records(RecordManager *rm);

// Initialize context manager
void initialize_context_manager(ContextManager *cm) {
    cm->contexts = malloc(INITIAL_CAPACITY * sizeof(UEContext *));
    cm->size = 0;
    cm->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&cm->lock, NULL);
}

// Add a UE context
int add_ue_context(ContextManager *cm, const char *imsi, int mme_id, int nas_sequence_number) {
    pthread_mutex_lock(&cm->lock);

    if (cm->size >= cm->capacity) resize_contexts(cm);

    UEContext *context = malloc(sizeof(UEContext));
    strncpy(context->imsi, imsi, MAX_IMSI_LENGTH);
    context->mme_id = mme_id;
    context->nas_sequence_number = nas_sequence_number;

    cm->contexts[cm->size++] = context;

    pthread_mutex_unlock(&cm->lock);
    return 0; // Success
}

// Get a UE context by IMSI
UEContext* get_ue_context(ContextManager *cm, const char *imsi) {
    pthread_mutex_lock(&cm->lock);

    for (int i = 0; i < cm->size; ++i) {
        if (strcmp(cm->contexts[i]->imsi, imsi) == 0) {
            pthread_mutex_unlock(&cm->lock);
            return cm->contexts[i];
        }
    }

    pthread_mutex_unlock(&cm->lock);
    return NULL;
}

// Resize context array
void resize_contexts(ContextManager *cm) {
    int new_capacity = cm->capacity * 2;
    UEContext **new_array = realloc(cm->contexts, new_capacity * sizeof(UEContext *));
    if (new_array) {
        cm->contexts = new_array;
        cm->capacity = new_capacity;
    }
}

// Initialize record manager
void initialize_record_manager(RecordManager *rm) {
    rm->records = malloc(INITIAL_CAPACITY * sizeof(Record *));
    rm->size = 0;
    rm->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&rm->lock, NULL);
}

// Add a record
int add_record(RecordManager *rm, int value, const char *key, long offset_value) {
    pthread_mutex_lock(&rm->lock);

    if (rm->size >= rm->capacity) resize_records(rm);

    Record *record = malloc(sizeof(Record));
    record->value = value;
    strncpy(record->key, key, sizeof(record->key) - 1);
    record->offset_value = malloc(sizeof(long));
    *(record->offset_value) = offset_value;

    rm->records[rm->size++] = record;

    pthread_mutex_unlock(&rm->lock);
    return 0; // Success
}

// Get a record by index
Record* get_record_by_index(RecordManager *rm, int index) {
    if (index < 0 || index >= rm->size) return NULL;
    return rm->records[index];
}

// Resize records array
void resize_records(RecordManager *rm) {
    int new_capacity = rm->capacity * 2;
    Record **new_array = realloc(rm->records, new_capacity * sizeof(Record *));
    if (new_array) {
        rm->records = new_array;
        rm->capacity = new_capacity;
    }
}

// Example usage
int main() {
    ContextManager cm;
    initialize_context_manager(&cm);

    add_ue_context(&cm, "123456789012345", 1, 100);
    UEContext *context = get_ue_context(&cm, "123456789012345");
    if (context) {
        printf("Retrieved IMSI: %s\n", context->imsi);
    }

    RecordManager rm;
    initialize_record_manager(&rm);

    add_record(&rm, 42, "key1", 1000L);
    Record *record = get_record_by_index(&rm, 0);
    if (record) {
        printf("Retrieved Key: %s\n", record->key);
    }

    return 0;
}
