namespace fs = std::filesystem;

std::vector<std::string> inputDirs;
std::string outputDir;
std::atomic<bool> running{true};
std::mutex logMutex;

void signalHandler(int signum) {
    std::cout << "Interrupt signal (" << signum << ") received. Exiting gracefully.\n";
    running = false;
}

struct LogEntry {
    std::string filename;
    std::chrono::steady_clock::time_point start_time;
};

std::vector<LogEntry> processingLogs;

void logProcessingStart(const fs::path& filePath) {
    std::lock_guard<std::mutex> lock(logMutex);
    processingLogs.push_back({filePath.string(), std::chrono::steady_clock::now()});
}

void logProcessingEnd() {
    std::lock_guard<std::mutex> lock(logMutex);
    for (auto& entry : processingLogs) {
        auto end_time = std::chrono::steady_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - entry.start_time).count();
        spdlog::info("Processed {} in {} ms", entry.filename, duration);
    }
}

void processDirectory(const fs::path& dirPath) {
    if (!fs::exists(dirPath) || !fs::is_directory(dirPath)) return;

    logProcessingStart(dirPath);

    try {
        for (const auto& entry : fs::recursive_directory_iterator(dirPath)) {
            if (entry.is_regular_file() && entry.path().extension() == ".log") {
                // Process file logic here
                spdlog::info("Processing file: {}", entry.path());

                fs::path outputFilePath = outputDir / (entry.path().stem().string() + "_aggregated" + entry.path().extension().string());
                std::ofstream outputFile(outputFilePath, std::ios::out | std::ios::binary);
                if (!outputFile) {
                    spdlog::error("Failed to open output file: {}", outputFilePath);
                    continue;
                }

                // Example aggregation logic
                outputFile << "Aggregated content for " << entry.path() << "\n";
            }
        }
    } catch (const fs::filesystem_error& e) {
        spdlog::error("Filesystem error: {}", e.what());
    }

    logProcessingEnd();
}

void compressFiles(const fs::path& dirPath, const std::string& extension) {
    for (const auto& entry : fs::directory_iterator(dirPath)) {
        if (entry.is_regular_file() && entry.path().extension() == extension) {
            // Compression logic using zlib or similar library
            spdlog::info("Compressing file: {}", entry.path());
            // Note: Implement compression logic here
        }
    }
}

void processInputDirectories() {
    std::vector<std::thread> threads;

    for (const auto& dir : inputDirs) {
        if (!running) break;

        threads.emplace_back(processDirectory, dir);
    }

    for (auto& t : threads) {
        if (t.joinable()) t.join();
    }
}

void setupSignalHandling() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cout << "Usage: <program> <input_dir1> [input_dir2 ...] --output-dir=<output_directory>\n";
        return 1;
    }

    for (int i = 1; i < argc; ++i) {
        std::string arg(argv[i]);
        if (arg == "--output-dir=" && i + 1 < argc) {
            outputDir = argv[++i];
        } else {
            inputDirs.push_back(arg);
        }
    }

    if (inputDirs.empty() || outputDir.empty()) {
        std::cout << "Missing required arguments. Use --help for usage information.\n";
        return 1;
    }

    setupSignalHandling();

    spdlog::info("Starting processing...");

    processInputDirectories();

    compressFiles(outputDir, ".txt"); // Assuming .txt as aggregated extension

    spdlog::info("Processing completed.");

    return 0;
}
