typedef struct {
    char imsi[15];
    int mmeIdentifier;
    unsigned long nasMessageSequenceNumber;
    unsigned long nasMessageId;
    char nasMessageData[256]; // Example size, adjust as necessary
} UEContext;

// Function to simulate NAS message generation
void generateNasMessage(UEContext *ue) {
    ue->nasMessageId = rand() % 1000000; // Simulate a random ID
    snprintf(ue->nasMessageData, sizeof(ue->nasMessageData), "NAS Message for IMSI: %s", ue->imsi);
}

// Worker function for initializing UEContext
void* initializeUEContext(void *arg) {
    int index = *(int*)arg;
    UEContext *contexts = (UEContext *)((char *)arg + sizeof(int));

    snprintf(contexts[index].imsi, sizeof(contexts[index].imsi), "IMSI%010d", index);
    contexts[index].mmeIdentifier = rand() % 1000; // Simulate a random MME identifier
    contexts[index].nasMessageSequenceNumber = (unsigned long)index;

    generateNasMessage(&contexts[index]);

    return NULL;
}

// Function to initialize UEContexts
void initUEContexts(UEContext **contexts, int numberOfUEContexts, bool enableParallelProcessing) {
    *contexts = malloc(sizeof(UEContext) * numberOfUEContexts);
    if (*contexts == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_t *threads;
    if (enableParallelProcessing) {
        threads = malloc(numberOfUEContexts * sizeof(pthread_t));
        if (threads == NULL) {
            free(*contexts);
            fprintf(stderr, "Thread allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < numberOfUEContexts; ++i) {
            int* index = malloc(sizeof(int));
            if (index == NULL) {
                free(threads);
                free(*contexts);
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            *index = i;

            pthread_create(&threads[i], NULL, initializeUEContext, (void *)((char *)index + sizeof(int)));
        }

        for (int i = 0; i < numberOfUEContexts; ++i) {
            pthread_join(threads[i], NULL);
            free((void*)((char*)threads + i * sizeof(pthread_t)) - sizeof(int));
        }

        free(threads);
    } else {
        for (int i = 0; i < numberOfUEContexts; ++i) {
            initializeUEContext((void *)((char *)&i + sizeof(int)));
        }
    }
}

// Dummy function to simulate image-to-PDF conversion
