void manage_memory_and_initialize(long** offsets, int** keys, record*** records,
                                  int offset_count, int key_count, 
                                  int record_count, int min_val, int max_val, 
                                  char* log) {
    *offsets = get_offsets(offset_count);
    if (*offsets == NULL) {
        sprintf(log, "Failed to allocate memory for offsets.\n");
        return;
    }

    *keys = fetch_keys(key_count);
    if (*keys == NULL) {
        sprintf(log, "Failed to retrieve keys from external source or allocation failed.\n");
        free(*offsets);
        return;
    }

    *records = (record**) malloc(record_count * sizeof(record*));
    if (*records == NULL) {
        sprintf(log, "Failed to allocate memory for records array.\n");
        free(*keys);
        free(*offsets);
        return;
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < record_count; ++i) {
        (*records)[i] = (record*) malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            sprintf(log, "Failed to allocate memory for record %d.\n", i);
            while (--i >= 0) free((*records)[i]);
            free(*records);
            *records = NULL;
            free(*keys);
            free(*offsets);
            return;
        }

        int rand_val = (rand() % (max_val - min_val + 1)) + min_val;
        while (!validate_record((*records)[i]->value, min_val, max_val)) {
            rand_val = (rand() % (max_val - min_val + 1)) + min_val;
        }
        (*records)[i]->value = rand_val;
    }

    sprintf(log, "Memory allocation and initialization successful.\n");
}

// Example implementations for external functions
