#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure for records
typedef struct {
    int value;
} record;

// Function prototypes
void initialize_dynamic_structures(int num_arrays, int num_keys, int num_records, 
                                   long* array_sizes, FILE* log_file, const char* csv_filename);

int generate_random_int(int min, int max);
int validate_record_value(int value, int criteria_min, int criteria_max);
void export_to_csv(record* records, int num_records, const char* filename);
void free_resources(long** offsets, int* keys, record** recs, long num_offsets, 
                    int num_keys, int num_records);

// Main function to manage memory allocation and initialization
void initialize_dynamic_structures(int num_arrays, int num_keys, int num_records, 
                                   long* array_sizes, FILE* log_file, const char* csv_filename) {
    if (!log_file || !csv_filename || num_arrays <= 0 || num_keys <= 0 || num_records <= 0) return;

    // Seed random number generator
    srand(time(NULL));

    // Dynamic allocation and initialization of arrays, keys, records, and statuses
    long** offsets = (long**)malloc(num_arrays * sizeof(long*));
    int* keys = (int*)malloc(num_keys * sizeof(int));
    record** records = (record**)malloc(num_records * sizeof(record*));

    if (!offsets || !keys || !records) {
        fprintf(log_file, "Memory allocation failed\n");
        free_resources(offsets, keys, records, num_arrays, num_keys, num_records);
        return;
    }

    for (int i = 0; i < num_arrays; ++i) {
        offsets[i] = (long*)malloc(array_sizes[i] * sizeof(long));
        if (!offsets[i]) {
            fprintf(log_file, "Memory allocation failed for array %d\n", i);
            free_resources(offsets, keys, records, num_arrays, num_keys, num_records);
            return;
        }
    }

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = generate_random_int(0, 100); // Example range
    }

    int criteria_min = 10;  // Example validation criteria
    int criteria_max = 50;

    for (int i = 0; i < num_records; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(log_file, "Memory allocation failed for record %d\n", i);
            free_resources(offsets, keys, records, num_arrays, num_keys, num_records);
            return;
        }

        int retries = 0;
        do {
            records[i]->value = generate_random_int(criteria_min - 10, criteria_max + 10); // Wider range
            if (!validate_record_value(records[i]->value, criteria_min, criteria_max)) {
                ++retries;
            }
        } while (retries < 5 && !validate_record_value(records[i]->value, criteria_min, criteria_max));

        fprintf(log_file, "Record %d: Value = %d after %d retries\n", i, records[i]->value, retries);
    }

    // Export to CSV
    export_to_csv(*records, num_records, csv_filename);

    // Free resources and cleanup
    free_resources(offsets, keys, records, num_arrays, num_keys, num_records);
}

// Generate random integer within a range
int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Validate record value against criteria
int validate_record_value(int value, int criteria_min, int criteria_max) {
    return (value >= criteria_min && value <= criteria_max);
}

// Export records to a CSV file
void export_to_csv(record* records, int num_records, const char* filename) {
    FILE* csv_file = fopen(filename, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        return;
    }

    fprintf(csv_file, "Value\n");
    for (int i = 0; i < num_records; ++i) {
        fprintf(csv_file, "%d\n", records[i].value);
    }

    fclose(csv_file);
}

// Free dynamically allocated resources
void free_resources(long** offsets, int* keys, record** recs, long num_offsets, 
                    int num_keys, int num_records) {
    for (long i = 0; i < num_offsets; ++i) {
        free(offsets[i]);
    }
    free(offsets);

    free(keys);

    for (int i = 0; i < num_records; ++i) {
        free(recs[i]);
    }
    free(recs);
}
