['Below is a C implementation of the described task. It uses POSIX semaphores for synchronization, JSON parsing with `jansson` library, and simple HTTP logging using `libcurl`. You'll need to link against these libraries when compiling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <string.h>
#include <curl/curl.h>
#include <jansson.h>

#define MAX_THREADS 500

typedef struct {
    int shared_resource;
    sem_t semaphore;
} SharedResource;

SharedResource resource = {0, SEM_FAILED};
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Function declarations
void load_config();
int get_shared_value();
void set_shared_value(int value);
void log_state(int thread_id);
void reset_to_initial();
void* async_access(void* arg);

// Global variables for configuration and logging
int initial_resource_value;
char* config_file_path = "config.json";

// Helper function to handle JSON parsing and loading config
void load_config() {
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = malloc(fsize + 1);
    fread(buffer, 1, fsize, file);
    buffer[fsize] = '\0';
    fclose(file);

    json_error_t error;
    json_t *root = json_loads(buffer, 0, &error);
    free(buffer);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return;
    }

    initial_resource_value = json_integer_value(json_object_get(root, "initial_value"));
    json_decref(root);
}

// Synchronous access to the shared resource
int get_shared_value() {
    sem_wait(&resource.semaphore);
    int value = resource.shared_resource;
    sem_post(&resource.semaphore);

    return value;
}

void set_shared_value(int value) {
    sem_wait(&resource.semaphore);
    resource.shared_resource = value;
    log_state(pthread_self());
    sem_post(&resource.semaphore);
}

// Log the state of the shared resource
void log_state(int thread_id) {
    CURL *curl = curl_easy_init();
    if (curl) {
        char post_data[256];
        snprintf(post_data, sizeof(post_data), "thread_id=%d&value=%d", thread_id, get_shared_value());

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/x-www-form-urlencoded");

        curl_easy_setopt(curl, CURLOPT_URL, "http://logging-service.local/log");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
}

// Reset the shared resource to its initial value
void reset_to_initial() {
    pthread_mutex_lock(&config_lock);
    sem_wait(&resource.semaphore);
    resource.shared_resource = initial_resource_value;
    log_state(pthread_self());
    sem_post(&resource.semaphore);
    pthread_mutex_unlock(&config_lock);
}

// Asynchronous access function for threads
void* async_access(void* arg) {
    int value = *(int*)arg;

    set_shared_value(value);

    return NULL;
}

int main() {
    load_config();

    if (sem_init(&resource.semaphore, 0, 1) != 0) {
        perror("Failed to initialize semaphore");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_THREADS];
    int values[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        values[i] = rand() % 100;
        if (pthread_create(&threads[i], NULL, async_access, &values[i])) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    reset_to_initial();

    sem_destroy(&resource.semaphore);

    return 0;
}
```

### Notes:
- **Semaphore**: Used to protect access to the shared resource.
- **Configuration Loading**: Uses `jansson` for JSON parsing. Make sure to handle different data formats as needed.
- **Logging**: Utilizes `libcurl` for HTTP logging. Adjust the URL and headers based on your logging service.
- **Thread Safety**: Managed using semaphores and mutexes.
- **Error Handling**: Basic error handling is implemented; extend it as necessary.

### Compilation:
```bash
gcc -o resource_manager resource_manager.c -lpthread -ljansson -lcurl
```

Ensure the `jansson` and `libcurl` libraries are installed on your system. Adjust paths and configurations according to your environment.']

