        for (int i = 0; i < count; ++i)
            if (inputArray[i] > currentHighest)
                currentHighest = inputArray[i];

        highestValue = currentHighest > highestValue ? currentHighest : highestValue;
        pthread_mutex_unlock(&mutex);
    }

cleanup:
