#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Assuming an external library for secure random number generation.
extern int secure_rand(int min, int max);
extern void log_error(const char* message);

typedef struct {
    int value;
    char key[256];
    long* ptr;
} record;

#define INITIAL_SIZE 10
#define MAX_RETRIES 3

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void processRecordCallback(record* rec) {
    // Example callback: just printing the initialized record's value.
    printf("Initialized record with value: %d\n", rec->value);
}

long long secureRandomInRange(int min, int max, unsigned int seed) {
    srand(seed);  // Initial seeding
    return (long long)(secure_rand(min, max));
}

int* resizeArray(int* array, size_t currentSize, size_t newSize) {
    if (newSize <= currentSize)
        return array;

    int* newArray = realloc(array, sizeof(int) * newSize);
    if (!newArray) {
        log_error("Failed to reallocate memory for array");
        return NULL;
    }

    memset(newArray + currentSize, 0, (newSize - currentSize) * sizeof(int));
    return newArray;
}

long* resizeLongArray(long* array, size_t currentSize, size_t newSize) {
    if (newSize <= currentSize)
        return array;

    long* newArray = realloc(array, sizeof(long) * newSize);
    if (!newArray) {
        log_error("Failed to reallocate memory for long array");
        return NULL;
    }

    memset(newArray + currentSize, 0, (newSize - currentSize) * sizeof(long));
    return newArray;
}

record* resizeRecordsArray(record* records, size_t currentSize, size_t newSize) {
    if (newSize <= currentSize)
        return records;

    record* newRecords = realloc(records, sizeof(record) * newSize);
    if (!newRecords) {
        log_error("Failed to reallocate memory for records array");
        return NULL;
    }

    memset(newRecords + currentSize, 0, (newSize - currentSize) * sizeof(record));
    return newRecords;
}

record* processAndAnalyzeRecords(size_t initialRecordCount, int (*callback)(record*)) {
    size_t recordCount = initialRecordCount;
    record* records = malloc(sizeof(record) * recordCount);

    if (!records) {
        log_error("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    int offsetSize = INITIAL_SIZE, keySize = INITIAL_SIZE;
    long* offsets = malloc(sizeof(long) * offsetSize);
    int* keys = malloc(sizeof(int) * keySize);

    if (!offsets || !keys) {
        log_error("Failed to allocate memory for auxiliary arrays");
        free(records);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < recordCount; ++i) {
        for (int retries = 0; retries < MAX_RETRIES; ++retries) {
            int seed = time(NULL); // or use a custom seed
            long randomValue = secureRandomInRange(1, 100, seed);

            records[i].value = (int)(randomValue % 100);

            if (i >= offsetSize) {
                offsets = resizeLongArray(offsets, offsetSize, offsetSize * 2);
                if (!offsets) {
                    log_error("Failed to resize offsets array");
                    free(records);
                    free(keys);
                    free(offsets);
                    pthread_mutex_unlock(&mutex);
                    return NULL;
                }
                offsetSize *= 2;
            }

            if (i >= keySize) {
                keys = resizeArray(keys, keySize, keySize * 2);
                if (!keys) {
                    log_error("Failed to resize keys array");
                    free(records);
                    free(offsets);
                    pthread_mutex_unlock(&mutex);
                    return NULL;
                }
                keySize *= 2;
            }

            snprintf(records[i].key, sizeof(records[i].key), "Key_%d", keys[i]);
            records[i].ptr = malloc(sizeof(long));

            if (records[i].ptr) {
                *records[i].ptr = offsets[i];

                if (callback && callback(&records[i]) != 0) {
                    log_error("Callback processing failed");
                }
            } else {
                log_error("Failed to allocate memory for record pointer");
                free(records);
                free(keys);
                free(offsets);
                pthread_mutex_unlock(&mutex);
