// Define UserSession structure
typedef struct UserSession {
    int userId;
    int subscriptionId;
    char sessionToken[256];
    struct UserSession *next;
} UserSession;

// Node for managing sessions with thread safety
typedef struct SessionList {
    UserSession *head;
    pthread_mutex_t lock;
} SessionList;

// Global linked list
SessionList sessionList = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Memory pool for efficient allocation (simple example)
#define POOL_SIZE 1024
char memoryPool[POOL_SIZE][256];
int poolIndex = 0;

void *allocateFromPool(size_t size) {
    if (poolIndex < POOL_SIZE && sizeof(memoryPool[0]) >= size) {
        return memoryPool[poolIndex++];
    }
    return malloc(size);
}

void freeToPool(void *ptr, size_t size) {
    if (poolIndex > 0 && ptr != NULL) {
        poolIndex--;
        memcpy(memoryPool[poolIndex], ptr, sizeof(memoryPool[0]));
    } else {
        free(ptr);
    }
}

// Helper function to generate random bytes
void generateRandomBytes(unsigned char *buffer, int length) {
    if (RAND_bytes(buffer, length) != 1) {
        fprintf(stderr, "Error generating random bytes\n");
    }
}

// Function to initialize a session with cryptographic keys
void initializeSession(UserSession *session) {
    unsigned char authKeyId[32], authKeyData[64];

    generateRandomBytes(authKeyId, sizeof(authKeyId));
    generateRandomBytes(authKeyData, sizeof(authKeyData));

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, authKeyId, NULL) != 1 ||
        EVP_EncryptUpdate(ctx, session->sessionToken, NULL, authKeyData, sizeof(authKeyData)) != 1 ||
        EVP_EncryptFinal_ex(ctx, session->sessionToken, NULL) != 1) {
        fprintf(stderr, "Error encrypting session token\n");
    }

    EVP_CIPHER_CTX_free(ctx);
}

// Function to add a new session
void addSession(int userId, int subscriptionId) {
    UserSession *newSession = (UserSession *)allocateFromPool(sizeof(UserSession));
    if (!newSession) return;

    newSession->userId = userId;
    newSession->subscriptionId = subscriptionId;
    initializeSession(newSession);
    newSession->next = NULL;

    pthread_mutex_lock(&sessionList.lock);
    newSession->next = sessionList.head;
    sessionList.head = newSession;
    pthread_mutex_unlock(&sessionList.lock);
}

// Function to remove a session by userId
void removeSession(int userId) {
    pthread_mutex_lock(&sessionList.lock);

    UserSession *current = sessionList.head;
    UserSession *prev = NULL;

    while (current != NULL && current->userId != userId) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL) {
            sessionList.head = current->next;
        } else {
            prev->next = current->next;
        }
        freeToPool(current, sizeof(UserSession));
    }

    pthread_mutex_unlock(&sessionList.lock);
}

// Function to update a session
void updateSession(int userId, int newSubscriptionId) {
    pthread_mutex_lock(&sessionList.lock);

    UserSession *current = sessionList.head;

    while (current != NULL && current->userId != userId) {
        current = current->next;
    }

    if (current != NULL) {
        current->subscriptionId = newSubscriptionId;
        initializeSession(current);
    }

    pthread_mutex_unlock(&sessionList.lock);
}

// Function to simulate authentication
int authenticate(int userId, const char *token) {
    pthread_mutex_lock(&sessionList.lock);

    UserSession *current = sessionList.head;

    while (current != NULL && current->userId != userId) {
        current = current->next;
    }

    int authenticated = 0;

    if (current != NULL) {
        HMAC_CTX *hmacCtx = HMAC_CTX_new();
        unsigned char hmac[32];

        if (HMAC_Init_ex(hmacCtx, current->sessionToken, strlen(current->sessionToken), EVP_sha256(), NULL) == 1 &&
            HMAC_Update(hmacCtx, token, strlen(token)) == 1 &&
            HMAC_Final(hmacCtx, hmac, NULL) == 1) {

            authenticated = (memcmp(hmac, current->sessionToken, sizeof(hmac)) == 0);
        }

        HMAC_CTX_free(hmacCtx);
    }

    pthread_mutex_unlock(&sessionList.lock);

    return authenticated;
}

// Main function to demonstrate usage
void manageSessions() {
    addSession(1, 101);
    updateSession(1, 102);
    int auth = authenticate(1, "someToken");
    printf("Authentication result: %d\n", auth);
    removeSession(1);
}
