#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEYS 100

typedef struct {
    long* offset_ptr;
    int key;
    char* name;
} record;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int generate_unique_keys(int* keys) {
    for (int i = 0; i < MAX_KEYS; ++i)
        keys[i] = -1;

    int count = 0;
    while (count < MAX_KEYS) {
        int num = rand() % MAX_KEYS + 1;
        if (keys[num - 1] == -1) {
            keys[num - 1] = num;
            ++count;
        }
    }

    return count == MAX_KEYS ? 1 : 0;
}

int shuffle_records(record* records, size_t n) {
    for (size_t i = n - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }
    return 1;
}

record* manage_memory() {
    FILE* file = fopen("offsets.txt", "r");
    if (!file) {
        log_error("Failed to open offsets.txt");
        return NULL;
    }

    long offset, *offsets = NULL;
    size_t num_offsets = 0;

    while (fscanf(file, "%ld", &offset) == 1) {
        offsets = realloc(offsets, (num_offsets + 1) * sizeof(long));
        if (!offsets) {
            log_error("Memory allocation failed for offsets");
            fclose(file);
            return NULL;
        }
        offsets[num_offsets++] = offset;
    }

    fclose(file);

    int* keys = malloc(MAX_KEYS * sizeof(int));
    if (!keys || !generate_unique_keys(keys)) {
        log_error("Failed to generate unique keys");
        free(offsets);
        return NULL;
    }

    record* records = malloc(num_offsets * sizeof(record));
    if (!records) {
        log_error("Memory allocation failed for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        records[i].offset_ptr = &offsets[i];
        records[i].key = keys[i];

        char* name_format = malloc(20 * sizeof(char));
        if (!name_format) {
            log_error("Memory allocation failed for name format");
            free(records, offsets, keys);
            return NULL;
        }
        snprintf(name_format, 20, "Record_%zu_Key%d", i, records[i].key);

        records[i].name = strdup(name_format);
        free(name_format);
        if (!records[i].name) {
            log_error("Memory allocation failed for record name");
            for (size_t j = 0; j <= i; ++j)
                free(records[j].name);
            free(records, offsets, keys);
            return NULL;
        }
    }

    shuffle_records(records, num_offsets);

    // Clean up and deallocate resources
    for (size_t i = 0; i < num_offsets; ++i) {
        free(records[i].name);
    }
    free(keys);
    free(offsets);

    return records;
}

int main() {
    srand(time(NULL));
    record* result = manage_memory();
    if (!result) {
        log_error("Memory management failed");
        return EXIT_FAILURE;
    }

    // Utilize the shuffled records as needed
    // ...

    // Free allocated resources
    free(result);

    return EXIT_SUCCESS;
}
```

