import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.client.RestTemplate;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

import java.time.Duration;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

@SpringBootApplication
public class RestClientApplication {

    private static final String TARGET_URL = "https://example.com/api";
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        SpringApplication.run(RestClientApplication.class, args);
    }

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }

    @Bean
    public ExecutorService executorService(int corePoolSize, int maxPoolSize, long keepAliveTimeMs) {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(corePoolSize);
        executor.setMaxPoolSize(maxPoolSize);
        executor.setKeepAliveSeconds(keepAliveTimeMs / 1000);
        executor.initialize();
        return executor;
    }

    public void sendPostRequest() {
        ExecutorService executor = (ExecutorService) applicationContext.getBean("executorService");
        for (int i = 0; i < 10; i++) { // Simulating concurrent requests
            int finalI = i;
            executor.submit(() -> performPostWithRetries(finalI));
        }
    }

    private void performPostWithRetries(int attemptNumber) {
        int retries = 0;
        while (retries <= MAX_RETRIES) {
            try {
                HttpEntity<String> request = new HttpEntity<>("payload", createHeaders());
                restTemplate().postForObject(TARGET_URL, request, String.class);
                // Telemetry: record success
                logTelemetry("Success", attemptNumber);
                return;
            } catch (Exception e) {
                retries++;
                if (retries > MAX_RETRIES) {
                    // Telemetry: record failure
                    logTelemetry("Failure", attemptNumber);
                    throw e;
                }
                try {
                    Thread.sleep((long) Math.pow(2, retries) * 1000); // Exponential backoff
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    private HttpHeaders createHeaders() {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        return headers;
    }

    private void logTelemetry(String status, int attemptNumber) {
        // Implement telemetry logic to report metrics
        System.out.println("Attempt " + attemptNumber + ": " + status);
    }
}

// Mock Test Class using Mockito

import static org.mockito.Mockito.*;

class ConfigServiceTest {

    @org.junit.jupiter.api.Test
    void testConfigurations() throws Exception {
        ConfigService mockService = mock(ConfigService.class);

        when(mockService.getConfig("test")).thenReturn("Success");
        // Simulate latency
        doAnswer(invocation -> {
            Thread.sleep(1000);
            return "Delayed";
        }).when(mockService).getConfig(anyString());

        RestClientApplication app = new RestClientApplication();
        app.sendPostRequest();

        verify(mockService, times(1)).getConfig("test");
    }
}

// Config Service Mock Interface
interface ConfigService {
    String getConfig(String key);
}

