    struct Record *next;
    struct Record *prev;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record *record;
    struct Node *next;
    struct Node *prev;
} Node;

// Forward declarations
int hash_function(int input);
bool is_unique_key(Node* list, int key);
void free_memory(Node* head);
long calculate_offset(size_t index, size_t increment_factor, size_t max_jump);
Record* generate_record(int range_min, int range_max);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Node* initialize_data_structures(size_t num_elements, size_t increment_factor,
                                 size_t max_jump, int key_range_start, int key_range_end,
                                 int record_value_range_min, int record_value_range_max) {
    Node *head = NULL;
    Node *tail = NULL;

    for (size_t i = 0; i < num_elements; ++i) {
        // Allocate memory for the node
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            free_memory(head);
            return NULL;
        }

        // Calculate offset with rolling window constraint
        new_node->offset = calculate_offset(i, increment_factor, max_jump);

        // Generate unique key using a hash function and collision resolution strategy
        int key = 0;
        bool is_unique = false;
        while (!is_unique) {
            key = hash_function((int)i); // Example seed for uniqueness per index
            pthread_mutex_lock(&mutex);
            is_unique = is_unique_key(head, key);
            pthread_mutex_unlock(&mutex);

            if (!is_unique) {
                key += 1; // Simple collision resolution strategy
            }
        }

        new_node->key = key;

        // Generate a unique record value and create the record
        Record* new_record = generate_record(record_value_range_min, record_value_range_max);
        if (!new_record) {
            fprintf(stderr, "Record generation failed\n");
            free(new_node);
            free_memory(head);
            return NULL;
        }
        new_node->record = new_record;

        // Insert the node into the doubly linked list
        if (tail) {
            tail->next = new_node;
            new_node->prev = tail;
        } else {
            head = new_node; // First element case
        }
        new_node->next = NULL;
        tail = new_node;
    }

    return head;
}

long calculate_offset(size_t index, size_t increment_factor, size_t max_jump) {
    long offset = (index * increment_factor) % max_jump;
    return offset;
}

Record* generate_record(int range_min, int range_max) {
    static bool* used_values = NULL; // Global or persistent storage for duplicates
    Record* record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation for record failed\n");
        return NULL;
    }

    if (used_values == NULL) {
        size_t range_size = (range_max - range_min + 1);
        used_values = calloc(range_size, sizeof(bool));
        if (!used_values) {
            free(record);
            fprintf(stderr, "Memory allocation for used values tracking failed\n");
            return NULL;
        }
    }

    int value;
    bool is_unique;
    do {
        value = range_min + rand() % (range_max - range_min + 1);
        pthread_mutex_lock(&mutex);
        is_unique = !used_values[value - range_min];
        if (is_unique) {
            used_values[value - range_min] = true;
        }
        pthread_mutex_unlock(&mutex);

    } while (!is_unique);

    record->value = value;
    record->next = NULL;
    record->prev = NULL;

    return record;
}

bool is_unique_key(Node* list, int key) {
    Node* current = list;
    while (current) {
        if (current->key == key) {
            return false; // Collision found
        }
        current = current->next;
    }
    return true; // No collision
}

void free_memory(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->record);
        free(current);
        current = next;
    }
}
```']

