#include <prometheus/registry.h>
#include <prometheus/exposer.h>
#include <prometheus/gauge.h>
#include <prometheus/histogram.h>
#include <prometheus/counter.h>
#include <thread>
#include <future>
#include <chrono>
#include <iostream>

namespace MetricsCollection {

class ServiceMetrics {
public:
    ServiceMetrics(const std::string& endpoint)
        : registry_(std::make_shared<prometheus::Registry>()),
          exposer_(
              prometheus::Exposer::CreateInstance(endpoint, *registry_, 0.3)) {}

    ~ServiceMetrics() = default;

    void AddCounter(const std::string& name, const std::map<std::string, std::string>& labels) {
        auto counter = std::make_shared<prometheus::Family<prometheus::Counter>>(
            prometheus::Metric{
                .name = name,
                .documentation = "A sample counter",
                .const_labels = labels
            });

        registry_->RegisterFamily(counter);
    }

    void AddGauge(const std::string& name, const std::map<std::string, std::string>& labels) {
        auto gauge = std::make_shared<prometheus::Family<prometheus::Gauge>>(
            prometheus::Metric{
                .name = name,
                .documentation = "A sample gauge",
                .const_labels = labels
            });

        registry_->RegisterFamily(gauge);
    }

    void AddHistogram(const std::string& name, const std::vector<std::pair<double, double>>& buckets, 
                      const std::map<std::string, std::string>& labels) {
        auto histogram = std::make_shared<prometheus::Family<prometheus::Histogram>>(
            prometheus::Metric{
                .name = name,
                .documentation = "A sample histogram",
                .const_labels = labels
            }, buckets);

        registry_->RegisterFamily(histogram);
    }

    void StartAsyncDataIngestion() {
        ingestion_thread_ = std::thread([this]() {
            while (true) {
                // Simulate data ingestion logic here.
                std::this_thread::sleep_for(std::chrono::seconds(1));

                // Example: increment a counter
                auto counter = registry_->GetFamily<prometheus::Counter>("sample_counter");
                if (counter) {
                    (*counter)["example_label"] += 1;
                }
            }
        });
    }

    void Shutdown() {
        if (ingestion_thread_.joinable()) {
            ingestion_thread_.join();
        }
    }

private:
    std::shared_ptr<prometheus::Registry> registry_;
    prometheus::Exposer exposer_;

    std::thread ingestion_thread_;
};

} // namespace MetricsCollection

int main() {
    auto metrics = std::make_shared<MetricsCollection::ServiceMetrics>("http://localhost:8080/metrics");

    metrics->AddCounter("sample_counter", {{"example_label", "value1"}});
    metrics->AddGauge("sample_gauge", {{"example_label", "value2"}});

    std::vector<std::pair<double, double>> buckets = {
        {0.0, 10.0},
        {10.0, 100.0},
        {100.0, 1000.0}
    };

    metrics->AddHistogram("sample_histogram", buckets, {{"example_label", "value3"}});

    metrics->StartAsyncDataIngestion();

    // Simulate application running
    std::this_thread::sleep_for(std::chrono::seconds(10));

    metrics->Shutdown();
    return 0;
}
```

