unsigned int threadSafeRandom(unsigned int min, unsigned int max) {
    pthread_mutex_lock(&rand_lock);
    unsigned int range = (max - min) + 1;
    unsigned int num = (unsigned int)(rand() % range) + min;
    pthread_mutex_unlock(&rand_lock);
