    for (long i = 0; i < index; ++i) {
        if (keys[i] == key) {
            return 0;
        }
    }
    return 1;
}

// Check if record value is unique in the records array
int isDuplicateRecord(record *records, long index) {
    for (long i = 0; i < index; ++i) {
        if (records[i].value == records[index].value) {
            return 1;
        }
    }
    return 0;
}

