    // Check for unique record values
    for (long i = 0; i < size; ++i) {
        for (long j = i + 1; j < size; ++j) {
            if (records[i].value == records[j].value) {
                handleError("Duplicate record value found");
            }
        }
    }

    printf("Integrity check passed.\n");
}

int main() {
