#define INITIAL_SIZE 10
#define MAX_KEY_LENGTH 50
#define RANDOM_RANGE_MAX 100

typedef struct {
    int value;
    char key[MAX_KEY_LENGTH];
    long *dataPointer;
} record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record* initializeRecords(size_t size, int (*randomNumberGenerator)(void)) {
    pthread_mutex_lock(&mutex);

    record *records = (record *)malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate records");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].value = randomNumberGenerator();
        snprintf(records[i].key, MAX_KEY_LENGTH, "Key_%zu", i);
        records[i].dataPointer = malloc(sizeof(long));
        if (!records[i].dataPointer) {
            perror("Failed to allocate data pointer");
            freeRecords(records, size);  // Free previously allocated resources
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

void freeRecords(record *records, size_t size) {
    if (records) {
        for (size_t i = 0; i < size; ++i) {
            free(records[i].dataPointer);
        }
        free(records);
    }
}

int processRecordsAndFindMax(int (*callback)(record*), int (*randomNumberGenerator)(void)) {
    pthread_mutex_lock(&mutex);

    size_t currentSize = INITIAL_SIZE;
    record *records = initializeRecords(currentSize, randomNumberGenerator);
    if (!records) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error code for failed initialization
    }

    int maxSizeValue = INT_MIN;

    while (1) {
        printf("Enter an integer value (negative to quit): ");
        char input[256];
        if (!fgets(input, sizeof(input), stdin)) {
            fprintf(stderr, "Failed to read input\n");
            break;
        }

        // Remove newline character
        input[strcspn(input, "\n")] = 0;

        int userInput;
        if (sscanf(input, "%d", &userInput) != 1 || userInput < 0) {
            printf("Invalid input. Please enter a valid integer.\n");
            continue;
        }

        // Resize array if needed
        if (records == NULL) { 
            records = initializeRecords(currentSize, randomNumberGenerator);
            if (!records) {
                fprintf(stderr, "Failed to reallocate memory\n");
                break;
            }
        }

        for (size_t i = 0; i < currentSize; ++i) {
            if (callback) {
                callback(&records[i]);
            }
            if (userInput > maxSizeValue) {
                maxSizeValue = userInput;
            }
        }

        printf("Current max value: %d\n", maxSizeValue);
    }

    freeRecords(records, currentSize);

    pthread_mutex_unlock(&mutex);
    return 0; // Success code
}

// Example random number generator function
int exampleRandomNumberGenerator(void) {
    return rand() % RANDOM_RANGE_MAX;
}

// Example callback function
int processRecordCallback(record *r) {
    printf("Processing record: Value = %d, Key = %s\n", r->value, r->key);
    return 0; // Return value indicating successful processing
}

int main() {
    srand((unsigned int)time(NULL));

    // Execute the function with a random number generator and callback
    processRecordsAndFindMax(processRecordCallback, exampleRandomNumberGenerator);

    return 0;
}
