// Define the record structure
typedef struct {
    int id;
    char key[256]; // Assuming a maximum length of 255 characters + null terminator
    long *data_ptr;
} record;

// Callback function type definition
typedef void (*callback_t)(record *);

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize records
void initialize_records(size_t size, unsigned int seed, callback_t user_callback) {
    if (size == 0 || user_callback == NULL) return;

    // Allocate and initialize offsets array
    long *offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = (long)i;
    }

    // Allocate and initialize keys array
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        keys[i] = (int)i;
    }

    // Initialize random number generator
    srand(seed);

    // Allocate and initialize records array
    record *records = malloc(sizeof(record) * size);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        // Generate a random ID within a predefined range
        int id_range_min = 1;
        int id_range_max = 100;
        records[i].id = id_range_min + rand() % (id_range_max - id_range_min + 1);

        // Initialize key with a dummy string
        snprintf(records[i].key, sizeof(records[i].key), "Key_%zu", i);

        // Allocate memory for additional data storage
        pthread_mutex_lock(&lock);
        records[i].data_ptr = malloc(sizeof(long));
        if (!records[i].data_ptr) {
            fprintf(stderr, "Failed to allocate memory for record data pointer\n");
            pthread_mutex_unlock(&lock);
            continue;
        }
        *records[i].data_ptr = 0; // Initialize with zero
        pthread_mutex_unlock(&lock);

        // Invoke the user-defined callback function
        if (user_callback) {
            user_callback(&records[i]);
        }
    }

    // Example of cleanup mechanism
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        free(records[i].data_ptr);
        pthread_mutex_unlock(&lock);
    }

    // Free all allocated memory
    free(records);
    free(keys);
    free(offsets);

    // Destroy the mutex
    pthread_mutex_destroy(&lock);
}

// Example callback function
void example_callback(record *rec) {
    printf("Callback: ID=%d, Key=%s\n", rec->id, rec->key);
}

int main() {
    size_t record_size = 10;
    unsigned int seed = 42;

    initialize_records(record_size, seed, example_callback);

    return 0;
}
```

