typedef struct {
    int fd;
    char host_name[HOST_NAME_LENGTH];
    void *metadata_buffer;
} Socket;

// User-defined callback function type
typedef void (*socket_setup_callback)(Socket*);

void configure_network_interface(int seed, socket_setup_callback user_callback) {
    // Initialize random number generator
    srand(seed);

    // Allocate and initialize ports array
    int *ports = (int *)malloc(MAX_PORTS * sizeof(int));
    for (int i = 0; i < MAX_PORTS; ++i) {
        ports[i] = rand() % 65535 + 1; // Random port between 1 and 65535
    }

    // Allocate and initialize inet_addr array
    struct in_addr *addresses = (struct in_addr *)malloc(MAX_ADDRESSES * sizeof(struct in_addr));
    for (int i = 0; i < MAX_ADDRESSES; ++i) {
        addresses[i] = ((struct in_addr){ .s_addr = htonl(rand() % 256 << 24) }); // Random IP
    }

    // Allocate and initialize socket array
    Socket *sockets = (Socket *)malloc(MAX_SOCKETS * sizeof(Socket));
    for (int i = 0; i < MAX_SOCKETS; ++i) {
        sockets[i].fd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockets[i].fd < 0) {
            perror("Failed to create socket");
            continue;
        }

        snprintf(sockets[i].host_name, HOST_NAME_LENGTH, "Host_%d", i);
        sockets[i].metadata_buffer = malloc(SOCKET_BUFFER_SIZE);
        if (!sockets[i].metadata_buffer) {
            perror("Failed to allocate metadata buffer");
            close(sockets[i].fd); // Close socket on allocation failure
            continue;
        }

        // Invoke user-defined callback for additional setup
        if (user_callback) {
            user_callback(&sockets[i]);
        }
    }

    // Error handling and cleanup mechanism
    for (int i = 0; i < MAX_SOCKETS; ++i) {
        if (sockets[i].fd >= 0) {
            close(sockets[i].fd);
        }
        if (sockets[i].metadata_buffer) {
            free(sockets[i].metadata_buffer);
        }
    }

    // Free allocated resources
    free(ports);
    free(addresses);
    free(sockets);
}
