#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "external_random_library.h" // Assume this header provides an RNG initialization and number generation

typedef struct {
    int integer_value;
    char *key;
    long *identifier;
} Record;

void freeRecords(Record **records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->key);
            free(records[i]->identifier);
            free(records[i]);
        }
    }
    free(*records);
}

void initializeRecords(int max_num_records, size_t max_total_size, unsigned int seed,
                       void (*callback)(Record *record), const char *log_level, FILE *log_file) {
    if (!external_random_init(seed)) {
        fprintf(stderr, "Failed to initialize random number generator.\n");
        return;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Record **records = NULL;
    int *keys = malloc(max_num_records * sizeof(int));
    long *offsets = malloc(max_num_records * sizeof(long));

    if (!keys || !offsets) {
        fprintf(stderr, "Memory allocation failed for keys or offsets.\n");
        free(keys);
        free(offsets);
        return;
    }

    size_t current_size = 0;
    int num_allocated = 0;

    for (int i = 0; i < max_num_records && current_size < max_total_size; ++i) {
        pthread_mutex_lock(&mutex);

        size_t record_size = sizeof(Record) + MAX_KEY_LENGTH + sizeof(long);
        if (current_size + record_size > max_total_size)
            break;

        Record *record = malloc(record_size);
        if (!record) {
            fprintf(stderr, "Memory allocation failed for record.\n");
            pthread_mutex_unlock(&mutex);
            break;
        }

        keys[i] = i;
        offsets[i] = num_allocated++;

        current_size += record_size;

        size_t key_space = MAX_KEY_LENGTH + 1; // For null-terminator
        char *key_memory = (char *)(record + 1);
        record->key = key_memory;
        snprintf(record->key, key_space, "Key_%d", i);

        long identifier_space = sizeof(long) + 10; // Allow some space for the number as string
        long *identifier_memory = (long *)((char *)key_memory + key_space);
        record->identifier = identifier_memory;
        sprintf((char *)record->identifier, "%ld", offsets[i]);

        external_random_long_t random_value = external_random_generate();
        record->integer_value = random_value % MAX_INT_VALUE;

        if (callback) {
            callback(record);
        }

        records = realloc(records, sizeof(Record*) * (num_allocated + 1));
        if (!records) {
            fprintf(stderr, "Memory allocation failed for records array.\n");
            free(record);
            pthread_mutex_unlock(&mutex);
            break;
        }
        records[num_allocated - 1] = record;

        pthread_mutex_unlock(&mutex);

        if (log_level && log_file) {
            fprintf(log_file, "Initialized Record %d: integer_value=%d, key=%s, identifier=%ld\n",
                    i, record->integer_value, record->key, *record->identifier);
        }
    }

    free(keys);
    free(offsets);

    // Cleanup
    if (records) {
        freeRecords(&records, num_allocated);
    }

    external_random_cleanup();
}

// Example callback function for processing each initialized record
void exampleCallback(Record *record) {
    printf("Processing Record: integer_value=%d, key=%s, identifier=%ld\n",
           record->integer_value, record->key, *(record->identifier));
}
