void initialize_data_structure(DataStructure *ds, size_t size, int range_min, int range_max, unsigned int seed, void (*callback)(Record*), const char *filename) {
    srand(seed);

    ds->offsets = (long *)malloc(size * sizeof(long));
    ds->keys = (int *)malloc(size * sizeof(int));
    ds->records = (Record *)malloc(size * sizeof(Record));
    ds->strings = (char **)malloc(size * sizeof(char *));

    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        ds->offsets[i] = i;
        ds->keys[i] = i;
        ds->records[i].value = external_rand(range_min, range_max);

        char buffer[20];
        snprintf(buffer, sizeof(buffer), "ID_%lu", i);
        ds->strings[i] = strdup(buffer);

        if (callback) {
            callback(&ds->records[i]);
        }
    }

    // Logging initialization
    FILE *log_file = fopen("init_log.txt", "w");
    for (size_t i = 0; i < size; ++i) {
        fprintf(log_file, "Offset: %ld, Key: %d, Record Value: %d, String: %s\n",
                ds->offsets[i], ds->keys[i], ds->records[i].value, ds->strings[i]);
    }
    fclose(log_file);

    // Serialize to file
    FILE *file = fopen(filename, "wb");
    fwrite(ds->offsets, sizeof(long), size, file);
    fwrite(ds->keys, sizeof(int), size, file);
    fwrite(ds->records, sizeof(Record), size, file);
    for (size_t i = 0; i < size; ++i) {
        size_t len = strlen(ds->strings[i]) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(ds->strings[i], sizeof(char), len, file);
    }
    fclose(file);
}

void free_data_structure(DataStructure *ds, size_t size) {
    pthread_mutex_lock(&ds->lock);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    for (size_t i = 0; i < size; ++i) {
        free(ds->strings[i]);
    }
    free(ds->strings);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

