typedef struct {
    int some_integer;
} record;

typedef void (*post_init_callback)(void *);

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    char **identifiers;
    size_t max_record_size;
    size_t max_total_size;
    unsigned int seed;
    post_init_callback callback;
} RecordManager;

int initialize_records(size_t num_records, size_t max_record_size, size_t max_total_size,
                       unsigned int seed, post_init_callback callback) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    RecordManager manager;
    manager.max_record_size = max_record_size;
    manager.max_total_size = max_total_size;
    manager.seed = seed;
    manager.callback = callback;

    // Calculate memory requirements
    size_t offset_size = num_records * sizeof(long);
    size_t key_size = num_records * sizeof(int);
    size_t record_size = num_records * sizeof(record);

    // Assume each identifier is of maximum length specified by user + 1 for null terminator
    char **identifiers = (char **)malloc(num_records * sizeof(char *));
    if (!identifiers) {
        log_error("Failed to allocate identifiers");
        return -1;
    }

    size_t total_size = offset_size + key_size + record_size;
    for (size_t i = 0; i < num_records; ++i) {
        total_size += max_record_size; // Maximum possible string size per identifier
    }

    if (total_size > manager.max_total_size) {
        log_error("Total memory required exceeds maximum allowed");
        free(identifiers);
        return -1;
    }

    // Allocate and initialize arrays
    manager.offsets = (long *)malloc(offset_size);
    manager.keys = (int *)malloc(key_size);
    manager.records = (record *)malloc(record_size);

    if (!manager.offsets || !manager.keys || !manager.records) {
        log_error("Memory allocation for base structures failed");
        free(identifiers);
        if (manager.offsets) free(manager.offsets);
        if (manager.keys) free(manager.keys);
        if (manager.records) free(manager.records);
        return -1;
    }

    srand(manager.seed);

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_records; ++i) {
        manager.offsets[i] = i * max_record_size;
        manager.keys[i] = i;

        // Initialize records with random values
        manager.records[i].some_integer = rand() % 100; // Example range [0, 99]

        // Allocate and initialize string identifiers
        char *identifier = (char *)malloc(max_record_size);
        if (!identifier) {
            log_warning("Failed to allocate identifier for record %zu", i);
            continue;
        }
        snprintf(identifier, max_record_size, "Identifier_%zu", i);
        identifiers[i] = identifier;

        // Invoke the callback function if provided
        if (manager.callback) manager.callback(&manager.records[i]);
    }
    pthread_mutex_unlock(&lock);

    manager.identifiers = identifiers;

    log_info("Initialization complete");

    return 0;
}

void cleanup_records(RecordManager *manager) {
    if (!manager) return;

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    for (size_t i = 0; i < manager->max_total_size / manager->max_record_size; ++i) {
        free(manager->identifiers[i]);
    }
    free(manager->identifiers);

    log_info("Cleanup complete");
}

// Example logging function
void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void log_warning(const char *message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

void log_info(const char *message) {
    printf("INFO: %s\n", message);
}
