#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <fcntl.h>
#include <unistd.h>
#include <yaml.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define MAX_PROCESSES 20

typedef struct {
    long timestamp;
    float temperature;
    char sensor_id[10];
} sensor_data;

sem_t sem;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int initial_value;
FILE *log_file;
char log_filename[] = "sema_log.txt";

void open_rotate_log() {
    static int rotation_counter = 0;
    char new_log_filename[30];

    snprintf(new_log_filename, sizeof(new_log_filename), "%s.%d", log_filename, rotation_counter++);
    if (rotation_counter % 5 == 0) { // Rotate every 5 files
        fclose(log_file);
        rename(new_log_filename, log_filename);
        sprintf(new_log_filename, "sema_log.%d", rotation_counter);
    }

    log_file = fopen(new_log_filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void init_semaphore_from_yaml(const char *yaml_path) {
    FILE *file = fopen(yaml_path, "r");
    yaml_parser_t parser;
    yaml_event_t event;

    if (!file) {
        perror("Failed to open YAML file");
        exit(EXIT_FAILURE);
    }

    yaml_parser_initialize(&parser);
    yaml_parser_set_input_file(&parser, file);

    while (1) {
        if (!yaml_parser_parse(&parser, &event))
            break;

        if (event.type == YAML_SCALAR_EVENT) {
            const char *value = event.data.scalar.value;

            if (strcmp(event.data.scalar.tag, "initial_value") == 0) {
                initial_value = atoi(value);
            }
        }

        yaml_event_delete(&event);
        if (event.type == YAML_STREAM_END_EVENT)
            break;
    }

    yaml_parser_delete(&parser);
    fclose(file);

    if (sem_init(&sem, 1, initial_value) != 0) {
        perror("Failed to initialize semaphore");
        exit(EXIT_FAILURE);
    }
}

void log_operation(int pid, int operation_result) {
    pthread_mutex_lock(&mutex);
    open_rotate_log();
    fprintf(log_file, "PID: %d, Semaphore State: %d, Result: %d\n", getpid(), sem_getvalue(&sem, NULL), operation_result);
    fflush(log_file);
    fclose(log_file);
    pthread_mutex_unlock(&mutex);
}

void reset_semaphore() {
    pthread_mutex_lock(&mutex);
    sem_destroy(&sem);
    sem_init(&sem, 1, initial_value);
    log_operation(getpid(), 0); // Log reset action
    pthread_mutex_unlock(&mutex);
}

int semaphore_wait(int blocking) {
    int result = -1;
    if (blocking)
        result = sem_wait(&sem);
    else
        result = sem_trywait(&sem);

    log_operation(getpid(), result);
    return result;
}

void semaphore_post() {
    sem_post(&sem);
    log_operation(getpid(), 0);
}

sensor_data* initialize_sensor_data(int num_sensors) {
    sensor_data *data = (sensor_data *)malloc(num_sensors * sizeof(sensor_data));
    if (!data) {
        perror("Failed to allocate memory for sensor data");
        exit(EXIT_FAILURE);
    }

    time_t current_time;
    float dummy_temperature = 25.0; // Example initial temperature value

    for (int i = 0; i < num_sensors; i++) {
        data[i].timestamp = (long)time(&current_time);
        data[i].temperature = dummy_temperature + ((float)rand() / RAND_MAX * 10); // Randomize temperature
        snprintf(data[i].sensor_id, sizeof(data[i].sensor_id), "Sensor_%d", i);
    }

    return data;
}

void free_sensor_data(sensor_data *data, int num_sensors) {
    if (data)
        free(data);
}

int main(int argc, char **argv) {
    const char *yaml_config = "config.yaml";

    init_semaphore_from_yaml(yaml_config);

    // Simulate semaphore operations
    semaphore_wait(1);  // Blocking wait

    sensor_data *sensors = initialize_sensor_data(MAX_PROCESSES);

    semaphore_post();

    reset_semaphore(); // Reset the semaphore state without terminating the program

    free_sensor_data(sensors, MAX_PROCESSES);

    sem_destroy(&sem);
    pthread_mutex_destroy(&mutex);

    return 0;
}
```

