#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *name;
    bool is_up;
    char **ip_addresses;
    size_t ip_count;
} IPAddressList;

typedef struct {
    int id;
    char *interface_name;
    bool is_up;
    IPAddressList ips;
} NetworkInterface;

typedef struct {
    NetworkInterface *interfaces;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} InterfaceList;

// Function prototypes
void initialize_list(InterfaceList *list, size_t initial_capacity);
bool add_interface(InterfaceList *list, int id, const char *name, bool is_up, char **ip_addresses, size_t ip_count, void (*callback)(const NetworkInterface*));
bool update_interface_state(InterfaceList *list, int id, bool is_up, char **new_ips, size_t new_ip_count);
void export_to_config(const InterfaceList *list, const char *filename);
void iterate_interfaces(const InterfaceList *list, bool reverse, void (*func)(const NetworkInterface *));
int safe_str_to_int(const char *str);

// Initialize the dynamic list
void initialize_list(InterfaceList *list, size_t initial_capacity) {
    list->interfaces = malloc(initial_capacity * sizeof(NetworkInterface));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new interface to the list
bool add_interface(InterfaceList *list, int id, const char *name, bool is_up, char **ip_addresses, size_t ip_count, void (*callback)(const NetworkInterface *)) {
    pthread_mutex_lock(&list->lock);

    // Callback before addition
    if (callback) {
        for (size_t i = 0; i < list->count; ++i) {
            callback(&list->interfaces[i]);
        }
    }

    // Check for unique ID and handle collisions
    bool id_exists = false;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->interfaces[i].id == id) {
            id_exists = true;
            break;
        }
    }

    if (id_exists) {
        pthread_mutex_unlock(&list->lock);
        return false; // ID collision
    }

    // Resize if needed
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NetworkInterface *new_interfaces = realloc(list->interfaces, new_capacity * sizeof(NetworkInterface));
        if (!new_interfaces) {
            pthread_mutex_unlock(&list->lock);
            return false; // Memory allocation failure
        }
        list->interfaces = new_interfaces;
        list->capacity = new_capacity;
    }

    // Create and add the new interface
    NetworkInterface new_interface = {id, strdup(name), is_up, {ip_addresses, ip_count}};
    list->interfaces[list->count++] = new_interface;

    // Callback after addition
    if (callback) {
        callback(&new_interface);
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Update the state of an existing interface
bool update_interface_state(InterfaceList *list, int id, bool is_up, char **new_ips, size_t new_ip_count) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->interfaces[i].id == id) {
            list->interfaces[i].is_up = is_up;
            free(list->interfaces[i].ips.ip_addresses);
            list->interfaces[i].ips.ip_count = new_ip_count;
            list->interfaces[i].ips.ip_addresses = malloc(new_ip_count * sizeof(char *));
            if (!list->interfaces[i].ips.ip_addresses) {
                pthread_mutex_unlock(&list->lock);
                return false; // Memory allocation failure
            }
            for (size_t j = 0; j < new_ip_count; ++j) {
                list->interfaces[i].ips.ip_addresses[j] = strdup(new_ips[j]);
            }
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false; // Interface not found
}

// Export the current state to a configuration file
void export_to_config(const InterfaceList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    for (size_t i = 0; i < list->count; ++i) {
        fprintf(file, "ID: %d\n", list->interfaces[i].id);
        fprintf(file, "Name: %s\n", list->interfaces[i].interface_name);
        fprintf(file, "Status: %s\n", list->interfaces[i].is_up ? "UP" : "DOWN");
        for (size_t j = 0; j < list->interfaces[i].ips.ip_count; ++j) {
            fprintf(file, "IP Address: %s\n", list->interfaces[i].ips.ip_addresses[j]);
        }
    }

    fclose(file);
}

// Iterate over interfaces
void iterate_interfaces(const InterfaceList *list, bool reverse, void (*func)(const NetworkInterface *)) {
    size_t start = 0;
    size_t end = list->count;
    if (reverse) {
        start = list->count - 1;
        while (end--) { func(&list->interfaces[start--]); }
    } else {
        for (; start < end; ++start) {
            func(&list->interfaces[start]);
        }
    }
}

// Safely convert string to integer
int safe_str_to_int(const char *str) {
    char *endptr;
    int value = strtol(str, &endptr, 10);
    if (*endptr != '\0' || endptr == str) {
        return -1; // Conversion failed
    }
    return value;
}

// Example callback function
void example_callback(const NetworkInterface *interface) {
    printf("Callback: Processing interface ID %d\n", interface->id);
}
