    return *(long *)buf;
}

void initialize_collection(Collection *collection, size_t num_records, void (*callback)(Collection *, size_t), unsigned long seed) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->num_records = num_records;
    collection->offsets = malloc(num_records * sizeof(long));
    collection->keys = malloc(num_records * sizeof(int));
    collection->values = malloc(num_records * sizeof(double));
    collection->records = malloc(num_records * sizeof(Record));
    collection->metadata = malloc(num_records * sizeof(char *));

    if (!collection->offsets || !collection->keys || !collection->values || !collection->records || !collection->metadata) {
        handle_error("Memory allocation failed");
    }

    srand(seed);
    for (size_t i = 0; i < num_records; ++i) {
        collection->offsets[i] = i;
        collection->keys[i] = i;
        collection->values[i] = (double)i;

        collection->records[i].value = rand() % 100;

        char *meta = malloc(METADATA_MAX_LENGTH);
        if (!meta) {
            handle_error("Metadata allocation failed");
        }
        snprintf(meta, METADATA_MAX_LENGTH, "Key: %d, Value: %.2f, ID: %ld", collection->keys[i], collection->values[i], generate_unique_id());
        collection->metadata[i] = meta;
    }

    if (callback) {
        for (size_t i = 0; i < num_records; ++i) {
            callback(collection, i);
        }
    }
}

void free_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->offsets);
    free(collection->keys);
    free(collection->values);
    for (size_t i = 0; i < collection->num_records; ++i) {
        free(collection->metadata[i]);
    }
    free(collection->records);
    free(collection->metadata);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

void log_operation(const char *operation, size_t index) {
    printf("Operation: %s on index: %zu\n", operation, index);
}

// Example callback function
void example_callback(Collection *collection, size_t index) {
    log_operation("Callback invoked", index);
    // Perform additional validation or transformation here
}

int main() {
    Collection collection;
    initialize_collection(&collection, RECORD_SIZE, example_callback, 12345UL);

    free_collection(&collection);
    return 0;
}
```

