#define INITIAL_HASH_TABLE_SIZE 101

typedef struct {
    long offset;
    int key;
    double value;
    unsigned int ref_count;
} record;

typedef struct hash_table_entry {
    int key;
    struct hash_table_entry *next;
} hash_table_entry;

typedef struct {
    record **records;
    size_t num_records;
    hash_table_entry **hash_table;
    size_t hash_table_size;
    double random_value_min, random_value_max;
    unsigned int access_threshold;
    size_t memory_limit;
    pthread_mutex_t lock;
} record_manager;

unsigned int simple_hash(int key, size_t table_size) {
    return (unsigned int)(key % table_size);
}

hash_table_entry *find_in_hash_table(hash_table_entry **table, int key, size_t table_size) {
    unsigned int index = simple_hash(key, table_size);
    hash_table_entry *entry = table[index];
    while (entry != NULL) {
        if (entry->key == key) {
            return entry;
        }
        entry = entry->next;
    }
    return NULL;
}

void insert_into_hash_table(hash_table_entry **table, int key, size_t table_size) {
    unsigned int index = simple_hash(key, table_size);
    hash_table_entry *new_entry = malloc(sizeof(hash_table_entry));
    if (!new_entry) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_entry->key = key;
    new_entry->next = table[index];
    table[index] = new_entry;
}

void free_hash_table(hash_table_entry **table, size_t table_size) {
    for (size_t i = 0; i < table_size; ++i) {
        hash_table_entry *entry = table[i];
        while (entry != NULL) {
            hash_table_entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
}

double generate_random_value(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

void garbage_collect(record_manager *manager);

record_manager* create_record_manager(
    size_t initial_num_records,
    double random_value_min,
    double random_value_max,
    unsigned int access_threshold,
    size_t memory_limit
) {
