    if (!manager) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->records = calloc(initial_num_records, sizeof(record *));
    if (!manager->records) {
        free(manager);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->num_records = initial_num_records;

    manager->hash_table_size = INITIAL_HASH_TABLE_SIZE;
    manager->hash_table = calloc(manager->hash_table_size, sizeof(hash_table_entry *));
    if (!manager->hash_table) {
        free(manager->records);
        free(manager);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    manager->random_value_min = random_value_min;
    manager->random_value_max = random_value_max;
    manager->access_threshold = access_threshold;
    manager->memory_limit = memory_limit;

    srand(time(NULL));

    return manager;
}

void destroy_record_manager(record_manager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->num_records; ++i) {
            if (manager->records[i]) {
                free(manager->records[i]);
            }
        }
        free(manager->records);

        free_hash_table(manager->hash_table, manager->hash_table_size);
        free(manager->hash_table);

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

record* add_record(record_manager *manager, long offset, int key) {
    if (pthread_mutex_lock(&manager->lock)) {
        fprintf(stderr, "Mutex lock failed\n");
        exit(EXIT_FAILURE);
    }

    hash_table_entry *entry = find_in_hash_table(manager->hash_table, key, manager->hash_table_size);
    if (entry != NULL) {
        pthread_mutex_unlock(&manager->lock);
        return NULL; // Key already exists
    }

    if ((manager->num_records * sizeof(record *)) + sizeof(record) > manager->memory_limit) {
        garbage_collect(manager); // Trigger GC before adding new record
    }

    if (manager->num_records >= sizeof(manager->records) / sizeof(record *)) {
        size_t new_size = manager->num_records * 2;
        record **new_records = realloc(manager->records, new_size * sizeof(record *));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memset(new_records + manager->num_records, 0, (new_size - manager->num_records) * sizeof(record *));
        manager->records = new_records;
    }

    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = generate_random_value(manager->random_value_min, manager->random_value_max);
    new_record->ref_count = 0;

    manager->records[manager->num_records++] = new_record;
    insert_into_hash_table(manager->hash_table, key, manager->hash_table_size);

    pthread_mutex_unlock(&manager->lock);
    return new_record;
}

void access_record(record_manager *manager, long offset, int key) {
    if (pthread_mutex_lock(&manager->lock)) {
        fprintf(stderr, "Mutex lock failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < manager->num_records; ++i) {
        record *rec = manager->records[i];
        if (rec && rec->offset == offset && rec->key == key) {
            rec->ref_count++;
            if (rec->ref_count > manager->access_threshold) {
                fprintf(stderr, "Warning: Record accessed more than threshold\n");
                rec->ref_count *= 0.9; // Reduce access count by 10%
            }
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void garbage_collect(record_manager *manager) {
    size_t current_memory_usage = manager->num_records * sizeof(record *);
    for (size_t i = 0; i < manager->num_records; ++i) {
        if (manager->records[i]) {
            current_memory_usage += sizeof(record);
        }
    }

    if (current_memory_usage > manager->memory_limit) {
        // Sort records by ref_count
        qsort(manager->records, manager->num_records, sizeof(record *), 
              [](const void *a, const void *b) {
                  return ((record *)*b)->ref_count - ((record *)*a)->ref_count;
              });

        while (current_memory_usage > manager->memory_limit && manager->num_records > 0) {
            record *rec_to_free = manager->records[manager->num_records - 1];
            if (rec_to_free) {
                free(rec_to_free);
                manager->records[--manager->num_records] = NULL;
                current_memory_usage -= sizeof(record);
            }
        }

        // Compact the records array to remove NULL entries
        record **compact_array = malloc(manager->num_records * sizeof(record *));
        if (!compact_array) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        size_t j = 0;
        for (size_t i = 0; i < manager->num_records; ++i) {
            if (manager->records[i]) {
                compact_array[j++] = manager->records[i];
            }
        }

        free(manager->records);
        manager->records = compact_array;
    }
}
