#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Task SubTask;

typedef struct {
    unsigned long id;
    char *name;
    unsigned long *dependencies; // array of IDs
    size_t dependency_count;
    SubTask **sub_tasks;         // array of pointers to sub-tasks
    size_t sub_task_count;
} Task;

struct Task {
    unsigned long id;
    char *name;
    unsigned long *dependencies;
    size_t dependency_count;
    SubTask **sub_tasks;
    size_t sub_task_count;
    pthread_mutex_t lock;        // For fine-grained locking
};

typedef struct Node {
    Task *task;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_rwlock_t rwlock;
    unsigned long next_id;
    pthread_mutex_t id_lock;
    void (*pre_add_callback)(Task *);
} TaskList;

TaskList* initialize_task_list(void (*callback)(Task *)) {
    TaskList *list = malloc(sizeof(TaskList));
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    pthread_mutex_init(&list->id_lock, NULL);
    list->next_id = 1; // Start ID from 1
    list->pre_add_callback = callback;
    return list;
}

unsigned long generate_unique_id(TaskList *list) {
    unsigned long id;
    pthread_mutex_lock(&list->id_lock);
    id = list->next_id++;
    pthread_mutex_unlock(&list->id_lock);
    return id;
}

void add_task(TaskList *list, Task *new_task) {
    if (list->pre_add_callback) {
        list->pre_add_callback(new_task);
    }

    new_task->dependencies = malloc(new_task->dependency_count * sizeof(unsigned long));
    memcpy(new_task->dependencies, new_task->dependencies, new_task->dependency_count * sizeof(unsigned long));

    new_task->sub_tasks = malloc(new_task->sub_task_count * sizeof(SubTask*));
    for (size_t i = 0; i < new_task->sub_task_count; ++i) {
        SubTask *sub_task_copy = malloc(sizeof(SubTask));
        memcpy(sub_task_copy, new_task->sub_tasks[i], sizeof(SubTask));
        sub_task_copy->lock = PTHREAD_MUTEX_INITIALIZER;
        new_task->sub_tasks[i] = sub_task_copy;
    }

    pthread_rwlock_wrlock(&list->rwlock);
    Node *new_node = malloc(sizeof(Node));
    new_node->task = new_task;
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->rwlock);
}

Task* create_task(const char *name, unsigned long *dependencies, size_t dependency_count,
                  SubTask **sub_tasks, size_t sub_task_count) {
    Task *task = malloc(sizeof(Task));
    task->id = generate_unique_id(NULL); // Pass the list if needed
    task->name = strdup(name);
    task->dependency_count = dependency_count;
    task->dependencies = dependencies;
    task->sub_task_count = sub_task_count;
    task->sub_tasks = sub_tasks;
    pthread_mutex_init(&task->lock, NULL);
    return task;
}

void free_task(Task *task) {
    if (task) {
        pthread_mutex_destroy(&task->lock);
        free(task->name);
        free(task->dependencies);
        for (size_t i = 0; i < task->sub_task_count; ++i) {
            free(task->sub_tasks[i]);
        }
        free(task->sub_tasks);
        free(task);
    }
}

void destroy_task_list(TaskList *list) {
    pthread_rwlock_wrlock(&list->rwlock);
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free_task(current->task);
        free(current);
        current = next;
    }
    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
    pthread_mutex_destroy(&list->id_lock);
    free(list);
}

void serialize_task_list(TaskList *list, const char *filename) {
    // Placeholder for serialization logic
}

void deserialize_task_list(TaskList *list, const char *filename) {
    // Placeholder for deserialization logic
}

// Example callback function
void example_callback(Task *task) {
    printf("Initializing task: %s\n", task->name);
}

int main() {
    TaskList *list = initialize_task_list(example_callback);

    unsigned long dependencies[] = {1, 2};
    SubTask *sub_tasks = NULL;
    Task *task = create_task("Main Task", dependencies, 2, sub_tasks, 0);

    add_task(list, task);

    destroy_task_list(list);
    return 0;
}
```

