record* allocate_and_initialize_records(size_t count, int min, int max) {
    record *records = malloc(count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value = generate_random_int(min, max);
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return records;
}

