#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void manage_memory(int num_rounds, size_t *offset_sizes, int *key_ranges, size_t *record_sizes) {
    long **offset_arrays = NULL;
    int **key_arrays = NULL;
    record ***record_struct_arrays = NULL;

    for (int round = 0; round < num_rounds; ++round) {
        // Free previously allocated memory
        if (offset_arrays && offset_arrays[round]) {
            free(offset_arrays[round]);
        }
        if (key_arrays && key_arrays[round]) {
            free(key_arrays[round]);
        }
        if (record_struct_arrays && record_struct_arrays[round]) {
            for (size_t i = 0; i < record_sizes[round]; ++i) {
                free(record_struct_arrays[round][i]);
            }
            free(record_struct_arrays[round]);
        }

        // Allocate new memory
        offset_arrays = realloc(offset_arrays, sizeof(long*) * (round + 1));
        key_arrays = realloc(key_arrays, sizeof(int*) * (round + 1));
        record_struct_arrays = realloc(record_struct_arrays, sizeof(record**) * (round + 1));

        size_t offset_size = offset_sizes[round];
        int key_range = key_ranges[round];
        size_t record_size = record_sizes[round];

        offset_arrays[round] = malloc(sizeof(long) * offset_size);
        key_arrays[round] = malloc(sizeof(int) * offset_size);
        record_struct_arrays[round] = malloc(sizeof(record*) * record_size);

        // Initialize arrays with random values
        srand(time(NULL));
        for (size_t i = 0; i < offset_size; ++i) {
            offset_arrays[round][i] = rand() % 100000;
            key_arrays[round][i] = rand() % key_range;
        }

        for (size_t j = 0; j < record_size; ++j) {
            record_struct_arrays[round][j] = malloc(sizeof(record));
            record_struct_arrays[round][j]->value = rand() % 100000;
        }
    }

    // Free all allocated memory after rounds
    for (int round = 0; round < num_rounds; ++round) {
        free(offset_arrays[round]);
        free(key_arrays[round]);
        if (record_struct_arrays && record_struct_arrays[round]) {
            for (size_t i = 0; i < record_sizes[round]; ++i) {
                free(record_struct_arrays[round][i]);
            }
            free(record_struct_arrays[round]);
        }
    }

    free(offset_arrays);
    free(key_arrays);
    free(record_struct_arrays);
}

int main() {
    size_t offset_sizes[] = {100, 200};
    int key_ranges[] = {50, 75};
    size_t record_sizes[] = {10, 20};

    manage_memory(2, offset_sizes, key_ranges, record_sizes);

    return 0;
}
