using Microsoft.AspNetCore.Mvc;
using System;
using System.IO;
using System.Linq;
using System.Xml.XPath;

[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly IResourceService _resourceService; // Assume this service handles resource storage

    public ResourceController(IResourceService resourceService)
    {
        _resourceService = resourceService;
    }

    [HttpPut("{id}")]
    public IActionResult UpdateResourceById(string id, [FromBody] ResourceUpdateModel updateData)
    {
        try
        {
            var existingResource = _resourceService.Get(id);

            if (existingResource == null)
                return NotFound($"Resource with ID {id} not found.");

            ValidateSingleElement(updateData.XmlContent, "/Root/Element"); // Example XPath

            _resourceService.Update(id, updateData);

            return Ok(existingResource);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(ex.Message);
        }
        catch (Exception ex)
        {
            return StatusCode(500, "An error occurred while updating the resource.");
        }
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteResourceById(string id)
    {
        try
        {
            var existingResource = _resourceService.Get(id);

            if (existingResource == null)
                return NotFound($"Resource with ID {id} not found.");

            _resourceService.Delete(id);

            return Ok(new Resource()); // Return new resource object with default values
        }
        catch (Exception ex)
        {
            return StatusCode(500, "An error occurred while deleting the resource.");
        }
    }

    private void ValidateSingleElement(string xmlContent, string xPathExpression)
    {
        var document = new XPathDocument(new StringReader(xmlContent));
        var navigator = document.CreateNavigator();

        var nodes = navigator.Select(xPathExpression).Cast<XPathNavigator>().ToList();

        if (nodes.Count != 1)
            throw new InvalidOperationException("Expected exactly one matching XML element.");
    }

    public static void CreateDirectoryWithEnvVar()
    {
        string directoryPath = Environment.GetEnvironmentVariable("DIRECTORY_PATH");

        if (!string.IsNullOrEmpty(directoryPath) && Directory.Exists(directoryPath))
            return;

        if (string.IsNullOrEmpty(directoryPath) || !Directory.Exists(directoryPath))
        {
            try
            {
                directoryPath ??= Path.Combine(Environment.CurrentDirectory, "NewDirectory");

                if (!Directory.Exists(directoryPath))
                    Directory.CreateDirectory(directoryPath);

                Environment.SetEnvironmentVariable("DIRECTORY_PATH", directoryPath);
            }
            catch (IOException)
            {
                // Handle IO exception for directory creation gracefully
                Console.WriteLine("The directory already exists.");
            }
        }
    }
}

public class Resource
{
    public string Id { get; set; }
    public string Name { get; set; }
    public string XmlContent { get; set; } // Assuming XML content is a property of the resource

    public Resource()
    {
        // Default constructor with default values
    }
}

public class ResourceUpdateModel
{
    public string Id { get; set; }
    public string Name { get; set; }
    public string XmlContent { get; set; }
}

// Mock interface for demonstration purposes
public interface IResourceService
{
    Resource Get(string id);
    void Update(string id, ResourceUpdateModel updateData);
    void Delete(string id);
}
```

