using System;

public class RandomValueGenerator {
    private float minValue, maxValue;
    private static readonly object lockObject = new object();

    public RandomValueGenerator(float min, float max) {
        if (min >= max) {
            minValue = 0;
            maxValue = 100;
        } else {
            minValue = min;
            maxValue = max;
        }
    }

    public float GenerateRandomFloat(bool inclusiveLowerBound, bool inclusiveUpperBound) {
        lock (lockObject) {
            Random random = new Random();
            double range = maxValue - minValue;
            if (!inclusiveLowerBound) minValue += 1.0f / ((double)(int.MaxValue));
            if (!inclusiveUpperBound) maxValue -= 1.0f / ((double)(int.MaxValue));
            return (float)(minValue + range * random.NextDouble());
        }
    }

    public float RoundToTwoDecimalPlaces(float value) {
        lock (lockObject) {
            return Math.Round(value, 2);
        }
    }

    public int GenerateRandomInteger() {
        lock (lockObject) {
            Random random = new Random();
            return random.Next((int)Math.Floor(minValue), (int)Math.Ceiling(maxValue));
        }
    }

    public float CalculateMidpoint() {
        lock (lockObject) {
            return (minValue + maxValue) / 2.0f;
        }
    }

    public bool IsWithinBounds(float value) {
        lock (lockObject) {
            return value >= minValue && value <= maxValue;
        }
    }
}
)";

