#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Record structure definition
typedef struct {
    int value;
    char *key;
    long *longPtr;
} Record;

// Function prototype for secure random number generation check
int is_secure_random_library_available();

// Callback function type
typedef void (*RecordCallback)(Record*);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void setup_directory_and_records(size_t offsets_size, size_t keys_size, size_t records_size,
                                 RecordCallback callback) {
    // Check if secure random number library is available
    if (!is_secure_random_library_available()) {
        fprintf(stderr, "Secure random number generation library not available.\n");
        return;
    }

    // Lock for thread safety during initialization
    pthread_mutex_lock(&mutex);

    // Environment variable check and directory setup
    char *dir_path = getenv("MY_DIRECTORY_PATH");
    if (dir_path == NULL) {
        dir_path = "my_new_directory";
        mkdir(dir_path, 0755);
        setenv("MY_DIRECTORY_PATH", dir_path, 1);
    }

    // Initialize offset array
    long *offsets = malloc(offsets_size * sizeof(long));
    int *keys = malloc(keys_size * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation for offsets or keys failed.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Fill offset array with sequential numbers
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }

    // Fill key array with sequential numbers
    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = i;
    }

    // Initialize records array
    Record *records = malloc(records_size * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Seed random number generator
    srand(time(NULL));

    for (size_t i = 0; i < records_size; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
        records[i].key = malloc(20 * sizeof(char)); // Assume key length of 20

        if (records[i].key == NULL) {
            fprintf(stderr, "Memory allocation for record key failed.\n");
            break;
        }

        snprintf(records[i].key, 20, "Key_%zu", i); // Fill with a sample key string
        records[i].longPtr = malloc(sizeof(long));

        if (records[i].longPtr == NULL) {
            fprintf(stderr, "Memory allocation for record long pointer failed.\n");
            free(records[i].key);
            break;
        }
    }

    // Process each record using the callback function
    if (callback != NULL && records != NULL) {
        for (size_t i = 0; i < records_size; ++i) {
            callback(&records[i]);
        }
    }

    // Cleanup memory
    free(offsets);
    free(keys);

    for (size_t i = 0; i < records_size; ++i) {
        if (records[i].key != NULL) {
            free(records[i].key);
        }
        if (records[i].longPtr != NULL) {
            free(records[i].longPtr);
        }
    }

    free(records);

    // Unlock mutex
    pthread_mutex_unlock(&mutex);
}

