['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "email_validator.h"  // Assume an external library

#define INITIAL_CAPACITY 100
#define USER_ID_MAX_LENGTH 64
#define USERNAME_MAX_LENGTH 32

typedef struct {
    char user_id[USER_ID_MAX_LENGTH];
    char username[USERNAME_MAX_LENGTH];
    int creation_timestamp;
    int active_status;  // Using int for boolean: 0 (false), 1 (true)
    char **emails;
    size_t email_count;
} UserAccount;

typedef struct {
    UserAccount *accounts;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
    void (*pre_add_callback)(UserAccount*);
    void (*post_add_callback)(UserAccount*);
} AccountRegistry;

// Function prototypes
void init_registry(AccountRegistry* registry, 
                   void (*pre_add)(UserAccount*), 
                   void (*post_add)(UserAccount*));
int add_account(AccountRegistry* registry, UserAccount account);
int update_account_status(AccountRegistry* registry, const char* user_id, int active_status);
int update_email_list(AccountRegistry* registry, const char* user_id, const char** new_emails, size_t email_count);
void iterate_accounts(const AccountRegistry* registry, void (*callback)(const UserAccount*));
void export_registry_state(const AccountRegistry* registry, const char* filename);
int import_from_csv(AccountRegistry* registry, const char* filename);

// Implementations

void init_registry(AccountRegistry* registry, 
                   void (*pre_add)(UserAccount*), 
                   void (*post_add)(UserAccount*)) {
    registry->accounts = malloc(INITIAL_CAPACITY * sizeof(UserAccount));
    if (!registry->accounts) exit(EXIT_FAILURE);
    registry->capacity = INITIAL_CAPACITY;
    registry->size = 0;
    pthread_rwlock_init(&registry->lock, NULL);
    registry->pre_add_callback = pre_add;
    registry->post_add_callback = post_add;
}

int add_account(AccountRegistry* registry, UserAccount account) {
    pthread_rwlock_wrlock(&registry->lock);

    // Check for duplicate username
    for (size_t i = 0; i < registry->size; ++i) {
        if (strcmp(registry->accounts[i].username, account.username) == 0) {
            pthread_rwlock_unlock(&registry->lock);
            return -1; // Duplicate username
        }
    }

    // Trigger pre-add callback
    if (registry->pre_add_callback) registry->pre_add_callback(&account);

    // Ensure capacity
    if (registry->size >= registry->capacity) {
        size_t new_capacity = registry->capacity * 2;
        UserAccount* temp = realloc(registry->accounts, new_capacity * sizeof(UserAccount));
        if (!temp) {
            pthread_rwlock_unlock(&registry->lock);
            return -2; // Out of memory
        }
        registry->accounts = temp;
        registry->capacity = new_capacity;
    }

    // Add account
    memcpy(&registry->accounts[registry->size], &account, sizeof(UserAccount));
    registry->size++;

    // Trigger post-add callback
    if (registry->post_add_callback) registry->post_add_callback(&account);

    pthread_rwlock_unlock(&registry->lock);
    return 0; // Success
}

int update_account_status(AccountRegistry* registry, const char* user_id, int active_status) {
    pthread_rwlock_wrlock(&registry->lock);

    for (size_t i = 0; i < registry->size; ++i) {
        if (strcmp(registry->accounts[i].user_id, user_id) == 0) {
            registry->accounts[i].active_status = active_status;
            pthread_rwlock_unlock(&registry->lock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&registry->lock);
    return -1; // User not found
}

int update_email_list(AccountRegistry* registry, const char* user_id, const char** new_emails, size_t email_count) {
    pthread_rwlock_wrlock(&registry->lock);

    for (size_t i = 0; i < registry->size; ++i) {
        if (strcmp(registry->accounts[i].user_id, user_id) == 0) {
            // Free existing emails
            for (size_t j = 0; j < registry->accounts[i].email_count; ++j)
                free(registry->accounts[i].emails[j]);
            free(registry->accounts[i].emails);

            // Allocate new emails
            registry->accounts[i].emails = malloc(email_count * sizeof(char*));
            if (!registry->accounts[i].emails) {
                pthread_rwlock_unlock(&registry->lock);
                return -2; // Out of memory
            }

            for (size_t j = 0; j < email_count; ++j) {
                registry->accounts[i].emails[j] = strdup(new_emails[j]);
                if (!registry->accounts[i].emails[j]) {
                    // Cleanup in case of failure
                    for (size_t k = 0; k < j; ++k)
                        free(registry->accounts[i].emails[k]);
                    free(registry->accounts[i].emails);
                    pthread_rwlock_unlock(&registry->lock);
                    return -2; // Out of memory
                }
            }

            registry->accounts[i].email_count = email_count;
            pthread_rwlock_unlock(&registry->lock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&registry->lock);
    return -1; // User not found
}

void iterate_accounts(const AccountRegistry* registry, void (*callback)(const UserAccount*)) {
    for (size_t i = 0; i < registry->size; ++i) {
        callback(&registry->accounts[i]);
    }
}

void export_registry_state(const AccountRegistry* registry, const char* filename) {
    FILE *file = fopen(filename, "w");
    if (!file) exit(EXIT_FAILURE);

    for (size_t i = 0; i < registry->size; ++i) {
        fprintf(file, "%s,%s,%d,%d,", 
                registry->accounts[i].user_id,
                registry->accounts[i].username,
                registry->accounts[i].creation_timestamp,
                registry->accounts[i].active_status);
        for (size_t j = 0; j < registry->accounts[i].email_count; ++j) {
            fprintf(file, "%s", registry->accounts[i].emails[j]);
            if (j < registry->accounts[i].email_count - 1)
                fputc(',', file);
        }
        fputc('\n', file);
    }

    fclose(file);
}

int import_from_csv(AccountRegistry* registry, const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1; // File open error

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char user_id[USER_ID_MAX_LENGTH], username[USERNAME_MAX_LENGTH], email[256];
        int timestamp, active_status;
        size_t email_count = 0;

        if (sscanf(line, "%[^,],%[^,],%d,%d", 
                   user_id, username, &timestamp, &active_status) != 4)
            continue; // Skip malformed lines

        const char* tmp_line = strchr(line, ',') + 1;
        while (sscanf(tmp_line, "%[^,]", email)) {
            email_count++;
            tmp_line = strchr(tmp_line, ',');
            if (tmp_line) tmp_line += 1;
        }

        UserAccount account = {0};
        strncpy(account.user_id, user_id, USER_ID_MAX_LENGTH);
        strncpy(account.username, username, USERNAME_MAX_LENGTH);
        account.creation_timestamp = timestamp;
        account.active_status = active_status;

        account.emails = malloc(email_count * sizeof(char*));
        if (!account.emails) {
            fclose(file);
            return -2; // Out of memory
        }

        tmp_line = strchr(line, ',') + 1;
        for (size_t i = 0; i < email_count; ++i) {
            sscanf(tmp_line, "%[^,]", email);
            account.emails[i] = strdup(email);
            if (!account.emails[i]) {
                // Cleanup in case of failure
                for (size_t j = 0; j < i; ++j)
                    free(account.emails[j]);
                free(account.emails);
                fclose(file);
                return -2; // Out of memory
            }
            tmp_line = strchr(tmp_line, ',');
            if (tmp_line) tmp_line += 1;
        }

        account.email_count = email_count;

        int result = add_account(registry, account);
        for (size_t i = 0; i < email_count; ++i)
            free(account.emails[i]);
        free(account.emails);

        if (result != 0) {
            fclose(file);
            return result;
        }
    }

    fclose(file);
    return 0; // Success
}
