typedef struct {
    Account *accounts;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Registry;

void before_add_callback(Account *account);
void after_add_callback(Account *account);

Registry* initialize_registry() {
    Registry *registry = malloc(sizeof(Registry));
    if (!registry) return NULL;

    registry->capacity = INITIAL_CAPACITY;
    registry->size = 0;
    registry->accounts = calloc(registry->capacity, sizeof(Account));

    pthread_mutex_init(&registry->lock, NULL);
    return registry;
}

int add_account(Registry *registry, const char *username, int active_status, const char *email) {
    if (!registry || !username) return -1;

    pthread_mutex_lock(&registry->lock);

    // Ensure unique usernames and check capacity
    for (size_t i = 0; i < registry->size; ++i) {
        if (strcmp(registry->accounts[i].username, username) == 0) {
            printf("Username already exists.\n");
            pthread_mutex_unlock(&registry->lock);
            return -2;
        }
    }

    if (registry->size >= registry->capacity) {
        size_t new_capacity = registry->capacity * 2;
        Account *new_accounts = realloc(registry->accounts, new_capacity * sizeof(Account));

        if (!new_accounts) {
            printf("Allocation failed.\n");
            pthread_mutex_unlock(&registry->lock);
            return -3;
        }

        registry->accounts = new_accounts;
        registry->capacity = new_capacity;
    }

    Account *account = &registry->accounts[registry->size++];
    strncpy(account->username, username, sizeof(account->username) - 1);

    // Simulate email validation and normalization
    strcpy(account->email_list, email); // Simplified

    account->active_status = active_status;
    account->user_id = registry->size; // Simple user ID assignment

    before_add_callback(account);
    after_add_callback(account);

    pthread_mutex_unlock(&registry->lock);
    return 0;
}

void update_account(Registry *registry, int user_id, int new_active_status) {
    if (!registry) return;

    pthread_mutex_lock(&registry->lock);

    for (size_t i = 0; i < registry->size; ++i) {
        if (registry->accounts[i].user_id == user_id) {
            registry->accounts[i].active_status = new_active_status;
            break;
        }
    }

    pthread_mutex_unlock(&registry->lock);
}

void free_registry(Registry *registry) {
    if (!registry) return;

    free(registry->accounts);
    pthread_mutex_destroy(&registry->lock);
    free(registry);
}

void before_add_callback(Account *account) {
    // Custom logic before adding an account
}

void after_add_callback(Account *account) {
    // Custom logic after adding an account
}

// Example iteration function (forward)
void iterate_accounts(Registry *registry, int (*filter)(const Account*)) {
    if (!registry || !filter) return;

    pthread_mutex_lock(&registry->lock);

    for (size_t i = 0; i < registry->size; ++i) {
        if (filter(&registry->accounts[i])) {
            printf("User ID: %d, Username: %s\n", registry->accounts[i].user_id, registry->accounts[i].username);
        }
    }

    pthread_mutex_unlock(&registry->lock);
}

int is_active(const Account *account) {
    return account->active_status == 1;
}

int main() {
    Registry *registry = initialize_registry();

    add_account(registry, "user1", 1, "user1@example.com");
    add_account(registry, "user2", 0, "user2@example.com");

    update_account(registry, 1, 0);

    iterate_accounts(registry, is_active);

    free_registry(registry);
    return 0;
}
