#include <string.h>
#include <pthread.h>

// Assume this is provided by an external library for better randomness
extern void set_seed(unsigned int seed);
extern double random_double(double min, double max);

typedef struct {
    double value;
    char identifier[20];
    double *ptrValue;
    size_t index;
} dataEntry;

typedef void (*processCallback)(dataEntry*);

void freeMemory(dataEntry **entries, size_t numEntries) {
    for (size_t i = 0; i < numEntries; ++i) {
        if (entries[i]->ptrValue != NULL) {
            free(entries[i]->ptrValue);
        }
    }
    free(*entries);
}

double findMax(double *array, size_t size) {
    double max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void processAndAnalyzeData(unsigned int seed, processCallback callback) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Set the random number generator seed
    set_seed(seed);

    size_t numEntries = 10; // Example size
    double *values = malloc(numEntries * sizeof(double));
    char **identifiers = malloc(numEntries * sizeof(char*));

    if (!values || !identifiers) {
        fprintf(stderr, "Memory allocation failed\n");
        free(values);
        free(identifiers);
        return;
    }

    // Initialize values and identifiers
    for (size_t i = 0; i < numEntries; ++i) {
        values[i] = (double)i + 1.0;
        identifiers[i] = malloc(20 * sizeof(char));
        if (!identifiers[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            free(values);
            for (size_t j = 0; j < i; ++j) {
                free(identifiers[j]);
            }
            free(identifiers);
            return;
        }
        snprintf(identifiers[i], 20, "ID_%zu", i + 1);
    }

    dataEntry *entries = malloc(numEntries * sizeof(dataEntry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        free(values);
        for (size_t i = 0; i < numEntries; ++i) {
            free(identifiers[i]);
        }
        free(identifiers);
        return;
    }

    // Initialize entries
    for (size_t i = 0; i < numEntries; ++i) {
        pthread_mutex_lock(&mutex);
        entries[i].value = random_double(0.0, 100.0);
        snprintf(entries[i].identifier, sizeof(entries[i].identifier), "%s", identifiers[i]);
        entries[i].ptrValue = malloc(sizeof(double));
        if (!entries[i].ptrValue) {
            fprintf(stderr, "Memory allocation failed\n");
            freeMemory(&entries, numEntries);
            pthread_mutex_unlock(&mutex);
            return;
        }
        *(entries[i].ptrValue) = entries[i].value;
        entries[i].index = i;
        pthread_mutex_unlock(&mutex);

        if (callback != NULL) {
            callback(&entries[i]);
        }
    }

    // Read floating-point numbers from standard input
    double *inputNumbers = malloc(10 * sizeof(double));
    size_t capacity = 10, count = 0;

    while (1) {
        printf("Enter a number (-1.0 to finish): ");
        double num;
        if (scanf("%lf", &num) != 1 || num == -1.0) break;

        if (count >= capacity) {
            capacity *= 2;
            inputNumbers = realloc(inputNumbers, capacity * sizeof(double));
            if (!inputNumbers) {
                fprintf(stderr, "Memory allocation failed\n");
                freeMemory(&entries, numEntries);
                free(values);
                for (size_t i = 0; i < numEntries; ++i) {
                    free(identifiers[i]);
                }
                free(identifiers);
                return;
            }
        }

        inputNumbers[count++] = num;
    }

    double maxNumber = findMax(inputNumbers, count);
    printf("The largest number is: %.2f\n", maxNumber);

    // Free allocated memory
    freeMemory(&entries, numEntries);
    free(values);
    for (size_t i = 0; i < numEntries; ++i) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(inputNumbers);
    pthread_mutex_destroy(&mutex);
}
