// Define the structure for a record
typedef struct {
    int key;
    char *identifier;
    long offset;
    float value;
} Record;

// Function prototype
void initializeRecords(size_t numRecords, size_t maxTotalSize, unsigned int seed,
                       MemoryPool *pool, void (*callback)(Record *), 
                       size_t maxProcess = SIZE_MAX);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeRecords(size_t numRecords, size_t maxTotalSize, unsigned int seed,
                       MemoryPool *pool, void (*callback)(Record *), 
                       size_t maxProcess) {
    if (numRecords > maxProcess) {
        numRecords = maxProcess;
    }

    // Initialize random number generator
    RandomLibContext *randCtx = random_lib_init(seed);

    // Arrays for keys, offsets, and values
    int *keys = malloc(numRecords * sizeof(int));
    long *offsets = malloc(numRecords * sizeof(long));
    float *values = malloc(numRecords * sizeof(float));

    if (!keys || !offsets || !values) {
        free(keys);
        free(offsets);
        free(values);
        fprintf(stderr, "Memory allocation failed for arrays\n");
        return;
    }

    // Initialize keys, offsets, and values
    for (size_t i = 0; i < numRecords; ++i) {
        keys[i] = i;
        offsets[i] = i * sizeof(Record); // Example offset calculation
        values[i] = random_lib_float(randCtx);
    }

    // Allocate records array from memory pool
    Record *records = (Record *)memory_pool_alloc(pool, numRecords * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        free(values);
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    // Initialize each record
    size_t totalAllocatedSize = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&mutex);

        char *identifier = memory_pool_alloc(pool, IDENTIFIER_MAX_LENGTH);
        if (!identifier) {
            fprintf(stderr, "Memory allocation failed for identifier\n");
            break; // Partial cleanup handled later
        }

        strcpy(identifier, "Record");  // Example key generation

        records[i].key = keys[i];
        records[i].identifier = identifier;
        records[i].offset = offsets[i];
        records[i].value = values[i];

        if (callback) {
            callback(&records[i]);
        }

        totalAllocatedSize += sizeof(Record) + IDENTIFIER_MAX_LENGTH;

        pthread_mutex_unlock(&mutex);

        // Check memory limits
        if (totalAllocatedSize > maxTotalSize) {
            fprintf(stderr, "Exceeded maximum total size\n");
            break;
        }
    }

    // Cleanup in case of early exit or failure
    for (size_t i = 0; i < numRecords && records[i].identifier != NULL; ++i) {
        memory_pool_free(pool, records[i].identifier);
    }

    memory_pool_free(pool, records);

    free(keys);
    free(offsets);
    free(values);
    random_lib_cleanup(randCtx);

    // Logging example
    printf("Initialized %zu out of %zu records\n", numRecords, maxProcess);
}

// Example callback function
void processRecord(Record *record) {
    if (record) {
        printf("Processing record with key: %d, identifier: %s, value: %.2f\n",
               record->key, record->identifier, record->value);
    }
}
