#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_INTERFACE_NAME_LENGTH 256

typedef struct {
    char *ips; // Assuming IPs are stored as a single string for simplicity
} IPAddressList;

typedef struct {
    int id;
    char name[MAX_INTERFACE_NAME_LENGTH];
    bool is_up;
    IPAddressList ip_addresses;
} NetworkInterface;

typedef struct {
    NetworkInterface *interfaces;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
    void (*pre_add_callback)(NetworkInterface*);
    void (*post_add_callback)(NetworkInterface*);
} InterfaceManager;

void custom_memory_allocator_init(InterfaceManager *manager);
void custom_memory_allocator_destroy(InterfaceManager *manager);
bool add_interface(InterfaceManager *manager, NetworkInterface new_interface);
void update_interface_state(InterfaceManager *manager, int id, bool is_up, IPAddressList ip_addresses);

static inline void grow_capacity(InterfaceManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NetworkInterface *new_interfaces = realloc(manager->interfaces, new_capacity * sizeof(NetworkInterface));
    if (new_interfaces == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->interfaces = new_interfaces;
    manager->capacity = new_capacity;
}

void custom_memory_allocator_init(InterfaceManager *manager) {
    manager->interfaces = malloc(INITIAL_CAPACITY * sizeof(NetworkInterface));
    if (manager->interfaces == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void custom_memory_allocator_destroy(InterfaceManager *manager) {
    free(manager->interfaces);
    pthread_mutex_destroy(&manager->lock);
}

bool is_id_unique(const InterfaceManager *manager, int id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->interfaces[i].id == id) {
            return false;
        }
    }
    return true;
}

bool add_interface(InterfaceManager *manager, NetworkInterface new_interface) {
    pthread_mutex_lock(&manager->lock);

    if (!is_id_unique(manager, new_interface.id)) {
        fprintf(stderr, "Error: Interface ID %d already exists.\n", new_interface.id);
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    if (strlen(new_interface.name) >= MAX_INTERFACE_NAME_LENGTH) {
        fprintf(stderr, "Error: Interface name too long.\n");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    // Call pre-add callback
    if (manager->pre_add_callback != NULL) {
        manager->pre_add_callback(&new_interface);
    }

    if (manager->count >= manager->capacity) {
        grow_capacity(manager);
    }

    manager->interfaces[manager->count++] = new_interface;

    // Call post-add callback
    if (manager->post_add_callback != NULL) {
        manager->post_add_callback(&new_interface);
    }

    pthread_mutex_unlock(&manager->lock);
    return true;
}

void update_interface_state(InterfaceManager *manager, int id, bool is_up, IPAddressList ip_addresses) {
