            // Optimistic locking could be implemented here with version numbers
            manager->interfaces[i].is_up = is_up;
            free(manager->interfaces[i].ip_addresses.ips);
            manager->interfaces[i].ip_addresses.ips = strdup(ip_addresses.ips);

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    fprintf(stderr, "Error: Interface ID %d not found.\n", id);
    pthread_mutex_unlock(&manager->lock);
}

void set_pre_add_callback(InterfaceManager *manager, void (*callback)(NetworkInterface*)) {
    manager->pre_add_callback = callback;
}

void set_post_add_callback(InterfaceManager *manager, void (*callback)(NetworkInterface*)) {
    manager->post_add_callback = callback;
}
