#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    char stringKey[256];
    long *dynamicPtr;
} Record;

// Function to initialize the DynamicRecordManager
void DynamicRecordManager(int offsetSize, int keySize, int recordSize, void (*callback)(int, Record*)) {
    if (offsetSize <= 0 || keySize <= 0 || recordSize <= 0) return;

    // Allocate memory for offsets and keys
    long *offsets = (long *)malloc(offsetSize * sizeof(long));
    int *keys = (int *)malloc(keySize * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offsets and keys
    for (int i = 0; i < offsetSize; ++i) {
        offsets[i] = i;
    }
    for (int i = 0; i < keySize; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records
    Record *records = (Record *)malloc(recordSize * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    for (int i = 0; i < recordSize; ++i) {
        pthread_mutex_lock(&mutex);

        records[i].value = rand() % 1000; // Random float number within range [0, 999]
        snprintf(records[i].stringKey, sizeof(records[i].stringKey), "Key_%d", keys[i % keySize]);
        records[i].dynamicPtr = (long *)malloc(sizeof(long));
        if (!records[i].dynamicPtr) {
            fprintf(stderr, "Memory allocation failed for dynamic pointer\n");
            pthread_mutex_unlock(&mutex);
            continue;
        }
        *records[i].dynamicPtr = offsets[i % offsetSize];

        if (callback) {
            callback(i, &records[i]);
        }

        pthread_mutex_unlock(&mutex);
    }

    // Free allocated memory
    for (int i = 0; i < recordSize; ++i) {
        free(records[i].dynamicPtr);
    }
    free(records);
    free(offsets);
    free(keys);
    pthread_mutex_destroy(&mutex);
}
