using System;

public class FlexibleValueGenerator
{
    private float minValue;
    private float maxValue;

    public FlexibleValueGenerator(float min = 0, float max = 100)
    {
        if (min >= max) throw new ArgumentException("minValue must be less than maxValue");
        this.minValue = min;
        this.maxValue = max;
    }

    private Random random = new Random();

    public float GenerateRandomFloat()
    {
        return minValue + (float)(random.NextDouble() * (maxValue - minValue));
    }

    public float GenerateStrictRandomFloat()
    {
        double fraction = (double)random.NextDouble();
        double range = maxValue - minValue;
        // Adjust to ensure the value is strictly between minValue and maxValue
        return (float)(minValue + Math.Max(0.0001, fraction * range));
    }
}
