[ApiController]
[Route("api/[controller]")]
public class ElementController : ControllerBase
{
    private readonly IElementService _elementService;
    private readonly ICssRecompilationQueue _cssRecompileQueue;
    private readonly ILogger<ElementController> _logger;

    public ElementController(IElementService elementService, ICssRecompilationQueue cssRecompileQueue, ILogger<ElementController> logger)
    {
        _elementService = elementService ?? throw new ArgumentNullException(nameof(elementService));
        _cssRecompileQueue = cssRecompileQueue ?? throw new ArgumentNullException(nameof(cssRecompileQueue));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElementHtmlAsync([FromBody] ElementUpdateRequest request)
    {
        try
        {
            // Validate the input parameters
            if (string.IsNullOrWhiteSpace(request.PageSectionId) || 
                string.IsNullOrWhiteSpace(request.ElementId) ||
                string.IsNullOrWhiteSpace(request.HtmlContent))
            {
                return BadRequest("Required fields are missing or invalid.");
            }

            // Example length constraint: Max 255 chars for IDs, max 10,000 chars for HTML content
            if (request.PageSectionId.Length > 255 || request.ElementId.Length > 255 ||
                request.HtmlContent.Length > 10000)
            {
                return BadRequest("Input exceeds maximum allowed length.");
            }

            // Log the request details
            _logger.LogInformation($"Updating element {request.ElementId} in section {request.PageSectionId}");

            // Check for specific HTML tags or attributes that may require CSS recompilation
            bool requiresCssRecompile = request.HtmlContent.Contains("<style>") || request.HtmlContent.Contains("class=\"");

            // Use the service to update the HTML content asynchronously
            await _elementService.UpdateHtmlContentAsync(request.PageSectionId, request.ElementId, request.HtmlContent);

            if (requiresCssRecompile)
            {
                // Enqueue a task for CSS recompilation
                await _cssRecompileQueue.EnqueueRecompileTaskAsync();
                // Notify the service layer to update the asset cache
                await _elementService.UpdateAssetCacheAsync();
            }

            return Ok("HTML content updated successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating HTML content for element {ElementId}", request.ElementId);
            return StatusCode(500, "An error occurred. Please refresh the page and try again.");
        }
    }
}

public record ElementUpdateRequest(string PageSectionId, string ElementId, string HtmlContent);

// Example service interfaces
public interface IElementService
{
    Task UpdateHtmlContentAsync(string sectionId, string elementId, string htmlContent);
    Task UpdateAssetCacheAsync();
}

public interface ICssRecompilationQueue
{
    Task EnqueueRecompileTaskAsync();
}
