['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>

#define INITIAL_CAPACITY 16
#define MAX_USERNAME_LENGTH 50
#define RECORD_KEY_SIZE 50
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 100

typedef struct {
    int value;
    char key[RECORD_KEY_SIZE];
    long *dataPtr;
} Record;

typedef struct {
    int id;
    char username[MAX_USERNAME_LENGTH];
    bool isActive;
    char **emails;
    size_t emailCount;
    Record records[];
} Account;

typedef struct Node {
    Account account;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Registry;

unsigned long hash(const char* str, unsigned long seed) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash ^ seed;
}

void initialize_registry(Registry* registry) {
    pthread_mutex_init(&registry->lock, NULL);
    registry->capacity = INITIAL_CAPACITY;
    registry->count = 0;
    registry->buckets = calloc(registry->capacity, sizeof(Node*));
}

void resize_registry_if_needed(Registry* registry) {
    if ((float)registry->count / registry->capacity > 0.75) {
        size_t new_capacity = registry->capacity * 2;
        Node** new_buckets = calloc(new_capacity, sizeof(Node*));

        for (size_t i = 0; i < registry->capacity; i++) {
            Node* node = registry->buckets[i];
            while (node) {
                unsigned long index = hash(node->account.username, new_capacity);
                Node* next = node->next;
                node->next = new_buckets[index];
                new_buckets[index] = node;
                node = next;
            }
        }

        free(registry->buckets);
        registry->buckets = new_buckets;
        registry->capacity = new_capacity;
    }
}

bool add_account(Registry* registry, int id, const char* username, size_t emailCount) {
    pthread_mutex_lock(&registry->lock);

    if (registry->count >= registry->capacity * 0.75) {
        pthread_mutex_unlock(&registry->lock);
        return false; // Full capacity
    }

    for (size_t i = 0; i < strlen(username); ++i) {
        if (!isalnum(username[i]) && username[i] != '_') {
            pthread_mutex_unlock(&registry->lock);
            return false; // Invalid characters in username
        }
    }

    unsigned long index = hash(username, registry->capacity);
    Node* node = registry->buckets[index];

    while (node) {
        if (strcmp(node->account.username, username) == 0) {
            pthread_mutex_unlock(&registry->lock);
            return false; // Duplicate username
        }
        node = node->next;
    }

    Account new_account = {id, "", true, NULL, emailCount};
    strncpy(new_account.username, username, MAX_USERNAME_LENGTH);

    size_t record_size = sizeof(Record) * (emailCount + 1);
    Record* records = malloc(record_size);
    for (size_t i = 0; i <= emailCount; ++i) {
        records[i].value = rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1) + INT_RANGE_MIN;
        snprintf(records[i].key, RECORD_KEY_SIZE, "Key_%zu", i);
        records[i].dataPtr = malloc(sizeof(long));
    }

    new_account.records = records;

    Node* newNode = malloc(sizeof(Node));
    newNode->account = new_account;
    newNode->next = registry->buckets[index];
    registry->buckets[index] = newNode;

    registry->count++;
    resize_registry_if_needed(registry);

    pthread_mutex_unlock(&registry->lock);
    return true;
}

void free_registry(Registry* registry) {
    for (size_t i = 0; i < registry->capacity; ++i) {
        Node* node = registry->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;

            for (size_t j = 0; j <= node->account.emailCount; ++j) {
                free(node->account.records[j].dataPtr);
            }
            free(node->account.records);

            free(temp);
        }
    }

    free(registry->buckets);
    pthread_mutex_destroy(&registry->lock);
}

void iterate_accounts(Registry* registry, bool (*filter)(const Account*)) {
    pthread_mutex_lock(&registry->lock);

    for (size_t i = 0; i < registry->capacity; ++i) {
        Node* node = registry->buckets[i];
        while (node) {
            if (filter && !filter(&node->account)) {
                node = node->next;
                continue;
            }
            // Process account
            printf("Account ID: %d, Username: %s\n", node->account.id, node->account.username);
            node = node->next;
        }
    }

    pthread_mutex_unlock(&registry->lock);
}

bool filter_active_accounts(const Account* account) {
    return account->isActive;
}
```

This code provides a basic implementation of a dynamic registry for managing user accounts using a hash table. It includes functions to initialize the registry, add new accounts while handling collisions and capacity issues, and iterate over accounts with filtering capabilities. The `Registry` structure is thread-safe with mutex locks to manage concurrent access.

The `resize_registry_if_needed` function dynamically resizes the hash table when it reaches 75% capacity, minimizing fragmentation by doubling the size. Each account has a list of records initialized with random integer values and string keys. Memory management functions ensure that all allocated memory is freed properly to prevent leaks. The `iterate_accounts` function demonstrates iterating over accounts with an optional filter for active accounts only.']

