public class MoSTStateManager {

    private static final Logger logger = Logger.getLogger(MoSTStateManager.class.getName());
    private static volatile String defaultThemeDirectory;
    private static final String DEFAULT_THEME_DIRECTORY = "/default/theme/directory";
    private static final int THREAD_POOL_SIZE = 5;
    private static final long BITMAP_SIZE_THRESHOLD = 10 * 1024 * 1024; // 10 MB

    private final ExecutorService executorService;

    public MoSTStateManager() {
        this.executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    }

    public MoSTState loadMoSTStateFromCache(File stateFile) {
        synchronized (this) {
            ObjectInputStream objectInputStream = null;
            try {
                if (!defaultThemeDirectory.isEmpty()) {
                    return deserializeState(stateFile, objectInputStream);
                } else {
                    defaultThemeDirectory = DEFAULT_THEME_DIRECTORY;
                    initializeThemeCache();
                }
            } catch (IOException | ClassNotFoundException e) {
                logger.log(Level.SEVERE, "Error loading state from cache", e);
            } finally {
                if (objectInputStream != null) {
                    try {
                        objectInputStream.close();
                    } catch (IOException e) {
                        logger.log(Level.WARNING, "Failed to close ObjectInputStream", e);
                    }
                }
            }
        }
        return null;
    }

    private MoSTState deserializeState(File stateFile, ObjectInputStream objectInputStream) throws IOException, ClassNotFoundException {
        if (!stateFile.exists()) {
            return null;
        }

        objectInputStream = new ObjectInputStream(new FileInputStream(stateFile));
        Object obj = objectInputStream.readObject();

        if (obj instanceof MoSTState) {
            return (MoSTState) obj;
        }
        return null;
    }

    private void initializeThemeCache() {
        executorService.submit(() -> {
            try {
                // Simulate theme bitmap loading from CDN
