        current_capacity *= 2;
        node *new_nodes = realloc(*nodes, current_capacity * sizeof(node));
        if (!new_nodes) {
            perror("Failed to reallocate nodes");
            exit(EXIT_FAILURE);
        }
        *nodes = new_nodes;
    }

    node *n = &((*nodes)[*node_count]);
    initialize_random_values(n, min_ip, max_ip, min_port, max_port);

    if (callback) {
        callback(n, NULL);
    }

    (*node_count)++;
}

void add_request(request **requests, int *request_count, size_t current_capacity, init_callback_fn callback) {
    if (*request_count >= current_capacity) {
        current_capacity *= 2;
        request *new_requests = realloc(*requests, current_capacity * sizeof(request));
        if (!new_requests) {
            perror("Failed to reallocate requests");
            exit(EXIT_FAILURE);
        }
        *requests = new_requests;
    }

    request *r = &((*requests)[*request_count]);
    r->action = NULL; // Set actual function pointers as needed
    r->data = NULL;   // Populate with relevant data
    r->next = NULL;

    if (callback) {
        callback(NULL, r);
    }

    (*request_count)++;
}

void resize_int_array(int **array, int *size, size_t capacity) {
    if (*size >= capacity) {
        capacity *= 2;
        int *new_array = realloc(*array, capacity * sizeof(int));
        if (!new_array) {
            perror("Failed to reallocate integers array");
            exit(EXIT_FAILURE);
        }
        *array = new_array;
    }
}

