['```python
import threading
import time
from collections import deque
import queue

class LogEntry:
    def __init__(self, timestamp=None, severity="INFO", message_id=0, message_body=""):
        self.timestamp = timestamp or time.time_ns()
        self.severity = severity
        self.message_id = message_id
        self.message_body = message_body

class SlabAllocator:
    _lock = threading.Lock()
    _free_slabs = deque()

    @classmethod
    def allocate(cls, size):
        with cls._lock:
            if cls._free_slabs and len(cls._free_slabs[0]) >= size:
                return cls._free_slabs.popleft()
            else:
                return bytearray(size)

    @classmethod
    def deallocate(cls, slab):
        with cls._lock:
            cls._free_slabs.append(slab)

class LogManager:
    def __init__(self, initial_capacity=1000, seed=1):
        self.buffer = deque(maxlen=initial_capacity)
        self.message_id_generator = self._message_id_gen(seed)
        self.lock = threading.Lock()
        self.async_queue = queue.Queue()
        self.running = True
        self.logging_thread = threading.Thread(target=self._process_async_logs)
        self.logging_thread.start()

    def _message_id_gen(self, seed):
        while True:
            yield seed
            seed += 1

    def append_log_entry_sync(self, severity="INFO", message_body="", callback=None):
        with self.lock:
            log_entry = LogEntry(severity=severity, message_id=next(self.message_id_generator), message_body=message_body)
            if callback: 
                callback(log_entry, "pre")
            self.buffer.append(log_entry)
            if callback: 
                callback(log_entry, "post")

    def append_log_entry_async(self, severity="INFO", message_body="", callback=None):
        log_entry = LogEntry(severity=severity, message_id=next(self.message_id_generator), message_body=message_body)
        if callback:
            callback(log_entry, "pre")
        self.async_queue.put(log_entry)

    def _process_async_logs(self):
        while self.running:
            try:
                log_entry = self.async_queue.get(timeout=1)
                with self.lock:
                    self.buffer.append(log_entry)
            except queue.Empty:
                continue

    def query_logs(self, severity=None, start_time=None, end_time=None, message_id_range=None):
        with self.lock:
            for entry in self.buffer:
                if ((severity is None or entry.severity == severity) and
                        (start_time is None or entry.timestamp >= start_time) and
                        (end_time is None or entry.timestamp <= end_time) and
                        (message_id_range is None or message_id_range[0] <= entry.message_id <= message_id_range[1])):
                    yield entry

    def stop_logging(self):
        self.running = False
        self.logging_thread.join()

    def free_memory(self):
        with self.lock:
            for slab in list(self.buffer):
                SlabAllocator.deallocate(slab)
            self.buffer.clear()
```

This code implements a logging infrastructure using a slab allocator for memory efficiency and supports both synchronous and asynchronous log entry appending. It provides querying capabilities based on various criteria, ensures thread safety, and manages resources effectively.']

