#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "secure_random.h"  // Assume this header provides secure random functions

typedef struct Record {
    int value;
    char key[64];
    long *dynamic_long;
    struct Record *next;
} Record;

void log_error(FILE* fd, const char* message) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    fprintf(fd, "%s\n", message);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

long custom_random(long min, long max, unsigned int *seed) {
    // Custom random function using a simple linear congruential generator
    const long a = 1664525;
    const long c = 1013904223;
    const long m = (1LL << 32);

    *seed = (*seed * a + c) % m;
    return min + ((*seed / (double)m) * (max - min));
}

void free_resources(Record* head, FILE* log_fd) {
    Record *current = head;
    while (current != NULL) {
        Record *next = current->next;
        free(current->dynamic_long);
        free(current);
        current = next;
    }
}

int init_data_structure(size_t offsets_size, size_t keys_size, long range_min, long range_max, unsigned int seed,
                        FILE* log_fd, void (*callback)(Record*)) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for offsets and keys
    long *offsets = (long*)malloc(offsets_size * sizeof(long));
    if (!offsets) {
        log_error(log_fd, "Failed to allocate memory for offsets");
        return -1;
    }

    int *keys = (int*)malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        log_error(log_fd, "Failed to allocate memory for keys");
        return -1;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }

    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = i;
    }

    pthread_mutex_lock(&lock);

    // Create the linked list
    Record *head = NULL, *tail = NULL;

    for (int i = 0; i < keys_size; ++i) {
        Record *new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            log_error(log_fd, "Failed to allocate memory for record");
            free_resources(head, log_fd);
            free(offsets);
            free(keys);
            pthread_mutex_unlock(&lock);
            return -1;
        }

        new_record->value = custom_random(range_min, range_max, &seed);
        snprintf(new_record->key, sizeof(new_record->key), "Key_%d", i);

        new_record->dynamic_long = (long*)malloc(sizeof(long));
        if (!new_record->dynamic_long) {
            log_error(log_fd, "Failed to allocate memory for dynamic long");
            free(new_record);
            free_resources(head, log_fd);
            free(offsets);
            free(keys);
            pthread_mutex_unlock(&lock);
            return -1;
        }
        *new_record->dynamic_long = i;  // Initialize with some value

        new_record->next = NULL;

        if (!head) {
            head = tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }

        if (callback) {
            callback(new_record);
        }
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    // Clean up
    free_resources(head, log_fd);
    free(offsets);
    free(keys);

    return 0;
}
