// Define record structure
typedef struct {
    int value;
    char string_key[256];
    long *dynamic_long_ptr;
} Record;

// External library for random number generation
#include "random_library.h"

// Callback function type
typedef void (*RecordCallback)(Record*);

// Memory pool to reuse allocations
typedef struct {
    size_t block_size;
    unsigned int count;
    unsigned int capacity;
    Record **blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Initialize memory pool
void init_memory_pool(MemoryPool *pool, size_t block_size, unsigned int initial_capacity) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->blocks = malloc(initial_capacity * sizeof(Record*));
}

// Allocate record from memory pool
Record* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count > 0) {
        Record *record = pool->blocks[--pool->count];
        pthread_mutex_unlock(&pool->lock);
        return record;
    }
    pthread_mutex_unlock(&pool->lock);

    // Allocate new block if no available blocks
    Record *new_record = malloc(pool->block_size);
    return new_record;
}

// Return record to memory pool
void free_to_pool(MemoryPool *pool, Record *record) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        pool->blocks[pool->count++] = record;
    } else {
        free(record);
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to initialize records
void initialize_records(unsigned int size, int key_range, int value_range, RecordCallback callback) {
    MemoryPool pool;
    init_memory_pool(&pool, sizeof(Record), 100);

    for (unsigned int i = 0; i < size; ++i) {
        Record *record = allocate_from_pool(&pool);

        // Initialize record
        record->value = random_range(value_range);  // Assume `random_range` is provided by the external library
        snprintf(record->string_key, sizeof(record->string_key), "Key_%d", i % key_range);
        record->dynamic_long_ptr = malloc(sizeof(long));
        *record->dynamic_long_ptr = 0;  // Initialize with some default value

        if (callback) {
            callback(record);  // Process each record via user-provided callback
        }
    }

    // Cleanup and free resources
    for (unsigned int i = 0; i < pool.count; ++i) {
        Record *record = pool.blocks[i];
        free(record->dynamic_long_ptr);
        free_to_pool(&pool, record);
    }
    free(pool.blocks);
    pthread_mutex_destroy(&pool.lock);
}

