#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    time_t timestamp;
} record;

typedef struct UnionFind {
    int *parent, *rank;
    size_t size;
} UnionFind;

UnionFind* UF_create(size_t n) {
    UnionFind* uf = malloc(sizeof(UnionFind));
    uf->parent = calloc(n, sizeof(int));
    uf->rank = calloc(n, sizeof(int));
    uf->size = n;
    for (size_t i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
    return uf;
}

int UF_find(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = UF_find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void UF_union(UnionFind* uf, int x, int y) {
    int rootX = UF_find(uf, x);
    int rootY = UF_find(uf, y);
    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int UF_connected(UnionFind* uf, int x, int y) {
    return UF_find(uf, x) == UF_find(uf, y);
}

void UF_destroy(UnionFind* uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

int process_batches(const char* filename, int range_min, int range_max, size_t batch_size) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    int num_disjoint_pairs = 0;

    char line[256];
    size_t offset_count = 0, key_count = 0, total_records = 0;
    while (fgets(line, sizeof(line), file)) {
        if (line[0] == '\n' || line[0] == '#') continue;

        char *token = strtok(line, ",");
        long offset = strtol(token, NULL, 10);
        token = strtok(NULL, ",");
        int key = atoi(token);

        offsets = realloc(offsets, sizeof(long) * (offset_count + 1));
        keys = realloc(keys, sizeof(int) * (key_count + 1));

        offsets[offset_count++] = offset;
        keys[key_count++] = key;

        total_records++;
    }
    fclose(file);

    size_t num_batches = (total_records + batch_size - 1) / batch_size;

    for (size_t b = 0; b < num_batches; b++) {
        size_t start_index = b * batch_size;
        size_t end_index = (b + 1) * batch_size;
        if (end_index > total_records) end_index = total_records;

        records = realloc(records, sizeof(record) * (end_index - start_index));

        for (size_t i = start_index; i < end_index; i++) {
            records[i - start_index].value = range_min + rand() % (range_max - range_min + 1);
            records[i - start_index].timestamp = time(NULL);
        }

        UnionFind *uf = UF_create(10000); // Adjust size as needed

        clock_t begin = clock();

        for (size_t i = start_index; i < end_index; i++) {
            int root_value = records[i - start_index].value;
            if (!UF_connected(uf, keys[i], root_value)) {
                UF_union(uf, keys[i], root_value);
            } else {
                num_disjoint_pairs++;
            }
        }

        clock_t end = clock();
        double time_spent = (double)(end - begin) / CLOCKS_PER_SEC;
        printf("Batch %zu processed in %.2f seconds.\n", b + 1, time_spent);

        UF_destroy(uf);
        free(records); // Free current batch
    }

    free(offsets);
    free(keys);

    return num_disjoint_pairs;
}

int main() {
    srand(time(NULL));
    int disjoint_count = process_batches("input.csv", 0, 100, 10000);
    printf("Total number of disjoint pairs: %d\n", disjoint_count);
    return 0;
}
