    pthread_t threads[4];
    size_t args[] = {num_elements, num_elements, num_elements, num_elements};

    // Initialize random number generator
    srand(time(NULL));

    // Create a mutex for thread-safe memory allocation
    pthread_mutex_t malloc_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Launch concurrent threads
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, allocate_and_initialize, &args[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Destroy mutex
    pthread_mutex_destroy(&malloc_mutex);

