#include <stdio.h>
#include <stdlib.h>
import stdlib.h>
#include <time.h>
#include <pthread.h>

// Define constants
#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB maximum memory usage limit for simplicity
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

// Structure definition for record
typedef struct {
    long offset;
    int key;
    int value;
} record;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize arrays
void allocate_and_initialize(int n, long** offsets, int** keys, record*** records) {
    size_t total_memory_usage = sizeof(long) * n + sizeof(int) * n + sizeof(record) * n;

    if (total_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory allocation exceeds the limit.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets and keys
    *offsets = (long*) malloc(n * sizeof(long));
    if (*offsets == NULL) { perror("Failed to allocate memory for offsets"); exit(EXIT_FAILURE); }

    *keys = (int*) malloc(n * sizeof(int));
    if (*keys == NULL) { perror("Failed to allocate memory for keys"); free(*offsets); exit(EXIT_FAILURE); }

    // Initialize arrays
    for (int i = 0; i < n; ++i) {
        (*offsets)[i] = rand() % 1000000;
        (*keys)[i] = rand() % 1000000; // Assume unique initially, collision will be handled later
    }

    // Allocate memory for records array
    *records = (record**) malloc(n * sizeof(record*));
    if (*records == NULL) { perror("Failed to allocate memory for records"); free(*offsets); free(*keys); exit(EXIT_FAILURE); }

    for (int i = 0; i < n; ++i) {
        (*records)[i] = (record*) malloc(sizeof(record));
        if ((*records)[i] == NULL) { perror("Failed to allocate memory for record"); 
                                      while (--i >= 0) free((*records)[i]); // Free previous allocations
                                      free(*offsets); free(*keys); free(*records);
                                      exit(EXIT_FAILURE); }
    }

    // Initialize records with offsets and keys
    for (int i = 0; i < n; ++i) {
        (*records)[i]->offset = (*offsets)[i];
        (*records)[i]->key = (*keys)[i];
    }
}

// Function to set random values avoiding key conflicts
void set_random_values(int n, record** records, int* keys) {
    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        int value;
        do {
            pthread_mutex_lock(&lock);
            value = rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1) + RANDOM_RANGE_MIN;
            // Check for key conflicts
            int conflict = 0;
            for (int j = 0; j < n && !conflict; ++j) {
                if ((*records)[i]->key == keys[j] && value == (*records)[j]->value) {
                    conflict = 1;
                }
            }
            pthread_mutex_unlock(&lock);
        } while (conflict);

        pthread_mutex_lock(&lock);
        (*records)[i]->value = value; // Set the unique random value
        pthread_mutex_unlock(&lock);
    }
}

// Function to free allocated memory
void free_allocated_memory(int n, long* offsets, int* keys, record** records) {
    for (int i = 0; i < n; ++i) {
        if (records[i]) free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

// Example usage
int main() {
    int array_size;
    printf("Enter the size of arrays: ");
    scanf("%d", &array_size);

    long* offsets = NULL;
    int* keys = NULL;
    record** records = NULL;

    allocate_and_initialize(array_size, &offsets, &keys, &records);
    set_random_values(array_size, records, keys);

    for (int i = 0; i < array_size; ++i) {
        printf("Record %d - Offset: %ld, Key: %d, Value: %d\n", i, records[i]->offset, records[i]->key, records[i]->value);
    }

    free_allocated_memory(array_size, offsets, keys, records);

    pthread_mutex_destroy(&lock); // Clean up the mutex
    return 0;
}
```

### Design Choices and Trade-offs:

1. **Memory Allocation**: Carefully calculated total memory usage to ensure it does not exceed a predefined limit (`MAX_MEMORY_USAGE`). Ensures that all allocations are checked for success, with proper error handling to free previously allocated resources in case of failures.

2. **Thread Safety**: Used `pthread_mutex_t` to provide thread-safe operations when setting random values in the `records`. This approach prevents race conditions and ensures data consistency across concurrent threads/processes.

3. **Random Value Assignment**: Implemented a collision detection mechanism that checks for conflicts between keys and assigned values, ensuring unique assignments. It prioritizes correctness over performance due to potential key-value collisions.

4. **Scalability and Efficiency**: The code is designed to handle dynamic input sizes efficiently by scaling the memory allocations proportionally while maintaining constant space complexity relative to `n`. Trade-offs include balancing cache efficiency with flexibility for future growth.

5. **Error Handling and Cleanup**: Comprehensive error handling includes free() operations in case of failures, ensuring no memory leaks occur. The code also ensures that mutex resources are properly destroyed after use.

This implementation balances performance needs, resource utilization, and reliability considerations effectively within the given constraints.']

