    EDE3,
    CFB,
    NULL_CIPHER
} CipherMode;

// Function prototypes for DES algorithm (pseudo implementations)
void des_encrypt_ecb(int *data, size_t num_records);
void des_encrypt_ede(int *data, size_t num_records);
void des_encrypt_ede3(int *data, size_t num_records);
void des_encrypt_cfb(int *data, size_t num_records);

// Function to log messages
void log_message(const char *message) {
    printf("%s\n", message);
}

// Function to validate cipher mode
CipherMode get_cipher_mode(const char* mode_str) {
    if (strcmp(mode_str, "ECB") == 0) return ECB;
    if (strcmp(mode_str, "EDE") == 0) return EDE;
    if (strcmp(mode_str, "EDE3") == 0) return EDE3;
    if (strcmp(mode_str, "CFB") == 0) return CFB;
    return NULL_CIPHER; // Default to Null
}

// Main function to allocate memory and initialize data structures
void* process_records(const char *json_file_path) {
    json_error_t error;
    json_t *root = json_load_file(json_file_path, 0, &error);

    if (!root) {
        log_message("Error loading JSON file");
        return NULL;
    }

    Config config = { .num_records = 0, .value_range_min = 0, .value_range_max = 0 };
    json_t *num_records, *min_value, *max_value, *cipher_mode_str;

    if (json_unpack(root, "{s:i, s:i, s:s}", "num_records", &config.num_records,
                    "value_range_min", &config.value_range_min,
                    "value_range_max", &config.value_range_max,
                    "cipher_mode", &cipher_mode_str) != 0) {
        log_message("Error parsing JSON configuration");
        json_decref(root);
        return NULL;
    }

    char *mode_str = json_string_value(cipher_mode_str);
    CipherMode cipher_mode = get_cipher_mode(mode_str);

    if (cipher_mode == NULL_CIPHER) {
        log_message("Invalid cipher mode specified in configuration");
        json_decref(root);
        return NULL;
    }

    Record *records = malloc(config.num_records * sizeof(Record));
    if (!records) {
        log_message("Memory allocation failed for records");
        json_decref(root);
        return NULL;
    }

    log_message("Allocated memory for records");

    // Initialize records with random values within the specified range
    for (int i = 0; i < config.num_records; ++i) {
        records[i].data = rand() % (config.value_range_max - config.value_range_min + 1)
                          + config.value_range_min;
    }

    log_message("Initialized record data");

    // Encrypt records based on the specified cipher mode
    switch (cipher_mode) {
        case ECB:
            des_encrypt_ecb((int *)records, config.num_records);
            break;
        case EDE:
            des_encrypt_ede((int *)records, config.num_records);
            break;
        case EDE3:
            des_encrypt_ede3((int *)records, config.num_records);
            break;
        case CFB:
            des_encrypt_cfb((int *)records, config.num_records);
            break;
        default:
            log_message("Cipher operation skipped due to invalid mode");
    }

    json_decref(root);

    // Return pointer to the records
    return records;
}

