#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_SIZE 1024

typedef struct {
    int value;
    size_t size;
} record;

typedef struct memory_pool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t lock;
} memory_pool;

void init_memory_pool(memory_pool *mp, size_t block_size, size_t blocks) {
    mp->block_size = block_size;
    mp->pool_size = block_size * blocks;
    mp->pool = malloc(mp->pool_size);
    pthread_mutex_init(&mp->lock, NULL);
}

void free_memory_pool(memory_pool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

long* allocate_offset_array(size_t count) {
    long *offsets = (long*)malloc(count * sizeof(long));
    if (!offsets) return NULL;
    for (size_t i = 0; i < count; ++i) offsets[i] = rand() % 100; // Example initialization
    return offsets;
}

int* allocate_key_array(size_t count) {
    int *keys = (int*)malloc(count * sizeof(int));
    if (!keys) return NULL;
    for (size_t i = 0; i < count; ++i) keys[i] = rand() % 100; // Example initialization
    return keys;
}

record* allocate_record_array(memory_pool *mp, size_t record_count, int min_value, int max_value) {
    pthread_mutex_lock(&mp->lock);

    if (record_count == 0) {
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }

    record *records = (record*)malloc(record_count * sizeof(record));
    if (!records) {
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].size = DEFAULT_SIZE; // Initialize to default size
    }

    pthread_mutex_unlock(&mp->lock);
    return records;
}

void* init_data_structures(size_t offset_count, size_t key_count, size_t record_count, int min_value, int max_value) {
    long *offsets = allocate_offset_array(offset_count);
    if (!offsets) return NULL;

    int *keys = allocate_key_array(key_count);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    memory_pool mp;
    init_memory_pool(&mp, sizeof(record), record_count);

    record *records = allocate_record_array(&mp, record_count, min_value, max_value);
    if (!records) {
        free(offsets);
        free(keys);
        free_memory_pool(&mp);
        return NULL;
    }

    // Clean up
    free(offsets);
    free(keys);
    free_memory_pool(&mp);

    return (void*)records; // Return records as an example, can be adjusted to your needs
}

int main() {
    srand(time(NULL)); // Initialize random seed

    size_t offset_count = 100;
    size_t key_count = 100;
    size_t record_count = 10000000; // Example large dataset
    int min_value = 1;
    int max_value = 100;

    void *records = init_data_structures(offset_count, key_count, record_count, min_value, max_value);

    if (records) {
        printf("Data structures initialized successfully.\n");
    } else {
        printf("Failed to initialize data structures.\n");
    }

    return 0;
}
