public class ResourceManager
{
    private int _resourceValue;
    private SemaphoreSlim _semaphore;
    private readonly string _configFilePath;

    public ResourceManager(string configFilePath)
    {
        _configFilePath = configFilePath;
        InitializeSemaphore();
        LoadConfiguration();
    }

    private void InitializeSemaphore()
    {
        try
        {
            _semaphore = new SemaphoreSlim(100);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to initialize semaphore.", ex);
        }
    }

    private void LoadConfiguration()
    {
        if (!File.Exists(_configFilePath))
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        string configContent = File.ReadAllText(_configFilePath);
        _resourceValue = int.TryParse(configContent, out var value) ? value : 0;
        Log($"Initial resource value set to {_resourceValue}.");
    }

    public void ResetResource()
    {
        LoadConfiguration();
        Log("Resource reset to initial value.");
    }

    public async Task<int> AccessResourceAsync(Func<int, int> operation)
    {
        await _semaphore.WaitAsync();

        try
        {
            var result = operation(_resourceValue);
            _resourceValue = result;
            Log($"Asynchronous access by thread {Thread.CurrentThread.ManagedThreadId}: {_resourceValue}");
            return result;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public int AccessResource(Func<int, int> operation)
    {
        _semaphore.Wait();

        try
        {
            var result = operation(_resourceValue);
            _resourceValue = result;
            Log($"Synchronous access by thread {Thread.CurrentThread.ManagedThreadId}: {_resourceValue}");
            return result;
        }
        finally
        {
            _semaphore.Release();
        }
    }

