#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    time_t timestamp;
} record;

// Union-Find structure with path compression and union by rank.
typedef struct {
    int *parent;
    int *rank;
} UnionFind;

void initUnionFind(UnionFind *uf, int size) {
    uf->parent = (int *)malloc(size * sizeof(int));
    uf->rank = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int countDisjointSets(UnionFind *uf, int size) {
    int count = 0;
    for (int i = 0; i < size; ++i) {
        if (uf->parent[i] == i)
            count++;
    }
    return count;
}

void freeUnionFind(UnionFind *uf) {
    free(uf->parent);
    free(uf->rank);
}

void manageMemory(int longSize, int keySize, int recordSize, int minValue, int maxValue) {
    // Memory allocation
    long *offsets = (long *)malloc(longSize * sizeof(long));
    int *keys = (int *)malloc(keySize * sizeof(int));

    record *records = (record *)malloc(recordSize * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    // Initialize Union-Find structure
    UnionFind uf;
    initUnionFind(&uf, recordSize);

    // Populate records with random values and timestamps
    srand(time(NULL));
    for (int i = 0; i < recordSize; ++i) {
        records[i].value = minValue + rand() % (maxValue - minValue + 1);
        records[i].timestamp = time(NULL); // or use a more precise timer if needed
    }

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < recordSize - 1; ++i) {
        for (int j = i + 1; j < recordSize; ++j) {
            start = clock();
            if (records[i].value == records[j].value) {
                unionSets(&uf, i, j);
            }
            end = clock();
            cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;
            printf("Merge operation took %f milliseconds\n", cpu_time_used);
        }
    }

    // Count disjoint sets
    int numDisjointSets = countDisjointSets(&uf, recordSize);

    // Free resources
    free(offsets);
    free(keys);
    free(records);
    freeUnionFind(&uf);

    printf("Number of disjoint groups: %d\n", numDisjointSets);
}
