        if (!(*data)[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Initialize data_point structure
        (*data)[i]->value = (double)(rand() / (RAND_MAX + 1.0));

        const int max_label_length = 10;
        char *label = malloc((max_label_length + 1) * sizeof(char));
        if (!label) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < max_label_length; ++j) {
            label[j] = 'a' + rand() % 26;
        }
        label[max_label_length] = '\0';
        (*data)[i]->label = label;

        // Random boolean flag
        (*data)[i]->isValid = (rand() % 2 == 0);
    }
