void free_data_points(int num_points, data_point **data) {
    if (!data || !*data) return;

    for (int i = 0; i < num_points; ++i) {
        if ((*data)[i]) {
            free((*data)[i]->label);
            free((*data)[i]);
        }
    }

    free(*data);
    *data = NULL;
}

