void flush_memory(void *ptr, size_t size) {
    // Assuming we can use memset to hint for memory deallocation.
    // Note: This is just a placeholder since such optimizations depend on the compiler and platform.
    if (ptr != NULL) {
        memset(ptr, 0, size);
    }
}

int process_large_binary_file(const char *filename, record ***records_out, long **offsets_out, int **keys_out, size_t *record_count) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return -1;
    }

    long offset;
    int key;
    size_t processed_records = 0;

    // Initial allocations
    size_t buffer_size = 10000;  // Start with a buffer for 10k records
    *offsets_out = malloc(buffer_size * sizeof(long));
    *keys_out = malloc(buffer_size * sizeof(int));
    if (!*offsets_out || !*keys_out) {
        fprintf(stderr, "Memory allocation error\n");
        fclose(file);
        return -1;
    }

    *records_out = malloc(buffer_size * sizeof(record *));
    if (!*records_out) {
        fprintf(stderr, "Memory allocation error for records array\n");
        free(*offsets_out);
        free(*keys_out);
        fclose(file);
        return -1;
    }

    size_t offsets_index = 0, keys_index = 0, records_index = 0;

    while (fread(&offset, sizeof(long), 1, file) == 1 && fread(&key, sizeof(int), 1, file) == 1) {
        if (processed_records >= buffer_size) {
            // Expand memory as needed
            buffer_size *= 2;
            *offsets_out = realloc(*offsets_out, buffer_size * sizeof(long));
            *keys_out = realloc(*keys_out, buffer_size * sizeof(int));

            // Allocate more records array pointers and expand them
            record **new_records_array = realloc(*records_out, buffer_size * sizeof(record *));
            if (!new_records_array) {
                fprintf(stderr, "Memory allocation error for expanding records array\n");
                free(*offsets_out);
                free(*keys_out);
                fclose(file);
                return -1;
            }
            *records_out = new_records_array;

            // Initialize the newly allocated memory
            for (size_t i = processed_records; i < buffer_size; ++i) {
                (*records_out)[i] = NULL;
            }

            flush_memory(*offsets_out + offsets_index, sizeof(long) * (buffer_size - offsets_index));
            flush_memory(*keys_out + keys_index, sizeof(int) * (buffer_size - keys_index));
        }

        // Store offset and key
        (*offsets_out)[offsets_index++] = offset;
        (*keys_out)[keys_index++] = key;

        // Allocate a new record and store it in the records array
        (*records_out)[records_index] = malloc(sizeof(record));
        if (!(*records_out)[records_index]) {
            fprintf(stderr, "Memory allocation error for individual record\n");
            fclose(file);
            return -1;
        }

        (*records_out)[records_index]->offset = offset;
        (*records_out)[records_index]->key = key;

        records_index++;
        processed_records++;
    }

    if (ferror(file)) {
        fprintf(stderr, "Error reading file: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    *record_count = processed_records;
    fclose(file);

    // Clean up any unused allocated memory
    for (size_t i = records_index; i < buffer_size; ++i) {
        if ((*records_out)[i] != NULL) {
            free((*records_out)[i]);
        }
    }

    return 0;
}
