            return -1;
        }

        *value = minVal + rand() % (maxVal - minVal + 1);
        record->value = value;
        temp[i] = record;
    }

    // Assign the allocated array to the output parameter
    *recordsArray = temp;

    return 0; // Success
}

// Example usage of the function
int main() {
    int logFd = open("log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logFd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    Record **recordsArray = NULL;
    size_t numRecords = 100; // Example number of records
    int minVal = 1, maxVal = 100; // Range for random values
    unsigned int seed = 42; // Seed for random number generator

    if (initializeRecords(&recordsArray, numRecords, minVal, maxVal, seed, logFd) != 0) {
        fprintf(stderr, "Initialization failed\n");
        close(logFd);
        return EXIT_FAILURE;
    }

    // Example usage of the records
    for (size_t i = 0; i < numRecords; ++i) {
        printf("Record %zu: Value = %d\n", i, *recordsArray[i]->value);
    }

    // Free allocated memory
    for (size_t i = 0; i < numRecords; ++i) {
        free(recordsArray[i]->value);
        free(recordsArray[i]);
    }
    free(recordsArray);

    close(logFd);
    return EXIT_SUCCESS;
}
