#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <execinfo.h>
#include <string.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example threshold in bytes

typedef struct {
    float x;
    float y;
} point;

typedef struct {
    double* doubles;
    size_t num_doubles;
    char** strings;
    size_t num_strings;
    point* points;
    size_t num_points;
    pthread_mutex_t mutex;
    size_t total_memory_usage;
    void* memory_pool;
    size_t pool_size;
} MemoryManager;

static const size_t BLOCK_SIZE = 4096; // Block size for the custom memory pool

// Custom memory allocation function
void* custom_malloc(MemoryManager* manager, size_t size) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->memory_pool == NULL || (size + manager->total_memory_usage > manager->pool_size)) {
        // Allocate new block
        void* new_block = malloc(size);
        if (!new_block) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
        manager->memory_pool = realloc(manager->memory_pool, manager->pool_size + BLOCK_SIZE);
        memcpy((char*)manager->memory_pool + manager->pool_size, new_block, size);
        free(new_block);

        manager->pool_size += BLOCK_SIZE;
    }

    void* allocated_memory = (char*)manager->memory_pool + manager->total_memory_usage;
    manager->total_memory_usage += size;

    log_allocation(allocated_memory, size);

    pthread_mutex_unlock(&manager->mutex);
    return allocated_memory;
}

// Custom memory deallocation function
void custom_free(MemoryManager* manager, void* ptr) {
    pthread_mutex_lock(&manager->mutex);

    // Simulate freeing by marking it as unused in this simple example
    log_deallocation(ptr);

    pthread_mutex_unlock(&manager->mutex);
}

void log_allocation(void* ptr, size_t size) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] Allocated %zu bytes at %p\n", ctime(&now), size, ptr);
    void* stack[10];
    int frames = backtrace(stack, 10);
    backtrace_symbols_fd(stack, frames, STDERR_FILENO);
}

void log_deallocation(void* ptr) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] Deallocated memory at %p\n", ctime(&now), ptr);
    void* stack[10];
    int frames = backtrace(stack, 10);
    backtrace_symbols_fd(stack, frames, STDERR_FILENO);
}

MemoryManager* create_memory_manager() {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->doubles = NULL;
    manager->num_doubles = 0;
    manager->strings = NULL;
    manager->num_strings = 0;
    manager->points = NULL;
    manager->num_points = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->total_memory_usage = 0;
    manager->memory_pool = malloc(BLOCK_SIZE); // Initial pool size
    if (!manager->memory_pool) {
        free(manager);
        return NULL;
    }
    manager->pool_size = BLOCK_SIZE;

    return manager;
}

void resize_doubles(MemoryManager* manager, size_t new_size) {
    pthread_mutex_lock(&manager->mutex);

    double* new_doubles = (double*)custom_malloc(manager, new_size * sizeof(double));
    if (!new_doubles) {
        fprintf(stderr, "Failed to allocate memory for doubles\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    size_t min_size = manager->num_doubles < new_size ? manager->num_doubles : new_size;
    memcpy(new_doubles, manager->doubles, min_size * sizeof(double));

    custom_free(manager, manager->doubles);
    manager->doubles = new_doubles;
    manager->num_doubles = new_size;

    pthread_mutex_unlock(&manager->mutex);
}

void resize_strings(MemoryManager* manager, size_t new_size) {
    pthread_mutex_lock(&manager->mutex);

    char** new_strings = (char**)custom_malloc(manager, new_size * sizeof(char*));
    if (!new_strings) {
        fprintf(stderr, "Failed to allocate memory for strings\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    size_t min_size = manager->num_strings < new_size ? manager->num_strings : new_size;
    memcpy(new_strings, manager->strings, min_size * sizeof(char*));

    custom_free(manager, manager->strings);
    manager->strings = new_strings;
    manager->num_strings = new_size;

    pthread_mutex_unlock(&manager->mutex);
}

void resize_points(MemoryManager* manager, size_t new_size) {
    pthread_mutex_lock(&manager->mutex);

    point* new_points = (point*)custom_malloc(manager, new_size * sizeof(point));
    if (!new_points) {
        fprintf(stderr, "Failed to allocate memory for points\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    size_t min_size = manager->num_points < new_size ? manager->num_points : new_size;
    memcpy(new_points, manager->points, min_size * sizeof(point));

    custom_free(manager, manager->points);
    manager->points = new_points;
    manager->num_points = new_size;

    pthread_mutex_unlock(&manager->mutex);
}

size_t get_total_memory_usage(MemoryManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    size_t usage = manager->total_memory_usage;
    pthread_mutex_unlock(&manager->mutex);

    return usage;
}

void cleanup_memory_manager(MemoryManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    custom_free(manager, manager->doubles);
    custom_free(manager, manager->strings);
    custom_free(manager, manager->points);

    free(manager->memory_pool);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Example usage with external dependency library
void interact_with_external_library(MemoryManager* manager) {
    // Placeholder for interaction logic
}
