#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_OFFSET 1000
#define KEY_RANGE 256

typedef struct {
    int value;
} Record;

void initialize_records(long *offsets, int *keys, Record **records, size_t key_count) {
    // Allocate memory for offsets and keys
    if (key_count % 3 != 0) {
        fprintf(stderr, "Key count must be a multiple of 3.\n");
        exit(EXIT_FAILURE);
    }

    sizes_t record_count = key_count / 3;

    offsets = malloc(key_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    keys = malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records
    *records = malloc(record_count * sizeof(Record));
    if (!*records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Populate offsets and keys
    for (size_t i = 0; i < key_count; ++i) {
        offsets[i] = rand() % (MAX_OFFSET + 1); // Random non-negative values up to MAX_OFFSET
        keys[i] = rand() % KEY_RANGE;           // Random values between 0 and 255
    }

    // Initialize records with random integers, ensuring no two consecutive records have the same value
    int last_value = -2;
    for (size_t i = 0; i < record_count; ++i) {
        int new_value;
        do {
            new_value = rand() % KEY_RANGE; // Assuming similar range for simplicity
        } while (new_value == last_value);

        (*records)[i].value = new_value;
        last_value = new_value;
    }

    printf("Initialization complete.\n");
}

int main() {
    size_t key_count = 9; // Example key count, must be multiple of 3
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    initialize_records(offsets, keys, &records, key_count);

    // Cleanup
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
