['```javascript
const EventEmitter = require('events');
const { v4: uuidv4 } = require('uuid');

class DataStreamManager extends EventEmitter {
  constructor(retentionPeriodMs) {
    super();
    this.dataStreams = new Map();
    this.retentionPeriodMs = retentionPeriodMs;
    this.globalPaused = false;

    setInterval(() => this.cleanupOldData(), 60000); // Cleanup every minute
  }

  addDataStream(id, dataFetcherCallback) {
    if (this.dataStreams.has(id)) return; // Ignore duplicate stream registrations

    const newDataStream = {
      id,
      active: true,
      paused: false,
      timestamp: new Date(),
      entries: new Map(), // Using a map to handle high-frequency data efficiently
      fetcherCallback: dataFetcherCallback
    };

    this.dataStreams.set(id, newDataStream);
    this.emit('streamAdded', id);

    const processData = async () => {
      if (newDataStream.paused || this.globalPaused) return;

      try {
        const data = await newDataStream.fetcherCallback();

        for (const [key, value] of Object.entries(data)) {
          // Using a unique key to prevent duplicates
          const entryKey = `${newDataStream.id}-${uuidv4()}`;
          if (!newDataStream.entries.has(entryKey)) {
            newDataStream.entries.set(entryKey, { ...value, timestamp: new Date().getTime() });
          }
        }

        setTimeout(processData, 1000 / dataFetcherCallback.concurrency); // Adjust based on expected frequency
      } catch (error) {
        console.error(`Error fetching data for stream ${id}:`, error);
        this.emit('streamError', id, error);
      }
    };

    processData();
  }

  pauseStream(id) {
    const newDataStream = this.dataStreams.get(id);
    if (!newDataStream || !newDataStream.active) return;

    newDataStream.paused = true;
    this.emit('streamPaused', id);
  }

  resumeStream(id) {
    const newDataStream = this.dataStreams.get(id);
    if (!newDataStream || !newDataStream.active) return;

    newDataStream.paused = false;
    this.emit('streamResumed', id);
  }

  pauseAllStreams() {
    this.globalPaused = true;
    this.emit('allStreamsPaused');
  }

  resumeAllStreams() {
    this.globalPaused = false;
    for (const dataStream of this.dataStreams.values()) {
      if (dataStream.active && dataStream.paused) {
        dataStream.paused = false;
        this.emit('streamResumed', dataStream.id);
      }
    }
    this.emit('allStreamsResumed');
  }

  cleanupOldData() {
    const currentTime = Date.now();
    for (const [id, dataStream] of this.dataStreams.entries()) {
      if (!dataStream.active) continue;

      const entriesToKeep = new Map();

      for (const [key, entry] of dataStream.entries.entries()) {
        if (currentTime - entry.timestamp < this.retentionPeriodMs) {
          entriesToKeep.set(key, entry);
        } else {
          // Optionally integrate with an external database here
          console.log(`Archiving old entry from stream ${id}:`, key);
        }
      }

      dataStream.entries = entriesToKeep;
    }
  }

  shutdown() {
    this.dataStreams.forEach((stream) => {
      if (stream.active) {
        stream.active = false;
        this.emit('streamRemoved', stream.id);
      }
    });
    this.dataStreams.clear();
    console.log("Shutdown complete. All streams have been stopped.");
  }
}

module.exports = DataStreamManager;

// Usage example
const manager = new DataStreamManager(60 * 1000 * 60); // Retain data for 1 hour

manager.on('streamAdded', (id) => console.log(`Stream added: ${id}`));
manager.on('streamPaused', (id) => console.log(`Stream paused: ${id}`));
manager.on('streamResumed', (id) => console.log(`Stream resumed: ${id}`));
manager.on('allStreamsPaused', () => console.log("All streams have been paused."));
manager.on('allStreamsResumed', () => console.log("All streams have been resumed."));
manager.on('streamRemoved', (id) => console.log(`Stream removed: ${id}`));

// Example dataFetcherCallback for a stream
const exampleDataFetcher = async () => {
  // Simulate fetching data from an external source
  return { temperature: Math.random() * 100 };
};
exampleDataFetcher.concurrency = 5; // Expected frequency (adjust as needed)

manager.addDataStream('weatherStation1', exampleDataFetcher);
// Add more streams, pause/resume individually or globally as needed

// Shutdown the manager when no longer needed
// process.on('exit', () => manager.shutdown());
```']

['Below is a simplified implementation of a semaphore with the requested features in C. This example uses POSIX semaphores, atomic operations, and signal handling for resetting the semaphore. It includes basic logging and rate limiting.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define DEFAULT_SEMAPHORE_VALUE 5
#define CONFIG_FILE "config.txt"
#define MAX_THREADS 50
#define MAX_PROCESSES 10

sem_t semaphore;
int initial_value = DEFAULT_SEMAPHORE_VALUE;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to read configuration file
void read_config_file() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file) {
        fscanf(file, "%d", &initial_value);
        fclose(file);
    }
}

// Logging function
void log_operation(const char *operation, pid_t pid, int sem_value) {
    time_t now;
    time(&now);
    pthread_mutex_lock(&log_lock);
    printf("[%s] Process %d: %s, Semaphore Value: %d\n", ctime(&now), pid, operation, sem_value);
    pthread_mutex_unlock(&log_lock);
}

// Signal handler to reset semaphore
void handle_reset(int sig) {
    int value = initial_value;
    if (semctl(semaphore, 0, SETVAL, value) == -1) {
        perror("Failed to reset semaphore");
    }
    log_operation("Reset semaphore", getpid(), value);
}

// Initialize semaphore from config or command line
void initialize_semaphore(int argc, char *argv[]) {
    read_config_file();
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--sem-init") == 0 && i + 1 < argc) {
            initial_value = atoi(argv[++i]);
        }
    }

    sem_init(&semaphore, 1, initial_value);
    log_operation("Initialize semaphore", getpid(), initial_value);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_reset;
    sigaction(SIGUSR1, &sa, NULL);
}

// Semaphore acquire with timeout
int sem_acquire_with_timeout(int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    int result = sem_timedwait(&semaphore, &ts);
    if (result == -1 && errno == ETIMEDOUT) {
        log_operation("Timeout acquire", getpid(), sem_getvalue(&semaphore, NULL));
        return -1; // Timeout
    }
    log_operation("Acquire semaphore", getpid(), sem_getvalue(&semaphore, NULL));
    return 0; // Acquired
}

// Semaphore release
void sem_release() {
    sem_post(&semaphore);
    log_operation("Release semaphore", getpid(), sem_getvalue(&semaphore, NULL));
}

// Rate limiting mechanism
int rate_limit(int current_rate, int max_rate) {
    static pthread_mutex_t rate_lock = PTHREAD_MUTEX_INITIALIZER;
    static int current_operations = 0;

    pthread_mutex_lock(&rate_lock);
    if (current_operations >= max_rate) {
        pthread_mutex_unlock(&rate_lock);
        return -1; // Rate limit exceeded
    }
    current_operations++;
    pthread_mutex_unlock(&rate_lock);

    usleep(1000000 / max_rate); // Simulate rate limiting delay
    return 0;
}

// Export semaphore state
void export_semaphore_state(int sockfd) {
    int value = sem_getvalue(&semaphore, NULL);
    send(sockfd, &value, sizeof(value), 0);
}

// Unit test function (simplified)
void run_tests() {
    printf("Running unit tests...\n");
    initialize_semaphore(1, NULL);

    if (sem_acquire_with_timeout(100) != 0) {
        fprintf(stderr, "Test failed: Semaphore acquire with timeout\n");
    }
    sem_release();

    if (sigaction(SIGUSR1, NULL, NULL) == -1) {
        fprintf(stderr, "Test failed: Signal handling setup\n");
    }

    printf("All tests passed.\n");
}

int main(int argc, char *argv[]) {
    initialize_semaphore(argc, argv);

    // Example usage
    if (sem_acquire_with_timeout(1000) == 0) {
        // Critical section
        sem_release();
    } else {
        fprintf(stderr, "Failed to acquire semaphore within timeout\n");
    }

    run_tests();

    return 0;
}
```

### Key Points:
- **Configuration**: Reads initial semaphore value from a config file or command-line argument.
- **Logging**: Uses mutexes to ensure thread-safe logging without becoming a bottleneck.
- **Signal Handling**: Resets the semaphore on `SIGUSR1`.
- **Timeouts**: Supports acquiring the semaphore with a timeout.
- **Rate Limiting**: Simple rate limiting mechanism using mutexes and delays.
- **Export Mechanism**: Exports semaphore state via a socket (not fully implemented here).
- **Unit Tests**: Basic test setup to verify functionality.

This code is a starting point. You may need to adapt it for specific system requirements, handle errors more robustly, and expand the logging and export mechanisms as needed.']

