#define MAX_RECORDS 50000

// Function prototypes
void initialize_data(long seed, int max_value_range, long **offsets, int **keys, record ***records, node **nodes);
void update_record(node **nodes, int index, int new_value);
void access_records(node *nodes, int num_nodes);
void serialize_data(const char *filename, long offsets[], int keys[], record records[], node nodes[]);
int deserialize_data(const char *filename, long **offsets, int **keys, record ***records, node **nodes);

// Global variables for synchronization
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_data(long seed, int max_value_range, long **offsets, int **keys, record ***records, node **nodes) {
    srand(seed);

    *offsets = malloc(MAX_RECORDS * sizeof(long));
    *keys = malloc(MAX_RECORDS * sizeof(int));
    *records = malloc(MAX_RECORDS * sizeof(record *));
    *nodes = malloc(MAX_RECORDS * sizeof(node));

    if (!*offsets || !*keys || !*records || !*nodes) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*offsets)[i] = rand() % max_value_range;
        (*keys)[i] = i;

        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        (*records)[i]->value = rand() % max_value_range;

        pthread_mutex_init(&((*nodes)[i].lock), NULL);
        (*nodes)[i].record_ptr = (*records)[i];
        (*nodes)[i].ref_count = 1;
    }
}

void update_record(node **nodes, int index, int new_value) {
    if (index < 0 || index >= MAX_RECORDS) return;

    pthread_mutex_lock(&((*nodes)[index].lock));
    (*nodes)[index].record_ptr->value = new_value;
    ++(*nodes)[index].ref_count; // Simulating access
    pthread_mutex_unlock(&((*nodes)[index].lock));
}

void *access_records_thread(void *arg) {
    node **nodes = (node **)arg;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        pthread_mutex_lock(&((*nodes)[i].lock));
        (*nodes)[i].ref_count++; // Simulating access
        pthread_mutex_unlock(&((*nodes)[i].lock));
    }

    return NULL;
}

void access_records(node *nodes, int num_nodes) {
    pthread_t threads[100];
    for (int i = 0; i < 100; ++i) {
        if (pthread_create(&threads[i], NULL, access_records_thread, nodes)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void serialize_data(const char *filename, long offsets[], int keys[], record records[], node nodes[]) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(offsets, sizeof(long), MAX_RECORDS, file);
    fwrite(keys, sizeof(int), MAX_RECORDS, file);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        fwrite(&records[i]->value, sizeof(int), 1, file);
        fwrite(&(nodes[i].ref_count), sizeof(int), 1, file);
    }

    fclose(file);
}

int deserialize_data(const char *filename, long **offsets, int **keys, record ***records, node **nodes) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    *offsets = malloc(MAX_RECORDS * sizeof(long));
    *keys = malloc(MAX_RECORDS * sizeof(int));
    *records = malloc(MAX_RECORDS * sizeof(record *));
    *nodes = malloc(MAX_RECORDS * sizeof(node));

    if (!*offsets || !*keys || !*records || !*nodes) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    fread(*offsets, sizeof(long), MAX_RECORDS, file);
    fread(*keys, sizeof(int), MAX_RECORDS, file);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        fread(&((*records)[i]->value), sizeof(int), 1, file);

        (*nodes)[i].record_ptr = (*records)[i];
        fread(&(nodes[i].ref_count), sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

void cleanup(long *offsets, int *keys, record **records, node *nodes) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        free(records[i]);
        pthread_mutex_destroy(&nodes[i].lock);
    }

    free(offsets);
    free(keys);
    free(records);
    free(nodes);
}

int main() {
    long *offsets;
    int *keys;
    record **records;
    node *nodes;

    initialize_data(42, 1000, &offsets, &keys, &records, &nodes);

    access_records(nodes, MAX_RECORDS);

    serialize_data("data.bin", offsets, keys, *records, nodes);

    long *new_offsets;
    int *new_keys;
    record **new_records;
    node *new_nodes;

    if (deserialize_data("data.bin", &new_offsets, &new_keys, &new_records, &new_nodes) == 0) {
        // Successfully deserialized
    }

    cleanup(offsets, keys, records, nodes);
    cleanup(new_offsets, new_keys, new_records, new_nodes);

    return 0;
}
```']

["Below is a JavaScript implementation using modern Web APIs and Node.js concepts to create a robust data merging utility:

```javascript
// Required modules for file system operations and stream handling
const { Readable, Writable, pipeline } = require('stream');
const { once } = require('events');
const zlib = require('zlib'); // For compression/decompression

// Simulated external signals for pausing/resuming
let isPaused = false;
setInterval(() => {
  // Example logic to toggle pause state based on some condition
  isPaused = !isPaused; 
}, 10000);

// Custom error class for corrupted data handling
class CorruptedDataError extends Error {}

// Schema validation function (example schema)
function validateSchema(data) {
  if (!data || typeof data !== 'object') throw new CorruptedDataError('Invalid schema');
  // Add more validation logic as needed based on predefined schema
}

// Utility to manage network conditions and adapt ingestion rate
class NetworkManager {
  constructor() {
    this.currentRate = 1024; // Start with a base rate
    // Simulate dynamic adjustment of network conditions
    setInterval(() => {
      this.currentRate += Math.floor(Math.random() * 512 - 256);
      this.currentRate = Math.max(512, this.currentRate); // Set lower bounds
    }, 5000);
  }

  getAdaptiveRate() {
    return this.currentRate;
  }
}

// Main class for merging data streams
class DataMerger {
  constructor(sources) {
    this.sources = sources.map(source => new Readable({ objectMode: true }));
    this.networkManager = new NetworkManager();
    this.corruptedBlocks = 0;
    this.mergedData = [];
    this.metrics = { startTime: Date.now(), skippedCorrupt: 0 };

    // Implementing backpressure by managing the writable stream
    const mergedStream = new Writable({
      objectMode: true,
      write(chunk, encoding, callback) {
        if (isPaused) return setImmediate(callback); // Pause handling

        try {
          validateSchema(chunk);
          this.mergedData.push(chunk); // Simulated unified buffer storage
          callback();
        } catch (error) {
          console.error('Corrupted data block detected:', error.message);
          this.metrics.skippedCorrupt++;
          callback(new CorruptedDataError(error.message));
        }
      },
    });

    this.sources.forEach(source => source.on('data', chunk => {
      if (!isPaused) mergedStream.write(chunk);
    }));

    // Handling stream completion
    once(mergedStream, 'finish', () => console.log('Merging completed:', this.metrics));
  }

  start() {
    this.sources.forEach(source => {
      pipeline(
        source,
        zlib.createGunzip(), // Example: decompressing incoming data
        mergedStream,
        (err) => {
          if (err) console.error('Pipeline error:', err);
        }
      );
    });
  }

  getMetrics() {
    return this.metrics;
  }
}

// Usage example

const source1 = new Readable({ objectMode: true, read() {} });
source1.push({ id: 1, data: 'example' });
source1.push(null); // Signifies end of stream

const source2 = new Readable({ objectMode: true, read() {} });
source2.push({ id: 2, data: 'sample' });
source2.push(null);

const merger = new DataMerger([source1, source2]);
merger.start();
```

### Key Features:

- **Concurrency Handling:** Implemented using Node.js streams and pipelines to manage multiple data sources concurrently.
- **Corruption Detection:** Custom error handling for corrupted data blocks with schema validation.
- **Adaptive Rate Management:** Simulated network manager adjusts the ingestion rate based on dynamic conditions.
- **Pause/Resume Mechanism:** Demonstrated by periodically toggling `isPaused`.
- **Metrics Collection:** Tracks processing time and corrupted blocks."]

