    printf("%s\n", message);
}

int initialize_data_structures(long **offset_array, int **key_array, record ***record_array, void ***secondary_array, size_t num_records, unsigned int seed) {
    if (num_records > MAX_RECORDS) {
        log_message("Number of records exceeds maximum limit.");
        return -1;
    }

    // Seed the random number generator for reproducibility
    srand(seed);

    // Allocate memory for offset array
    *offset_array = malloc(num_records * sizeof(long));
    if (*offset_array == NULL) {
        log_message("Failed to allocate memory for offsets.");
        return -1;
    }
    memset(*offset_array, 0, num_records * sizeof(long));

    // Allocate memory for key array
    *key_array = malloc(num_records * sizeof(int));
    if (*key_array == NULL) {
        free(*offset_array);
        log_message("Failed to allocate memory for keys.");
        return -1;
    }
    memset(*key_array, 0, num_records * sizeof(int));

    // Allocate memory for the array of records
    *record_array = malloc(num_records * sizeof(record *));
    if (*record_array == NULL) {
        free(*offset_array);
        free(*key_array);
        log_message("Failed to allocate memory for record pointers.");
        return -1;
    }
    memset(*record_array, 0, num_records * sizeof(record *));

    // Allocate and initialize records
    for (size_t i = 0; i < num_records; ++i) {
        (*record_array)[i] = malloc(sizeof(record));
        if ((*record_array)[i] == NULL) {
            log_message("Failed to allocate memory for a record.");
            for (size_t j = 0; j <= i; ++j) {
                free((*record_array)[j]);
            }
            free(*offset_array);
            free(*key_array);
            free(*record_array);
            return -1;
        }

        // Initialize the record with a random value
        (*record_array)[i]->value = rand() % 1000; // Example: range of values from 0 to 999

        // Update offset and key for this record as an example
        (*offset_array)[i] = (long)i * sizeof(record);
        (*key_array)[i] = i;
    }

    // Allocate memory for secondary array of pointers to records
    *secondary_array = malloc(num_records * sizeof(void *));
    if (*secondary_array == NULL) {
        log_message("Failed to allocate memory for secondary array.");
        for (size_t i = 0; i < num_records; ++i) {
            free((*record_array)[i]);
        }
        free(*offset_array);
        free(*key_array);
        free(*record_array);
        return -1;
    }

    // Initialize the secondary array with pointers to records
    memcpy(*secondary_array, *record_array, num_records * sizeof(void *));

    log_message("Data structures initialized successfully.");
    return 0;
}

void cleanup_data_structures(long *offset_array, int *key_array, record **record_array, void **secondary_array, size_t num_records) {
    if (offset_array != NULL) free(offset_array);
    if (key_array != NULL) free(key_array);
    if (record_array != NULL) {
        for (size_t i = 0; i < num_records; ++i) {
            if (record_array[i] != NULL) free(record_array[i]);
        }
        free(record_array);
    }
    if (secondary_array != NULL) free(secondary_array);
}

// Unit test function to validate the implementation
