#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t lock;
    int *pending_updates; // bitmask for pending updates
} RecordsManager;

// Function prototypes
void initialize_records_manager(RecordsManager *manager, size_t initial_size);
void free_records_manager(RecordsManager *manager);
int fetch_updated_value(int key);
void *update_record(void *arg);

RecordsManager manager;

void initialize_records_manager(RecordsManager *manager, size_t initial_size) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->records = malloc(initial_size * sizeof(Record));
    manager->count = 0;
    manager->pending_updates = calloc((initial_size + 7) / 8, sizeof(int)); // bit mask for pending updates
}

void free_records_manager(RecordsManager *manager) {
    free(manager->records);
    free(manager->pending_updates);
    pthread_mutex_destroy(&manager->lock);
}

int fetch_updated_value(int key) {
    // Simulate fetching updated value from external source
    return key * 2; // Example transformation
}

void *update_record(void *arg) {
    int index = *(int *)arg;
    Record *record = &manager.records[index];

    pthread_mutex_lock(&manager.lock);
    if (manager.pending_updates[index / 8] & (1 << (index % 8))) {
        record->value = fetch_updated_value(record->key);
        manager.pending_updates[index / 8] &= ~(1 << (index % 8)); // clear pending update
    }
    pthread_mutex_unlock(&manager.lock);

    return NULL;
}

void process_updates() {
    for (size_t i = 0; i < manager.count; ++i) {
        int index = i;
        pthread_t thread;
        pthread_create(&thread, NULL, update_record, &index);
        pthread_detach(thread); // Detach the thread to handle updates asynchronously
    }
}

void add_record(int key, int value) {
    pthread_mutex_lock(&manager.lock);
    manager.records[manager.count].key = key;
    manager.records[manager.count].value = value;
    ++manager.count;
    pthread_mutex_unlock(&manager.lock);
}

void mark_pending_update(size_t index) {
    pthread_mutex_lock(&manager.lock);
    manager.pending_updates[index / 8] |= (1 << (index % 8));
    pthread_mutex_unlock(&manager.lock);
}

// Example usage
int main() {
    initialize_records_manager(&manager, 10);

    add_record(1, 100);
    add_record(2, 200);

    mark_pending_update(0); // Mark the first record for update

    process_updates();

    // Simulate waiting for updates to complete
    sleep(1);

    for (size_t i = 0; i < manager.count; ++i) {
        printf("Record %zu: key=%d, value=%d\n", i, manager.records[i].key, manager.records[i].value);
    }

    free_records_manager(&manager);
    return 0;
}
```']

