typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp;
    char unique_id[64];
} Record;

typedef struct {
    int *parent;
    pthread_mutex_t lock;
} UnionFind;

// Function declarations
int find(UnionFind uf, int x);
void union_sets(UnionFind uf, int x, int y);
long calculate_memory_usage(size_t long_count, size_t int_count, size_t record_count, size_t id_count);
void process_batch(char *csv_file, size_t batch_size, UnionFind uf);
char* generate_unique_id();
int parse_csv_and_initialize_arrays(const char* csv_file, Record **records, size_t *size);

// Union-Find functions
int find(UnionFind uf, int x) {
    if (uf.parent[x] != x)
        uf.parent[x] = find(uf, uf.parent[x]);
    return uf.parent[x];
}

void union_sets(UnionFind uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY)
        uf.parent[rootY] = rootX;
}

// Main function to process records
void dynamic_memory_management(const char *csv_file) {
    size_t total_size = 0;
    Record *records = NULL;

    // Parse CSV and initialize arrays
    if (!parse_csv_and_initialize_arrays(csv_file, &records, &total_size)) {
        fprintf(stderr, "Failed to parse CSV file.\n");
        return;
    }

    UnionFind uf;
    uf.parent = malloc(total_size * sizeof(int));
    pthread_mutex_init(&uf.lock, NULL);

    for (size_t i = 0; i < total_size; ++i)
        uf.parent[i] = i;

    size_t batch_count = (total_size + BATCH_SIZE - 1) / BATCH_SIZE;

    for (size_t b = 0; b < batch_count; ++b) {
        process_batch(csv_file, BATCH_SIZE, uf);

        // Free current batch memory
        free(records);
        records = NULL;

        // Recalculate size if needed and reallocate
        parse_csv_and_initialize_arrays(csv_file, &records, &total_size);
    }

    // Cleanup
    pthread_mutex_destroy(&uf.lock);
    free(uf.parent);
}

// Helper functions

long calculate_memory_usage(size_t long_count, size_t int_count, size_t record_count, size_t id_count) {
    return (long_count * sizeof(long)) + 
           (int_count * sizeof(int)) +
           (record_count * sizeof(Record)) + 
           (id_count * sizeof(char) * 64);
}

void process_batch(char *csv_file, size_t batch_size, UnionFind uf) {
    Record *records = NULL;
    size_t total_size = 0;

    parse_csv_and_initialize_arrays(csv_file, &records, &total_size);

    time_t start_time = time(NULL);

    for (size_t i = 0; i < batch_size && i < total_size; ++i) {
        // Randomly populate values
        records[i].value = rand() % RANDOM_RANGE_MAX;

        // Perform Union-Find operations
        pthread_mutex_lock(&uf.lock);
        int parent1 = find(uf, records[i].key);
        int parent2 = find(uf, records[i].value);

        if (parent1 != parent2) {
            union_sets(uf, parent1, parent2);
        }

        pthread_mutex_unlock(&uf.lock);
    }

    time_t end_time = time(NULL);
    printf("Time taken for disjointness checks: %ld seconds\n", end_time - start_time);

    free(records);
}

char* generate_unique_id() {
    static char id[64];
    snprintf(id, sizeof(id), "%lx", (unsigned long)time(NULL));
    return id;
}

int parse_csv_and_initialize_arrays(const char *csv_file, Record **records, size_t *size) {
