#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Define maximum memory usage (e.g., 1MB)
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

typedef struct {
    long offset;
    int key;
    int value;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long calculate_max_array_size(int element_size) {
    return MAX_MEMORY_USAGE / element_size;
}

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned_alloc(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

int initialize_arrays(long *offsets, int *keys, int array_size) {
    if (!offsets || !keys || array_size <= 0) return -1;

    for (int i = 0; i < array_size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % RANDOM_RANGE_MAX + RANDOM_RANGE_MIN;
    }
    return 0;
}

int* generate_unique_random_values(int *keys, int size, int range_min, int range_max) {
    if (!keys || size <= 0) return NULL;

    int *random_values = (int *)malloc(size * sizeof(int));
    if (!random_values) return NULL;

    for (int i = 0; i < size; ++i) {
        int value;
        do {
            value = rand() % (range_max - range_min + 1) + range_min;
        } while (contains_key(keys, size, value));
        random_values[i] = value;
    }
    return random_values;
}

int contains_key(int *keys, int size, int key) {
    for (int i = 0; i < size; ++i) {
        if (keys[i] == key) return 1;
    }
    return 0;
}

void initialize_records(record *records, long *offsets, int *keys, int size, int range_min, int range_max) {
    if (!records || !offsets || !keys || size <= 0) return;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < size; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];

        int* random_values = generate_unique_random_values(keys, size, range_min, range_max);
        if (!random_values) {
            fprintf(stderr, "Failed to allocate memory for unique random values\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        records[i].value = random_values[i];
        free(random_values);
    }
    pthread_mutex_unlock(&lock);
}

void cleanup(void *ptr) {
    if (ptr) free_aligned_alloc(ptr);
}

int main() {
    int array_size;
    printf("Enter the size of arrays: ");
    scanf("%d", &array_size);

    long max_long_array_size = calculate_max_array_size(sizeof(long));
    int max_int_array_size = calculate_max_array_size(sizeof(int));

    if (array_size > max_long_array_size || array_size > max_int_array_size) {
        fprintf(stderr, "Requested size exceeds memory limits\n");
        return -1;
    }

    long *offsets = aligned_alloc(64, array_size * sizeof(long));
    int *keys = aligned_alloc(64, array_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup(offsets);
        cleanup(keys);
        return -1;
    }

    if (initialize_arrays(offsets, keys, array_size) != 0) {
        cleanup(offsets);
        cleanup(keys);
        return -1;
    }

    int records_size = array_size; // Assuming same size for simplicity
    record *records = aligned_alloc(64, records_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup(offsets);
        cleanup(keys);
        return -1;
    }

    initialize_records(records, offsets, keys, records_size, RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);

    // Example use of records
    for (int i = 0; i < records_size; ++i) {
        printf("Record %d: Offset=%ld Key=%d Value=%d\n", i, records[i].offset, records[i].key, records[i].value);
    }

    cleanup(offsets);
    cleanup(keys);
    cleanup(records);

    return 0;
}
