import "cJSON.h"

// Define the struct item
typedef struct {
    char *name;
    int value;
} item;

// Define the context structure
typedef struct {
    item **items;
} context;

// Function to dynamically allocate and initialize arrays based on configuration from JSON file
int initialize_arrays(context *ctx, double **dArray, char **cArray, size_t config_size) {
    // Configuration settings
    FILE *file = fopen("/config/settings.json", "r");
    if (!file) {
        perror("Unable to open the configuration file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *json_text = (char *)malloc(length + 1);
    if (!json_text) {
        fclose(file);
        perror("Memory allocation failed for JSON text");
        return -1;
    }

    fread(json_text, 1, length, file);
    json_text[length] = '\0';
    fclose(file);

    cJSON *json_root = cJSON_Parse(json_text);
    free(json_text);
    if (!json_root) {
        fprintf(stderr, "Error parsing JSON configuration\n");
        return -1;
    }

    int num_items = cJSON_GetObjectItemCaseSensitive(json_root, "num_items")->valueint;
    int min_value = cJSON_GetObjectItemCaseSensitive(json_root, "min_value")->valueint;
    int max_value = cJSON_GetObjectItemCaseSensitive(json_root, "max_value")->valueint;

    // Validate JSON values
    if (num_items <= 0 || max_value <= min_value) {
        cJSON_Delete(json_root);
        return -1;
    }

    *ctx = malloc(sizeof(struct context));
    if (!*ctx) {
        fprintf(stderr, "Memory allocation failed for context\n");
        cJSON_Delete(json_root);
        return -1;
    }

    (*ctx)->items = (item **)malloc(num_items * sizeof(item *));
    if (!(*ctx)->items) {
        free(*ctx);
        fprintf(stderr, "Memory allocation failed for item pointers\n");
        cJSON_Delete(json_root);
        return -1;
    }

    // Define a pool of keywords
    char *keywords[] = {"Alpha", "Beta", "Gamma", "Delta", "Epsilon"};
    size_t keyword_count = sizeof(keywords) / sizeof(char *);

    // Allocate memory for arrays and initialize
    if (!(*dArray = (double *)malloc(num_items * sizeof(double))) ||
        !(*cArray = (char *)malloc(config_size * num_items * sizeof(char)))) {
        fprintf(stderr, "Memory allocation failed\n");
        free((*ctx)->items);
        free(*ctx);
        cJSON_Delete(json_root);
        return -1;
    }

    // Generate unique strings and initialize items
    for (int i = 0; i < num_items; ++i) {
        int random_idx = rand() % keyword_count;

        item *itm = malloc(sizeof(item));
        if (!itm) {
            fprintf(stderr, "Memory allocation failed for item\n");
            cJSON_Delete(json_root);
            free((*ctx)->items[i - 1]);
            for (int j = 0; j < i; ++j) {
                free((*ctx)->items[j]->name);
                free((*ctx)->items[j]);
            }
            free(*dArray);
            free(*cArray);
            free((*ctx)->items);
            free(*ctx);
            return -1;
        }

        itm->name = strdup(keywords[random_idx]);
        if (!itm->name) {
            fprintf(stderr, "Memory allocation failed for item name\n");
            cJSON_Delete(json_root);
            free(itm);
            free((*ctx)->items[i - 1]);
            for (int j = 0; j < i; ++j) {
                free((*ctx)->items[j]->name);
                free((*ctx)->items[j]);
            }
            free(*dArray);
            free(*cArray);
            free((*ctx)->items);
            free(*ctx);
            return -1;
        }

        itm->value = rand() % (max_value - min_value + 1) + min_value;

        (*dArray)[i] = (double)(rand() / (RAND_MAX + 1.0));
        memset((*cArray) + i * config_size, 'A' + i % 26, config_size);

        (*ctx)->items[i] = itm;
    }

    cJSON_Delete(json_root);

    return 0; // Success
}
