#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example: 1 MB limit

typedef struct {
    int value;
} record;

// Function prototypes
int initialize_arrays(size_t long_array_size, size_t int_key_size, size_t record_count, long** offset_array, int** key_array, record** records);
void free_memory(long* offset_array, int* key_array, record* records, size_t record_count);
void populate_records(record* records, size_t record_count, int min_val, int max_val);
int validate_uniqueness(long* offset_array, int* key_array, size_t long_array_size, size_t int_key_size);
void sort_records(record* records, size_t record_count);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initialize_arrays(size_t long_array_size, size_t int_key_size, size_t record_count, long** offset_array, int** key_array, record** records) {
    pthread_mutex_lock(&mutex);

    size_t total_memory_usage;
    do {
        *offset_array = (long*)malloc(long_array_size * sizeof(long));
        *key_array = (int*)malloc(int_key_size * sizeof(int));
        *records = (record*)malloc(record_count * sizeof(record));

        if (!*offset_array || !*key_array || !*records) {
            size_t new_record_count = record_count / 2;
            free(*offset_array);
            free(*key_array);
            free(*records);

            long_array_size /= 2;
            int_key_size /= 2;
            record_count = new_record_count;

            *offset_array = (long*)malloc(long_array_size * sizeof(long));
            *key_array = (int*)malloc(int_key_size * sizeof(int));
            *records = (record*)malloc(record_count * sizeof(record));

            if (!*offset_array || !*key_array || !*records) {
                pthread_mutex_unlock(&mutex);
                return -1; // Memory allocation failed
            }
        }

        total_memory_usage = long_array_size * sizeof(long) + int_key_size * sizeof(int) + record_count * sizeof(record);

    } while (total_memory_usage > MAX_MEMORY_USAGE);

    populate_records(*records, record_count, 0, 100); // Example range: 0 to 100

    if (!validate_uniqueness(*offset_array, *key_array, long_array_size, int_key_size)) {
        pthread_mutex_unlock(&mutex);
        free_memory(*offset_array, *key_array, *records, record_count);
        return -1; // Validation failed
    }

    sort_records(*records, record_count);

    pthread_mutex_unlock(&mutex);
    return 0;
}

void free_memory(long* offset_array, int* key_array, record* records, size_t record_count) {
    free(offset_array);
    free(key_array);
    free(records);
}

void populate_records(record* records, size_t record_count, int min_val, int max_val) {
    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

int validate_uniqueness(long* offset_array, int* key_array, size_t long_array_size, size_t int_key_size) {
    for (size_t i = 0; i < long_array_size; ++i) {
        for (size_t j = i + 1; j < long_array_size; ++j) {
            if (offset_array[i] == offset_array[j]) return 0;
        }
    }

    for (size_t i = 0; i < int_key_size; ++i) {
        for (size_t j = i + 1; j < int_key_size; ++j) {
            if (key_array[i] == key_array[j]) return 0;
        }
    }

    return 1;
}

void sort_records(record* records, size_t record_count) {
    // Simple insertion sort for demonstration
    for (size_t i = 1; i < record_count; ++i) {
        record key = records[i];
        int j = i - 1;

        while (j >= 0 && records[j].value > key.value) {
            records[j + 1] = records[j];
            --j;
        }
        records[j + 1] = key;
    }
}

int main() {
    long* offset_array;
    int* key_array;
    record* records;

    if (initialize_arrays(100, 50, 200, &offset_array, &key_array, &records) == 0) {
        // Use the arrays
    }

    free_memory(offset_array, key_array, records, 200);
    return 0;
}
