#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_RETRIES 3
#define ALERT_THRESHOLD_MS 1000
#define CACHE_UPDATE_INTERVAL_SEC 60

typedef struct {
    int key;
    long offset;
} record;

typedef enum {
    SUCCESS = 0,
    ALLOCATION_FAILURE,
    INVALID_OFFSET,
    DUPLICATE_KEY,
    DUPLICATE_OFFSET,
    RETRIEVAL_FAILURE
} status_code_t;

typedef struct {
    size_t total_memory_limit;
    size_t allocated_memory;
    record **records;
    size_t num_records;
} memory_manager_t;

bool is_duplicate_key(int key, int *existing_keys, size_t size);
bool is_duplicate_offset(long offset, long *existing_offsets, size_t size);

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

int random_int_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

status_code_t allocate_memory(memory_manager_t *manager, size_t num_records, long offset_size, int key_size) {
    manager->allocated_memory = num_records * sizeof(record *) +
                                num_records * (sizeof(int) + offset_size);

    if (manager->allocated_memory > manager->total_memory_limit) {
        return ALLOCATION_FAILURE;
    }

    manager->records = (record **)calloc(num_records, sizeof(record *));
    if (!manager->records) return ALLOCATION_FAILURE;

    for (size_t i = 0; i < num_records; ++i) {
        manager->records[i] = (record *)malloc(sizeof(int) + offset_size);
        if (!manager->records[i]) {
            // Free previously allocated records on failure
            while (i--) free(manager->records[i]);
            free(manager->records);
            return ALLOCATION_FAILURE;
        }
    }

    manager->num_records = num_records;
    return SUCCESS;
}

void deallocate_memory(memory_manager_t *manager) {
    if (manager->records) {
        for (size_t i = 0; i < manager->num_records; ++i) {
            free(manager->records[i]);
        }
        free(manager->records);
        manager->allocated_memory = 0;
        manager->num_records = 0;
    }
}

status_code_t initialize_records(memory_manager_t *manager, int min_value, int max_value,
                                long offsets[], int keys[], size_t num_offsets, size_t num_keys) {
    int *existing_keys = (int *)calloc(manager->num_records, sizeof(int));
    long *existing_offsets = (long *)calloc(manager->num_records, sizeof(long));

    for (size_t i = 0; i < manager->num_records; ++i) {
        // Allocate and initialize records
        if (!manager->records[i]) continue;

        int key;
        bool valid_key = false;
        while (!valid_key && num_keys--) {
            key = keys[--num_keys];
            valid_key = !is_duplicate_key(key, existing_keys, i);
        }

        long offset;
        bool valid_offset = false;
        while (!valid_offset && num_offsets--) {
            offset = offsets[--num_offsets];
            valid_offset = !is_duplicate_offset(offset, existing_offsets, i);
        }

        if (!valid_key || !valid_offset) {
            deallocate_memory(manager);
            free(existing_keys);
            free(existing_offsets);
            return ALLOCATION_FAILURE;
        }

        // Set key and random int
        manager->records[i]->key = key;
        manager->records[i] += 1;  // Move pointer to offset location in record

        *manager->records[i] = random_int_in_range(min_value, max_value);

        existing_keys[i] = key;
        existing_offsets[i] = offset;
    }

    free(existing_keys);
    free(existing_offsets);
    return SUCCESS;
}

bool is_duplicate_key(int key, int *existing_keys, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (existing_keys[i] == key) return true;
    }
    return false;
}

bool is_duplicate_offset(long offset, long *existing_offsets, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (existing_offsets[i] == offset) return true;
    }
    return false;
}

void log_performance(unsigned int start_time, unsigned int end_time) {
    unsigned int duration_ms = (end_time - start_time);
    if (duration_ms > ALERT_THRESHOLD_MS) {
        printf("Performance Alert: Duration %u ms exceeds threshold.\n", duration_ms);
    }
}

unsigned int get_current_time_ms() {
    struct timespec spec;
    clock_gettime(CLOCK_REALTIME, &spec);
    return (unsigned int)(spec.tv_sec * 1000 + spec.tv_nsec / 1e6);
}

int main() {
    memory_manager_t manager = { .total_memory_limit = 1024 * 1024 }; // 1MB limit

    long offsets[] = {101, 202, 303};  // Example offset array
    int keys[] = {1001, 2002, 3003};   // Example key array

    if (allocate_memory(&manager, 3, sizeof(long), sizeof(int)) != SUCCESS) {
        fprintf(stderr, "Failed to allocate memory\n");
        return ALLOCATION_FAILURE;
    }

    unsigned int start_time = get_current_time_ms();
    status_code_t result = initialize_records(&manager, 10, 100, offsets, keys,
                                              sizeof(offsets)/sizeof(long), sizeof(keys)/sizeof(int));
    unsigned int end_time = get_current_time_ms();

    log_performance(start_time, end_time);

    if (result != SUCCESS) {
        fprintf(stderr, "Failed to initialize records\n");
    } else {
        printf("Records initialized successfully.\n");
    }

    deallocate_memory(&manager);
    return result;
}
```

This C program defines a memory manager for handling arrays of `record` structures with an integer key and long offset. The code includes robust error handling, dynamic allocation strategies, performance monitoring, and validation of unique keys and offsets.

Key features include:

