#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for records
typedef struct {
    int key;
    double value;
    size_t offsets_size;
    long *offsets; // Dynamic array of long integers
} Record;

// Define the collection structure
typedef struct {
    size_t size;
    size_t capacity;
    Record **records;
} Collection;

// Function prototypes
void init_collection(Collection *collection);
void free_collection(Collection *collection);
int insert_record(Collection *collection, int key, double value, const long *offsets, size_t offsets_size);
int delete_record(Collection *collection, int key);
Record* find_record(const Collection *collection, int key);
void resize_if_needed(Collection *collection);

// Function implementations

void init_collection(Collection *collection) {
    collection->size = 0;
    collection->capacity = 10; // Initial capacity
    collection->records = malloc(collection->capacity * sizeof(Record *));
}

void free_record(Record *record) {
    if (record) {
        free(record->offsets);
        free(record);
    }
}

void free_collection(Collection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free_record(collection->records[i]);
    }
    free(collection->records);
}

int insert_record(Collection *collection, int key, double value, const long *offsets, size_t offsets_size) {
    resize_if_needed(collection);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i]->key == key) {
            return -1; // Key already exists
        }
    }

    Record *new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->offsets_size = offsets_size;
    new_record->offsets = malloc(offsets_size * sizeof(long));

    if (!new_record || !new_record->offsets) {
        free(new_record);
        return -1; // Memory allocation failed
    }

    memcpy(new_record->offsets, offsets, offsets_size * sizeof(long));

    collection->records[collection->size++] = new_record;
    return 0;
}

int delete_record(Collection *collection, int key) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i]->key == key) {
            free_record(collection->records[i]);
            collection->records[i] = collection->records[--collection->size];
            return 0;
        }
    }
    return -1; // Key not found
}

Record* find_record(const Collection *collection, int key) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i]->key == key) {
            return collection->records[i];
        }
    }
    return NULL;
}

void resize_if_needed(Collection *collection) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));

        if (!new_records) {
            return; // Handle memory allocation failure gracefully
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }
}

// Example main function to demonstrate usage
int main() {
    Collection collection;
    init_collection(&collection);

    long offsets[] = {1, 2, 3};
    insert_record(&collection, 10, 20.5, offsets, sizeof(offsets) / sizeof(offsets[0]));

    Record *found = find_record(&collection, 10);
    if (found) {
        printf("Found record: key=%d, value=%.1f\n", found->key, found->value);
    }

    delete_record(&collection, 10);
    free_collection(&collection);

    return 0;
}
```

