import requests
from cachetools import TTLCache, cached
from ratelimit import limits, sleep_and_retry
import logging

# Set up basic configuration for logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class UserAPIClient:
    def __init__(self, api_key: str, cache_ttl: int = 300, max_cache_size: int = 1000):
        self.api_base_url = "https://api.usermanagement.com"
        self.api_key = api_key
        self.cache = TTLCache(maxsize=max_cache_size, ttl=cache_ttl)

    @sleep_and_retry
    @limits(calls=10, period=60)  # Adjust rate limit as per API constraints (10 calls/minute here)
    def fetch_user_details(self, user_ids: list[str], role: str = None, status: str = None) -> dict:
        results = {}

        for user_id in user_ids:
            try:
                cached_result = self.get_cached_user_details(user_id)
                if cached_result:
                    logger.info(f"Cache hit for user {user_id}")
                    results[user_id] = cached_result
                    continue

                response = requests.get(
                    f"{self.api_base_url}/users/{user_id}",
                    headers={"Authorization": f"Bearer {self.api_key}"}
                )

                if response.status_code == 404:
                    logger.warning(f"User ID {user_id} not found.")
                    results[user_id] = None
                    continue

                response.raise_for_status()

                user_data = response.json()

                # Filter based on role and status, if specified
                if (role and user_data.get("role") != role) or (status and user_data.get("status") != status):
                    logger.info(f"User {user_id} does not match the filtering criteria.")
                    results[user_id] = None
                    continue

                # Cache the response for future requests
                self.cache_user_details(user_id, user_data)

                results[user_id] = {
                    "name": user_data.get("name"),
                    "email": user_data.get("email"),
                    "phone": user_data.get("phone")
                }

            except requests.exceptions.HTTPError as e:
                logger.error(f"HTTP error for user {user_id}: {e}")
                results[user_id] = None
            except requests.exceptions.RequestException as e:
                logger.error(f"Request exception for user {user_id}: {e}")
                results[user_id] = None

        return results

    @cached(cache=lambda self: self.cache)
    def get_cached_user_details(self, user_id):
        return self.cache.get(user_id)

    def cache_user_details(self, user_id, data):
        self.cache[user_id] = {
            "name": data.get("name"),
            "email": data.get("email"),
            "phone": data.get("phone")
        }

# Example usage
if __name__ == "__main__":
    api_client = UserAPIClient(api_key="your_api_key_here")
    user_details = api_client.fetch_user_details(["123", "456"], role="admin")
    print(user_details)
```

### Key Points:
- **Caching**: Uses `cachetools.TTLCache` for caching user details with a time-to-live (TTL) strategy.
- **Rate Limiting**: Implements rate limiting using the `ratelimit` library to prevent exceeding API usage limits.
- **Error Handling**: Handles potential network issues and invalid responses robustly, including logging warnings and errors.
- **Filtering**: Supports filtering based on user roles or statuses.
- **Logging**: Logs essential information for auditing purposes without excessive verbosity.']

