#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *buffer;
    size_t length;
} message;

// Define a structure for handling the context of our cryptographic operations
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned long *nonces;
    unsigned int *key_ids;
    message *messages;
    size_t num_messages;
} CryptoContext;

int init_crypto_context(CryptoContext *crypto_ctx, size_t num_messages, const char *cipher_name, 
                        const unsigned char *iv) {
    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();

    // Allocate memory for contexts and arrays
    crypto_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!crypto_ctx->ctx) return -1;

    crypto_ctx->nonces = (unsigned long *)malloc(num_messages * sizeof(unsigned long));
    crypto_ctx->key_ids = (unsigned int *)malloc(num_messages * sizeof(unsigned int));
    crypto_ctx->messages = (message *)malloc(num_messages * sizeof(message));

    if (!crypto_ctx->nonces || !crypto_ctx->key_ids || !crypto_ctx->messages) {
        // Free allocated resources in case of failure
        EVP_CIPHER_CTX_free(crypto_ctx->ctx);
        free(crypto_ctx->nonces);
        free(crypto_ctx->key_ids);
        free(crypto_ctx->messages);
        return -1;
    }

    crypto_ctx->num_messages = num_messages;

    // Initialize each message structure
    for (size_t i = 0; i < num_messages; ++i) {
        crypto_ctx->messages[i].buffer = NULL;
        crypto_ctx->messages[i].length = 0;

        // Allocate nonce and key ID
        if (!RAND_bytes((unsigned char *)&crypto_ctx->nonces[i], sizeof(crypto_ctx->nonces[i]))) return -1;
        crypto_ctx->key_ids[i] = rand(); // Use a better key derivation function in practice

        // Initialize cipher context for each message
        if (EVP_EncryptInit_ex(crypto_ctx->ctx, EVP_get_cipherbyname(cipher_name), NULL, NULL, iv) != 1)
            return -1;
    }

    return 0; // Success
}

void free_crypto_context(CryptoContext *crypto_ctx) {
    for (size_t i = 0; i < crypto_ctx->num_messages; ++i) {
        if (crypto_ctx->messages[i].buffer) {
            OPENSSL_cleanse(crypto_ctx->messages[i].buffer, crypto_ctx->messages[i].length);
            free(crypto_ctx->messages[i].buffer);
        }
    }

    // Free allocated arrays
    free(crypto_ctx->nonces);
    free(crypto_ctx->key_ids);
    free(crypto_ctx->messages);

    // Destroy the cipher context
    EVP_CIPHER_CTX_free(crypto_ctx->ctx);
}

EVP_CIPHER_CTX *get_cipher_context(CryptoContext *crypto_ctx, size_t message_index) {
    return crypto_ctx->ctx;
}
