const fs = require('fs');
const path = require('path');
const axios = require('axios');

async function fetchAndProcessData(url, apiKey, destinationPath) {
    const activeApiKeys = ['validApiKey1', 'validApiKey2']; // Predefined list of active keys

    // Function to validate the URL
    async function isValidUrl(apiEndpoint) {
        try {
            const response = await axios.get(apiEndpoint, { method: 'HEAD' });
            return response.status === 200;
        } catch (error) {
            return false;
        }
    }

    // Validate API Key
    function isApiKeyValid(key) {
        return activeApiKeys.includes(key);
    }

    if (!isValidUrl(url)) {
        return { status: 'Invalid URL', content: null, fileOperationSuccess: false };
    }

    if (!isApiKeyValid(apiKey)) {
        return { status: 'Invalid API Key', content: null, fileOperationSuccess: false };
    }

    try {
        const response = await axios.get(url, {
            headers: {
                'Authorization': `Bearer ${apiKey}`
            }
        });

        // Ensure the destination directory exists
        const dirName = path.dirname(destinationPath);
        if (!fs.existsSync(dirName)) {
            fs.mkdirSync(dirName, { recursive: true });
        }

        // Check if the file is writable or create it with appropriate permissions
        let fileExists;
        try {
            fs.accessSync(destinationPath, fs.constants.F_OK | fs.constants.W_OK);
            fileExists = true;
        } catch (err) {
            fileExists = false;
        }

        const writeStream = fs.createWriteStream(destinationPath, { flags: 'a' });

        // Write JSON response to the file
        await new Promise((resolve, reject) => {
            writeStream.write(JSON.stringify(response.data), (err) => {
                if (err) return reject(err);
                resolve();
            });
        });

        writeStream.end();

        return { status: 'Success', content: response.data, fileOperationSuccess: true };
    } catch (error) {
        return { status: 'Error', content: error.message, fileOperationSuccess: false };
    }
}

module.exports = fetchAndProcessData;
```

