        free(records[i].data);
    }
    free(records);

    log_message("Finished record processing.");
}

void cleanup_resources() {
    // Implement resource cleanup logic
    pthread_mutex_destroy(&config_cache_lock);
}

int main(int argc, char *argv[]) {
