                arraySize = std::min(maxRecords, static_cast<size_t>(atoi((const char*)content)));
                xmlFree(content);
            } else if (std::string((const char*)cur->name) == "NumOffsets") {
                xmlChar* content = xmlNodeGetContent(cur);
                numOffsets = atoi((const char*)content);
                xmlFree(content);
            } else if (std::string((const char*)cur->name) == "NumKeys") {
                xmlChar* content = xmlNodeGetContent(cur);
                numKeys = atoi((const char*)content);
                xmlFree(content);
            } else if (std::string((const char*)cur->name) == "ValueRange") {
                xmlNodePtr minNode = cur->children;
                xmlNodePtr maxNode = minNode->next;
                minValue = atoi((const char*)xmlNodeGetContent(minNode));
                maxValue = atoi((const char*)xmlNodeGetContent(maxNode));
                xmlFree(xmlNodeGetContent(minNode));
                xmlFree(xmlNodeGetContent(maxNode));
            }
        }
    }

    std::vector<Record> records(arraySize);
    long* offsets = new (std::nothrow) long[numOffsets];
    int* keys = new (std::nothrow) int[numKeys];

    if (!records.size() || !offsets || !keys) {
        logMessage("Memory allocation failed.");
        xmlFreeDoc(doc);
        return -1;
    }

    std::mt19937 rng(static_cast<unsigned int>(time(nullptr)));
    std::uniform_int_distribution<int> dist(minValue, maxValue);

    for (size_t i = 0; i < arraySize; ++i) {
        records[i].value = dist(rng);
    }

    logMessage("Configuration loaded successfully.");
    logMessage("Number of records created: " + std::to_string(arraySize));
    logMessage("Offset count: " + std::to_string(numOffsets) + ", Key count: " + std::to_string(numKeys));

    delete[] offsets;
    delete[] keys;

    xmlFreeDoc(doc);
    xmlCleanupParser();

    return 0;
