#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRING_LENGTH 256

typedef struct data_entry {
    double number;
    char string[MAX_STRING_LENGTH];
    struct data_entry *next;
} data_entry;

typedef struct database {
    data_entry *head;
    size_t count;
} database;

// Function to create a new data entry
data_entry* create_data_entry(double number, const char *string) {
    data_entry *entry = (data_entry*)malloc(sizeof(data_entry));
    if (!entry) return NULL;

    entry->number = number;
    strncpy(entry->string, string, MAX_STRING_LENGTH - 1);
    entry->string[MAX_STRING_LENGTH - 1] = '\0'; // Ensure null-termination
    entry->next = NULL;

    return entry;
}

// Function to initialize the database
database* init_database() {
    database *db = (database*)malloc(sizeof(database));
    if (!db) return NULL;

    db->head = NULL;
    db->count = 0;
    return db;
}

// Function to add a data entry to the database
int add_data_entry(database *db, double number, const char *string) {
    if (!db) return -1;

    data_entry *entry = create_data_entry(number, string);
    if (!entry) return -1; // Memory allocation failed

    entry->next = db->head;
    db->head = entry;
    db->count++;

    return 0;
}

// Function to find a data entry by number
data_entry* find_by_number(database *db, double number) {
    if (!db || !db->head) return NULL;

    for (data_entry *current = db->head; current != NULL; current = current->next) {
        if (current->number == number) {
            return current;
        }
    }

    return NULL;
}

// Function to find a data entry by string
data_entry* find_by_string(database *db, const char *string) {
    if (!db || !db->head || !string) return NULL;

    for (data_entry *current = db->head; current != NULL; current = current->next) {
        if (strcmp(current->string, string) == 0) {
            return current;
        }
    }

    return NULL;
}

// Function to free all data entries in the database
void free_database(database *db) {
    if (!db) return;

    data_entry *current = db->head;
    while (current != NULL) {
        data_entry *next = current->next;
        free(current);
        current = next;
    }

    free(db);
}

// Example usage
int main() {
    database *db = init_database();
    if (!db) {
        fprintf(stderr, "Failed to initialize database\n");
        return 1;
    }

    add_data_entry(db, 3.14, "Pi");
    add_data_entry(db, 2.71, "Euler's Number");

    data_entry *entry = find_by_number(db, 3.14);
    if (entry) {
        printf("Found entry: %f, %s\n", entry->number, entry->string);
    }

    free_database(db);

    return 0;
}
