['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <unordered_set>
#include <algorithm>
#include <memory>
#include <stdexcept>

class DataProcessor {
public:
    struct UserInfo {
        std::string name;
        int age;
        std::string email;

        bool operator<(const UserInfo& other) const {
            return name < other.name;
        }
    };

private:
    std::vector<UserInfo> users_;
    std::unordered_set<std::string> uniqueEmails_;

public:
    DataProcessor(const std::string& filename) {
        loadFromFile(filename);
    }

    void loadFromFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Cannot open file: " + filename);
        }

        std::string line;
        while (std::getline(file, line)) {
            try {
                auto user = parseLine(line);
                if (user && uniqueEmails_.insert(user->email).second) {
                    users_.emplace_back(*user);
                }
            } catch (const std::invalid_argument&) {
                // Skip malformed entries
            }
        }

        file.close();
    }

    std::unique_ptr<UserInfo> parseLine(const std::string& line) {
        std::istringstream ss(line);
        std::string name, ageStr, email;

        if (!std::getline(ss, name, ',') || !std::getline(ss, ageStr, ',') ||
            !std::getline(ss, email)) {
            throw std::invalid_argument("Malformed CSV entry");
        }

        int age = std::stoi(ageStr);
        return std::make_unique<UserInfo>(UserInfo{name, age, email});
    }

    void filterByAge(int minAge) {
        users_.erase(std::remove_if(users_.begin(), users_.end(),
                                    [minAge](const UserInfo& user) { return user.age < minAge; }),
                     users_.end());
    }

    void sortByName() {
        std::sort(users_.begin(), users_.end());
    }

    double calculateAverageAge() const {
        if (users_.empty()) return 0.0;

        int totalAge = 0;
        for (const auto& user : users_) {
            totalAge += user.age;
        }
        return static_cast<double>(totalAge) / users_.size();
    }

    void displayUsers() const {
        for (const auto& user : users_) {
            std::cout << "Name: " << user.name 
                      << ", Age: " << user.age 
                      << ", Email: " << user.email << "\n";
        }
    }
};

int main() {
    try {
        DataProcessor processor("sample.csv");

        std::cout << "Average age: " << processor.calculateAverageAge() << "\n";

        processor.filterByAge(18);
        std::cout << "Filtered (age >= 18):\n";
        processor.displayUsers();

        processor.sortByName();
        std::cout << "Sorted by name:\n";
        processor.displayUsers();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }

    return 0;
}
