#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

typedef struct {
    char name[50];
    int version;
    EVP_CIPHER_CTX *ctx;
} AlgorithmInstance;

typedef struct {
    char config_name[100];
    AlgorithmInstance **algorithms;
    size_t count;
    pthread_mutex_t lock;
} AlgorithmCollection;

AlgorithmCollection* create_algorithm_collection() {
    AlgorithmCollection *collection = (AlgorithmCollection *)malloc(sizeof(AlgorithmCollection));
    if (!collection) return NULL;

    collection->algorithms = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_algorithm_collection(AlgorithmCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        EVP_CIPHER_CTX_free(collection->algorithms[i]->ctx);
        free(collection->algorithms[i]);
    }
    free(collection->algorithms);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

AlgorithmInstance* add_algorithm(AlgorithmCollection *collection, const char *name, int version) {
    if (!collection || !name) return NULL;

    pthread_mutex_lock(&collection->lock);

    AlgorithmInstance *new_instance = (AlgorithmInstance *)malloc(sizeof(AlgorithmInstance));
    if (!new_instance) {
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }

    strncpy(new_instance->name, name, sizeof(new_instance->name) - 1);
    new_instance->version = version;

    // Initialize the EVP_CIPHER_CTX based on algorithm type
    if (strcmp(name, "AES-GCM") == 0) {
        new_instance->ctx = EVP_CIPHER_CTX_new();
        if (!new_instance->ctx || !EVP_EncryptInit_ex(new_instance->ctx, EVP_aes_256_gcm(), NULL, NULL, NULL)) {
            free(new_instance);
            pthread_mutex_unlock(&collection->lock);
            return NULL;
        }
    } else if (strcmp(name, "ChaCha20") == 0) {
        new_instance->ctx = EVP_CIPHER_CTX_new();
        if (!new_instance->ctx || !EVP_EncryptInit_ex(new_instance->ctx, EVP_chacha20(), NULL, NULL, NULL)) {
            free(new_instance);
            pthread_mutex_unlock(&collection->lock);
            return NULL;
        }
    } else if (strcmp(name, "XChaCha20") == 0) {
        new_instance->ctx = EVP_CIPHER_CTX_new();
        if (!new_instance->ctx || !EVP_EncryptInit_ex(new_instance->ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL)) {
            free(new_instance);
            pthread_mutex_unlock(&collection->lock);
            return NULL;
        }
    } else {
        // Handle custom algorithm configurations
        fprintf(stderr, "Unsupported algorithm: %s\n", name);
        free(new_instance);
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }

    size_t new_count = collection->count + 1;
    AlgorithmInstance **new_algorithms = (AlgorithmInstance **)realloc(collection->algorithms, sizeof(AlgorithmInstance *) * new_count);
    if (!new_algorithms) {
        EVP_CIPHER_CTX_free(new_instance->ctx);
        free(new_instance);
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }

    collection->algorithms = new_algorithms;
    collection->algorithms[collection->count] = new_instance;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    return new_instance;
}

AlgorithmInstance* get_algorithm(AlgorithmCollection *collection, const char *name, int version) {
    if (!collection || !name) return NULL;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->algorithms[i]->name, name) == 0 && collection->algorithms[i]->version == version) {
            AlgorithmInstance *instance = collection->algorithms[i];
            pthread_mutex_unlock(&collection->lock);
            return instance;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    fprintf(stderr, "Algorithm %s version %d not found\n", name, version);
    return NULL;
}

void remove_algorithm(AlgorithmCollection *collection, const char *name, int version) {
    if (!collection || !name) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->algorithms[i]->name, name) == 0 && collection->algorithms[i]->version == version) {
            EVP_CIPHER_CTX_free(collection->algorithms[i]->ctx);
            free(collection->algorithms[i]);

            memmove(&collection->algorithms[i], &collection->algorithms[i + 1],
                    (collection->count - i - 1) * sizeof(AlgorithmInstance *));
            collection->count--;

            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void log_message(const char *level, const char *message) {
    // Basic logging function
    printf("[%s] %s\n", level, message);
}
