#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <pthread.h>

#define MAX_BACKENDS 10

typedef struct {
    char *name;
    int (*init)(void);
    void (*log)(const char *);
    void *params;
} LoggingBackend;

typedef struct {
    LoggingBackend *backends[MAX_BACKENDS];
    size_t count;
    pthread_mutex_t lock;
} BackendList;

BackendList* discover_logging_backends() {
    static BackendList backend_list = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };
    char **env_vars = NULL;
    int env_count = 0;
    char *token;
    const char *prefix = "LOGGING_BACKEND_";

    // Discover available backends via environment variables
    token = strtok_r(getenv("AVAILABLE_LOGGING_BACKENDS"), ",", &token);
    while (token) {
        env_vars = realloc(env_vars, sizeof(char*) * (++env_count));
        env_vars[env_count - 1] = strdup(token);
        token = strtok_r(NULL, ",", &token);
    }

    pthread_mutex_lock(&backend_list.lock);

    for (int i = 0; i < env_count; ++i) {
        if (backend_list.count >= MAX_BACKENDS) break;

        char *lib_path = getenv(env_vars[i]);
        if (!lib_path) continue;

        void *handle = dlopen(lib_path, RTLD_LAZY);
        if (!handle) continue;

        // Load backend functions
        int (*init_fn)(void) = (int (*)(void))dlsym(handle, "log_backend_init");
        void (*log_fn)(const char *) = (void (*)(const char *))dlsym(handle, "log_backend_log");

        if (!init_fn || !log_fn) {
            dlclose(handle);
            continue;
        }

        // Initialize backend
        if (init_fn()) {
            dlclose(handle);
            continue;
        }

        LoggingBackend *backend = malloc(sizeof(LoggingBackend));
        backend->name = strdup(env_vars[i]);
        backend->init = init_fn;
        backend->log = log_fn;
        backend->params = NULL; // Additional parameters can be managed here

        backend_list.backends[backend_list.count++] = backend;
    }

    pthread_mutex_unlock(&backend_list.lock);

    for (int i = 0; i < env_count; ++i) {
        free(env_vars[i]);
    }
    free(env_vars);

    return &backend_list;
}

void release_logging_backends(BackendList *list) {
    pthread_mutex_lock(list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->backends[i]->name);
        free(list->backends[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(list->lock);
}

int main() {
    BackendList *backend_list = discover_logging_backends();

    for (size_t i = 0; i < backend_list->count; ++i) {
        printf("Logging Backend: %s\n", backend_list->backends[i]->name);
        backend_list->backends[i]->log("Test log message");
    }

    release_logging_backends(backend_list);
    return 0;
}
```

### Key Points:
- **Dynamic Loading**: Uses `dlopen`, `dlsym` to load and resolve symbols at runtime.
- **Thread Safety**: Protects shared resources with a mutex.
- **Environment Variables**: Determines available backends dynamically.
- **Memory Management**: Allocates and frees memory carefully, preventing leaks.
- **Backward Compatibility**: Can be integrated without disrupting existing systems.

This code is designed to be flexible and maintainable while providing efficient logging mechanism discovery.']

