namespace MetricsSystem {

class MetricManager {
public:
    static const std::string METRIC_CONFIG_FILE;

    // Constructor
    MetricManager(const std::string& address, int flush_interval_seconds) 
        : exposer_(address), flush_interval_(flush_interval_seconds) {
        load_configurations();
        start_flushing_thread();
        monitor_system_health();
    }

    // Destructor
    ~MetricManager() {
        stop_flushing_thread();
        exposer_.Shutdown();
    }

    void register_metric(const std::string& name, const prometheus::MetricFamilyBuilder& builder) {
        registry_.Register(builder);
    }

private:
    static void load_configurations() {
        // Load metric configurations from file or environment
        if (std::ifstream(METRIC_CONFIG_FILE)) {
            std::cout << "Loading configurations...\n";
            // Parse configuration files to register metrics dynamically
        }
    }

    void start_flushing_thread() {
        flushing_ = true;
        flusher_ = std::thread([this]() { 
            while (flushing_) {
                exposer_.Expose();
                std::this_thread::sleep_for(std::chrono::seconds(flush_interval_));
            }
        });
    }

    void stop_flushing_thread() {
        if (flushing_) {
            flushing_ = false;
            flusher_.join();
        }
    }

    void monitor_system_health() {
        std::thread([this]() {
            while (true) {
                // Monitor and log system performance
