    prometheus::Exposer exposer_;
    prometheus::Registry registry_;

    int flush_interval_;
    std::thread flusher_;
    bool flushing_ = false;
};

const std::string MetricManager::METRIC_CONFIG_FILE = "metrics_config.txt";

}  // namespace MetricsSystem

int main() {
    MetricsSystem::MetricManager manager("http://localhost:9090", 10);

