import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

public class FileProcessor {

    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
    private static final int MAX_LINES_PER_FILE = 10_000;
    private static final Pattern VALID_LINE_PATTERN = Pattern.compile("^[a-zA-Z0-9 ]*$");

    public static class SummaryReport {
        private int totalFilesProcessed;
        private int totalLinesTransformed;
        private List<String> issues;

        // Getters and setters
        public int getTotalFilesProcessed() { return totalFilesProcessed; }
        public void setTotalFilesProcessed(int totalFilesProcessed) { this.totalFilesProcessed = totalFilesProcessed; }

        public int getTotalLinesTransformed() { return totalLinesTransformed; }
        public void setTotalLinesTransformed(int totalLinesTransformed) { this.totalLinesTransformed = totalLinesTransformed; }

        public List<String> getIssues() { return issues; }
        public void addIssue(String issue) { if (issues == null) issues = new ArrayList<>(); issues.add(issue); }
    }

    private static void logError(String message) {
        // Integrate with external logging service
        System.err.println(message);
    }

    private static String transformLine(String line) {
        // Custom transformation logic here, e.g., reversing the string
        return new StringBuilder(line).reverse().toString();
    }

    public static SummaryReport processFiles(List<String> filePaths) {
        SummaryReport report = new SummaryReport();

        for (String filePath : filePaths) {
            try {
                Path path = Paths.get(filePath);

                if (!Files.exists(path)) {
                    logError("File does not exist: " + filePath);
                    continue;
                }

                long fileSize = Files.size(path);
                if (fileSize > MAX_FILE_SIZE) {
                    report.addIssue("File exceeds maximum size: " + filePath);
                    continue;
                }

                int linesTransformed = 0;

                try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
                    String line;
                    int lineNumber = 0;
                    while ((line = reader.readLine()) != null) {
                        if (++lineNumber > MAX_LINES_PER_FILE) break;

                        if (!VALID_LINE_PATTERN.matcher(line).matches()) {
                            logError("Invalid line in file " + filePath + ": " + line);
                            continue;
                        }

                        transformLine(line); // Perform transformation
                        linesTransformed++;
                    }
                } catch (IOException e) {
                    logError("Failed to read file: " + filePath + ". Error: " + e.getMessage());
                }

                report.setTotalFilesProcessed(report.getTotalFilesProcessed() + 1);
                report.setTotalLinesTransformed(report.getTotalLinesTransformed() + linesTransformed);

            } catch (IOException e) {
                logError("Error processing file path: " + filePath + ". Error: " + e.getMessage());
            }
        }

        return report;
    }
}
