public class StateLoader {
    private static final ReentrantLock lock = new ReentrantLock();

    public static class CorruptedStateException extends Exception {
        public CorruptedStateException(String message) {
            super(message);
        }
    }

    public static MoSTState loadStateFromFile(String filePath) throws IOException, CorruptedStateException {
        File file = new File(filePath);

        // Step 1: Check if the file exists and is accessible
        if (!file.exists() || !file.canRead()) {
            throw new FileNotFoundException("File not found or inaccessible: " + filePath);
        }

        long expectedSize = MoSTState.getExpectedSerializedSize();

        try (RandomAccessFile randomAccessFile = new RandomAccessFile(file, "r");
             FileChannel fileChannel = randomAccessFile.getChannel();
             FileInputStream fis = new FileInputStream(file);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

            // Step 2: Validate the file size
            if (file.length() != expectedSize) {
                logWarning("Unexpected file size for " + filePath);
                return retryWithFallbackConfiguration(filePath, expectedSize);
            }

            // Step 6: Use a lock to ensure thread-safe access
            lock.lock();

            try {
                Object obj = ois.readObject();

                // Step 3 & 5: Check if the object is an instance of MoSTState and versioning
                if (!(obj instanceof MoSTState)) {
                    throw new CorruptedStateException("Invalid object type.");
                }

                MoSTState state = (MoSTState) obj;
                if (!state.isCompatibleVersion()) {
                    logWarning("Incompatible version detected for " + filePath);
                    return migrateToLatestVersion(state);
                }

                // Step 4: Checksum verification
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    digest.update(buffer, 0, bytesRead);
                }

                if (!state.verifyChecksum(digest.digest())) {
                    throw new CorruptedStateException("Checksum mismatch detected.");
                }

                return state;

            } finally {
                lock.unlock();
            }

        } catch (ClassNotFoundException | IOException e) {
            logError("Error loading state from file: " + filePath, e);
            throw new CorruptedStateException("Failed to load MoSTState: " + e.getMessage());
        }
    }

    private static void logWarning(String message) {
        System.err.println("WARNING: " + message);
    }

