async function runModuleTests(moduleName, testCases, blueslipMock, environmentConfig) {
    const results = {
        passed: 0,
        failed: 0,
        logs: []
    };

    const cache = new Map();

    async function loadModuleAsync(name) {
        if (cache.has(name)) return cache.get(name);
        try {
            const module = await customAsyncLoader(name); // Replace with actual async loader
            cache.set(name, module);
            return module;
        } catch (error) {
            throw new Error(`Failed to load module: ${name}. Error: ${error.message}`);
        }
    }

    function runTest(fn, retriesLeft = environmentConfig.retryAttempts || 3) {
        return new Promise((resolve, reject) => {
            fn()
                .then(() => {
                    resolve(true);
                })
                .catch((err) => {
                    if (retriesLeft > 0) {
                        console.warn(`Retrying test due to error: ${err.message}. Retries left: ${retriesLeft}`);
                        runTest(fn, retriesLeft - 1).then(resolve).catch(reject);
                    } else {
                        reject(err);
                    }
                });
        });
    }

    async function executeTestCase(testCase) {
        const { name, fn } = testCase;

        console.log(`Starting test: ${moduleName}.${name}`);
        try {
            await loadModuleAsync(moduleName);

            blueslipMock.reset(); // Reset mock state

            try {
                await runTest(fn);

                results.passed += 1;
                results.logs.push({ testName: name, status: 'passed' });

                console.log(`Passed test: ${moduleName}.${name}`);
            } catch (error) {
                results.failed += 1;
                results.logs.push({ testName: name, status: 'failed', error: error.message });

                console.error(`Failed test: ${moduleName}.${name}. Error: ${error.message}`);
            }

        } catch (error) {
            results.failed += 1;
            results.logs.push({ testName: name, status: 'moduleLoadFailed', error: error.message });

            console.error(`Error loading module or running test for: ${moduleName}.${name}. Error: ${error.message}`);
        } finally {
            // Check memory usage and garbage collect if needed
            monitorMemoryAndGarbageCollect(environmentConfig.memoryLimit);
        }
    }

    async function runAllTests() {
        const tasks = testCases.map(executeTestCase);

        await Promise.allSettled(tasks).then(() => {
            console.log('All tests completed.');
        });
    }

    runAllTests();

    return results;
}

// Helper functions

function customAsyncLoader(moduleName) {
    // Implement custom async module loading with caching.
    return new Promise((resolve, reject) => {
        // Simulate module load
        setTimeout(() => resolve(`Loaded ${moduleName}`), 100);
    });
}

function monitorMemoryAndGarbageCollect(memoryLimit) {
    const used = process.memoryUsage().heapUsed / 1024 / 1024; // Convert to MB

    if (used > memoryLimit) {
        console.warn(`High memory usage detected: ${used.toFixed(2)}MB. Triggering garbage collection.`);

        // Simulate garbage collection
        global.gc(); // Node.js specific, ensure `--expose-gc` flag is set for this
    }
}

