class Record:
    def __init__(self, offset: int, key: int, value: int):
        self.offset = offset
        self.key = key
        self.value = value

# Constants for memory management
MAX_MEMORY_USAGE = 1024 * 1024 * 100  # Example: 100MB limit
OFFSET_SIZE = 8  # Size of long in bytes
KEY_SIZE = 4     # Size of int in bytes
RECORD_OVERHEAD = 12  # Additional overhead for a record (e.g., padding)

def get_user_input(prompt):
    try:
        return int(input(prompt))
    except ValueError:
        print("Invalid input, please enter an integer.")
        return get_user_input(prompt)

def calculate_max_records(memory_limit, record_size):
    return memory_limit // record_size

def authenticate_with_mfa():
    # Dummy MFA API call
    response = requests.get('https://api.example.com/mfa/verify')
    if response.status_code == 200:
        print("MFA verification successful.")
        return True
    else:
        print(f"MFA failed: {response.text}")
        return False

def allocate_and_initialize_records(num_records):
    record_size = OFFSET_SIZE + KEY_SIZE * 2 + RECORD_OVERHEAD
    max_possible_records = calculate_max_records(MAX_MEMORY_USAGE, record_size)

    if num_records > max_possible_records:
        raise MemoryError("Requested size exceeds maximum allowable memory usage.")

    records = [None] * num_records

    offsets = (random.randint(0, 100000) for _ in range(num_records))
    keys = set()

    key_lock = threading.Lock()

    def generate_unique_key():
        with key_lock:
            while True:
                new_key = random.randint(1, 100000)
                if new_key not in keys:
                    keys.add(new_key)
                    return new_key

    for i in range(num_records):
        offset = next(offsets)
        key = generate_unique_key()
        value = random.randint(0, 100)  # Adjust the range as needed
        records[i] = Record(offset, key, value)

    return records

def initialize_system():
    if not authenticate_with_mfa():
        print("MFA required. Exiting.")
        return

    num_records_input = get_user_input("Enter number of records to initialize: ")

    try:
        records = allocate_and_initialize_records(num_records_input)
        print(f"Successfully initialized {len(records)} records.")

    except MemoryError as e:
        print(e)

if __name__ == "__main__":
    # Simulate distributed system communication and retries
    retry_attempts = 3

    for attempt in range(retry_attempts):
        try:
            initialize_system()
            break
        except requests.RequestException as e:
            if attempt < retry_attempts - 1:
                print(f"Network error: {e}. Retrying...")
            else:
                print("Failed to initialize system after multiple attempts.")
