#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Define a structure for an event type node in the list
typedef struct EventTypeNode {
    int eventType;
    struct EventTypeNode *next;
} EventTypeNode;

// Define a structure for the dynamic list of events (EDA)
typedef struct EventDrivenArchitecture {
    EventTypeNode *head;
    // Additional fields for managing state can be added here
} EventDrivenArchitecture;

EventTypeNode* create_event_list(int *eventTypes, int numEvents, EventDrivenArchitecture *eda, int lastEventType, bool clearList) {
    // If the list should be cleared, reset the head of the EDA
    if (clearList && eda->head != NULL) {
        EventTypeNode *current = eda->head;
        while (current != NULL) {
            EventTypeNode *next = current->next;
            free(current);
            current = next;
        }
        eda->head = NULL;
    }

    // Allocate memory for the new event list
    EventTypeNode *newListHead = malloc(sizeof(EventTypeNode));
    if (!newListHead) return NULL;  // Return NULL if memory allocation fails

    EventTypeNode *currentNewNode = newListHead;

    // Initialize the first node of the new list with the last event type in the existing list
    currentNewNode->eventType = lastEventType;
    currentNewNode->next = NULL;

    // Traverse the input event types and add them to the new list
    for (int i = 0; i < numEvents; ++i) {
        EventTypeNode *newNode = malloc(sizeof(EventTypeNode));
        if (!newNode) {  // If memory allocation fails, free previously allocated nodes
            while (currentNewNode != NULL) {
                EventTypeNode *toFree = currentNewNode;
                currentNewNode = currentNewNode->next;
                free(toFree);
            }
            return NULL;  // Return NULL due to insufficient memory
        }

        newNode->eventType = eventTypes[i];
        newNode->next = NULL;

        // Link the new node to the end of the list
        currentNewNode->next = newNode;
        currentNewNode = newNode;
    }

    // Update the 'next' pointer of the last event type in the existing list, if it exists
    EventTypeNode *lastNodeInExistingList = NULL;
    if (eda->head != NULL) {
        lastNodeInExistingList = eda->head;
        while (lastNodeInExistingList->next != NULL) {
            lastNodeInExistingList = lastNodeInExistingList->next;
        }
    }

    if (lastNodeInExistingList != NULL) {
        lastNodeInExistingList->next = newListHead;
    } else {
        // If the existing list is empty, initialize it with the new list
        eda->head = newListHead;
    }

    return newListHead;  // Return the head of the newly created event list
}
