['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEFAULT_LOG_FILE_MODE (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)
#define DEFAULT_MAX_RUNTIME 30

void handle_error(const char *message, FILE *log_file) {
    if (log_file != NULL) {
        fprintf(log_file, "Error: %s\n", message);
        fclose(log_file);
    }
    perror(message);
}

int create_log_directory(const char *path) {
    size_t len = strlen(path);
    char dir_path[len + 1];
    strcpy(dir_path, path);

    for (size_t i = 0; i < len; ++i) {
        if (dir_path[i] == '/' && (i + 1 < len)) {
            dir_path[i + 1] = '\0';
            if (mkdir(dir_path, DEFAULT_LOG_FILE_MODE) != 0 && errno != EEXIST) {
                return -1;
            }
            dir_path[i + 1] = '/';
        }
    }

    return mkdir(path, DEFAULT_LOG_FILE_MODE);
}

int execute_command(const char *command, const char *log_file_path, int max_runtime) {
    if (create_log_directory(log_file_path) == -1) {
        perror("Failed to create log directory");
        return 0;
    }

    FILE *log_file = fopen(log_file_path, "w");
    if (!log_file) {
        handle_error("Failed to open log file", NULL);
        return 0;
    }

    int fd[2];
    if (pipe(fd) == -1) {
        handle_error("Pipe creation failed", log_file);
        fclose(log_file);
        return 0;
    }

    pid_t pid = fork();
    if (pid < 0) {
        handle_error("Fork failed", log_file);
        close(fd[0]);
        close(fd[1]);
        fclose(log_file);
        return 0;
    }

    if (pid == 0) { // Child process
        dup2(fd[1], STDOUT_FILENO);
        dup2(fd[1], STDERR_FILENO);
        close(fd[0]);

        char *argv[] = { strdup(command), NULL };
        execv(argv[0], argv);

        handle_error("Exec failed", NULL);
        exit(EXIT_FAILURE); // Should not reach here
    }

    close(fd[1]); // Parent closes write end of pipe

    int status;
    struct timespec ts_start, ts_end;
    clock_gettime(CLOCK_REALTIME, &ts_start);

    while (waitpid(pid, &status, WNOHANG) == 0) {
        if ((ts_end.tv_sec - ts_start.tv_sec) > max_runtime ||
            ((ts_end.tv_sec == ts_start.tv_sec) && (ts_end.tv_nsec - ts_start.tv_nsec) / 1e9 > max_runtime)) {

            clock_gettime(CLOCK_REALTIME, &ts_end);

            kill(pid, SIGTERM);
            waitpid(pid, &status, 0); // Wait for the process to terminate

            if (WIFEXITED(status) || WIFSIGNALED(status)) {
                fprintf(log_file, "Command exceeded time limit and was terminated.\n");
            } else {
                fprintf(log_file, "Failed to terminate command after exceeding time limit.\n");
            }
            fclose(log_file);
            return -1;
        }

        struct timespec ts_current;
        clock_gettime(CLOCK_REALTIME, &ts_current);

        if ((ts_end.tv_sec < ts_current.tv_sec) || 
           (ts_end.tv_sec == ts_current.tv_sec && ts_end.tv_nsec <= ts_current.tv_nsec)) {
            ts_end = ts_current;
        }

        usleep(100000); // Sleep for 0.1 seconds
    }

    fclose(log_file);
    return WIFEXITED(status) || WIFSIGNALED(status) ? 1 : 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <command> <log file path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *command = argv[1];
    const char *log_file_path = argv[2];
    int max_runtime = DEFAULT_MAX_RUNTIME;

    if (argc > 3) {
        max_runtime = atoi(argv[3]);
    }

    int result = execute_command(command, log_file_path, max_runtime);

    if (result == -1) {
        fprintf(stderr, "Command exceeded time limit.\n");
    } else if (result == 0) {
        fprintf(stderr, "Failed to start command.\n");
    } else {
        printf("Command executed successfully in the background.\n");
    }

    return result;
}
```']

