#define MAX_TRANSACTIONS 1000
#define SLIDING_WINDOW_SECONDS 3

typedef struct {
    int transaction_id;
    time_t timestamp; // UNIX epoch time
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    Transaction *transactions[MAX_TRANSACTIONS];
    size_t count;
    double total_age;
    size_t accepted_count;
    size_t rejected_count;
    double highest_weighted_sum;
    double current_rate_limit;  // Transactions per second allowed
} Metrics;

Metrics metrics = { .count = 0, .total_age = 0.0, .accepted_count = 0, 
                   .rejected_count = 0, .highest_weighted_sum = 0.0 };

// Function to calculate weighted sum for a transaction
double calculate_weighted_sum(Transaction *transaction) {
    // Placeholder function: implement your logic here.
    return transaction->timestamp % 100; // Example calculation
}

void log_event(const char *message, const char *level) {
    printf("[%s] %s\n", level, message);
}

int should_accept_transaction(Transaction *transaction) {
    pthread_mutex_lock(&metrics.lock);

    time_t current_time = time(NULL);
    size_t transaction_count_in_window = 0;
    double weighted_sum = calculate_weighted_sum(transaction);

    // Remove stale transactions
    for (size_t i = 0; i < metrics.count; ++i) {
        if (current_time - metrics.transactions[i]->timestamp > SLIDING_WINDOW_SECONDS * 2) {
            free(metrics.transactions[i]);
            metrics.transactions[i] = metrics.transactions[--metrics.count];
            i--; // Adjust index since we just removed an item
        }
    }

    for (size_t i = 0; i < metrics.count; ++i) {
        if (current_time - metrics.transactions[i]->timestamp <= SLIDING_WINDOW_SECONDS * 1000) {
            transaction_count_in_window++;
            if (weighted_sum > metrics.highest_weighted_sum) {
                metrics.highest_weighted_sum = weighted_sum;
            }
        }
    }

    int accept = (transaction_count_in_window < current_rate_limit && 
                  current_time - transaction->timestamp <= SLIDING_WINDOW_SECONDS * 1000);

    pthread_mutex_unlock(&metrics.lock);

    if (accept) {
        metrics.accepted_count++;
        metrics.total_age += difftime(current_time, transaction->timestamp);
        log_event("Transaction accepted", "INFO");
    } else {
        metrics.rejected_count++;
        log_event("Transaction rejected", "WARN");
    }

    return accept;
}

void *process_transactions(void *arg) {
    Transaction *transaction = (Transaction *)arg;

    if (should_accept_transaction(transaction)) {
        pthread_mutex_lock(&metrics.lock);
        if (metrics.count < MAX_TRANSACTIONS) {
            metrics.transactions[metrics.count++] = transaction;
        } else {
            log_event("Dropped transaction due to overflow", "ERROR");
        }
        pthread_mutex_unlock(&metrics.lock);
    }

    free(transaction);  // Ensure memory is freed
    return NULL;
}

void update_metrics() {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&metrics.lock);
    if (metrics.accepted_count > 0) {
        double average_age = metrics.total_age / metrics.accepted_count;
        log_event("Average transaction age updated", "INFO");
    }
    pthread_mutex_unlock(&metrics.lock);
}

int main() {
    pthread_t thread_id;

    // Initialize lock
    pthread_mutex_init(&metrics.lock, NULL);

    // Simulate incoming transactions
    for (int i = 0; i < 100; ++i) {
        Transaction *transaction = malloc(sizeof(Transaction));
        transaction->transaction_id = i;
        transaction->timestamp = time(NULL); 

        if (pthread_create(&thread_id, NULL, process_transactions, (void *)transaction)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < 100; ++i) {
        pthread_join(thread_id, NULL);
    }

    update_metrics();

    // Cleanup lock
    pthread_mutex_destroy(&metrics.lock);

    return 0;
}
