long findMax(int* arr, size_t size) {
    if (size == 0) return LONG_MIN;
    long max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

void processRecordsAndFindMaxWithSemaphore(size_t offset_size, size_t key_size, size_t record_size,
                                           long random_min, long random_max, unsigned int seed,
                                           void (*custom_callback)(record*)) {

    sem_t semaphore;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Failed to initialize semaphore");
        return;
    }

    long* offset = malloc(offset_size * sizeof(long));
    int* key = malloc(key_size * sizeof(int));
    record* records = malloc(record_size * sizeof(record));

    if (!offset || !key || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset);
        free(key);
        free(records);
        sem_destroy(&semaphore);
        return;
    }

    // Initialize arrays with sequential numbers
    for (size_t i = 0; i < offset_size; ++i) offset[i] = i;
    for (size_t i = 0; i < key_size; ++i) key[i] = i;

    srand(seed);

    // Initialize records
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = secure_random(random_min, random_max);
        snprintf(records[i].key, sizeof(records[i].key), "Key_%zu", i);

        sem_wait(&semaphore);
        pthread_mutex_lock(&mutex);

        records[i].dynamic_long = malloc(sizeof(long));
        if (!records[i].dynamic_long) {
            fprintf(stderr, "Memory allocation failed for dynamic_long\n");
            free(offset);
            free(key);
            for (size_t j = 0; j < i; ++j) {
                free(records[j].dynamic_long);
            }
            free(records);
            sem_destroy(&semaphore);
            return;
        }

        *(records[i].dynamic_long) = secure_random(random_min, random_max);

        pthread_mutex_unlock(&mutex);
        sem_post(&semaphore);

        if (custom_callback) custom_callback(&records[i]);
    }

    int* input_array = NULL;
    size_t current_size = 0;

    printf("Enter integers (-1 to stop):\n");
    while (1) {
        int num;
        scanf("%d", &num);

        if (num == -1) break;

        sem_wait(&semaphore);

        if (current_size >= input_array_size) {
            size_t new_size = current_size ? current_size * 2 : 4;
            int* temp = realloc(input_array, new_size * sizeof(int));
            if (!temp) {
                fprintf(stderr, "Memory allocation failed\n");
                sem_post(&semaphore);
                free(offset);
                free(key);
                for (size_t i = 0; i < record_size; ++i) {
                    free(records[i].dynamic_long);
                }
                free(records);
                sem_destroy(&semaphore);
                return;
            }
            input_array = temp;
        }

        input_array[current_size++] = num;

        sem_post(&semaphore);
    }

    long max_value = findMax(input_array, current_size);
    printf("The largest integer is: %ld\n", max_value);

    // Free allocated memory
    free(offset);
    free(key);
    for (size_t i = 0; i < record_size; ++i) {
        free(records[i].dynamic_long);
    }
    free(records);
    if (input_array) free(input_array);

    sem_destroy(&semaphore);
}
