typedef enum { STRING, INTEGER, BOOLEAN } ValueType;

typedef struct {
    char name[256];
    ValueType type;
    union {
        char *str_value;
        int int_value;
        _Bool bool_value;
    };
    union {
        char *default_str_value;
        int default_int_value;
        _Bool default_bool_value;
    };
    char dns_address[256];
} Preference;

typedef void (*PreferenceInitCallback)(Preference *);

typedef struct {
    Preference *preferences;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PreferencesManager;

PreferencesManager* initPreferences(size_t min_size, size_t max_size) {
    if (min_size > max_size || min_size == 0) return NULL;

    PreferencesManager *manager = malloc(sizeof(PreferencesManager));
    if (!manager) return NULL;

    manager->preferences = calloc(max_size, sizeof(Preference));
    if (!manager->preferences) {
        free(manager);
        return NULL;
    }

    manager->count = min_size;
    manager->capacity = max_size;
    pthread_mutex_init(&manager->lock, NULL);

    // Initialize with default values
    for (size_t i = 0; i < min_size; ++i) {
        manager->preferences[i].name[0] = '\0';
        manager->preferences[i].type = STRING;
        manager->preferences[i].str_value = "default";
        manager->preferences[i].default_str_value = "default";
    }

    return manager;
}

void resizePreferences(PreferencesManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);
    if (new_capacity > manager->capacity) {
        Preference *temp = realloc(manager->preferences, new_capacity * sizeof(Preference));
        if (!temp) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->preferences = temp;
        manager->capacity = new_capacity;
    }
    pthread_mutex_unlock(&manager->lock);
}

void addPreference(PreferencesManager *manager, const char *name, ValueType type, void *value, PreferenceInitCallback callback) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resizePreferences(manager, manager->capacity * 2);
    }

    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (strcmp(manager->preferences[i].name, "") == 0) break;
    }

    strncpy(manager->preferences[i].name, name, sizeof(manager->preferences[i].name) - 1);
    manager->preferences[i].type = type;

    switch (type) {
        case STRING:
            manager->preferences[i].str_value = strdup((char *)value);
            manager->preferences[i].default_str_value = strdup("default");
            break;
        case INTEGER:
            manager->preferences[i].int_value = *(int *)value;
            manager->preferences[i].default_int_value = 0;
            break;
        case BOOLEAN:
            manager->preferences[i].bool_value = *(int)value; // _Bool cast to int
            manager->preferences[i].default_bool_value = 0;
            break;
    }

    if (callback) callback(&manager->preferences[i]);

    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

void readPreferences(PreferencesManager *manager) {
    char input[256];
    while (1) {
        printf("Enter preference name and value (or 'exit' to quit): ");
        if (!fgets(input, sizeof(input), stdin)) break;

        if (strncmp(input, "exit", 4) == 0) break;

        char name[256], *value = NULL;
        ValueType type = STRING;
        int int_value;

        if (sscanf(input, "%255[^=]=%m[^\n]", name, &value) != 2) {
            fprintf(stderr, "Malformed input\n");
            continue;
        }

        switch (*value) {
            case '0': case '1': case '2': case '3': case '4':
            case '5': case '6': case '7': case '8': case '9':
                if (sscanf(value, "%d", &int_value) == 1) {
                    type = INTEGER;
                }
                break;
            case 't': case 'f':
                type = BOOLEAN;
                break;
        }

        switch (type) {
            case STRING:
                addPreference(manager, name, STRING, value, NULL);
                free(value);
                break;
            case INTEGER:
                int *int_ptr = malloc(sizeof(int));
                if (!int_ptr) continue;
                *(int_ptr) = int_value;
                addPreference(manager, name, INTEGER, int_ptr, NULL);
                break;
            case BOOLEAN:
                _Bool bool_value = (*value == 't');
                int *bool_ptr = malloc(sizeof(int)); // store as integer
                if (!bool_ptr) continue;
                *(bool_ptr) = bool_value;
                addPreference(manager, name, BOOLEAN, bool_ptr, NULL);
                break;
        }
    }
}

void freePreferences(PreferencesManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->preferences[i].type == STRING && manager->preferences[i].str_value) {
            free(manager->preferences[i].str_value);
            free(manager->preferences[i].default_str_value);
        }
    }

    free(manager->preferences);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void resolveAndManagePreferences() {
    PreferencesManager *prefs_manager = initPreferences(10, 20);
    if (!prefs_manager) {
        fprintf(stderr, "Failed to initialize preferences manager\n");
        return;
    }

    readPreferences(prefs_manager);

    // Here you can perform DNS resolution or other actions on prefs_manager->preferences
    // For example:
    for (size_t i = 0; i < prefs_manager->count; ++i) {
        if (prefs_manager->preferences[i].type == STRING && strstr(prefs_manager->preferences[i].str_value, "http")) {
            printf("Performing DNS resolution on: %s\n", prefs_manager->preferences[i].dns_address);
        }
    }

    freePreferences(prefs_manager);
}

int main() {
    resolveAndManagePreferences();
    return 0;
}
