    pthread_mutex_t offset_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t keys_lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays
    long* offsets = (long*)malloc(record_count * sizeof(long));
    if (!offsets) return -1;

    int* keys = (int*)malloc(record_count * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1;
    }

    Record* records = (Record*)malloc(record_count * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return -1;
    }

    // Initialize custom random number generator
    custom_random_init(seed);

    // Seed external data source for unique keys
    // Example: Load from file or database into a temporary array (omitted for brevity)

    unsigned int used_values[record_count] = {0};  // Simple hash map replacement

    // Populate the arrays
    for (int i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&offset_lock);
        offsets[i] = increment_factor * i;
        pthread_mutex_unlock(&offset_lock);

        int key;
        do {
            pthread_mutex_lock(&keys_lock);
            key = custom_random_get();
            pthread_mutex_unlock(&keys_lock);
        } while (key < 0 || used_values[key % record_count]); // Ensure unique keys

        used_values[key % record_count] = 1; // Mark as used
        keys[i] = key;

        unsigned int value;
        do {
            value = custom_random_get();
        } while (used_values[value % record_count]); // Ensure unique values within range

        records[i].value = value;
        used_values[value % record_count] = 1; // Mark as used
    }

    // Callback processing each record
    if (callback) {
        for (int i = 0; i < record_count; ++i) {
            callback(&records[i]);
        }
    }

    // Verify integrity
    for (int i = 0; i < record_count - 1; ++i) {
        for (int j = i + 1; j < record_count; ++j) {
            if (keys[i] == keys[j]) {
                fprintf(stderr, "Duplicate key found at indices %d and %d\n", i, j);
                // Log error to centralized system
            }
            if (records[i].value == records[j].value) {
                fprintf(stderr, "Duplicate value found in records at indices %d and %d\n", i, j);
                // Log error to centralized system
            }
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&offset_lock);
    pthread_mutex_destroy(&keys_lock);

    return 0; // Success
}

// Example callback function
