// Define a record structure for holding FSA state information.
typedef struct Record {
    int value;
    struct Record* next;
} Record;

// Function prototype declaration.
void manageFsaStateList(long* offsets, size_t numOffsets,
                        void* fsa, int lastState, bool clearBeforeAddition,
                        double performanceThreshold,
                        uint32_t rangeMin, uint32_t rangeMax,
                        uint32_t seed,
                        void (*callback)(const Record*));

// Helper function to generate a random number within a specified range.
int generateRandomNumber(uint32_t min, uint32_t max, uint32_t seed) {
    srand(seed);
    return (rand() % (max - min + 1)) + min;
}

// Mutex for synchronizing access in a multithreaded environment.
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void manageFsaStateList(long* offsets, size_t numOffsets,
                        void* fsa, int lastState, bool clearBeforeAddition,
                        double performanceThreshold,
                        uint32_t rangeMin, uint32_t rangeMax,
                        uint32_t seed,
                        void (*callback)(const Record*)) {
    // Initialize the head of the linked list to NULL.
    Record *head = NULL;
    if (clearBeforeAddition && head) {
        while (head != NULL) {
            Record* temp = head;
            head = head->next;
            free(temp);
        }
    }

    for (size_t i = 0; i < numOffsets; ++i) {
        pthread_mutex_lock(&mutex);

        // Create a new record and allocate memory.
        Record *newRecord = (Record*)malloc(sizeof(Record));
        if (!newRecord) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Set the value of the record to a random number within the specified range.
        newRecord->value = generateRandomNumber(rangeMin, rangeMax, seed);

        // Add it to the linked list.
        if (!head) {
            head = newRecord;
        } else {
            Record *temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newRecord;
        }

        newRecord->next = NULL;

        // Call the callback function if provided.
        if (callback != NULL) {
            callback(newRecord);
        }

        pthread_mutex_unlock(&mutex);
    }

    // Free allocated memory on exit or as needed to prevent leaks.
    Record *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Example of a callback function that could be passed in.
void exampleCallback(const Record* record) {
    printf("Record initialized with value: %d\n", record->value);
}
