// Define record structure
typedef struct {
    int value;
} record;

// Memory pool for long values with fine-grained locking
typedef struct {
    pthread_mutex_t lock;
    long* data;
    size_t capacity;
} LongPool;

// Function to initialize a memory pool
void initLongPool(LongPool* pool, size_t capacity) {
    pool->data = (long*)malloc(capacity * sizeof(long));
    if (!pool->data) {
        fprintf(stderr, "Memory allocation failed for long offsets.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = capacity;
}

// Function to free a memory pool
void freeLongPool(LongPool* pool) {
    free(pool->data);
    pthread_mutex_destroy(&pool->lock);
}

// Function to allocate and initialize arrays with given constraints
int allocateAndInitialize(int keyCount, int recordCount, long incrementFactor, int rangeMin, int rangeMax,
                          void (*callback)(record*)) {

    // Seed random number generator using external source for robustness
    srand(time(NULL) ^ *(unsigned int*)(&keyCount));

    // Allocate memory pools
    LongPool offsetPool;
    initLongPool(&offsetPool, keyCount);

    int* keys = (int*)malloc(keyCount * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        freeLongPool(&offsetPool);
        return -1;
    }

    record* records = (record*)malloc(recordCount * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(keys);
        freeLongPool(&offsetPool);
        return -1;
    }

    // Initialize sequential offsets with thread safety
    for (size_t i = 0; i < offsetPool.capacity; ++i) {
        pthread_mutex_lock(&offsetPool.lock);
        offsetPool.data[i] = i * incrementFactor;
        pthread_mutex_unlock(&offsetPool.lock);
    }

    // Generate unique keys and check integrity
    bool* keyExists = (bool*)calloc(keyCount, sizeof(bool));
    for (int i = 0; i < keyCount; ++i) {
        int key;
        do {
            key = rand() % keyCount;
        } while (keyExists[key]);
        keyExists[key] = true;
        keys[i] = key + 1; // Ensure uniqueness by starting from 1
    }
    free(keyExists);

    // Initialize records with random values ensuring no duplicates
    bool* valueExists = (bool*)calloc(recordCount, sizeof(bool));
    for (int i = 0; i < recordCount; ++i) {
        int value;
        do {
            value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        } while (valueExists[value]);
        valueExists[value] = true;
        records[i].value = value;

        // Call callback function if provided
        if (callback != NULL) {
            callback(&records[i]);
        }
    }
    free(valueExists);

    // Verification and logging can be added here

    // Output allocated data for testing purposes
    printf("Offsets:\n");
    for (size_t i = 0; i < offsetPool.capacity; ++i) {
        printf("%ld ", offsetPool.data[i]);
    }
    printf("\nKeys:\n");
    for (int i = 0; i < keyCount; ++i) {
        printf("%d ", keys[i]);
    }
    printf("\nRecords:\n");
    for (int i = 0; i < recordCount; ++i) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    // Clean up
    freeLongPool(&offsetPool);
    free(keys);
    free(records);

    return 0;
}

// Example callback function
void processRecord(record* rec) {
    printf("Processing record with value: %d\n", rec->value);
}

int main() {
    allocateAndInitialize(10, 5, 3, 1, 100, processRecord);
    return 0;
}
