typedef struct Node {
    int value;
    char key[256];
    long *ptr;
    struct Node *next;
} Node;

// Error logging function
void log_error(FILE *log_fd, const char *message) {
    if (fprintf(log_fd, "Error: %s\n", message) < 0) {
        perror("Logging failed");
    }
}

// Custom random number generator
typedef enum { UNIQUE, PERMUTATION, SEQUENCE } RNGMode;

int custom_rng(int min, int max, RNGMode mode, unsigned long seed) {
    static unsigned long last_seed = 0;
    if (mode == SEQUENCE && !last_seed) {
        last_seed = seed ? seed : time(NULL);
    }

    switch (mode) {
        case UNIQUE:
            return rand_r(&seed) % (max - min + 1) + min;
        case PERMUTATION:
            // Simplified permutation logic for demonstration
            return (rand_r(&seed) * (max - min)) % (max - min + 1) + min;
        case SEQUENCE:
            last_seed = (last_seed * 1103515245 + 12345) & 0x7fffffff;
            return (int)(last_seed % ((unsigned long)(max - min + 1))) + min;
        default:
            return -1; // Error
    }
}

// Dynamic array with resizing capability
typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t size;
} DynamicArray;

void dynamic_array_init(DynamicArray *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->offsets = malloc(arr->capacity * sizeof(long));
    arr->keys = malloc(arr->capacity * sizeof(int));

    if (!arr->offsets || !arr->keys) {
        log_error(stderr, "Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < arr->capacity; ++i) {
        arr->offsets[i] = (long)i;
        arr->keys[i] = (int)i;
    }
}

void dynamic_array_resize(DynamicArray *arr, size_t new_capacity) {
    long *new_offsets = realloc(arr->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(arr->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        log_error(stderr, "Failed to resize dynamic array");
        exit(EXIT_FAILURE);
    }

    arr->offsets = new_offsets;
    arr->keys = new_keys;
    arr->capacity = new_capacity;

    for (size_t i = arr->size; i < arr->capacity; ++i) {
        arr->offsets[i] = (long)i;
        arr->keys[i] = (int)i;
    }
}

// Linked list management
Node* create_node(int index, unsigned long seed) {
    Node *node = malloc(sizeof(Node));
    if (!node) {
        log_error(stderr, "Failed to allocate memory for node");
        return NULL;
    }

    node->value = custom_rng(0, 100, UNIQUE, seed);
    snprintf(node->key, sizeof(node->key), "Key_%d", index);
    node->ptr = malloc(sizeof(long));
    if (!node->ptr) {
        log_error(stderr, "Failed to allocate memory for long pointer");
        free(node);
        return NULL;
    }
    *node->ptr = 0;
    node->next = NULL;

    return node;
}

void free_linked_list(Node *head) {
    while (head) {
        Node *temp = head;
        head = head->next;
        free(temp->ptr);
        free(temp);
    }
}

// Main function to initialize and manage data structures
void init_data_structures(size_t array_size, size_t list_size, unsigned long seed, FILE *log_fd) {
    DynamicArray offsets_keys;
    dynamic_array_init(&offsets_keys, array_size);

    Node *head = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < list_size; ++i) {
        pthread_mutex_lock(&lock);
        Node *new_node = create_node(i, seed);
        if (!new_node) continue;

        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&lock);

        if ((i + 1) % (array_size / 2) == 0) {
            dynamic_array_resize(&offsets_keys, offsets_keys.capacity * 2);
        }
    }

    // Clean up
    free_linked_list(head);
    free(offsets_keys.offsets);
    free(offsets_keys.keys);
}

int main() {
    size_t array_size = 10;
    size_t list_size = 100;
    unsigned long seed = time(NULL);

    FILE *log_fd = fopen("error_log.txt", "w");
    if (!log_fd) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    init_data_structures(array_size, list_size, seed, log_fd);
    fclose(log_fd);

    return 0;
}
