#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_KEY_LENGTH 256

typedef struct record {
    int value;
    char key[MAX_KEY_LENGTH];
    long *dynamic_var;
    struct record *next;
} record;

typedef struct memory_pool {
    void *memory;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} memory_pool;

typedef struct data_structure {
    long *offsets;
    int *keys;
    size_t offsets_count;
    size_t keys_count;
    record *head_record;
    memory_pool pool;
    unsigned int rand_seed;
    FILE *log_file;
    pthread_mutex_t log_lock;
} data_structure;

// Error logging function
void log_error(data_structure *ds, const char *message) {
    pthread_mutex_lock(&ds->log_lock);
    fprintf(ds->log_file, "Error: %s\n", message);
    fflush(ds->log_file);
    pthread_mutex_unlock(&ds->log_lock);
}

// Memory pool functions
int init_memory_pool(memory_pool *mp, size_t block_size, size_t total_blocks) {
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;

    if (pthread_mutex_init(&mp->lock, NULL)) {
        return -1;
    }

    mp->memory = malloc(block_size * total_blocks);
    if (!mp->memory) {
        log_error(NULL, "Memory pool allocation failed");
        pthread_mutex_destroy(&mp->lock);
        return -1;
    }
    return 0;
}

void* allocate_from_pool(memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used_blocks >= mp->total_blocks) {
        pthread_mutex_unlock(&mp->lock);
        log_error(NULL, "Memory pool exhausted");
        return NULL;
    }

    void *block = ((char*)mp->memory) + (mp->used_blocks++ * mp->block_size);
    pthread_mutex_unlock(&mp->lock);

    return block;
}

void free_memory_pool(memory_pool *mp) {
    free(mp->memory);
    pthread_mutex_destroy(&mp->lock);
}

// Data structure initialization
int init_data_structure(data_structure *ds, size_t offsets_count, size_t keys_count, unsigned int seed, FILE *log_fd) {
    if (init_memory_pool(&ds->pool, sizeof(long), 1000)) {
        return -1;
    }

    ds->offsets = allocate_from_pool(&ds->pool);
    ds->keys = allocate_from_pool(&ds->pool);

    if (!ds->offsets || !ds->keys) {
        free_memory_pool(&ds->pool);
        return -1;
    }

    for (size_t i = 0; i < offsets_count; ++i) {
        ((long *)ds->offsets)[i] = i;
    }

    for (size_t i = 0; i < keys_count; ++i) {
        ds->keys[i] = (int)i;
    }

    ds->offsets_count = offsets_count;
    ds->keys_count = keys_count;

    srand(seed);
    ds->rand_seed = seed;

    ds->head_record = NULL;

    ds->log_file = log_fd;
    if (pthread_mutex_init(&ds->log_lock, NULL)) {
        return -1;
    }

    return 0;
}

// Record operations
void add_record(data_structure *ds, int range_min, int range_max) {
    record *new_node = allocate_from_pool(&ds->pool);
    if (!new_node) return;

    new_node->value = rand() % (range_max - range_min + 1) + range_min;
    snprintf(new_node->key, MAX_KEY_LENGTH, "record_%lu", ds->keys_count);

    size_t var_size = sizeof(long);
    long *dyn_var = allocate_from_pool(&ds->pool);
    if (!dyn_var) {
        free_memory_pool(&ds->pool);
        return;
    }
    new_node->dynamic_var = dyn_var;

    new_node->next = ds->head_record;
    ds->head_record = new_node;
}

void free_records(record *head, memory_pool *mp) {
    while (head) {
        record *temp = head;
        head = head->next;
        if (temp->dynamic_var) {
            pthread_mutex_lock(&mp->lock);
            mp->used_blocks--;
            pthread_mutex_unlock(&mp->lock);
        }
        free_memory_pool(mp); // Free all blocks in the pool
    }
}

// Clean up data structure
void cleanup_data_structure(data_structure *ds) {
    free_records(ds->head_record, &ds->pool);

    if (ds->offsets) {
        pthread_mutex_lock(&ds->pool.lock);
        ds->pool.used_blocks += ds->offsets_count;
        pthread_mutex_unlock(&ds->pool.lock);
    }

    if (ds->keys) {
        pthread_mutex_lock(&ds->pool.lock);
        ds->pool.used_blocks += ds->keys_count;
        pthread_mutex_unlock(&ds->pool.lock);
    }

    free_memory_pool(&ds->pool);

    pthread_mutex_destroy(&ds->log_lock);
}

int main() {
    FILE *logfile = fopen("error.log", "w");
    if (!logfile) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

