// Custom random number generator using an external library
class SecureRandom {
public:
    SecureRandom(unsigned long seed) : engine(seed) {}

    int generate(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(engine);
    }

private:
    std::mt19937 engine;
};

// Function to initialize data structures
void initializeData(
    const std::forward_list<std::string>& inputList,
    long offsetIncrementFactor,
    int keyCount,
    Record recordValueRangeMin,
    Record recordValueRangeMax,
    bool verifyIntegrity = false,
    void (*callback)(const Record&) = nullptr) {

    // Lock for thread safety
    static std::shared_mutex offsetMutex;

    // Allocate and initialize offsets
    long* offsets = new long[inputList.size()];
    {
        std::unique_lock<std::shared_mutex> lock(offsetMutex);
        long offset = 0;
        auto it = inputList.begin();
        for (size_t i = 0; it != inputList.end(); ++it, ++i) {
            offsets[i] = offset;
            offset += offsetIncrementFactor;
        }
    }

    // Allocate and initialize keys
    std::unique_ptr<int[]> keys(new int[keyCount]);
    std::unordered_set<int> uniqueKeys;
    std::random_device rd;
    std::mt19937 gen(rd());

    for (int i = 0; i < keyCount; ++i) {
        do {
            keys[i] = gen();
        } while (!uniqueKeys.insert(keys[i]).second);
    }

    // Allocate and initialize records
    Record* records = new Record[keyCount];
    SecureRandom secureRand(rd());
    std::unordered_set<int> recordValues;

    for (int i = 0; i < keyCount; ++i) {
        int value;
        do {
            value = secureRand.generate(recordValueRangeMin.value, recordValueRangeMax.value);
        } while (!recordValues.insert(value).second);

        records[i].value = value;

        // Process each record with the callback if provided
        if (callback) {
            callback(records[i]);
        }
    }

    // Verify integrity and uniqueness of keys
    if (verifyIntegrity) {
        std::unordered_set<long> offsetSet(offsets, offsets + inputList.size());
        if (offsetSet.size() != inputList.size()) {
            throw std::runtime_error("Duplicate offsets detected.");
        }

        if (uniqueKeys.size() != keyCount) {
            throw std::runtime_error("Duplicate keys detected.");
        }
    }

    // Cleanup
    delete[] offsets;
    delete[] records;

    // Note: 'keys' is managed by unique_ptr, so no need to manually delete it.
}

// Example callback function
void processRecord(const Record& record) {
    std::cout << "Processing record with value: " << record.value << std::endl;
}
