#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum { STRING_TYPE, INT_TYPE, BOOL_TYPE } ValueType;

typedef struct {
    char *name;
    ValueType value_type;
    void *default_value;
    void *current_value;
    char *dns_address; // NULL if not applicable
} Preference;

typedef struct {
    int data_value;
    int min_range;
    int max_range;
} Record;

typedef struct CacheNode {
    void *key;
    void *value;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode **buckets;
    size_t bucket_count;
    size_t entry_count;
    pthread_mutex_t lock;
} LRUCache;

#define INITIAL_PREF_COUNT 10
#define INITIAL_RECORD_COUNT 10

Preference* preferences = NULL;
size_t pref_count = 0;
Record* records = NULL;
size_t record_count = 0;
pthread_mutex_t data_lock = PTHREAD_MUTEX_INITIALIZER;
LRUCache *preference_cache = NULL, *record_cache = NULL;

void cache_init(LRUCache **cache, size_t bucket_count);
void cache_put(LRUCache *cache, void *key, void *value);
void* cache_get(LRUCache *cache, void *key);

void resize_array(void ***array, size_t current_size, size_t new_size) {
    if (*array == NULL) {
        *array = calloc(new_size, sizeof(**array));
    } else {
        *array = realloc(*array, new_size * sizeof(**array));
    }
}

void initialize_arrays(size_t pref_count, size_t record_count) {
    resize_array((void**)&preferences, 0, pref_count);
    resize_array((void**)&records, 0, record_count);

    for (size_t i = 0; i < pref_count; ++i) {
        preferences[i].name = strdup("default");
        preferences[i].value_type = STRING_TYPE;
        preferences[i].current_value = malloc(sizeof(char*));
        strcpy(preferences[i].default_value = strdup("default"), "default");
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].data_value = 0;
        records[i].min_range = 0;
        records[i].max_range = 100;
    }

    cache_init(&preference_cache, pref_count);
    cache_init(&record_cache, record_count);
}

void managePreferencesAndDataProcessing(size_t new_pref_count, size_t new_record_count) {
    pthread_mutex_lock(&data_lock);

    if (new_pref_count > pref_count) {
        resize_array((void**)&preferences, pref_count, new_pref_count);
        for (size_t i = pref_count; i < new_pref_count; ++i) {
            preferences[i].name = strdup("default");
            preferences[i].value_type = STRING_TYPE;
            preferences[i].current_value = malloc(sizeof(char*));
            strcpy(preferences[i].default_value = strdup("default"), "default");
        }
    }

    if (new_record_count > record_count) {
        resize_array((void**)&records, record_count, new_record_count);
        for (size_t i = record_count; i < new_record_count; ++i) {
            records[i].data_value = 0;
            records[i].min_range = 0;
            records[i].max_range = 100;
        }
    }

    pref_count = new_pref_count;
    record_count = new_record_count;

    pthread_mutex_unlock(&data_lock);
}

void cache_init(LRUCache **cache, size_t bucket_count) {
    *cache = malloc(sizeof(LRUCache));
    (*cache)->buckets = calloc(bucket_count, sizeof(CacheNode*));
    (*cache)->bucket_count = bucket_count;
    (*cache)->entry_count = 0;
    pthread_mutex_init(&((*cache)->lock), NULL);
}

void cache_put(LRUCache *cache, void *key, void *value) {
    // Simplified LRU Cache Insertion Logic
    size_t index = ((uintptr_t)key % cache->bucket_count);
    pthread_mutex_lock(&cache->lock);

    CacheNode *node = malloc(sizeof(CacheNode));
    node->key = key;
    node->value = value;
    node->next = cache->buckets[index];
    cache->buckets[index] = node;

    pthread_mutex_unlock(&cache->lock);
}

void* cache_get(LRUCache *cache, void *key) {
    size_t index = ((uintptr_t)key % cache->bucket_count);
    CacheNode *node = cache->buckets[index];

    while (node != NULL) {
        if (node->key == key) {
            return node->value;
        }
        node = node->next;
    }

    return NULL;
}

int main() {
    initialize_arrays(INITIAL_PREF_COUNT, INITIAL_RECORD_COUNT);
    managePreferencesAndDataProcessing(20, 20);

    // Example usage
    Preference *pref = preferences + 5;
    pref->name = strdup("theme");
    pref->value_type = STRING_TYPE;
    pref->current_value = malloc(sizeof(char*));
    strcpy(pref->default_value = strdup("dark"), "dark");

    Record *record = records + 3;
    record->data_value = 42;

    cache_put(preference_cache, (void*)pref, pref);
    cache_put(record_cache, (void*)record, record);

    Preference *cached_pref = (Preference*)cache_get(preference_cache, (void*)pref);
    Record *cached_record = (Record*)cache_get(record_cache, (void*)record);

    if (cached_pref) {
        printf("Cached Pref: %s\n", cached_pref->default_value);
    }

    if (cached_record) {
        printf("Cached Record Value: %d\n", cached_record->data_value);
    }

    return 0;
}
