    for (size_t i = 0; i < offsetKeySize; ++i) {
        free(keys[i]);
    }
    free(keys);
    free(offsets);
    free(inputIntegers);

    pthread_mutex_destroy(&lock);
}

void freeMemory(Record **records, size_t recordCount) {
    if (!records || !*records) return;
    for (size_t i = 0; i < recordCount; ++i) {
        free((*records)[i].key);
        free((*records)[i].longPtr);
        free((*records)[i].doublePtr);
    }
    free(*records);
}

int findMaxInArray(const int *array, size_t size) {
    if (!array || size == 0) return INT_MIN;
    int maxVal = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > maxVal) {
            maxVal = array[i];
        }
    }
    return maxVal;
}

// Placeholder for external library functions
int secure_random(int min, int max) { return rand() % (max - min + 1) + min; }
double external_distribution() { return ((double)rand()) / RAND_MAX; }
