And here is the PHP function for managing user authentication and data retrieval:

```php
<?php

function oauth_authenticate($clientId, $clientSecret, $authUrl, $redirectUri) {
    session_start();

    // Step 1: Redirect to OAuth provider authorization URL
    if (!isset($_GET['code'])) {
        $params = [
            'response_type' => 'code',
            'client_id' => $clientId,
            'redirect_uri' => $redirectUri,
            'scope' => 'read'
        ];

        $authUrlWithParams = sprintf('%s?%s', $authUrl, http_build_query($params));
        header('Location: ' . $authUrlWithParams);
        exit;
    }

    // Step 2: Exchange authorization code for access token
    $authorizationCode = $_GET['code'];
    $tokenRequestParams = [
        'grant_type' => 'authorization_code',
        'code' => $authorizationCode,
        'redirect_uri' => $redirectUri,
        'client_id' => $clientId,
        'client_secret' => $clientSecret
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $authUrl . '/token');
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($tokenRequestParams));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);

    if (curl_errno($ch)) {
        error_log('Curl error: ' . curl_error($ch));
        exit;
    }

    $tokenData = json_decode($response);
    if (!isset($tokenData->access_token)) {
        error_log('Failed to obtain access token');
        exit;
    }

    // Store the access token in session
    $_SESSION['access_token'] = $tokenData->access_token;

    curl_close($ch);

    return true;
}

function fetch_user_data($apiUrl, $accessToken) {
    $headers = [
        'Authorization: Bearer ' . $accessToken
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $apiUrl);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);

    if (curl_errno($ch)) {
        error_log('Curl error: ' . curl_error($ch));
        return false;
    }

    $userData = json_decode($response);
    curl_close($ch);

    return $userData;
}
?>
