            goto cleanup;
        }

        // Populate metadata
        record[i].metadata->timestamp = time(NULL);
        record[i].metadata->flag = secure_random() & 1;  // Random boolean

        // Initialize dependencies linked list
        Dependency* dep_head = NULL;
        Dependency* prev_dep = NULL;

        for (int j = 0; j < 3; ++j) {  // Example: Each record depends on 3 others
            int dependency_index = secure_random() % num_records;
            Dependency* new_dep = malloc(sizeof(Dependency));
            if (!new_dep) {
                perror("Failed to allocate memory for dependency");
                free_dependencies(dep_head);
                free(record[i].metadata);
                free(record[i].offset_ptr);
                goto cleanup;
            }
            new_dep->record_index = dependency_index;
            new_dep->next = NULL;

            if (prev_dep) {
                prev_dep->next = new_dep;
            } else {
                dep_head = new_dep;
            }
            prev_dep = new_dep;
        }

        record[i].metadata->dependencies = dep_head;

        // Invoke callback function if provided
        if (callback) {
            pthread_mutex_lock(&lock);
            callback(&record[i]);
            pthread_mutex_unlock(&lock);
        }
    }

