typedef struct {
    double temperature;
    char unit;
} record;

int validate_record(record r) {
    // Validate unit and temperature range
    if (r.unit != 'C' && r.unit != 'F') return 0; // Invalid unit
    if (r.temperature < -50.0 || r.temperature > 100.0) return 0; // Out of valid temperature range
    return 1;
}

record* allocate_records(size_t num_records, size_t *allocated_count) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        // Simulate receiving data and validation check
        records[i].temperature = -50.0 + ((double)rand() / RAND_MAX) * 150.0;
        records[i].unit = 'C' + rand() % 2;

        if (!validate_record(records[i])) {
            fprintf(stderr, "Invalid record detected at index %zu\n", i);
            free(records); // Free allocated memory on error
            return NULL;
        }
    }

    *allocated_count = num_records; // Set the count of valid records
    return records;
}

void free_records(record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t num_records = 1000;
    size_t allocated_count;

