```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int randomNumber;
    char *keyBuffer;
    long *metadata;
} Record;

void initializeDataStore(long seed, size_t arraySize, void (*callback)(Record*)) {
    // Seed random number generator
    srand(seed);

    // Allocate memory for arrays
    long* offsetArray = malloc(arraySize * sizeof(long));
    int* keyArray = malloc(arraySize * sizeof(int));

    Record* recordArray = malloc(arraySize * sizeof(Record));

    if (!offsetArray || !keyArray || !recordArray) {
        perror("Memory allocation failed");
        // Free any allocated memory before exiting
        free(offsetArray);
        free(keyArray);
        free(recordArray);
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (size_t i = 0; i < arraySize; ++i) {
        offsetArray[i] = seed + i;
        keyArray[i] = i;

        recordArray[i].randomNumber = rand() % 100; // Random number between 0 and 99

        const size_t keyBufferSize = 256;
        recordArray[i].keyBuffer = malloc(keyBufferSize);
        if (!recordArray[i].keyBuffer) {
            perror("Failed to allocate memory for key buffer");
            // Free previously allocated resources
            free(offsetArray);
            free(keyArray);
            for (size_t j = 0; j < i; ++j) {
                free(recordArray[j].keyBuffer);
                free(recordArray[j].metadata);
            }
            free(recordArray);
            exit(EXIT_FAILURE);
        }

        snprintf(recordArray[i].keyBuffer, keyBufferSize, "Key_%zu", i);

        recordArray[i].metadata = malloc(sizeof(long));
        if (!recordArray[i].metadata) {
            perror("Failed to allocate memory for metadata");
            // Free previously allocated resources
            free(offsetArray);
            free(keyArray);
            for (size_t j = 0; j <= i; ++j) {
                free(recordArray[j].keyBuffer);
                free(recordArray[j].metadata);
            }
            free(recordArray);
            exit(EXIT_FAILURE);
        }

        *recordArray[i].metadata = offsetArray[i]; // Example metadata

        if (callback) {
            callback(&recordArray[i]);
        }
    }

    // Function exits here; remember to deallocate resources in real use case
}

// Example callback function
void exampleCallback(Record* record) {
    printf("Initialized Record: Random Number = %d, Key = %s\n", record->randomNumber, record->keyBuffer);
}
