### PHP Function: `authenticateAndRetrieveUser`

```php
session_start();

function authenticateAndRetrieveUser($clientId, $clientSecret, $redirectUri, $authUrl, $tokenUrl) {
    if (!isset($_GET['code'])) {
        // Initiate OAuth flow
        $params = [
            'response_type' => 'code',
            'client_id' => $clientId,
            'redirect_uri' => $redirectUri
        ];

        $authEndpoint = $authUrl . '?' . http_build_query($params);
        header('Location: ' . $authEndpoint);
        exit;
    } else {
        // Exchange authorization code for access token
        $code = $_GET['code'];
        $tokenData = [
            'grant_type' => 'authorization_code',
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
            'redirect_uri' => $redirectUri,
            'code' => $code
        ];

        $response = file_get_contents($tokenUrl, false, stream_context_create([
            'http' => [
                'method' => 'POST',
                'header' => "Content-Type: application/x-www-form-urlencoded\r\n",
                'content' => http_build_query($tokenData),
            ]
        ]));

        if (!$response) {
            die('Error obtaining access token');
        }

        $data = json_decode($response, true);
        if (isset($data['access_token'])) {
            $_SESSION['access_token'] = $data['access_token'];
            $_SESSION['expires_at'] = time() + $data['expires_in'];

            // Retrieve user data
            return retrieveUserData($_SESSION['access_token']);
        } else {
            die('Error: ' . $data['error_description']);
        }
    }
}

function retrieveUserData($accessToken) {
    $apiUrl = 'https://example.com/api/user'; // Example API URL
    $response = file_get_contents($apiUrl, false, stream_context_create([
        'http' => [
            'header' => "Authorization: Bearer {$accessToken}\r\n",
        ]
    ]));

    if (!$response) {
        die('Error retrieving user data');
    }

    return json_decode($response, true);
}

function refreshTokenIfNeeded() {
    if (isset($_SESSION['expires_at']) && time() > $_SESSION['expires_at'] - 300) { // Refresh 5 minutes before expiry
        // Logic to refresh token using stored client credentials and refresh token
    }
}
