long generate_random_number(long range_limit) {
    // Using a more reliable pseudo-random generator from an external library
    // For demonstration purposes, using rand() as a placeholder
    return rand() % (range_limit + 1);
}

void initialize_data_structure(DataStructure *ds, size_t num_offsets, size_t num_keys, size_t num_records) {
    pthread_mutex_init(&ds->lock, NULL);

    ds->num_offsets = num_offsets;
    ds->num_keys = num_keys;
    ds->num_records = num_records;

    ds->offsets = (long *)malloc(num_offsets * sizeof(long));
    ds->keys = (int *)malloc(num_keys * sizeof(int));
    ds->records = (Record *)malloc(num_records * sizeof(Record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void free_data_structure(DataStructure *ds) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->num_records; ++i) {
        free(ds->records[i].identifier);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

void populate_offsets(DataStructure *ds, long range_limit) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->num_offsets; ++i) {
        ds->offsets[i] = generate_random_number(range_limit);
    }

    pthread_mutex_unlock(&ds->lock);
}

void generate_keys(DataStructure *ds) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->num_keys; ++i) {
        ds->keys[i] = (int)i;
    }

    pthread_mutex_unlock(&ds->lock);
}

void populate_records(DataStructure *ds, int value_range_min, int value_range_max) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->num_records; ++i) {
        ds->records[i].value = generate_random_number(value_range_max - value_range_min) + value_range_min;
        char identifier[20];
        snprintf(identifier, sizeof(identifier), "ID_%zu", i);

        // Ensure unique identifiers
        ds->records[i].identifier = strdup(identifier);

        log_message("Record populated");
    }

    pthread_mutex_unlock(&ds->lock);
}

void log_message(const char *message) {
    printf("%s\n", message);  // Simple logging to console; can be replaced with file-based logging
}

void serialize_to_file(const DataStructure *ds, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock((pthread_mutex_t *)&ds->lock);

    fprintf(file, "Offsets: ");
    for (size_t i = 0; i < ds->num_offsets; ++i) {
        fprintf(file, "%ld ", ds->offsets[i]);
    }
    fprintf(file, "\nKeys: ");
    for (size_t i = 0; i < ds->num_keys; ++i) {
        fprintf(file, "%d ", ds->keys[i]);
    }
    fprintf(file, "\nRecords:\n");
    for (size_t i = 0; i < ds->num_records; ++i) {
        fprintf(file, "Value: %d, Identifier: %s\n", ds->records[i].value, ds->records[i].identifier);
    }

    pthread_mutex_unlock((pthread_mutex_t *)&ds->lock);

    fclose(file);
}

int verify_integrity(const DataStructure *ds) {
    pthread_mutex_lock((pthread_mutex_t *)&ds->lock);

    // Simple checksum: sum of all offsets and keys
    long offset_sum = 0;
    int key_sum = 0;

    for (size_t i = 0; i < ds->num_offsets; ++i) {
        offset_sum += ds->offsets[i];
    }

    for (size_t i = 0; i < ds->num_keys; ++i) {
        key_sum += ds->keys[i];
    }

    pthread_mutex_unlock((pthread_mutex_t *)&ds->lock);

    // Simple integrity check: ensure sums are not zero
    return offset_sum != 0 && key_sum != 0;
}

int main() {
    srand(time(NULL));  // Seed the random number generator

    DataStructure ds;
    initialize_data_structure(&ds, 100, 50, 75);
    populate_offsets(&ds, 10000);
    generate_keys(&ds);
    populate_records(&ds, 1, 100);

    log_message("Data structure initialized and populated.");

    if (verify_integrity(&ds)) {
        printf("Integrity check passed.\n");
    } else {
        printf("Integrity check failed.\n");
    }

    serialize_to_file(&ds, "data_structure.txt");

    free_data_structure(&ds);

    return 0;
}
