int init_records_and_load_bundle(long* offset, size_t offset_size,
                                 int* keys, size_t keys_size,
                                 Record** records, size_t record_size,
                                 const char* filename,
                                 unsigned int random_seed, 
                                 int min_random_value, 
                                 int max_random_value,
                                 RecordCallback callback) {
    // Error handling flag
    int error_occurred = 0;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize the offset and keys arrays with sequential numbers
    for (size_t i = 0; i < offset_size; ++i) {
        offset[i] = i;
    }

    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records array
    *records = malloc(record_size * sizeof(Record));
    if (!*records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        error_occurred = 1;
        goto cleanup;
    }

    // Seed the random number generator
    srand(random_seed);

    for (size_t i = 0; i < record_size && !error_occurred; ++i) {
        (*records)[i].value = min_random_value + rand() % (max_random_value - min_random_value + 1);

        // Initialize key string
