        // Allocate memory for dynamic long pointer in record
        (*records)[i].dynamic_long = malloc(sizeof(long));
        if (!(*records)[i].dynamic_long) {
            fprintf(stderr, "Failed to allocate memory for dynamic long\n");
            error_occurred = 1;
            break; // Break instead of continue to handle deallocation in cleanup
        }

        pthread_mutex_lock(&lock);
        (*records)[i].dynamic_long[0] = rand() % 1000000L; // Example initialization

        if (callback) {
            callback((*records)[i]);
        }

        pthread_mutex_unlock(&lock);
    }

    // Simulate loading a resource bundle and return its size
    int bundle_items = 0;
    FILE* file = fopen(filename, "r");
    if (file) {
        char buffer[256];
        while (fgets(buffer, sizeof(buffer), file)) {
            ++bundle_items;
        }
        fclose(file);
    } else {
        fprintf(stderr, "Failed to load resource bundle\n");
        error_occurred = 1;
    }

cleanup:
    pthread_mutex_destroy(&lock);

    // Cleanup and deallocation in case of errors
    if (error_occurred) {
        for (size_t i = 0; i < record_size; ++i) {
            free((*records)[i].dynamic_long);
        }
        free(*records);
        *records = NULL;
    }

    return bundle_items;
}

