#include <pthread.h>

typedef enum {
    STRING,
    INTEGER,
    FLOATING_POINT
} ResourceType;

typedef struct {
    char name[256];
    ResourceType type;
    union {
        const char* str_val;
        int int_val;
        float float_val;
    } default_value;
    union {
        const char* str_val;
        int int_val;
        float float_val;
    } current_value;
    unsigned long id; // unique identifier
} Resource;

typedef struct {
    double value;
    unsigned long id; // unique identifier
} Chunk;

typedef struct CacheEntry {
    void *data;
    unsigned long id;
    struct CacheEntry *next;
} CacheEntry;

typedef struct {
    CacheEntry *head;
    size_t size;
    pthread_mutex_t lock;
} ResourceCache;

typedef struct {
    Resource *resources;
    size_t resource_count;
    Chunk *chunks;
    size_t chunk_count;
    ResourceCache cache;
} ResourceManager;

void initialize_cache(ResourceCache *cache) {
    cache->head = NULL;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void free_cache_entry(CacheEntry *entry) {
    if (entry->data) free(entry->data);
    free(entry);
}

void evict_from_cache(ResourceCache *cache) {
    pthread_mutex_lock(&cache->lock);
    CacheEntry *entry = cache->head;
    if (entry) {
        cache->head = entry->next;
        free_cache_entry(entry);
        cache->size--;
    }
    pthread_mutex_unlock(&cache->lock);
}

void add_to_cache(ResourceCache *cache, void *data, unsigned long id) {
    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    if (!new_entry) return;

    new_entry->data = data;
    new_entry->id = id;
    new_entry->next = cache->head;

    pthread_mutex_lock(&cache->lock);
    cache->head = new_entry;
    cache->size++;
    if (cache->size > 10) { // example eviction policy
        evict_from_cache(cache);
    }
    pthread_mutex_unlock(&cache->lock);
}

void *find_in_cache(ResourceCache *cache, unsigned long id) {
    pthread_mutex_lock(&cache->lock);
    for (CacheEntry *entry = cache->head; entry != NULL; entry = entry->next) {
        if (entry->id == id) {
            pthread_mutex_unlock(&cache->lock);
            return entry->data;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void handleDynamicResourceAllocationAndCacheManagement(size_t initial_resource_count, size_t initial_chunk_count, void (*callback)(const Resource*, const Chunk*)) {
    ResourceManager manager;

    // Initialize resources
    manager.resources = malloc(initial_resource_count * sizeof(Resource));
    if (!manager.resources) exit(EXIT_FAILURE);
    for (size_t i = 0; i < initial_resource_count; ++i) {
        manager.resources[i].default_value.int_val = 0;  // default value example
        manager.resources[i].current_value.int_val = 0;
    }

    // Initialize chunks
    manager.chunks = malloc(initial_chunk_count * sizeof(Chunk));
    if (!manager.chunks) exit(EXIT_FAILURE);
    for (size_t i = 0; i < initial_chunk_count; ++i) {
        manager.chunks[i].value = 0.0;
    }

    // Initialize cache
    initialize_cache(&manager.cache);

    pthread_mutex_t resource_lock = PTHREAD_MUTEX_INITIALIZER;

    void add_resource(const char *name, ResourceType type, union Resource::union_type default_value, unsigned long id) {
        pthread_mutex_lock(&resource_lock);

        if (manager.resource_count >= sizeof(ResourceManager).resource_count) { // resize logic
            size_t new_size = manager.resource_count * 2;
            manager.resources = realloc(manager.resources, new_size * sizeof(Resource));
            if (!manager.resources) exit(EXIT_FAILURE);
        }

        Resource *res = &manager.resources[manager.resource_count++];
        strncpy(res->name, name, sizeof(res->name));
        res->type = type;
        memcpy(&res->default_value, &default_value, sizeof(default_value));
        res->current_value.int_val = default_value.int_val; // assuming int for simplicity
        res->id = id;

        add_to_cache(&manager.cache, res, id);

        pthread_mutex_unlock(&resource_lock);
    }

    void add_chunk(double value, unsigned long id) {
        pthread_mutex_lock(&resource_lock);

        if (manager.chunk_count >= sizeof(ResourceManager).chunk_count) { // resize logic
            size_t new_size = manager.chunk_count * 2;
            manager.chunks = realloc(manager.chunks, new_size * sizeof(Chunk));
            if (!manager.chunks) exit(EXIT_FAILURE);
        }

        Chunk *ch = &manager.chunks[manager.chunk_count++];
        ch->value = value;
        ch->id = id;

        pthread_mutex_unlock(&resource_lock);
    }

    // Example callback function usage
    if (callback) {
        for (size_t i = 0; i < manager.resource_count; ++i) {
            callback(&manager.resources[i], NULL);
        }
        for (size_t i = 0; i < manager.chunk_count; ++i) {
            callback(NULL, &manager.chunks[i]);
        }
    }

    // Clean up
    pthread_mutex_destroy(&resource_lock);
}

int main() {
    handleDynamicResourceAllocationAndCacheManagement(10, 5, NULL);
    return 0;
}
