#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure definition for a record
typedef struct {
    int key;
    char description[256];
    long* offset;
} record_t;

// Memory pool structure
typedef struct {
    size_t block_size;
    void* memory_block;
    size_t num_blocks;
    size_t blocks_used;
    pthread_mutex_t lock; // For thread safety
} memory_pool_t;

// Function to initialize a memory pool
int init_memory_pool(memory_pool_t *pool, size_t block_size, size_t num_blocks) {
    if (pthread_mutex_init(&pool->lock, NULL)) return -1;
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks_used = 0;

    pool->memory_block = malloc(block_size * num_blocks);
    if (!pool->memory_block) {
        pthread_mutex_destroy(&pool->lock);
        return -1;
    }

    return 0;
}

// Function to allocate memory from the pool
void* mem_pool_alloc(memory_pool_t *pool, size_t size) {
    void *ptr = NULL;

    pthread_mutex_lock(&pool->lock);

    if (size > pool->block_size || pool->blocks_used >= pool->num_blocks) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    ptr = (char*)pool->memory_block + (pool->blocks_used * pool->block_size);
    pool->blocks_used++;

    pthread_mutex_unlock(&pool->lock);

    if (ptr) printf("Allocated memory at %p\n", ptr);  // Logging allocation

    return ptr;
}

// Function to deallocate all memory from the pool
void mem_pool_free(memory_pool_t *pool) {
    free(pool->memory_block);
    pthread_mutex_destroy(&pool->lock);

    printf("Freed all memory from pool\n");  // Logging deallocation
}

// Callback type for post-initialization processing of records
typedef void (*record_callback_t)(record_t *);

// Function to generate a random integer within range
int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Main function to process records and find the maximum key value
void processRecordsAndFindMax(size_t num_records, int start_key, int key_increment,
                              int offset_start, long offset_increment, int range_min, int range_max,
                              record_callback_t callback) {

    srand(time(NULL));  // Seed for random number generation

    // Initialize memory pool for records
    memory_pool_t pool;
    if (init_memory_pool(&pool, sizeof(record_t), num_records)) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return;
    }

    record_t *records = (record_t*)mem_pool_alloc(&pool, num_records * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        mem_pool_free(&pool);
        return;
    }

    int max_key = INT_MIN;

    // Populate the records array
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = start_key + i * key_increment;
        snprintf(records[i].description, sizeof(records[i].description), "Record %zu", i);

        long* offset = (long*)mem_pool_alloc(&pool, sizeof(long));
        if (!offset) {
            fprintf(stderr, "Memory allocation for offsets failed\n");
            break;
        }
        *offset = offset_start + i * offset_increment;
        records[i].offset = offset;

        int random_key = generate_random_int(range_min, range_max);
        if (random_key > max_key) max_key = random_key;

        // Invoke callback function
        if (callback) {
            pthread_t thread_id;
            pthread_create(&thread_id, NULL, (void* (*)(void*))callback, &records[i]);
            pthread_join(thread_id, NULL);
        }
    }

    printf("Maximum key value: %d\n", max_key);

    // Free all allocated memory
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].offset) free(records[i].offset);
    }
    mem_pool_free(&pool);
}

// Example callback function for post-initialization processing of records
void record_processing_callback(record_t *record) {
    printf("Processing Record: Key=%d, Description=%s\n", record->key, record->description);
}
