#include <stdint.h>
#include <pthread.h>

// Assume external library provides this function for random number generation
long generate_random_long(long min, long max);
int generate_random_int(int min, int max);

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    long *offsets;
    int *keys;
    Record *records;
    int *available_integers;
    size_t array_size;
    size_t record_count;
    int start_index;
    int free_flag; // 0 means active, 1 means free resources
} DataStructureManager;

// Function to initialize the data structures
int init_data_structures(DataStructureManager *manager, size_t array_size, size_t record_count,
                         long min_offset, long max_offset, int min_int, int max_int) {
    if (manager->free_flag == 1) return -1; // Already freed

    pthread_mutex_init(&manager->lock, NULL);

    manager->array_size = array_size;
    manager->record_count = record_count;

    // Allocate and initialize offsets
    manager->offsets = (long *)malloc(array_size * sizeof(long));
    if (!manager->offsets) goto cleanup;

    for (size_t i = 0; i < array_size; ++i) {
        manager->offsets[i] = generate_random_long(min_offset, max_offset);
    }

    // Allocate and initialize keys
    manager->keys = (int *)malloc(array_size * sizeof(int));
    if (!manager->keys) goto cleanup;

    for (size_t i = 0; i < array_size; ++i) {
        manager->keys[i] = (int)i;
    }

    // Initialize records and circular buffer
    manager->records = (Record *)malloc(record_count * sizeof(Record));
    if (!manager->records) goto cleanup;

    manager->available_integers = (int *)malloc(record_count * sizeof(int));
    if (!manager->available_integers) goto cleanup;

    for (size_t i = 0; i < record_count; ++i) {
        manager->available_integers[i] = generate_random_int(min_int, max_int);
    }

    manager->start_index = 0;

    return 0;

cleanup:
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->available_integers);

    pthread_mutex_destroy(&manager->lock);
    return -1;
}

// Function to free all allocated memory
void free_data_structures(DataStructureManager *manager) {
    if (manager->free_flag == 1) return; // Already freed

    pthread_mutex_lock(&manager->lock);

    free(manager->offsets);
    manager->offsets = NULL;

    free(manager->keys);
    manager->keys = NULL;

    free(manager->records);
    manager->records = NULL;

    free(manager->available_integers);
    manager->available_integers = NULL;

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);

    manager->free_flag = 1;
}

// Example usage
int main() {
    DataStructureManager manager = {0};
    if (init_data_structures(&manager, 10, 5, 100, 200, 0, 50) != 0) {
        fprintf(stderr, "Failed to initialize data structures.\n");
        return EXIT_FAILURE;
    }

    // Use the data structures...

    free_data_structures(&manager);

    return EXIT_SUCCESS;
}
