record* manage_dynamic_memory(size_t n, size_t m, unsigned int seed) {
    // Error checking variables
    void *ptr = NULL;
    record *records = NULL;

    // Allocate memory for offsets and keys with alignment
    ptr = aligned_alloc(alignof(long), n * sizeof(long));
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for long offsets\n");
        return NULL;
    }
    long *offsets = (long*)ptr;

    ptr = aligned_alloc(alignof(int), m * sizeof(int));
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for integer keys\n");
        free(offsets);
        return NULL;
    }
    int *keys = (int*)ptr;

    // Allocate memory for records
    ptr = malloc(n * sizeof(record));
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for record structures\n");
        free(keys);
        free(offsets);
        return NULL;
    }
    records = (record*)ptr;

    // Seed the random number generator
    srand(seed);

    // Initialize offsets and keys with sample values
    for (size_t i = 0; i < n; ++i) {
