    }
    for (size_t i = 0; i < m; ++i) {
        keys[i] = rand() % 10000; // Example key value
    }

    // Initialize records
    for (size_t i = 0; i < n; ++i) {
        ptr = malloc(sizeof(int));
        if (!ptr) {
            fprintf(stderr, "Memory allocation failed for int* value\n");

            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(records[j].value);
            }
            free(keys);
            free(offsets);
            free(records);
            return NULL;
        }

        records[i].value = (int*)ptr;
        *records[i].value = rand() % 1001; // Random value between 0 and 1000

        records[i].key = keys[i % m]; // Assign key from the keys array
        records[i].offset = offsets[i]; // Assign offset from the offsets array
    }

    return records;
}

// Example usage:
