class InterfaceStatusChecker implements Callable<Boolean> {
    private final NetworkInterface interfaceObj;
    private final Logger logger;

    public InterfaceStatusChecker(NetworkInterface interfaceObj, Logger logger) {
        this.interfaceObj = interfaceObj;
        this.logger = logger;
    }

    @Override
    public Boolean call() throws Exception {
        int attempts = 0;
        int maxAttempts = 3;
        long backoffTime = 1000; // Initial backoff time in milliseconds

        while (attempts < maxAttempts) {
            try {
                if (isInterfaceOperational(interfaceObj)) {
                    reportStatusToMonitoringService(interfaceObj, true);
                    logger.info("Interface " + interfaceObj.getName() + " is operational.");
                    return true;
                } else {
                    attempts++;
                    long sleepTime = backoffTime * Math.pow(2, attempts - 1); // Exponential backoff
                    Thread.sleep(sleepTime);
                }
            } catch (Exception e) {
                logger.warning("Error checking interface: " + interfaceObj.getName() + ", attempt " + attempts);
                attempts++;
                long sleepTime = backoffTime * Math.pow(2, attempts - 1); // Exponential backoff
                Thread.sleep(sleepTime);
            }
        }

        reportStatusToMonitoringService(interfaceObj, false);
        logger.warning("Interface " + interfaceObj.getName() + " failed to become operational after " + maxAttempts + " attempts.");
        return false;
    }

