typedef struct {
    int value;
} record;

typedef int (*transformation_func)(int key, long offset, int current_value);

// Function to fetch keys and offsets from an external data source.
void fetch_external_data(int *keys_array, size_t array_size, long *offsets_array, size_t array_size_long, int *success) {
    // Simulated external data fetching
    for (size_t i = 0; i < array_size; ++i) {
        keys_array[i] = rand() % 100;  // Random key values
    }
    for (size_t i = 0; i < array_size_long; ++i) {
        offsets_array[i] = rand() % 1000;  // Random offset values
    }
    *success = 1;
}

void initialize_data(int *keys_array, size_t keys_size,
                     long *offsets_array, size_t offsets_size,
                     record **records, size_t *record_count,
                     int min_value, int max_value, 
                     transformation_func transform, 
                     size_t array_size, size_t max_memory_limit) {

    size_t key_mem = sizeof(int) * keys_size;
    size_t offset_mem = sizeof(long) * offsets_size;

    size_t record_struct_size = sizeof(record);
    size_t total_fixed_mem = key_mem + offset_mem;

    // Calculate maximum possible records within memory limit
    *record_count = (max_memory_limit - total_fixed_mem) / record_struct_size;
    if (*record_count > array_size) {
        *record_count = array_size;
    }

    if (total_fixed_mem + (*record_count) * record_struct_size > max_memory_limit) {
        printf("Memory limit exceeded, reducing records count.\n");
        size_t extra_mem_needed = total_fixed_mem + (*record_count) * record_struct_size - max_memory_limit;
        size_t reduced_records = extra_mem_needed / record_struct_size;
        *record_count -= reduced_records;
    }

    *records = (record *)malloc(*record_count * sizeof(record));

    if (*records == NULL || keys_array == NULL || offsets_array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < *record_count; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    int success;
    fetch_external_data(keys_array, keys_size, offsets_array, offsets_size, &success);

    if (!success) {
        fprintf(stderr, "Failed to fetch external data.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < *record_count; ++i) {
        pthread_mutex_lock(&mutex);
        (*records)[i].value = transform(keys_array[i % keys_size], offsets_array[i % offsets_size], (*records)[i].value);
        pthread_mutex_unlock(&mutex);
    }

    printf("Total memory used: %zu bytes\n", total_fixed_mem + *record_count * record_struct_size);

    // Cleanup
    free(*records);
    pthread_mutex_destroy(&mutex);
}

// Example transformation function
int example_transform(int key, long offset, int current_value) {
    return (key + offset) % 1000 + current_value;
}

int main() {
    size_t array_size = 10;
    size_t record_count = 50;
    size_t max_memory_limit = sizeof(int) * array_size + sizeof(long) * array_size + record_count * sizeof(record);

    int *keys_array = (int *)malloc(array_size * sizeof(int));
    long *offsets_array = (long *)malloc(array_size * sizeof(long));
    record *records;

    initialize_data(keys_array, array_size, offsets_array, array_size,
                    &records, &record_count, 0, 100, example_transform, 
                    array_size, max_memory_limit);

    free(keys_array);
    free(offsets_array);

    return 0;
}
