        {
            JObject payload = JObject.Parse(jsonPayload);

            // Validate structure and required fields.
            if (!payload.ContainsKey("metadata") || !payload.ContainsKey("messages"))
                throw new FormatException("Invalid JSON format: Required keys missing.");

            var metadata = (JObject)payload["metadata"];
            var messages = (JArray)payload["messages"];

