                var msgData = (JObject)message;
                string encodedMessage = (string)msgData["encoded"];
                byte[] decodedBytes;

                if (IsValidBase64(encodedMessage))
                {
                    decodedBytes = Convert.FromBase64String(encodedMessage);
                }
                else
                {
                    throw new FormatException("Invalid Base64 encoding.");
                }

