record* allocate_and_initialize_records(size_t n, size_t m, unsigned long seed, int enable_logging) {
    if (enable_logging) log_message("Starting memory allocation.");

    // Memory alignment
    size_t offset_alignment = sizeof(long);
    size_t key_alignment = sizeof(int);

    long *offsets = aligned_alloc(offset_alignment, n * sizeof(long));
    int *keys = aligned_alloc(key_alignment, m * sizeof(int));

    if (!offsets || !keys) {
        log_message("Memory allocation for offsets or keys failed.");
        free_memory(NULL, n, &offsets, &keys);
        return NULL;
    }

    // Initialize random number generator
    srand(seed);

    record **records = malloc(n * sizeof(record*));
    if (!records) {
        log_message("Memory allocation for records pointers array failed.");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Allocate and initialize records
    for (size_t i = 0; i < n; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            log_message("Memory allocation for record failed.");
            for (size_t j = 0; j < i; ++j) free(records[j]->value);
            free_memory(&records, n, &offsets, &keys);
            return NULL;
        }

        // Initialize fields
        records[i]->value = malloc(sizeof(int));
        if (!records[i]->value) {
            log_message("Memory allocation for record value failed.");
            free(records[i]);
            for (size_t j = 0; j < i; ++j) free(records[j]->value);
            free_memory(&records, n, &offsets, &keys);
            return NULL;
        }

        records[i]->key = rand() % m;
        offsets[i] = rand();
        records[i]->offset = offsets[i];
        *records[i]->value = rand() % 1001;

        if (enable_logging) {
            log_message("Record initialized successfully.");
        }
    }

    record *result = malloc(n * sizeof(record));
    for (size_t i = 0; i < n; ++i) {
        result[i].value = records[i]->value;
        result[i].key = records[i]->key;
        result[i].offset = records[i]->offset;
        free(records[i]);
    }
    free(records);

    if (enable_logging) log_message("Memory allocation completed successfully.");

    return result;
}

// Example of freeing memory
void deallocate_records(record *records, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        free(records[i].value);
    }
    free(records);
}
