    private const int MaxRetryAttempts = 3;

    public FilePathProcessor(ILogger<FilePathProcessor> logger)
    {
        _logger = logger;
    }

    public async Task ProcessFilesAsync(Dictionary<string, string> placeholderValues, string configFilePath)
    {
        foreach (var filePath in GetFileList())
        {
            try
            {
                if (IsValidPath(filePath))
                {
                    var encryptionKey = await FetchEncryptionKeyWithRetryAsync();
                    var fileHash = ComputeSha256Hash(filePath, encryptionKey);

                    UpdateConfigFile(configFilePath, placeholderValues, fileHash);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error processing file {filePath}");
                // Implement recovery actions like notifications here
            }
        }
