    }

    private bool IsValidPath(string path)
    {
        try
        {
            return File.Exists(path);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Invalid path: {path}");
            return false;
        }
    }

    private async Task<string> FetchEncryptionKeyWithRetryAsync()
    {
        using var httpClient = new HttpClient();
        int attempt = 0;

        while (attempt < MaxRetryAttempts)
        {
            try
            {
                var response = await httpClient.GetAsync("https://api.example.com/encryption-key");
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching encryption key.");
            }

            attempt++;
            await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Exponential backoff
        }

        throw new Exception("Failed to fetch encryption key after multiple attempts.");
    }

    private string ComputeSha256Hash(string filePath, string encryptionKey)
    {
        using var sha256 = SHA256.Create();
        using var stream = File.OpenRead(filePath);

        const int bufferSize = 8192;
        byte[] buffer = new byte[bufferSize];
        int bytesRead;

        while ((bytesRead = stream.Read(buffer, 0, bufferSize)) > 0)
        {
            // Optionally use encryptionKey for additional processing if needed
            var hashBytes = sha256.ComputeHash(buffer, 0, bytesRead);
            // Process hashBytes as required
        }

        return BitConverter.ToString(sha256.Hash).Replace("-", "").ToLowerInvariant();
    }

    private void UpdateConfigFile(string configFilePath, Dictionary<string, string> placeholderValues, string fileHash)
    {
        try
        {
            var configFileContent = File.ReadAllText(configFilePath);

            foreach (var placeholder in placeholderValues)
            {
                configFileContent = configFileContent.Replace($"{{{{{placeholder.Key}}}}}", placeholder.Value);
            }

            // Assume that the last placeholder needs to be replaced with fileHash
            configFileContent = configFileContent.Replace("{{fileHashPlaceholder}}", fileHash);

            File.WriteAllText(configFilePath, configFileContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating config file.");
            throw;
        }
    }
}
