#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int* value;
    int key;
    long offset;
} record;

void handle_memory_error(void *ptr1, void *ptr2, void *ptr3) {
    if (ptr1 != NULL) free(ptr1);
    if (ptr2 != NULL) free(ptr2);
    if (ptr3 != NULL) free(ptr3);
    fprintf(stderr, "Memory allocation failed. Exiting...\n");
    exit(EXIT_FAILURE);
}

record* manage_dynamic_memory(size_t n, size_t m, unsigned int seed) {
    // Allocate aligned memory for long offsets and integer keys
    long *offsets = aligned_alloc(alignof(long), n * sizeof(long));
    if (!offsets) handle_memory_error(offsets, NULL, NULL);

    int *keys = aligned_alloc(alignof(int), m * sizeof(int));
    if (!keys) handle_memory_error(offsets, keys, NULL);

    // Allocate memory for record array
    record *records = malloc(n * sizeof(record));
    if (!records) handle_memory_error(offsets, keys, records);

    // Seed the random number generator
    srand(seed);

    // Populate records
    for (size_t i = 0; i < n; ++i) {
        records[i].value = aligned_alloc(alignof(int), sizeof(int));
        if (!records[i].value) handle_memory_error(offsets, keys, records);

        int random_value;
        do {
            random_value = rand() % 1001; // Generate a number between 0 and 1000
        } while (random_value < 0); // Safety check for overflow

        *(records[i].value) = random_value;

        if (i < m) {
            records[i].key = keys[i];  // Assign key if available
        } else {
            records[i].key = -1;       // Default value when m < n
        }

        offsets[i] = i * sizeof(long); // Example offset assignment
        records[i].offset = offsets[i];
    }

    free(offsets);
    free(keys);

    return records;
}

int main() {
    size_t n = 10, m = 5; // Example values for n and m
    unsigned int seed = time(NULL);

    record *records = manage_dynamic_memory(n, m, seed);

    // Use the records as needed...

    // Cleanup
    for (size_t i = 0; i < n; ++i) {
        free(records[i].value);
    }
    free(records);

    return 0;
}
```

### Explanation of Key Points:

1. **Memory Alignment**: `aligned_alloc` is used to ensure memory alignment, which is critical for performance on modern hardware.

2. **Error Handling**: The function checks each allocation and uses a helper function `handle_memory_error` to free any previously allocated resources before exiting in case of an error.

3. **Random Number Generation**: Uses `rand()` with modulo operation to generate numbers between 0 and 1000, ensuring no negative values are assigned.

4. **Ownership and Cleanup**: The caller is responsible for freeing the memory after use, as indicated by returning a pointer to the allocated records.

5. **Robustness**: Handles both cases where `n` might be greater than or less than `m`, assigning default values when necessary.

This function provides a robust and efficient way to manage dynamic memory allocation under varying conditions, considering alignment, error handling, and performance optimization.']

