int generate_secure_random(int min, int max) {
    if (max <= min) return min;
    unsigned long range = (unsigned long)(max - min + 1);
    unsigned char buffer[sizeof(unsigned long)];
    RAND_bytes(buffer, sizeof(buffer));
    uint64_t rand_val = 0;
    for (size_t i = 0; i < sizeof(buffer); ++i)
        rand_val = (rand_val << 8) | buffer[i];
    return min + (int)(rand_val % range);
}

void initialize_arrays(int *offsets, char **keys, size_t size) {
    for (size_t i = 0; i < size; ++i) {
