}

typedef struct {
    char *fileName;
    size_t fileSize;
    uint64_t timestamp;
} FileMetadata;

typedef struct {
    uint8_t *data;
    size_t position;
} DataChunk;

typedef void (*ChunkProcessedCallback)(DataChunk *);

void freeResources(FileMetadata **fileMetas, size_t metaCount, DataChunk **dataChunks, size_t chunkCount) {
    for (size_t i = 0; i < metaCount; ++i) {
        free(fileMetas[i]->fileName);
        free(fileMetas[i]);
    }
    free(fileMetas);

    for (size_t i = 0; i < chunkCount; ++i) {
        free(dataChunks[i]->data);
        free(dataChunks[i]);
    }
    free(dataChunks);
}

int validateAndSaveChunk(DataChunk *chunk, const char *filePath) {
    FILE *file = fopen(filePath, "ab");
    if (!file) return -1;

    size_t patternLength = strlen(chunk->data);
    for (size_t i = 0; i < patternLength; ++i) {
        if ((i % 2 == 0 && chunk->data[i] != 0) || (i % 2 == 1 && chunk->data[i] != 1)) {
            fclose(file);
            return -1;
        }
    }

    fwrite(chunk->data, sizeof(uint8_t), patternLength, file);
    fclose(file);
    return 0;
}

void *processChunks(void *arg) {
    size_t metaCount = *(size_t *)arg;
    FileMetadata **fileMetas = (FileMetadata **)malloc(metaCount * sizeof(FileMetadata *));
    DataChunk **dataChunks = (DataChunk **)malloc(metaCount * sizeof(DataChunk *));
    ChunkProcessedCallback callback = NULL;

    if (!fileMetas || !dataChunks) {
        free(fileMetas);
        free(dataChunks);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < metaCount; ++i) {
        fileMetas[i] = malloc(sizeof(FileMetadata));
        if (!fileMetas[i]) break;

        fileMetas[i]->fileName = strdup("file" + i);
        fileMetas[i]->fileSize = 1024 * (i + 1); // Example size
        fileMetas[i]->timestamp = secure_get_timestamp();

        dataChunks[i] = malloc(sizeof(DataChunk));
        if (!dataChunks[i]) break;

        dataChunks[i]->data = calloc(fileMetas[i]->fileSize, sizeof(uint8_t));
        if (!dataChunks[i]->data) break;

        for (size_t j = 0; j < fileMetas[i]->fileSize; ++j) {
            dataChunks[i]->data[j] = j % 2;
        }
        dataChunks[i]->position = i;

        pthread_mutex_lock(&lock);
        if (validateAndSaveChunk(dataChunks[i], fileMetas[i]->fileName)) {
            fprintf(stderr, "Failed to save chunk for %s\n", fileMetas[i]->fileName);
        }
        pthread_mutex_unlock(&lock);

        if (callback) callback(dataChunks[i]);
    }

    freeResources(fileMetas, metaCount, dataChunks, metaCount);
    pthread_mutex_destroy(&lock);
    return NULL;
}

void manageFileMetadataAndProcessChunks(size_t metadataSize, ChunkProcessedCallback callback) {
    processChunks(&metadataSize);
}
