    Record *newRecords = realloc(processor->records, sizeof(Record) * newCapacity);
    if (!newRecords) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    processor->records = newRecords;
    processor->capacity = newCapacity;
}

