        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = (long)i;
        keys[i] = (int)i;
    }

    // Secure random initialization with seed
    secure_random_init(seed);

    // Populate records with secure random values
    for (size_t i = 0; i < record_count; ++i) {
        int value = secure_random_range(range_min, range_max);
        pthread_mutex_lock(&mutex); // Ensure thread safety during modification
        records[i].value = value;
        pthread_mutex_unlock(&mutex);

        if (callback) callback(&records[i]);
    }

    // Reading integers from standard input until sentinel is encountered
    int *input_array = NULL;
    size_t input_size = 0, capacity = 10;
    input_array = (int *)malloc(capacity * sizeof(int));
    if (!input_array) {
        cleanup((void**)&offsets, (void**)&keys, records, record_count);
        fprintf(stderr, "Memory allocation failed for input array\n");
        return;
    }

    int value;
    printf("Enter integers (enter %s to finish):\n", sentinel_value);
    while (1) {
        if (scanf("%d", &value) != 1 || value == atoi(sentinel_value)) break;

        // Resize strategy
        if (input_size >= capacity) {
            size_t new_capacity = capacity * 2;
            int *new_array = realloc(input_array, new_capacity * sizeof(int));
            if (!new_array) {
                cleanup((void**)&offsets, (void**)&keys, records, record_count);
                free(input_array);
                fprintf(stderr, "Memory allocation failed for resizing input array\n");
                return;
            }
            input_array = new_array;
            capacity = new_capacity;
        }

        pthread_mutex_lock(&mutex); // Ensure thread safety during access
        input_array[input_size++] = value;
        pthread_mutex_unlock(&mutex);
    }

    // Find and print the maximum integer in the array
    if (input_size > 0) {
        int max_value = findMax(input_array, input_size);
        printf("Maximum integer entered: %d\n", max_value);
    }

    // Cleanup all resources
    cleanup((void**)&offsets, (void**)&keys, records, record_count);
    free(input_array);

    secure_random_cleanup(); // Clean up RNG library if needed
}
