#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_RESOURCE_SIZE 10
#define INITIAL_CHUNK_SIZE 10

typedef enum { STRING, INTEGER, FLOATING_POINT } ResourceType;

typedef struct {
    char name[256];
    ResourceType type;
    union {
        char strValue[256];
        int intValue;
        double floatValue;
    };
    double defaultValue;
    double currentValue;
    unsigned long identifier;
    int version;
} Resource;

typedef struct {
    double value;
    int isValid; // Custom validation flag
} Chunk;

typedef struct {
    Resource* resources;
    size_t resource_count;
    size_t resource_capacity;
    pthread_mutex_t resource_lock;

    Chunk* chunks;
    size_t chunk_count;
    size_t chunk_capacity;
    pthread_mutex_t chunk_lock;

    void (*callback)(Resource*, void*);
    void* callback_context;
} ResourceManager;

void init_resource_manager(ResourceManager* manager, void (*callback)(Resource*, void*), void* context) {
    pthread_mutex_init(&manager->resource_lock, NULL);
    pthread_mutex_init(&manager->chunk_lock, NULL);

    manager->resources = (Resource*)malloc(INITIAL_RESOURCE_SIZE * sizeof(Resource));
    manager->resource_count = 0;
    manager->resource_capacity = INITIAL_RESOURCE_SIZE;

    manager->chunks = (Chunk*)malloc(INITIAL_CHUNK_SIZE * sizeof(Chunk));
    manager->chunk_count = 0;
    manager->chunk_capacity = INITIAL_CHUNK_SIZE;

    manager->callback = callback;
    manager->callback_context = context;
}

void resize_array(void** array, size_t* count, size_t* capacity) {
    if (*count >= *capacity) {
        size_t new_capacity = (*capacity == 0) ? 1 : *capacity * 2;
        void* new_array = realloc(*array, new_capacity * sizeof(**array));
        if (new_array) {
            *array = new_array;
            *capacity = new_capacity;
        } else {
            perror("Failed to resize array");
            exit(EXIT_FAILURE);
        }
    }
}

void add_resource(ResourceManager* manager, const char* name, ResourceType type, double defaultValue) {
    pthread_mutex_lock(&manager->resource_lock);

    resize_array((void**)&manager->resources, &manager->resource_count, &manager->resource_capacity);

    Resource* resource = &manager->resources[manager->resource_count++];
    strncpy(resource->name, name, sizeof(resource->name));
    resource->type = type;
    resource->defaultValue = defaultValue;
    resource->currentValue = defaultValue;
    resource->identifier = rand();
    resource->version = 1;

    if (manager->callback) {
        manager->callback(resource, manager->callback_context);
    }

    pthread_mutex_unlock(&manager->resource_lock);
}

void add_chunk(ResourceManager* manager, double value) {
    pthread_mutex_lock(&manager->chunk_lock);

    resize_array((void**)&manager->chunks, &manager->chunk_count, &manager->chunk_capacity);

    Chunk* chunk = &manager->chunks[manager->chunk_count++];
    chunk->value = value;
    chunk->isValid = (value >= 0); // Custom validation logic

    pthread_mutex_unlock(&manager->chunk_lock);
}

void free_resource_manager(ResourceManager* manager) {
    free(manager->resources);
    free(manager->chunks);

    pthread_mutex_destroy(&manager->resource_lock);
    pthread_mutex_destroy(&manager->chunk_lock);
}

void example_callback(Resource* resource, void* context) {
    // Example callback logic
    if (strcmp(resource->name, "critical_resource") == 0) {
        resource->currentValue *= 2; // Modify current value
    }
    resource->version++; // Increment version number
}

int main() {
    ResourceManager manager;
    init_resource_manager(&manager, example_callback, NULL);

    add_resource(&manager, "CPU_Usage", FLOATING_POINT, 0.75);
    add_chunk(&manager, 3.14);

    free_resource_manager(&manager);

    return 0;
}
```

This code provides a basic structure for managing resources and chunks with dynamic resizing, callback support, and thread safety using mutexes. It includes error handling for memory allocation failures and uses callbacks to allow custom processing of resources during initialization.']

