// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void process_shape(shape *s, void (*callback)(shape*)) {
    if (callback) callback(s);
}

int allocate_and_initialize(float **values, size_t value_size,
                            point **coordinates, size_t coord_size,
                            shape ***shapes, size_t shape_size,
                            const char *config_file, void (*callback)(shape*),
                            int async_mode) {

    // Error handling variables
    if (!values || !coordinates || !shapes)
        return -1;

    pthread_mutex_lock(&mutex);

    // Allocate and initialize 'float' values array
    *values = (float *)malloc(value_size * sizeof(float));
    if (!*values) {
        fprintf(stderr, "Failed to allocate memory for float values.\n");
        goto cleanup;
    }
    for (size_t i = 0; i < value_size; ++i)
        (*values)[i] = (float)i;

    // Allocate and initialize 'point' coordinates array
    *coordinates = (point *)malloc(coord_size * sizeof(point));
    if (!*coordinates) {
        fprintf(stderr, "Failed to allocate memory for points.\n");
        goto cleanup_values;
    }
    for (size_t i = 0; i < coord_size; ++i)
        (*coordinates)[i].x = (float)i;

    // Allocate and initialize 'shape' array
    *shapes = (shape **)malloc(shape_size * sizeof(shape *));
    if (!*shapes) {
        fprintf(stderr, "Failed to allocate memory for shapes.\n");
        goto cleanup_coordinates;
    }

    for (size_t i = 0; i < shape_size; ++i) {
        (*shapes)[i] = (shape *)malloc(sizeof(shape));
        if (!(*shapes)[i]) {
            fprintf(stderr, "Failed to allocate memory for a shape.\n");
            goto cleanup_shapes;
        }

        // Initialize the 'shape'
        (*shapes)[i]->area = i * 3.14;  // Example: circle radius squared
        snprintf((*shapes)[i]->name, sizeof((*shapes)[i]->name), "Shape_%zu", i);

        // Reuse or allocate new point
        if (i < coord_size)
            (*shapes)[i]->coordinate = &(*coordinates)[i];
        else {
            (*shapes)[i]->coordinate = (point *)malloc(sizeof(point));
            if (!(*shapes)[i]->coordinate) {
                fprintf(stderr, "Failed to allocate memory for a shape's point.\n");
                free((*shapes)[i]);
                goto cleanup_shapes;
            }
            (*shapes)[i]->coordinate->x = (float)i;  // Example initialization
        }

        // Process each shape with the callback if provided
        process_shape(*(*shapes)[i], callback);
    }

    pthread_mutex_unlock(&mutex);

    return 0;

cleanup_shapes:
    while (shape_size--) {
        free((*shapes)[shape_size]);
    }
cleanup_coordinates:
    free(*coordinates);
cleanup_values:
    free(*values);

    pthread_mutex_unlock(&mutex);
    return -1;
}

void batch_free(float *values, point *coordinates, shape **shapes, size_t shape_size) {
    if (shapes) {
        for (size_t i = 0; i < shape_size; ++i) {
            if ((*shapes)[i] && (*shapes)[i]->coordinate) {
                free((*shapes)[i]->coordinate);
            }
            free((*shapes)[i]);
        }
        free(shapes);
    }
    free(values);
    free(coordinates);

    // Optionally, log the deallocations
}

// Example callback function for demonstration purposes
void example_callback(shape *s) {
    printf("Processing shape: %s with area: %.2f\n", s->name, s->area);
}

int main() {
