    point *coordinates;
    shape **shapes;

    int result = allocate_and_initialize(&values, 10, &coordinates, 5,
                                         &shapes, 7, NULL, example_callback, 0);

    if (result == 0) {
        // Use the allocated structures
    }

    batch_free(values, coordinates, shapes, 7);

    return 0;
}
