#include <stdint.h>

#define MAX_DIR_NAME 256
#define MAX_FILE_COUNT 1000

typedef struct File {
    int id;
    char name[MAX_DIR_NAME];
    size_t size; // in bytes
} File;

typedef struct Directory {
    int id;
    char name[MAX_DIR_NAME];
    File* files[MAX_FILE_COUNT];
    pthread_mutex_t lock;
} Directory;

static pthread_mutex_t dir_list_lock = PTHREAD_MUTEX_INITIALIZER;
static Directory* dir_head = NULL;
static int next_dir_id = 0;

// Function to generate random size between 1KB and 1MB
size_t random_file_size() {
    return (rand() % 1023 + 1024) * 1024; // Random size from 1KB to 1MB
}

// Initialize a new directory with a sequential ID and name
Directory* create_directory(const char* dir_name, int file_count) {
    Directory* new_dir = malloc(sizeof(Directory));
    if (!new_dir) return NULL;

    strncpy(new_dir->name, dir_name, MAX_DIR_NAME - 1);
    new_dir->id = next_dir_id++;
    pthread_mutex_init(&new_dir->lock, NULL);

    // Initialize files in this directory
    for (int i = 0; i < file_count; ++i) {
        File* file = malloc(sizeof(File));
        if (!file) continue;

        snprintf(file->name, MAX_DIR_NAME - 1, "%s_File%d", dir_name, i);
        file->id = i;
        file->size = random_file_size();

        pthread_mutex_lock(&new_dir->lock);
        new_dir->files[i] = file;
        pthread_mutex_unlock(&new_dir->lock);

        printf("Created %s in Directory %d with size %zu bytes\n", file->name, new_dir->id, file->size);
    }

    return new_dir;
}

// Add a directory to the global list
void add_directory(const char* dir_name, int file_count) {
    pthread_mutex_lock(&dir_list_lock);

    char buffer[MAX_DIR_NAME];
    snprintf(buffer, MAX_DIR_NAME - 1, "Dir%d", next_dir_id);
    Directory* new_dir = create_directory(buffer, file_count);

    if (new_dir) {
        new_dir->next = dir_head;
        dir_head = new_dir;
    }

    pthread_mutex_unlock(&dir_list_lock);
}

// Clean up resources
void cleanup() {
    while (dir_head) {
        Directory* current = dir_head;
        dir_head = current->next;

        pthread_mutex_destroy(&current->lock);

        for (int i = 0; current->files[i]; ++i) {
            free(current->files[i]);
        }

        free(current);
    }
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Initialize random seed

    add_directory("ExampleDir", 5);

    cleanup();
    return 0;
}
```

