```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    time_t timestamp;
    int status_code;
    char *string_buffer;
} Event;

typedef struct {
    Event **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventCollection;

EventCollection* create_event_collection(size_t initial_capacity) {
    EventCollection *collection = malloc(sizeof(EventCollection));
    if (!collection) return NULL;

    collection->events = calloc(initial_capacity, sizeof(Event *));
    if (!collection->events) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int add_event(EventCollection *collection, time_t timestamp, int status_code, const char *format, ...) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Event **new_events = realloc(collection->events, new_capacity * sizeof(Event *));
        if (!new_events) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failure
        }
        collection->events = new_events;
        collection->capacity = new_capacity;
    }

    Event *event = malloc(sizeof(Event));
    if (!event) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failure
    }

    event->timestamp = timestamp;
    event->status_code = status_code;

    va_list args;
    va_start(args, format);
    char buffer[MAX_STRING_LENGTH];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    size_t string_length = strlen(buffer) + 1;
    event->string_buffer = malloc(string_length);
    if (!event->string_buffer) {
        free(event);
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failure
    }

    snprintf(event->string_buffer, string_length, "%s", buffer);

    collection->events[collection->count++] = event;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

void free_event_collection(EventCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->events[i]->string_buffer);
        free(collection->events[i]);
    }
    free(collection->events);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

size_t get_active_event_count(EventCollection *collection) {
    if (!collection) return 0;

    pthread_mutex_lock(&collection->lock);
    size_t count = collection->count;
    pthread_mutex_unlock(&collection->lock);

    return count;
}

size_t get_event_capacity(EventCollection *collection) {
    if (!collection) return 0;

    pthread_mutex_lock(&collection->lock);
    size_t capacity = collection->capacity;
    pthread_mutex_unlock(&collection->lock);

    return capacity;
}
```

