#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_FILE_SIZE (1024 * 1024) // 1 MB for example
#define COMPRESSION_RETENTION_PERIOD (7 * 24 * 60 * 60) // 7 days in seconds

typedef struct {
    int value;
    double timestamp;
    char status;
} NestedRecord;

typedef struct {
    long offset;
    int key;
    NestedRecord nested_record;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

typedef struct {
    FILE *file;
    pthread_mutex_t file_lock;
    char current_log_filename[256];
    time_t last_rotation_time;
} LogManager;

LogManager log_manager = {NULL, PTHREAD_MUTEX_INITIALIZER};

void initialize_log_manager() {
    snprintf(log_manager.current_log_filename, sizeof(log_manager.current_log_filename), "log_%ld.txt", (long)time(NULL));
    log_manager.file = fopen(log_manager.current_log_filename, "a");
    if (!log_manager.file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log_manager.last_rotation_time = time(NULL);
}

void rotate_log_file() {
    pthread_mutex_lock(&log_manager.file_lock);

    if (ftell(log_manager.file) >= MAX_LOG_FILE_SIZE || difftime(time(NULL), log_manager.last_rotation_time) > COMPRESSION_RETENTION_PERIOD) {
        fclose(log_manager.file);
        char archived_filename[256];
        snprintf(archived_filename, sizeof(archived_filename), "%s.gz", log_manager.current_log_filename); // Gzip compression naming
        rename(log_manager.current_log_filename, archived_filename);

        snprintf(log_manager.current_log_filename, sizeof(log_manager.current_log_filename), "log_%ld.txt", (long)time(NULL));
        log_manager.file = fopen(log_manager.current_log_filename, "a");
        if (!log_manager.file) {
            perror("Failed to open new log file");
            exit(EXIT_FAILURE);
        }
        log_manager.last_rotation_time = time(NULL);
    }

    pthread_mutex_unlock(&log_manager.file_lock);
}

void log_record_creation(const Record *record) {
    rotate_log_file();

    pthread_mutex_lock(&log_manager.file_lock);

    fprintf(log_manager.file, "Record created: offset=%ld, key=%d\n", record->offset, record->key);

    fflush(log_manager.file); // Ensure logs are written immediately

    pthread_mutex_unlock(&log_manager.file_lock);
}

int add_record(RecordManager *manager, long offset, int key, int value, double timestamp, char status) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        Record **new_records = realloc(manager->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            perror("Failed to allocate memory for records");
            return -1; // Allocation failure
        }
        memset(new_records + manager->count, 0, (new_capacity - manager->capacity) * sizeof(Record *));
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    pthread_mutex_lock(&manager->lock);

    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failure
    }

    record->offset = offset;
    record->key = key;
    record->nested_record.value = value;
    record->nested_record.timestamp = timestamp;
    record->nested_record.status = status;

    manager->records[manager->count++] = record;

    log_record_creation(record);

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void free_records(RecordManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]) {
            free(manager->records[i]);
        }
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}

void cleanup_log_manager() {
    fclose(log_manager.file);
}

int main() {
    initialize_log_manager();

    RecordManager manager = {NULL, 0, 0};
    pthread_mutex_init(&manager.lock, NULL);

    // Add records example
    if (add_record(&manager, 100, 1, 10, time(NULL), 'A') == -1) {
        fprintf(stderr, "Failed to add record\n");
    }

    free_records(&manager);
    cleanup_log_manager();

    return 0;
}
