void manageGraphDatabase(int offset_size, int key_size, int min_records, int max_records, int min_edges, int max_edges) {
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    if (!offsets || !keys) { perror("Memory allocation failed"); exit(EXIT_FAILURE); }

    for (int i = 0; i < offset_size; ++i) offsets[i] = i;
    for (int i = 0; i < key_size; ++i) keys[i] = i;

    int num_records = rand() % (max_records - min_records + 1) + min_records;
    int num_edges = rand() % (max_edges - min_edges + 1) + min_edges;

    record *records = malloc(num_records * sizeof(record));
    edge *edges = malloc(num_edges * sizeof(edge));
    if (!records || !edges) { perror("Memory allocation failed"); exit(EXIT_FAILURE); }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = secure_random_long(1, 100);
        records[i].key = malloc(10 * sizeof(char));
        sprintf(records[i].key, "Key%d", i);

        records[i].pointer = malloc(sizeof(long));
        if (!records[i].pointer) { perror("Memory allocation failed"); exit(EXIT_FAILURE); }

        *(records[i].pointer) = secure_random_long(1, 1000);
    }

    for (int i = 0; i < num_edges; ++i) {
        edges[i].from_vertex = secure_random_long(0, num_records - 1);
        edges[i].to_vertex = secure_random_long(0, num_records - 1);
        edges[i].weight = secure_random_long(1, 100) / 10.0;
        edges[i].type = secure_random_long(0, 5);
    }

    int *dynamic_array = malloc(10 * sizeof(int));
    if (!dynamic_array) { perror("Memory allocation failed"); exit(EXIT_FAILURE); }
    size_t current_size = 10;

    while (1) {
        pthread_mutex_lock(&lock);

        int new_entry;
        if (scanf("%d", &new_entry) != 1) {
            if (feof(stdin)) break; // End of input
            else { perror("Failed to read input"); continue; }
        }

        if (current_size == dynamic_array) {
            current_size *= 2;
            int *temp = realloc(dynamic_array, current_size * sizeof(int));
            if (!temp) { perror("Memory reallocation failed"); exit(EXIT_FAILURE); }
            dynamic_array = temp;
        }

        dynamic_array[current_size / 10 - 1] = new_entry;

        pthread_mutex_unlock(&lock);
    }

    // Cleanup
    for (int i = 0; i < num_records; ++i) {
        free(records[i].key);
        free(records[i].pointer);
    }
    free(records);
    free(edges);

    free(dynamic_array);
    free(offsets);
    free(keys);
}

