#define MAX_DATA_BLOCKS 100

typedef struct data_block {
    double num;
    char byte;
    struct data_block* next;
} data_block_t;

int initialize_arrays(double** doubles, char** chars, data_block_t*** data_blocks) {
    const size_t num_elements = 10;
    *doubles = (double*)malloc(num_elements * sizeof(double));
    if (*doubles == NULL) return -1;

    *chars = (char*)malloc(num_elements * sizeof(char));
    if (*chars == NULL) { free(*doubles); return -1; }

    *data_blocks = (data_block_t**)malloc(MAX_DATA_BLOCKS * sizeof(data_block_t*));
    if (*data_blocks == NULL) { 
        free(*doubles); free(*chars); return -1;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        (*doubles)[i] = (double)i;
        (*chars)[i] = 'a' + i;

        data_block_t* block = (data_block_t*)malloc(sizeof(data_block_t));
        if (block == NULL) { 
            for (size_t j = 0; j < i; ++j) free((*data_blocks)[j]);
            free(*doubles); free(*chars); free(*data_blocks);
            return -1;
        }

        block->num = (double)i + 0.5;
        block->byte = 'A' + i;

        (*data_blocks)[i] = block;

        // Create circular linked list
        if (i == num_elements - 1) {
            block->next = (*data_blocks)[0];
        } else {
            block->next = (*data_blocks)[i + 1];
        }
    }

    return 0;
}

void free_resources(double* doubles, char* chars, data_block_t** data_blocks, size_t num_elements) {
    if (doubles != NULL) free(doubles);
    if (chars != NULL) free(chars);

    for (size_t i = 0; i < num_elements; ++i) {
        if (data_blocks[i] != NULL) free(data_blocks[i]);
    }

    free(data_blocks);
}

int main() {
    double* doubles;
    char* chars;
    data_block_t** data_blocks;

    int result = initialize_arrays(&doubles, &chars, &data_blocks);
    if (result == -1) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Use the initialized arrays and data blocks here
    for (size_t i = 0; i < 10; ++i) {
        printf("Data Block %zu: num=%.2f, byte=%c\n", 
            i, (*data_blocks)[i]->num, (*data_blocks)[i]->byte);
        if ((*data_blocks)[i]->next == *data_blocks) break;
    }

    free_resources(doubles, chars, data_blocks, 10);

    return 0;
}
