#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <stdatomic.h>
#include <pthread.h>

#define ALIGNMENT 64

typedef struct {
    int* value;
    int key;
    long offset;
} record;

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
#else
    if ((ptr = memalign(alignment, size))) {
        return ptr;
    }
#endif
    return NULL;
}

void free_aligned(void* ptr) {
    free(ptr);
}

int generate_random(int min, int max, unsigned int* seed) {
    int range = (max - min + 1);
    long long x = ((long long)rand_r(seed)) << 32 | rand_r(seed);
    return min + (x % range);
}

void initialize_records(record** records, size_t n, size_t m, unsigned int seed) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&mutex);

        records[i]->value = aligned_alloc(ALIGNMENT, sizeof(int));
        if (!records[i]->value) {
            fprintf(stderr, "Memory allocation failed\n");
            for (size_t j = 0; j <= i; ++j) {
                free_aligned(records[j]->value);
                free_aligned(records[j]);
            }
            pthread_mutex_destroy(&mutex);
            return;
        }

        records[i]->key = generate_random(0, m - 1, &seed);

        records[i]->offset = rand_r(&seed) % (long)RAND_MAX;

        *records[i]->value = generate_random(0, 1000, &seed);

        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
}

record** allocate_and_initialize_records(size_t n, size_t m, unsigned int seed) {
    if (n == 0 || m == 0) return NULL;

    record** records = aligned_alloc(ALIGNMENT, n * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        records[i] = aligned_alloc(ALIGNMENT, sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            for (size_t j = 0; j < i; ++j) {
                free_aligned(records[j]->value);
                free_aligned(records[j]);
            }
            free_aligned(records);
            return NULL;
        }
    }

    initialize_records(records, n, m, seed);

    return records;
}

void cleanup_records(record** records, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (records[i]) {
            free_aligned(records[i]->value);
            free_aligned(records[i]);
        }
    }
    free_aligned(records);
}
```

### Key Considerations:
- **Memory Alignment:** Uses `aligned_alloc` to ensure allocations are aligned to 64 bytes for optimal CPU performance.
- **Concurrency Control:** Utilizes a mutex (`pthread_mutex_t`) for safe concurrent access, ensuring no race conditions when initializing records.
- **Error Handling:** Checks all memory allocation results and ensures graceful failure with proper cleanup if any allocation fails.
- **Random Number Generation:** Uses `rand_r` seeded by the provided seed to ensure deterministic outputs across multiple invocations. 
- **Thread Safety & Performance:** The mutex locks only during critical sections, minimizing performance bottlenecks while ensuring data integrity.

This code snippet implements a robust and efficient way to dynamically allocate and initialize records with alignment considerations, concurrency support, and error handling in mind for real-world application scenarios.']

