// Function to create a new node in the list
Node* create_node(double value, char character, int number) {
    pthread_mutex_lock(&node_lock);

    if (!can_allocate(sizeof(Node))) {
        printf("Memory allocation limit reached or insufficient memory.\n");
        pthread_mutex_unlock(&node_lock);
        return NULL;
    }

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
