```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;

public class ConfigManager {
    private static final String[] ENVIRONMENTS = {"development", "testing", "production"};
    private static final Map<String, Map<String, String>> defaultConfigurations = new HashMap<>();
    private static final Set<String> loggingLevels = new HashSet<>(Arrays.asList("DEBUG", "INFO", "WARN", "ERROR"));
    private static final int MAX_LOGGING_LEVELS = 4;

    static {
        for (String env : ENVIRONMENTS) {
            Map<String, String> config = new HashMap<>();
            config.put("logFilePath", "/var/log/" + env + ".log");
            config.put("maxLogSize", "100MB");
            defaultConfigurations.put(env, config);
        }
    }

    private final ConcurrentHashMap<String, Map<String, String>> environmentConfigs;
    private final List<String> activeLoggingLevels = new ArrayList<>(loggingLevels);
    private final Set<LogHandler> logHandlers = ConcurrentHashMap.newKeySet();
    private final Object lock = new Object();

    public ConfigManager() {
        this.environmentConfigs = new ConcurrentHashMap<>();
        for (String env : ENVIRONMENTS) {
            environmentConfigs.put(env, new HashMap<>(defaultConfigurations.get(env)));
        }
    }

    public void addEnvironmentConfiguration(String environment, Map<String, String> customConfig) {
        synchronized (lock) {
            environmentConfigs.computeIfAbsent(environment, k -> new HashMap<>()).putAll(customConfig);
        }
    }

    public void updateLoggingLevels(List<String> levels) {
        synchronized (lock) {
            if (levels.size() > MAX_LOGGING_LEVELS) {
                throw new IllegalArgumentException("Exceeds maximum logging level count.");
            }
            activeLoggingLevels.clear();
            activeLoggingLevels.addAll(levels);
        }
    }

    public void addLogHandler(LogHandler handler) {
        logHandlers.add(handler);
    }

    public void removeLogHandler(LogHandler handler) {
        logHandlers.remove(handler);
    }

    public void setConfigurationSeed(long seed, boolean randomize) {
        if (randomize) {
            Random random = new Random(seed);
            // Use randomization logic here
        } else {
            // Initialize with the given seed for reproducibility
        }
    }

    public void registerConfigChangeCallback(Consumer<Map<String, String>> callback) {
        synchronized (lock) {
            environmentConfigs.forEach((env, config) -> callback.accept(config));
        }
    }

    public void resetResources() {
        synchronized (lock) {
            environmentConfigs.clear();
            activeLoggingLevels.clear();
            logHandlers.clear();
        }
    }

    // Example interface for custom log handlers
    public interface LogHandler {
        void handleLog(String message);
    }
}
```

### Key Points:
- **Thread Safety**: Uses `ConcurrentHashMap` and synchronized blocks to ensure thread-safe operations.
- **Configuration Management**: Allows adding custom configurations per environment.
