class GraphService {
private:
    Graph graph;
    shared_mutex graphMutex;
    atomic<int> requestCount{0};
    atomic<double> errorRate{0.0};

public:
    void addVertex() {
        unique_lock lock(graphMutex);
        add_vertex(graph);
    }

    void removeVertex(int vertex) {
        unique_lock lock(graphMutex);
        remove_vertex(vertex, graph);
    }

    void addEdge(int u, int v) {
        shared_lock lock(graphMutex);
        add_edge(u, v, graph);
    }

    void removeEdge(int u, int v) {
        shared_lock lock(graphMutex);
        remove_edge(u, v, graph);
    }

    void processRequests(const vector<string>& requests) {
