            requestCount++;
            // Simulate processing a request
            this_thread::sleep_for(chrono::milliseconds(100));
        }
    }

    int getRequestCount() const {
        return requestCount.load();
    }

    double getErrorRate() const {
        return errorRate.load();
    }
};

