// Function to generate pseudo-random numbers with a seed
unsigned int customRandom(unsigned int *seed, unsigned int max) {
    *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
    return (unsigned int)(*seed % max);
}

void processRecordsAndFindMax(int offsetSize, int keySize, int initialRecordCount,
                             int recordCountIncrement, int randomRangeStart,
                             int randomRangeEnd, unsigned int seed, 
                             void (*callback)(record*)) {

    long *offset = NULL;
    int *key = NULL;
    record *records = NULL;
    int totalRecords = initialRecordCount;
    size_t maxRecords = initialRecordCount;
    int i;

    // Allocate and initialize offset and key arrays
    for (i = 0; i < 3; ++i) {
        pthread_mutex_lock(&lock);

        offset = realloc(offset, offsetSize * sizeof(long));
        key = realloc(key, keySize * sizeof(int));

        if (!offset || !key) {
            perror("Memory allocation failed");
            free(offset);
            free(key);
            free(records);
            pthread_mutex_unlock(&lock);
            return;
        }

        for (int j = 0; j < offsetSize; ++j)
            offset[j] = j;

        for (int k = 0; k < keySize; ++k)
            key[k] = k;

        // Reallocate and initialize record array
        if (!records) {
            records = malloc(maxRecords * sizeof(record));
            if (!records) {
                perror("Memory allocation failed");
                free(offset);
                free(key);
                pthread_mutex_unlock(&lock);
                return;
            }
        } else {
            record *temp = realloc(records, (maxRecords + recordCountIncrement) * sizeof(record));
            if (!temp) {
                perror("Memory reallocation failed");
                free(offset);
                free(key);
                free(records);
                pthread_mutex_unlock(&lock);
                return;
            }
            records = temp;
        }

        for (int r = totalRecords; r < totalRecords + recordCountIncrement; ++r) {
            records[r].value = randomRangeStart + customRandom(&seed, randomRangeEnd - randomRangeStart + 1);
            records[r].key = malloc(20 * sizeof(char)); // Example size
            if (!records[r].key) {
                perror("Memory allocation failed");
                free(offset);
                free(key);
                for (int m = totalRecords; m < r; ++m)
                    free(records[m].key);
                free(records);
                pthread_mutex_unlock(&lock);
                return;
            }
            snprintf(records[r].key, 20, "Key%d", records[r].value);
            records[r].dynamicPointer = malloc(sizeof(long));
            if (!records[r].dynamicPointer) {
                perror("Memory allocation failed");
                free(offset);
                free(key);
                for (int m = totalRecords; m <= r; ++m)
                    free(records[m].key);
                free(records);
                pthread_mutex_unlock(&lock);
                return;
            }
            *records[r].dynamicPointer = records[r].value;

            if (callback) {
                callback(&records[r]);
            }

            totalRecords++;
        }

        maxRecords += recordCountIncrement;

        pthread_mutex_unlock(&lock);
    }

    // Read list of integers from standard input
    int num, largest = INT_MIN;
    while (scanf("%d", &num) == 1) {
        if (num > largest)
            largest = num;
    }

    printf("Largest integer: %d\n", largest);

    // Free allocated memory
    for (i = 0; i < totalRecords; ++i) {
        free(records[i].key);
        free(records[i].dynamicPointer);
    }
    free(records);
    free(offset);
    free(key);
}

// Example callback function
