        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Maximum value found: %ld\n", max_value);

cleanup:
    pthread_mutex_destroy(&mutex);

    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (int i = 0; i < record_size; ++i) {
            if (records[i].string_key) free(records[i].string_key);
            if (records[i].dynamic_long_ptr) free(records[i].dynamic_long_ptr);
        }
        free(records);
    }

    return;
}
