// Function to handle memory allocation failures
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize the message queue
int init_message_queue(Message **messages, int size, const char *default_content, 
                       unsigned int timestamp_seed, void (*callback)(Message*), pthread_mutex_t *mutex) {
    if (size <= 0 || !messages || !default_content || !mutex)
        return -1;

    // Allocate memory for messages
    *messages = safe_malloc(size * sizeof(Message));

    srand(timestamp_seed); // Seed the random number generator

    // Lock mutex for thread safety
    pthread_mutex_lock(mutex);

    for (int i = 0; i < size; ++i) {
        (*messages)[i].timestamp = rand(); // Generate timestamp using seed
        (*messages)[i].priority = i;

        // Allocate memory for content with extra space for future use
        char *content_buffer = safe_malloc(strlen(default_content) + 128);
        strcpy(content_buffer, default_content);

        (*messages)[i].content = content_buffer;

        if (callback) {
            callback(&(*messages)[i]);
        }
    }

    // Unlock mutex after initialization
    pthread_mutex_unlock(mutex);

    return 0;
}

// Function to free the message queue memory
void free_message_queue(Message *messages, int size) {
    for (int i = 0; i < size; ++i) {
        free(messages[i].content);
    }
    free(messages);
}

// Sample callback function for additional processing
