    if (init_message_queue(&message_queue, queue_size, "Default content", 12345, sample_callback, &mutex) == 0) {
        // Use the message queue...

        // Free allocated memory
        free_message_queue(message_queue, queue_size);
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}
