// Assuming an external library for secure random number generation
void secure_rand_init(uint32_t seed);
uint32_t secure_rand(void);

typedef struct {
    int value;
    char string_key[256];
    long *dynamic_value;
} Record;

typedef void (*InitCallback)(Record*);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initialize_database(size_t n_records, uint32_t seed, InitCallback init_callback) {
    pthread_mutex_lock(&mutex);

    // Memory allocation for arrays
    long *offsets = malloc(n_records * sizeof(long));
    int *keys = malloc(n_records * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return -1;  // Error handling: Memory allocation failure
    }

    Record *records = malloc(n_records * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    secure_rand_init(seed);

    int min_value = 0; // Minimum bound for random int
    int max_value = 100; // Maximum bound for random int

    int generated_values[n_records];
    memset(generated_values, 0, sizeof(int) * n_records);

    // Initialize offsets and keys with sequential numbers
    for (size_t i = 0; i < n_records; ++i) {
        offsets[i] = i;
        keys[i] = i;

        uint32_t random_value;
        do {
            random_value = secure_rand() % (max_value - min_value + 1) + min_value;
        } while (generated_values[random_value]);

        generated_values[random_value] = 1;
        records[i].value = random_value;

        snprintf(records[i].string_key, sizeof(records[i].string_key), "Key_%d", i);

        // Allocate and assign dynamic value
        records[i].dynamic_value = malloc(sizeof(long));
        if (!records[i].dynamic_value) {
            for (size_t j = 0; j <= i; ++j) {
                free(records[j].dynamic_value); // Cleanup on failure
            }
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    // Process each record with the callback function
    for (size_t i = 0; i < n_records; ++i) {
        if (init_callback) init_callback(&records[i]);
    }

    // Free memory safely on exit
    for (size_t i = 0; i < n_records; ++i) {
        free(records[i].dynamic_value);
    }

    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_unlock(&mutex);
    return 0;
}
