#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char key[256];
    long *dynamic_long;
} record;

typedef void (*record_callback_t)(record *);

typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    unsigned int seed; // For reproducibility
} collection_t;

collection_t* init_collection(size_t initial_capacity, size_t max_capacity, unsigned int seed) {
    if (initial_capacity > max_capacity) return NULL;

    collection_t *coll = malloc(sizeof(collection_t));
    coll->records = calloc(initial_capacity, sizeof(record *));
    coll->capacity = initial_capacity;
    coll->count = 0;
    pthread_mutex_init(&coll->mutex, NULL);
    pthread_cond_init(&coll->cond_var, NULL);
    coll->seed = seed;

    return coll;
}

void resize_collection(collection_t *coll, size_t new_capacity) {
    if (new_capacity > coll->capacity && new_capacity <= coll->max_capacity) {
        record **temp_records = realloc(coll->records, new_capacity * sizeof(record *));
        if (temp_records) {
            memset(temp_records + coll->capacity, 0, (new_capacity - coll->capacity) * sizeof(record *));
            coll->records = temp_records;
            coll->capacity = new_capacity;
        }
    }
}

int add_record(collection_t *coll, int value, const char *key_str) {
    pthread_mutex_lock(&coll->mutex);

    if (coll->count == coll->capacity)
        resize_collection(coll, coll->capacity * 2 <= coll->max_capacity ? coll->capacity * 2 : coll->max_capacity);

    record *new_record = malloc(sizeof(record));
    new_record->value = value;
    strncpy(new_record->key, key_str, sizeof(new_record->key) - 1);
    new_record->dynamic_long = malloc(sizeof(long));

    if (!new_record || !new_record->dynamic_long) {
        pthread_mutex_unlock(&coll->mutex);
        free(new_record);
        return -1;
    }

    *new_record->dynamic_long = rand_r((unsigned int *)&(coll->seed)); // Secure random number generation
    coll->records[coll->count++] = new_record;

    pthread_mutex_unlock(&coll->mutex);
    return 0;
}

void process_records(collection_t *coll, record_callback_t callback) {
    pthread_mutex_lock(&coll->mutex);

    for (size_t i = 0; i < coll->count; ++i) {
        if (callback)
            callback(coll->records[i]);
    }

    pthread_mutex_unlock(&coll->mutex);
}

void flush_records(collection_t *coll) {
    pthread_mutex_lock(&coll->mutex);

    for (size_t i = 0; i < coll->count; ++i) {
        free(coll->records[i]->dynamic_long);
        free(coll->records[i]);
    }

    free(coll->records);
    coll->records = NULL;
    coll->capacity = 0;
    coll->count = 0;

    pthread_mutex_unlock(&coll->mutex);
}

void destroy_collection(collection_t *coll) {
    flush_records(coll);
    pthread_mutex_destroy(&coll->mutex);
    pthread_cond_destroy(&coll->cond_var);
    free(coll);
}
```

### Notes:

- This code initializes a dynamic collection of `record` structures with thread-safety mechanisms using mutex locks.
- It supports dynamic resizing, adding records while maintaining capacity constraints.
- A callback mechanism is provided for processing each record after initialization.
- Memory management includes allocation and deallocation to prevent leaks, with a method to flush all records safely.
- The code uses secure random number generation with `rand_r` for reproducibility based on a seed value.
- Edge cases are considered, such as resizing beyond maximum capacity or invalid operations during flushing.']

