                cleanup_all(&offsets, &keys, &recordsA, &recordsB, &metaData);
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_destroy(mutex);
                return;
            }
            *(recordsA[i / 2]->base.dynamicValue) = secure_random();

            callback(recordsA[i / 2], i); // Post-initialization processing
        } else {
            recordsB[i / 2] = malloc(sizeof(typeB_record));
            if (!recordsB[i / 2]) {
                cleanup_all(&offsets, &keys, &recordsA, &recordsB, &metaData);
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_destroy(mutex);
                return;
            }

            recordsB[i / 2]->base.value = secure_random_range(typeBRangeStart, typeBRangeEnd);
            strcpy(recordsB[i / 2]->base.key, "TypeBKey");
            recordsB[i / 2]->base.dynamicValue = malloc(sizeof(long));
            if (!recordsB[i / 2]->base.dynamicValue) {
