            *(recordsB[i / 2]->base.dynamicValue) = secure_random();

            callback(recordsB[i / 2], i); // Post-initialization processing
        }
    }

    metaData->count = record_size;
    // Compute average_value or other statistics as needed

    pthread_mutex_destroy(mutex);
}
