    time_t last_used_time;
} Connection;

// Connection pool structure
typedef struct {
    size_t max_connections;
    size_t active_connections;
    Connection *connections;
    pthread_mutex_t lock;
    TimestampLibrary timestamp_lib;
    void (*init_callback)(Connection *);
    int log_enabled;
} ConnectionPool;

// Function prototypes
int init_connection_pool(ConnectionPool *pool, size_t max_connections, unsigned int seed, 
                         void (*callback)(Connection *), int log);
void shutdown_connection_pool(ConnectionPool *pool);

int init_connection_pool(ConnectionPool *pool, size_t max_connections, unsigned int seed, 
                         void (*callback)(Connection *), int log) {
    srand(seed); // Seed for reproducible connection sequences
    pool->max_connections = max_connections;
    pool->active_connections = 0;
    pool->connections = (Connection *)malloc(max_connections * sizeof(Connection));
    if (!pool->connections) return -1; // Memory allocation failure

    pthread_mutex_init(&pool->lock, NULL);
    init_timestamp_library(&pool->timestamp_lib);
    pool->init_callback = callback;
    pool->log_enabled = log;

    for (size_t i = 0; i < max_connections; ++i) {
        Connection *conn = &pool->connections[i];
        conn->id = i;
        conn->status = 0; // Default status: available
        conn->last_used_time = get_current_time(&pool->timestamp_lib);

        if (callback) callback(conn); // Initialize or validate connection

        if (log_enabled && log) {
            printf("Initialized Connection ID %d\n", i);
        }
    }

    return 0;
}

void shutdown_connection_pool(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->connections);
    pool->connections = NULL;
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    ConnectionPool pool;
    int init_result = init_connection_pool(&pool, 10, 12345, NULL, 1);

    if (init_result == 0) {
        printf("Connection pool initialized successfully.\n");
    } else {
        fprintf(stderr, "Failed to initialize connection pool.\n");
    }

    shutdown_connection_pool(&pool);
    return 0;
}
