#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>

#define INITIAL_POOL_SIZE 10
#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit: 1MB
#define TIMEOUT_DURATION 2

typedef enum { IDLE, ACTIVE } ConnectionStatus;

typedef struct {
    char ip[16]; // IPv4 address as string
    int port;
    ConnectionStatus status;
} Connection;

typedef struct {
    Connection *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool* create_connection_pool(size_t initial_capacity) {
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->connections = malloc(initial_capacity * sizeof(Connection));
    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->connections[i].status = IDLE;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void resize_pool_if_needed(ConnectionPool *pool) {
    size_t new_capacity = pool->capacity * 2;
    if (new_capacity * sizeof(Connection) > MAX_MEMORY_USAGE || 
        pool->count >= pool->capacity) {
        fprintf(stderr, "Memory limit reached or capacity exceeded\n");
        return; // Handle memory pressure scenario
    }

    Connection *new_connections = realloc(pool->connections, new_capacity * sizeof(Connection));
    if (new_connections) {
        for (size_t i = pool->capacity; i < new_capacity; ++i) {
            new_connections[i].status = IDLE;
        }
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize the connection pool\n");
    }
}

int test_connection(const Connection *conn) {
    struct sockaddr_in addr;
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return -1;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(conn->port);

    if (inet_pton(AF_INET, conn->ip, &addr.sin_addr) <= 0) {
        close(sock);
        return -1;
    }

    int result = connect(sock, (struct sockaddr*)&addr, sizeof(addr));
    if (result < 0) {
        close(sock);
        return -1; // Connection failed
    }

    close(sock);
    return 0; // Successful connection
}

int get_active_connection(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->connections[i].status == IDLE && test_connection(&pool->connections[i]) == 0) {
            pool->connections[i].status = ACTIVE;
            pthread_mutex_unlock(&pool->lock);
            return i; // Connection index
        }
    }

    resize_pool_if_needed(pool);

    if (pool->count < pool->capacity) {
        int new_index = pool->count++;
        strcpy(pool->connections[new_index].ip, "0.0.0.0"); // Default IP
        pool->connections[new_index].port = 0; // Default port
        pool->connections[new_index].status = ACTIVE;
        pthread_mutex_unlock(&pool->lock);
        return new_index;
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // No available connection
}

void close_connection(ConnectionPool *pool, int index) {
    if (index >= 0 && index < pool->count) {
        pthread_mutex_lock(&pool->lock);
        pool->connections[index].status = IDLE;
        pthread_mutex_unlock(&pool->lock);
    }
}

void cleanup_connection_pool(ConnectionPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->connections);
    free(pool);
}
