#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

#define MAX_SEED 4294967295UL
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100
#define STRING_KEY_SIZE 256

typedef struct {
    int value;
    char key[STRING_KEY_SIZE];
    long *offset_ptr;
    time_t *timestamp_ptr;
} record;

typedef struct {
    void (*process_record)(record *);
} Callback;

void log_message(const char *message) {
    printf("%s\n", message);
}

int validate_seed(unsigned long seed, unsigned long *validated_seed) {
    if (seed > MAX_SEED || seed == 0) {
        log_message("Invalid seed provided.");
        return -1;
    }
    *validated_seed = seed;
    return 0;
}

void secure_random_init(unsigned long seed) {
    if (!srand(seed)) {
        log_message("Failed to initialize random number generator.");
        exit(EXIT_FAILURE);
    }
}

int allocate_and_initialize(int size, long **offsets, int **keys, record ***records, time_t **timestamps, Callback *callback, unsigned long seed) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    if (validate_seed(seed, &seed)) return -1;

    secure_random_init(seed);

    offsets = malloc(size * sizeof(long));
    keys = malloc(size * sizeof(int));
    timestamps = malloc(size * sizeof(time_t));

    if (!offsets || !keys || !timestamps) {
        log_message("Memory allocation failed.");
        free(offsets);
        free(keys);
        free(timestamps);
        return -1;
    }

    for (int i = 0; i < size; ++i) {
        offsets[i] = i;
        keys[i] = i;
        timestamps[i] = time(NULL); // Using system time as a placeholder
    }

    records = malloc(size * sizeof(record *));
    if (!records) {
        log_message("Memory allocation for records failed.");
        free(offsets);
        free(keys);
        free(timestamps);
        return -1;
    }

    for (int i = 0; i < size; ++i) {
        record *rec = malloc(sizeof(record));
        if (!rec) {
            log_message("Memory allocation for a record failed.");
            continue;
        }

        rec->value = rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1) + RANDOM_RANGE_MIN;

        snprintf(rec->key, STRING_KEY_SIZE, "Key_%d", i);

        rec->offset_ptr = malloc(sizeof(long));
        if (!rec->offset_ptr) {
            log_message("Memory allocation for offset pointer failed.");
            free(rec);
            continue;
        }

        *(rec->offset_ptr) = offsets[i];

        rec->timestamp_ptr = malloc(sizeof(time_t));
        if (!rec->timestamp_ptr) {
            log_message("Memory allocation for timestamp pointer failed.");
            free(*rec->offset_ptr);
            free(rec);
            continue;
        }

        *(rec->timestamp_ptr) = timestamps[i];

        records[i] = rec;

        if (callback && callback->process_record) {
            pthread_mutex_lock(&mutex);
            callback->process_record(rec);
            pthread_mutex_unlock(&mutex);
        }
    }

    return 0;
}

void free_memory(int size, long *offsets, int *keys, record **records, time_t *timestamps) {
    for (int i = 0; i < size; ++i) {
        if (records[i]) {
            if (records[i]->offset_ptr) free(records[i]->offset_ptr);
            if (records[i]->timestamp_ptr) free(records[i]->timestamp_ptr);
            free(records[i]);
        }
    }

    free(offsets);
    free(keys);
    free(timestamps);
    free(records);
}

// Example usage
void example_callback(record *rec) {
    printf("Processing record with value: %d\n", rec->value);
}

int main() {
    int size = 10;
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;
    time_t *timestamps = NULL;

    Callback callback = { example_callback };
    unsigned long seed = 12345UL;

    if (allocate_and_initialize(size, &offsets, &keys, &records, &timestamps, &callback, seed) == -1) {
        log_message("Initialization failed.");
        return EXIT_FAILURE;
    }

    free_memory(size, offsets, keys, records, timestamps);
    return EXIT_SUCCESS;
}
