    srand(time(NULL));
    int num = rand() % (max - min + 1) + min;
}

void resizeArray(void** array, size_t elementSize, size_t currentSize, size_t newSize) {
    void* newAlloc = realloc(*array, elementSize * newSize);
    if (!newAlloc) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = newAlloc;
}

void processGraphAndFindMax(size_t minRecords, size_t maxRecords,
                            size_t minEdges, size_t maxEdges,
                            size_t minVertices, size_t maxVertices,
                            size_t minQueries, size_t maxQueries,
                            void (*callback)(const char*, const void*)) {

    // Initialize arrays
    long* offset = malloc(sizeof(long) * minRecords);
    int* key = malloc(sizeof(int) * minRecords);

    Record* records = malloc(sizeof(Record) * minRecords);
    Edge* edges = malloc(sizeof(Edge) * minEdges);

    Vertex** vertices = malloc(sizeof(Vertex*) * minVertices);
    Query** queries = malloc(sizeof(Query*)) * minQueries;

    int* inputNumbers = NULL;
    size_t currentSize = 0, capacity = 10;
    inputNumbers = malloc(capacity * sizeof(int));

    if (!offset || !key || !records || !edges || !vertices || !queries || !inputNumbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Fill offset and key arrays
    for (size_t i = 0; i < minRecords; ++i) {
        offset[i] = i;
        key[i] = i;
        records[i].value = secureRandom(1, 100);
        records[i].key = strdup("default_key");
        records[i].dataPointer = malloc(sizeof(long));
        if (!records[i].dataPointer) {
            perror("Failed to allocate memory for record data pointer");
            exit(EXIT_FAILURE);
        }
        *records[i].dataPointer = secureRandom(1, 100);

        if (callback) callback("Record", &records[i]);
    }

    // Add random edges
    size_t edgeCount = secureRandom(minEdges, maxEdges);
    resizeArray((void**)&edges, sizeof(Edge), minEdges, edgeCount);

    for (size_t i = 0; i < edgeCount; ++i) {
        edges[i].weight = secureRandom(1, 50);
        edges[i].type = secureRandom(1, 5);

        if (callback) callback("Edge", &edges[i]);
    }

    // Add random vertices
    size_t vertexCount = secureRandom(minVertices, maxVertices);
    resizeArray((void**)&vertices, sizeof(Vertex*), minVertices, vertexCount);

    for (size_t i = 0; i < vertexCount; ++i) {
        vertices[i] = malloc(sizeof(Vertex));
        if (!vertices[i]) {
            perror("Failed to allocate memory for vertex");
            exit(EXIT_FAILURE);
        }

        vertices[i]->x = secureRandom(1, 100) / 10.0;
        vertices[i]->y = secureRandom(1, 100) / 10.0;
        vertices[i]->labels = malloc(sizeof(char*) * 3); // Assume max 3 labels
        if (!vertices[i]->labels) {
            perror("Failed to allocate memory for vertex labels");
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < 3; ++j) {
            vertices[i]->labels[j] = strdup("default_label");
        }

        vertices[i]->labelCount = secureRandom(1, 3);

        if (callback) callback("Vertex", vertices[i]);

        // Link list implementation
        if (i > 0) {
            vertices[i-1]->next = vertices[i];
        }
    }

    // Read integers from standard input into dynamic array
    int number;
    while (scanf("%d", &number) == 1 && number != -1) {
        if (currentSize >= capacity) {
            capacity *= 2;
            resizeArray((void**)&inputNumbers, sizeof(int), currentSize, capacity);
        }
        inputNumbers[currentSize++] = number;
    }

    // Add queries
    size_t queryCount = secureRandom(minQueries, maxQueries);
    resizeArray((void**)queries, sizeof(Query*), minQueries, queryCount);

    for (size_t i = 0; i < queryCount; ++i) {
        queries[i] = malloc(sizeof(Query));
