// Forward declaration for callback
typedef void (*record_callback_t)(void* record);

typedef struct {
    int value;
    char key[256];
    long* offset_ptr;
    time_t* timestamp_ptr;
} Record;

#define INITIAL_RECORD_SIZE 10

// Function prototypes
Record* initialize_records(size_t size, unsigned int random_seed);
void cleanup_records(Record* records, size_t size);
int resize_records(Record** records, size_t* current_size, size_t new_size);
void process_record(void* record, record_callback_t callback);

// Random number generator with fallback strategy
static inline int generate_random(int min, int max) {
    static int is_initialized = 0;
    if (!is_initialized) {
        srand(time(NULL));
        is_initialized = 1;
    }

    return (rand() % (max - min + 1)) + min;
}

// Initialize records with random values and setup callbacks
Record* initialize_records(size_t size, unsigned int random_seed) {
    if (size == 0 || random_seed == 0)
        return NULL;

    Record* records = malloc(size * sizeof(Record));
    if (!records)
        return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = generate_random(1, 100); // Random value between 1 and 100
        snprintf(records[i].key, sizeof(records[i].key), "Key_%zu", i);

        records[i].offset_ptr = malloc(sizeof(long));
        if (!records[i].offset_ptr) {
            cleanup_records(records, size);
            return NULL;
        }
        *records[i].offset_ptr = (long)i;

        records[i].timestamp_ptr = malloc(sizeof(time_t));
        if (!records[i].timestamp_ptr) {
            free(records[i].offset_ptr);
            cleanup_records(records, size);
            return NULL;
        }
        *records[i].timestamp_ptr = time(NULL); // Current timestamp
    }

    return records;
}

// Callback mechanism to process each record
void process_record(void* record, record_callback_t callback) {
    if (record && callback) {
        callback(record);
    }
}

// Cleanup function for allocated memory
void cleanup_records(Record* records, size_t size) {
    if (!records)
        return;

    for (size_t i = 0; i < size; ++i) {
        free(records[i].offset_ptr);
        free(records[i].timestamp_ptr);
    }
    free(records);
}

// Dynamic resizing mechanism
int resize_records(Record** records, size_t* current_size, size_t new_size) {
    if (!records || !current_size)
        return -1;

    Record* temp = realloc(*records, new_size * sizeof(Record));
    if (!temp)
        return -1;

    *records = temp;

    for (size_t i = *current_size; i < new_size; ++i) {
        (*records)[i].value = generate_random(1, 100);
        snprintf((*records)[i].key, sizeof((*records)[i].key), "Key_%zu", i);

        (*records)[i].offset_ptr = malloc(sizeof(long));
        if (!(*records)[i].offset_ptr) {
            cleanup_records(*records, new_size);
            return -1;
        }
        *(*records)[i].offset_ptr = (long)i;

        (*records)[i].timestamp_ptr = malloc(sizeof(time_t));
        if (!(*records)[i].timestamp_ptr) {
            free((*records)[i].offset_ptr);
            cleanup_records(*records, new_size);
            return -1;
        }
        *(*records)[i].timestamp_ptr = time(NULL); // Current timestamp
    }

    *current_size = new_size;
    return 0;
}

// Example callback function
void example_callback(void* record) {
    Record* rec = (Record*)record;
    printf("Processing: %s, Value: %d\n", rec->key, rec->value);
}

int main() {
    size_t record_count = INITIAL_RECORD_SIZE;
    unsigned int seed = 12345; // Example seed

    Record* records = initialize_records(record_count, seed);
    if (!records) {
        fprintf(stderr, "Failed to initialize records.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < record_count; ++i) {
        process_record(&records[i], example_callback);
    }

    // Example resize
    if (resize_records(&records, &record_count, record_count + 5)) {
        fprintf(stderr, "Failed to resize records.\n");
        cleanup_records(records, record_count);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < record_count; ++i) {
        process_record(&records[i], example_callback);
    }

    cleanup_records(records, record_count);

    return EXIT_SUCCESS;
}
