    dataset->keys = malloc(num_records * sizeof(int));
    dataset->records = malloc(num_records * sizeof(record_t*));
    dataset->identifiers = malloc(num_records * sizeof(char*));

    if (!dataset->offsets || !dataset->keys || !dataset->records || !dataset->identifiers) {
        log_message("Failed to allocate memory for arrays.");
        free_resources(dataset);
        return NULL;
    }

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_records; ++i) {
        dataset->offsets[i] = i * max_record_size;
        dataset->keys[i] = i;

        dataset->records[i] = malloc(record_struct_size);
