typedef enum {
    PREFERENCE_TYPE_STRING,
    PREFERENCE_TYPE_INTEGER,
    PREFERENCE_TYPE_BOOLEAN
} PreferenceType;

typedef struct {
    char *name;
    PreferenceType type;
    union {
        char *stringValue;
        int intValue;
        _Bool boolValue;
    } defaultValue;
    union {
        char *stringValue;
        int intValue;
        _Bool boolValue;
    } currentValue;
} Preference;

typedef void (*CallbackFunc)(Preference*);

typedef struct {
    Preference **preferences;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PreferenceManager;

// Function prototypes
void manageUserPreferences(size_t minSize, size_t maxSize);
static void initializePreferences(PreferenceManager *manager, size_t initialCapacity, CallbackFunc callback);
static void resizePreferencesIfNeeded(PreferenceManager *manager, size_t newSize);
static void addPreference(PreferenceManager *manager, const char *name, PreferenceType type, union {
    char *stringValue;
    int intValue;
    _Bool boolValue;
} defaultValue);
static void handleInput(PreferenceManager *manager, CallbackFunc callback);

// Manage user preferences
void manageUserPreferences(size_t minSize, size_t maxSize) {
    if (minSize > maxSize || !maxSize) return;

    PreferenceManager manager = {0};
    pthread_mutex_init(&manager.lock, NULL);
    initializePreferences(&manager, minSize, NULL);

    handleInput(&manager, NULL);

    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.preferences[i]->name);
        free(manager.preferences[i]->defaultValue.stringValue);
        if (manager.preferences[i]->type == PREFERENCE_TYPE_STRING)
            free(manager.preferences[i]->currentValue.stringValue);
        free(manager.preferences[i]);
    }
    for (size_t i = 0; i < manager.capacity; ++i) {
        free(manager.preferences[i]);
    }
    free(manager.preferences);
    pthread_mutex_destroy(&manager.lock);
}

static void initializePreferences(PreferenceManager *manager, size_t initialCapacity, CallbackFunc callback) {
    manager->preferences = calloc(initialCapacity, sizeof(Preference *));
    if (!manager->preferences) exit(EXIT_FAILURE);

    manager->capacity = initialCapacity;
    manager->count = 0;

    for (size_t i = 0; i < initialCapacity; ++i) {
        Preference *pref = malloc(sizeof(Preference));
        if (!pref) exit(EXIT_FAILURE);

        // Example initialization logic
        pref->name = strdup("default");
        pref->type = PREFERENCE_TYPE_STRING;
        pref->defaultValue.stringValue = strdup("");
        pref->currentValue.stringValue = strdup("");

        manager->preferences[i] = pref;

        if (callback) callback(pref);

        manager->count++;
    }
}

static void resizePreferencesIfNeeded(PreferenceManager *manager, size_t newSize) {
    pthread_mutex_lock(&manager->lock);
    if (newSize > manager->capacity) {
        size_t newCapacity = manager->capacity;
        while (newCapacity < newSize) newCapacity *= 2;

        Preference **temp = realloc(manager->preferences, newCapacity * sizeof(Preference *));
        if (!temp) exit(EXIT_FAILURE);

        for (size_t i = manager->count; i < newCapacity; ++i)
            temp[i] = NULL;

        manager->preferences = temp;
        manager->capacity = newCapacity;
    }
    pthread_mutex_unlock(&manager->lock);
}

static void addPreference(PreferenceManager *manager, const char *name, PreferenceType type, union {
    char *stringValue;
    int intValue;
    _Bool boolValue;
} defaultValue) {
    resizePreferencesIfNeeded(manager, manager->count + 1);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (!manager->preferences[i]) {
            Preference *pref = malloc(sizeof(Preference));
            if (!pref) exit(EXIT_FAILURE);

            pref->name = strdup(name);
            pref->type = type;
            switch (type) {
                case PREFERENCE_TYPE_STRING:
                    pref->defaultValue.stringValue = strdup(defaultValue.stringValue);
                    pref->currentValue.stringValue = strdup("");
                    break;
                case PREFERENCE_TYPE_INTEGER:
                    pref->defaultValue.intValue = defaultValue.intValue;
                    pref->currentValue.intValue = defaultValue.intValue;
                    break;
                case PREFERENCE_TYPE_BOOLEAN:
                    pref->defaultValue.boolValue = defaultValue.boolValue;
                    pref->currentValue.boolValue = defaultValue.boolValue;
                    break;
            }

            manager->preferences[i] = pref;
            manager->count++;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    Preference *pref = malloc(sizeof(Preference));
    if (!pref) exit(EXIT_FAILURE);

    pref->name = strdup(name);
    pref->type = type;
    switch (type) {
        case PREFERENCE_TYPE_STRING:
            pref->defaultValue.stringValue = strdup(defaultValue.stringValue);
            pref->currentValue.stringValue = strdup("");
            break;
        case PREFERENCE_TYPE_INTEGER:
            pref->defaultValue.intValue = defaultValue.intValue;
            pref->currentValue.intValue = defaultValue.intValue;
            break;
        case PREFERENCE_TYPE_BOOLEAN:
            pref->defaultValue.boolValue = defaultValue.boolValue;
            pref->currentValue.boolValue = defaultValue.boolValue;
            break;
    }

    manager->preferences[manager->count++] = pref;

    pthread_mutex_unlock(&manager->lock);
}

static void handleInput(PreferenceManager *manager, CallbackFunc callback) {
    char inputBuffer[256];
    while (fgets(inputBuffer, sizeof(inputBuffer), stdin)) {
        // Simple parsing logic for demonstration
        if (strncmp(inputBuffer, "exit", 4) == 0)
            break;

        char name[64], value[64];
        int type;

        if (sscanf(inputBuffer, "%63[^:]: %d:%63s", name, &type, value) < 2)
            continue; // malformed input

        union {
            char *stringValue;
            int intValue;
            _Bool boolValue;
        } defaultValue;

        switch (type) {
            case PREFERENCE_TYPE_STRING:
                defaultValue.stringValue = strdup(value);
                addPreference(manager, name, PREFERENCE_TYPE_STRING, defaultValue);
                free(defaultValue.stringValue);
                break;
            case PREFERENCE_TYPE_INTEGER: {
                char *endptr;
                long intValue = strtol(value, &endptr, 10);
                if (*endptr || errno == ERANGE) continue; // invalid or out of range
                defaultValue.intValue = (int)intValue;
                addPreference(manager, name, PREFERENCE_TYPE_INTEGER, defaultValue);
                break;
            }
            case PREFERENCE_TYPE_BOOLEAN:
                defaultValue.boolValue = (strcmp(value, "true") == 0);
                addPreference(manager, name, PREFERENCE_TYPE_BOOLEAN, defaultValue);
                break;
        }
    }
}
