```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <semaphore.h>

#include "pcg_random.h"  // Assuming the use of a header file provided by the PCG library

typedef struct {
    int value;
    char key[256];
    long* data_ptr;
} record;

void cleanup(record *records, long *offsets, int *keys, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].data_ptr);
    }
    free(records);
    free(offsets);
    free(keys);
}

int processRecordsAndFindMaxWithSemaphore(size_t offset_size, size_t key_size, size_t record_size,
                                          unsigned long seed, void (*callback)(record*), sem_t *sem) {

    // Initialize arrays with sequential numbers
    long *offsets = (long *)malloc(offset_size * sizeof(long));
    int *keys = (int *)malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        cleanup(NULL, NULL, NULL, 0);
        return -1;
    }

    for (size_t i = 0; i < offset_size; ++i) offsets[i] = (long)i;
    for (size_t i = 0; i < key_size; ++i) keys[i] = (int)i;

    // Allocate and initialize records
    record *records = (record *)malloc(record_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        cleanup(NULL, offsets, keys, 0);
        return -1;
    }

    pcg64_srandom_r(seed ? seed : (unsigned long)time(NULL));

    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = pcg64_random_r() % 100; // Random value within range [0, 99]
        snprintf(records[i].key, sizeof(records[i].key), "Record_%zu", i);

        long *data_ptr = (long *)malloc(sizeof(long));
        if (!data_ptr) {
            fprintf(stderr, "Memory allocation failed for record data.\n");
            cleanup(records, offsets, keys, 0);
            return -1;
        }

        records[i].data_ptr = data_ptr;

        if (callback) callback(&records[i]);

        sem_wait(sem);
        *data_ptr = i; // Example of inter-thread communication
        sem_post(sem);
    }

    int max_value = records[0].value;
    for (size_t i = 1; i < record_size; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Maximum value: %d\n", max_value);

    cleanup(records, offsets, keys, record_size);
    return 0;
}

void example_callback(record *rec) {
    // Example callback function for additional processing
    printf("Processing record with key: %s and value: %d\n", rec->key, rec->value);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <record_size> [seed]\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t record_size = (size_t)atoi(argv[1]);
    unsigned long seed = argc > 2 ? strtoul(argv[2], NULL, 10) : 0;

    sem_t semaphore;
    if (sem_init(&semaphore, 0, 1) != 0) {
        fprintf(stderr, "Failed to initialize semaphore.\n");
        return EXIT_FAILURE;
    }

    processRecordsAndFindMaxWithSemaphore(record_size, record_size, record_size, seed, example_callback, &semaphore);

    sem_destroy(&semaphore);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Management**: The `cleanup` function ensures that all dynamically allocated memory is freed.
- **Random Number Generation**: Uses the PCG library for high-performance random number generation with optional seeding.
- **Synchronization**: A POSIX semaphore is used to manage inter-thread communication and ensure thread safety.
- **Error Handling**: Gracefully handles memory allocation failures.
- **Callback Functionality**: Allows custom processing of each record via a callback function.

This implementation assumes the availability of the PCG random number generation library. Adjust the include paths and link settings as necessary when compiling this code with your specific development environment.']

