['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_RECORD_SIZE 10
#define INITIAL_QUEUE_SIZE 10

typedef struct {
    int integerValue;
    char *key;
    long *dynamicLongPtr;
    time_t timestamp;
} Record;

typedef struct QueueNode {
    Record data;
    struct QueueNode *next;
} QueueNode;

typedef struct {
    QueueNode *front;
    QueueNode *rear;
    size_t size;
    pthread_mutex_t lock;
} Queue;

void initQueue(Queue *q) {
    q->front = q->rear = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
}

bool isQueueEmpty(const Queue *q) {
    return q->size == 0;
}

void enqueue(Queue *q, Record record) {
    QueueNode *newNode = (QueueNode *)malloc(sizeof(QueueNode));
    newNode->data = record;
    newNode->next = NULL;

    pthread_mutex_lock(&q->lock);
    if (isQueueEmpty(q)) {
        q->front = q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    q->size++;
    pthread_mutex_unlock(&q->lock);
}

Record dequeue(Queue *q) {
    pthread_mutex_lock(&q->lock);
    QueueNode *temp = q->front;
    Record record = temp->data;

    if (q->front == q->rear) {
        q->front = q->rear = NULL;
    } else {
        q->front = q->front->next;
    }
    q->size--;
    pthread_mutex_unlock(&q->lock);

    free(temp);
    return record;
}

void processAndAnalyzeRecords(const char *sourceType, const char *filePath) {
    FILE *file = NULL;
    if (strcmp(sourceType, "file") == 0 && filePath != NULL) {
        file = fopen(filePath, "r");
        if (!file) {
            perror("Failed to open file");
            return;
        }
    }

    Record *records = (Record *)malloc(INITIAL_RECORD_SIZE * sizeof(Record));
    int recordCount = 0;
    int capacity = INITIAL_RECORD_SIZE;

    Queue queue;
    initQueue(&queue);

    size_t keySize = 100;
    char buffer[256];

    while (true) {
        if (strcmp(sourceType, "file") == 0 && file != NULL) {
            if (!fgets(buffer, sizeof(buffer), file)) break;
        } else {
            printf("Enter data: ");
            if (!fgets(buffer, sizeof(buffer), stdin)) break;
        }

        // Parse input
        char *token = strtok(buffer, ",");
        if (token == NULL || sscanf(token, "%d", &records[recordCount].integerValue) != 1) {
            fprintf(stderr, "Invalid input format\n");
            continue;
        }

        token = strtok(NULL, ",");
        if (token == NULL || strlen(token) >= keySize - 1) {
            fprintf(stderr, "Invalid key length\n");
            continue;
        }
        records[recordCount].key = strdup(token);

        token = strtok(NULL, ",");
        long *longPtr = malloc(sizeof(long));
        if (token == NULL || sscanf(token, "%ld", longPtr) != 1) {
            free(longPtr);
            fprintf(stderr, "Invalid long value\n");
            continue;
        }
        records[recordCount].dynamicLongPtr = longPtr;

        token = strtok(NULL, ",");
        char *timeStr = token ? token : "0";
        if (strptime(timeStr, "%Y-%m-%d %H:%M:%S", localtime(&records[recordCount].timestamp)) == NULL) {
            fprintf(stderr, "Invalid timestamp format\n");
            continue;
        }

        records[recordCount].timestamp = time(NULL);

        enqueue(&queue, records[recordCount]);
        recordCount++;

        if (recordCount >= capacity) {
            capacity *= 2;
            records = (Record *)realloc(records, capacity * sizeof(Record));
        }
    }

    int maxIntValue = INT_MIN;
    while (!isQueueEmpty(&queue)) {
        Record record = dequeue(&queue);
        if (record.integerValue > maxIntValue) {
            maxIntValue = record.integerValue;
        }
        free(record.key);
        free(record.dynamicLongPtr);
    }

    printf("Maximum integer value: %d\n", maxIntValue);

    free(records);
    if (file != NULL) fclose(file);
}

