```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LEN 256

typedef struct {
    long offset;
    int key;
    double value;
    char *metadata;
    int ref_count;
    int access_count;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    unsigned long memory_limit;
    unsigned int access_threshold;
    double reduction_factor;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity, unsigned long memory_limit,
                                     unsigned int access_threshold, double reduction_factor) {
    RecordManager *manager = (RecordManager *)malloc(sizeof(RecordManager));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for RecordManager\n");
        exit(EXIT_FAILURE);
    }

    manager->records = (Record **)calloc(initial_capacity, sizeof(Record *));
    if (!manager->records) {
        free(manager);
        fprintf(stderr, "Failed to allocate memory for records array\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->mutex, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->memory_limit = memory_limit;
    manager->access_threshold = access_threshold;
    manager->reduction_factor = reduction_factor;

    return manager;
}

void destroy_record_manager(RecordManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]->metadata);
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_unlock(&manager->mutex);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int generate_unique_key(RecordManager *manager, int *key) {
    while (1) {
        *key = rand() % 1000000;

        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->records[i]->key == *key) break;
        }

        if (i == manager->count) return 1; // Unique key found
    }
}

Record* create_record(long offset, int key, double value, const char *metadata) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for Record\n");
        exit(EXIT_FAILURE);
    }

    record->offset = offset;
    record->key = key;
    record->value = value;
    record->metadata = strdup(metadata);
    if (!record->metadata) {
        free(record);
        fprintf(stderr, "Failed to duplicate metadata string\n");
        exit(EXIT_FAILURE);
    }
    record->ref_count = 0;
    record->access_count = 0;

    return record;
}

void insert_record(RecordManager *manager, Record *record) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record **new_records = realloc(manager->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            fprintf(stderr, "Failed to reallocate memory for records array\n");
            pthread_mutex_unlock(&manager->mutex);
            exit(EXIT_FAILURE);
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count++] = record;

    // Check and enforce memory limit
    unsigned long current_memory_usage = sizeof(RecordManager) +
                                         manager->count * (sizeof(Record *) + sizeof(long) + 
                                                          sizeof(int) + sizeof(double) + 
                                                          MAX_METADATA_LEN + sizeof(int) + sizeof(int));
    if (current_memory_usage > manager->memory_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        pthread_mutex_unlock(&manager->mutex);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&manager->mutex);
}

Record* get_record(RecordManager *manager, int key) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]->key == key) {
            manager->records[i]->access_count++;

            // Check access threshold
            if (manager->records[i]->access_count > manager->access_threshold) {
                manager->records[i]->ref_count = 
                    (int)(manager->records[i]->ref_count * (1 - manager->reduction_factor));
            }

            pthread_mutex_unlock(&manager->mutex);
            return manager->records[i];
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void serialize_records(RecordManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        return;
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(manager->records[i], sizeof(Record), 1, file);
    }
    pthread_mutex_unlock(&manager->mutex);

    fclose(file);
}

int deserialize_records(RecordManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->mutex);
    manager->records = (Record **)realloc(manager->records, count * sizeof(Record *));
    if (!manager->records) {
        fprintf(stderr, "Failed to reallocate memory for records array\n");
        fclose(file);
        return -1;
    }
    manager->count = count;

    for (size_t i = 0; i < manager->count; ++i) {
        fread(manager->records[i], sizeof(Record), 1, file);
        // Reallocate metadata string
        free(manager->records[i]->metadata);
        manager->records[i]->metadata = strdup(manager->records[i]->metadata);
    }
    pthread_mutex_unlock(&manager->mutex);

    fclose(file);
    return 0;
}

void check_for_corruption(RecordManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (!manager->records[i]) {
            fprintf(stderr, "Corrupted record at index %zu\n", i);
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void garbage_collect(RecordManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    size_t new_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]->access_count > 1) { // Keep records accessed more than once
            manager->records[new_count++] = manager->records[i];
        } else {
            free(manager->records[i]->metadata);
            free(manager->records[i]);
        }
    }

    manager->count = new_count;
    pthread_mutex_unlock(&manager->mutex);
}

int main() {
    srand(time(NULL));

    RecordManager *manager = create_record_manager(10, 1024 * 1024, 5, 0.1);

    int key;
    for (size_t i = 0; i < 20; ++i) {
        generate_unique_key(manager, &key);
        long offset = rand() % 10000;
        double value = (double)rand() / RAND_MAX;

        char metadata[MAX_METADATA_LEN];
        snprintf(metadata, MAX_METADATA_LEN, "Metadata for key %d", key);

        Record *record = create_record(offset, key, value, metadata);
        insert_record(manager, record);
    }

    serialize_records(manager, "records.dat");
    check_for_corruption(manager);

    Record *retrieved_record = get_record(manager, 12345); // Example key
    if (retrieved_record) {
        printf("Record found: key=%d, value=%.2f\n", retrieved_record->key, retrieved_record->value);
    } else {
        printf("Record not found.\n");
    }

    garbage_collect(manager);

    deserialize_records(manager, "records.dat");

    destroy_record_manager(manager);
    return 0;
}
