        inputNumbers = realloc(inputNumbers, (numElements + 1) * sizeof(int));
        if (!inputNumbers) {
            perror("Memory allocation failed");
            free(offsets); free(keys);
            for (size_t i = 0; i < recordSize; ++i)
                free(records[i].ptr);
            free(records);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        inputNumbers[numElements++] = number;
    }

    pthread_mutex_unlock(&mutex);

    int maxVal = findMax(inputNumbers, numElements);

    printf("Maximum Value: %d\n", maxVal);

    // Free allocated memory
    free(offsets); 
    free(keys);
    for (size_t i = 0; i < recordSize; ++i)
        free(records[i].ptr);
    free(records);
    free(inputNumbers);

    return NULL;
}

int findMax(int *numbers, size_t count) {
    if (!numbers || count == 0)
        return INT_MIN;

    int maxVal = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > maxVal)
            maxVal = numbers[i];
    }

    return maxVal;
}

