        offset[i] = i;
    }
    for (int i = 0; i < key_size; ++i) {
        key[i] = i;
    }
}

void initializeRecords(int *records, int record_size, int rand_min, int rand_max, unsigned int seed, void (*callback)(int)) {
    secure_random_init(seed); // Initialize the random generator with a seed

    for (int i = 0; i < record_size; ++i) {
        records[i] = secure_random_int(rand_min, rand_max);
        if (callback) {
            callback(records[i]);
        }
    }

    secure_random_cleanup(); // Cleanup resources used by the external library
}

void findMax(int *array, int size, int *max_value) {
    *max_value = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > *max_value) {
            *max_value = array[i];
        }
    }
}

void processRecordsAndFindMax(const Config *config, void (*callback)(int)) {
    int *offset = malloc(config->offset_size * sizeof(int));
    handleMemoryError(offset);

    int *key = malloc(config->key_size * sizeof(int));
    handleMemoryError(key);

    initializeArrays(offset, config->offset_size, key, config->key_size);

    int *records = malloc(config->record_size * sizeof(int));
    handleMemoryError(records);

    promptForValidRange(&config->rand_min, &config->rand_max);
    initializeRecords(records, config->record_size, config->rand_min, config->rand_max, config->seed, callback);

    free(offset);
    free(key);
    free(records);
}

void readIntegersAndFindMax() {
