    int *array = malloc(size * sizeof(int));
    handleMemoryError(array);

    int count = 0;
    int number;

    printf("Enter integers (terminate with -1):\n");
    while (scanf("%d", &number) && number != -1) {
        if (count >= size) {
            size *= 2;
            array = realloc(array, size * sizeof(int));
            handleMemoryError(array);
        }
        array[count++] = number;
    }

    int max_value;
    findMax(array, count, &max_value);

    printf("Maximum integer: %d\n", max_value);

    free(array);
}

int main() {
