#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef void (*TaskCallback)(void);

typedef struct {
    int priority;
    char *title;
    TaskCallback callback;
} Task;

typedef struct {
    Task *tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int (*compare)(const Task *, const Task *);
} TaskList;

static void resize_task_list(TaskList *list) {
    size_t new_capacity = list->capacity * 2;
    Task *new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));

    if (!new_tasks) {
        perror("Failed to reallocate memory for task list");
        exit(EXIT_FAILURE);
    }

    list->tasks = new_tasks;
    list->capacity = new_capacity;
}

TaskList* initialize_task_list(size_t initial_capacity, int (*compare)(const Task *, const Task *)) {
    if (initial_capacity == 0) {
        initial_capacity = 4; // default capacity
    }

    TaskList *list = malloc(sizeof(TaskList));
    if (!list) {
        perror("Failed to allocate memory for task list");
        return NULL;
    }

    list->tasks = calloc(initial_capacity, sizeof(Task));
    if (!list->tasks) {
        free(list);
        perror("Failed to allocate memory for tasks");
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->compare = compare ? compare : (int (*)(const Task *, const Task *))default_compare;

    return list;
}

static int default_compare(const Task *a, const Task *b) {
    return a->priority - b->priority;
}

int add_task(TaskList *list, int priority, const char *title, TaskCallback callback) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resize_task_list(list);
    }

    Task *task = &list->tasks[list->count++];
    task->priority = priority;

    size_t title_len = strlen(title) + 1;
    char *new_title = malloc(title_len);
    if (!new_title) {
        perror("Failed to allocate memory for task title");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(new_title, title, title_len);
    task->title = new_title;

    task->callback = callback ? callback : (TaskCallback)default_callback;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_task(TaskList *list, size_t index, int priority, const char *new_title) {
    if (index >= list->count) {
        return -1; // Index out of bounds
    }

    pthread_mutex_lock(&list->lock);

    Task *task = &list->tasks[index];
    task->priority = priority;

    if (new_title != NULL && new_title[0] != '\0') {
        free(task->title);
        size_t title_len = strlen(new_title) + 1;
        char *updated_title = malloc(title_len);
        if (!updated_title) {
            perror("Failed to allocate memory for updated task title");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        memcpy(updated_title, new_title, title_len);
        task->title = updated_title;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void execute_task(TaskList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Task index out of bounds\n");
        return;
    }

    Task task = list->tasks[index];

    pthread_mutex_lock(&list->lock);
    task.callback();
    pthread_mutex_unlock(&list->lock);
}

void free_task_list(TaskList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->tasks[i].title);
    }

    free(list->tasks);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void default_callback(void) {
