#include "thread_safe_lib.h" // Placeholder for an external thread-safe library

typedef struct {
    int id;
    double value;
    char *description;
} item;

typedef struct {
    item **items;            // Dynamic array of pointers to items
    size_t capacity;         // Maximum number of items the array can hold
    size_t count;            // Current number of items in the collection
    pthread_mutex_t mutex;   // Mutex for thread safety
    ts_lock *lock;           // External thread-safe lock (from external library)
} item_collection;

// Callback function type definition
typedef void (*item_callback)(item*);

// Function to initialize the collection
int init_item_collection(item_collection *collection, size_t initial_capacity) {
    if (!collection) return -1;

    pthread_mutex_init(&collection->mutex, NULL);
    ts_lock_init(collection->lock);

    collection->capacity = initial_capacity > 0 ? initial_capacity : 10; // Default to 10
    collection->items = calloc(collection->capacity, sizeof(item*));
    collection->count = 0;

    if (!collection->items) {
        pthread_mutex_destroy(&collection->mutex);
        ts_lock_destroy(collection->lock);
        return -1;
    }

    return 0;
}

// Function to add a new item
int add_item(item_collection *collection, int id, double value, const char *description, item_callback callback) {
    if (!collection) return -1;

    // Lock for thread safety
    pthread_mutex_lock(&collection->mutex);
    ts_lock_acquire(collection->lock);

    // Check for duplicate ID
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->items[i]->id == id) {
            pthread_mutex_unlock(&collection->mutex);
            ts_lock_release(collection->lock);
            return -1; // Duplicate ID found
        }
    }

    // Ensure capacity and reallocate if necessary
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        item **new_items = realloc(collection->items, new_capacity * sizeof(item*));

        if (!new_items) {
            pthread_mutex_unlock(&collection->mutex);
            ts_lock_release(collection->lock);
            return -1; // Reallocation failed
        }

        collection->items = new_items;
        collection->capacity = new_capacity;
    }

    // Create and add the new item
    item *new_item = malloc(sizeof(item));
    if (!new_item) {
        pthread_mutex_unlock(&collection->mutex);
        ts_lock_release(collection->lock);
        return -1; // Allocation failed
    }

    new_item->id = id;
    new_item->value = value;
    new_item->description = strdup(description);

    collection->items[collection->count++] = new_item;

    // Execute callback if provided
    if (callback) {
        callback(new_item);
    }

    pthread_mutex_unlock(&collection->mutex);
    ts_lock_release(collection->lock);

    return 0;
}

// Function to retrieve an item by ID
item* get_item(item_collection *collection, int id) {
    if (!collection) return NULL;

    pthread_mutex_lock(&collection->mutex);
    ts_lock_acquire(collection->lock);

    for (size_t i = 0; i < collection->count; i++) {
        if (collection->items[i]->id == id) {
            item *result = collection->items[i];
            pthread_mutex_unlock(&collection->mutex);
            ts_lock_release(collection->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    ts_lock_release(collection->lock);

    return NULL; // Item not found
}

// Function to retrieve the entire collection as a list of items
item** get_collection_list(item_collection *collection, size_t *out_count) {
    if (!collection || !out_count) return NULL;

    pthread_mutex_lock(&collection->mutex);
    ts_lock_acquire(collection->lock);

    item **list = malloc(collection->count * sizeof(item*));
    if (!list) {
        pthread_mutex_unlock(&collection->mutex);
        ts_lock_release(collection->lock);
        return NULL;
    }

    memcpy(list, collection->items, collection->count * sizeof(item*));
    *out_count = collection->count;

    pthread_mutex_unlock(&collection->mutex);
    ts_lock_release(collection->lock);

    return list; // Caller is responsible for freeing this memory
}

// Function to free all resources in the collection
void free_item_collection(item_collection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->mutex);
    ts_lock_acquire(collection->lock);

    for (size_t i = 0; i < collection->count; i++) {
        free(collection->items[i]->description);
        free(collection->items[i]);
    }
    free(collection->items);

    pthread_mutex_unlock(&collection->mutex);
    ts_lock_release(collection->lock);

    pthread_mutex_destroy(&collection->mutex);
    ts_lock_destroy(collection->lock);
}
