void allocate_and_init(int *num_elements, void **array, size_t element_size) {
    if (*num_elements > 0) {
        *array = malloc(*num_elements * element_size);
        if (!*array) {
            log_error("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        memset(*array, 0, *num_elements * element_size); // Efficient initialization
    } else {
        *array = NULL;
    }
}

void process_transactions(const char *input_file_path, size_t max_transactions) {
    FILE *file = fopen(input_file_path, "r");
    if (!file) {
        log_error("Failed to open input file");
        return;
    }

    // Dynamic memory allocation
    int num_offsets = 0, num_identifiers = 0, num_transactions = 0, num_audits = 0;
    long *offsets = NULL, *transaction_amounts = NULL;
    char **identifiers = NULL;
    transaction *transactions = NULL;
    audit_log *audit_logs = NULL;

    allocate_and_init(&num_offsets, (void**)&offsets, sizeof(long));
    allocate_and_init(&num_identifiers, (void**) &identifiers, sizeof(char*));
    allocate_and_init(&num_transactions, (void**)&transaction_amounts, sizeof(float));
    allocate_and_init(&num_transactions, (void**)&transactions, sizeof(transaction));
    allocate_and_init(&num_audits, (void**)&audit_logs, sizeof(audit_log));

    long offset = 0;
    while (fscanf(file, "%Lf", &offset) == 1 && num_transactions < max_transactions) {
        // Read and validate transaction amount
        float amount;
        int valid = 0;
        int retry_count = 0;

        do {
            if (fscanf(file, "%f", &amount) != 1) {
                log_error("Invalid input format");
                continue;
            }

            if (!validate_transaction_amount(amount)) {
                log_error("Transaction amount validation failed");
                retry_count++;
            } else {
                valid = 1;
            }
        } while (!valid && ++retry_count < 5); // Max retries

        if (valid) {
            offsets[num_offsets++] = offset;
            allocate_and_init(&num_identifiers, (void**) &identifiers, sizeof(char*));
            identifiers[num_identifiers] = strdup("TransactionID"); // Placeholder for actual ID fetching
            transaction_amounts[num_transactions] = amount;

            transactions[num_transactions].amount = amount;
            transactions[num_transactions].timestamp = 0; // Placeholder timestamp
            strcpy(transactions[num_transactions].status, "Pending");

            audit_logs[num_audits].retry_count = retry_count;
            audit_logs[num_audits].offset = offset;
            snprintf(audit_logs[num_audits].validation_message, sizeof(audit_logs[0].validation_message), 
                     "Transaction at offset %ld validated after %d retries", offset, retry_count);

            num_transactions++;
            num_audits++;
        }
    }

    fclose(file);

    // Export transactions to JSON
    if (num_transactions > 0) {
        char *json_output = json_export_transactions(transactions, num_transactions);
        printf("%s\n", json_output); // For demonstration; in real use-case write to a file or another system component

        free(json_output);
    }

    // Cleanup resources
    for (int i = 0; i < num_identifiers; ++i) {
        free(identifiers[i]);
    }
    free(offsets);
    free(transaction_amounts);
    free(transactions);
    free(audit_logs);
}

// Main function to demonstrate usage
int main() {
    process_transactions("transactions.txt", 1000); // Example input file and max limit
    return 0;
}
