#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structure for key-value pair
typedef struct KeyValue {
    int key;
    void *value; // User-defined data structure
    void (*callback)(void*); // Callback function pointer
} KeyValue;

// External memory management library integration placeholder
#define EXTERNAL_MEM_ALLOC(size) malloc(size)
#define EXTERNAL_MEM_FREE(ptr) free(ptr)

// Define structure for dictionary
typedef struct {
    KeyValue **table;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
    int (*compare)(int, int); // Custom comparison function
} DynamicDictionary;

// Function prototypes
DynamicDictionary* init_dictionary(size_t initial_capacity, int (*compare)(int, int));
void resize_dictionary(DynamicDictionary *dict);
int hash_function(int key, size_t capacity);
void insert_or_update(DynamicDictionary *dict, int key, void *value, void (*callback)(void*));
void process_value(DynamicDictionary *dict, int key);
void cleanup_dictionary(DynamicDictionary **dict);

// Initialize dictionary
DynamicDictionary* init_dictionary(size_t initial_capacity, int (*compare)(int, int)) {
    DynamicDictionary *dict = EXTERNAL_MEM_ALLOC(sizeof(DynamicDictionary));
    dict->table = EXTERNAL_MEM_ALLOC(initial_capacity * sizeof(KeyValue *));
    for (size_t i = 0; i < initial_capacity; ++i) {
        dict->table[i] = NULL;
    }
    dict->capacity = initial_capacity;
    dict->size = 0;
    pthread_mutex_init(&dict->lock, NULL);
    dict->compare = compare ? compare : __default_compare;
    return dict;
}

// Default comparison function
int __default_compare(int a, int b) {
    return (a > b) - (a < b);
}

// Hash function
int hash_function(int key, size_t capacity) {
    return (key % capacity + capacity) % capacity; // Ensure positive index
}

// Resize dictionary when needed
void resize_dictionary(DynamicDictionary *dict) {
    pthread_mutex_lock(&dict->lock);

    size_t new_capacity = dict->capacity * 2;
    KeyValue **new_table = EXTERNAL_MEM_ALLOC(new_capacity * sizeof(KeyValue *));
    for (size_t i = 0; i < new_capacity; ++i) {
        new_table[i] = NULL;
    }

    for (size_t i = 0; i < dict->capacity; ++i) {
        if (dict->table[i]) {
            int index = hash_function(dict->table[i]->key, new_capacity);
            KeyValue *entry = EXTERNAL_MEM_ALLOC(sizeof(KeyValue));
            entry->key = dict->table[i]->key;
            entry->value = dict->table[i]->value;
            entry->callback = dict->table[i]->callback;

            while (new_table[index]) {
                index = (index + 1) % new_capacity; // Linear probing
            }
            new_table[index] = entry;
        }
    }

    EXTERNAL_MEM_FREE(dict->table);
    dict->table = new_table;
    dict->capacity = new_capacity;

    pthread_mutex_unlock(&dict->lock);
}

// Insert or update a key-value pair
void insert_or_update(DynamicDictionary *dict, int key, void *value, void (*callback)(void*)) {
    pthread_mutex_lock(&dict->lock);

    if (dict->size >= dict->capacity) {
        resize_dictionary(dict);
    }

    int index = hash_function(key, dict->capacity);
    while (dict->table[index] && dict->table[index]->key != key) {
        index = (index + 1) % dict->capacity; // Linear probing
    }

    if (!dict->table[index]) {
        dict->size++;
    }

    KeyValue *entry = EXTERNAL_MEM_ALLOC(sizeof(KeyValue));
    entry->key = key;
    entry->value = value;
    entry->callback = callback ? callback : __default_callback;

    dict->table[index] = entry;

    pthread_mutex_unlock(&dict->lock);
}

// Default callback function
void __default_callback(void *data) {
    // Do nothing or placeholder processing
}

// Process a value using its associated callback
void process_value(DynamicDictionary *dict, int key) {
    pthread_mutex_lock(&dict->lock);

    int index = hash_function(key, dict->capacity);
    while (dict->table[index] && dict->table[index]->key != key) {
        index = (index + 1) % dict->capacity; // Linear probing
    }

    if (dict->table[index] && dict->table[index]->callback) {
        dict->table[index]->callback(dict->table[index]->value);
    }

    pthread_mutex_unlock(&dict->lock);
}

// Cleanup dictionary and release resources
void cleanup_dictionary(DynamicDictionary **dict_ptr) {
    DynamicDictionary *dict = *dict_ptr;
    if (!dict) return;

    for (size_t i = 0; i < dict->capacity; ++i) {
        if (dict->table[i]) {
            EXTERNAL_MEM_FREE(dict->table[i]);
        }
    }

    pthread_mutex_destroy(&dict->lock);
    EXTERNAL_MEM_FREE(dict->table);
    EXTERNAL_MEM_FREE(dict);
    *dict_ptr = NULL;
}

// Example usage
int main() {
    DynamicDictionary *my_dict = init_dictionary(8, NULL);

    // Example data and callback functions
    int my_data = 42;

    void custom_callback(void* data) {
        printf("Processing value: %d\n", *(int*)data);
    }

    insert_or_update(my_dict, 1, &my_data, custom_callback);
    process_value(my_dict, 1);

    cleanup_dictionary(&my_dict);
    return 0;
}
