#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef void (*TaskCallback)(void);

typedef struct {
    int priority;
    char *title;
    TaskCallback callback;
} Task;

typedef struct {
    Task **tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    int (*compare)(const Task *, const Task *);
} TaskManager;

typedef struct {
    int value;
} Record;

void task_manager_init(TaskManager *manager, size_t initial_capacity, int (*compare)(const Task *, const Task *)) {
    manager->tasks = calloc(initial_capacity, sizeof(Task *));
    if (!manager->tasks) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->compare = compare;
}

void task_manager_free(TaskManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->tasks[i]->title);
        free(manager->tasks[i]);
    }
    free(manager->tasks);
    pthread_mutex_destroy(&manager->lock);
}

int task_manager_resize(TaskManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Task **new_tasks = realloc(manager->tasks, new_capacity * sizeof(Task *));
    if (!new_tasks) {
        fprintf(stderr, "Memory reallocation failed\n");
        return -1;
    }
    manager->tasks = new_tasks;
    manager->capacity = new_capacity;
    return 0;
}

int add_task(TaskManager *manager, int priority, const char *title, TaskCallback callback) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity && task_manager_resize(manager) != 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Task *new_task = malloc(sizeof(Task));
    if (!new_task) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_task->priority = priority;
    new_task->title = strdup(title);
    new_task->callback = callback;

    manager->tasks[manager->size++] = new_task;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_task(TaskManager *manager, int index, int new_priority, const char *new_title) {
    if (index < 0 || index >= manager->size) return -1;

    pthread_mutex_lock(&manager->lock);

    Task *task = manager->tasks[index];
    task->priority = new_priority;

    free(task->title);
    task->title = strdup(new_title);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void execute_task(TaskManager *manager, int index) {
    if (index < 0 || index >= manager->size) return;

    pthread_mutex_lock(&manager->lock);

    Task *task = manager->tasks[index];
    if (task && task->callback) {
        task->callback();
    }

    pthread_mutex_unlock(&manager->lock);
}

void custom_compare(const Task *a, const Task *b) {
    // Example comparison function
    return a->priority - b->priority;
}

long* allocate_offsets(size_t count) {
    long *offsets = calloc(count, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation for offsets failed\n");
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* allocate_keys(size_t count) {
    int *keys = calloc(count, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation for keys failed\n");
        exit(EXIT_FAILURE);
    }
    return keys;
}

Record* initialize_records(size_t count, int min_val, int max_val) {
    Record *records = malloc(count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        exit(EXIT_FAILURE);
