    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    return records;
}

int read_and_process_integers(int *result) {
    int value, max_value = INT_MIN;
    while (scanf("%d", &value) == 1) {
        if (value > max_value) {
            max_value = value;
        }
    }

    if (ferror(stdin)) {
        fprintf(stderr, "Error reading input\n");
        return -1;
    }

    *result = max_value;
    return 0;
}

int main() {
    TaskManager manager;
    task_manager_init(&manager, 4, custom_compare);

