#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <uuid/uuid.h>

// Define structure for records
typedef struct {
    int value;
    char key[256];
    long *offset_ptr;
    time_t timestamp;
    char metadata[512];
} record;

// Function prototypes
void initialize_data(int size, int offset_size, int range_min, int range_max);
void cleanup_memory(long *offsets, int *keys, record **records, time_t *timestamps, char ***metadata);
void process_record_callback(record *rec);

// Thread-local storage for thread safety
__thread pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_data(int size, int offset_size, int range_min, int range_max) {
    srand(time(NULL)); // Set random seed

    long *offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(size * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    record *records = calloc(size, sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    time_t *timestamps = malloc(size * sizeof(time_t));
    if (!timestamps) {
        free(records);
        free(keys);
        free(offsets);
        perror("Failed to allocate memory for timestamps");
        exit(EXIT_FAILURE);
    }

    char **metadata = calloc(size, sizeof(char *));
    if (!metadata) {
        free(timestamps);
        free(records);
        free(keys);
        free(offsets);
        perror("Failed to allocate memory for metadata");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and keys
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }

    for (int i = 0; i < size; ++i) {
        keys[i] = i;

        records[i].value = range_min + rand() % (range_max - range_min + 1);
        timestamps[i] = time(NULL);

        // Generate UUID
        uuid_t uuid;
        uuid_generate_random(uuid);
        char struuid[37];
        uuid_unparse_lower(uuid, struuid);

        snprintf(records[i].key, sizeof(records[i].key), "%s", struuid);

        records[i].offset_ptr = &offsets[rand() % offset_size];

        // Generate metadata
        asprintf(&metadata[i], "Record ID: %d UUID: %s", i, struuid);
    }

    // Process each record with a callback
    for (int i = 0; i < size; ++i) {
        process_record_callback(&records[i]);
    }

    // Simulated logging
    printf("Initialization completed successfully at %ld\n", time(NULL));

    // Clean up function call
    cleanup_memory(offsets, keys, &records, timestamps, &metadata);
}

void cleanup_memory(long *offsets, int *keys, record **records, time_t *timestamps, char ***metadata) {
    free(*records);
    free(keys);
    free(timestamps);

    for (int i = 0; (*metadata)[i] != NULL; ++i) {
        free((*metadata)[i]);
    }
    free(*metadata);
    free(offsets);
}

void process_record_callback(record *rec) {
    pthread_mutex_lock(&lock);
    printf("Processing record with key: %s\n", rec->key);
    pthread_mutex_unlock(&lock);
}
```

