void freeMemory(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

void* safeMalloc(size_t size) {
    void *ptr = malloc(size);
    return ptr;
}

int calculateTotalMemoryUsage(size_t offsetSize, size_t keySize, size_t recordSize, size_t recordElementSize) {
    return sizeof(int) * (offsetSize + keySize) + recordSize * recordElementSize;
}

void manageRecords(
    size_t offsetArraySize,
    size_t keyValueArraySize,
    size_t recordArraySize,
    size_t maxMemoryLimit,
    int randomRangeStart,
    int randomRangeEnd,
    unsigned int seed,
    RecordInitCallback initCallback,
    TransformationFunction transformFunc
) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int *offsets = safeMalloc(offsetArraySize * sizeof(int));
    int *keys = safeMalloc(keyValueArraySize * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed for offsets or keys.\n");
        freeMemory(keys);
        freeMemory(offsets);
        pthread_mutex_destroy(&lock);
        return;
    }

    srand(seed);

    // Initialize offset and key arrays
    for (size_t i = 0; i < offsetArraySize; ++i) {
        offsets[i] = i;
    }
    for (size_t j = 0; j < keyValueArraySize; ++j) {
        keys[j] = j;
    }

    size_t recordElementSize = sizeof(Record);
    Record *records = NULL;

    // Calculate initial memory usage and adjust the number of records if necessary
    while (calculateTotalMemoryUsage(offsetArraySize, keyValueArraySize, recordArraySize, recordElementSize) > maxMemoryLimit && recordArraySize > 0) {
        --recordArraySize;
    }

    records = safeMalloc(recordArraySize * recordElementSize);

    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        freeMemory(keys);
        freeMemory(offsets);
        pthread_mutex_destroy(&lock);
        return;
    }

    // Initialize the records with random values and invoke callback
    for (size_t k = 0; k < recordArraySize; ++k) {
        records[k].value = rand() % (randomRangeEnd - randomRangeStart + 1) + randomRangeStart;

        if (initCallback != NULL) {
            initCallback(k, &records[k]);
        }
    }

    // Update each record based on key and offset
    for (size_t l = 0; l < recordArraySize; ++l) {
        int transformedValue = transformFunc(keys[l % keyValueArraySize], offsets[l % offsetArraySize], records[l].value);
        records[l].value = transformedValue;
    }

    // Simulate external data integration and logging

    // Free all allocated memory
    freeMemory(records);
    freeMemory(keys);
    freeMemory(offsets);

    pthread_mutex_destroy(&lock);
}

