#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STR_LEN 100
#define MAX_RECORDS 10000

typedef enum {
    OFFSET_TYPE,
    KEY_TYPE,
    STRING_TYPE
} RecordType;

typedef struct {
    RecordType type;
    union {
        long offset;
        int key;
        char *str;
    } data;
} Record;

int readIntegers(int **numbers, const char *filePath) {
    FILE *file = (filePath != NULL && strcmp(filePath, "") != 0) ? fopen(filePath, "r") : stdin;
    if (!file) {
        fprintf(stderr, "Error: Cannot open file or standard input.\n");
        return -1;
    }

    int size = 0;
    int capacity = 10; // Start with an initial capacity
    *numbers = malloc(capacity * sizeof(int));
    if (*numbers == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        fclose(file);
        return -1;
    }

    while (size < MAX_RECORDS && fscanf(file, "%d", &(*numbers)[size]) == 1) {
        size++;
        // Double the capacity if needed
        if (size >= capacity) {
            int newCapacity = capacity * 2;
            int *temp = realloc(*numbers, newCapacity * sizeof(int));
            if (!temp) {
                fprintf(stderr, "Memory allocation error\n");
                free(*numbers);
                fclose(file);
                return -1;
            }
            *numbers = temp;
            capacity = newCapacity;
        }
    }

    fclose(file);
    int *newNumbers = realloc(*numbers, size * sizeof(int));
    if (newNumbers == NULL && size != 0) {
        fprintf(stderr, "Memory allocation error\n");
        free(*numbers);
        return -1;
    }
    *numbers = newNumbers;

    return size;
}

Record* createRecords(int numRecords) {
    Record *records = malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < numRecords; ++i) {
        records[i].type = rand() % 3;

        switch (records[i].type) {
            case OFFSET_TYPE:
                records[i].data.offset = rand();
                break;
            case KEY_TYPE:
                records[i].data.key = rand();
                break;
            case STRING_TYPE: {
                size_t len = rand() % (MAX_STR_LEN + 1);
                records[i].data.str = malloc(len + 1);
                if (records[i].data.str == NULL) {
                    fprintf(stderr, "Memory allocation error\n");
                    // Cleanup previously allocated records
                    for (int j = 0; j < i; ++j) {
                        free(records[j].data.str);
                    }
                    free(records);
                    return NULL;
                }
                memset(records[i].data.str, 'A' + rand() % 26, len); // Fill with random uppercase letters
                records[i].data.str[len] = '\0';
                break;
            }
        }
    }

    return records;
}

void freeRecords(Record *records, int numRecords) {
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].type == STRING_TYPE) {
            free(records[i].data.str);
        }
    }
    free(records);
}

int main(int argc, char **argv) {
    const char *filePath = (argc > 1) ? argv[1] : NULL;
    int *numbers = NULL;
    int numIntegers = readIntegers(&numbers, filePath);

    if (numIntegers < 0) return EXIT_FAILURE;

    Record *records = createRecords(numIntegers);
    if (records == NULL) {
        free(numbers);
        return EXIT_FAILURE;
    }

    // Example usage: Print records
    for (int i = 0; i < numIntegers; ++i) {
        switch (records[i].type) {
            case OFFSET_TYPE:
                printf("Record %d - Type: Offset, Value: %ld\n", i + 1, records[i].data.offset);
                break;
            case KEY_TYPE:
                printf("Record %d - Type: Key, Value: %d\n", i + 1, records[i].data.key);
                break;
            case STRING_TYPE:
                printf("Record %d - Type: String, Value: %s\n", i + 1, records[i].data.str);
                break;
        }
    }

    freeRecords(records, numIntegers);
    free(numbers);

    return EXIT_SUCCESS;
}
