typedef struct {
    int value;
    char *string_key;
    long *dynamic_long_ptr;
    time_t *timestamp_ptr;
} Record;

// Global mutex for thread safety.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_resources(long **offset, int **key, Record **records, time_t **timestamps, size_t record_size) {
    if (offset) free(*offset);
    if (key) free(*key);
    if (timestamps) free(*timestamps);

    for (size_t i = 0; i < record_size; ++i) {
        if (records && records[i]) {
            if (records[i]->string_key) free(records[i]->string_key);
            if (records[i]->dynamic_long_ptr) free(records[i]->dynamic_long_ptr);
            if (records[i]->timestamp_ptr) free(records[i]->timestamp_ptr);
            free(records[i]);
        }
    }
}

int initialize_memory(long **offset, int **key, Record ***records, time_t **timestamps, size_t offset_size, 
                      size_t key_size, size_t record_size, unsigned int seed, void (*callback)(Record *)) {

    if (seed > MAX_SEED) {
        log_error("Invalid seed value.");
        return -1;
    }

    // Initialize random library with custom seed.
    if (!random_library_initialize(seed)) {
        log_error("Random library initialization failed.");
        return -2;
    }

    pthread_mutex_lock(&lock);

    *offset = (long *)malloc(offset_size * sizeof(long));
    *key = (int *)malloc(key_size * sizeof(int));
    *timestamps = (time_t *)malloc(record_size * sizeof(time_t));
    *records = (Record **)malloc(record_size * sizeof(Record *));

    if (!*offset || !*key || !*timestamps || !*records) {
        log_error("Memory allocation failed.");
        free_resources(offset, key, *records, timestamps, record_size);
        pthread_mutex_unlock(&lock);
        return -3;
    }

    for (size_t i = 0; i < offset_size; ++i) (*offset)[i] = i;
    for (size_t i = 0; i < key_size; ++i) (*key)[i] = i;

    for (size_t i = 0; i < record_size; ++i) {
        time(&(*timestamps)[i]);

        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            log_error("Memory allocation for a record failed.");
            free_resources(offset, key, *records, timestamps, record_size);
            pthread_mutex_unlock(&lock);
            return -4;
        }

        record->value = random_library_generate(RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);

        const size_t string_key_length = 10; // Example length.
        record->string_key = (char *)malloc(string_key_length * sizeof(char));
        if (!record->string_key) {
            log_error("Memory allocation for a string key failed.");
            free(record);
            free_resources(offset, key, *records, timestamps, record_size);
            pthread_mutex_unlock(&lock);
            return -5;
        }

        snprintf(record->string_key, string_key_length, "Key_%zu", i);

        record->dynamic_long_ptr = (long *)malloc(sizeof(long));
        if (!record->dynamic_long_ptr) {
            log_error("Memory allocation for dynamic long failed.");
            free(record->string_key);
            free(record);
            free_resources(offset, key, *records, timestamps, record_size);
            pthread_mutex_unlock(&lock);
            return -6;
        }

        record->timestamp_ptr = (time_t *)malloc(sizeof(time_t));
        if (!record->timestamp_ptr) {
            log_error("Memory allocation for timestamp failed.");
            free(record->dynamic_long_ptr);
            free(record->string_key);
            free(record);
            free_resources(offset, key, *records, timestamps, record_size);
            pthread_mutex_unlock(&lock);
            return -7;
        }

        memcpy(record->timestamp_ptr, &(*timestamps)[i], sizeof(time_t));

        (*records)[i] = record;

        if (callback) {
            callback(record);
        }

        log_info("Record initialized successfully.");
    }

    pthread_mutex_unlock(&lock);

    return 0; // Success.
}
