    int keyIndex;
    int offsetIndex;
    char *value;  // This could be any type depending on your use case
} Record;

// Function to dynamically allocate and initialize memory for records
void* createRecords(int numKeys, const char **keys, int numOffsets, const char **offsets) {
    if (numKeys <= 0 || numOffsets <= 0) return NULL;

    // Allocate memory for keys and offsets arrays
    char **keyArray = malloc(numKeys * sizeof(char *));
    char **offsetArray = malloc(numOffsets * sizeof(char *));
    if (!keyArray || !offsetArray) {
        free(keyArray);
        free(offsetArray);
        return NULL;
    }

