#include <stdint.h>

typedef struct {
    char id[37]; // UUID string length + null terminator
    char description[256];
    int priority;
    time_t deadline;
} Project;

typedef struct {
    Project *projects;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ProjectList;

void init_random_seed(unsigned int seed) {
    srand(seed);
}

int generate_random_priority(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Project* create_project(const char *description, time_t deadline, int min_priority, int max_priority) {
    Project *project = malloc(sizeof(Project));
    if (!project) return NULL;

    uuid_generate_random((uuid_t *)project->id);
    project->id[36] = '\0';
    strncpy(project->description, description, sizeof(project->description) - 1);
    project->priority = generate_random_priority(min_priority, max_priority);
    project->deadline = deadline;

    return project;
}

int initialize_project_list(ProjectList *list, size_t initial_capacity, unsigned int seed) {
    pthread_mutex_init(&list->lock, NULL);

    list->projects = malloc(initial_capacity * sizeof(Project));
    if (!list->projects) return -1;

    list->capacity = initial_capacity;
    list->count = 0;

    init_random_seed(seed);
    return 0;
}

int add_project(ProjectList *list, const char *description, time_t deadline, int min_priority, int max_priority, void (*callback)(Project*)) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Project *new_projects = realloc(list->projects, new_capacity * sizeof(Project));
        if (!new_projects) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->projects = new_projects;
        list->capacity = new_capacity;
    }

    Project *project = create_project(description, deadline, min_priority, max_priority);
    if (!project) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->projects[list->count++] = *project;

    if (callback) callback(project);

    pthread_mutex_unlock(&list->lock);
    free(project); // Free the temporary allocation
    return 0;
}

void mark_project_complete(ProjectList *list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index < list->count) {
        memset(&list->projects[index], 0, sizeof(Project)); // Simple way to mark as complete
    }

    pthread_mutex_unlock(&list->lock);
}

void free_project_list(ProjectList *list) {
    pthread_mutex_lock(&list->lock);

    free(list->projects);
    list->projects = NULL;
    list->capacity = 0;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void validate_project_list(ProjectList *list) {
    // Placeholder for validation logic
    printf("Validating project list...\n");
}

int main() {
    ProjectList list;
    if (initialize_project_list(&list, 10, time(NULL)) != 0) {
        fprintf(stderr, "Failed to initialize project list.\n");
        return EXIT_FAILURE;
    }

    add_project(&list, "Project A", time(NULL) + 86400, 1, 5, NULL);
    mark_project_complete(&list, 0);

    validate_project_list(&list);
    free_project_list(&list);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Resizing**: Automatically resizes the project list when needed.
- **Random Priority and UUIDs**: Uses `rand()` for priority and `uuid` library for unique IDs.
- **Thread Safety**: Utilizes `pthread_mutex_t` to ensure thread safety.
- **Memory Management**: Frees memory upon exit with `free_project_list`.
- **Error Handling**: Handles allocation failures gracefully.
- **Callback Functionality**: Allows custom processing after project initialization.
- **Project Completion**: Marks projects as complete by zeroing out their data.

This code provides a robust starting point for managing a dynamic list of projects in C, ensuring efficient memory usage and thread safety.']

