typedef struct {
    int value;
    char key[256];
    long *dynamic_long;
    time_t creation_time;
    char metadata[256];
} record;

// Global seed for reproducibility
static unsigned long global_seed = 0;

void set_seed(unsigned long seed) {
    global_seed = seed;
}

int initialize_data_structures(long offsets[], int keys[], record records[], timestamp timestamps[], char *metadata_pool[]) {
    // Initialize offsets and keys with sequential numbers starting from 0.
    for (int i = 0; i < OFFSET_SIZE; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Seed the random number generator
    srand(global_seed);

    // Allocate and initialize records
    for (int i = 0; i < RECORD_SIZE; ++i) {
        records[i].value = rand() % RANDOM_RANGE_MAX;

        char key_template[] = "key_XXXX";
        snprintf(records[i].key, sizeof(records[i].key), key_template, i);

        records[i].dynamic_long = malloc(sizeof(long));
        if (!records[i].dynamic_long) {
            fprintf(stderr, "Memory allocation failed for dynamic long\n");
            return -1;
        }

        *records[i].dynamic_long = offsets[i];

        records[i].creation_time = time(NULL);

        // Assign metadata from pool
        snprintf(records[i].metadata, sizeof(records[i].metadata), "meta_%d", i % METADATA_POOL_SIZE);

        timestamps[i] = records[i].creation_time;
    }

    // Initialize metadata pool
    for (int i = 0; i < METADATA_POOL_SIZE; ++i) {
        metadata_pool[i] = malloc(256);
        if (!metadata_pool[i]) {
            fprintf(stderr, "Memory allocation failed for metadata\n");
            return -1;
        }
        snprintf(metadata_pool[i], 256, "metadata_string_%d", i);
    }

    // Callback function to process each record
    void (*callback)(record *) = NULL; // Define your callback logic

    // Multi-threaded processing
    pthread_t threads[RECORD_SIZE];

    for (int i = 0; i < RECORD_SIZE; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))callback, &records[i])) {
            fprintf(stderr, "Error creating thread\n");
            return -1;
        }
    }

    // Join threads
    for (int i = 0; i < RECORD_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0; // Success
}

void callback_function(record *rec) {
    // Custom logic here, e.g., modify record or log its state.
    printf("Processing record: %d\n", rec->value);
}
