static void initializeFileDescriptor(FileDescriptor *fd, const char *filename, size_t minBufferSize, FileInitCallback callback, unsigned long seed) {
    if (!fd || !filename) return;

    fd->filename = strdup(filename);
    if (!validateFilePath(fd->filename)) {
