        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&fd->lock, NULL);

    // Call the callback function
    if (callback) {
        callback(fd);
    }
}

void handleFileSystemOperations(int numFiles, size_t minBufferSize, FileInitCallback callback, unsigned long seed) {
    FileDescriptor *fds = calloc(numFiles, sizeof(FileDescriptor));
    if (!fds) {
        fprintf(stderr, "Failed to allocate memory for file descriptors\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;
    FILE *inputStream = stdin;

    while (true) {
        char filename[256];
        char content[DEFAULT_MIN_BUFFER_SIZE];

        if (!fgets(filename, sizeof(filename), inputStream) || !fgets(content, DEFAULT_MIN_BUFFER_SIZE, inputStream)) break;

        size_t nameLen = strlen(filename);
        if (filename[nameLen - 1] == '\n') filename[--nameLen] = '\0'; // Remove newline

        size_t contentLen = strlen(content);
        if (content[contentLen - 1] == '\n') content[--contentLen] = '\0';

        pthread_mutex_lock(&globalLock);

        for (int i = 0; i < numFiles; ++i) {
            if (!fds[i].filename || strcmp(fds[i].filename, "") == 0) {
                initializeFileDescriptor(&fds[i], filename, minBufferSize, callback, seed);
                strncpy(fds[i].buffer, content, fds[i].size);
                break;
            }
        }

        pthread_mutex_unlock(&globalLock);

        // Logging example
        printf("Processed file: %s\n", filename);
    }

    freeFileDescriptors(fds, numFiles);
    pthread_mutex_destroy(&globalLock);
}

int main() {
    size_t minBufferSize = DEFAULT_MIN_BUFFER_SIZE;
    handleFileSystemOperations(FILE_DESCRIPTOR_MAX_COUNT, minBufferSize, NULL, 123456789); // Example seed
    return 0;
}
