            capacity *= 2;
            Transaction *new_transactions = realloc(transactions, capacity * sizeof(Transaction));
            if (!new_transactions) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(transactions);
                return;
            }
            transactions = new_transactions;
        }
        pthread_mutex_unlock(&lock);

        // Create a transaction and check its validity
        Transaction transaction = {timestamp, transaction_id, value, 0};
        if (isValidTransaction(&transaction, config)) {
            transaction.is_valid = 1;
        }

        transactions[count++] = transaction;
    }

    double max_weighted_sum = -1.0;
    int corresponding_transaction_id = -1;

    // Calculate the maximum weighted sum among valid transactions
    for (size_t i = 0; i < count; ++i) {
        if (transactions[i].is_valid) {
            double weighted_sum = transactions[i].value * transactions[i].timestamp;
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                corresponding_transaction_id = transactions[i].transaction_id;
            }
        }
    }

    // Output the result
    printf("Max Weighted Sum: %f, Transaction ID: %d\n", max_weighted_sum, corresponding_transaction_id);

    // Free allocated memory
    free(transactions);
}

int main() {
