['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    record *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    long total_sum;
    size_t record_size;
} RecordManager;

void log_message(const char* level, const char* message) {
    // Example logging function; adjust verbosity as needed
    printf("[%s] %s\n", level, message);
}

RecordManager* init_record_manager(size_t capacity, size_t record_size, long target_sum) {
    if (capacity == 0 || record_size == 0) {
        log_message("ERROR", "Invalid input parameters.");
        return NULL;
    }

    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) {
        log_message("ERROR", "Failed to allocate memory for manager.");
        return NULL;
    }

    manager->array = calloc(capacity, record_size);
    if (!manager->array) {
        free(manager);
        log_message("ERROR", "Failed to allocate memory for records array.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->capacity = capacity;
    manager->count = 0;
    manager->total_sum = 0;
    manager->record_size = record_size;

    log_message("INFO", "RecordManager initialized successfully.");

    // Initialize records with random values near target sum
    srand(time(NULL));
    long average_value = target_sum / capacity;
    for (size_t i = 0; i < capacity; ++i) {
        int value = rand() % (2 * record_size) + (average_value - record_size);
        if (value < 0) value = 0;

        pthread_mutex_lock(&manager->lock);
        manager->array[i].value = value;
        manager->total_sum += value;
        pthread_mutex_unlock(&manager->lock);
    }

    return manager;
}

int add_record(RecordManager *manager, int min_value, int max_value) {
    if (!manager || manager->count >= manager->capacity) {
        log_message("ERROR", "Failed to add record. Manager is null or full.");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count < manager->capacity) {
        int value = rand() % (max_value - min_value + 1) + min_value;

        // Adjust total_sum to keep it near target
        long current_total = manager->total_sum;
        long average_target = (current_total + value) / (manager->count + 1);

        if (current_total < average_target * (manager->count + 1)) {
            while (value < average_target && manager->total_sum + value > average_target * (manager->count + 1)) {
                value++;
            }
        } else {
            while (value > average_target && manager->total_sum - value < average_target * (manager->count + 1)) {
                value--;
            }
        }

        manager->array[manager->count].value = value;
        manager->total_sum += value;
        manager->count++;

        log_message("INFO", "Record added successfully.");
    } else {
        log_message("WARNING", "Attempted to add record beyond capacity, ignoring.");
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void cleanup_record_manager(RecordManager *manager) {
    if (manager) {
        free(manager->array);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
        log_message("INFO", "RecordManager cleaned up successfully.");
    }
}
```

This code provides a basic implementation for managing an array of `record` structures with concurrent access support. The `init_record_manager` function initializes the manager, allocating memory and setting up synchronization mechanisms. The `add_record` function adds records while adjusting their values to maintain the target sum constraint. Logging is done through the `log_message` function. This implementation uses a simple mutex for concurrency control, ensuring that record additions are thread-safe.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *name;
    int priority;
    time_t deadline;
} Task;

typedef struct {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TaskManager;

// Function prototypes
TaskManager* create_task_manager(size_t max_tasks);
void destroy_task_manager(TaskManager *manager);
int add_task(TaskManager *manager, const char *name, int priority, time_t deadline);
int remove_task(TaskManager *manager, const char *name);
Task* get_task_by_name(const TaskManager *manager, const char *name);
double calculate_average_priority(const TaskManager *manager);
void send_notification(const char *task_name);

// Create a new task manager with a specified maximum number of tasks
TaskManager* create_task_manager(size_t max_tasks) {
    TaskManager *manager = malloc(sizeof(TaskManager));
    if (!manager) return NULL;

    manager->tasks = calloc(max_tasks, sizeof(Task *));
    if (!manager->tasks) {
        free(manager);
        return NULL;
    }

    manager->capacity = max_tasks;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Destroy the task manager and free resources
void destroy_task_manager(TaskManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->tasks[i]->name);
        free(manager->tasks[i]);
    }
    free(manager->tasks);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Add a new task to the manager
int add_task(TaskManager *manager, const char *name, int priority, time_t deadline) {
    if (!manager || !name || priority <= 0) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Capacity reached
    }

    Task *new_task = malloc(sizeof(Task));
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->deadline = deadline;

    if (!new_task || !new_task->name) {
        free(new_task);
        pthread_mutex_unlock(&manager->lock);
        return -3; // Memory allocation failed
    }

    manager->tasks[manager->count++] = new_task;

    // Check for overdue tasks and send notifications
    time_t current_time = time(NULL);
    if (new_task->deadline < current_time) {
        send_notification(new_task->name);
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Remove a task by name
int remove_task(TaskManager *manager, const char *name) {
    if (!manager || !name) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->tasks[i]->name, name) == 0) {
            free(manager->tasks[i]->name);
            free(manager->tasks[i]);
            memmove(&manager->tasks[i], &manager->tasks[i + 1],
                    (manager->count - i - 1) * sizeof(Task *));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Task not found
}

// Retrieve a task by name
Task* get_task_by_name(const TaskManager *manager, const char *name) {
    if (!manager || !name) return NULL;

    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->tasks[i]->name, name) == 0) {
            Task *task = malloc(sizeof(Task));
            if (!task) {
                pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
                return NULL;
            }
            memcpy(task, manager->tasks[i], sizeof(Task));
            task->name = strdup(manager->tasks[i]->name);
            pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
            return task; // Task found
        }
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return NULL; // Task not found
}

// Calculate the average priority of all tasks
double calculate_average_priority(const TaskManager *manager) {
    if (!manager || manager->count == 0) return 0.0;

    double total_priority = 0;
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        total_priority += manager->tasks[i]->priority;
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return total_priority / manager->count;
}

// Send a notification for an overdue task
void send_notification(const char *task_name) {
    // Placeholder for sending notifications (e.g., email, SMS)
    printf("Notification: Task '%s' is overdue!\n", task_name);
}

// Serialization and deserialization functions can be added here

int main() {
    // Example usage of the task manager
    TaskManager *manager = create_task_manager(10);

    add_task(manager, "Task 1", 5, time(NULL) + 3600);
    add_task(manager, "Task 2", 3, time(NULL) - 3600); // Overdue

    Task *retrieved_task = get_task_by_name(manager, "Task 1");
    if (retrieved_task) {
        printf("Retrieved: %s with priority %d\n",
               retrieved_task->name, retrieved_task->priority);
        free(retrieved_task->name);
        free(retrieved_task);
    }

    double avg_priority = calculate_average_priority(manager);
    printf("Average Priority: %.2f\n", avg_priority);

    remove_task(manager, "Task 1");

    destroy_task_manager(manager);
    return 0;
}
```

This code provides a basic implementation of a task manager with thread safety using mutex locks. It includes functions to add, remove, and retrieve tasks, as well as calculate the average priority. Notifications are printed for overdue tasks. Serialization and deserialization logic would need to be implemented separately, considering data persistence requirements.']

