#include <sodium.h>  // For secure random number generation

// Define the record structure
typedef struct {
    int value;
    char key[256];
    long* offset_ptr;
} Record;

// Callback function type definition
typedef void (*RecordCallback)(const Record*);

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void processAndAnalyzeRecords(size_t record_size, size_t offset_size, size_t key_size,
                              unsigned int seed, RecordCallback callback) {
    if (sodium_init() == -1) {
        fprintf(stderr, "Failed to initialize libsodium\n");
        return;
    }

    // Initialize arrays
    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed for offsets or keys\n");
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < offset_size; ++i) offsets[i] = i;
    for (size_t i = 0; i < key_size; ++i) keys[i] = i;

    // Allocate records
    Record* records = malloc(record_size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    unsigned char buf[32];
    randombytes_buf(buf, sizeof(buf));  // Seed with secure random bytes

    for (size_t i = 0; i < record_size; ++i) {
        int value_range_min = 1;
        int value_range_max = 100;

        // Secure random number generation within range
        int rand_value = lcg_rand(value_range_min, value_range_max, buf);
        records[i].value = rand_value;
        snprintf(records[i].key, sizeof(records[i].key), "Key_%d", i);

        // Allocate and assign offset pointer
        long* offset_ptr = malloc(sizeof(long));
        if (!offset_ptr) {
            fprintf(stderr, "Memory allocation failed for record offset\n");
            continue;  // Skip this record but do not exit
        }
        *offset_ptr = offsets[i % offset_size];
        records[i].offset_ptr = offset_ptr;

        // Invoke callback function in a thread-safe manner
        if (callback) {
            pthread_mutex_lock(&lock);
            callback(&records[i]);
            pthread_mutex_unlock(&lock);
        }
    }

    // Input integers and dynamic resizing of the array
    size_t input_size = 10;
    int* inputs = malloc(input_size * sizeof(int));
    if (!inputs) {
        fprintf(stderr, "Memory allocation failed for inputs\n");
        goto cleanup;
    }

    size_t count = 0;
    while (1) {
        printf("Enter integer (-1 to stop): ");
        int num;
        scanf("%d", &num);

        if (num == -1) break;

        // Resize input array if necessary
        if (count >= input_size) {
            size_t new_size = input_size * 2;
            int* temp = realloc(inputs, new_size * sizeof(int));
            if (!temp) {
                fprintf(stderr, "Memory reallocation failed for inputs\n");
                break;  // Exit the loop on failure
            }
            inputs = temp;
            input_size = new_size;
        }

        pthread_mutex_lock(&lock);
        inputs[count++] = num;
        pthread_mutex_unlock(&lock);
    }

    printf("Max integer entered: %d\n", count > 0 ? (int)max_element(inputs, count) : -1);

cleanup:
    // Free allocated memory
    for (size_t i = 0; i < record_size; ++i)
        free(records[i].offset_ptr);
    free(records);
    free(offsets);
    free(keys);
    free(inputs);
}

// Linear congruential generator for secure random numbers within a range
int lcg_rand(int min, int max, unsigned char* seed) {
    const long a = 1664525L;
    const long c = 1013904223L;
    const long m = (1LL << 32);

    // Convert seed to an integer
    unsigned long s = *(unsigned long*)seed;

    // Generate random number using LCG
    s = (a * s + c) % m;
    return min + (s % (max - min + 1));
}

// Helper function to find the maximum element in an array
int max_element(const int* arr, size_t count) {
    if (!arr || count == 0) return -1;

    int max = arr[0];
    for (size_t i = 1; i < count; ++i)
        if (arr[i] > max) max = arr[i];

    return max;
}
```

### Notes:
- **Secure Random Generation**: The `sodium` library is used to initialize secure random number generation.
- **Thread Safety**: A mutex lock ensures thread-safe operations when accessing shared resources, like invoking the callback or modifying the input array.
- **Dynamic Resizing**: The input array doubles in size each time it fills up, minimizing reallocation overhead.
- **Memory Management**: Proper cleanup of dynamically allocated memory to prevent leaks.']

