#define INITIAL_POOL_SIZE 100

typedef struct {
    int id;
    time_t timestamp;
    int count_past_three_seconds;
    double weighted_sum;
} Transaction;

typedef void (*TransactionCallback)(Transaction*);

// Shared resource
typedef struct {
    Transaction *pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    double max_weighted_sum;
} TransactionManager;

void initialize_manager(TransactionManager *manager) {
    manager->capacity = INITIAL_POOL_SIZE;
    manager->size = 0;
    manager->max_weighted_sum = 0.0;
    manager->pool = (Transaction *)malloc(manager->capacity * sizeof(Transaction));
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_manager(TransactionManager *manager) {
    free(manager->pool);
    pthread_mutex_destroy(&manager->lock);
}

int process_transaction(TransactionManager *manager, Transaction transaction, TransactionCallback callback) {
    if (callback) {
        callback(&transaction);
    }

    // Update the running maximum weighted sum
    double new_max = fmax(transaction.weighted_sum, manager->max_weighted_sum);
    pthread_mutex_lock(&manager->lock);
    if (new_max > manager->max_weighted_sum) {
        manager->max_weighted_sum = new_max;
    }
    pthread_mutex_unlock(&manager->lock);

    // Resize pool if necessary
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Transaction *new_pool = (Transaction *)realloc(manager->pool, new_capacity * sizeof(Transaction));
        if (!new_pool) return -1; // Memory allocation failed

        pthread_mutex_lock(&manager->lock);
        manager->pool = new_pool;
        manager->capacity = new_capacity;
        pthread_mutex_unlock(&manager->lock);
    }

    // Add transaction to the pool
    pthread_mutex_lock(&manager->lock);
    manager->pool[manager->size++] = transaction;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void resolve_hostname(const char *hostname, struct in_addr *ip) {
    struct hostent *host_info = gethostbyname(hostname);
    if (host_info && host_info->h_addr_list[0]) {
        memcpy(ip, host_info->h_addr_list[0], sizeof(struct in_addr));
    } else {
        // Handle DNS resolution failure
        ip->s_addr = INADDR_NONE;
    }
}

int processTransactionsAndFindMax(int socket_fd) {
    TransactionManager manager;
    initialize_manager(&manager);

    char buffer[1024];
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    struct in_addr resolved_ip;

    while (1) {
        ssize_t bytes_received = recvfrom(socket_fd, buffer, sizeof(buffer), 0, 
                                          (struct sockaddr *)&client_addr, &addr_len);
        if (bytes_received <= 0) break; // Handle error or disconnection

        Transaction transaction;
        // Parse the received data into a Transaction struct
        // Assuming buffer contains id, timestamp, count, weighted_sum in sequence
        memcpy(&transaction.id, buffer, sizeof(transaction.id));
        memcpy(&transaction.timestamp, buffer + sizeof(transaction.id), sizeof(transaction.timestamp));
        memcpy(&transaction.count_past_three_seconds, buffer + sizeof(transaction.id) + sizeof(transaction.timestamp), sizeof(transaction.count_past_three_seconds));
        memcpy(&transaction.weighted_sum, buffer + sizeof(transaction.id) + sizeof(transaction.timestamp) + sizeof(transaction.count_past_three_seconds), sizeof(transaction.weighted_sum));

        // Resolve hostname to IP address
        char hostname[256];
        // Assume hostname is extracted from buffer
        resolve_hostname(hostname, &resolved_ip);

        if (transaction.weighted_sum < 0 || resolved_ip.s_addr == INADDR_NONE) {
            continue; // Skip invalid transactions or failed DNS resolution
        }

        process_transaction(&manager, transaction, NULL);
    }

    printf("Maximum Weighted Sum: %f\n", manager.max_weighted_sum);

    destroy_manager(&manager);
    return 0;
}
