void init_data(int offset_size, int key_size, int record_size, unsigned long seed, void (*callback)(Record*)) {
    if (offset_size <= 0 || key_size <= 0 || record_size <= 0) return;

    // Initialize random number generator
    srand(seed);

    pthread_mutex_lock(&mutex);

    // Allocate and initialize offset array
    long* offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = 0; i < offset_size; ++i) offsets[i] = i;

    // Allocate and initialize key array
    int* keys = malloc(key_size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = 0; i < key_size; ++i) keys[i] = i;

    // Allocate and initialize records
    Record* records = malloc(record_size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (int i = 0; i < record_size; ++i) {
        // Allocate memory for record fields
        records[i].value = rand() % 100; // Random number in range [0, 99]

        char* key_buffer = malloc(50 * sizeof(char));
        if (!key_buffer) {
            perror("Failed to allocate memory for record key");
            continue;
        }
        snprintf(key_buffer, 50, "key_%d", i);
        records[i].key = key_buffer;

        long* pointer_to_long_value = malloc(sizeof(long));
        if (!pointer_to_long_value) {
            perror("Failed to allocate memory for long value");
            free(key_buffer);
            continue;
        }
        *pointer_to_long_value = rand() % 1000; // Random number in range [0, 999]
        records[i].pointer_to_long = pointer_to_long_value;

        // Invoke callback function if provided
        if (callback) {
            callback(&records[i]);
        }
    }

    pthread_mutex_unlock(&mutex);

    // Clean up: This would normally be handled by the caller or a dedicated cleanup function
    free(offsets);
    free(keys);

    for (int i = 0; i < record_size; ++i) {
        if (records[i].key) free(records[i].key);
        if (records[i].pointer_to_long) free(records[i].pointer_to_long);
    }
    free(records);
}

// Example callback function
void print_record(Record* record) {
    printf("Record Value: %d, Key: %s\n", record->value, record->key);
}
