    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void *ptr) {
    if (ptr) {
        free(ptr);
    }
}

void initialize_event(EventMetadata *event, const char *identifier) {
    event->key = generate_unique_key();
    strncpy(event->identifier, identifier, sizeof(event->identifier) - 1);
    event->offset = allocate_memory(sizeof(long));
    event->timestamp = allocate_memory(sizeof(time_t));
    *event->offset = rand(); // Example initialization
    *event->timestamp = time(NULL); // Current timestamp
}

EventBuffer* create_event_buffer(size_t initial_size) {
    EventBuffer *buffer = allocate_memory(sizeof(EventBuffer));
    buffer->events = allocate_memory(initial_size * sizeof(EventMetadata));
    buffer->capacity = initial_size;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void resize_event_buffer(EventBuffer *buffer) {
    size_t new_capacity = buffer->capacity * 2;
    if (new_capacity > MAX_EVENTS) {
        fprintf(stderr, "Maximum capacity reached\n");
        exit(EXIT_FAILURE);
    }
    EventMetadata *new_events = allocate_memory(new_capacity * sizeof(EventMetadata));
    memcpy(new_events, buffer->events, buffer->count * sizeof(EventMetadata));
    free_memory(buffer->events);
    buffer->events = new_events;
    buffer->capacity = new_capacity;
}

void add_event(EventBuffer *buffer, const char *identifier, EventCallback callback) {
    pthread_mutex_lock(&buffer->mutex);

    if (buffer->count == buffer->capacity) {
        resize_event_buffer(buffer);
    }

    initialize_event(&buffer->events[buffer->count], identifier);

    if (callback) {
        callback(&buffer->events[buffer->count]);
    }

    buffer->count++;
    pthread_mutex_unlock(&buffer->mutex);
}

void destroy_event_buffer(EventBuffer *buffer) {
    for (size_t i = 0; i < buffer->count; ++i) {
        free_memory(buffer->events[i].offset);
        free_memory(buffer->events[i].timestamp);
    }
    free_memory(buffer->events);
    pthread_mutex_destroy(&buffer->mutex);
    free_memory(buffer);
}

// Example usage
