void increment_reference(DataStorage *storage) {
    atomic_fetch_add(&storage->reference_count, 1);
}

void decrement_reference(DataStorage **storage) {
    if (atomic_fetch_sub(&(*storage)->reference_count, 1) == 1) {
        cleanup_data_storage(storage);
    }
}

void cleanup_data_storage(DataStorage **storage) {
    if (!storage || !*storage) return;

    pthread_mutex_lock(&((*storage)->lock));

    for (size_t i = 0; i < (*storage)->record_size; ++i) {
        free((*storage)->record_array[i].key);
        free((*storage)->record_array[i].value);
    }

    free((*storage)->offset_array);
    free((*storage)->key_array);
    free((*storage)->record_array);

    pthread_mutex_unlock(&((*storage)->lock));

    pthread_mutex_destroy(&((*storage)->lock));

    free(*storage);
    *storage = NULL;
}

