#define MAX_RESOURCES 100
#define CACHE_SIZE 50

typedef enum { STRING, INTEGER, FLOAT } ResourceType;

typedef struct {
    char *name;
    ResourceType type;
    union {
        char *stringValue;
        int intValue;
        double floatValue;
    };
    union {
        char *currentValueString;
        int currentValueInt;
        double currentValueDouble;
    };
    unsigned long identifier;
    unsigned int version;
} Resource;

typedef struct {
    double value;
} DataChunk;

typedef struct {
    Resource resources[MAX_RESOURCES];
    DataChunk dataChunks[CACHE_SIZE];
    pthread_mutex_t lock;
    size_t resource_count;
    size_t chunk_count;
} ResourceManager;

void initializeResourceManager(ResourceManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->resource_count = 0;
    manager->chunk_count = 0;
}

void cleanupResourceManager(ResourceManager *manager) {
    for (size_t i = 0; i < manager->resource_count; ++i) {
        free(manager->resources[i].name);
        if (manager->resources[i].type == STRING) {
            free(manager->resources[i].stringValue);
            free(manager->resources[i].currentValueString);
        }
    }
    pthread_mutex_destroy(&manager->lock);
}

int addResource(ResourceManager *manager, const char *name, ResourceType type, void *defaultValue) {
    pthread_mutex_lock(&manager->lock);

    if (manager->resource_count >= MAX_RESOURCES) {
        fprintf(stderr, "Maximum resource limit reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Resource *res = &manager->resources[manager->resource_count++];
    res->name = strdup(name);
    res->type = type;
    res->identifier = rand();
    res->version = 0;

    switch (type) {
        case STRING:
            res->stringValue = strdup((char *)defaultValue);
            break;
        case INTEGER:
            res->intValue = *(int *)defaultValue;
            break;
        case FLOAT:
            res->floatValue = *(double *)defaultValue;
            break;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void *customMemoryAllocator(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

