#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "ext_rand_lib.h" // Assume this is the external library for secure random numbers

typedef struct {
    int value;
    char key[256];
    long *dynamicLongPtr;
} record;

void freeResources(record **records, size_t recordSize) {
    for (size_t i = 0; i < recordSize; ++i) {
        if (records[i] != NULL) {
            free(records[i]->dynamicLongPtr);
            free(records[i]);
        }
    }
    free(*records);
}

void processRecordsAndFindMax(size_t numOffsets, size_t numKeys, size_t numRecords, void (*callback)(record *), const char* dbConnectionStr) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int *offsets = (int *)calloc(numOffsets, sizeof(int));
    if (!offsets) { perror("Failed to allocate offsets"); exit(EXIT_FAILURE); }

    int *keys = (int *)calloc(numKeys, sizeof(int));
    if (!keys) { free(offsets); perror("Failed to allocate keys"); exit(EXIT_FAILURE); }

    for (size_t i = 0; i < numOffsets; ++i) offsets[i] = i;
    for (size_t i = 0; i < numKeys; ++i) keys[i] = i;

    record *records = (record *)calloc(numRecords, sizeof(record));
    if (!records) { free(offsets); free(keys); perror("Failed to allocate records"); exit(EXIT_FAILURE); }

    for (size_t i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&lock);

        records[i].value = ext_rand_generate(); // Assume this is the external library function
        snprintf(records[i].key, sizeof(records[i].key), "Record_%d", i);
        records[i].dynamicLongPtr = (long *)malloc(sizeof(long));
        if (!records[i].dynamicLongPtr) { 
            perror("Failed to allocate dynamic long pointer");
            freeResources(&records, numRecords);
            exit(EXIT_FAILURE); 
        }

        *records[i].dynamicLongPtr = ext_rand_generate_long(); // Another external library function

        if (callback != NULL) {
            callback(&records[i]);
        }

        pthread_mutex_unlock(&lock);
    }

    int maxInt = findMax(); // Function to read from stdin and return the max integer
    printf("Maximum Integer: %d\n", maxInt);

    freeResources(&records, numRecords);
    free(offsets);
    free(keys);
    pthread_mutex_destroy(&lock);
}

int findMax() {
    int *array = NULL;
    size_t capacity = 10;
    array = (int *)malloc(capacity * sizeof(int));
    if (!array) { perror("Failed to allocate initial array"); exit(EXIT_FAILURE); }

    size_t count = 0;
    int input;

    while (1) {
        scanf("%d", &input);
        if (input == -1) break;

        if (count >= capacity) {
            capacity *= 2;
            array = (int *)realloc(array, capacity * sizeof(int));
            if (!array) { perror("Failed to reallocate array"); exit(EXIT_FAILURE); }
        }

        array[count++] = input;
    }

    int maxInt = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > maxInt) maxInt = array[i];
    }

    free(array);
    return maxInt;
