// authenticate_and_retrieve_user.php

function authenticateAndRetrieveUser($clientId, $clientSecret, $redirectUri, $authUrl, $tokenUrl, $apiUrl) {
    session_start();

    if (!isset($_SESSION['access_token']) || isTokenExpired($_SESSION['expires_in'])) {
        $_SESSION['oauth_state'] = bin2hex(random_bytes(16));

        $authEndpoint = "$authUrl?response_type=code&client_id=$clientId&redirect_uri=" . urlencode($redirectUri) . "&state=$_SESSION[oauth_state]";
        header("Location: $authEndpoint");
        exit;
    }

    if (isset($_GET['code']) && isset($_GET['state']) && $_GET['state'] === $_SESSION['oauth_state']) {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, "$tokenUrl?grant_type=authorization_code&code=$_GET[code]&redirect_uri=" . urlencode($redirectUri) . "&client_id=$clientId&client_secret=$clientSecret");
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            error_log("CURL Error: " . curl_error($ch));
            curl_close($ch);
            return;
        }

        $data = json_decode($response, true);
        curl_close($ch);

        if (!isset($data['access_token'])) {
            error_log("Failed to obtain access token");
            return;
        }

        $_SESSION['access_token'] = $data['access_token'];
        $_SESSION['expires_in'] = time() + $data['expires_in'];

        unset($_SESSION['oauth_state']);
    } elseif (isset($_GET['error'])) {
        error_log("OAuth Error: " . $_GET['error_description']);
        return;
    }

    retrieveUserData($apiUrl, $_SESSION['access_token']);
}

function isTokenExpired($expiresIn) {
    return time() > $expiresIn;
}

function retrieveUserData($apiUrl, $accessToken) {
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, "$apiUrl?access_token=$accessToken");
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        error_log("CURL Error: " . curl_error($ch));
        curl_close($ch);
        return;
    }

    $data = json_decode($response, true);
    curl_close($ch);

    if (isset($data['error'])) {
        error_log("API Error: " . $data['error_description']);
        return;
    }

    // Process user data
}

// Example usage
authenticateAndRetrieveUser('your_client_id', 'your_client_secret', 'https://your_redirect_uri.com/callback', 'https://auth.server.com/oauth/authorize', 'https://auth.server.com/oauth/token', 'https://api.server.com/user/data');
