#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_HASH_SIZE 1024

typedef struct {
    time_t timestamp;
    int status_code;
    int *key_reference;
} entry;

typedef struct hash_node {
    int key;
    entry *entry_ptr;
    struct hash_node *next;
} hash_node;

typedef struct {
    hash_node **buckets;
    size_t size;
    pthread_mutex_t lock;
} hashtable;

void init_hashtable(hashtable *ht) {
    ht->size = INITIAL_HASH_SIZE;
    ht->buckets = calloc(ht->size, sizeof(hash_node *));
    if (!ht->buckets) exit(EXIT_FAILURE);
    pthread_mutex_init(&ht->lock, NULL);
}

unsigned long hash_function(int key, size_t size) {
    return (key * 2654435761UL) % size; // Example: FNV-1a-like hash
}

entry* create_entry(time_t timestamp, int status_code, int *key_reference) {
    entry *e = malloc(sizeof(entry));
    if (!e) exit(EXIT_FAILURE);
    e->timestamp = timestamp;
    e->status_code = status_code;
    e->key_reference = key_reference;
    return e;
}

void insert_into_hashtable(hashtable *ht, int key, entry *entry_ptr) {
    pthread_mutex_lock(&ht->lock);
    unsigned long index = hash_function(key, ht->size);
    hash_node *new_node = malloc(sizeof(hash_node));
    if (!new_node) exit(EXIT_FAILURE);

    new_node->key = key;
    new_node->entry_ptr = entry_ptr;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;

    pthread_mutex_unlock(&ht->lock);
}

entry* lookup_in_hashtable(hashtable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    unsigned long index = hash_function(key, ht->size);
    hash_node *node = ht->buckets[index];
    while (node) {
        if (node->key == key) {
            entry *entry_ptr = node->entry_ptr;
            pthread_mutex_unlock(&ht->lock);
            return entry_ptr;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void cleanup_hashtable(hashtable *ht) {
    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->size; ++i) {
        hash_node *current = ht->buckets[i];
        while (current) {
            hash_node *to_delete = current;
            current = current->next;
            free(to_delete->entry_ptr);
            free(to_delete);
        }
    }

    pthread_mutex_unlock(&ht->lock);

    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
}

void periodic_cleanup(hashtable *ht) {
    // Example: Remove entries older than a certain threshold
    time_t current_time = time(NULL);
    const int MAX_AGE = 3600; // One hour

    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->size; ++i) {
        hash_node *current = ht->buckets[i];
        while (current) {
            if (difftime(current->entry_ptr->timestamp, current_time) > MAX_AGE) {
                hash_node *to_delete = current;
                current = current->next;

                free(to_delete->entry_ptr);
                free(to_delete);
                ht->buckets[i] = current;
            } else {
                current = current->next;
            }
        }
    }

    pthread_mutex_unlock(&ht->lock);
}

int main() {
    hashtable ht;
    init_hashtable(&ht);

    // Simulate adding entries
    int key1 = 123;
    int *key_ref1 = malloc(sizeof(int));
    if (!key_ref1) exit(EXIT_FAILURE);
    *key_ref1 = key1;

    entry *e1 = create_entry(time(NULL), 200, key_ref1);
    insert_into_hashtable(&ht, key1, e1);

    // Simulate periodic cleanup
    periodic_cleanup(&ht);

    // Cleanup hashtable resources
    cleanup_hashtable(&ht);

    return 0;
}
```

This code provides a basic implementation of a thread-safe hash table with reference counting for memory management. It includes initialization, insertion, lookup, and cleanup operations while ensuring that concurrent access is handled safely using mutex locks. The periodic cleanup function removes entries older than an hour to demonstrate resource efficiency.']

