#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define INITIAL_NODE_SIZE 10
#define INITIAL_REQUEST_SIZE 10
#define HASH_TABLE_INITIAL_CAPACITY 16

typedef struct {
    char ip[16];
    int port;
    time_t last_activity;
    uint32_t load;
    uint8_t health_status; // e.g., 0: unhealthy, 1: healthy
} node;

typedef struct {
    int status;
    int bandwidth;
    int latency;
    int encryption_level;
} connection;

typedef struct request {
    char description[256];
    struct request *next;
} request;

typedef struct hashtable_entry {
    node key;
    void *value;
    struct hashtable_entry *next;
} hashtable_entry;

typedef struct {
    hashtable_entry **buckets;
    size_t capacity;
} hash_table;

typedef struct event_queue_node {
    void *event_data;
    struct event_queue_node *next;
} event_queue_node;

typedef struct {
    event_queue_node *front, *rear;
} event_queue;

// Function prototypes
void secure_random_ip(char *ip);
int secure_random_int(int min, int max);
hash_table* create_hash_table(size_t capacity);
void resize_hash_table(hash_table *table);
event_queue* create_event_queue();
void enqueue(event_queue *queue, void *data);
node** expand_node_array(node **array, size_t current_size, size_t new_size);
request** expand_request_array(request **array, size_t current_size, size_t new_size);
int** expand_int_array(int **array, size_t current_size, size_t new_size);

void processNetworkAndFindMax(size_t min_nodes, size_t max_nodes, 
                              size_t min_connections, size_t max_connections,
                              size_t min_requests, size_t max_requests,
                              void (*callback)(node *n, connection *c, request *r)) {
    if (min_nodes > max_nodes || min_connections > max_connections || min_requests > max_requests) {
        fprintf(stderr, "Invalid ranges for nodes, connections, or requests.\n");
        return;
    }

    srand(time(NULL));  // Seed the random number generator

    size_t offset_size = max_nodes;
    long *offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate offsets array");
        exit(EXIT_FAILURE);
    }

    int key_size = max_connections;
    int *keys = malloc(key_size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate keys array");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    node **nodes = malloc(INITIAL_NODE_SIZE * sizeof(node *));
    if (!nodes) {
        perror("Failed to allocate nodes array");
        free(offsets); 
        free(keys);
        exit(EXIT_FAILURE);
    }

    connection *connections = malloc(max_connections * sizeof(connection));
    if (!connections) {
        perror("Failed to allocate connections array");
        free(nodes);
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    request **requests = malloc(INITIAL_REQUEST_SIZE * sizeof(request *));
    if (!requests) {
        perror("Failed to allocate requests array");
        free(connections);
        free(nodes);
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    int **input_integers = NULL;
    size_t input_size = 0;

    hash_table *node_properties = create_hash_table(HASH_TABLE_INITIAL_CAPACITY);

    event_queue *event_queue = create_event_queue();

    // Initialize offset and key arrays
    for (size_t i = 0; i < max_nodes; ++i) {
        offsets[i] = i;
    }
    for (size_t i = 0; i < max_connections; ++i) {
        keys[i] = i;
    }

    size_t node_count = min_nodes + rand() % ((max_nodes - min_nodes) + 1);
    size_t connection_count = min_connections + rand() % ((max_connections - min_connections) + 1);
    size_t request_count = min_requests + rand() % ((max_requests - min_requests) + 1);

    // Initialize nodes
    for (size_t i = 0; i < node_count; ++i) {
        if (i >= INITIAL_NODE_SIZE) {
            nodes = expand_node_array(nodes, INITIAL_NODE_SIZE, i * 2);
        }
        nodes[i] = malloc(sizeof(node));
        if (!nodes[i]) {
            perror("Failed to allocate a node");
            // Free previous allocations
            for (size_t j = 0; j < i; ++j) free(nodes[j]);
            free(nodes);
            free(connections); 
            free(requests); 
            free(offsets);
            free(keys);
            exit(EXIT_FAILURE);
        }
        secure_random_ip(nodes[i]->ip);
        nodes[i]->port = secure_random_int(1024, 65535);
        nodes[i]->last_activity = time(NULL);
        nodes[i]->load = rand() % 100;
        nodes[i]->health_status = (rand() % 2);

        if (callback) {
            callback(nodes[i], NULL, NULL);
        }
    }

    // Initialize connections
    for (size_t i = 0; i < connection_count; ++i) {
        connections[i].status = secure_random_int(0, 1); // active or inactive
        connections[i].bandwidth = secure_random_int(100, 10000);
        connections[i].latency = secure_random_int(10, 500);
        connections[i].encryption_level = secure_random_int(1, 5);
    }

    // Initialize requests
    for (size_t i = 0; i < request_count; ++i) {
        if (i >= INITIAL_REQUEST_SIZE) {
            requests = expand_request_array(requests, INITIAL_REQUEST_SIZE, i * 2);
        }
        requests[i] = malloc(sizeof(request));
        if (!requests[i]) {
            perror("Failed to allocate a request");
            // Free previous allocations
            for (size_t j = 0; j < i; ++j) free(requests[j]);
            free(requests);
            for (size_t k = 0; k < node_count; ++k) free(nodes[k]);
            free(nodes);
            free(connections); 
            free(offsets);
            free(keys);
            exit(EXIT_FAILURE);
        }
        snprintf(requests[i]->description, sizeof(requests[i]->description), "Request %zu", i);

        if (callback) {
            callback(NULL, NULL, requests[i]);
        }

        // Linking in a simple linked list for demonstration
        requests[i]->next = requests[0];
    }

    // Read integers from standard input
    int input;
    while ((input = getchar()) != EOF && input != '-') {
        if (input == '\n') continue;

        ungetc(input, stdin);
        if (scanf("%d", &input) != 1 || input == -1) break;

        if (!input_integers) {
            input_size = 8;
            input_integers = malloc(input_size * sizeof(int *));
        }

        if (input_size == 0) {
            perror("Failed to allocate initial input integer array");
            // Free previously allocated memory
            for (size_t j = 0; j < node_count; ++j) free(nodes[j]);
            free(nodes);
            free(connections); 
            free(requests); 
            free(offsets);
            free(keys);
            exit(EXIT_FAILURE);
        }

        if (input_size <= input_count) {
            int **temp = expand_int_array(input_integers, input_size, input_size * 2);
            if (!temp) {
                perror("Failed to allocate new integer array");
                // Free previously allocated memory
                for (size_t j = 0; j < node_count; ++j) free(nodes[j]);
                free(nodes);
                free(connections); 
                free(requests); 
                free(offsets);
                free(keys);
                exit(EXIT_FAILURE);
            }
            input_integers = temp;
            input_size *= 2;
        }

        input_integers[input_count++] = malloc(sizeof(int));
        if (!input_integers[input_count - 1]) {
            perror("Failed to allocate an integer in the array");
            // Free previously allocated memory
            for (size_t j = 0; j < node_count; ++j) free(nodes[j]);
            free(nodes);
            free(connections); 
            free(requests); 
            free(offsets);
            free(keys);
            exit(EXIT_FAILURE);
        }
        *input_integers[input_count - 1] = input;
    }

    // Cleanup: Ensure proper deallocation after use
    for (size_t i = 0; i < node_count; ++i) {
        free(nodes[i]);
    }
    free(nodes);

    if (requests[0]) { // Ensuring that there was at least one request allocated
        requests[0]->next = NULL;
    }

    for (size_t i = 0; i < request_count; ++i) {
        free(requests[i]);
    }
    free(requests);

    for (size_t i = 0; i < input_count; ++i) {
        free(input_integers[i]);
    }
    if (input_integers) {
        free(input_integers);
    }

    // Additional cleanup not shown: hash_table, event_queue
}

// Helper function definitions

void secure_random_ip(char *ip) {
    snprintf(ip, sizeof(ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
}

int secure_random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

hash_table* create_hash_table(size_t capacity) {
    hash_table *table = malloc(sizeof(hash_table));
    if (!table) {
        perror("Failed to allocate hash table");
        exit(EXIT_FAILURE);
    }

    table->buckets = calloc(capacity, sizeof(hashtable_entry *));
    if (!table->buckets) {
        perror("Failed to allocate hash table buckets");
        free(table);
        exit(EXIT_FAILURE);
    }

    table->capacity = capacity;
    return table;
}

void resize_hash_table(hash_table *table) {
    size_t new_capacity = table->capacity * 2;
    hashtable_entry **new_buckets = calloc(new_capacity, sizeof(hashtable_entry *));
    if (!new_buckets) {
        perror("Failed to allocate resized hash table buckets");
        exit(EXIT_FAILURE);
    }

    // Rehashing logic omitted for brevity

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

event_queue* create_event_queue() {
    event_queue *queue = malloc(sizeof(event_queue));
    if (!queue) {
        perror("Failed to allocate event queue");
        exit(EXIT_FAILURE);
    }

    queue->front = queue->rear = NULL;
    return queue;
}

void enqueue(event_queue *queue, void *data) {
    event_queue_node *new_node = malloc(sizeof(event_queue_node));
    if (!new_node) {
        perror("Failed to allocate new node for the event queue");
        exit(EXIT_FAILURE);
    }

    new_node->event_data = data;
    new_node->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
}

node** expand_node_array(node **array, size_t current_size, size_t new_size) {
    node **new_array = realloc(array, new_size * sizeof(node *));
    if (!new_array) {
        perror("Failed to resize node array");
        exit(EXIT_FAILURE);
    }

    for (size_t i = current_size; i < new_size; ++i) {
        new_array[i] = NULL;
    }

    return new_array;
}

request** expand_request_array(request **array, size_t current_size, size_t new_size) {
    request **new_array = realloc(array, new_size * sizeof(request *));
    if (!new_array) {
        perror("Failed to resize request array");
        exit(EXIT_FAILURE);
    }

    for (size_t i = current_size; i < new_size; ++i) {
        new_array[i] = NULL;
