```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define DEFAULT_SEVERITY 1 // Assuming severity levels: 0 = info, 1 = warning, 2 = error, 3 = critical

typedef struct {
    time_t timestamp;
    int severity;
    char message[256];
    void *metadata; // Placeholder for metadata
} LogEvent;

typedef struct {
    LogEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogManager;

LogManager* initLogManager(size_t minCapacity, size_t maxCapacity) {
    LogManager *manager = malloc(sizeof(LogManager));
    manager->capacity = minCapacity;
    manager->count = 0;
    manager->events = calloc(manager->capacity, sizeof(LogEvent *));
    pthread_mutex_init(&manager->lock, NULL);
    for (size_t i = 0; i < minCapacity; ++i) {
        LogEvent *event = malloc(sizeof(LogEvent));
        event->severity = DEFAULT_SEVERITY;
        strcpy(event->message, "");
        manager->events[i] = event;
    }
    return manager;
}

void resizeLogEvents(LogManager *manager, size_t newSize) {
    pthread_mutex_lock(&manager->lock);
    LogEvent **newArray = realloc(manager->events, newSize * sizeof(LogEvent *));
    if (newArray) {
        for (size_t i = manager->count; i < newSize; ++i) {
            LogEvent *event = malloc(sizeof(LogEvent));
            event->severity = DEFAULT_SEVERITY;
            strcpy(event->message, "");
            newArray[i] = event;
        }
        manager->events = newArray;
        manager->capacity = newSize;
    } else {
        fprintf(stderr, "Memory allocation failed during resize.\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

int addLogEvent(LogManager *manager, LogEvent *event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t newSize = manager->capacity * 2;
        if (newSize > SIZE_MAX / sizeof(LogEvent *)) {
            fprintf(stderr, "Exceeded maximum capacity for log events.\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        resizeLogEvents(manager, newSize);
    }
    manager->events[manager->count++] = event;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void handleLogEvents() {
    LogManager *manager = initLogManager(10, SIZE_MAX);

    char input[512];
    while (1) {
        printf("Enter log event or 'exit' to quit: ");
        if (!fgets(input, sizeof(input), stdin)) break;

        if (strncmp(input, "exit", 4) == 0) break;

        LogEvent *event = malloc(sizeof(LogEvent));
        if (!event) {
            fprintf(stderr, "Memory allocation failed for log event.\n");
            continue;
        }

        // Basic parsing and validation
        sscanf(input, "%ld %d %[^\n]", &event->timestamp, &event->severity, event->message);
        if (strlen(event->message) == 0 || event->severity < 0 || event->severity > 3) {
            free(event);
            continue;
        }

        addLogEvent(manager, event);

        // Example prioritization: move critical events to the front
        for (size_t i = 1; i < manager->count; ++i) {
            if (manager->events[i]->severity == 3 && manager->events[i - 1]->severity < 3) {
                LogEvent *temp = manager->events[i];
                manager->events[i] = manager->events[i - 1];
                manager->events[i - 1] = temp;
            }
        }
    }

    // Cleanup
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    handleLogEvents();
    return 0;
}
```

### Key Points:
- **Initialization**: The `initLogManager` function initializes the log manager with a specified minimum capacity and sets default values for each event.
- **Dynamic Resizing**: The `resizeLogEvents` function handles resizing of the event array, doubling its size when needed.
- **Thread Safety**: Mutexes are used to ensure thread safety during concurrent access to shared resources.
- **Event Handling**: Events are read from standard input, validated, and added to the log manager. Critical events are prioritized by moving them to the front of the list.
- **Cleanup**: Resources are freed appropriately at the end of the function.

This implementation provides a scalable and efficient way to manage log events with considerations for memory usage and thread safety.']

