#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 100 // Example: 100 MB limit
#define REDUCE_PERCENTAGE 10
#define ACCESS_THRESHOLD 5

typedef struct {
    long offset;
    int key;
    double value;
    char* metadata;
    int ref_count;
    int access_frequency;
} Record;

typedef struct {
    Record** records;
    int size;
    unsigned long used_memory;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
} Collection;

static void log_error(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}

static double random_double(double min, double max) {
    return (rand() / (double)RAND_MAX) * (max - min) + min;
}

static int hash_function(int key, int size) {
    return key % size;
}

Collection* create_collection(int size) {
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) log_error("Failed to allocate memory for collection");

    collection->records = calloc(size, sizeof(Record*));
    if (!collection->records) log_error("Failed to allocate records array");

    collection->size = size;
    collection->used_memory = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_rwlock_init(&collection->rwlock, NULL);

    return collection;
}

void free_record(Record* record) {
    if (record) {
        free(record->metadata);
        free(record);
    }
}

void garbage_collect(Collection* collection) {
    pthread_rwlock_wrlock(&collection->rwlock);
    for (int i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (record && record->access_frequency < ACCESS_THRESHOLD) {
            free_record(record);
            collection->records[i] = NULL;
            collection->used_memory -= sizeof(Record) + strlen(record->metadata) + 1;
        }
    }
    pthread_rwlock_unlock(&collection->rwlock);
}

int add_record(Collection* collection, long offset, int key, char* metadata) {
    if (collection->used_memory >= MAX_MEMORY_USAGE) {
        garbage_collect(collection);
    }

    pthread_mutex_lock(&collection->lock);

    for (int i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (!record || record->key == key) break;

        int index = hash_function(key, collection->size);
        if (index != i && collection->records[index] && collection->records[index]->key == key) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
    }

    Record* record = malloc(sizeof(Record));
    if (!record) log_error("Failed to allocate memory for record");

    record->offset = offset;
    record->key = key;
    record->value = random_double(-100.0, 100.0); // Example range
    record->metadata = strdup(metadata);
    record->ref_count = 1;
    record->access_frequency = 0;

    int index = hash_function(key, collection->size);
    if (collection->records[index]) {
        free_record(collection->records[index]);
    }
    collection->records[index] = record;
    collection->used_memory += sizeof(Record) + strlen(metadata) + 1;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

Record* get_record(Collection* collection, int key) {
    pthread_rwlock_rdlock(&collection->rwlock);
    for (int i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (!record) continue;

        if (record->key == key) {
            record->access_frequency++;
            if (record->access_frequency > ACCESS_THRESHOLD) {
                printf("Warning: Record accessed more than threshold\n");
                // Reduce access limit logic here
            }
            pthread_rwlock_unlock(&collection->rwlock);
            return record;
        }
    }

    pthread_rwlock_unlock(&collection->rwlock);
    return NULL;
}

void serialize_collection(Collection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) log_error("Failed to open file for serialization");

    fwrite(&collection->size, sizeof(int), 1, file);
    pthread_rwlock_rdlock(&collection->rwlock);
    for (int i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (!record) continue;

        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->value, sizeof(double), 1, file);
        int metadata_len = strlen(record->metadata) + 1;
        fwrite(&metadata_len, sizeof(int), 1, file);
        fwrite(record->metadata, sizeof(char), metadata_len, file);
    }
    pthread_rwlock_unlock(&collection->rwlock);

    fclose(file);
}

void deserialize_collection(Collection* collection, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) log_error("Failed to open file for deserialization");

    fread(&collection->size, sizeof(int), 1, file);
    collection->records = realloc(collection->records, collection->size * sizeof(Record*));
    pthread_rwlock_wrlock(&collection->rwlock);
    for (int i = 0; i < collection->size; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) log_error("Failed to allocate memory during deserialization");

        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(double), 1, file);
        int metadata_len;
        fread(&metadata_len, sizeof(int), 1, file);
        record->metadata = malloc(metadata_len * sizeof(char));
        if (!record->metadata) log_error("Failed to allocate memory for metadata");

        fread(record->metadata, sizeof(char), metadata_len, file);
        record->offset = -1; // Default offset
        record->ref_count = 0;
        record->access_frequency = 0;

        int index = hash_function(record->key, collection->size);
        if (collection->records[index]) {
            free_record(collection->records[index]);
        }
        collection->records[index] = record;
    }
    pthread_rwlock_unlock(&collection->rwlock);

    fclose(file);
}

void cleanup_collection(Collection* collection) {
    for (int i = 0; i < collection->size; ++i) {
        free_record(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

void periodic_check(Collection* collection) {
    // Implement logic to periodically check data integrity
}

// Further implementation for real-time monitoring, multi-threaded access,
// handling of external APIs, and other advanced features would follow similar patterns.

int main() {
    srand(time(NULL));

    Collection* collection = create_collection(100);
    add_record(collection, 1L, 42, "Sample metadata");
    Record* record = get_record(collection, 42);

    if (record) {
        printf("Record found: key=%d, value=%.2f\n", record->key, record->value);
    }

    serialize_collection(collection, "records.dat");
    Collection* new_collection = create_collection(100);
    deserialize_collection(new_collection, "records.dat");

    cleanup_collection(collection);
    cleanup_collection(new_collection);

    return 0;
}
