```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <openssl/rand.h>

#define MAX_RECORDS 1024
#define MIN_RANDOM_VALUE 0
#define MAX_RANDOM_VALUE 100

typedef struct {
    int value;
} Record;

pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void initArray(int *array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        array[i] = i;
    }
}

int secureRandomNumber(int min, int max) {
    int range = max - min + 1;
    unsigned char buf[4];
    if (RAND_bytes(buf, sizeof(buf)) != 1) {
        fprintf(stderr, "Error generating random number.\n");
        exit(EXIT_FAILURE);
    }

    uint32_t rnd_num = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
    return min + (rnd_num % range);
}

void logCreation(const char *message, int fd) {
    pthread_mutex_lock(&log_lock);
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    dprintf(fd, "[%02d:%02d:%02d] %s\n", tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
    pthread_mutex_unlock(&log_lock);
}

Record* createRecords(size_t size) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&record_lock);
        records[i].value = secureRandomNumber(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
        logCreation("Record created", STDOUT_FILENO); // Replace with actual file descriptor if needed
        pthread_mutex_unlock(&record_lock);
    }

    return records;
}

void freeRecords(Record *records) {
    free(records);
}

int findMaxInRecords(const Record *records, size_t size) {
    int max_value = MIN_RANDOM_VALUE - 1;
    for (size_t i = 0; i < size; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

void *threadSafeRecordInit(void *arg) {
    Record *records = (Record *) arg;
    size_t half_size = MAX_RECORDS / 2;

    for (size_t i = 0; i < half_size; ++i) {
        pthread_mutex_lock(&record_lock);
        records[i].value = secureRandomNumber(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
        logCreation("Record created in thread", STDOUT_FILENO); // Replace with actual file descriptor if needed
        pthread_mutex_unlock(&record_lock);
    }

    return NULL;
}

int processRecordsAndFindMax(int fd) {
    int seed = time(NULL);

    srand(seed);
    RAND_seed((const unsigned char*)&seed, sizeof(seed));

    int offset[MAX_RECORDS], key[MAX_RECORDS];
    initArray(offset, MAX_RECORDS);
    initArray(key, MAX_RECORDS);

    Record *records = createRecords(MAX_RECORDS);

    pthread_t threads[2];
    pthread_create(&threads[0], NULL, threadSafeRecordInit, records);
    pthread_create(&threads[1], NULL, threadSafeRecordInit, &records[MAX_RECORDS / 2]);

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    int max_value = findMaxInRecords(records, MAX_RECORDS);

    freeRecords(records);

    dprintf(fd, "Max value found: %d\n", max_value);
    return max_value;
}

int main() {
    const char *log_file_path = "logfile.txt";
    int log_fd = open(log_file_path, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    processRecordsAndFindMax(log_fd);

    close(log_fd);
    return 0;
}
```

