// Assuming an external library for secure random number generation is included here.
extern void secure_random_init(unsigned int seed);
extern unsigned int secure_random(void);

typedef struct {
    char *ip_address;
    int port;
    time_t last_activity;
    char *buffer;
    size_t buffer_size;
    size_t used_buffer_size;
    int connection_status; // 0: inactive, 1: active
} ConnectionState;

#define INITIAL_BUFFER_SIZE 128
#define GROWTH_FACTOR 2

typedef void (*InitCallback)(ConnectionState*);

void manageNetworkConnections(ConnectionState *connections, size_t num_connections, unsigned int seed, InitCallback callback) {
    if (!connections || !callback) return;

    secure_random_init(seed);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_connections; ++i) {
        connections[i].ip_address = NULL;
        connections[i].port = 0;
        connections[i].last_activity = time(NULL);
        connections[i].buffer_size = INITIAL_BUFFER_SIZE;
        connections[i].used_buffer_size = 0;
        connections[i].connection_status = 0;

        // Allocate initial buffer
        pthread_mutex_lock(&mutex);
        connections[i].buffer = (char *)malloc(connections[i].buffer_size);
        if (!connections[i].buffer) {
            perror("Failed to allocate memory for connection buffer");
            continue; // Skip this connection on failure
        }
        memset(connections[i].buffer, 0, connections[i].buffer_size);
        pthread_mutex_unlock(&mutex);

        // Initialize with random idle timeout and other parameters if needed
        unsigned int random_value = secure_random();
        // Example usage of the random value (e.g., setting an idle timeout)

        callback(&connections[i]);
    }

    // Ensure thread safety for concurrent access
    for (size_t i = 0; i < num_connections; ++i) {
        pthread_mutex_lock(&mutex);
        if (!connections[i].buffer_size || !connections[i].buffer) {
            perror("Invalid buffer state detected");
            continue;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Logging mechanism example
    for (size_t i = 0; i < num_connections; ++i) {
        printf("Connection initialized: IP=%s, Port=%d\n", connections[i].ip_address ? connections[i].ip_address : "N/A", connections[i].port);
    }
}

void freeConnections(ConnectionState *connections, size_t num_connections) {
    if (!connections) return;

    for (size_t i = 0; i < num_connections; ++i) {
        pthread_mutex_lock(&mutex); // Ensure thread-safe access
        if (connections[i].buffer) {
            free(connections[i].buffer);
            connections[i].buffer = NULL;
            connections[i].buffer_size = 0;
            connections[i].used_buffer_size = 0;
        }
        pthread_mutex_unlock(&mutex);
    }
}

// Example callback function
void defaultInitCallback(ConnectionState *state) {
    // Set a random idle timeout or other initialization logic here
    state->port = secure_random() % 65535; // Random port for example purposes
}
