    if (!*inputArray) return -1;

    int count = 0, input;
    while (scanf("%d", &input) == 1 && input != -1) {
        if (count >= bufferSize) {
            bufferSize *= 2;
            *inputArray = realloc(*inputArray, bufferSize * sizeof(int));
            if (!*inputArray) return -1;
        }
        (*inputArray)[count++] = input;
    }

    *arraySize = count;
    return 0;
}

void processRecordsAndFindMax(size_t offsetSize, size_t keySize, size_t recordSize, unsigned long seed) {
