    }

    cleanupResources(offsetSize, keySize, recordArray, recordSize);
    free(offsetArray);
    free(keyArray);

    // Initialize semaphore for thread-safe operations
    sem_init(&semaphore, 0, MAX_THREADS);
}

int findMax(const int *array, size_t arraySize) {
    if (arraySize == 0)
        return -1;

    int max = array[0];
    for (size_t i = 1; i < arraySize; ++i)
        if (array[i] > max)
            max = array[i];

    return max;
}

void *threadFunction(void *arg) {
