            }, { once: true });
          }
        }
      }
    } catch (error) {
      console.error('Error refreshing fields:', error);
    }
  }

  insertAfterFieldNames(targetFieldName, forwardList) {
    const index = forwardList.indexOf(targetFieldName);

    if (index !== -1 && index < forwardList.length - 1) {
      forwardList.splice(index + 1, 0, targetFieldName);
    } else {
      forwardList.push(targetFieldName);
    }
  }

  // Utility function to test the insertion logic
  static insertAfter(fieldNames, first, second) {
    const index = fieldNames.indexOf(first);

    if (index !== -1 && index < fieldNames.length - 1) {
      fieldNames.splice(index + 1, 0, second);
    } else {
      fieldNames.push(second);
    }

    return fieldNames;
  }
});

