#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming an external library provides this function for secure random number generation.
extern int secure_random_int(int min, int max);

typedef struct {
    int value;
    char key[50];
    long *longPtr;
} record;

int findMax(const int* array, size_t size) {
    if (array == NULL || size <= 0) return INT_MIN;

    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void processRecordsAndFindMax(size_t maxRecords, void (*callback)(record*), int minVal, int maxVal) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    record *records = malloc(maxRecords * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return;
    }

    int *offset = calloc(maxRecords, sizeof(int));
    char *keyArray = malloc(maxRecords * 50);
    if (!offset || !keyArray) {
        perror("Failed to allocate memory for offset or keyArray");
        free(records);
        free(offset);
        free(keyArray);
        return;
    }

    int usedValues[maxRecords];
    memset(usedValues, -1, sizeof(usedValues));

    for (size_t i = 0; i < maxRecords; ++i) {
        pthread_mutex_lock(&lock);

        int value;
        do {
            value = secure_random_int(minVal, maxVal);
        } while (findMax(usedValues, maxRecords) == value);

        records[i].value = value;
        usedValues[i] = value;
        snprintf(records[i].key, 50, "Key%d", i);
        records[i].longPtr = malloc(sizeof(long));
        if (!records[i].longPtr) {
            perror("Failed to allocate memory for longPtr");
            pthread_mutex_unlock(&lock);
            continue; // Skip this record on failure
        }

        *records[i].longPtr = (long)value;

        if (callback) callback(&records[i]);

        pthread_mutex_unlock(&lock);
    }

    free(offset);
    free(keyArray);

    int inputSize = 10;
    int *inputArray = malloc(inputSize * sizeof(int));
    if (!inputArray) {
        perror("Failed to allocate memory for inputArray");
        free(records);
        return;
    }

    size_t currentInputSize = 0;

    printf("Enter integers (enter -1 to finish):\n");

    while (1) {
        int input;
        scanf("%d", &input);

        if (input == -1) break;

        if (currentInputSize >= inputSize) {
            inputSize *= 2;
            inputArray = realloc(inputArray, inputSize * sizeof(int));
            if (!inputArray) {
                perror("Failed to reallocate memory for inputArray");
                return;
            }
        }

        inputArray[currentInputSize++] = input;
    }

    int maxInputValue = findMax(inputArray, currentInputSize);
    printf("Largest integer entered: %d\n", maxInputValue);

    free(inputArray);

    // Free all allocated records resources
    for (size_t i = 0; i < maxRecords; ++i) {
        if (records[i].longPtr) {
            free(records[i].longPtr);
        }
    }

    free(records);
