        // Allocate memory for the log message and timestamp
        logs[i].message = strdup(message);
        logs[i].timestamp = malloc(sizeof(int));
        if (!logs[i].message || !logs[i].timestamp) {
            perror("Memory allocation failed");
            cleanupResources(logs, timestamps, i);
            pthread_exit(NULL);
        }

        // Set log level and timestamp
        logs[i].level = ERROR;
        *logs[i].timestamp = timestamps[i % TIME_INTERVALS];
    }

    // Analyze error frequency
    analyzeErrorFrequency(logs, log_count);

    // Send logs to external service every 30 seconds
    while (1) {
        pthread_mutex_lock(&lock);
        sendLogsToExternalService(logs, log_count, NULL);
        pthread_mutex_unlock(&lock);
        sleep(30); // Simulate network call delay
    }

    cleanupResources(logs, timestamps, log_count);
    pthread_exit(NULL);
}

int generateRandomErrorCode() {
