<?php

// Load Composer autoloader
require_once __DIR__ . '/vendor/autoload.php';

use Psr\Log\LoggerInterface;
use Psr\Log\NullLogger;

class ConfigManager {
    private $config = [];
    private $logger;

    public function __construct(LoggerInterface $logger = null) {
        $this->logger = $logger ?: new NullLogger();

        // Set environment variables from user input
        $this->setEnvironmentVariables();

        // Load and merge configurations
        $this->loadConfigurations();

        // Log initial configuration load
        $this->log('Configuration loaded successfully.');
    }

    private function setEnvironmentVariables() {
        if (isset($_SERVER['USER_ENV'])) {
            putenv("APP_ENV=" . $_SERVER['USER_ENV']);
        } else {
            $defaultEnv = getenv('APP_ENV') ?: 'production';
            putenv("APP_ENV=$defaultEnv");
        }
    }

    private function loadConfigurations() {
        // Load global configuration
        $this->config = include(__DIR__ . '/config/global.php');

        // Environment-specific configuration
        $environment = getenv('APP_ENV');
        if ($environment && file_exists(__DIR__ . "/config/{$environment}.php")) {
            $envConfig = include(__DIR__ . "/config/{$environment}.php");
            $this->config = array_merge($this->config, $envConfig);
        }

        // Override with runtime configuration
        if (file_exists(__DIR__ . '/runtime_config.php')) {
            $runtimeConfig = include(__DIR__ . '/runtime_config.php');
            $this->config = array_merge($this->config, $runtimeConfig);
        }
    }

    public function getConfig() {
        return $this->config;
    }

    private function log($message) {
        $this->logger->info($message);
    }

    // Handle dynamic configuration updates
    public function updateConfigFromExternalSource($sourceUrl) {
        try {
            if (filter_var($sourceUrl, FILTER_VALIDATE_URL)) {
                $response = file_get_contents($sourceUrl);

                if ($response !== false) {
                    $externalConfig = json_decode($response, true);
                    if (!is_null($externalConfig)) {
                        $this->config = array_merge($this->config, $externalConfig);
                        $this->log('Configuration updated from external source.');
                    }
                } else {
                    throw new Exception('Failed to fetch configuration from the external source.');
                }
            } else {
                throw new InvalidArgumentException('Invalid URL for external configuration source.');
            }
        } catch (Exception $e) {
            $this->logger->error($e->getMessage());
            // Fallback mechanism: use default configurations
        }
    }

    public function handleConfigurationIssue() {
        try {
            // Simulate a potential issue in config loading or processing
        } catch (Exception $e) {
            $this->log('Error handling configuration: ' . $e->getMessage());
            // Graceful fallback to ensure the application continues running
        }
    }

    public function ensureBackwardCompatibility($newConfig) {
        // Logic for checking backward compatibility with existing configurations
    }
}

// Instantiate ConfigManager and set up logging
