// Main function to manage the transaction stream and message queue.
long manageTransactionStreamAndMessageQueue(Config config) {
    pthread_mutex_init(&lock, NULL);

    // Initialize arrays with specific sizes.
    size_t array_size = 10;
    long* timestamps = malloc(array_size * sizeof(long));
    int* ids = malloc(array_size * sizeof(int));
    char*** messages = malloc(array_size * sizeof(char**));

    if (!timestamps || !ids || !messages) {
        freeResources(NULL, &messages, array_size);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    initializeArrays(timestamps, ids, messages, array_size, "Default Message");

    // Seed for reproducibility.
    srand(42);

    // Read input lines until sentinel value is encountered.
    char line[256];
    long max_weighted_sum = 0;
    int corresponding_id = -1;

    while (fgets(line, sizeof(line), stdin)) {
        if (strncmp(line, "END", 3) == 0) break;

        Transaction* transaction = processInputLine(line, config);
        if (!transaction) continue;

        pthread_mutex_lock(&lock);

        // Resize arrays if necessary.
        if (sizeof(timestamps) / sizeof(long) <= array_size) {
            size_t new_size = array_size * 2;
            long* new_timestamps = realloc(timestamps, new_size * sizeof(long));
            int* new_ids = realloc(ids, new_size * sizeof(int));
            char*** new_messages = realloc(messages, new_size * sizeof(char**));

            if (!new_timestamps || !new_ids || !new_messages) {
                freeResources(&transaction, &messages, array_size);
                pthread_mutex_unlock(&lock);
                pthread_mutex_destroy(&lock);
                return -1;
            }

            timestamps = new_timestamps;
            ids = new_ids;
            messages = new_messages;
        }

        // Store transaction data.
        *timestamps++ = transaction->timestamp;
        *ids++ = transaction->transaction_id;
        char* message_copy = strdup(transaction->message);
        if (!message_copy) {
            free(transaction);
            pthread_mutex_unlock(&lock);
            continue;
        }
        *messages++ = &message_copy;

        // Call the callback function for additional processing.
        messageCallback(message_copy);

        // Check validity and calculate weighted sum.
        if (isValidTransaction(transaction, config)) {
            long weighted_sum = transaction->timestamp + transaction->value;
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                corresponding_id = transaction->transaction_id;
            }
        }

        free(transaction);
        pthread_mutex_unlock(&lock);

        array_size++;
    }

    // Free allocated resources.
    freeResources((Transaction**)timestamps, &messages, array_size - (sizeof(timestamps) / sizeof(long)));

    pthread_mutex_destroy(&lock);

    return max_weighted_sum;
}

