// Global variables for monitoring and configuration
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile size_t record_count = 0;
static volatile time_t last_minute_mark = 0;
static Config config;

// Function prototypes
void* processStreamAndComputeMax(void* arg);
void monitorThroughput();
void logMessage(int severity, const char *message);

// Random number generator (mock)
int randomInRange(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Callback function prototype
typedef void (*RecordCallback)(const Record*);

void* processStreamAndComputeMax(void* arg) {
    if (!arg) return NULL;

    Config *cfg = (Config*)arg;
    memcpy(&config, cfg, sizeof(Config));

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void*)monitorThroughput, NULL);

    RecordCallback record_callback = NULL; // Define or assign your callback function
    size_t current_size = 0;
    size_t capacity = 10;
    Record *records = malloc(capacity * sizeof(Record));
    if (!records) {
        logMessage(1, "Memory allocation failed for records array.");
        return NULL;
    }

    int max_value = INT_MIN;

    while (1) {
        // Simulate reading from a non-blocking stream
        sleep(rand() % 3); // Random delay to simulate varying input frequency

        if (current_size == capacity) {
            capacity *= 2;
            records = realloc(records, capacity * sizeof(Record));
            if (!records) {
                logMessage(1, "Memory reallocation failed for records array.");
                break;
            }
        }

        int new_value = randomInRange(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
        records[current_size].value = new_value;
        snprintf(records[current_size].key, sizeof(records[current_size].key), "Record %zu", current_size);
        records[current_size].dynamic_value = malloc(sizeof(long));
        if (!records[current_size].dynamic_value) {
            logMessage(1, "Memory allocation failed for dynamic value.");
            continue; // Skip this record
        }
        *(records[current_size].dynamic_value) = new_value;

        max_value = (new_value > max_value) ? new_value : max_value;
        current_size++;

        if (record_callback) {
            record_callback(&records[current_size - 1]);
        }

        pthread_mutex_lock(&mutex);
        record_count++;
        pthread_mutex_unlock(&mutex);

        // Rate limiting
        if (config.enable_rate_limiting) {
            usleep(100000); // Sleep for 100ms to simulate rate limiting
        }
    }

    free(records);

    return NULL;
}

void monitorThroughput() {
    while (1) {
        sleep(60);
        pthread_mutex_lock(&mutex);
        size_t current_count = record_count;
        time_t current_time = time(NULL);

        if (current_time != last_minute_mark) {
            logMessage(0, "Records processed in the last minute: %zu", current_count);
            if (config.enable_logging && current_count > config.throughput_threshold) {
                logMessage(1, "Throughput threshold exceeded!");
            }
            record_count = 0;
            last_minute_mark = current_time;
        }

        pthread_mutex_unlock(&mutex);
    }
}

void logMessage(int severity, const char *message) {
    if (!config.enable_logging) return;

    time_t now = time(NULL);
    printf("[%s] [%d] %s\n", ctime(&now), severity, message);
}
