LogEntry** processLogsAndAggregateStats(size_t logSize, time_t startTimestamp, void (*preprocess)(LogEntry*), pthread_mutex_t *lock) {
    LogEntry **logEntries = NULL;
    size_t currentSize = 0;

    // Initialize timestamps
    time_t timestamps[logSize];
    for (size_t i = 0; i < logSize; ++i) {
        timestamps[i] = startTimestamp + i;
    }

    // Allocate and initialize log entries array
    logEntries = malloc(logSize * sizeof(LogEntry *));
    if (!logEntries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    currentSize = logSize;

    for (size_t i = 0; i < logSize; ++i) {
        logEntries[i] = malloc(sizeof(LogEntry));
        if (!logEntries[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated entries
            while (i > 0) free(logEntries[--i]);
            free(logEntries);
            return NULL;
        }

        logEntries[i]->timestamp = timestamps[i];
        logEntries[i]->status = -1; // Default status code
        logEntries[i]->message = strdup("Default message");
        logEntries[i]->stats = malloc(sizeof(Stats));
        if (!logEntries[i]->stats) {
            fprintf(stderr, "Memory allocation failed\n");
            free(logEntries[i]);
            while (i > 0) free(logEntries[--i]);
            free(logEntries);
            return NULL;
        }
    }

    // Continuously read log entries
    char inputBuffer[256];
    while (fgets(inputBuffer, sizeof(inputBuffer), stdin)) {
        if (currentSize == logSize) {
            logSize *= 2;
            LogEntry **newLogEntries = realloc(logEntries, logSize * sizeof(LogEntry *));
            if (!newLogEntries) {
                fprintf(stderr, "Memory allocation failed\n");
                break;
            }
            logEntries = newLogEntries;

            for (size_t i = currentSize; i < logSize; ++i) {
                logEntries[i] = malloc(sizeof(LogEntry));
                if (!logEntries[i]) {
                    fprintf(stderr, "Memory allocation failed\n");
                    while (i > currentSize) free(logEntries[--i]);
                    break;
                }

                logEntries[i]->timestamp = time(NULL);
                logEntries[i]->status = -1; // Default status code
                logEntries[i]->message = strdup("Default message");
                logEntries[i]->stats = malloc(sizeof(Stats));
                if (!logEntries[i]->stats) {
                    fprintf(stderr, "Memory allocation failed\n");
                    free(logEntries[i]);
                    while (i > currentSize) free(logEntries[--i]);
                    break;
                }
            }
        }

        // Assume input is timestamp,status,message
        sscanf(inputBuffer, "%ld,%d,%255s", &timestamps[currentSize], &logEntries[currentSize]->status, logEntries[currentSize]->message);
        if (preprocess) {
            preprocess(logEntries[currentSize]);
        }
        currentSize++;
    }

    // Aggregate statistics using external library function
    Stats *aggregatedStats = NULL;
    externalAggregateStats(logEntries, currentSize, &aggregatedStats);

    // Print aggregated statistics
    printf("Count: %d\n", aggregatedStats->count);
    printf("Sum: %.2f\n", aggregatedStats->sum);
    printf("Average: %.2f\n", aggregatedStats->average);
    printf("Max: %.2f\n", aggregatedStats->max);

    // Free all allocated memory
    for (size_t i = 0; i < currentSize; ++i) {
        free(logEntries[i]->message);
        free(logEntries[i]->stats);
        free(logEntries[i]);
    }
    free(aggregatedStats);
    free(logEntries);

    return NULL;
}
