    int new_capacity = manager->capacity * 2;
    Record *new_records = realloc(manager->records, sizeof(Record) * new_capacity);
    if (new_records) {
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    pthread_mutex_unlock(&manager->lock);
}

void processRecordsAndFindMax(int seed, RecordCallback callback) {
    RecordManager manager = {NULL, 0, INITIAL_SIZE};
    pthread_mutex_init(&manager.lock, NULL);

    manager.records = malloc(sizeof(Record) * manager.capacity);
    if (!manager.records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int max_value = INT_MIN;
    while (1) {
        int input = scanf("%d", &input);
        if (input == EOF || input == 0 || input == SENTINEL) break;

        pthread_mutex_lock(&manager.lock);

        if (manager.size >= manager.capacity) {
            resize(&manager);
        }

        Record new_record;
        new_record.key = getUniqueKey(); // Handle potential failure appropriately
        new_record.value = secureRandomNumberGenerator(seed); 
        new_record.offset = rand() % 100; // Example offset

        manager.records[manager.size++] = new_record;

        if (callback) {
            callback(&new_record);
        }

        if (new_record.value > max_value) {
            max_value = new_record.value;
        }

        pthread_mutex_unlock(&manager.lock);
