['Below is a C implementation for managing a large-scale filesystem cache application based on your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_FILE_ARRAY_SIZE 100
#define INITIAL_HASH_TABLE_SIZE 50

typedef struct File {
    int id;
    size_t size;
    time_t last_access_time;
} File;

typedef struct Directory {
    char name[256];
    struct Directory *parent;
    struct Directory **children;
    int children_count;
} Directory;

typedef struct HashNode {
    char filename[256];
    File *file;
    struct HashNode *next;
} HashNode;

typedef struct LinkedListNode {
    File *file;
    struct LinkedListNode *prev, *next;
} LinkedListNode;

// Global variables for managing components
File **fileArray = NULL;
Directory **directoryArray = NULL;
HashNode **hashTable = NULL;
LinkedListNode *cacheHead = NULL, *cacheTail = NULL;
int fileArraySize = 0;
int hashTableSize = INITIAL_HASH_TABLE_SIZE;
int cacheSize = 0;

// Function declarations
void manageFilesystemAndCache(int numFiles, int numDirectories);
void initializeFiles(int numFiles);
void resizeFileArray();
void initializeDirectories(int numDirectories);
unsigned long hashFunction(const char *filename);
void insertIntoHashTable(const char *filename, File *file);
File* lookupInHashTable(const char *filename);
void addToCache(File *file);
void updateAccessTimeInCache(File *file);
void evictLRUIfNeeded();

// Main function to manage filesystem and cache
void manageFilesystemAndCache(int numFiles, int numDirectories) {
    initializeFiles(numFiles);
    initializeDirectories(numDirectories);

    // Example usage of hash table and cache
    for (int i = 0; i < fileArraySize; ++i) {
        char filename[256];
        sprintf(filename, "file_%d.txt", fileArray[i]->id);
        insertIntoHashTable(filename, fileArray[i]);
        addToCache(fileArray[i]);
    }
}

// Initialize file array
void initializeFiles(int numFiles) {
    fileArray = realloc(fileArray, sizeof(File*) * numFiles);
    for (int i = 0; i < numFiles; ++i) {
        fileArray[i] = malloc(sizeof(File));
        fileArray[i]->id = i;
        fileArray[i]->size = rand() % 1024 + 1; // Random size between 1 and 1024
        fileArray[i]->last_access_time = time(NULL);
    }
    fileArraySize = numFiles;
}

// Resize file array if needed
void resizeFileArray() {
    int newSize = fileArraySize * 2;
    File **newArray = realloc(fileArray, sizeof(File*) * newSize);
    if (newArray) {
        for (int i = fileArraySize; i < newSize; ++i) {
            newArray[i] = malloc(sizeof(File));
            newArray[i]->id = i;
            newArray[i]->size = rand() % 1024 + 1;
            newArray[i]->last_access_time = time(NULL);
        }
        fileArray = newArray;
        fileArraySize = newSize;
    } else {
        fprintf(stderr, "Failed to resize file array\n");
    }
}

// Initialize directory array
void initializeDirectories(int numDirectories) {
    directoryArray = malloc(sizeof(Directory*) * numDirectories);
    for (int i = 0; i < numDirectories; ++i) {
        directoryArray[i] = malloc(sizeof(Directory));
        snprintf(directoryArray[i]->name, sizeof(directoryArray[i]->name), "dir_%d", i);
        directoryArray[i]->parent = NULL;
        directoryArray[i]->children_count = 0;
        directoryArray[i]->children = malloc(sizeof(Directory*) * 10); // Initial capacity
    }
}

// Hash function for filenames
unsigned long hashFunction(const char *filename) {
    unsigned long hash = 5381;
    int c;
    while ((c = *filename++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % hashTableSize;
}

// Insert into hash table
void insertIntoHashTable(const char *filename, File *file) {
    unsigned long index = hashFunction(filename);
    HashNode *newNode = malloc(sizeof(HashNode));
    strcpy(newNode->filename, filename);
    newNode->file = file;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
}

// Lookup in hash table
File* lookupInHashTable(const char *filename) {
    unsigned long index = hashFunction(filename);
    HashNode *node = hashTable[index];
    while (node) {
        if (strcmp(node->filename, filename) == 0)
            return node->file;
        node = node->next;
    }
    return NULL;
}

// Add to cache
void addToCache(File *file) {
    LinkedListNode *newNode = malloc(sizeof(LinkedListNode));
    newNode->file = file;
    newNode->prev = NULL;
    newNode->next = cacheHead;

    if (cacheHead != NULL)
        cacheHead->prev = newNode;
    cacheHead = newNode;

    if (cacheTail == NULL)
        cacheTail = newNode;

    updateAccessTimeInCache(file);
    evictLRUIfNeeded();
}

// Update access time in cache
void updateAccessTimeInCache(File *file) {
    LinkedListNode *node = cacheHead;
    while (node) {
        if (node->file == file) {
            node->file->last_access_time = time(NULL);
            // Move to head if not already there
            if (node != cacheHead) {
                if (node->prev)
                    node->prev->next = node->next;
                if (node->next)
                    node->next->prev = node->prev;

                if (cacheTail == node)
                    cacheTail = node->prev;

                node->next = cacheHead;
                node->prev = NULL;
                if (cacheHead)
                    cacheHead->prev = node;
                cacheHead = node;
            }
            break;
        }
        node = node->next;
    }
}

// Evict LRU if needed
void evictLRUIfNeeded() {
    // Assume a maximum cache size for demonstration
    int maxCacheSize = 10;
    while (cacheSize > maxCacheSize) {
        LinkedListNode *nodeToEvict = cacheTail;
        if (nodeToEvict->prev)
            nodeToEvict->prev->next = NULL;
        cacheTail = nodeToEvict->prev;

        // Remove from hash table
        for (int i = 0; i < hashTableSize; ++i) {
            HashNode *current = hashTable[i];
            HashNode *prev = NULL;
            while (current) {
                if (current->file == nodeToEvict->file) {
                    if (prev)
                        prev->next = current->next;
                    else
                        hashTable[i] = current->next;

                    free(current);
                    break;
                }
                prev = current;
                current = current->next;
            }
        }

        // Remove from linked list
        free(nodeToEvict);
        cacheSize--;
    }
}

int main() {
    manageFilesystemAndCache(150, 10); // Example usage
    return 0;
}
```

This code sets up a basic framework for managing files and directories in a filesystem cache application. It includes dynamic resizing of the file array, hash table operations for metadata lookup, and an LRU cache management system using a linked list.']

