        int value;
        do {
            value = secure_random(minVal, maxVal);  // Secure random function from external library
        } while (randomSet[value] != -1);

        records[i].value = value;
        sprintf(records[i].key, "Key_%zu", i);
        if (posix_memalign((void**)&records[i].stat_ptr, 16, sizeof(long))) {
            fprintf(stderr, "Memory allocation failed\n");
