    }

    int dataPoint;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (!fscanf(stdin, "%d", &dataPoint)) {
            fprintf(stderr, "Failed to read from stream\n");
            break;  // Exit on failure
        }

        if (dataPoint == -1) break;

        if (streamSize >= streamData ? sizeof(streamData) / sizeof(int) : streamSize + 1) {
            int *newStream = realloc(streamData, (streamSize + 1) * sizeof(int));
            if (!newStream) {
                fprintf(stderr, "Failed to resize stream data array\n");
                break;
            }
            streamData = newStream;
        }

        streamData[streamSize++] = dataPoint;
        pthread_mutex_unlock(&mutex);
    }

    // Calculate and print statistical metrics
    double mean = calculateMean(streamData, streamSize);
    double median = calculateMedian((int *)malloc(streamSize * sizeof(int)), streamSize);  // Copy needed for median calculation
    int mode = calculateMode(streamData, streamSize);
    double stddev = calculateStandardDeviation(streamData, streamSize);

    printf("Mean: %f\n", mean);
    printf("Median: %f\n", median);
    printf("Mode: %d\n", mode);
    printf("Standard Deviation: %f\n", stddev);

    // Free resources
    free(records[i].stat_ptr);  // Free each stat_ptr
    free(streamData);
    pthread_mutex_destroy(&mutex);
}

