#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define DEFAULT_CAPACITY 1024
#define CACHE_LINE_SIZE 64

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} MemoryPool;

typedef struct {
    int offset[DEFAULT_CAPACITY];
    char key[DEFAULT_CAPACITY];
    int record[DEFAULT_CAPACITY];
} UserRegistry;

typedef void (*CallbackFunc)(int);

MemoryPool* create_memory_pool(size_t initial_capacity) {
    if (initial_capacity % CACHE_LINE_SIZE != 0) {
        initial_capacity = ((initial_capacity / CACHE_LINE_SIZE) + 1) * CACHE_LINE_SIZE;
    }

    MemoryPool *pool = (MemoryPool *)aligned_alloc(CACHE_LINE_SIZE, sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->data = (int *)aligned_alloc(CACHE_LINE_SIZE, initial_capacity * sizeof(int));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initial_capacity;
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->data);
        free(pool);
    }
}

int* allocate_from_pool(MemoryPool *pool, size_t count) {
    if (!pool || pool->size + count > pool->capacity) {
        size_t new_capacity = pool->capacity;
        while (new_capacity < pool->size + count) {
            new_capacity *= 2;
        }

        int *new_data = (int *)realloc(pool->data, new_capacity * sizeof(int));
        if (!new_data) return NULL;

        pool->data = new_data;
        pool->capacity = new_capacity;
    }

    int *ptr = &pool->data[pool->size];
    pool->size += count;
    return ptr;
}

void initialize_registry(UserRegistry *registry, MemoryPool *pool, CallbackFunc callback) {
    for (size_t i = 0; i < DEFAULT_CAPACITY; ++i) {
        registry->offset[i] = i;
        registry->key[i] = 'A' + (i % 26);

        int *record_ptr = allocate_from_pool(pool, 1);
        if (!record_ptr) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        record_ptr[0] = rand() % 100; // Random number in range [0, 99]
        registry->record[i] = record_ptr[0];

        if (callback) callback(registry->record[i]);
    }
}

