    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return;
    }

    UserRegistry registry = {0};
    initialize_registry(&registry, pool, callback);

    find_max_int();

    destroy_memory_pool(pool);
}

void example_callback(int value) {
    // Custom processing of each record
}

int main() {
