        const char *stringValue;
        int intValue;
        double floatValue;
    } defaultValue;
    union {
        const char *stringValue;
        int intValue;
        double floatValue;
    } currentValue;
    unsigned long id;
    unsigned int version;
} Resource;

typedef struct {
    double value;
} Chunk;

typedef struct {
    Resource **resources;
    size_t resource_count;
    size_t capacity;
    pthread_mutex_t mutex;
} ResourceManager;

typedef struct {
    Chunk *chunks;
    size_t chunk_count;
    size_t capacity;
    pthread_mutex_t mutex;
} ChunkManager;

// Function prototypes
ResourceManager* init_resource_manager(size_t initial_size);
void free_resource_manager(ResourceManager *manager);
void resize_resources_if_needed(ResourceManager *manager);

ChunkManager* init_chunk_manager(size_t initial_size);
void free_chunk_manager(ChunkManager *manager);
void resize_chunks_if_needed(ChunkManager *manager);

void add_resource(ResourceManager *manager, Resource *resource, void (*callback)(Resource *));
void update_current_value(Resource *res, const char *value_str) {
    if (strcmp(value_str, "") == 0 || value_str == NULL)
        return;
    switch (res->type) {
        case STRING:
            res->currentValue.stringValue = strdup(value_str);
            break;
        case INTEGER:
            res->currentValue.intValue = atoi(value_str);
            break;
        case FLOAT:
            res->currentValue.floatValue = atof(value_str);
            break;
    }
}

void manageDynamicResourcesAndCaching(size_t resource_size, size_t chunk_size) {
    ResourceManager *resManager = init_resource_manager(resource_size);
    ChunkManager *chunkManager = init_chunk_manager(chunk_size);

    // Example: Adding a new resource
    Resource exampleResource;
    exampleResource.name = "example";
    exampleResource.type = STRING;
    exampleResource.defaultValue.stringValue = "default";
    exampleResource.currentValue.stringValue = NULL;
    exampleResource.id = 1;
    exampleResource.version = 0;

    add_resource(resManager, &exampleResource, NULL);

    // Example: Adding a new chunk
    pthread_mutex_lock(&chunkManager->mutex);
    if (chunkManager->chunk_count >= chunkManager->capacity) {
        resize_chunks_if_needed(chunkManager);
    }
    Chunk newChunk;
    newChunk.value = 3.14;
    memcpy(&chunkManager->chunks[chunkManager->chunk_count++], &newChunk, sizeof(Chunk));
    pthread_mutex_unlock(&chunkManager->mutex);

    // Cleanup
    free_resource_manager(resManager);
    free_chunk_manager(chunkManager);
}

ResourceManager* init_resource_manager(size_t initial_size) {
    ResourceManager *manager = malloc(sizeof(ResourceManager));
    manager->resources = calloc(initial_size, sizeof(Resource *));
    manager->resource_count = 0;
    manager->capacity = initial_size;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void free_resource_manager(ResourceManager *manager) {
    for (size_t i = 0; i < manager->resource_count; ++i) {
        free(manager->resources[i]->name);
        if (manager->resources[i]->type == STRING) {
            free(manager->resources[i]->currentValue.stringValue);
        }
        free(manager->resources[i]);
    }
    free(manager->resources);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void resize_resources_if_needed(ResourceManager *manager) {
    if (manager->resource_count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Resource **new_resources = realloc(manager->resources, new_capacity * sizeof(Resource *));
        if (!new_resources) return; // Handle allocation failure gracefully
        memset(new_resources + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(Resource *));
        manager->resources = new_resources;
        manager->capacity = new_capacity;
    }
}

void add_resource(ResourceManager *manager, Resource *resource, void (*callback)(Resource *)) {
    pthread_mutex_lock(&manager->mutex);
    resize_resources_if_needed(manager);

    resource->name = strdup(resource->name); // Copy name to ensure persistence
    if (resource->type == STRING) {
        resource->currentValue.stringValue = strdup(resource->defaultValue.stringValue);
    }

    manager->resources[manager->resource_count++] = resource;
    pthread_mutex_unlock(&manager->mutex);

    if (callback) callback(resource);
}

ChunkManager* init_chunk_manager(size_t initial_size) {
    ChunkManager *manager = malloc(sizeof(ChunkManager));
    manager->chunks = calloc(initial_size, sizeof(Chunk));
    manager->chunk_count = 0;
    manager->capacity = initial_size;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void free_chunk_manager(ChunkManager *manager) {
    free(manager->chunks);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void resize_chunks_if_needed(ChunkManager *manager) {
    if (manager->chunk_count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Chunk *new_chunks = realloc(manager->chunks, new_capacity * sizeof(Chunk));
        if (!new_chunks) return; // Handle allocation failure gracefully
        memset(new_chunks + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(Chunk));
        manager->chunks = new_chunks;
        manager->capacity = new_capacity;
    }
}
