int resizeArray(void **array, size_t current_size, size_t new_size, size_t element_size) {
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) {
        handleMemoryAllocationFailure("Failed to allocate memory for array resizing");
        return -1;
    }
    *array = new_array;
    return 0;
}

void freeResources(void **array, size_t size, size_t element_size) {
    if (*array) {
        free(*array);
        *array = NULL;
    }
}

