['Here is a C code implementation outline for managing a scalable task queue system as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define MAX_CAPACITY 100

typedef struct Task {
    char *name;
    int priority;
    void (*callback)(void*);
    void* arg;
} Task;

typedef struct TaskQueue {
    Task **tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int (*comparator)(const Task *, const Task *);
} TaskQueue;

TaskQueue* init_task_queue(size_t initial_capacity, int (*comparator)(const Task*, const Task*)) {
    TaskQueue *queue = malloc(sizeof(TaskQueue));
    if (!queue) return NULL;

    queue->tasks = calloc(initial_capacity, sizeof(Task *));
    if (!queue->tasks) { free(queue); return NULL; }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    queue->comparator = comparator;

    return queue;
}

int add_task(TaskQueue *queue, Task *task) {
    if (!queue || !task || queue->size >= queue->capacity) return -1;

    pthread_mutex_lock(&queue->lock);

    for (size_t i = 0; i < queue->size; ++i) {
        if (strcmp(queue->tasks[i]->name, task->name) == 0) {
            pthread_mutex_unlock(&queue->lock);
            return -2;
        }
    }

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2 <= MAX_CAPACITY ? queue->capacity * 2 : MAX_CAPACITY;
        Task **new_tasks = realloc(queue->tasks, new_capacity * sizeof(Task *));
        if (!new_tasks) { 
            pthread_mutex_unlock(&queue->lock);
            return -3; 
        }
        memset(new_tasks + queue->capacity, 0, (new_capacity - queue->capacity) * sizeof(Task *));
        queue->tasks = new_tasks;
        queue->capacity = new_capacity;
    }

    queue->tasks[queue->size++] = task;

    pthread_cond_broadcast(&queue->cond_var);
    pthread_mutex_unlock(&queue->lock);

    return 0;
}

Task* get_task(TaskQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond_var, &queue->lock);
    }

    Task *task = queue->tasks[0];

    for (size_t i = 1; i < queue->size; ++i) {
        queue->tasks[i-1] = queue->tasks[i];
    }
    --queue->size;
    queue->tasks[queue->size] = NULL;

    pthread_mutex_unlock(&queue->lock);

    return task;
}

void free_task_queue(TaskQueue *queue) {
    if (!queue) return;

    for (size_t i = 0; i < queue->size; ++i) {
        free(queue->tasks[i]->name);
        free(queue->tasks[i]);
    }
    free(queue->tasks);

    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond_var);
    free(queue);
}

void execute_task(Task *task) {
    if (task && task->callback) {
        task->callback(task->arg);
    }
}

// Example comparator function
int priority_comparator(const Task *a, const Task *b) {
    return a->priority - b->priority;
}

// Example callback function
void sample_task(void* arg) {
    printf("Executing task with argument: %s\n", (char*)arg);
}

int main() {
    TaskQueue *queue = init_task_queue(INITIAL_CAPACITY, priority_comparator);

    for (int i = 0; i < 5; ++i) {
        Task *task = malloc(sizeof(Task));
        task->name = strdup("SampleTask");
        task->priority = rand() % 10;
        task->callback = sample_task;
        task->arg = strdup("Hello, World!");

        if (add_task(queue, task) != 0) {
            printf("Failed to add task.\n");
            free(task->name);
            free(task->arg);
            free(task);
        }
    }

    for (int i = 0; i < 5; ++i) {
        Task *task = get_task(queue);
        if (task) {
            execute_task(task);

            free(task->name);
            free(task->arg);
            free(task);
        }
    }

    free_task_queue(queue);
    return 0;
}
```

This code sets up a basic task queue system with dynamic resizing, priority-based ordering using a comparator function, and thread safety. It includes memory management for tasks and demonstrates how to add, retrieve, and execute tasks in a concurrent environment. The example also provides basic error handling and initialization cleanup.']

