    pthread_mutex_lock(&mutex);

    srand(seed); // Seed for reproducibility
    Node *nodes = malloc(size * sizeof(Node));
    if (!nodes) {
        log_event("Failed to allocate memory for nodes.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

