            return NULL;
        }

        nodes[i].data->items = malloc(num_items * sizeof(Item *));
        if (!nodes[i].data->items) {
            log_event("Failed to allocate memory for items.");
            free(nodes[i].data);
            free_nodes(&nodes, i);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        for (int j = 0; j < num_items; ++j) {
            nodes[i].data->items[j] = malloc(sizeof(Item));
            if (!nodes[i].data->items[j]) {
                log_event("Failed to allocate memory for an item.");
                for (int k = 0; k < j; ++k) {
                    free(nodes[i].data->items[k]);
                }
                free(nodes[i].data->items);
                free(nodes[i].data);
                free_nodes(&nodes, i);
                pthread_mutex_unlock(&mutex);
                return NULL;
            }

            nodes[i].data->items[j]->index = rand() % 100; // Random index
            nodes[i].data->items[j]->value = malloc(sizeof(Value));
            if (!nodes[i].data->items[j]->value) {
                log_event("Failed to allocate memory for a value.");
                free(nodes[i].data->items[j]);
                for (int k = 0; k < j; ++k) {
                    free(nodes[i].data->items[k]);
                }
                free(nodes[i].data->items);
                free(nodes[i].data);
                free_nodes(&nodes, i);
                pthread_mutex_unlock(&mutex);
                return NULL;
            }

            nodes[i].data->items[j]->value->number = (double)rand() / RAND_MAX * 100.0;
            snprintf(nodes[i].data->items[j]->value->str, sizeof(nodes[i].data->items[j]->value->str), "Value_%d", j);

            if (callback) {
                callback(*nodes[i].data->items[j]);
            }
        }
        nodes[i].data->num_items = num_items;
    }

    pthread_mutex_unlock(&mutex);
    return nodes;
}

void free_nodes(Node **nodes, int size) {
    if (!nodes || !*nodes) return;

    for (int i = 0; i < size; ++i) {
        Data *data = (*nodes)[i].data;
        if (data) {
            for (int j = 0; j < data->num_items; ++j) {
                Item *item = data->items[j];
                if (item && item->value) {
                    free(item->value);
                }
                free(item);
            }
            free(data->items);
            free(data);
        }
    }

    free(*nodes);
    *nodes = NULL;
}
