    printf("Maximum integer read: %d\n", max_value);

    free(input_integers);
    free(metrics_list[0].next);
    free(metrics_list);
    event *current_event = events_head, *prev_event;
    while (current_event) {
        prev_event = current_event;
        current_event = current_event->next;
        free(prev_event);
    }
    free(requests);
    free(connections);
    free(nodes);

    return 0;
}
