#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "secure_random.h"  // Assume this is the external library for secure random generation

#define STRING_KEY_SIZE 256
#define INITIAL_ARRAY_CAPACITY 10

typedef struct {
    int value;
    char key[STRING_KEY_SIZE];
    long *dynamic_ptr;
} Record;

// Function prototypes
void processRecordsAndFindMax(int size, void (*callback)(Record*));
void findMax(int *array, int length);
long safeMalloc(size_t size);
void freeResources(long *offsets, int *keys, Record *records, int record_size);
void resizeArrayIfNeeded(int **array, int *capacity, int *size, int new_element);

// Helper function to read integers and find max
int* readIntegersAndFindMax(int *max_length) {
    int capacity = INITIAL_ARRAY_CAPACITY;
    int size = 0;
    int *numbers = malloc(capacity * sizeof(int));

    if (!numbers) {
        perror("Failed to allocate memory for numbers");
        exit(EXIT_FAILURE);
    }

    int number;
    while (1) {
        scanf("%d", &number);
        if (number == -1) break;

        resizeArrayIfNeeded(&numbers, &capacity, &size, number);

        numbers[size++] = number;
    }

    *max_length = size;
    return numbers;
}

// Callback function example
void sampleCallback(Record* record) {
    // Example processing: print the value and key
    printf("Record Value: %d, Key: %s\n", record->value, record->key);
}

// Thread-safe safe allocation with logging on failure
long safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Resize the integer array when needed
void resizeArrayIfNeeded(int **array, int *capacity, int *size, int new_element) {
    if (*size >= *capacity) {
        *capacity *= 2;
        *array = realloc(*array, *capacity * sizeof(int));
        if (!*array) {
            perror("Failed to reallocate memory for numbers");
            exit(EXIT_FAILURE);
        }
    }
}

void processRecordsAndFindMax(int size, void (*callback)(Record*)) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = safeMalloc(size * sizeof(long));
    int *keys = safeMalloc(size * sizeof(int));

    Record *records = safeMalloc(size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        offsets[i] = i;
        keys[i] = i;

        records[i].value = secure_random(1, 100); // Secure random number between 1 and 100
        snprintf(records[i].key, STRING_KEY_SIZE, "Key_%d", i);
        records[i].dynamic_ptr = (long*)safeMalloc(sizeof(long));

        if (callback) callback(&records[i]);

        pthread_mutex_lock(&lock);
        *records[i].dynamic_ptr = offsets[i];
        pthread_mutex_unlock(&lock);
    }

    int max_length;
    int *integers = readIntegersAndFindMax(&max_length);

    findMax(integers, max_length);

    freeResources(offsets, keys, records, size);
    free(integers);
}

void findMax(int *array, int length) {
    if (length == 0) {
        printf("No numbers to process.\n");
        return;
    }

    int max = array[0];
    for (int i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    printf("Maximum integer: %d\n", max);
}

void freeResources(long *offsets, int *keys, Record *records, int record_size) {
    for (int i = 0; i < record_size; ++i) {
        free(records[i].dynamic_ptr);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || sscanf(argv[1], "%d", &size) != 1 || size <= 0) {
        fprintf(stderr, "Usage: %s <record_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processRecordsAndFindMax(size, sampleCallback);
    return EXIT_SUCCESS;
}
```

### Key Notes:
- The `secure_random` function is assumed to be provided by the external library and is used for generating random numbers.
- A mutex (`pthread_mutex_t`) is initialized to ensure thread safety when accessing shared resources.
- Memory allocation failures are handled with error logging, and the program exits if an allocation fails.
- Memory is freed using a dedicated `freeResources` function to maintain clean code structure and allow for easier maintenance/testing.']

