#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    int priority;
    char* description;
} Task;

typedef struct {
    Task** tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    // Add any other fields for memory pooling or performance monitoring if needed
} TaskCollection;

void initialize_task_collection(TaskCollection* collection, size_t initial_capacity);
int add_task(TaskCollection* collection, const char* id_str, int priority, const char* description, void (*callback)(Task*));
void cleanup_task_collection(TaskCollection* collection);
size_t get_number_of_tasks(const TaskCollection* collection);

// External string manipulation library function (stub for example)
char* external_string_copy(const char* src) {
    // Implement or link to an efficient string copying function
    return strdup(src);  // Using standard strdup as a placeholder
}

void initialize_task_collection(TaskCollection* collection, size_t initial_capacity) {
    if (!collection || initial_capacity == 0) return;

    pthread_mutex_init(&collection->lock, NULL);
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->tasks = (Task**)malloc(initial_capacity * sizeof(Task*));
}

int add_task(TaskCollection* collection, const char* id_str, int priority, const char* description, void (*callback)(Task*)) {
    if (!collection || !id_str || !description) return -1;

    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Task** new_tasks = (Task**)realloc(collection->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
    }

    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    task->id = atoi(id_str);
    task->priority = priority;
    task->description = external_string_copy(description);

    if (callback) callback(task);

    collection->tasks[collection->size++] = task;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void cleanup_task_collection(TaskCollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->tasks[i]->description);
        free(collection->tasks[i]);
    }

    free(collection->tasks);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
}

size_t get_number_of_tasks(const TaskCollection* collection) {
    if (!collection) return 0;

    pthread_mutex_lock((pthread_mutex_t*)&collection->lock);
    size_t task_count = collection->size;
    pthread_mutex_unlock((pthread_mutex_t*)&collection->lock);

    return task_count;
}
