['```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int task_id;
    int priority;
    char *description;
} Task;

typedef struct {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for thread safety
} TaskCollection;

// Function to initialize the task collection with a given initial capacity and growth factor
TaskCollection* init_task_collection(size_t initial_capacity, int growth_factor) {
    TaskCollection *collection = malloc(sizeof(TaskCollection));
    if (!collection) return NULL;

    pthread_rwlock_init(&collection->rwlock, NULL);
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->tasks = calloc(initial_capacity, sizeof(Task*));

    if (!collection->tasks) {
        free(collection);
        pthread_rwlock_destroy(&collection->rwlock);
        return NULL;
    }

    return collection;
}

// Function to resize the task array when necessary
int resize_task_collection(TaskCollection *collection) {
    size_t new_capacity = collection->capacity * GROWTH_FACTOR;
    Task **new_tasks = realloc(collection->tasks, new_capacity * sizeof(Task*));

    if (!new_tasks) return 0; // Allocation failed

    collection->tasks = new_tasks;
    collection->capacity = new_capacity;

    return 1;
}

// Callback type for processing tasks before insertion
typedef void (*TaskCallback)(Task*);

// Function to add a task to the collection with optional callback
int add_task(TaskCollection *collection, int id, int priority, const char* description, TaskCallback callback) {
    pthread_rwlock_wrlock(&collection->rwlock);

    if (callback) {
        Task temp_task = {id, priority, strdup(description)};
        callback(&temp_task);
        free(temp_task.description); // Clean up if we didn't insert
    }

    if (collection->count == collection->capacity && !resize_task_collection(collection)) {
        pthread_rwlock_unlock(&collection->rwlock);
        return 0;
    }

    Task *task = malloc(sizeof(Task));
    if (!task) {
        pthread_rwlock_unlock(&collection->rwlock);
        return 0;
    }

    task->task_id = id;
    task->priority = priority;
    task->description = strdup(description);

    collection->tasks[collection->count++] = task;

    pthread_rwlock_unlock(&collection->rwlock);
    return 1;
}

// Function to parse tasks from multiple data sources
int parse_and_add_task(TaskCollection *collection, const char* data_source, TaskCallback callback) {
