// Function to cleanup the task collection resources
void cleanup_task_collection(TaskCollection *collection) {
    pthread_rwlock_wrlock(&collection->rwlock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->tasks[i]->description);
        free(collection->tasks[i]);
    }

    free(collection->tasks);
    pthread_rwlock_unlock(&collection->rwlock);

    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

// Example usage
