#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <time.h>

#define INITIAL_HASH_TABLE_SIZE 1024

typedef struct UserSession {
    char userId[64];
    char subscriptionId[64];
    char sessionToken[256];
    time_t expiryTime;
    struct UserSession* next;
} UserSession;

typedef struct Node {
    char userId[64];
    UserSession* session;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable hashTable;

void initHashTable(size_t initialSize) {
    hashTable.size = initialSize;
    hashTable.buckets = calloc(initialSize, sizeof(Node*));
    pthread_mutex_init(&hashTable.lock, NULL);
}

unsigned long hashFunction(const char* userId) {
    unsigned long hash = 5381;
    int c;
    while ((c = *userId++))
        hash = ((hash << 5) + hash) + c;
    return hash % hashTable.size;
}

void rehash() {
    size_t newSize = hashTable.size * 2;
    Node** newBuckets = calloc(newSize, sizeof(Node*));

    for (size_t i = 0; i < hashTable.size; ++i) {
        Node* node = hashTable.buckets[i];
        while (node) {
            Node* nextNode = node->next;
            unsigned long index = hashFunction(node->userId);

            node->next = newBuckets[index];
            newBuckets[index] = node;

            node = nextNode;
        }
    }

    free(hashTable.buckets);
    hashTable.buckets = newBuckets;
    hashTable.size = newSize;
}

void addSession(const char* userId, const char* subscriptionId, const char* sessionToken) {
    pthread_mutex_lock(&hashTable.lock);

    unsigned long index = hashFunction(userId);
    Node* node = hashTable.buckets[index];

    while (node) {
        if (strcmp(node->userId, userId) == 0) {
            free(node->session);
            break;
        }
        node = node->next;
    }

    UserSession* session = malloc(sizeof(UserSession));
    strcpy(session->userId, userId);
    strcpy(session->subscriptionId, subscriptionId);
    strcpy(session->sessionToken, sessionToken);
    session->expiryTime = time(NULL) + 3600; // 1 hour expiry
    session->next = NULL;

    Node* newNode = malloc(sizeof(Node));
    strcpy(newNode->userId, userId);
    newNode->session = session;
    newNode->next = hashTable.buckets[index];
    hashTable.buckets[index] = newNode;

    if (/* condition to rehash */) {
        rehash();
    }

    pthread_mutex_unlock(&hashTable.lock);
}

void removeSession(const char* userId) {
    pthread_mutex_lock(&hashTable.lock);

    unsigned long index = hashFunction(userId);
    Node *node = hashTable.buckets[index], *prev = NULL;

    while (node) {
        if (strcmp(node->userId, userId) == 0) {
            if (prev)
                prev->next = node->next;
            else
                hashTable.buckets[index] = node->next;

            free(node->session);
            free(node);
            break;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&hashTable.lock);
}

void updateSession(const char* userId, const char* newToken) {
    pthread_mutex_lock(&hashTable.lock);

    unsigned long index = hashFunction(userId);
    Node *node = hashTable.buckets[index];

    while (node) {
        if (strcmp(node->userId, userId) == 0) {
            strcpy(node->session->sessionToken, newToken);
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&hashTable.lock);
}

void authenticateSession(const char* userId) {
    unsigned long index = hashFunction(userId);
    Node *node = hashTable.buckets[index];

    while (node) {
        if (strcmp(node->userId, userId) == 0) {
            // Generate authKeyId and authKeyData using cryptographic primitives
            unsigned char authKeyId[EVP_MAX_KEY_LENGTH];
            unsigned char authKeyData[EVP_MAX_KEYLENGTH];

            if (!RAND_bytes(authKeyId, sizeof(authKeyId)) || !RAND_bytes(authKeyData, sizeof(authKeyData))) {
                fprintf(stderr, "Error generating random bytes\n");
                return;
            }

            printf("Authentication successful for userId: %s\n", userId);
            // Use authKeyId and authKeyData as needed
            break;
        }
        node = node->next;
    }
}

void cleanupExpiredSessions() {
    time_t now = time(NULL);

    pthread_mutex_lock(&hashTable.lock);

    for (size_t i = 0; i < hashTable.size; ++i) {
        Node *node = hashTable.buckets[i], *prev = NULL;

        while (node) {
            if (node->session->expiryTime <= now) {
                if (prev)
                    prev->next = node->next;
                else
                    hashTable.buckets[i] = node->next;

                free(node->session);
                Node* toFree = node;
                node = node->next;
                free(toFree);
            } else {
                prev = node;
                node = node->next;
            }
        }
    }

    pthread_mutex_unlock(&hashTable.lock);
}

void initializeSystem() {
    initHashTable(INITIAL_HASH_TABLE_SIZE);

    // Simulate adding sessions
    for (int i = 0; i < 1000000; ++i) {
        char userId[64], subscriptionId[64], sessionToken[256];

        snprintf(userId, sizeof(userId), "user%d", i);
        snprintf(subscriptionId, sizeof(subscriptionId), "sub%d", rand() % 10);
        RAND_bytes((unsigned char*)sessionToken, sizeof(sessionToken) - 1);
        sessionToken[sizeof(sessionToken) - 1] = '\0';

        addSession(userId, subscriptionId, sessionToken);
    }
}

int main() {
    initializeSystem();

    // Simulate operations
    authenticateSession("user42");
    updateSession("user42", "newToken123");
    removeSession("user999999");

    cleanupExpiredSessions();

    return 0;
}
