        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void processRecord(record *rec, void (*callback)(record *)) {
    if (callback != NULL) {
        callback(rec);
    }
}

void freeResources(record *records, size_t recordCount, int *inputArray, size_t inputSize) {
