    free(records);
    free(inputArray);
}

void processRecordsAndFindMax(size_t recordCount, void (*callback)(record *)) {
    int *offset = malloc(recordCount * sizeof(int));
    char **key = malloc(recordCount * sizeof(char *));
    if (!offset || !key) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < recordCount; ++i) {
        offset[i] = i;
        key[i] = malloc(20); // Assume fixed size for simplicity
        snprintf(key[i], 20, "key_%zu", i);
    }

    record *records = malloc(recordCount * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset);
        for (size_t i = 0; i < recordCount; ++i) {
            free(key[i]);
        }
        free(key);
        exit(EXIT_FAILURE);
    }

    srand(42); // Custom seed for reproducibility
    secure_random_state *state = secure_random_init();
    if (!state) {
        fprintf(stderr, "Failed to initialize secure random state\n");
        free(offset);
        for (size_t i = 0; i < recordCount; ++i) {
            free(key[i]);
        }
        free(key);
        free(records);
        exit(EXIT_FAILURE);
    }

    size_t inputSize = 10;
    int *inputArray = malloc(inputSize * sizeof(int));
    if (!inputArray) {
        fprintf(stderr, "Memory allocation failed\n");
        secure_random_cleanup(state);
        free(offset);
        for (size_t i = 0; i < recordCount; ++i) {
            free(key[i]);
        }
        free(key);
        free(records);
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    while (1) {
        int input;
        if (!scanf("%d", &input)) break;
        if (input == -1) break;

        if (count >= inputSize) {
            inputSize *= 2;
            int *newArray = realloc(inputArray, inputSize * sizeof(int));
            if (!newArray) {
                fprintf(stderr, "Memory allocation failed\n");
                secure_random_cleanup(state);
                free(offset);
                for (size_t i = 0; i < recordCount; ++i) {
                    free(key[i]);
                }
                free(key);
                free(records);
                exit(EXIT_FAILURE);
            }
            inputArray = newArray;
        }

        inputArray[count++] = input;

        for (size_t i = 0; i < recordCount; ++i) {
            records[i].value = secure_random_int(state, INT_MIN, INT_MAX);
            records[i].key = key[i];
            long *ptr = malloc(sizeof(long));
            if (!ptr) {
                fprintf(stderr, "Memory allocation failed\n");
                secure_random_cleanup(state);
                free(offset);
                for (size_t j = 0; j < recordCount; ++j) {
                    free(key[j]);
                }
                free(key);
                free(records);
                exit(EXIT_FAILURE);
            }
            records[i].pointer = ptr;
            processRecord(&records[i], callback);
        }
    }

    int maxInputValue = findMax(inputArray, count);
    printf("Maximum input value: %d\n", maxInputValue);

    secure_random_cleanup(state);
    freeResources(records, recordCount, inputArray, inputSize);
}
