    resize_array((void**)&keys, 0, config->key_size, sizeof(int));
    for (int i = 0; i < config->key_size; ++i) {
        keys[i] = i;
    }

    MemoryPool pool;
    initialize_memory_pool(&pool, 4096, 10); // Example block size and number
    resize_array((void**)&records, 0, config->record_size, sizeof(Record));

    srand(config->seed);
    for (int i = 0; i < config->record_size; ++i) {
        records[i].key = keys[i % config->key_size];
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID-%d", records[i].key);
        records[i].value = rand() % (config->rand_max - config->rand_min + 1) + config->rand_min;
    }

    for (int i = 0; i < config->record_size; ++i) {
        if (callback)
            callback(&records[i]);
    }

    int input;
    while (scanf("%d", &input) && input != -1) {
        // Process the input, dynamically resize records as necessary
        resize_array((void**)&records, config->record_size, config->record_size + 1, sizeof(Record));
        records[config->record_size].key = input;
        snprintf(records[config->record_size].identifier, sizeof(records[config->record_size].identifier), "ID-%d", input);
        records[config->record_size].value = rand() % (config->rand_max - config->rand_min + 1) + config->rand_min;
        ++config->record_size;
    }

    finalize_memory_pool(&pool);
    free(offsets);
    free(keys);
    free(records);
}
