use std::process::{Command, Output};
use std::time::{Duration, Instant};
use std::fs;
use std::io::{self, Write};

fn compile_rust_program(directory: &str) -> io::Result<()> {
    let start_time = Instant::now();

    // Check if the directory exists
    if !std::path::Path::new(directory).exists() {
        eprintln!("Error: Directory does not exist.");
        return Err(io::Error::new(io::ErrorKind::NotFound, "Directory not found"));
    }

    let manifest_path = format!("{}/Cargo.toml", directory);
    if !manifest_path.exists() {
        eprintln!("Error: Cargo.toml not found in the specified directory.");
        return Err(io::Error::new(io::ErrorKind::NotFound, "Cargo.toml not found"));
    }

    // Prepare to capture output
    let mut log_file = fs::File::create(format!("{}/compilation_log.txt"))?;

    // Execute cargo build command
    match Command::new("cargo")
        .arg("build")
        .current_dir(directory)
        .output() {
        Ok(output) => {
            if !output.status.success() {
                writeln!(log_file, "Compilation failed: {:?}", output.stderr)?;
                return Err(io::Error::new(io::ErrorKind::Other, "Compilation failed"));
            }

            // Log the compilation success
            writeln!(log_file, "Compilation succeeded")?;
        },
        Err(e) => {
            writeln!(log_file, "Failed to execute cargo command: {:?}", e)?;
            return Err(io::Error::from(e));
        }
    }

    let duration = start_time.elapsed();

    // Log the time taken for compilation
    writeln!(log_file, "Compilation took {:?}", duration)?;

    println!("Compiling Rust program completed in {:?}", duration);
    Ok(())
}

fn main() {
    if let Err(e) = compile_rust_program("./your_directory") {
        eprintln!("Error occurred: {}", e);
    }
}
