// Custom typedefs
typedef long offset_t;
typedef int key_t;

#define MAX_MEMORY_LIMIT 10485760 // Example maximum memory limit (e.g., 10 MB)

typedef struct {
    int field;
} record_t;

typedef struct {
    pthread_mutex_t lock; // Synchronization for concurrent access
    offset_t *offset_array;
    size_t offset_size;
    key_t *key_array;
    size_t key_size;
    record_t *record_array;
    size_t record_size;
} MemoryManager;

// Function prototypes
bool initialize_memory_manager(MemoryManager *manager, size_t offset_count, size_t key_count, size_t record_count);
void deallocate_memory_manager(MemoryManager *manager);
bool validate_keys(const MemoryManager *manager, int max_threshold);
record_t* find_record_by_key(const MemoryManager *manager, key_t key);

// Function implementations
bool initialize_memory_manager(MemoryManager *manager, size_t offset_count, size_t key_count, size_t record_count) {
    pthread_mutex_init(&manager->lock, NULL);

    manager->offset_size = offset_count;
    manager->key_size = key_count;
    manager->record_size = record_count;

    // Calculate total memory usage
    size_t total_memory_usage = sizeof(offset_t) * offset_count +
                                sizeof(key_t) * key_count +
                                sizeof(record_t) * record_count;

    if (total_memory_usage > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation exceeds the maximum limit.\n");
        return false;
    }

    // Allocate and initialize offset array
    manager->offset_array = (offset_t *)malloc(sizeof(offset_t) * offset_count);
    for (size_t i = 0; i < offset_count; ++i) {
        manager->offset_array[i] = rand() % 100 + 1; // Random values within range [1, 100]
    }

    // Allocate and initialize key array
    manager->key_array = (key_t *)malloc(sizeof(key_t) * key_count);
    int max_threshold = fetch_max_key_threshold(); // Fetch dynamically from an external source

    for (size_t i = 0; i < key_count; ++i) {
        do {
            manager->key_array[i] = rand() % max_threshold + 1;
        } while (!is_unique_in_array(manager->key_array, i));
    }

    // Allocate and initialize record array
    manager->record_array = (record_t *)malloc(sizeof(record_t) * record_count);
    for (size_t i = 0; i < record_count; ++i) {
        manager->record_array[i].field = rand() % 100 + 1; // Random values within range [1, 100]
    }

    return true;
}

void deallocate_memory_manager(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->offset_array) free(manager->offset_array);
    if (manager->key_array) free(manager->key_array);
    if (manager->record_array) free(manager->record_array);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

bool validate_keys(const MemoryManager *manager, int max_threshold) {
    for (size_t i = 0; i < manager->key_size; ++i) {
        if (manager->key_array[i] > max_threshold || !is_unique_in_array(manager->key_array, i)) {
            return false;
        }
    }
    return true;
}

record_t* find_record_by_key(const MemoryManager *manager, key_t key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->record_size; ++i) {
        if (manager->key_array[i] == key) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->record_array[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Helper functions
int fetch_max_key_threshold() {
    // Simulate fetching from an external source, e.g., config file or database.
