```c
#include <stdio.h>
#include <stdlib.h>
import pthread.h

#define MAX_MEMORY_USAGE 0.5 // Maximum 50% of available RAM
typedef struct {
    int value;
} record;

size_t get_available_ram() {
    FILE* file = fopen("/proc/meminfo", "r");
    if (!file) return 0;
    size_t total_memory_kb = 0;
    char line[128];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "MemTotal: %zu kB", &total_memory_kb) == 1) break;
    }
    fclose(file);
    return total_memory_kb * 1024; // Convert to bytes
}

void initialize_arrays(size_t long_count, size_t int_count, size_t record_count) {
    size_t available_ram = get_available_ram();
    size_t max_alloc_size = (size_t)(available_ram * MAX_MEMORY_USAGE);

    size_t long_array_size = long_count * sizeof(long);
    size_t int_array_size = int_count * sizeof(int);
    size_t records_array_size = record_count * sizeof(record);

    size_t total_required_memory = long_array_size + int_array_size + records_array_size;

    if (total_required_memory > max_alloc_size) {
        fprintf(stderr, "Warning: Limited memory allocation due to insufficient available RAM.\n");
        // Adjust allocations proportionally
        double scale_factor = (double)max_alloc_size / total_required_memory;
        long_count = (size_t)(long_count * scale_factor);
        int_count = (size_t)(int_count * scale_factor);
        record_count = (size_t)(record_count * scale_factor);

        long_array_size = long_count * sizeof(long);
        int_array_size = int_count * sizeof(int);
        records_array_size = record_count * sizeof(record);
    }

    long* offsets = malloc(long_array_size);
    int* keys = malloc(int_array_size);
    record* records = malloc(records_array_size);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    void* write_to_records(size_t index, int value) {
        pthread_mutex_lock(&mutex);
        if (index < record_count) {
            records[index].value = value;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Use the arrays and records as needed...

    free(offsets);
    free(keys);
    free(records);
}
