### Rust Function

```rust
use std::process::{Command, Output};
use std::time::Instant;
use log::{info, error};

fn run_compiler_and_measure() -> i32 {
    let start_time = Instant::now();

    match measure_resident_set_size() {
        Ok((before, after)) => info!("Resident Set Size before: {} bytes", before),
        Err(e) => error!("Failed to measure Resident Set Size before compilation: {}", e),
    }

    let output: Output = Command::new("rustc")
        .arg("--crate-name")
        .arg("example")
        .arg("--emit=bin,dep-info,link"
        )
        .output()
        .expect("Failed to execute compiler");

    match measure_resident_set_size() {
        Ok((_, after)) => info!("Resident Set Size after: {} bytes", after),
        Err(e) => error!("Failed to measure Resident Set Size after compilation: {}", e),
    }

    let duration = start_time.elapsed();
    info!("Compilation took: {:?}", duration);

    match output.status.success() {
        true => 0,
        false => {
            error!("Compiler error: {:?}", String::from_utf8_lossy(&output.stderr));
            1
        }
    }
}

fn measure_resident_set_size() -> Result<(u64, u64), Box<dyn std::error::Error>> {
    use sysinfo::{ProcessExt, System, SystemExt};

    let mut system = System::new_all();
    system.refresh_processes();

    if let Some(process) = system.get_process(0) { // Assuming rustc is the main process
        let before_rss = process.memory().resident();
        std::thread::sleep(std::time::Duration::from_secs(1)); // Wait for potential changes
        system.refresh_all(); // Refresh to get updated metrics

        if let Some(process) = system.get_process(0) { 
            Ok((before_rss, process.memory().resident()))
        } else {
            Err("Failed to retrieve process after refresh".into())
        }
    } else {
        Err("Failed to retrieve initial process".into())
    }
}

fn main() {
    env_logger::init();

    let exit_code = run_compiler_and_measure();
    std::process::exit(exit_code);
}
```

