TaskList* create_task_list(size_t initial_capacity) {
    TaskList *list = malloc(sizeof(TaskList));
    if (!list) {
        log_error("Failed to allocate memory for task list");
        return NULL;
    }

    list->tasks = calloc(initial_capacity, sizeof(Task));
    if (!list->tasks) {
        free(list->tasks);
        log_error("Failed to allocate memory for tasks array");
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;

    // Initialize offsets with random values
    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        list->tasks[i].offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
    }

    return list;
}

int add_task(TaskList *list, Task task) {
    if (!list || list->count >= MAX_TASKS) return -1;

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Task *new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));
        if (!new_tasks) {
            log_error("Failed to reallocate memory for tasks array");
            return -1;
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;

        // Initialize new offsets with random values
        for (size_t i = list->count; i < list->capacity; ++i) {
            list->tasks[i].offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
        }
    }

    list->tasks[list->count++] = task;
    return 0;
}

