        json_object_object_add(task_obj, "offset", json_object_new_int(list->tasks[i].offset));

        json_object_array_add(jobj, task_obj);
    }

    const char *json_str = json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN);
    json_object_put(jobj);

    return strdup(json_str);
}

int compress_and_store(const char *data, size_t data_len) {
    if (data == NULL || data_len < 1) return -1;

    uLongf compressed_size = compressBound(data_len);
    unsigned char *compressed_data = malloc(compressed_size);
    if (!compressed_data) {
        log_error("Failed to allocate memory for compression");
        return -1;
    }

    if (compress(compressed_data, &compressed_size, (const Bytef *)data, data_len) != Z_OK) {
        free(compressed_data);
        log_error("Compression failed");
        return -1;
    }

    FILE *fp = fopen("tasks_compressed.dat", "wb");
    if (!fp) {
        free(compressed_data);
        log_error("Failed to open file for writing compressed data");
        return -1;
