#define MAX_RECORDS 1000
#define KEY_SIZE 256
#define TIMESTAMP_SIZE 64
#define OFFSET_RANGE_MIN -10000
#define OFFSET_RANGE_MAX 10000
#define INT_RANGE_MIN 1
#define INT_RANGE_MAX 1000
#define JSON_COMPRESSION_THRESHOLD 10

typedef struct {
    int id;
    int priority;
    time_t due_date;
    int status; // Assume 0 for inactive, 1 for active, etc.
    long offset;
    int value;
    char key[KEY_SIZE];
    long* ptr_long;
    time_t* timestamp_ptr;
} Record;

typedef struct {
    Record *records;
    size_t count;
} RecordList;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int initialize_record(Record* record, int id, int priority, time_t due_date, int status, long offset, int value, const char* key) {
    if (!record) return -1;

    record->id = id;
    record->priority = priority;
    record->due_date = due_date;
    record->status = status;
    record->offset = offset;
    record->value = value;
    strncpy(record->key, key, KEY_SIZE-1);
    record->ptr_long = NULL;
    record->timestamp_ptr = NULL;

    return 0;
}

RecordList* create_record_list(size_t initial_size) {
    if (initial_size > MAX_RECORDS) {
        log_error("Requested size exceeds maximum allowed records.");
        return NULL;
    }

    RecordList* list = malloc(sizeof(RecordList));
    if (!list) {
        log_error("Failed to allocate memory for record list.");
        return NULL;
    }

    list->records = calloc(initial_size, sizeof(Record));
    if (!list->records) {
        free(list);
        log_error("Failed to allocate memory for records array.");
        return NULL;
    }

    list->count = 0;

    // Seed random number generator
    unsigned int seed = (unsigned int)time(NULL); 
    secure_random_init(seed);

    // Initialize records with random values and sequential keys/timestamps
    for (size_t i = 0; i < initial_size; ++i) {
        long offset = secure_random_range(OFFSET_RANGE_MIN, OFFSET_RANGE_MAX);
        int value = secure_random_range(INT_RANGE_MIN, INT_RANGE_MAX);
        snprintf(list->records[i].key, KEY_SIZE, "key_%zu", i);

        initialize_record(&list->records[i], i, 0, time(NULL), 1, offset, value, list->records[i].key);
    }

    return list;
}

void free_record_list(RecordList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i].ptr_long);
        free(list->records[i].timestamp_ptr);
    }

    free(list->records);
    free(list);
}

int serialize_to_json(RecordList* list, char** json_out) {
    if (!list || !json_out) return -1;

    json_object *jobj = json_object_new_array();
    for (size_t i = 0; i < list->count; ++i) {
        json_object *record_obj = json_object_new_object();

        json_object_object_add(record_obj, "id", json_object_new_int(list->records[i].id));
        json_object_object_add(record_obj, "priority", json_object_new_int(list->records[i].priority));
        json_object_object_add(record_obj, "due_date", json_object_new_int64((int64_t)list->records[i].due_date));
        json_object_object_add(record_obj, "status", json_object_new_int(list->records[i].status));
        json_object_object_add(record_obj, "offset", json_object_new_int64((int64_t)list->records[i].offset));
        json_object_object_add(record_obj, "value", json_object_new_int(list->records[i].value));
        json_object_object_add(record_obj, "key", json_object_new_string(list->records[i].key));

        json_object_array_add(jobj, record_obj);
    }

    *json_out = strdup(json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN));
    if (!*json_out) {
        log_error("Failed to serialize records to JSON.");
        json_object_put(jobj); // Free JSON object
        return -1;
    }

    json_object_put(jobj); // Clean up

    return 0;
}

int compress_and_store(const char* json_data, size_t data_size) {
    if (data_size < JSON_COMPRESSION_THRESHOLD * 1024) return 0; // Skip compression for small data

    unsigned long compressed_size = compressBound(data_size);
    unsigned char* compressed_data = malloc(compressed_size);

    if (!compressed_data || !compress(compressed_data, &compressed_size, (const unsigned char*)json_data, data_size)) {
        free(compressed_data);
        log_error("Compression failed.");
        return -1;
    }

    FILE* archive_file = fopen("archive.zip", "ab");
    if (!archive_file) {
        free(compressed_data);
        log_error("Failed to open archive file for writing.");
        return -1;
    }

    fwrite(compressed_data, 1, compressed_size, archive_file);
    fclose(archive_file);

    free(compressed_data);

    return 0;
}

int main() {
    RecordList* list = create_record_list(5); // Example with initial size of 5
    if (!list) return EXIT_FAILURE;

    char* json_output;
    if (serialize_to_json(list, &json_output)) {
        free(json_output);
        free_record_list(list);
        return EXIT_FAILURE;
    }

    compress_and_store(json_output, strlen(json_output));

    free(json_output);
    free_record_list(list);

    return EXIT_SUCCESS;
}
