void initialize_data(double *temperatures, time_t *timestamps, sensor *sensors, size_t n) {
    srand((unsigned int)time(NULL));

    // Initialize temperatures with random values between 0.0 and 100.0
    for (size_t i = 0; i < n; ++i) {
        temperatures[i] = rand() / (double)RAND_MAX * 100.0;
    }

    // Initialize timestamps with unique random values
    for (size_t i = 0; i < n; ++i) {
        timestamps[i] = rand();
    }

    // Sort and remove duplicates from timestamps to ensure uniqueness
    qsort(timestamps, n, sizeof(time_t), (__compar_fn_t)strcmp);
    size_t unique_count = 1;
    for (size_t i = 1; i < n; ++i) {
        if (timestamps[i] != timestamps[unique_count - 1]) {
            timestamps[unique_count++] = timestamps[i];
        }
    }

    // Initialize sensors with random signal strengths and corresponding timestamps
    for (size_t i = 0; i < unique_count && i < n; ++i) {
        sensors[i].signal_strength = rand() / (float)RAND_MAX * 10.0;
    }
}

