import subprocess
import time
import psutil
import logging

def monitor_script(directory_path, script_name, interval=1):
    logging.basicConfig(filename='system_monitor.log', level=logging.INFO)

    try:
        # Construct the full path to the script
        script_path = f"{directory_path}/{script_name}"

        # Start the script as a subprocess
        process = subprocess.Popen(['python3', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        while True:
            # Check if the script is still running
            if process.poll() is not None:
                logging.info(f"Script '{script_name}' finished with return code {process.returncode}")
                break

            # Measure CPU and memory usage
            cpu_usage = psutil.cpu_percent(interval=interval)
            memory_info = psutil.virtual_memory()
            logging.info(f"CPU Usage: {cpu_usage}%, Memory Usage: {memory_info.percent}%")

            time.sleep(interval)

        # Capture any errors from the script execution
        stdout, stderr = process.communicate()
        if stderr:
            logging.error(f"Script '{script_name}' encountered an error:\n{stderr.decode()}")

    except Exception as e:
        logging.error(f"An exception occurred: {str(e)}")

# Example usage:
# monitor_script('/path/to/directory', 'custom_script.py')
