typedef struct {
    int value;
    char *buffer;
} Record;

#define MAX_THREADS 10

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int shared_counter = 0;

// Function to initialize and fill arrays
int initialize_arrays(long n, long offset[], int keys[], Record records[],
                      int min_key_value, int max_key_value, const char *prefix) {
    pthread_mutex_lock(&mutex);
    size_t buffer_size = strlen(prefix) + sizeof(int);

    // Allocate memory for offsets, keys, and records
    offset = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));
    records = (Record *)malloc(n * sizeof(Record));

    if (!offset || !keys || !records) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failure
    }

    srand(time(NULL)); // Seed for random number generation

    for (long i = 0; i < n; ++i) {
        offset[i] = i;

        keys[i] = min_key_value + rand() % (max_key_value - min_key_value + 1);

        records[i].value = keys[i];

        // Allocate memory for the buffer and check allocation
        records[i].buffer = (char *)malloc(buffer_size);
        if (!records[i].buffer) {
            // Free already allocated resources on failure
            free(offset);
            free(keys);
            for (long j = 0; j < i; ++j) {
                free(records[j].buffer);
            }
            free(records);
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        snprintf(records[i].buffer, buffer_size, "%s%d", prefix, shared_counter++);
    }

    // Validate integrity of allocations (basic example)
    for (long i = 0; i < n; ++i) {
        if (!offset[i] || !keys[i] || !records[i].value || !records[i].buffer) {
            free_resources(offset, keys, records, n);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

// Function to release all allocated resources safely
void free_resources(long *offset, int *keys, Record *records, long n) {
    if (offset) free(offset);
    if (keys) free(keys);
    for (long i = 0; i < n; ++i) {
        if (records[i].buffer) free(records[i].buffer);
    }
    if (records) free(records);
}

// Example usage
int main() {
    long n = 10;
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    const char *prefix = "Record";
    int min_key_value = 0, max_key_value = 100;

    if (initialize_arrays(n, offsets, keys, records, min_key_value, max_key_value, prefix) == 0) {
        // Use the arrays...

        free_resources(offsets, keys, records, n);
    } else {
        printf("Initialization failed.\n");
    }

    return 0;
}
