#include <unistd.h>
#include <errno.h>
#include "json-c/json.h" // Assuming json-c library for JSON operations
#include "zlib.h"        // Assuming zlib for compression

#define MAX_TASKS 1000
#define CATEGORY_COUNT 5
#define JSON_ARCHIVE_SIZE_THRESHOLD 500

typedef enum { TASK_PENDING, TASK_COMPLETED } Status;
typedef enum { CAT_WORK, CAT_PERSONAL, CAT_HOME, CAT_EDUCATION, CAT_OTHER } Category;

typedef struct {
    int id;
    int priority;
    time_t due_date;
    Status status;
    long offset;
    Category category;
} Task;

typedef struct {
    Task *tasks[MAX_TASKS];
    size_t count;
    pthread_mutex_t lock; // For thread-safe operations
} TaskManager;

// Function prototypes
int manage_tasks(TaskManager *manager, int time_shift);
void log_error(const char *message);
int update_task_due_date(Task *task, int time_shift);
int serialize_to_json(const TaskManager *manager, char **json_string);
int compress_and_store_json(const char *json_string);

// Main function to manage tasks
int manage_tasks(TaskManager *manager, int time_shift) {
    if (!manager) return -1;

    // Initialize mutex lock for thread-safety
    pthread_mutex_init(&manager->lock, NULL);

    // Allocate memory for task list and handle allocation failure
    for (size_t i = 0; i < MAX_TASKS && manager->count < MAX_TASKS; ++i) {
        Task *task = malloc(sizeof(Task));
        if (!task) {
            log_error("Memory allocation failed");
            return -1;
        }

        // Initialize task fields
        task->id = (int)i;
        task->priority = rand() % 10 + 1;
        task->due_date = time(NULL) + ((rand() % 30) * 24 * 60 * 60);
        task->status = TASK_PENDING;
        task->offset = rand() % 1000; // Example range [0, 999]

        const Category categories[CATEGORY_COUNT] = { CAT_WORK, CAT_PERSONAL, CAT_HOME, CAT_EDUCATION, CAT_OTHER };
        task->category = categories[rand() % CATEGORY_COUNT];

        manager->tasks[i] = task;
        manager->count++;
    }

    // Update due dates based on time shift
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        update_task_due_date(manager->tasks[i], time_shift);
    }
    pthread_mutex_unlock(&manager->lock);

    // Serialize to JSON and handle compression if necessary
    char *json_string = NULL;
    if (serialize_to_json(manager, &json_string)) return -1;

    if (manager->count >= JSON_ARCHIVE_SIZE_THRESHOLD) {
        compress_and_store_json(json_string);
    }

    free(json_string);

    pthread_mutex_destroy(&manager->lock);
    return 0; // Success
}

// Log error messages
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Update task due date with a time shift
int update_task_due_date(Task *task, int time_shift) {
    if (!task) return -1;

    // Handle potential precision issues by using proper calculations for time shifts
    struct tm *tm_info = localtime(&task->due_date);
    tm_info->tm_sec += time_shift; // Example of applying shift to seconds
    task->due_date = mktime(tm_info);

    return 0;
}

// Serialize task list to JSON string
int serialize_to_json(const TaskManager *manager, char **json_string) {
    if (!manager || !json_string) return -1;

    json_object *jobj = json_object_new_array();
    for (size_t i = 0; i < manager->count; ++i) {
        json_object *task_obj = json_object_new_object();

        json_object_object_add(task_obj, "id",         json_object_new_int(manager->tasks[i]->id));
        json_object_object_add(task_obj, "priority",   json_object_new_int(manager->tasks[i]->priority));
        json_object_object_add(task_obj, "due_date",   json_object_new_int64(manager->tasks[i]->due_date));

        const char *status = manager->tasks[i]->status == TASK_PENDING ? "pending" : "completed";
        json_object_object_add(task_obj, "status",     json_object_new_string(status));

        json_object_object_add(task_obj, "offset",     json_object_new_int64(manager->tasks[i]->offset));

        const char *categories[CATEGORY_COUNT] = { "work", "personal", "home", "education", "other" };
        json_object_object_add(task_obj, "category",   json_object_new_string(categories[manager->tasks[i]->category]));

        json_object_array_add(jobj, task_obj);
    }

    // Convert JSON object to string
    const char *json_str = json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN);

    *json_string = strdup(json_str);
    if (!*json_string) return -1;

    json_object_put(jobj);  // Free the JSON object

    return 0;
}

// Compress and store JSON string in an archive file
int compress_and_store_json(const char *json_string) {
    if (!json_string) return -1;

    // Example of using zlib for compression (pseudo-code)
    uLongf compressed_size = compressBound(strlen(json_string));
    unsigned char *compressed_data = malloc(compressed_size);
    if (!compressed_data) return -1;

    if (compress(compressed_data, &compressed_size, (unsigned char *)json_string, strlen(json_string)) != Z_OK) {
        free(compressed_data);
        return -1;
    }

    // Write compressed data to a file (example)
    FILE *fp = fopen("tasks_archive.zip", "wb");
    if (!fp) return -1;

    fwrite(compressed_data, 1, compressed_size, fp);
    fclose(fp);

    free(compressed_data);
    return 0;
}
```

This code provides the core functionality for managing a dynamic list of tasks with features as described. It includes memory allocation, error handling, JSON serialization, compression, and thread safety using mutex locks. External dependencies like `json-c` and `zlib` are assumed to be available.']

