    }
}

long parseConfig(const char *filename, int *offsetSize, int *keySize, long *defaultSeed, int rangeLow, int rangeHigh) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file.\n");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Example parsing logic
        if (sscanf(line, "offsetSize %d", offsetSize) == 1 ||
            sscanf(line, "keySize %d", keySize) == 1 ||
            sscanf(line, "defaultSeed %ld", defaultSeed) == 1 ||
            sscanf(line, "rangeLow %d rangeHigh %d", &rangeLow, &rangeHigh) == 2) {
        }
    }

    fclose(file);
    return *defaultSeed;
}

void processRecordsAndFindMax(int rounds, const char *configFile, int defaultOffsetSize, int defaultKeySize, long seed, void (*callback)(Record *)) {
    int offsetSizes[rounds], keySizes[rounds];
    int rangeLow = 0, rangeHigh = 100;

    long defaultSeed = parseConfig(configFile, &defaultOffsetSize, &defaultKeySize, &seed, rangeLow, rangeHigh);
    srand(seed);

    for (int round = 0; round < rounds; ++round) {
        offsetSizes[round] = defaultOffsetSize + round;
        keySizes[round] = defaultKeySize + round;

        long *offsets = malloc(offsetSizes[round] * sizeof(long));
        handleMemoryAllocationFailure(offsets, "Failed to allocate offsets array.");

        int *keys = malloc(keySizes[round] * sizeof(int));
        handleMemoryAllocationFailure(keys, "Failed to allocate keys array.");

        Record *records = NULL;
        size_t recordCapacity = 10; // Initial capacity
        records = realloc(records, recordCapacity * sizeof(Record));
        handleMemoryAllocationFailure(records, "Failed to allocate initial records array.");

        for (int i = 0; i < offsetSizes[round]; ++i) {
            offsets[i] = i;
        }

        for (int i = 0; i < keySizes[round]; ++i) {
            keys[i] = i;
        }

        int recordCount = 0;
        long maxIntValue = LONG_MIN;

        while (recordCount < offsetSizes[round]) {
            if (recordCount >= recordCapacity) {
                recordCapacity *= 2;
                records = realloc(records, recordCapacity * sizeof(Record));
                handleMemoryAllocationFailure(records, "Failed to resize records array.");
            }

            records[recordCount].value = rand() % (rangeHigh - rangeLow + 1) + rangeLow;
            snprintf(records[recordCount].key, sizeof(records[recordCount].key), "Key_%d", recordCount);
            records[recordCount].dynamicPointer = malloc(sizeof(long));
            handleMemoryAllocationFailure(records[recordCount].dynamicPointer, "Failed to allocate dynamic pointer.");
            *(records[recordCount].dynamicPointer) = offsets[recordCount];

            if (callback) {
                callback(&records[recordCount]);
            }

            maxIntValue = records[recordCount].value > maxIntValue ? records[recordCount].value : maxIntValue;
            recordCount++;
        }

        printf("Round %d: Maximum Integer Value is %ld\n", round + 1, maxIntValue);

        for (int i = 0; i < recordCount; ++i) {
            free(records[i].dynamicPointer);
        }
        free(offsets);
        free(keys);
        free(records);
    }
}

void exampleCallback(Record *record) {
    printf("Processing Record: Value=%d, Key=%s\n", record->value, record->key);
}

int main(int argc, char *argv[]) {
    int rounds = 3;
    const char *configFile = "config.txt";
    long seed = time(NULL);

    if (argc > 1) {
        configFile = argv[1];
    }
    if (argc > 2) {
        seed = atol(argv[2]);
    }

    processRecordsAndFindMax(rounds, configFile, 5, 5, seed, exampleCallback);
    return 0;
}
