#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char key[256];
    long *dynamicLongPtr;
} Record;

typedef void (*RecordCallback)(Record*);

void freeRecords(long* offsets, int* keys, Record** records, size_t recordCount) {
    for (size_t i = 0; i < recordCount; ++i) {
        if (records[i]) {
            free(records[i]->dynamicLongPtr);
            free(records[i]);
        }
    }
    free(offsets);
    free(keys);
    free(records);
}

int* readIntegers(size_t* size, int sentinel) {
    size_t capacity = 10;
    size_t count = 0;
    *size = 0;

    int* numbers = malloc(capacity * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }

        int number;
        if (scanf("%d", &number) != 1) {
            fprintf(stderr, "Invalid input\n");
            free(numbers);
            exit(EXIT_FAILURE);
        }

        if (number == sentinel)
            break;

        numbers[count++] = number;
    }

    *size = count;
    return numbers;
}

int findMax(int* numbers, size_t size) {
    if (size == 0) {
        fprintf(stderr, "No valid numbers to process\n");
        exit(EXIT_FAILURE);
    }

    int max = numbers[0];
    for (size_t i = 1; i < size; ++i) {
        if (numbers[i] > max)
            max = numbers[i];
    }
    return max;
}

int generateSecureRandomInt(int min, int max) {
    srand((unsigned)time(NULL));
    return rand() % (max - min + 1) + min;
}

void processRecord(Record* record, RecordCallback callback) {
    if (callback)
        (*callback)(record);
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *processRecordsAndFindMax(void *arg) {
    size_t recordCount;
    printf("Enter the number of records: ");

    if (scanf("%zu", &recordCount) != 1 || recordCount <= 0) {
        fprintf(stderr, "Invalid number of records\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = malloc(recordCount * sizeof(long));
    int* keys = malloc(recordCount * sizeof(int));
    Record** records = malloc(recordCount * sizeof(Record*));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        freeRecords(offsets, keys, records, recordCount);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < recordCount; ++i) {
        offsets[i] = i;
        keys[i] = generateSecureRandomInt(1, 100);

        Record* record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            freeRecords(offsets, keys, records, i);
            exit(EXIT_FAILURE);
        }

        record->value = generateSecureRandomInt(-1000, 1000);
        strcpy(record->key, "ExampleKey");

        long* dynamicLongPtr = malloc(sizeof(long));
        if (!dynamicLongPtr) {
            fprintf(stderr, "Memory allocation failed\n");
            freeRecords(offsets, keys, records, i + 1);
            exit(EXIT_FAILURE);
        }

        record->dynamicLongPtr = dynamicLongPtr;
        *record->dynamicLongPtr = generateSecureRandomInt(0, 10000);

        pthread_mutex_lock(&lock);
        records[i] = record;
        pthread_mutex_unlock(&lock);
    }

    RecordCallback callback = NULL; // Define or pass your custom callback if needed

    for (size_t i = 0; i < recordCount; ++i) {
        processRecord(records[i], callback);
    }

    size_t numberSize;
    int sentinel = -1;
    printf("Enter integers followed by %d to finish:\n", sentinel);

    int* numbers = readIntegers(&numberSize, sentinel);

    pthread_mutex_lock(&lock);
    int maxNumber = findMax(numbers, numberSize);
    pthread_mutex_unlock(&lock);

    printf("The maximum integer is: %d\n", maxNumber);

    freeRecords(offsets, keys, records, recordCount);
    free(numbers);

    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, processRecordsAndFindMax, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        return EXIT_FAILURE;
    }

    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
