#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define STRING_KEY_SIZE 32

typedef struct {
    int value;
    char key[STRING_KEY_SIZE];
    long *offsetPtr;
} Record;

typedef void (*RecordCallback)(Record *);

// Secure random number generation
int secure_random_int(int min, int max) {
    if (min >= max) return min; // Ensure valid range
    return rand_r(NULL) % (max - min + 1) + min; // Simple replacement for demonstration
}

void *resize_array(void *arr_void, size_t old_size, size_t new_size, size_t elem_size);
int findMax(Record *records, int record_count);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

RecordCallback processRecordsAndFindMax(int long_offset_size, int key_size, int record_size,
                                        RecordCallback callback) {
    long *long_offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;
    int *input_integers = NULL;
    size_t input_count = 0;

    if (pthread_mutex_lock(&lock)) {
        perror("Failed to lock mutex");
        return NULL;
    }

    // Initialize arrays
    long_offsets = (long *)malloc(long_offset_size * sizeof(long));
    keys = (int *)malloc(key_size * sizeof(int));
    records = (Record *)malloc(record_size * sizeof(Record));

    if (!long_offsets || !keys || !records) {
        perror("Memory allocation failed");
        free(long_offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Fill long_offsets and keys with sequential numbers
    for (int i = 0; i < long_offset_size; ++i)
        long_offsets[i] = i;

    for (int i = 0; i < key_size; ++i)
        keys[i] = i;

    // Initialize records
    for (int i = 0; i < record_size; ++i) {
        records[i].value = secure_random_int(1, 100);
        snprintf(records[i].key, STRING_KEY_SIZE, "Key_%d", i);
        records[i].offsetPtr = malloc(sizeof(long));
        if (!records[i].offsetPtr || !malloc_is_successful()) {
            perror("Memory allocation for record failed");
            break;
        }
    }

    // Call the callback function
    if (callback) {
        callback(records);
    }

    // Read integers from standard input
    int sentinel = -1, num;
    while (scanf("%d", &num), num != sentinel) {
        pthread_mutex_lock(&lock);

        input_integers = resize_array(input_integers, input_count, input_count + 1, sizeof(int));
        if (!input_integers) {
            perror("Failed to resize integer array");
            break;
        }

        input_integers[input_count++] = num;

        pthread_mutex_unlock(&lock);
    }

    // Find the maximum value
    int max_value = findMax(records, record_size);

    // Logging
    FILE *log_file = fopen("record_log.txt", "a");
    if (log_file) {
        for (int i = 0; i < record_size; ++i) {
            fprintf(log_file, "Record %d: Value=%d, Key=%s\n", i, records[i].value, records[i].key);
        }
        fclose(log_file);
    }

    // Free memory
    free(long_offsets);
    free(keys);
    for (int i = 0; i < record_size; ++i) {
        if (records[i].offsetPtr)
            free(records[i].offsetPtr);
    }
    free(records);
    free(input_integers);

    pthread_mutex_unlock(&lock);

    return callback;
}

void *resize_array(void *arr_void, size_t old_size, size_t new_size, size_t elem_size) {
    if (new_size <= old_size)
        return arr_void;

    void *resized = realloc(arr_void, new_size * elem_size);
    if (!resized && new_size > 0) {
        perror("Failed to resize array");
        return NULL;
    }
    memset((char *)resized + old_size * elem_size, 0, (new_size - old_size) * elem_size);
    return resized;
}

int findMax(Record *records, int record_count) {
    if (!records || record_count <= 0)
        return INT_MIN;

    int max_value = records[0].value;
    for (int i = 1; i < record_count; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    return max_value;
}

// Helper function to check malloc success
int malloc_is_successful() {
    return errno != ENOMEM;
}
