#define MAX_ERROR_MSG_LENGTH 256
static char error_message[MAX_ERROR_MSG_LENGTH];

void log_error(const char* msg) {
    snprintf(error_message, sizeof(error_message), "%s", msg);
}

// Thread-safe function to generate a secure random number within a range
int secure_random(int min, int max, unsigned int *seedp) {
    if (*seedp == 0)
        *seedp = time(NULL); // Default seed value

    srand(*seedp);
    return rand() % (max - min + 1) + min;
}

// Function to process records and find the maximum integer value
long processRecordsAndFindMax(int offset_size, int key_size, int record_count,
                              unsigned int *random_seed, RecordCallback callback) {

    long max_value = LONG_MIN;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize offset array
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    if (!offsets) { log_error("Failed to allocate memory for offsets"); goto cleanup; }
    for (int i = 0; i < offset_size; ++i)
        offsets[i] = (long)i;

    // Initialize key array
    int* keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) { log_error("Failed to allocate memory for keys"); goto cleanup_offsets; }
    for (int i = 0; i < key_size; ++i)
        keys[i] = i;

    // Dynamically allocate and initialize the record array
    Record* records = (Record*)malloc(record_count * sizeof(Record));
    if (!records) { log_error("Failed to allocate memory for records"); goto cleanup_keys; }

    for (int i = 0; i < record_count; ++i) {
        int value = secure_random(-100, 100, random_seed);

        pthread_mutex_lock(&mutex);
        records[i].value = value;
        snprintf(records[i].key, sizeof(records[i].key), "Key%d", keys[i % key_size]);
        records[i].ptr_long = (long*)malloc(sizeof(long));
        if (!records[i].ptr_long) { 
            log_error("Failed to allocate memory for long pointer in record");
            goto cleanup_records;
        }
        *records[i].ptr_long = offsets[i % offset_size];
        pthread_mutex_unlock(&mutex);

        // Update max_value
        if (value > max_value)
            max_value = value;

        // Callback function processing
        if (callback) {
            callback(&records[i]);
        }
    }

    // Cleanup and return the maximum value found
cleanup_records:
    for (int i = 0; i < record_count; ++i) {
        free(records[i].ptr_long);
    }
cleanup_keys:
    free(keys);
cleanup_offsets:
    free(offsets);

    pthread_mutex_destroy(&mutex);
    free(records);

    if (error_message[0] != '\0') {
        fprintf(stderr, "Error: %s\n", error_message);
    }

    return max_value;
}

// Example of a callback function
void example_callback(Record* record) {
    printf("Processing Record with Value: %d and Key: %s\n", record->value, record->key);
}

int main() {
    unsigned int seed = 42; // Custom seed for reproducibility

    long max_value = processRecordsAndFindMax(
        1000, 500, 200, &seed, example_callback
    );

    printf("Maximum Value: %ld\n", max_value);
    return 0;
}
