    exit(EXIT_FAILURE);
}

long find_max_in_array(int *array, size_t length) {
    if (length == 0) return LONG_MIN; // Adjust based on actual expected range
    long max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

