}

long processRecordsAndFindMax(size_t count, int seed, long data_min, long data_max) {
    if (count == 0) return LONG_MIN;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long *offsets = malloc(count * sizeof(long));
    int *keys = malloc(count * sizeof(int));
    record *records = malloc(count * sizeof(record));

    if (!offsets || !keys || !records) {
        handle_error("Memory allocation failed");
    }

    srand48(seed);
    int input_size;
    printf("Enter the number of integers: ");
    scanf("%d", &input_size);

    if (input_size <= 0) return LONG_MIN;

    int *inputs = malloc(input_size * sizeof(int));
    if (!inputs) {
        handle_error("Memory allocation for inputs failed");
    }

    pthread_mutex_lock(&mutex);
    printf("Enter %d integers: ", input_size);
    for (int i = 0; i < input_size; ++i) {
        scanf("%d", &inputs[i]);
    }
    pthread_mutex_unlock(&mutex);

    long max_input = find_max_in_array(inputs, input_size);

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = i;
        keys[i] = i;

        records[i].offset = offsets[i];
        records[i].key = keys[i];

        records[i].data = malloc(sizeof(long));
        if (!records[i].data) {
            handle_error("Memory allocation for record data failed");
        }

        *records[i].data = lrand48() % (data_max - data_min + 1) + data_min;
    }

    for (size_t i = 0; i < count; ++i) {
        processRecordCallback(&records[i]);
    }

    free(inputs);
    for (size_t i = 0; i < count; ++i) {
        free(records[i].data);
    }
    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&mutex);

    return max_input;
}

int main() {
    size_t num_records = 10;
    int seed = 12345;
    long data_min = -1000;
    long data_max = 1000;

    long max_value = processRecordsAndFindMax(num_records, seed, data_min, data_max);
    printf("Maximum input value: %ld\n", max_value);

    return 0;
}
