                return -1;
            }
            array->data = new_data;
            array->capacity = new_capacity;
        }
        array->data[array->size++] = temp;
        pthread_mutex_unlock(&array->lock);
    }

    fclose(file);
    return 0;
}

void initialize_records(Record *records, size_t count, int min_key, int max_key) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].key = min_key + rand() % (max_key - min_key + 1);
        char name[20];
        snprintf(name, sizeof(name), "ID_%d", records[i].key);
        records[i].name = strdup(name); // Allocate and copy
    }
}

void find_and_print_largest(SafeIntArray *array, Node* head) {
    int largest = INT_MIN;
    Record* corresponding_record = NULL;

    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
            corresponding_record = find_record_by_key(head, largest); // Assuming function exists
        }
    }
    pthread_mutex_unlock(&array->lock);

    if (corresponding_record != NULL) {
        printf("Largest integer: %d, Record name: %s\n", largest, corresponding_record->name);
    } else {
        printf("No records found for the largest integer.\n");
    }
}

Record* find_record_by_key(Node* head, int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->record.key == key) return &current->record;
        current = current->next;
    }
    return NULL;
}

void free_records(Node *head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->record.name);
        free(current);
        current = next;
    }
}

void manage_records_and_integers(const char* filename, size_t record_count, int min_key, int max_key) {
    Record *records = malloc(record_count * sizeof(Record));
    if (!records) exit(EXIT_FAILURE);

    initialize_records(records, record_count, min_key, max_key);

    Node head_node;
    head_node.next = NULL;

    // Convert array to linked list
    for (size_t i = 0; i < record_count; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) exit(EXIT_FAILURE);
        new_node->record = records[i];
        new_node->next = head_node.next;
        head_node.next = new_node;
    }

    SafeIntArray int_array = { .data = NULL, .size = 0, .capacity = 0 };
    pthread_mutex_init(&int_array.lock, NULL);

    if (read_integers_from_file(filename, &int_array) != 0) {
        fprintf(stderr, "Error reading integers from file.\n");
        free_records(head_node.next);
        pthread_mutex_destroy(&int_array.lock);
        free(records);
        exit(EXIT_FAILURE);
    }

    find_and_print_largest(&int_array, head_node.next);

    // Cleanup
    free(int_array.data);
    pthread_mutex_destroy(&int_array.lock);
    free(records);
    free_records(head_node.next);
}

int main() {
    manage_records_and_integers("input.txt", 1000, 1, 100);
    return 0;
}
