#include <string.h>

#define MAX_ENTRIES 1000

typedef struct {
    char *key;
    long value;
} Entry;

Entry* create_entries_array(size_t num_entries, const char *const keys[], int reject_duplicates) {
    if (num_entries > MAX_ENTRIES) {
        fprintf(stderr, "Exceeded maximum number of entries.\n");
        return NULL;
    }

    Entry *entries = malloc(num_entries * sizeof(Entry));
    if (!entries) {
        perror("Memory allocation failed for entries array");
        return NULL;
    }

    // Track keys to detect duplicates
    char **key_tracker = malloc(num_entries * sizeof(char *));
    if (!key_tracker) {
        free(entries);
        perror("Memory allocation failed for key tracker");
        return NULL;
    }

    int used_count = 0;

    for (size_t i = 0; i < num_entries; ++i) {
        const char *key = keys[i];

        // Check for duplicates
        if (reject_duplicates) {
            for (int j = 0; j < used_count; ++j) {
                if (strcmp(key_tracker[j], key) == 0) {
                    fprintf(stderr, "Duplicate key detected: %s\n", key);
                    continue;
                }
            }
        }

        // Allocate memory and copy the key
        entries[used_count].key = strdup(key);
        if (!entries[used_count].key) {
            perror("Memory allocation failed for entry key");
            free_entries_array(entries, used_count); // Free allocated keys up to this point
            free(key_tracker);
            return NULL;
        }

        entries[used_count].value = (long)(used_count + 1);

        if (!reject_duplicates || strcmp(key_tracker[j], key) != 0) {
            key_tracker[used_count] = strdup(key); // Store the unique key
            if (!key_tracker[used_count]) {
                perror("Memory allocation failed for key tracker");
                free_entries_array(entries, used_count + 1);
                free(key_tracker);
                return NULL;
            }
        }

        ++used_count;  // Only increment count on successful addition
    }

    free(key_tracker);  // Clean up the temporary key tracking array
    return entries;
}

void free_entries_array(Entry *entries, size_t num_entries) {
    if (!entries) return;

    for (size_t i = 0; i < num_entries; ++i) {
        free(entries[i].key);
    }
    free(entries);
}

int main() {
    const char *keys[] = {"apple", "banana", "orange", "grape", "apple"};
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    Entry *entries = create_entries_array(num_keys, keys, 1); // Reject duplicates

    if (entries) {
        for (size_t i = 0; i < num_keys && entries[i].key != NULL; ++i) {
            printf("Key: %s, Value: %ld\n", entries[i].key, entries[i].value);
        }
        free_entries_array(entries, num_keys);
    }

    return 0;
}
