#include <stdio.h>
#include <stdlib.h>
import json
import hashlib

// Offset Array
void manage_offset_array(long** offsetArray, size_t* size) {
    if (*offsetArray == NULL || *size <= 0) return;

    long* newOffsets = realloc(*offsetArray, (*size) * sizeof(long));
    if (newOffsets == NULL) {
        perror("Failed to allocate memory for Offset Array");
        exit(EXIT_FAILURE);
    }

    // Initialize with zero
    for (size_t i = 0; i < *size; ++i) {
        newOffsets[i] = 0;
    }
    *offsetArray = newOffsets;
}

// Key Array from JSON
void load_key_array(int** keyArray, size_t* size, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open JSON configuration file");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* jsonStr = malloc(fsize + 1);
    fread(jsonStr, 1, fsize, file);
    fclose(file);

    jsonStr[fsize] = '\0';

    // Parsing JSON
    struct json_object *parsed_json;
    struct json_object *keys_array;

    parsed_json = json_tokener_parse(jsonStr);
    if (!json_object_get_type(parsed_json) == json_type_array) {
        fprintf(stderr, "Error parsing JSON: Expected an array of keys\n");
        free(jsonStr);
        exit(EXIT_FAILURE);
    }

    json_object_object_get_ex(parsed_json, "keys", &keys_array);
    *size = json_object_array_length(keys_array);

    // Allocate memory
    *keyArray = malloc(*size * sizeof(int));
    if (*keyArray == NULL) {
        perror("Failed to allocate memory for Key Array");
        free(jsonStr);
        exit(EXIT_FAILURE);
    }

    // Load keys from JSON
    for (size_t i = 0; i < *size; ++i) {
        struct json_object* key_obj;
        json_object_array_get_idx(keys_array, i, &key_obj);

        if (json_object_get_type(key_obj) != json_type_int) {
            fprintf(stderr, "Error parsing JSON: Expected integer keys\n");
            free(*keyArray);
            free(jsonStr);
            exit(EXIT_FAILURE);
        }

        (*keyArray)[i] = json_object_get_int(key_obj);
    }

    free(jsonStr);
}

// Record Structures
