    int value;
} record;

void initialize_records(record** records, size_t size, int min_val, int max_val) {
    if (*records == NULL || size <= 0) return;

    *records = malloc(size * sizeof(record));
    if (*records == NULL) {
        perror("Failed to allocate memory for Record Structures");
        exit(EXIT_FAILURE);
    }

    // Initialize with random values
    #include <time.h>
    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = min_val + rand() % (max_val - min_val + 1);
    }
}

// MD5 Hashing
void compute_md5_hash(const char* input, unsigned char** hash_output) {
    struct md5_state_s mdctx;
    int i;

    md5_init(&mdctx);
    md5_append(&mdctx, (const unsigned char*)input, strlen(input));
    md5_finish(&mdctx, *hash_output);

    for (i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", (*hash_output)[i]);
    }
    printf("\n");
}

// Example Usage
int main() {
    long* offsetArray = NULL;
    size_t offsetSize = 10;

    // Manage Offset Array
    manage_offset_array(&offsetArray, &offsetSize);

    // Load Key Array from JSON
    int* keyArray = NULL;
    size_t keySize = 0;
    load_key_array(&keyArray, &keySize, "config.json");

    // Initialize Records
    record* records = NULL;
    size_t recordSize = 5;
    initialize_records(&records, recordSize, 1, 100);

    // Compute MD5 Hash
    unsigned char* hash_output = malloc(MD5_DIGEST_LENGTH);
    if (!hash_output) {
        perror("Failed to allocate memory for MD5 hash output");
        exit(EXIT_FAILURE);
    }

    compute_md5_hash("Sample String", &hash_output);

    free(offsetArray);
    free(keyArray);
    free(records);
    free(hash_output);

    return 0;
}
