int can_allocate(size_t size) {
    long avail_mem = available_memory();
    if (size > (avail_mem / 2)) {
        fprintf(stderr, "Not enough memory to allocate %zu bytes\n", size);
        return 0;
    }
    return 1;
}

void init_records(record **records, int *num_records, long offset_size, int key_size,
                  int min_val, int max_val) {
    if (!can_allocate((*num_records) * (sizeof(long) + sizeof(int) + sizeof(record)))) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    *records = malloc(*num_records * sizeof(record));
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));

    if (!*records || !offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*records);
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    srand(time(NULL));

    int used_values[MAX_RECORDS] = {0};
    int value_count = 0;

    for (int i = 0; i < *num_records; ++i) {
        record *rec = &(*records)[i];
        rec->offset_ptr = &offsets[i];
        rec->key_ptr = &keys[i];

        // Generate unique random values
        while (1) {
            int rand_val = min_val + rand() % (max_val - min_val + 1);
            if (!used_values[rand_val]) {
                used_values[rand_val] = 1;
                value_count++;
                rec->value = rand_val;
                break;
            }
        }

        // Adjust for possible collisions
        if (value_count >= (max_val - min_val + 1)) {
            fprintf(stderr, "Unable to generate unique values within the specified range\n");
            free(*records);
            free(offsets);
            free(keys);
            exit(EXIT_FAILURE);
        }
    }

    printf("Memory allocation and initialization successful.\n");
}

void adjust_record_count_based_on_load(int *record_count) {
    // Dynamic adjustment logic based on system load
    long avail_mem = available_memory();
    int max_records_based_on_mem = (avail_mem / 2) / (sizeof(long) + sizeof(int) + sizeof(record));

    if (*record_count > MAX_RECORDS || *record_count > max_records_based_on_mem) {
        *record_count = (MAX_RECORDS < max_records_based_on_mem) ? MAX_RECORDS : max_records_based_on_mem;
    }
}

void process_data(int num_records, int min_val, int max_val) {
    long offset_size = num_records; // Assume 1:1 mapping for demonstration
    int key_size = num_records;

    adjust_record_count_based_on_load(&num_records);

    record *records;
    init_records(&records, &num_records, offset_size, key_size, min_val, max_val);

    // Additional concurrent data processing logic can be added here

    free(records);
}

int main() {
    int num_records = 10000; // Example user input
    int min_val = 0;
    int max_val = 9999;

    process_data(num_records, min_val, max_val);

    return 0;
}
