typedef struct {
    char* message;
    int severity;
    unsigned long timestamp;
} Record;

Record** processAndFilterRecords(Record* records, size_t num_records, int min_severity, const char* format_string) {
    if (records == NULL || format_string == NULL) {
        return NULL;
    }

    // First pass to count the number of valid records
    size_t valid_count = 0;
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].severity >= min_severity) {
            ++valid_count;
        }
    }

    if (valid_count == 0) {
        return NULL;
    }

    // Allocate memory for the filtered records array
    Record** filtered_records = malloc(valid_count * sizeof(Record*));
    if (filtered_records == NULL) {
        return NULL; // Memory allocation failed
    }

    size_t index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].severity >= min_severity) {
            // Allocate and initialize the filtered record
            Record* new_record = malloc(sizeof(Record));
            if (new_record == NULL) {
                // Free allocated memory in case of failure
                for (size_t j = 0; j < index; ++j) {
                    free(filtered_records[j]->message);
                    free(filtered_records[j]);
                }
                free(filtered_records);
                return NULL;
            }

            new_record->severity = records[i].severity;
            new_record->timestamp = records[i].timestamp;

            // Allocate and format the message
            if (asprintf(&new_record->message, format_string, records[i].timestamp) == -1) {
                free(new_record);
                for (size_t j = 0; j < index; ++j) {
                    free(filtered_records[j]->message);
                    free(filtered_records[j]);
                }
                free(filtered_records);
                return NULL;
            }

            filtered_records[index++] = new_record;
        }
    }

    // Shrink the array to the exact number of valid records
    if (index < valid_count) {
        Record** temp = realloc(filtered_records, index * sizeof(Record*));
        if (temp == NULL) {
            for (size_t j = 0; j < index; ++j) {
                free(filtered_records[j]->message);
                free(filtered_records[j]);
            }
            free(filtered_records);
            return NULL;
        }
        filtered_records = temp;
    }

    return filtered_records;
}

// Example usage
int main() {
    Record records[] = {
        {"Message 1", 2, 1627849123},
        {"Message 2", 5, 1627849134},
        {"Message 3", 1, 1627849145}
    };

    int min_severity = 3;
    const char* format_string = "Timestamp: %lu";

    Record** filtered = processAndFilterRecords(records, 3, min_severity, format_string);

    if (filtered != NULL) {
        for (size_t i = 0; filtered[i] != NULL; ++i) {
            printf("Filtered Record: %s\n", filtered[i]->message);
            free(filtered[i]->message);
            free(filtered[i]);
        }
        free(filtered);
    } else {
        printf("No records met the severity threshold.\n");
    }

    return 0;
}
