        for (size_t i = 0; i < pluginCount; ++i) {
            free(plugins[i]); // Free plugins after use
        }
        free(plugins); // Free array of plugin pointers

        json_decref(root);
    } else {
        asprintf(errorLog, "Invalid JSON: Root is not an object");
        json_decref(root);
        return -3; // Invalid root type error
