} FileMetadata;

// Function prototype for user-defined callback
void (*process_chunk_callback)(FileMetadata*);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to validate and save a chunk
void validateAndSaveChunk(FileMetadata *metadata) {
    // Validation logic (e.g., checksum, size verification)
    // Save the chunk data to file or process it further

    // Simulate saving by printing metadata info
    printf("Saving %zu bytes of '%s' with timestamp %ld\n", 
           metadata->size, metadata->filename, metadata->timestamp);
