// Function for memory allocation and initialization
void allocateAndInitializeRecordsAndChunks(int num_records, int range_min, int range_max,
                                          unsigned int seed_for_timestamp,
                                          void (*callback)(FileMetadata*)) {
    // Seed the random number generator for reproducibility
    srand(seed_for_timestamp);

    // Allocate memory for records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    // Initialize records with random values
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = i;
        records[i].random_value = range_min + rand() % (range_max - range_min + 1);
    }

    // Array to hold file metadata
    FileMetadata *metadata_array = NULL;

    // Read file paths from standard input
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        size_t filename_len = strlen(buffer) - 1;
        if (buffer[filename_len] == '\n') {
            buffer[filename_len] = '\0';  // Remove newline character
        }

        // Allocate memory for file metadata entry
        FileMetadata *metadata = (FileMetadata *)malloc(sizeof(FileMetadata));
        if (!metadata) {
            fprintf(stderr, "Failed to allocate memory for file metadata\n");
            free(records);
            return;
        }

        // Initialize metadata fields
        metadata->filename = strdup(buffer);
        metadata->size = rand() % 1024 + 1;  // Random size between 1 and 1024 bytes
        metadata->timestamp = time(NULL);    // Use current time

        // Allocate memory for chunk data with alternating 0s and 1s pattern
        metadata->chunk_data = (unsigned char *)malloc(metadata->size);
        if (!metadata->chunk_data) {
            fprintf(stderr, "Failed to allocate memory for chunk data\n");
            free(metadata->filename);
            free(metadata);
            continue;  // Skip this file and continue with the next
        }

        for (size_t j = 0; j < metadata->size; ++j) {
            metadata->chunk_data[j] = (j % 2 == 0) ? 0 : 1;
        }

        // Lock mutex before appending to array
        pthread_mutex_lock(&mutex);
        metadata_array = realloc(metadata_array, sizeof(FileMetadata) * (metadata_array ? num_records + 1 : 1));
        if (!metadata_array) {
            fprintf(stderr, "Failed to reallocate memory for file metadata array\n");
            free(metadata->chunk_data);
            free(metadata->filename);
            free(metadata);
            pthread_mutex_unlock(&mutex);
            continue;
        }

        if (metadata_array) {
            memcpy(&metadata_array[num_records], metadata, sizeof(FileMetadata));
        } else {
            memcpy(metadata_array, metadata, sizeof(FileMetadata));
        }
        num_records++;
        pthread_mutex_unlock(&mutex);

        // Validate and save chunk
        validateAndSaveChunk(metadata);

        // Call the user-defined callback if provided
        if (callback) {
            callback(metadata);
        }
    }

    // Free allocated memory for records and metadata array
    free(records);

    // Free file metadata entries
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);
        if (metadata_array[i].filename) {
            free(metadata_array[i].filename);
        }
        if (metadata_array[i].chunk_data) {
            free(metadata_array[i].chunk_data);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Free metadata array
    free(metadata_array);
}
