#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Predefined list of unique string literals for keys.
const char *predefined_keys[] = {
    "alpha", "beta", "gamma", "delta", "epsilon",
    // Add more predefined keys as needed...
};

typedef struct {
    char* key;
    long value;
} Entry;

typedef struct {
    Entry* entries;
    size_t capacity;
    size_t count;
} Collection;

// Function to handle memory allocation errors.
void handle_allocation_error(void (*callback)(const char*)) {
    if (callback) {
        callback("Memory allocation failed");
    }
}

// Function to initialize a new collection with a given initial size.
Collection* create_collection(size_t initial_size, void (*error_callback)(const char*)) {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) {
        handle_allocation_error(error_callback);
        return NULL;
    }

    collection->entries = calloc(initial_size, sizeof(Entry));
    if (!collection->entries) {
        free(collection);
        handle_allocation_error(error_callback);
        return NULL;
    }

    collection->capacity = initial_size;
    collection->count = 0;

    for (size_t i = 0; i < initial_size && i < sizeof(predefined_keys)/sizeof(predefined_keys[0]); ++i) {
        collection->entries[i].key = strdup(predefined_keys[i]);
        if (!collection->entries[i].key) {
            handle_allocation_error(error_callback);
            // Free already allocated entries.
            for (size_t j = 0; j < i; ++j) {
                free(collection->entries[j].key);
            }
            free(collection->entries);
            free(collection);
            return NULL;
        }
        collection->entries[i].value = i + 1; // Unique ID starting from 1.
    }

    return collection;
}

// Function to resize the collection's capacity.
int resize_collection(Collection *collection, size_t new_capacity, void (*error_callback)(const char*)) {
    Entry* temp = realloc(collection->entries, new_capacity * sizeof(Entry));
    if (!temp) {
        handle_allocation_error(error_callback);
        return -1;
    }

    collection->entries = temp;
    collection->capacity = new_capacity;

    // Initialize newly allocated entries.
    for (size_t i = collection->count; i < new_capacity && i < sizeof(predefined_keys)/sizeof(predefined_keys[0]); ++i) {
        collection->entries[i].key = strdup(predefined_keys[i]);
        if (!collection->entries[i].key) {
            handle_allocation_error(error_callback);
            // Free newly allocated keys.
            for (size_t j = collection->count; j < i; ++j) {
                free(collection->entries[j].key);
            }
            return -1;
        }
        collection->entries[i].value = i + 1;
    }

    return 0;
}

// Function to add a new entry with an external key.
int add_entry(Collection *collection, const char* key, long value, void (*error_callback)(const char*)) {
    if (collection->count == collection->capacity) {
        if (resize_collection(collection, collection->capacity ? collection->capacity * 2 : 1, error_callback)) {
            return -1;
        }
    }

    Entry *new_entry = &collection->entries[collection->count];
    new_entry->key = strdup(key);
    if (!new_entry->key) {
        handle_allocation_error(error_callback);
        return -1;
    }

    new_entry->value = ++collection->count; // Unique ID.
    return 0;
}

// Function to remove an entry by its key.
int remove_entry(Collection *collection, const char* key, void (*error_callback)(const char*)) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->entries[i].key, key) == 0) {
            free(collection->entries[i].key);
            // Shift subsequent entries.
            memmove(&collection->entries[i], &collection->entries[i + 1],
                    (collection->count - i - 1) * sizeof(Entry));
            collection->count--;
            return 0;
        }
    }
    return -1; // Entry not found.
}

// Function to free the collection and its entries.
void destroy_collection(Collection *collection, void (*error_callback)(const char*)) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            free(collection->entries[i].key);
        }
        free(collection->entries);
        free(collection);
    }
}

// Example error handling callback.
void my_error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
