#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    char description[256];
    float *priority;
} Event;

typedef void (*EventCallback)(Event *);

// Simulated external library function for priority calculation
float calculatePriority(int timestamp, int seed) {
    return (float)timestamp * 0.5f + seed % 10; // Simplified example formula
}

void handleDataStreamAndFilterEvents(int eventCount, float multiplier, int seed,
                                     EventCallback callback, int minPriorityThreshold) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    Event *events = NULL;
    events = (Event *)malloc(eventCount * sizeof(Event));
    if (!events) {
        fprintf(stderr, "Memory allocation failed for events\n");
        goto cleanup;
    }

    // Initialize eventTimestamp and eventDescription arrays
    for (int i = 0; i < eventCount; ++i) {
        events[i].timestamp = i;

        snprintf(events[i].description, sizeof(events[i].description), "Event %d", i);

        float calculatedPriority = calculatePriority(i, seed) * multiplier;
        if (calculatedPriority >= minPriorityThreshold) {
            events[i].priority = (float *)malloc(sizeof(float));
            if (!events[i].priority) {
                fprintf(stderr, "Memory allocation failed for event priority\n");
                goto cleanup;
            }
            *events[i].priority = calculatedPriority;

            // Process each event with the callback
            if (callback != NULL) {
                pthread_mutex_lock(&lock);
                (*callback)(&events[i]);
                pthread_mutex_unlock(&lock);
            }
        } else {
            events[i].priority = NULL;
        }
    }

cleanup:
    for (int i = 0; i < eventCount; ++i) {
        if (events[i].priority) {
            free(events[i].priority);
        }
    }
    free(events);
    pthread_mutex_destroy(&lock);
}

void exampleCallback(Event *event) {
    printf("Processing Event: %d, Description: %s, Priority: %.2f\n",
           event->timestamp, event->description, *(event->priority));
}

int main() {
    int eventCount = 10;
    float multiplier = 1.5;
    int seed = 42;

    handleDataStreamAndFilterEvents(eventCount, multiplier, seed, exampleCallback, 20.0);
    return 0;
}
```

