    int value;
} config;

typedef struct hash_node {
    int id;
    void *data; // Can point to node or connection
    struct hash_node* next;
} hash_node;

typedef struct {
    hash_node** buckets;
    size_t bucket_count;
} hashtable;

void init_random() {
    srand((unsigned)time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Hash table functions
hashtable* create_hashtable(size_t bucket_count) {
    hashtable* ht = malloc(sizeof(hashtable));
    ht->buckets = calloc(bucket_count, sizeof(hash_node*));
    ht->bucket_count = bucket_count;
    return ht;
}

unsigned int hash(int id, size_t bucket_count) {
    return id % bucket_count;
}

void insert_into_hashtable(hashtable* ht, int id, void* data) {
    unsigned int index = hash(id, ht->bucket_count);
    hash_node* new_node = malloc(sizeof(hash_node));
    new_node->id = id;
    new_node->data = data;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
}

