    Resource configSetting = {.name = strdup("maxConnections"),
                              .type = INTEGER,
                              .intValue = 100,
                              .defaultValue = malloc(sizeof(int)),
                              .currentValue = malloc(sizeof(int)),
                              *(int *)configSetting.defaultValue = 100,
                              *(int *)configSetting.currentValue = 100,
                              .version = 1};
    strcpy(configSetting.uniqueID, "UUID-1234");

    addResource(resourceManager, &configSetting);

    updateResource(resourceManager, "maxConnections", malloc(sizeof(int)));
    *(int *)configSetting.currentValue = 200;

    Resource *foundResource = findResource(resourceManager, "maxConnections");
    if (foundResource) {
        printf("Max Connections: %d\n", *(int *)(foundResource->currentValue));
    }

    destroyResourceManager(resourceManager);
    return 0;
}
