#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define resource structure
typedef struct {
    char name[50];
    char type[20];
    union {
        double double_val;
        int int_val;
        float float_val;
    } default_value, current_value;
    char unique_id[30];
    unsigned int version_number;
} Resource;

// Define chunk structure
typedef struct {
    double value;
} DataChunk;

// Global variables for resource and data management
Resource *resources = NULL;
DataChunk *data_chunks = NULL;
size_t resources_count = 0, chunks_count = 0;

pthread_mutex_t resource_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t chunk_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new resource
void init_resource(const char *name, const char *type, union {
    double d_val;
    int i_val;
    float f_val;
} default_value, const char *unique_id) {
    pthread_mutex_lock(&resource_lock);

    resources = realloc(resources, (resources_count + 1) * sizeof(Resource));
    if (!resources) {
        perror("Failed to allocate memory for resource");
        pthread_mutex_unlock(&resource_lock);
        return;
    }

    Resource new_resource;
    strncpy(new_resource.name, name, sizeof(new_resource.name));
    strncpy(new_resource.type, type, sizeof(new_resource.type));

    if (strcmp(type, "double") == 0) {
        new_resource.default_value.double_val = default_value.d_val;
        new_resource.current_value.double_val = default_value.d_val;
    } else if (strcmp(type, "int") == 0) {
        new_resource.default_value.int_val = default_value.i_val;
        new_resource.current_value.int_val = default_value.i_val;
    } else if (strcmp(type, "float") == 0) {
        new_resource.default_value.float_val = default_value.f_val;
        new_resource.current_value.float_val = default_value.f_val;
    }

    strncpy(new_resource.unique_id, unique_id, sizeof(new_resource.unique_id));
    new_resource.version_number = 1;

    resources[resources_count++] = new_resource;

    pthread_mutex_unlock(&resource_lock);
}

// Function to initialize a new data chunk
void init_data_chunk(double value) {
    pthread_mutex_lock(&chunk_lock);

    data_chunks = realloc(data_chunks, (chunks_count + 1) * sizeof(DataChunk));
    if (!data_chunks) {
        perror("Failed to allocate memory for data chunk");
        pthread_mutex_unlock(&chunk_lock);
        return;
    }

    DataChunk new_chunk = { .value = value };
    data_chunks[chunks_count++] = new_chunk;

    pthread_mutex_unlock(&chunk_lock);
}

// Function to free resources and chunks
void cleanup_resources() {
    pthread_mutex_lock(&resource_lock);
    free(resources);
    resources = NULL;
    resources_count = 0;
    pthread_mutex_unlock(&resource_lock);

    pthread_mutex_lock(&chunk_lock);
    free(data_chunks);
    data_chunks = NULL;
    chunks_count = 0;
    pthread_mutex_unlock(&chunk_lock);
}

// Function to allocate and initialize arrays
void allocate_and_init_arrays(long **offsets, int **keys, struct record ***records1, struct record ***records2, char ***metadata_tags) {
    size_t size = 10; // Example size

    *offsets = malloc(size * sizeof(long));
    if (!*offsets) { perror("Failed to allocate memory for offsets"); exit(EXIT_FAILURE); }

    *keys = malloc(size * sizeof(int));
    if (!*keys) { free(*offsets); perror("Failed to allocate memory for keys"); exit(EXIT_FAILURE); }

    *records1 = malloc(size * sizeof(struct record *));
    if (!*records1) { free(*offsets); free(*keys); perror("Failed to allocate memory for records1"); exit(EXIT_FAILURE); }

    for (size_t i = 0; i < size; ++i) {
        (*records1)[i] = malloc(sizeof(struct record));
        if (!(*records1)[i]) { 
            while (--i >= 0) free((*records1)[i]); 
            free(*records1); *records1 = NULL;
            free(*keys);
            free(*offsets);
            perror("Failed to allocate memory for a record in records1");
            exit(EXIT_FAILURE);
        }
    }

    *records2 = malloc(size * sizeof(struct record *));
    if (!*records2) { 
        while (size-- > 0) free((*records1)[size]); 
        free(*records1); *records1 = NULL;
        free(*keys);
        free(*offsets);
        perror("Failed to allocate memory for records2");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        (*records2)[i] = malloc(sizeof(struct record));
        if (!(*records2)[i]) { 
            while (--i >= 0) free((*records2)[i]); 
            free(*records2); *records2 = NULL;
            while (size-- > 0) free((*records1)[size]);
            free(*records1); *records1 = NULL;
            free(*keys);
            free(*offsets);
            perror("Failed to allocate memory for a record in records2");
            exit(EXIT_FAILURE);
        }
    }

    *metadata_tags = malloc(size * sizeof(char *));
    if (!*metadata_tags) { 
        while (size-- > 0) free((*records2)[size]); 
        free(*records2); *records2 = NULL;
        while (size-- > 0) free((*records1)[size]);
        free(*records1); *records1 = NULL;
        free(*keys);
        free(*offsets);
        perror("Failed to allocate memory for metadata tags");
        exit(EXIT_FAILURE);
