    if (!keys) {
        free(offsets);
        perror("Failed to allocate keys");
        return;
    }

    for (size_t i = 0; i < offsetSize; ++i) offsets[i] = (long)i;
    for (size_t i = 0; i < keySize; ++i) keys[i] = i;

    // Allocate and initialize node, connection, request, and module arrays
    size_t nodeCount = minNodes + rand() % (maxNodes - minNodes + 1);
    Node *nodes = (Node *)calloc(nodeCount, sizeof(Node));
    if (!nodes) {
        free(offsets); free(keys);
        perror("Failed to allocate nodes");
        return;
    }

    size_t connectionCount = minConnections + rand() % (maxConnections - minConnections + 1);
    Connection *connections = (Connection *)calloc(connectionCount, sizeof(Connection));
    if (!connections) {
        free(offsets); free(keys); free(nodes);
        perror("Failed to allocate connections");
        return;
    }

    size_t requestCount = minRequests + rand() % (maxRequests - minRequests + 1);
    Request *requests = NULL;
    for (size_t i = 0; i < requestCount; ++i) {
        Request *newRequest = (Request *)malloc(sizeof(Request));
        if (!newRequest) {
            // Free previous requests
            while (requests) {
                Request *temp = requests;
                requests = requests->next;
                free(temp);
            }
            perror("Failed to allocate request");
            free(offsets); free(keys); free(nodes); free(connections);
            return;
        }
        newRequest->id = i;
        newRequest->next = requests;
        requests = newRequest;
    }

    size_t moduleCount = minModules + rand() % (maxModules - minModules + 1);
    Module *modules = (Module *)calloc(moduleCount, sizeof(Module));
    if (!modules) {
        free(offsets); free(keys); free(nodes); free(connections);
        while (requests) {
            Request *temp = requests;
            requests = requests->next;
            free(temp);
        }
        perror("Failed to allocate modules");
        return;
    }

    // Initialize hash table
    HashTable hashTable = { .nodes = {0}, .requests = {0} };

    // Fill nodes with random data
    for (size_t i = 0; i < nodeCount; ++i) {
        sprintf(nodes[i].ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        nodes[i].port = rand() % 65536;
        nodes[i].lastActivity = time(NULL);
        nodes[i].refCount = 0;
        addNode(&hashTable, nodes[i]);
    }

    // Fill connections with random data
    for (size_t i = 0; i < connectionCount; ++i) {
        connections[i].status = rand() % 2;
        connections[i].bandwidth = (float)(rand() % 1000);
        connections[i].latency = (float)(rand() % 500);
        pthread_mutex_init(&connections[i].mutex, NULL);
    }

    // Read integers from standard input into a dynamic array
    int *inputNumbers = NULL;
    size_t capacity = 10;
    inputNumbers = (int *)malloc(capacity * sizeof(int));
    if (!inputNumbers) {
        perror("Failed to allocate initial input numbers");
        free(offsets); free(keys); free(nodes); free(connections);
        while (requests) {
            Request *temp = requests;
            requests = requests->next;
            free(temp);
        }
        free(modules);
        return;
    }

    int num, count = 0;
    printf("Enter integers (-1 to stop): ");
    while (scanf("%d", &num) == 1 && num != -1) {
        if (count >= capacity) {
            capacity *= 2;
            inputNumbers = (int *)realloc(inputNumbers, capacity * sizeof(int));
            if (!inputNumbers) {
                perror("Failed to reallocate input numbers");
                free(offsets); free(keys); free(nodes); free(connections);
                while (requests) {
                    Request *temp = requests;
                    requests = requests->next;
                    free(temp);
                }
                free(modules);
                return;
            }
        }
        inputNumbers[count++] = num;
    }

    // Handle malformed input
    if (scanf("%*s") != 0) {
        printf("Warning: Malformed input detected\n");
    }

    // Execute callback function if provided
    if (callback) callback();

    // Cleanup
    free(offsets); free(keys);
    free(nodes); free(connections);
    while (requests) {
        Request *temp = requests;
        requests = requests->next;
        free(temp);
    }
    free(modules);
    free(inputNumbers);

    // Destroy mutexes in connections
    for (size_t i = 0; i < connectionCount; ++i) {
        pthread_mutex_destroy(&connections[i].mutex);
    }
}

unsigned int hash(unsigned char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;

    return hash % HASH_TABLE_SIZE;
}

int addNode(HashTable *hashTable, Node node) {
    unsigned int index = hash((unsigned char *)node.ip);
    hashTable->nodes[index] = &node;
    return 0;
}

int addRequest(HashTable *hashTable, Request request) {
    unsigned int index = hash((unsigned char *)(request.id));
    request.next = hashTable->requests[index];
    hashTable->requests[index] = &request;
    return 0;
}
