    while (1) {
        int input;
        if (scanf("%d", &input) != 1 || input == -1) break;

        pthread_mutex_lock(&lock);
        if (count >= capacity) {
            size_t new_capacity = capacity * 2;
            Record *new_records = realloc(records, new_capacity * sizeof(Record));
            if (!new_records) {
                free(records);
                return -1;
