        records[count].offset_ptr = malloc(sizeof(long));
        if (!records[count].offset_ptr) {
            free(records);
            return -1;
        }
        pthread_mutex_unlock(&lock);

        processRecord(&records[count], callback);
        max_value = (input > max_value) ? input : max_value;
        count++;
