    for (size_t i = 0; i < count; ++i) {
        max_value = (records[i].value > max_value) ? records[i].value : max_value;
        processRecord(&records[i], callback);
    }

    printf("Maximum value: %d\n", max_value);

    for (size_t i = 0; i < count; ++i) {
        free(records[i].offset_ptr);
    }
    free(records);

    return 0;
}

