typedef void (*SessionCallback)(unsigned long session_id, char* ip_address);

typedef struct {
    unsigned long session_id;
    time_t last_active;
    char *ip_address;
} Session;

typedef struct {
    Session **sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    SessionCallback on_new_session;
} SessionList;

SessionList* create_session_list(size_t initial_capacity) {
    SessionList *list = malloc(sizeof(SessionList));
    list->sessions = calloc(initial_capacity, sizeof(Session *));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_session_list(SessionList *list) {
    size_t new_capacity = list->capacity * 2;
    Session **new_sessions = realloc(list->sessions, new_capacity * sizeof(Session *));
    if (new_sessions) {
        memset(new_sessions + list->capacity, 0, list->capacity * sizeof(Session *));
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
}

void add_session(SessionList *list, unsigned long session_id, const char *ip_address) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        resize_session_list(list);
    }

    Session *session = malloc(sizeof(Session));
    session->session_id = session_id;
    session->last_active = time(NULL);
    session->ip_address = strdup(ip_address);

    list->sessions[list->count++] = session;

    if (list->on_new_session) {
        list->on_new_session(session_id, ip_address);
    }

    pthread_mutex_unlock(&list->lock);
}

void simulate_user_traffic(SessionList *list, size_t num_sessions) {
    for (size_t i = 0; i < num_sessions; ++i) {
        char ip[16];
        snprintf(ip, sizeof(ip), "192.168.1.%zu", i + 1);
        add_session(list, i + 1, ip);
    }
}

void update_sessions(SessionList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->sessions[i]) {
            list->sessions[i]->last_active = time(NULL);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_expired_sessions(SessionList *list, time_t expiration_duration) {
    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ) {
        Session *session = list->sessions[i];
        if (session && difftime(now, session->last_active) > expiration_duration) {
            free(session->ip_address);
            free(session);
            list->sessions[i] = NULL;
            for (size_t j = i; j < list->count - 1; ++j) {
                list->sessions[j] = list->sessions[j + 1];
            }
            --list->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_session_list(SessionList *list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->sessions[i]) {
            free(list->sessions[i]->ip_address);
            free(list->sessions[i]);
        }
    }

    free(list->sessions);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void register_callback(SessionList *list, SessionCallback callback) {
    pthread_mutex_lock(&list->lock);
    list->on_new_session = callback;
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    size_t initial_capacity = 10;
    time_t expiration_duration = 60; // seconds

    SessionList *session_list = create_session_list(initial_capacity);

    register_callback(session_list, [](unsigned long session_id, char* ip_address) {
        printf("New session: ID=%lu, IP=%s\n", session_id, ip_address);
    });

    simulate_user_traffic(session_list, 20);

    update_sessions(session_list);

    remove_expired_sessions(session_list, expiration_duration);

    free_session_list(session_list);

    return 0;
}
