#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Secure random number generator library function
extern int secure_random_number(int min, int max);

typedef struct {
    long value;
    int key;
    char *string_key;
} Record;

typedef void (*Callback)(Record *);

void manage_memory(size_t record_count, size_t string_length, int range_min, int range_max, unsigned int seed, Callback callback) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_once_t once_control = PTHREAD_ONCE_INIT;

    // Function to initialize the random number generator
    void init_random() {
        srand(seed);
    }

    // Ensure the RNG is initialized once per thread
    pthread_once(&once_control, init_random);

    Record *records = NULL;
    size_t i;

    if (record_count == 0) return;

    records = malloc(record_count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    for (i = 0; i < record_count; ++i) {
        records[i].value = secure_random_number(range_min, range_max);
        records[i].key = i;

        char *string_key = malloc(string_length + 1);
        if (!string_key) {
            fprintf(stderr, "Memory allocation failed for string key at index %zu\n", i);

            // Free previously allocated memory before exiting
            while (i-- > 0) free(records[i].string_key);
            free(records);
            pthread_mutex_unlock(&mutex);
            return;
        }

        snprintf(string_key, string_length + 1, "Key_%d", i);
        records[i].string_key = string_key;

        if (callback) {
            callback(&records[i]);
        }

        printf("Record %zu: Value=%ld, Key=%d, StringKey=%s\n", i, records[i].value, records[i].key, records[i].string_key);
    }
    pthread_mutex_unlock(&mutex);

    // Example of freeing memory
    for (i = 0; i < record_count; ++i) {
        free(records[i].string_key);
    }
    free(records);
}
