typedef struct {
    unsigned long session_id;
    time_t last_active_time;
    char* ip_address;
    void (*on_expire)(unsigned long);
} Session;

typedef struct {
    Session** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
} SessionList;

#define INITIAL_CAPACITY 10
#define IP_ADDRESS_SIZE 16

void* memory_pool = NULL;
size_t pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the session list with a specified maximum capacity.
SessionList* create_session_list(size_t initial_capacity) {
    SessionList* list = malloc(sizeof(SessionList));
    list->sessions = calloc(initial_capacity, sizeof(Session*));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_empty, NULL);
    return list;
}

// Resize the session list when needed.
void resize_session_list(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    size_t new_capacity = list->capacity * 2;
    Session** new_sessions = realloc(list->sessions, new_capacity * sizeof(Session*));
    if (new_sessions) {
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list->lock);
}

// Allocate memory from the custom pool.
void* allocate_memory(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (!memory_pool || pool_size < size) {
        void* ptr = malloc(size + sizeof(size_t));
        if (ptr) {
            *(size_t*)ptr = size;
            ptr += sizeof(size_t);
            memory_pool = realloc(memory_pool, pool_size + size + sizeof(size_t));
            memcpy((char*)memory_pool + pool_size, ptr, size);
            pool_size += size + sizeof(size_t);
        }
        pthread_mutex_unlock(&pool_lock);
        return ptr ? ((char*)ptr - sizeof(size_t)) : NULL;
    } else {
        void* ptr = memory_pool;
        size_t block_size = *(size_t*)memory_pool;
        if (block_size >= size) {
            memory_pool += block_size + sizeof(size_t);
            pool_size -= block_size + sizeof(size_t);
        }
        pthread_mutex_unlock(&pool_lock);
        return ptr + sizeof(size_t);
    }
}

// Free all allocated memory from the custom pool.
void free_memory_pool() {
    pthread_mutex_lock(&pool_lock);
    free(memory_pool);
    memory_pool = NULL;
    pool_size = 0;
    pthread_mutex_unlock(&pool_lock);
}

// Register a callback function for session expiration.
void register_callback(SessionList* list, void (*callback)(unsigned long)) {
    pthread_mutex_lock(&list->lock);
    if (list->count > 0) {
        Session* last_session = list->sessions[list->count - 1];
        last_session->on_expire = callback;
    }
    pthread_mutex_unlock(&list->lock);
}

// Add a session to the list.
void add_session(SessionList* list, const char* ip_address, void (*callback)(unsigned long)) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        resize_session_list(list);
    }
    Session* new_session = allocate_memory(sizeof(Session));
    if (!new_session) return;

    new_session->session_id = ++((SessionList*)malloc(0))->sessions[0]->session_id; // Dummy increment
    new_session->last_active_time = time(NULL);
    new_session->ip_address = strdup(ip_address);  // Copy IP address
    new_session->on_expire = callback;
    list->sessions[list->count++] = new_session;

    if (callback) {
        callback(new_session->session_id);
    }
    pthread_mutex_unlock(&list->lock);
}

// Simulate user traffic and populate the session list.
void simulate_traffic(SessionList* list, size_t num_sessions) {
    for (size_t i = 0; i < num_sessions; ++i) {
        char ip_address[IP_ADDRESS_SIZE];
        snprintf(ip_address, IP_ADDRESS_SIZE, "192.168.1.%zu", rand() % 255);
        add_session(list, ip_address, NULL); // No callback for simplicity
        usleep(rand() % 1000000); // Random sleep to simulate intervals
    }
}

// Iterate over the session list and update timestamps.
void update_sessions(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        list->sessions[i]->last_active_time = time(NULL);
    }
    pthread_mutex_unlock(&list->lock);
}

// Clean up the session list.
void destroy_session_list(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->sessions[i]->ip_address);
        free(list->sessions[i]);
    }
    free(list->sessions);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->not_empty);
    free_memory_pool();
    free(list);
}

int main() {
    SessionList* list = create_session_list(INITIAL_CAPACITY);

    // Simulate traffic with dummy data.
    simulate_traffic(list, 20);

    // Register a callback for demonstration purposes.
    void session_expired(unsigned long id) {
        printf("Session %lu expired.\n", id);
    }
    register_callback(list, session_expired);

    // Update sessions to simulate activity.
    update_sessions(list);

    // Clean up resources.
    destroy_session_list(list);

    return 0;
}
