#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

// External library for secure random number generation
#ifdef __linux__
#include <openssl/rand.h>  // OpenSSl for Linux
#elif _WIN32
#include <wincrypt.h>      // Windows Crypto API
#else
#error "Secure random number generator not supported on this platform"
#endif

#define MAX_KEY_SIZE 256

typedef struct {
    int integer_value;
    char *key;
    long *offset;
} Record;

void secure_random_int(int min, int max, int *result) {
#ifdef __linux__
    if (RAND_bytes((unsigned char*)result, sizeof(*result)) != 1) {
        fprintf(stderr, "Error generating random number\n");
        exit(EXIT_FAILURE);
    }
#elif _WIN32
    if (!CryptGenRandom(NULL, sizeof(*result), (BYTE*)result)) {
        fprintf(stderr, "Error generating random number\n");
        exit(EXIT_FAILURE);
    }
#endif

    int range = max - min + 1;
    *result = (*result % range) + min;
}

void findMax(int *array, size_t size, int *max_value) {
    if (size == 0) return;

    *max_value = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > *max_value) {
            *max_value = array[i];
        }
    }
}

void freeRecord(Record *record, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(record[i].key);
        free(record[i].offset);
    }
    free(record);
}

int processAndFindMaxRecord(size_t offset_size, size_t key_size, size_t record_size,
                            int min_range, int max_range, unsigned long seed,
                            void (*callback)(void *record, size_t num_records)) {

    // Seed for reproducibility
    srand(seed);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int *offset = (int *)malloc(offset_size * sizeof(int));
    int *key = (int *)malloc(key_size * sizeof(int));

    if (!offset || !key) {
        fprintf(stderr, "Memory allocation failed\n");
        freeRecord(NULL, 0);
        pthread_mutex_destroy(&mutex);
        return -1;
    }

    for (size_t i = 0; i < offset_size; ++i) {
        offset[i] = (int)i;
    }

    for (size_t i = 0; i < key_size; ++i) {
        key[i] = (int)i;
    }

    Record *record = (Record *)malloc(record_size * sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset);
        free(key);
        pthread_mutex_destroy(&mutex);
        return -1;
    }

    for (size_t i = 0; i < record_size; ++i) {
        record[i].key = (char *)malloc(MAX_KEY_SIZE * sizeof(char));
        record[i].offset = (long *)malloc(sizeof(long));

        if (!record[i].key || !record[i].offset) {
            fprintf(stderr, "Memory allocation failed\n");
            freeRecord(record, i);
            free(offset);
            free(key);
            pthread_mutex_destroy(&mutex);
            return -1;
        }

        snprintf(record[i].key, MAX_KEY_SIZE, "Key_%zu", i);

        int random_value;
        secure_random_int(min_range, max_range, &random_value);
        record[i].integer_value = random_value;

        if (record[i].offset) {
            secure_random_int(0, 1000000, (int *)record[i].offset); // Random offset
        }
    }

    if (callback) {
        callback(record, record_size);
    }

    int *input_array = NULL;
    size_t input_capacity = 10;
    size_t input_count = 0;

    while (1) {
        int value;
        scanf("%d", &value);

        if (value == -1) break;

        if (input_count >= input_capacity) {
            input_capacity *= 2;
            input_array = realloc(input_array, input_capacity * sizeof(int));
            if (!input_array) {
                fprintf(stderr, "Memory allocation failed\n");
                freeRecord(record, record_size);
                free(offset);
                free(key);
                pthread_mutex_destroy(&mutex);
                return -1;
            }
        }

        input_array[input_count++] = value;
    }

    int max_value = 0;
    findMax(input_array, input_count, &max_value);

    printf("Maximum integer value: %d\n", max_value);

    free(input_array);
    freeRecord(record, record_size);
    free(offset);
    free(key);
    pthread_mutex_destroy(&mutex);

    return max_value;
}
