#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define DEFAULT_WORD_ARRAY_SIZE 100

typedef struct {
    unsigned long id;
    size_t total_word_count;
    double average_word_length;
    char **words;
} DocumentMeta;

void *generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyz";
    char *random_string = malloc(length + 1);
    if (random_string == NULL) return NULL;

    for (size_t i = 0; i < length; i++) {
        random_string[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_string[length] = '\0';

    return random_string;
}

void initialize_document(DocumentMeta *doc, unsigned long id, size_t word_array_size, void (*callback)(DocumentMeta *)) {
    doc->id = id;
    doc->total_word_count = 0;
    doc->average_word_length = 0.0;

    doc->words = malloc(word_array_size * sizeof(char *));
    if (doc->words == NULL) return;

    for (size_t i = 0; i < word_array_size; i++) {
        char *word = generate_random_string(rand() % 10 + 1);
        if (word != NULL) doc->words[i] = word;
        else break;
    }

    if (callback) callback(doc);
}

void free_document(DocumentMeta *doc) {
    for (size_t i = 0; i < DEFAULT_WORD_ARRAY_SIZE; i++) {
        free(doc->words[i]);
    }
    free(doc->words);
}

void process_documents_and_analyze_stats(size_t num_docs, void (*callback)(DocumentMeta *)) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    DocumentMeta *docs = malloc(num_docs * sizeof(DocumentMeta));
    if (docs == NULL) return;

    for (unsigned long i = 0; i < num_docs; i++) {
        pthread_mutex_lock(&mutex);
        initialize_document(&docs[i], i, DEFAULT_WORD_ARRAY_SIZE, callback);
        pthread_mutex_unlock(&mutex);
    }

    double total_average_word_length = 0.0;
    size_t valid_documents = 0;

    for (unsigned long i = 0; i < num_docs; i++) {
        if (docs[i].total_word_count > 0) {
            total_average_word_length += docs[i].average_word_length;
            valid_documents++;
        }
    }

    double global_avg_word_length = valid_documents > 0 ? total_average_word_length / valid_documents : 0.0;
    printf("Global average word length: %f\n", global_avg_word_length);

    for (unsigned long i = 0; i < num_docs; i++) {
        free_document(&docs[i]);
    }

    free(docs);
}

void example_callback(DocumentMeta *doc) {
    size_t total_length = 0;
    for (size_t i = 0; i < DEFAULT_WORD_ARRAY_SIZE && doc->words[i] != NULL; i++) {
        total_length += strlen(doc->words[i]);
        doc->total_word_count++;
    }
    if (doc->total_word_count > 0) {
        doc->average_word_length = (double)total_length / doc->total_word_count;
    }
}

int main() {
    srand((unsigned int)time(NULL));

    size_t num_docs;
    printf("Enter the number of documents: ");
    scanf("%zu", &num_docs);

    process_documents_and_analyze_stats(num_docs, example_callback);

    return 0;
}
```

This code provides a basic implementation for processing documents and calculating statistical metrics as described. It initializes document metadata with random words, calculates average word length per document, and computes the global average word length across all documents. The function `process_documents_and_analyze_stats` uses mutexes to ensure thread safety when initializing each document.']

