// Define ImageMetaData structure
typedef struct {
    unsigned long imageID;
    size_t totalPixelCount;
    float averagePixelIntensity;
    int *pixelValues; // Pointer to dynamically allocated pixel values array
} ImageMetaData;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototype for callback
typedef void (*ImageCallback)(const ImageMetaData *);

// Helper function for generating random pixels and computing intensity
void generateRandomPixels(int *pixelArray, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pixelArray[i] = rand() % 256; // Simulating secure random generation
    }
}

float calculateAverageIntensity(const int *pixels, size_t count) {
    long sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += pixels[i];
    }
    return count ? (float)sum / count : 0.0f;
}

// Function to process the image batch
void processImageBatch(size_t initialSize, float defaultIntensity, ImageCallback callback) {
    pthread_mutex_lock(&mutex);

    unsigned long *imageIDs = NULL;
    ImageMetaData *metadataArray = NULL;

    // Allocate memory for initial arrays
    imageIDs = (unsigned long *)malloc(initialSize * sizeof(unsigned long));
    metadataArray = (ImageMetaData *)malloc(initialSize * sizeof(ImageMetaData));

    if (!imageIDs || !metadataArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    size_t currentSize = initialSize;

    // Initialize image IDs and metadata
    for (size_t i = 0; i < currentSize; ++i) {
        imageIDs[i] = i;
        metadataArray[i].imageID = i;
        metadataArray[i].totalPixelCount = 100; // Default pixel count
        metadataArray[i].averagePixelIntensity = defaultIntensity;

        int *pixels = (int *)malloc(metadataArray[i].totalPixelCount * sizeof(int));
        if (!pixels) {
            fprintf(stderr, "Memory allocation for pixels failed.\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        generateRandomPixels(pixels, metadataArray[i].totalPixelCount);
        metadataArray[i].pixelValues = pixels;

        // Calculate average intensity
        metadataArray[i].averagePixelIntensity = calculateAverageIntensity(pixels, metadataArray[i].totalPixelCount);

        if (callback) {
            callback(&metadataArray[i]);
        }
    }

    // Example of freeing resources for demonstration purposes.
    // In a real application, you'd likely continue to use these until batch is complete
    for (size_t i = 0; i < currentSize; ++i) {
        free(metadataArray[i].pixelValues);
    }
    free(imageIDs);
    free(metadataArray);

    pthread_mutex_unlock(&mutex);
}

// Example callback function
void exampleCallback(const ImageMetaData *metadata) {
    printf("Image ID: %lu, Avg Intensity: %.2f\n", metadata->imageID, metadata->averagePixelIntensity);
}
```

### Key Points:
- **Thread Safety:** The use of `pthread_mutex_lock` and `pthread_mutex_unlock` ensures thread safety when accessing shared resources.
- **Dynamic Memory Management:** Allocates memory dynamically for image IDs and their corresponding metadata. Pixel arrays are also allocated based on the default size.
- **Error Handling:** Checks for memory allocation failures to handle errors gracefully.
- **Callback Functionality:** Allows a user-defined function to be executed after each image is initialized, enhancing extensibility.
- **Memory Deallocation:** Frees all dynamically allocated memory at the end of the processing batch to prevent leaks.

This code provides a basic framework and can be extended further based on specific needs or additional requirements.']

