        for (size_t i = 0; i < num_records; ++i) {
            callback(&records_alloc[i]);
        }
    }

    *offsets = offsets_alloc;
    *keys = keys_alloc;
    *records = records_alloc;
    *identifiers = identifiers_alloc;

    log_message("INFO", "Memory management and initialization completed successfully");

    // Free resources function implementation
    return 0; // Return success
}

void handle_error(const char *error_message) {
    log_message("ERROR", error_message);
    free_resources(NULL, NULL, NULL, NULL, 0); // Cleanup in case of failure
    exit(EXIT_FAILURE);
}

size_t calculate_total_memory(size_t num_records, size_t max_record_size, size_t string_length_max) {
    return num_records * (sizeof(long) + sizeof(int) + max_record_size + (string_length_max + 1));
}

void free_resources(long **offsets, int **keys, record_t **records, char ***identifiers, size_t num_records) {
    if (offsets && *offsets) free(*offsets);
    if (keys && *keys) free(*keys);
    if (records && *records) free(*records);
    for (size_t i = 0; identifiers && *identifiers && i < num_records; ++i) {
