#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure definition for a node in the linked list
typedef struct Node {
    int key;
    struct Node* next;
} Node;

// Custom memory allocator structure
typedef struct {
    size_t block_size;
    unsigned char *memory_pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryAllocator;

// Function prototypes
MemoryAllocator* create_allocator(size_t block_size, size_t num_blocks);
void destroy_allocator(MemoryAllocator* allocator);
Node* init_list(MemoryAllocator* allocator, int min_key, int max_key);
int insert_node_sorted(MemoryAllocator* allocator, Node** head, int key);
void free_list(Node* head);

// Create a custom memory allocator
MemoryAllocator* create_allocator(size_t block_size, size_t num_blocks) {
    MemoryAllocator* allocator = (MemoryAllocator*)malloc(sizeof(MemoryAllocator));
    if (!allocator) return NULL;

    pthread_mutex_init(&allocator->lock, NULL);
    allocator->block_size = block_size;
    allocator->pool_size = block_size * num_blocks;
    allocator->memory_pool = (unsigned char*)malloc(allocator->pool_size);

    if (!allocator->memory_pool) {
        free(allocator);
        return NULL;
    }

    return allocator;
}

// Destroy a custom memory allocator
void destroy_allocator(MemoryAllocator* allocator) {
    if (allocator) {
        pthread_mutex_destroy(&allocator->lock);
        free(allocator->memory_pool);
        free(allocator);
    }
}

// Initialize the linked list with unique keys from min_key to max_key
Node* init_list(MemoryAllocator* allocator, int min_key, int max_key) {
    if (!allocator || min_key > max_key) return NULL;

    Node* head = NULL;
    for (int key = min_key; key <= max_key; ++key) {
        insert_node_sorted(allocator, &head, key);
    }

    return head;
}

// Insert a node into the linked list in sorted order
int insert_node_sorted(MemoryAllocator* allocator, Node** head, int key) {
    if (!allocator || !head) return -1;

    pthread_mutex_lock(&allocator->lock);

    // Allocate memory for new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&allocator->lock);
        return -2;
    }

    new_node->key = key;
    new_node->next = NULL;

    // Insert in sorted order
    if (*head == NULL || (*head)->key >= key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&allocator->lock);
    return 0;
}

// Free all nodes in the linked list
void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    size_t block_size = sizeof(Node);
    size_t num_blocks = 1024;

    MemoryAllocator* allocator = create_allocator(block_size, num_blocks);
    if (!allocator) {
        fprintf(stderr, "Failed to create memory allocator\n");
        return EXIT_FAILURE;
    }

    int min_key = 1;
    int max_key = 10;

    Node* list_head = init_list(allocator, min_key, max_key);

    // Example of inserting a new node
    if (insert_node_sorted(allocator, &list_head, 5) != 0) {
        fprintf(stderr, "Failed to insert node\n");
    }

    free_list(list_head);
    destroy_allocator(allocator);

    return EXIT_SUCCESS;
}
```

### Explanation

1. **Memory Allocator**: A simple custom allocator is implemented using a memory pool with mutex locking for thread safety.

2. **Thread Safety**: Mutex locks are used in `insert_node_sorted` to ensure safe concurrent access.

3. **Error Handling**: Functions check for errors during allocation and return meaningful error codes.

4. **List Operations**:
    - **Initialization**: The list is initialized with keys from a specified range.
    - **Insertion**: New nodes are inserted while maintaining sorted order.
    - **Deallocation**: All allocated memory is freed properly.

This design ensures scalability, low fragmentation, and easy maintenance, suitable for concurrent environments.']

