    long timestamp;
    int key;
    char buffer[256];
} Record;

Record* initialize_records(size_t num_records) {
    if (num_records <= 0) {
        fprintf(stderr, "Invalid number of records requested.\n");
        return NULL;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        records[i].timestamp = time(NULL);
        records[i].key = i;

        char *base_str = "Key_";
        snprintf(records[i].buffer, sizeof(records[i].buffer), "%s%d", base_str, i);

        // Fill the rest with random characters
        for (size_t j = strlen(base_str) + 1; j < sizeof(records[i].buffer) - 1; ++j) {
            records[i].buffer[j] = 'a' + rand() % 26;
        }
        records[i].buffer[sizeof(records[i].buffer) - 1] = '\0'; // Ensure null termination
    }

    return records;
}

void print_records(const Record *records, size_t num_records) {
    if (!records) {
        fprintf(stderr, "No records to display.\n");
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu:\n", i);
        printf("  Timestamp: %ld\n", records[i].timestamp);
        printf("  Key: %d\n", records[i].key);
        printf("  Buffer: %s\n", records[i].buffer);
    }
}

void free_records(Record *records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t num_records = 5; // Example number of records
    Record *records = initialize_records(num_records);

    if (!records) {
        return EXIT_FAILURE;
    }

    print_records(records, num_records);
    free_records(records);
    return EXIT_SUCCESS;
}
