                if (parts.Length == 2)
                    _resourceState[parts[0]] = int.Parse(parts[1]);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError("Failed to load initial resource configuration", ex);
        }
    }

    public DataTableReader ProcessDataAsync(byte[] data, CancellationToken cancellationToken)
    {
