            try
            {
                // Simulate sending byte array to a distributed service and getting results.
                var result = SendToDistributedService(data);

                _logger.LogInfo($"Processing completed for thread {Thread.CurrentThread.ManagedThreadId}");

                return new DataTableReader(result); // Assume DataTableReader is available.
            }
            catch (Exception ex)
            {
                _logger.LogError("Error during processing", ex);
                throw;
            }
            finally
            {
                _semaphore.Release();
            }
        }, cancellationToken).Result;
    }

