    }

    public string GenerateFilename(string baseName, ConcurrentDictionary<string, string> attributes)
    {
        try
        {
            foreach (var attribute in attributes)
            {
                baseName += "_" + attribute.Value.Replace(" ", "_").Replace("/", "-");
            }

            if (!System.IO.Path.GetInvalidFileNameChars().IsSubsetOf(baseName.ToCharArray()))
            {
                _logger.LogWarning($"Filename '{baseName}' contains invalid characters. Correcting...");
                foreach (char c in System.IO.Path.GetInvalidFileNameChars())
                    baseName = baseName.Replace(c, '_');
            }

            return $"{DateTime.Now.Ticks}_{baseName}.dat";
        }
        catch (Exception ex)
        {
            _logger.LogError("Error generating filename", ex);
            throw new InvalidOperationException("Filename generation failed.", ex);
        }
    }

    public void ResetResource()
    {
        try
        {
            // Logic to reset resource.
            _resourceState.Clear();
            _logger.LogInfo($"Resource reset by thread {Thread.CurrentThread.ManagedThreadId}");
        }
        catch (Exception ex)
        {
            _logger.LogError("Error during resource reset", ex);
        }
    }

    public void UpdateConfig(string configFilePath)
    {
