        {
            LoadInitialResourceValue();
            _logger.LogInfo("Configuration updated dynamically.");
        }
        catch (Exception ex)
        {
            _logger.LogError("Failed to update configuration dynamically.", ex);
        }
    }
}

public interface ILogger
{
    void LogError(string message, Exception ex = null);
    void LogWarning(string message);
    void LogInfo(string message);
}
