#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    int priority;
    char due_date[11]; // Format: YYYY-MM-DD
    int status;        // 0 for incomplete, 1 for complete
} Task;

// Function prototypes
void initialize_tasks(Task **tasks, size_t initial_size);
int set_task_priority(Task *task, int new_priority);
void add_task(Task **tasks, size_t *size, Task new_task, void (*callback)(Task*));
void process_and_add_task(Task **tasks, size_t *size, Task new_task, void (*callback)(Task*));
void free_tasks(Task **tasks);

// Callback prototype
void example_callback(Task *task);

// Mutex for thread safety
pthread_mutex_t tasks_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_tasks(Task **tasks, size_t initial_size) {
    *tasks = (Task *)malloc(initial_size * sizeof(Task));
    if (*tasks == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initial_size; ++i) {
        (*tasks)[i].id = i + 1;
        (*tasks)[i].priority = 5; // Default priority
        strcpy((*tasks)[i].due_date, "2023-12-31");
        (*tasks)[i].status = 0;
    }
}

int set_task_priority(Task *task, int new_priority) {
    if (task == NULL) return -1;

    pthread_mutex_lock(&tasks_mutex);
    task->priority = new_priority;
    pthread_mutex_unlock(&tasks_mutex);

    return 0; // Success
}

void add_task(Task **tasks, size_t *size, Task new_task, void (*callback)(Task*)) {
    if (callback != NULL) callback(&new_task); 

    pthread_mutex_lock(&tasks_mutex);
    size_t current_size = *size;
    *tasks = (Task *)realloc(*tasks, (current_size + 1) * sizeof(Task));

    if (*tasks == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    (*tasks)[current_size] = new_task;
    (*tasks)[current_size].id = current_size + 1; // Assign next ID
    ++(*size);

    pthread_mutex_unlock(&tasks_mutex);
}

void process_and_add_task(Task **tasks, size_t *size, Task new_task, void (*callback)(Task*)) {
    if (callback != NULL) callback(&new_task); 

    add_task(tasks, size, new_task, NULL);
}

void free_tasks(Task **tasks) {
    pthread_mutex_lock(&tasks_mutex);

    if (*tasks != NULL) {
        free(*tasks);
        *tasks = NULL;
    }

    pthread_mutex_unlock(&tasks_mutex);
}

// Example callback function
void example_callback(Task *task) {
    if (task == NULL) return;

    // Example validation or transformation logic
    task->priority += 1; // Adjust priority as needed
}

int main() {
    Task *tasks = NULL;
    size_t size = 0;

    initialize_tasks(&tasks, 10);

    Task new_task = { .id = 0, .priority = 3, .status = 0 };
    strcpy(new_task.due_date, "2024-01-01");

    process_and_add_task(&tasks, &size, new_task, example_callback);

    free_tasks(&tasks);
    return 0;
}
