["Here's an implementation of a simple in-memory cache system in C that meets the described requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// External library function prototype for secure random data generation
void generate_secure_random_data(void* buffer, size_t size);

typedef struct {
    time_t timestamp;
    int status; // 0: inactive, 1: active
    void* payload;
    size_t payload_size;
} CacheValue;

typedef struct Node {
    char* key;
    CacheValue value;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int capacity;
    int size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* create_cache(int capacity) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->head = NULL;
    cache->tail = NULL;
    cache->capacity = capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void move_to_head(LRUCache* cache, Node* node) {
    if (node == cache->head) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (cache->tail == node) cache->tail = node->prev;

    node->next = cache->head;
    node->prev = NULL;
    cache->head->prev = node;
    cache->head = node;
}

void evict_if_needed(LRUCache* cache) {
    while (cache->size > cache->capacity) {
        Node* to_remove = cache->tail;
        if (!to_remove) break;

        cache->tail = to_remove->prev;
        if (cache->tail) cache->tail->next = NULL;

        free(to_remove->key);
        free(to_remove->value.payload);
        free(to_remove);

        cache->size--;
    }
}

void add_entry(LRUCache* cache, const char* key, void* payload, size_t payload_size) {
    pthread_mutex_lock(&cache->lock);

    Node* existing_node = NULL;
    for (Node* node = cache->head; node; node = node->next) {
        if (strcmp(node->key, key) == 0) {
            existing_node = node;
            break;
        }
    }

    if (existing_node) {
        existing_node->value.payload = realloc(existing_node->value.payload, payload_size);
        memcpy(existing_node->value.payload, payload, payload_size);
        existing_node->value.payload_size = payload_size;
        existing_node->value.timestamp = time(NULL);
        existing_node->value.status = 1;

        move_to_head(cache, existing_node);

    } else {
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->key = strdup(key);
        new_node->value.payload = malloc(payload_size);
        memcpy(new_node->value.payload, payload, payload_size);
        new_node->value.payload_size = payload_size;
        new_node->value.timestamp = time(NULL);
        new_node->value.status = 1;

        new_node->next = cache->head;
        if (cache->head) cache->head->prev = new_node;
        cache->head = new_node;

        if (!cache->tail) cache->tail = new_node;

        cache->size++;
        evict_if_needed(cache);
    }

    pthread_mutex_unlock(&cache->lock);
}

CacheValue* get_entry(LRUCache* cache, const char* key) {
    pthread_mutex_lock(&cache->lock);

    for (Node* node = cache->head; node; node = node->next) {
        if (strcmp(node->key, key) == 0) {
            move_to_head(cache, node);
            CacheValue* value = &node->value;
            pthread_mutex_unlock(&cache->lock);
            return value;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void update_entry(LRUCache* cache, const char* key, int status) {
    pthread_mutex_lock(&cache->lock);

    for (Node* node = cache->head; node; node = node->next) {
        if (strcmp(node->key, key) == 0) {
            node->value.timestamp = time(NULL);
            node->value.status = status;
            move_to_head(cache, node);
            break;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void delete_entry(LRUCache* cache, const char* key) {
    pthread_mutex_lock(&cache->lock);

    Node *node = NULL, *prev_node = NULL;
    for (Node* current = cache->head; current; prev_node = current, current = current->next) {
        if (strcmp(current->key, key) == 0) {
            node = current;
            break;
        }
    }

    if (node) {
        if (node->prev) node->prev->next = node->next;
        else cache->head = node->next;

        if (node->next) node->next->prev = node->prev;
        else cache->tail = node->prev;

        free(node->key);
        free(node->value.payload);
        free(node);

        cache->size--;
    }

    pthread_mutex_unlock(&cache->lock);
}

void free_cache(LRUCache* cache) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current) {
        Node* next_node = current->next;
        free(current->key);
        free(current->value.payload);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void serialize_cache(LRUCache* cache, const char* filename) {
    // Implement serialization logic here
}

void deserialize_cache(LRUCache** cache, const char* filename) {
    // Implement deserialization logic here
}
