    new_node->next = cache->entries[index];
    cache->entries[index] = new_node;

    // Add to LRU/LFU heads
    if (!cache->lru_head || !cache->lfu_head) {
        new_node->prev = new_node->next = NULL;
        cache->lru_head = cache->lfu_head = new_node;
    } else {
        // Insert at the head for both LRU and LFU lists
        new_node->next = cache->lru_head;
        cache->lru_head->prev = new_node;
        new_node->prev = NULL;
        cache->lru_head = new_node;

        new_node->next = cache->lfu_head;
        cache->lfu_head->prev = new_node;
        new_node->prev = NULL;
        cache->lfu_head = new_node;
    }

    cache->current_size += payload_size + sizeof(CacheEntry) - sizeof(void*);
    cache->total_entries++;

    pthread_mutex_unlock(&cache->lock);
    return 1;
}

// Retrieve an entry from the cache
CacheEntry* get_entry(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);

    unsigned int hash_index = hash_function(key) % cache->max_capacity;
    Node *node = cache->entries[hash_index];
    while (node && strcmp(node->entry.key, key)) {
        node = node->next;
    }

    if (!node) { // Key not found
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    // Move to head of LRU list
    if (node != cache->lru_head) {
        if (node->prev) node->prev->next = node->next;
        if (node->next) node->next->prev = node->prev;

        node->next = cache->lru_head;
        if (cache->lru_head) cache->lru_head->prev = node;
        node->prev = NULL;
        cache->lru_head = node;
    }

    // Update LFU access count
    node->access_count++;

    pthread_mutex_unlock(&cache->lock);
    return &node->entry;
}

// Update an entry's timestamp and status flag
int update_entry(Cache *cache, const char *key, time_t new_timestamp, int new_status_flag) {
    CacheEntry *entry = get_entry(cache, key);
    if (entry) {
        pthread_mutex_lock(&cache->lock);

        // Update the values
        entry->timestamp = new_timestamp;
        entry->status_flag = new_status_flag;

        pthread_mutex_unlock(&cache->lock);
        return 1;
    }
    return 0;
}

// Delete an entry from the cache
void delete_entry(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);

    unsigned int hash_index = hash_function(key) % cache->max_capacity;
    Node *node = cache->entries[hash_index];
    while (node && strcmp(node->entry.key, key)) {
        node = node->next;
    }

    if (node) {
        // Remove from doubly linked lists
        if (node->prev) node->prev->next = node->next;
        if (node->next) node->next->prev = node->prev;

        if (node == cache->lru_head) cache->lru_head = node->next;
        if (node == cache->lfu_head && !--(node->access_count)) { // Adjust LFU
            while (cache->lfu_head && cache->lfu_head->access_count > 0)
                cache->lfu_head = cache->lfu_head->next;
        }

        // Remove from hash table
        cache->entries[hash_index] = node->next;

        // Free the memory
        free(node->entry.key);
        free(node->entry.payload);
        free(node);

        cache->current_size -= sizeof(CacheEntry) - sizeof(void*) + node->entry.payload_size;
        cache->total_entries--;
    }

    pthread_mutex_unlock(&cache->lock);
}

// Free all resources associated with the cache
void free_cache(Cache *cache) {
    if (!cache) return;

    pthread_mutex_lock(&cache->lock);

    Node *node = cache->lru_head;
    while (node) {
        Node *next_node = node->next;
        free(node->entry.key);
        free(node->entry.payload);
        free(node);
        node = next_node;
    }

    free(cache->entries);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Simple hash function for demonstration purposes
unsigned int hash_function(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash;
}

// Example usage
int main() {
    const char *keys[] = {"key1", "key2", "key3"};
    Cache *cache = init_cache(10);

    populate_cache(cache, keys, 3);

    CacheEntry *entry = get_entry(cache, "key1");
    if (entry) {
        printf("Retrieved entry with key: %s\n", entry->key);
    }

    update_entry(cache, "key1", time(NULL), 0);

    delete_entry(cache, "key2");

    free_cache(cache);
    return 0;
}
