    if (!keys) {
        fprintf(stderr, "Error: Memory allocation for keys failed.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < offset_size / 4; ++i) {
        keys[i] = i;
    }
    return keys;
}

record* allocate_records(size_t size, int use_offset, long *offsets) {
    if (size == 0) return NULL;
    record *records = malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation for records failed.\n");
        exit(EXIT_FAILURE);
