        if (use_offset && offsets != NULL && i < (sizeof(long*) / sizeof(int))) {
            records[i].reference = offsets[rand() % size];
        } else {
            records[i].reference = i;
        }
    }
    return records;
}

void free_memory(long *offsets, int *keys, record *records) {
