    if (!keys) {
        free(offsets);
        handle_error("Memory allocation for keys failed.");
        return -1;
    }

    record *records = (record *)malloc(record_count * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        handle_error("Memory allocation for records failed.");
        return -1;
    }

    int used_keys[key_size];
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = rand() % key_size + 1; // Random initial keys
        used_keys[i] = 0;
    }

    for (size_t i = 0; i < record_count; ++i) {
        int unique_key_found = 0;

        while (!unique_key_found) {
            int key_index = rand() % key_size;
            if (!used_keys[key_index]) {
                used_keys[key_index] = 1;
                records[i].key_ref = &keys[key_index];
                unique_key_found = 1;
            } else {
                // Increment to find a new unique key
                while (used_keys[key_index]) {
                    keys[key_index]++;
                    if (keys[key_index] > key_size) { // Avoid overflow
                        keys[key_index] = 1;
                    }
                    key_index = keys[key_index] - 1; // Adjust index for next lookup
                }
                used_keys[key_index] = 1;
                records[i].key_ref = &keys[key_index];
            }
        }

        int offset_index = rand() % offset_size;
        records[i].offset_ref = &offsets[offset_index];

        records[i].value = generate_random_number(range_min, range_max);
    }

    // Cleanup
    free_resources(offsets, keys, records, record_count);

    return 0; // Success
}

void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
