    size_t record_size;
    pthread_mutex_t lock;
} RecordManager;

typedef struct {
    Preference **preferences;
    size_t preference_count;
    size_t preference_capacity;
    pthread_rwlock_t rwlock;
} PreferenceManager;

void secure_random_init(unsigned int seed) {
#ifdef __MACH__ // OS X does not have srandomdev
    if (seed != 0)
        srand48(seed);
    else
        srand48dev();
#else
    if (seed != 0)
        srandom(seed);
    else
        srandomdev();
#endif
}

long secure_random_range(long min, long max) {
    double r = drand48();
    return (long)((r * ((max - min) + 1)) + min);
}

void handleRecordsAndPreferences(size_t record_size, unsigned int seed,
                                 void (*record_callback)(Record*)) {
