        pthread_mutex_lock(&rm.lock);

        Record *rec = &rm.records[i];
        rec->offset = i;
        rec->key = i + 1000; // Example key offset
        rec->record_pointer = (long *)malloc(sizeof(long));
        if (!rec->record_pointer) {
            perror("Failed to allocate memory for record pointer");
            exit(EXIT_FAILURE);
