        *rec->record_pointer = secure_random_range(1, 100); // Random range example

        pthread_mutex_unlock(&rm.lock);

        if (record_callback) {
            record_callback(rec);
        }
    }

    pm.preference_capacity = 10;
    pm.preferences = (Preference **)malloc(pm.preference_capacity * sizeof(Preference *));
    if (!pm.preferences) {
        perror("Failed to allocate memory for preferences");
        exit(EXIT_FAILURE);
