            return;
        }
    }

    fprintf(stderr, "Failed to fetch data after %d retries.\n", max_retries);
    *payload = NULL;
    *size = 0;
}

void log_cache_performance(const char *message) {
    printf("%s\n", message); // Replace with actual logging mechanism
}

// Example usage
int main() {
    initialize_cache(&cache);

    uuid_t id1, id2;
    uuid_generate(id1);
    uuid_generate(id2);

    unsigned char *payload1, *payload2;
    size_t size1, size2;

    fetch_data_with_retry(id1, &payload1, &size1);
