    ContentItem item2 = {id2, time(NULL), "inactive", size2, payload2};
    update_cache(&cache, item2);

    serialize_cache("cache.dat", &cache);

    LRUCache new_cache;
    initialize_cache(&new_cache);
    deserialize_cache("cache.dat", &new_cache);

    ContentItem *retrieved_item = retrieve_from_cache(&new_cache, id1);
    if (retrieved_item) {
