#include <arpa/inet.h>

#define SESSION_ID_LENGTH 64
#define TIME_WINDOW 60 // seconds

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    time_t timestamp;
} offset_t;

typedef unsigned long key_t;

typedef struct {
    key_t key;
    pthread_mutex_t lock;
} record_t;

typedef struct {
    record_t *records;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
} session_manager_t;

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Function declarations
void init_session_manager(session_manager_t *manager, size_t initial_capacity);
key_t generate_unique_key(const char *ip_address);
char *generate_session_id(key_t key, const char *ip_address);
int is_key_unique(session_manager_t *manager, key_t key);
void cleanup_session_manager(session_manager_t *manager);

// Helper functions
unsigned long hash_ip_and_time(const offset_t *offset) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < strlen(offset->ip); ++i)
        hash = ((hash << 5) + hash) + offset->ip[i];
    return hash ^ (unsigned long)(offset->timestamp);
}

// Implementation
void init_session_manager(session_manager_t *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);
    manager->records = calloc(initial_capacity, sizeof(record_t));
    for (size_t i = 0; i < initial_capacity; ++i)
        pthread_mutex_init(&manager->records[i].lock, NULL);
}

key_t generate_unique_key(const char *ip_address) {
    offset_t offset;
    time_t current_time = time(NULL);
    struct sockaddr_storage ss;
    socklen_t len = sizeof(ss);

    if (inet_pton(AF_INET6, ip_address, &ss.sa_data) == 1 || inet_pton(AF_INET, ip_address, &ss.sin_addr) == 1) {
        strncpy(offset.ip, ip_address, INET6_ADDRSTRLEN);
        offset.timestamp = current_time;

        unsigned long hash = hash_ip_and_time(&offset);
        return (key_t)(hash ^ ((unsigned long)time(NULL)) ^ rand());
    }

    return 0; // Invalid IP format
}

char *generate_session_id(key_t key, const char *ip_address) {
    static char session_id[SESSION_ID_LENGTH];
    snprintf(session_id, SESSION_ID_LENGTH, "%lu_%s", key, ip_address);
    return session_id;
}

int is_key_unique(session_manager_t *manager, key_t key) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            pthread_rwlock_unlock(&manager->rwlock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 1;
}

void cleanup_session_manager(session_manager_t *manager) {
    for (size_t i = 0; i < manager->capacity; ++i)
        pthread_mutex_destroy(&manager->records[i].lock);

    free(manager->records);
    pthread_rwlock_destroy(&manager->rwlock);
}

// Example usage
int main() {
    session_manager_t manager;
    init_session_manager(&manager, 100);

    const char *client_ip = "192.168.1.1";
    key_t new_key = generate_unique_key(client_ip);

    if (is_key_unique(&manager, new_key)) {
        char *session_id = generate_session_id(new_key, client_ip);
        printf("Generated Session ID: %s\n", session_id);

        // Add to records and manage lifecycle as needed
    }

    cleanup_session_manager(&manager);
    return 0;
}
