#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef void (*error_callback_t)(const char *message);

typedef struct {
    long *offsets;
    int *keys;
    size_t offset_size, key_size;
    record *records;
    size_t record_size;
    atomic_flag lock;
    error_callback_t error_cb;
    pthread_mutex_t mutex; // Mutex for dynamic resizing
} DataStructure;

// Helper function to reallocate memory and handle errors
static void *safe_realloc(void *ptr, size_t new_size, const char *context, DataStructure *ds) {
    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr && ds->error_cb != NULL) {
        ds->error_cb("Memory allocation failed during " context ".");
    }
    return new_ptr;
}

// Initialize and manage the data structure
void initialize_data_structure(DataStructure *ds, size_t offset_size, size_t key_size, size_t record_size,
                               error_callback_t error_cb) {
    ds->offsets = malloc(offset_size * sizeof(long));
    ds->keys = malloc(key_size * sizeof(int));
    ds->records = calloc(record_size, sizeof(record));
    ds->offset_size = offset_size;
    ds->key_size = key_size;
    ds->record_size = record_size;
    ds->lock = ATOMIC_FLAG_INIT;
    ds->error_cb = error_cb;
    pthread_mutex_init(&ds->mutex, NULL);

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets); ds->offsets = NULL;
        free(ds->keys); ds->keys = NULL;
        free(ds->records); ds->records = NULL;
        pthread_mutex_destroy(&ds->mutex);
        if (error_cb != NULL) error_cb("Initial memory allocation failed.");
    } else {
        // Initialize offsets and keys with zero
        for (size_t i = 0; i < offset_size; ++i) ds->offsets[i] = 0;
        for (size_t i = 0; i < key_size; ++i) ds->keys[i] = 0;

        // Populate records with random values ensuring uniqueness
        srand(time(NULL));
        for (size_t i = 0; i < record_size; ++i) {
            int unique;
            do {
                unique = 1;
                ds->records[i].value = rand() % 1000; // Example range [0, 999]
                pthread_mutex_lock(&ds->mutex);
                for (size_t j = 0; j < i; ++j) {
                    if (ds->records[j].value == ds->records[i].value) {
                        unique = 0;
                        break;
                    }
                }
                pthread_mutex_unlock(&ds->mutex);
            } while (!unique);
        }
    }
}

// Function to resize arrays
void resize_data_structure(DataStructure *ds, size_t new_offset_size, size_t new_key_size) {
    if (atomic_flag_test_and_set(&ds->lock)) return; // Prevent concurrent access

    ds->offsets = safe_realloc(ds->offsets, new_offset_size * sizeof(long), "resizing offsets", ds);
    ds->keys = safe_realloc(ds->keys, new_key_size * sizeof(int), "resizing keys", ds);

    if (ds->offsets && ds->keys) {
        ds->offset_size = new_offset_size;
        ds->key_size = new_key_size;

        // Initialize newly allocated memory
        for (size_t i = ds->offset_size; i < new_offset_size; ++i) ds->offsets[i] = 0;
        for (size_t i = ds->key_size; i < new_key_size; ++i) ds->keys[i] = 0;
    }

    atomic_flag_clear(&ds->lock);
}

// Reset the internal state of the function
void reset_data_structure(DataStructure *ds) {
    if (atomic_flag_test_and_set(&ds->lock)) return;

    free(ds->offsets); ds->offsets = NULL;
    free(ds->keys); ds->keys = NULL;
    free(ds->records); ds->records = NULL;
    atomic_flag_clear(&ds->lock);

    initialize_data_structure(ds, ds->offset_size, ds->key_size, ds->record_size, ds->error_cb);
}

// Cleanup and deallocate memory
void cleanup_data_structure(DataStructure *ds) {
    free(ds->offsets); ds->offsets = NULL;
    free(ds->keys); ds->keys = NULL;
    free(ds->records); ds->records = NULL;
    pthread_mutex_destroy(&ds->mutex);
}

// Example usage:
/*
int main() {
    DataStructure ds;
    initialize_data_structure(&ds, 10, 10, 5, my_error_callback);

    resize_data_structure(&ds, 20, 15);

    reset_data_structure(&ds);

    cleanup_data_structure(&ds);
}
*/
