#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Define a custom structure for elements
typedef struct {
    int value;
} Element;

// Memory pool structure
typedef struct {
    void *memory;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} MemoryPool;

// Log entry structure
typedef struct {
    time_t timestamp;
    uint64_t record_id;
} LogEntry;

// Global variables for logging and configuration
static FILE *log_file = NULL;
static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function declarations
MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks);
void destroy_memory_pool(MemoryPool *pool);
Element* initialize_elements(MemoryPool *element_pool, int element_count, unsigned long seed);
void resize_element_array(Element **elements, MemoryPool *element_pool, size_t new_size);

// Function to handle logging
static void log_message(const char *message) {
    pthread_mutex_lock(&log_lock);
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
    }
    fflush(log_file); // Ensure the message is written immediately
    pthread_mutex_unlock(&log_lock);
}

// Memory pool creation function
MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }

    pool->memory = malloc(block_size * num_blocks);
    if (!pool->memory) {
        free(pool);
        perror("Failed to allocate memory for memory pool blocks");
        exit(EXIT_FAILURE);
    }

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Memory pool destruction function
void destroy_memory_pool(MemoryPool *pool) {
    if (pool != NULL) {
        free(pool->memory);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

// Function to initialize elements with random values
Element* initialize_elements(MemoryPool *element_pool, int element_count, unsigned long seed) {
    Element *elements = malloc(element_count * sizeof(Element));
    if (!elements) {
        perror("Failed to allocate memory for elements");
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator
    srand48(seed);

    pthread_mutex_lock(&element_pool->lock); // Lock the pool for thread-safe access
    for (int i = 0; i < element_count; ++i) {
        elements[i].value = lrand48() % 1000; // Random value in [0, 999]

        LogEntry entry;
        entry.timestamp = time(NULL);
        entry.record_id = (uint64_t)(uintptr_t)&elements[i];

        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Record ID: %llu created at %ld", entry.record_id, entry.timestamp);
        log_message(log_buffer); // Log record creation
    }
    pthread_mutex_unlock(&element_pool->lock);

    return elements;
}

// Function to resize element array dynamically
void resize_element_array(Element **elements, MemoryPool *element_pool, size_t new_size) {
    if (!*elements) {
        *elements = initialize_elements(element_pool, new_size, time(NULL));
        return;
    }

    pthread_mutex_lock(&element_pool->lock);

    Element *new_elements = realloc(*elements, new_size * sizeof(Element));
    if (!new_elements && new_size > 0) {
        perror("Failed to resize memory for elements");
        exit(EXIT_FAILURE);
    }

    for (size_t i = (new_size > (*element_pool)->num_blocks ? (*element_pool)->num_blocks : new_size); 
         i < new_size; ++i) {
        new_elements[i].value = lrand48() % 1000;
    }

    *elements = new_elements;

    pthread_mutex_unlock(&element_pool->lock);
}

// Main function demonstrating usage
int main(int argc, char **argv) {
    // Open log file for writing
    log_file = fopen("log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Configuration options (example values)
    size_t offset_count = 10;
    size_t index_count = 20;
    size_t element_count = 30;
    unsigned long seed = time(NULL);

    MemoryPool *offset_pool = create_memory_pool(sizeof(long), offset_count);
    MemoryPool *index_pool = create_memory_pool(sizeof(short), index_count);
    MemoryPool *element_pool = create_memory_pool(sizeof(Element), element_count);

    long *offsets = malloc(offset_count * sizeof(long));
    short *indexes = malloc(index_count * sizeof(short));

    if (!offsets || !indexes) {
        perror("Failed to allocate memory for arrays");
        destroy_memory_pool(offset_pool);
        destroy_memory_pool(index_pool);
        destroy_memory_pool(element_pool);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and indexes
    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = i;
    }

    for (size_t i = 0; i < index_count; ++i) {
        indexes[i] = i;
    }

    Element *elements = initialize_elements(element_pool, element_count, seed);

    // Example of resizing the elements array
    resize_element_array(&elements, element_pool, element_count + 5);

    // Clean up
    free(offsets);
    free(indexes);
    destroy_memory_pool(offset_pool);
    destroy_memory_pool(index_pool);
    destroy_memory_pool(element_pool);
    if (elements) {
        free(elements);
    }

    fclose(log_file);
    return 0;
}
