#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Element;

typedef struct {
    long *offsets;
    short *indices;
    Element *elements;
    size_t count;
    pthread_mutex_t lock;
} DataManager;

void log_allocation(size_t size) {
    printf("Allocated %zu bytes\n", size);
}

void log_deallocation(void *ptr, size_t size) {
    printf("Deallocated %zu bytes at %p\n", size, ptr);
}

int allocate_data_manager(DataManager *dm, size_t count) {
    pthread_mutex_init(&dm->lock, NULL);

    dm->offsets = (long *)malloc(count * sizeof(long));
    if (!dm->offsets) return -1;
    log_allocation(count * sizeof(long));

    dm->indices = (short *)malloc((count - 1) * sizeof(short));
    if (!dm->indices) {
        free(dm->offsets);
        log_deallocation(dm->offsets, count * sizeof(long));
        return -1;
    }
    log_allocation((count - 1) * sizeof(short));

    dm->elements = (Element *)malloc(count * sizeof(Element));
    if (!dm->elements) {
        free(dm->offsets);
        free(dm->indices);
        log_deallocation(dm->offsets, count * sizeof(long));
        log_deallocation(dm->indices, (count - 1) * sizeof(short));
        return -1;
    }
    log_allocation(count * sizeof(Element));

    dm->count = count;

    // Initialize offsets and indices
    for (size_t i = 0; i < count; ++i) {
        dm->offsets[i] = rand() % 100;
    }

    for (size_t i = 0; i < count - 1; ++i) {
        dm->indices[i] = rand() % (count - i);
    }

    // Initialize elements with random values
    for (size_t i = 0; i < count; ++i) {
        dm->elements[i].value = rand() % 100;
    }

    return 0;
}

void deallocate_data_manager(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);
    free(dm->offsets);
    log_deallocation(dm->offsets, dm->count * sizeof(long));

    free(dm->indices);
    log_deallocation(dm->indices, (dm->count - 1) * sizeof(short));

    free(dm->elements);
    log_deallocation(dm->elements, dm->count * sizeof(Element));

    pthread_mutex_unlock(&dm->lock);
    pthread_mutex_destroy(&dm->lock);
}

void resize_data_manager(DataManager *dm, size_t new_count) {
    pthread_mutex_lock(&dm->lock);

    long *new_offsets = (long *)realloc(dm->offsets, new_count * sizeof(long));
    if (!new_offsets) {
        pthread_mutex_unlock(&dm->lock);
        return;
    }
    log_deallocation(dm->offsets, dm->count * sizeof(long));
    log_allocation(new_count * sizeof(long));
    dm->offsets = new_offsets;

    short *new_indices = (short *)realloc(dm->indices, (new_count - 1) * sizeof(short));
    if (!new_indices) {
        free(dm->offsets);
        log_deallocation(dm->offsets, new_count * sizeof(long));
        pthread_mutex_unlock(&dm->lock);
        return;
    }
    log_deallocation(dm->indices, (dm->count - 1) * sizeof(short));
    log_allocation((new_count - 1) * sizeof(short));
    dm->indices = new_indices;

    Element *new_elements = (Element *)realloc(dm->elements, new_count * sizeof(Element));
    if (!new_elements) {
        free(dm->offsets);
        free(dm->indices);
        log_deallocation(dm->offsets, new_count * sizeof(long));
        log_deallocation(dm->indices, (new_count - 1) * sizeof(short));
        pthread_mutex_unlock(&dm->lock);
        return;
    }
    log_deallocation(dm->elements, dm->count * sizeof(Element));
    log_allocation(new_count * sizeof(Element));
    dm->elements = new_elements;

    for (size_t i = dm->count; i < new_count; ++i) {
        dm->offsets[i] = rand() % 100;
        if (i > 0) dm->indices[i - 1] = rand() % (new_count - i);
        dm->elements[i].value = rand() % 100;
    }

    dm->count = new_count;

    pthread_mutex_unlock(&dm->lock);
}

void serialize_data_manager(const DataManager *dm, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&dm->count, sizeof(size_t), 1, file);

    size_t bytes_written = fwrite(dm->offsets, sizeof(long), dm->count, file);
    if (bytes_written != dm->count) fclose(file);

    bytes_written = fwrite(dm->indices, sizeof(short), dm->count - 1, file);
    if (bytes_written != dm->count - 1) fclose(file);

    bytes_written = fwrite(dm->elements, sizeof(Element), dm->count, file);
    if (bytes_written != dm->count) fclose(file);

    fclose(file);
}

int deserialize_data_manager(DataManager *dm, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    long *new_offsets = (long *)realloc(dm->offsets, count * sizeof(long));
    short *new_indices = (short *)realloc(dm->indices, (count - 1) * sizeof(short));
    Element *new_elements = (Element *)realloc(dm->elements, count * sizeof(Element));

    if (!new_offsets || !new_indices || !new_elements) {
        fclose(file);
        return -1;
    }

    size_t bytes_read = fread(new_offsets, sizeof(long), count, file);
    if (bytes_read != count) goto error;

    bytes_read = fread(new_indices, sizeof(short), count - 1, file);
    if (bytes_read != count - 1) goto error;

    bytes_read = fread(new_elements, sizeof(Element), count, file);
    if (bytes_read != count) goto error;

    dm->offsets = new_offsets;
    dm->indices = new_indices;
    dm->elements = new_elements;
    dm->count = count;

    fclose(file);
    return 0;

error:
    free(new_offsets);
    free(new_indices);
    free(new_elements);
    fclose(file);
    return -1;
}

void test_data_manager() {
    DataManager dm;
    if (allocate_data_manager(&dm, 10) == 0) {
        printf("Data manager allocated successfully.\n");

        resize_data_manager(&dm, 20);
        printf("Data manager resized to 20 elements.\n");

        serialize_data_manager(&dm, "data.bin");
        printf("Data serialized to data.bin\n");

        DataManager new_dm;
        if (allocate_data_manager(&new_dm, 10) == 0 && deserialize_data_manager(&new_dm, "data.bin") == 0) {
            printf("Data deserialized successfully.\n");
        }

        deallocate_data_manager(&dm);
        deallocate_data_manager(&new_dm);
    }
}

int main() {
    srand(time(NULL));
    test_data_manager();
    return 0;
}
