#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_SIZE 100
#define MAX_PREF_NAME_LENGTH 50

typedef enum { STRING, INTEGER, BOOLEAN } ValueType;

typedef struct {
    char name[MAX_PREF_NAME_LENGTH];
    ValueType type;
    union {
        const char *stringValue;
        int intValue;
        _Bool boolValue;
    } defaultValue;
    union {
        char valueString[256];
        int valueInt;
        _Bool valueBool;
    } currentValue;
} Preference;

typedef struct {
    int offset;
    int key;
    long recordValue;
} Record;

void handleError(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int secureRandom(int min, int max, unsigned int seed) {
    srand(seed ^ time(NULL));
    return min + rand() % (max - min + 1);
}

void handleRecordsAndFindMax(size_t recordSize, int offsetRangeStart, int offsetRangeEnd,
                             unsigned int seed, void (*recordCallback)(const Record *)) {
    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0)
        handleError("Mutex init has failed");

    Record *records = malloc(recordSize * sizeof(Record));
    if (!records)
        handleError("Failed to allocate memory for records");

    for (size_t i = 0; i < recordSize; ++i) {
        records[i].offset = secureRandom(offsetRangeStart, offsetRangeEnd, seed);
        records[i].key = i;
        records[i].recordValue = secureRandom(1, 1000000, seed);

        if (recordCallback)
            recordCallback(&records[i]);
    }

    pthread_mutex_lock(&lock);
    // Example of finding max
    long maxRecordValue = records[0].recordValue;
    for (size_t i = 1; i < recordSize; ++i) {
        if (records[i].recordValue > maxRecordValue)
            maxRecordValue = records[i].recordValue;
    }
    printf("Max Record Value: %ld\n", maxRecordValue);
    pthread_mutex_unlock(&lock);

    free(records);
    pthread_mutex_destroy(&lock);
}

void handlePreferences(size_t initialSize) {
    Preference *preferences = malloc(initialSize * sizeof(Preference));
    if (!preferences)
        handleError("Failed to allocate memory for preferences");

    for (size_t i = 0; i < initialSize; ++i) {
        snprintf(preferences[i].name, MAX_PREF_NAME_LENGTH, "Pref%d", (int)i);
        preferences[i].type = STRING;
        preferences[i].defaultValue.stringValue = "default";
        strncpy(preferences[i].currentValue.valueString,
                preferences[i].defaultValue.stringValue, sizeof(preferences[i].currentValue.valueString));
    }

    // Simulate adding a user-specific preference
    if (initialSize < 10) { // Example condition for resizing
        Preference *temp = realloc(preferences, 2 * initialSize * sizeof(Preference));
        if (!temp)
            handleError("Failed to reallocate memory for preferences");

        preferences = temp;
        for (size_t i = initialSize; i < 2 * initialSize; ++i) {
            snprintf(preferences[i].name, MAX_PREF_NAME_LENGTH, "Pref%d", (int)i);
            preferences[i].type = INTEGER;
            preferences[i].defaultValue.intValue = 0;
            preferences[i].currentValue.valueInt = 0;
        }
    }

    free(preferences);
}

void exampleCallback(const Record *record) {
    printf("Record initialized: offset=%d, key=%d, value=%ld\n",
           record->offset, record->key, record->recordValue);
}

int main() {
    handleRecordsAndFindMax(DEFAULT_SIZE, 0, 999, 12345, exampleCallback);
    handlePreferences(5);

    return 0;
}
