resource_manager* init_resource_manager(size_t initial_capacity) {
    if (initial_capacity <= 0) return NULL;

    resource_manager *rm = malloc(sizeof(resource_manager));
    if (!rm) return NULL;

    pthread_mutex_init(&rm->mutex, NULL);

    rm->offsets_size = 0;
    rm->allocated_offsets_size = initial_capacity;
    rm->offsets = malloc(rm->allocated_offsets_size * sizeof(long));
    if (!rm->offsets) {
        free(rm);
        return NULL;
    }

    rm->keys_size = 0;
    rm->allocated_keys_size = initial_capacity;
    rm->keys = malloc(rm->allocated_keys_size * sizeof(int));
    if (!rm->keys) {
        free(rm->offsets);
        free(rm);
        return NULL;
    }

    rm->records_size = 0;
    rm->allocated_records_size = initial_capacity;
    rm->records = malloc(rm->allocated_records_size * sizeof(record));
    if (!rm->records) {
        free(rm->keys);
        free(rm->offsets);
        free(rm);
        return NULL;
    }

    rm->string_pool = malloc(INITIAL_POOL_SIZE * sizeof(char *));
    if (!rm->string_pool) {
        free(rm->records);
        free(rm->keys);
        free(rm->offsets);
        free(rm);
        return NULL;
    }

    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i)
        rm->string_pool[i] = NULL;

    rm->pool_size = INITIAL_POOL_SIZE;
    rm->strings_in_use = 0;

    return rm;
}

char *get_string_from_pool(resource_manager *rm, const char *str) {
    if (!rm || !str) return NULL;

    pthread_mutex_lock(&rm->mutex);

    for (size_t i = 0; i < rm->pool_size; ++i) {
        if (rm->string_pool[i] && strcmp(rm->string_pool[i], str) == 0) {
            pthread_mutex_unlock(&rm->mutex);
            return rm->string_pool[i];
        }
    }

    if (rm->strings_in_use >= rm->pool_size) {
        size_t new_pool_size = rm->pool_size * 2;
        char **new_pool = realloc(rm->string_pool, new_pool_size * sizeof(char *));
        if (!new_pool) {
            pthread_mutex_unlock(&rm->mutex);
            return NULL;
        }

        for (size_t i = rm->pool_size; i < new_pool_size; ++i)
            new_pool[i] = NULL;

        rm->string_pool = new_pool;
        rm->pool_size = new_pool_size;
    }

    size_t len = strlen(str) + 1;
    char *new_str = malloc(len);
    if (!new_str) {
        pthread_mutex_unlock(&rm->mutex);
        return NULL;
    }

    strcpy(new_str, str);

    for (size_t i = 0; i < rm->pool_size; ++i) {
        if (rm->string_pool[i] == NULL) {
            rm->string_pool[i] = new_str;
            ++rm->strings_in_use;
            pthread_mutex_unlock(&rm->mutex);
            return new_str;
        }
    }

    pthread_mutex_unlock(&rm->mutex);

    free(new_str);
    return NULL;
}

int initialize_resources(resource_manager *rm, size_t num_offsets, size_t num_keys, size_t num_records,
                         int value_min, int value_max, const char **string_pool, size_t pool_size) {
    if (!rm || !string_pool || pool_size == 0) return -1;

    pthread_mutex_lock(&rm->mutex);

    if (num_offsets > rm->allocated_offsets_size ||
        num_keys > rm->allocated_keys_size ||
        num_records > rm->allocated_records_size)
    {
        pthread_mutex_unlock(&rm->mutex);
        return -2;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        rm->offsets[rm->offsets_size + i] = rand();
    }
    rm->offsets_size += num_offsets;

    for (size_t i = 0; i < num_keys; ++i) {
        rm->keys[rm->keys_size + i] = rand() % (value_max - value_min + 1) + value_min;
    }
    rm->keys_size += num_keys;

    for (size_t i = 0; i < num_records; ++i) {
        rm->records[rm->records_size].value =
            rand() % (value_max - value_min + 1) + value_min;

        if (pool_size > 0)
            rm->records[rm->records_size].str = get_string_from_pool(rm, string_pool[rand() % pool_size]);
        else
            rm->records[rm->records_size].str = NULL;

        ++(rm->records_size);
    }

    pthread_mutex_unlock(&rm->mutex);

    return 0;
}

void free_resource_manager(resource_manager *rm) {
    if (!rm) return;

    for (size_t i = 0; i < rm->strings_in_use; ++i)
        free(rm->string_pool[i]);

    free(rm->string_pool);
    free(rm->records);
    free(rm->keys);
    free(rm->offsets);

    pthread_mutex_destroy(&rm->mutex);
    free(rm);
}
