void processAndAggregateRecords(size_t timestampSize, size_t recordSize, time_t customStartTimestamp, void (*preprocessFunc)(Record *)) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int *timestamps = (int *)malloc(timestampSize * sizeof(int));
    if (!timestamps) {
        fprintf(stderr, "Memory allocation failed for timestamps\n");
        return;
    }

    Record *records = (Record *)calloc(recordSize, sizeof(Record));
