    for (size_t i = 0; i < timestampSize && validCount < recordSize; ++i) {
        if (customStartTimestamp == 0 || timestamps[i] >= customStartTimestamp) {
            records[validCount].offset = i;
            records[validCount].key = 0; // Default key
            records[validCount].value = 0; // Default value
            records[validCount].stats = (Stats *)malloc(sizeof(Stats));
            if (!records[validCount].stats) {
                fprintf(stderr, "Memory allocation failed for stats\n");
                break;
            }
            validCount++;
        }
    }

    // Process each record with the callback function
    if (preprocessFunc != NULL) {
        pthread_mutex_lock(&lock);
        for (size_t i = 0; i < validCount; ++i) {
            preprocessFunc(&records[i]);
        }
        pthread_mutex_unlock(&lock);
    }

    // Aggregate stats
    aggregateStats(records, validCount, NULL);

    // Free resources
    for (size_t i = 0; i < validCount; ++i) {
        freeRecord(&records[i]);
    }
    free(records);
    free(timestamps);
    pthread_mutex_destroy(&lock);
}

// Example usage of preprocess function
void examplePreprocess(Record *record) {
