#define INITIAL_TABLE_SIZE 16
#define MAX_RECORDS 1024

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t size;
    pthread_mutex_t lock;
    size_t count;
} HashTable;

HashTable* create_hash_table(size_t initial_size) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->size = initial_size;
    ht->table = calloc(ht->size, sizeof(HashNode*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    ht->count = 0;
    return ht;
}

unsigned int hash(int key, size_t table_size) {
    return (unsigned)(key % table_size);
}

void resize_hash_table(HashTable* ht);

int insert_record(HashTable* ht, Record record) {
    pthread_mutex_lock(&ht->lock);

    if (ht->count >= MAX_RECORDS) {
        printf("Maximum records limit reached.\n");
        pthread_mutex_unlock(&ht->lock);
        return -1;
    }

    unsigned int index = hash(record.key, ht->size);
    HashNode* newNode = malloc(sizeof(HashNode));
    if (!newNode) {
        pthread_mutex_unlock(&ht->lock);
        return -2;
    }
    *newNode = (HashNode){record, NULL};

    newNode->next = ht->table[index];
    ht->table[index] = newNode;

    ht->count++;
    if (ht->count > ht->size) {
        resize_hash_table(ht);
    }

    pthread_mutex_unlock(&ht->lock);
    return 0;
}

Record* retrieve_record(HashTable* ht, int key) {
    unsigned int index = hash(key, ht->size);

    HashNode* node = ht->table[index];
    while (node) {
        if (node->record.key == key) {
            Record* rec = malloc(sizeof(Record));
            if (!rec) return NULL;
            *rec = node->record;
            return rec;
        }
        node = node->next;
    }

    return NULL;
}

int delete_record(HashTable* ht, int key) {
    pthread_mutex_lock(&ht->lock);

    unsigned int index = hash(key, ht->size);
    HashNode *node = ht->table[index], *prev = NULL;

    while (node) {
        if (node->record.key == key) {
            if (prev) prev->next = node->next;
            else ht->table[index] = node->next;

            free(node);
            ht->count--;
            pthread_mutex_unlock(&ht->lock);
            return 0;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return -1;
}

void resize_hash_table(HashTable* ht) {
    size_t new_size = ht->size * 2;
    HashNode** new_table = calloc(new_size, sizeof(HashNode*));
    if (!new_table) return;

    for (size_t i = 0; i < ht->size; ++i) {
        HashNode* node = ht->table[i];
        while (node) {
            unsigned int index = hash(node->record.key, new_size);
            HashNode* next_node = node->next;
            node->next = new_table[index];
            new_table[index] = node;
            node = next_node;
        }
    }

    free(ht->table);
    ht->table = new_table;
    ht->size = new_size;
}

void destroy_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        HashNode* node = ht->table[i];
        while (node) {
            HashNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int main() {
    HashTable* db = create_hash_table(INITIAL_TABLE_SIZE);

    if (!db) return -1;

    Record rec1 = {1, 1000, time(NULL)};
    insert_record(db, rec1);

    Record* retrieved_rec = retrieve_record(db, 1);
    if (retrieved_rec) {
        printf("Retrieved record: key=%d, offset=%ld, timestamp=%ld\n", 
               retrieved_rec->key, retrieved_rec->offset, retrieved_rec->timestamp);
        free(retrieved_rec);
    }

    delete_record(db, 1);

    destroy_hash_table(db);
    return 0;
}
```']

