// Function prototype
void manage_records(int num_records);

int main() {
    int num_records;

    printf("Enter number of records: ");
    if (scanf("%d", &num_records) != 1 || num_records <= 0) {
        fprintf(stderr, "Invalid input. Please enter a positive integer.\n");
        return EXIT_FAILURE;
    }

    manage_records(num_records);

    return EXIT_SUCCESS;
}

// Function to dynamically allocate and initialize records.
void manage_records(int num_records) {
    // Seed the random number generator for unique sequences in each run.
    srand((unsigned int)time(NULL));

    Record* records = NULL;  // Pointer to hold dynamic allocation of records array.
    size_t* offsets = NULL;  // Separate array to hold cumulative sum of sizes.

    if (num_records <= 0) {
        fprintf(stderr, "Number of records must be greater than zero.\n");
        return;
    }

    try {
        // Allocate memory for the record array and the offset array.
        records = (Record*)calloc(num_records, sizeof(Record));
        offsets = (size_t*)calloc(num_records + 1, sizeof(size_t)); // Extra space for cumulative sum logic

        if (!records || !offsets) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(records);
            free(offsets);
            return;
        }

        size_t current_offset = 0;

        // Initialize records and compute offsets.
        for (int i = 0; i < num_records; ++i) {
            records[i].value = rand();  // Assign a random number to value
            records[i].key = "UniqueKey"; // Placeholder key

            current_offset += sizeof(records[i]);  // Compute the offset based on record size
            offsets[i + 1] = current_offset;
        }

        // Output initialized data for verification.
        printf("Record values and cumulative offsets:\n");
        for (int i = 0; i < num_records; ++i) {
            printf("Value: %d, Offset: %zu\n", records[i].value, offsets[i + 1]);
        }
    } catch (...) {
        // Handle potential failures gracefully
        fprintf(stderr, "An error occurred during record management.\n");
        free(records);
        free(offsets);
        return;
    }

    // Free allocated memory to prevent leaks.
    free(records);
    free(offsets);

    printf("Memory successfully freed. Records managed and released cleanly.\n");
}
```

