int initializeDataStructure(int numRecords, long *cumulativeSums) {
    if (numRecords <= 0 || numRecords > INT_MAX / sizeof(long)) {
        return INVALID_INPUT;
    }

    // Allocate memory for the arrays.
    long* offsets = malloc(numRecords * sizeof(long));
    int* keys = malloc(numRecords * sizeof(int));
    record* records = malloc(numRecords * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return MEMORY_ALLOCATION_FAILED;
    }

    // Initialize cumulative sum array.
    cumulativeSums[0] = 0;

    // Fetch configuration for random value generation range.
