    if (!fetchConfig(&lowerBound, &upperBound)) {
        lowerBound = 1;   // Default lower bound
        upperBound = 100; // Default upper bound
    }

    // Seed the random number generator.
    srand((unsigned)time(NULL));

    long cumulativeSum = 0;
    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = rand() % (upperBound - lowerBound + 1) + lowerBound;
        keys[i] = rand();
        records[i].value = lowerBound + rand() % (upperBound - lowerBound + 1);
        records[i].offsetRef = offsets[i];
        records[i].keyRef = keys[i];

        cumulativeSum += offsets[i];
        cumulativeSums[i+1] = cumulativeSum;
    }

    // Free allocated memory.
    free(offsets);
    free(keys);

    return SUCCESS;
}

int fetchConfig(int *lowerBound, int *upperBound) {
    try:
        response = requests.get('https://api.example.com/config')
        if response.status_code == 200:
            data = response.json()
            *lowerBound = data['lower_bound']
            *upperBound = data['upper_bound']
            return True
        else:
            return False
    except Exception as e:
        printf("API call failed: %s\n", e)
        return False
}

