#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Define the maximum size limit for allocation to prevent out-of-memory errors.
#define MAX_SIZE_LIMIT 1024 * 1024 // Example: 1MB

typedef struct {
    long offset;
    int key;
    int value;
} record;

// Thread-safe random number generator initialization
pthread_mutex_t rng_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int seed;

void set_seed(unsigned int new_seed) {
    pthread_mutex_lock(&rng_lock);
    seed = new_seed;
    pthread_mutex_unlock(&rng_lock);
}

int thread_safe_random(int min, int max) {
    pthread_mutex_lock(&rng_lock);
    int range = (max - min) + 1;
    int random_number = rand_r(&seed) % range + min;
    pthread_mutex_unlock(&rng_lock);
    return random_number;
}

// Function to allocate memory for records and arrays
record* initialize_records(int num_records, int max_key_value, int *error_code) {
    if (num_records <= 0 || num_records > MAX_SIZE_LIMIT / sizeof(record)) {
        *error_code = -1; // Invalid input size
        return NULL;
    }

    set_seed(time(NULL)); // Seed the random number generator

    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        *error_code = -2; // Memory allocation failed for records
        return NULL;
    }

    long* offsets = (long*)calloc(num_records, sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        free(records);
        free(offsets); // Safe to call since calloc was used
        free(keys);
        *error_code = -3; // Memory allocation failed for offsets or keys
        return NULL;
    }

    int used_keys[MAX_SIZE_LIMIT] = {0}; // To track used keys, assuming reasonable upper limit

    for (int i = 0; i < num_records; i++) {
        records[i].value = thread_safe_random(1, 100); // Random value between 1 and 100
        int new_key;
        do {
            new_key = thread_safe_random(1, max_key_value);
        } while (used_keys[new_key]);

        used_keys[new_key] = 1; // Mark the key as used

        records[i].key = new_key;
        records[i].offset = i; // Initial offset, will update this later
    }

    // Compute cumulative sum offsets
    long total_offset = 0;
    for (int i = 0; i < num_records; i++) {
        offsets[i] = total_offset;
        total_offset += sizeof(record);
    }

    free(offsets); // Free the temporary offset array, not needed anymore

    *error_code = 0; // Success
    return records;
}

// Function to deallocate memory
void cleanup_records(record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    int num_records, max_key_value, error_code;

    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    printf("Enter the maximum key value: ");
    scanf("%d", &max_key_value);

    record *records = initialize_records(num_records, max_key_value, &error_code);

    if (error_code != 0) {
        fprintf(stderr, "Error initializing records: %d\n", error_code);
        return EXIT_FAILURE;
    }

    // Use the records here...

    cleanup_records(records); // Ensure all allocated memory is freed
    return EXIT_SUCCESS;
}
