            fprintf(stderr, "Memory allocation failed for message\n");
            return;
        }

        pthread_mutex_lock(&lock);
        logArray[i] = entry;

        // Update histogram
        histogram.bins[entry.severity]++;

        // Add to rolling window
        if (rollingWindow.size < rollingWindow.capacity) {
            rollingWindow.values[rollingWindow.size++] = (double)entry.timestamp;
        } else {
            memmove(rollingWindow.values, &rollingWindow.values[1], 
                    (rollingWindow.capacity - 1) * sizeof(double));
            rollingWindow.values[rollingWindow.capacity - 1] = (double)entry.timestamp;
        }

        if (callback) callback(&entry);
        pthread_mutex_unlock(&lock);
    }

    freeResources(logArray, &histogram, &rollingWindow);
}
