#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_LEVEL 5

typedef struct {
    unsigned long timestamp;
    int log_level;
    char message[256];
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LogManager;

typedef void (*PreprocessFunc)(LogEntry *);

unsigned long seed = 12345; // Seed for RNG

unsigned long generateTimestamp() {
    seed = (1103515245 * seed + 12345);
    return (unsigned long)seed % (24*60*60); // Simulating seconds in a day
}

void initMemoryPool(LogManager *manager, size_t initialCapacity) {
    manager->entries = malloc(initialCapacity * sizeof(LogEntry *));
    manager->count = 0;
    manager->capacity = initialCapacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void resizeMemoryPool(LogManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t newCapacity = manager->capacity * 2;
    LogEntry **newEntries = realloc(manager->entries, newCapacity * sizeof(LogEntry *));
    if (newEntries != NULL) {
        manager->entries = newEntries;
        manager->capacity = newCapacity;
    }
    pthread_mutex_unlock(&manager->lock);
}

void addLogEntry(LogManager *manager, unsigned long timestamp, int log_level, const char *message, PreprocessFunc preprocess) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        resizeMemoryPool(manager);
    }
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    strncpy(entry->message, message, sizeof(entry->message) - 1);
    preprocess(entry); // Apply preprocessing function
    manager->entries[manager->count++] = entry;
    pthread_mutex_unlock(&manager->lock);
}

void defaultPreprocess(LogEntry *entry) {
    // Default preprocessing (identity function)
}

typedef struct {
    int total;
    int min_log_level;
    int max_log_level;
    double avg_log_level;
} Metrics;

Metrics calculateMetrics(const LogManager *manager) {
    if (manager->count == 0) return (Metrics){0, MAX_LOG_LEVEL, -1, 0.0};

    int sum_levels = 0;
    int min_level = manager->entries[0]->log_level;
    int max_level = manager->entries[0]->log_level;

    for (size_t i = 0; i < manager->count; ++i) {
        LogEntry *entry = manager->entries[i];
        sum_levels += entry->log_level;
        if (entry->log_level < min_level) min_level = entry->log_level;
        if (entry->log_level > max_level) max_level = entry->log_level;
    }

    return (Metrics){
        .total = (int)manager->count,
        .min_log_level = min_level,
        .max_log_level = max_level,
        .avg_log_level = (double)sum_levels / manager->count
    };
}

void processAndAggregateLogData(PreprocessFunc preprocess) {
    if (!preprocess) preprocess = defaultPreprocess;

    LogManager manager;
    initMemoryPool(&manager, 10);

    char buffer[512];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        unsigned long timestamp = generateTimestamp();
        int log_level = rand() % MAX_LOG_LEVEL; // Random log level for demonstration
        addLogEntry(&manager, timestamp, log_level, buffer, preprocess);
    }

    Metrics metrics = calculateMetrics(&manager);

    printf("Total logs: %d\n", metrics.total);
    printf("Min log level: %d\n", metrics.min_log_level);
    printf("Max log level: %d\n", metrics.max_log_level);
    printf("Average log level: %.2f\n", metrics.avg_log_level);

    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.entries[i]);
    }
    free(manager.entries);
    pthread_mutex_destroy(&manager.lock);
}

int main() {
    processAndAggregateLogData(NULL);
    return 0;
}
