#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_HASH_SIZE 1024
#define SESSION_EXPIRY_TIME (60 * 60) // 1 hour in seconds

typedef struct {
    int userId;
    int subscriptionId;
    char sessionToken[256];
    time_t lastAccessTime; // For tracking expiration
} UserSession;

typedef struct SessionNode {
    UserSession session;
    struct SessionNode* next;
} SessionNode;

// Hash table structure with lock for thread safety
typedef struct {
    size_t hashSize;
    SessionNode** buckets;
    pthread_mutex_t* locks;
} SessionHashTable;

// Record and timestamp structures
typedef struct {
    int value;
    char key[256];
    long* dynamicData;
} Record;

typedef struct {
    time_t lastAccessTime;
} TimestampMarker;

SessionHashTable* createHashTable(size_t hashSize) {
    SessionHashTable* table = malloc(sizeof(SessionHashTable));
    if (!table) return NULL;

    table->hashSize = hashSize;
    table->buckets = calloc(hashSize, sizeof(SessionNode*));
    table->locks = malloc(hashSize * sizeof(pthread_mutex_t));

    for (size_t i = 0; i < hashSize; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

void freeHashTable(SessionHashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->hashSize; ++i) {
        SessionNode* node = table->buckets[i];
        while (node) {
            SessionNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    for (size_t i = 0; i < table->hashSize; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }
    free(table->locks);
    free(table);
}

unsigned long hashUserId(int userId, size_t hashSize) {
    return (unsigned long)userId % hashSize;
}

void addSession(SessionHashTable* table, UserSession session) {
    if (!table) return;

    unsigned long index = hashUserId(session.userId, table->hashSize);
    pthread_mutex_lock(&table->locks[index]);

    SessionNode* newNode = malloc(sizeof(SessionNode));
    if (!newNode) {
        pthread_mutex_unlock(&table->locks[index]);
        return;
    }

    newNode->session = session;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->locks[index]);
}

void cleanupSessions(SessionHashTable* table, time_t currentTime) {
    if (!table) return;

    for (size_t i = 0; i < table->hashSize; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        SessionNode *node = table->buckets[i], *prev = NULL;
        while (node) {
            if (currentTime - node->session.lastAccessTime > SESSION_EXPIRY_TIME) {
                SessionNode* toDelete = node;
                node = node->next;
                if (prev) prev->next = node;
                else table->buckets[i] = node;

                free(toDelete);
            } else {
                prev = node;
                node = node->next;
            }
        }

        pthread_mutex_unlock(&table->locks[i]);
    }
}

int findMax(int* array, size_t size) {
    if (size == 0) return INT_MIN;
    int maxVal = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > maxVal) maxVal = array[i];
    }
    return maxVal;
}

void sessionManager() {
