    if (!table) return;

    int* numbers = NULL;
    size_t capacity = 0, count = 0;
    const int sentinel = -1; // Sentinel value for input termination

    while (1) {
        int num;
        scanf("%d", &num);

        if (num == sentinel) break;

        if (count >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) break; // Handle memory allocation failure
        }

        numbers[count++] = num;
    }

    if (numbers) {
        int maxNumber = findMax(numbers, count);
        printf("Largest number: %d\n", maxNumber);
        free(numbers);
    }

    time_t currentTime = time(NULL);
    cleanupSessions(table, currentTime);

    freeHashTable(table);
}

int main() {
    sessionManager();
    return 0;
}
