    void** payload;
    size_t metadataCount;
    size_t payloadCount;
} logEntry;

typedef struct {
    logEntry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} logCollection;

logCollection* initializeLogCollection(size_t initialCapacity) {
    logCollection* collection = (logCollection*)malloc(sizeof(logCollection));
    if (!collection) return NULL;

    collection->entries = (logEntry**)calloc(initialCapacity, sizeof(logEntry*));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void resizeLogCollectionIfNeeded(logCollection* collection) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        logEntry** newEntries = (logEntry**)realloc(collection->entries, newCapacity * sizeof(logEntry*));
        if (!newEntries) {
            pthread_mutex_unlock(&collection->mutex);
            return; // Handle error as needed
        }
        collection->entries = newEntries;
        collection->capacity = newCapacity;
    }
    pthread_mutex_unlock(&collection->mutex);
}

void freeLogCollection(logCollection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        logEntry* entry = collection->entries[i];
        free(entry->timestamp);
        free(entry->message);

        for (size_t j = 0; j < entry->metadataCount; ++j) {
            free(entry->metadata[j]);
        }
        free(entry->metadata);

        for (size_t j = 0; j < entry->payloadCount; ++j) {
            free(entry->payload[j]);
        }
        free(entry->payload);
        free(entry);
    }

    free(collection->entries);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
