    if (callback) callback(session);
}

void cleanupExpiredSessions(CustomHashTable *ht, time_t currentTime, int expiryTimeSecs) {
    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->size; ++i) {
        HashTableEntry **entryPtr = &ht->table[i];
        while (*entryPtr != NULL) {
            if (difftime(currentTime, (*entryPtr)->session->timestamp) > expiryTimeSecs) {
                HashTableEntry *toDelete = *entryPtr;
                *entryPtr = toDelete->next;
                free(toDelete);
            } else {
                entryPtr = &(*entryPtr)->next;
            }
        }
    }

    pthread_mutex_unlock(&ht->lock);
}

void registerSessionCallback(void (*callback)(UserSession *)) {
