#define INITIAL_RECORD_SIZE 10

typedef struct {
    int value;
    char *key;
    long *variable;
} Record;

// Memory pool structure for managing allocations
typedef struct {
    size_t block_size;
    void **blocks;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->capacity = initial_capacity;
    pool->blocks = (void **)malloc(pool->capacity * sizeof(void *));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < pool->capacity; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            while (i > 0) {
                free(pool->blocks[--i]);
            }
            free(pool->blocks);
            free(pool);
            return NULL;
        }
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->capacity == 0) {
        void **new_blocks = (void **)realloc(pool->blocks, sizeof(void *) * (pool->capacity + INITIAL_RECORD_SIZE));
        if (!new_blocks) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->blocks = new_blocks;
        for (size_t i = pool->capacity; i < pool->capacity + INITIAL_RECORD_SIZE; ++i) {
            pool->blocks[i] = malloc(pool->block_size);
            if (!pool->blocks[i]) {
                while (i > pool->capacity) {
                    free(pool->blocks[--i]);
                }
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }
        }
        pool->capacity += INITIAL_RECORD_SIZE;
    }

    void *allocated = pool->blocks[--pool->capacity];
    pthread_mutex_unlock(&pool->lock);
    return allocated;
}

void memory_pool_free(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->capacity; ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void processAndAggregateRecords(size_t num_records, void (*callback)(Record *)) {
