#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int sensor_id;
    double voltage_reading;
    char status_indicator;
} SensorData;

typedef struct Node {
    SensorData data;
    struct Node* next;
} Node;

// Function prototypes
Node* initialize_sensor_data(int initial_capacity);
void resize_sensor_data(Node** head, int new_capacity);
void populate_voltage_readings(Node* head, double min_voltage, double max_voltage);
void update_status_indicators(Node* head);
int filter_by_status(const SensorData* data, char status_to_filter);
int compare_by_status(const void* a, const void* b);

// Function to dynamically manage memory for sensor data
Node* initialize_sensor_data(int initial_capacity) {
    Node* head = NULL;
    Node* current = NULL;

    for (int i = 0; i < initial_capacity; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        new_node->data.sensor_id = i;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            current = head;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

void resize_sensor_data(Node** head, int new_capacity) {
    Node* current = *head;
    while (current != NULL && new_capacity > 0) {
        current = current->next;
        --new_capacity;
    }

    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
}

void populate_voltage_readings(Node* head, double min_voltage, double max_voltage) {
    if (!head) return;

    int count = 0;
    Node* current = head;
    while (current != NULL) {
        current->data.voltage_reading = 
            min_voltage + (max_voltage - min_voltage) * log1p(count) / log1p(INT_MAX);
        ++count;
        current = current->next;
    }
}

void update_status_indicators(Node* head) {
    if (!head) return;

    // Simulate external data source updates
    Node* current = head;
    while (current != NULL) {
        // Placeholder for actual status update logic
        current->data.status_indicator = 'O';  // Example: Online status
        current = current->next;
    }
}

int filter_by_status(const SensorData* data, char status_to_filter) {
    return data->status_indicator == status_to_filter;
}

int compare_by_status(const void* a, const void* b) {
    SensorData* sensor_a = (SensorData*)a;
    SensorData* sensor_b = (SensorData*)b;

    if (sensor_a->status_indicator < sensor_b->status_indicator)
        return -1;
    if (sensor_a->status_indicator > sensor_b->status_indicator)
        return 1;
    return 0;
}

void free_sensor_data(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
