    record *data;
    size_t size;
    size_t capacity;
} RecordList;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

int initialize_list(RecordList *list, size_t initial_size) {
    list->capacity = (initial_size > 0 ? initial_size : INITIAL_CAPACITY);
    list->size = 0;
    list->data = malloc(list->capacity * sizeof(record));
    if (!list->data) return -1; // Memory allocation failure
    return 0;
}

int update_record(RecordList *list, size_t index, double new_value) {
    if (index >= list->size) return -2; // Invalid index
    list->data[index].value = new_value;
    return 0;
}

int append_record(RecordList *list, double value) {
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        record *new_data = realloc(list->data, new_capacity * sizeof(record));
        if (!new_data) return -1; // Memory allocation failure
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++].value = value;
    return 0;
}

void iterate_records(const RecordList *list, void (*callback)(const record *)) {
    for (size_t i = 0; i < list->size; ++i) {
        callback(&list->data[i]);
    }
}

int free_list(RecordList *list) {
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    return 0;
}

void record_callback(const record *rec) {
