#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} DataRecord;

// Memory pool structure for managing memory blocks
typedef struct {
    size_t block_size;
    size_t total_blocks;
    void *memory_pool;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t block_size, size_t total_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->memory_pool = malloc(block_size * total_blocks);
    if (!pool->memory_pool) {
        fprintf(stderr, "Failed to allocate memory pool.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void *allocate_from_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *block = malloc(pool->block_size);
    if (!block) {
        fprintf(stderr, "Memory allocation failed from pool.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory_pool);
}

// Function to initialize an array of records
void initialize_records(DataRecord **records, size_t num_records, int min_value, int max_value, MemoryPool *pool) {
    if (!records || !num_records) return;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_records; ++i) {
        records[i] = allocate_from_memory_pool(pool);

        // Set fields with appropriate values
        records[i]->offset = rand();          // Example offset, can be replaced by a real value
        records[i]->key = rand() % 10000;     // Random key, modify as necessary
        records[i]->record.value = min_value + rand() % (max_value - min_value + 1);
    }
}

int main() {
    const size_t num_records = 1000000;
    DataRecord *records[num_records];

    MemoryPool pool;
    init_memory_pool(&pool, sizeof(DataRecord), num_records);

    initialize_records(records, num_records, 10, 100, &pool);

    // Clean up memory
    free_memory_pool(&pool);

    return 0;
}
```

