['Below is a C implementation of a dynamic list manager for `record` structures containing `double` values. The code considers performance optimization, memory management, error handling, and integration with existing pipelines.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double value;
} record;

typedef struct {
    record *data;
    size_t capacity;
    size_t size;
} RecordList;

// Function to initialize the list
void initRecordList(RecordList *list) {
    list->capacity = 1024; // Initial capacity, can be adjusted based on expected load
    list->size = 0;
    list->data = (record *)aligned_alloc(64, list->capacity * sizeof(record)); // Align to cache line size for optimization

    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
}

// Function to resize the list dynamically
void resizeRecordList(RecordList *list) {
    list->capacity *= 2;
    record *new_data = (record *)aligned_realloc(list->data, 64, list->capacity * sizeof(record));

    if (!new_data) {
        fprintf(stderr, "Failed to reallocate memory\n");
        exit(EXIT_FAILURE);
    }

    list->data = new_data;
}

// Function to add a record
void addRecord(RecordList *list, double value) {
    if (list->size == list->capacity) {
        resizeRecordList(list);
    }
    list->data[list->size++].value = value;
}

// Function to remove a record by index with error handling
int removeRecord(RecordList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Invalid index\n");
        return -1; // Error code for invalid index
    }

    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }
    --list->size;
    return 0; // Success
}

// Function to clear the list and free memory
void clearRecordList(RecordList *list) {
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
}

// Function to destroy the list
void destroyRecordList(RecordList *list) {
    clearRecordList(list);
}
```

### Key Considerations:
- **Memory Alignment**: `aligned_alloc` is used for memory allocation to ensure cache line optimization.
- **Dynamic Resizing**: The capacity of the list doubles when needed, which balances between performance and memory usage.
- **Error Handling**: The code includes checks for invalid operations such as accessing an out-of-bounds index.
- **Scalability**: While this implementation is single-threaded, it can be extended to a distributed system by managing separate `RecordList` instances across nodes.

This function provides a simple yet efficient way to manage dynamic lists of records, with considerations for performance and scalability in high-throughput environments.']

