size_t record_capacity = 0;
transform_func_t transform_function = NULL;

void resize_array_if_needed() {
    if (current_size >= capacity) {
        capacity *= 2; // Double the capacity
        offsets = external_realloc(offsets, sizeof(long) * capacity);
        keys = external_realloc(keys, sizeof(int) * capacity);

        if (!offsets || !keys) {
            perror("Memory allocation failed during resize");
            exit(EXIT_FAILURE);
        }
    }
}

void initialize_offsets_keys() {
    pthread_mutex_lock(&offset_keys_lock);

    offsets = external_malloc(sizeof(long) * INITIAL_SIZE);
    keys = external_malloc(sizeof(int) * INITIAL_SIZE);

    if (!offsets || !keys) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    current_size = 0;
    capacity = INITIAL_SIZE;

    pthread_mutex_unlock(&offset_keys_lock);
}

void initialize_records(size_t size, unsigned int seed) {
    pthread_mutex_lock(&records_lock);

    if (record_capacity < size) {
        record_capacity = size;
        records = external_realloc(records, sizeof(record) * record_capacity);
        if (!records) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < size; ++i) {
        srand(seed + i);
        records[i].value = rand() % (RAND_RANGE_MAX - RAND_RANGE_MIN + 1) + RAND_RANGE_MIN;
    }

    pthread_mutex_unlock(&records_lock);
}

void process_entry(record* entry, transform_func_t transform) {
    if (transform != NULL) {
        transform(entry);
    }
}

void flush_to_storage(const char* filepath) {
    FILE* file = fopen(filepath, "w");
    if (!file) {
        perror("Failed to open storage file");
        return;
    }

    for (size_t i = 0; i < current_size; ++i) {
        fprintf(file, "Offset: %ld, Key: %d\n", offsets[i], keys[i]);
    }

    fclose(file);
}

void dataProcessor(transform_func_t transform) {
    initialize_offsets_keys();
    initialize_records(INITIAL_SIZE, 42); // Example seed for reproducibility

    int key;
    while (true) {
        printf("Enter a key (-9999 to exit): ");
        scanf("%d", &key);

        if (key == SENTINEL) break;

        pthread_mutex_lock(&offset_keys_lock);
        resize_array_if_needed();
        offsets[current_size] = rand(); // Simulating an offset
        keys[current_size++] = key;
        pthread_mutex_unlock(&offset_keys_lock);

        record new_record;
        new_record.value = key;  // Simplistic example of setting the value

        pthread_mutex_lock(&records_lock);
        if (current_size > record_capacity) {
            initialize_records(current_size * 2, rand()); // Expand records with a random seed
        }

        process_entry(&new_record, transform);
        records[current_size - 1] = new_record; // Store the processed entry

        pthread_mutex_unlock(&records_lock);

        if (current_size % 100 == 0) {
            flush_to_storage("data_store.txt"); // Periodic storage flush
        }
    }

    free(offsets);
    free(keys);
    free(records);
}

void example_transform(record* r) {
    r->value *= 2; // Example transformation: double the value
}
