#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    double value;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} RecordList;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

RecordList* init_record_list(size_t initial_capacity) {
    RecordList *list = malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->capacity = (initial_capacity > 0) ? initial_capacity : INITIAL_CAPACITY;
    list->records = calloc(list->capacity, sizeof(record));
    if (!list->records) {
        free(list);
        return NULL;
    }
    list->count = 0;

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int update_record(RecordList *list, size_t index, double value) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index
    }

    list->records[index].value = value;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

int append_record(RecordList *list, double value) {
    pthread_mutex_lock(&list->mutex);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        record *new_records = realloc(list->records, new_capacity * sizeof(record));
        if (!new_records) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }

    list->records[list->count].value = value;
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void iterate_records(RecordList *list, void (*callback)(record *)) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        callback(&list->records[i]);
    }

    pthread_mutex_unlock(&list->mutex);
}

void export_records_to_file(RecordList *list, const char *filename, const char *format) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "%s\n", format == "CSV" ? "value" : "{\"records\":[");

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (format == "CSV") {
            fprintf(file, "%f", list->records[i].value);
            if (i != list->count - 1) {
                fputc(',', file);
            }
        } else { // JSON
            fprintf(file, "{\"value\":%f}", list->records[i].value);
            if (i != list->count - 1) {
                fputc(',', file);
            }
        }
    }

    if (format == "JSON") {
        fprintf(file, "]}");
    }

    pthread_mutex_unlock(&list->mutex);

    fclose(file);
}

void compress_list(RecordList *list) {
    pthread_mutex_lock(&list->mutex);

    if (list->count < list->capacity / GROWTH_FACTOR) {
        size_t new_capacity = list->capacity / GROWTH_FACTOR;
        record *new_records = realloc(list->records, new_capacity * sizeof(record));
        if (new_records) {
            list->records = new_records;
            list->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void free_record_list(RecordList *list) {
    pthread_mutex_destroy(&list->mutex);

    if (list) {
        free(list->records);
        free(list);
    }
}
