        var timestamp = DateTime.UtcNow.Ticks;
        var randomFileType = new[] { ".txt", ".json", ".xml" }[new Random().Next(0, 3)];

        var safeBaseFilename = RemoveInvalidCharacters(baseFilename);
        return $"{safeBaseFilename}_{uniqueId}_{timestamp}{randomFileType}";
    }

    private static string RemoveInvalidCharacters(string filename)
    {
