    }

    private static string DecryptString(string cipherText, string key)
    {
        using var aes = Aes.Create();
        var keyBytes = Encoding.UTF8.GetBytes(key.PadRight(32));
        aes.Key = keyBytes;
        aes.IV = new byte[16]; // Assuming zero IV for simplicity

