        long offset;
        int key;
        char *str;
    };
} Record;

#define MAX_RECORDS 10000
#define STRING_MAX_LENGTH 100

void initialize_records(Record *records, size_t count) {
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        records[i].type = rand() % 3;

        if (records[i].type == TYPE_LONG) {
            records[i].offset = rand();
        } else if (records[i].type == TYPE_INT) {
            records[i].key = rand() % 1000;
        } else { // TYPE_STRING
            records[i].str = malloc(STRING_MAX_LENGTH + 1);
            if (!records[i].str) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            for (int j = 0; j < STRING_MAX_LENGTH; ++j) {
                records[i].str[j] = 'a' + rand() % 26;
            }
            records[i].str[STRING_MAX_LENGTH] = '\0';
        }
    }
}

void free_records(Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i].type == TYPE_STRING && records[i].str) {
            free(records[i].str);
        }
    }
}

int read_integers(int **array, const char *file_path) {
    FILE *file;
    int num;

    if (file_path) {
        file = fopen(file_path, "r");
        if (!file) {
            perror("Error opening file");
            return -1;
        }
    } else {
        file = stdin;
    }

    *array = malloc(MAX_RECORDS * sizeof(int));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return -1;
    }

    size_t count = 0;
    while (count < MAX_RECORDS && fscanf(file, "%d", &num) == 1) {
        (*array)[count++] = num;
    }

    if (!feof(file) && ferror(file)) {
        perror("Error reading integers");
        free(*array);
        fclose(file);
        return -1;
    }

    fclose(file);

    // Reallocate array to the actual size
    *array = realloc(*array, count * sizeof(int));
    if (!*array) {
        fprintf(stderr, "Memory reallocation failed\n");
        return -1;
    }

    return (int)count;
}

void allocate_and_initialize_arrays(long **offsets, int **keys, Record **records, size_t record_count) {
    *offsets = malloc(record_count * sizeof(long));
    if (!*offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(record_count * sizeof(int));
    if (!*keys) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *records = malloc(record_count * sizeof(Record));
    if (!*records) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 1000;

        (*records)[i].type = TYPE_INT;
        (*records)[i].key = rand() % 100;
    }
}

int main() {
    Record *records;
    size_t record_count = 100;

    allocate_and_initialize_arrays(NULL, NULL, &records, record_count);

    initialize_records(records, record_count);

    int *integers;
    const char *file_path = "numbers.txt";
    int num_integers = read_integers(&integers, file_path);

    if (num_integers != -1) {
        for (int i = 0; i < num_integers; ++i) {
            printf("%d\n", integers[i]);
        }
    }

    free_records(records, record_count);
    free(records);
    free(integers);

    return 0;
}
