#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    double value;
    char *name;
    size_t index;
} data_point;

// Function to trim whitespace from a string
char* trim_whitespace(char* str) {
    char* end;

    // Trim leading space
    while(isspace((unsigned char)*str)) str++;

    if(*str == 0) return str; // All spaces?

    // Trim trailing space
    end = str + strlen(str) - 1;
    while(end > str && isspace((unsigned char)*end)) end--;

    // Write new null terminator character
    *(end+1) = '\0';

    return str;
}

// Function to parse a line from the CSV file and populate data_point struct
int parse_line(char *line, data_point *dp, size_t index) {
    char *token;
    int field_count = 0;

    dp->index = index;

    token = strtok(line, ",");
    if (token == NULL) return -1; // No double value

    dp->value = strtod(token, NULL);
    field_count++;

    token = strtok(NULL, ",");
    if (token != NULL && *token != '\0') {
        dp->name = malloc(strlen(trim_whitespace(token)) + 1);
        if (dp->name == NULL) return -2; // Memory allocation failure
        strcpy(dp->name, trim_whitespace(token));
    } else {
        dp->name = NULL;
    }

    return field_count;
}

// Function to read data from a CSV file and populate an array of data_point structs
data_point* load_data_from_csv(const char *filename, size_t *num_points) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    data_point *data_points = NULL;
    size_t capacity = 10;
    size_t count = 0;

    // Allocate initial memory for data points
    data_points = malloc(capacity * sizeof(data_point));
    if (data_points == NULL) {
        fclose(file);
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        if (count >= capacity) {
            capacity *= 2;
            data_points = realloc(data_points, capacity * sizeof(data_point));
            if (data_points == NULL) {
                fclose(file);
                fprintf(stderr, "Memory reallocation failure\n");
                return NULL;
            }
        }

        int result = parse_line(line, &data_points[count], count);
        if (result > 0) { // Successfully parsed
            count++;
        } else if (result < 0) {
            fprintf(stderr, "Warning: Skipping malformed line\n");
        } else {
            fprintf(stderr, "Memory allocation failed for string field in data point %zu\n", count);
        }
    }

    *num_points = count;
    fclose(file);

    // Resize to exact number of points
    if (count < capacity) {
        data_points = realloc(data_points, count * sizeof(data_point));
        if (data_points == NULL && count > 0) { // Avoid freeing memory on malloc failure
            fprintf(stderr, "Memory reallocation failure during final resize\n");
            return NULL;
        }
    }

    return data_points;
}

// Function to free the allocated memory for data points
void free_data_points(data_point *data_points, size_t num_points) {
    if (data_points == NULL) return;

    for (size_t i = 0; i < num_points; ++i) {
        free(data_points[i].name);
    }
    free(data_points);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_points = 0;
    data_point *data_points = load_data_from_csv(argv[1], &num_points);

    if (data_points == NULL) {
        return EXIT_FAILURE;
    }

    // Example usage: print loaded data
    for (size_t i = 0; i < num_points; ++i) {
        printf("Index: %zu, Value: %.2f, Name: %s\n", data_points[i].index, data_points[i].value,
               data_points[i].name ? data_points[i].name : "NULL");
    }

    free_data_points(data_points, num_points);
    return EXIT_SUCCESS;
}
