#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    double value;
    char *label;
    size_t index;
} data_point;

typedef struct {
    char *description;
    int id;
} metadata;

typedef struct hash_node {
    size_t index;
    int count;
    struct hash_node *next;
} hash_node;

hash_node* create_hash_table(size_t size) {
    hash_node **table = calloc(size, sizeof(hash_node *));
    if (!table) return NULL;
    for (size_t i = 0; i < size; ++i) {
        table[i] = NULL;
    }
    return table;
}

unsigned long hash_index(size_t index, size_t table_size) {
    // Simple modulo-based hash function
    return index % table_size;
}

void add_to_hash_table(hash_node **table, size_t table_size, size_t index) {
    unsigned long hash_value = hash_index(index, table_size);
    hash_node *entry = table[hash_value];

    while (entry) {
        if (entry->index == index) {
            entry->count++;
            return;
        }
        entry = entry->next;
    }

    // Create a new node
    hash_node *new_entry = malloc(sizeof(hash_node));
    if (!new_entry) {
        fprintf(stderr, "Failed to allocate memory for hash table.\n");
        exit(EXIT_FAILURE);
    }
    new_entry->index = index;
    new_entry->count = 1;
    new_entry->next = table[hash_value];
    table[hash_value] = new_entry;
}

void read_data_points(const char *filename, data_point **data_array, size_t *num_points, hash_node **hash_table) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    double value;
    char label[MAX_STRING_LENGTH];
    size_t index;

    // First pass to count data points
    while (fscanf(file, "%lf,%255[^,],%zu\n", &value, label, &index) == 3) {
        add_to_hash_table(hash_table, 1000, index); // Assuming table size of 1000
    }

    *num_points = hash_index(index, 1000) + 1; // Estimate number of data points

    fseek(file, 0, SEEK_SET);

    *data_array = malloc(*num_points * sizeof(data_point));
    if (!*data_array) {
        fprintf(stderr, "Failed to allocate memory for data points.\n");
        exit(EXIT_FAILURE);
    }

    size_t i = 0;
    while (fscanf(file, "%lf,%255[^,],%zu\n", &value, label, &index) == 3) {
        (*data_array)[i].value = value;

        // Allocate and copy string
        char *str_copy = malloc(strlen(label) + 1);
        if (!str_copy) {
            fprintf(stderr, "Failed to allocate memory for label.\n");
            exit(EXIT_FAILURE);
        }
        strcpy(str_copy, label);

        (*data_array)[i].label = str_copy;
        (*data_array)[i].index = index;

        i++;
    }

    fclose(file);
}

void read_metadata(const char *filename, metadata **metadata_array, size_t *num_metadata) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    // Count number of metadata entries
    char description[MAX_STRING_LENGTH];
    int id;
    *num_metadata = 0;

    while (fscanf(file, "%255[^,],%d\n", description, &id) == 2) {
        (*num_metadata)++;
    }

    fseek(file, 0, SEEK_SET);

    *metadata_array = malloc(*num_metadata * sizeof(metadata));
    if (!*metadata_array) {
        fprintf(stderr, "Failed to allocate memory for metadata.\n");
        exit(EXIT_FAILURE);
    }

    size_t i = 0;
    while (fscanf(file, "%255[^,],%d\n", description, &id) == 2) {
        // Allocate and copy string
        char *str_copy = malloc(strlen(description) + 1);
        if (!str_copy) {
            fprintf(stderr, "Failed to allocate memory for metadata description.\n");
            exit(EXIT_FAILURE);
        }
        strcpy(str_copy, description);

        (*metadata_array)[i].description = str_copy;
        (*metadata_array)[i].id = id;

        i++;
    }

    fclose(file);
}

void init_arrays(const char *data_file, const char *meta_file) {
    data_point *data_array = NULL;
    size_t num_data_points = 0;
    hash_node *hash_table = create_hash_table(1000);

    metadata *metadata_array = NULL;
    size_t num_metadata = 0;

    read_data_points(data_file, &data_array, &num_data_points, &hash_table);
    read_metadata(meta_file, &metadata_array, &num_metadata);

    // Free allocated resources
    for (size_t i = 0; i < num_data_points; ++i) {
        free(data_array[i].label);
    }
    free(data_array);

    for (size_t i = 0; i < num_metadata; ++i) {
        free(metadata_array[i].description);
    }
    free(metadata_array);

    // Free hash table
    for (size_t i = 0; i < 1000; ++i) {
        hash_node *entry = hash_table[i];
        while (entry) {
            hash_node *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(hash_table);
}
```

