#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define packet structure
typedef struct {
    uint32_t packet_id;
    int64_t timestamp;
    uint32_t payload_length;
    unsigned char *payload;
} Packet;

// Memory pool configuration
#define POOL_SIZE 1024 // Number of blocks in the memory pool
#define BLOCK_SIZE sizeof(Packet) + 512 // Assuming maximum payload size

// Structure for managing memory pool
typedef struct {
    void* pool[POOL_SIZE];
    pthread_mutex_t lock;
    int free_index;
} MemoryPool;

MemoryPool mem_pool = {0};

// Initialize memory pool
void init_memory_pool() {
    pthread_mutex_init(&mem_pool.lock, NULL);
    mem_pool.free_index = 0;

    for (int i = 0; i < POOL_SIZE; ++i) {
        void* block = malloc(BLOCK_SIZE);
        if (block != NULL) {
            mem_pool.pool[i] = block;
        }
    }
}

// Allocate packet from memory pool
Packet* allocate_packet() {
    pthread_mutex_lock(&mem_pool.lock);

    Packet* packet = NULL;
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (mem_pool.pool[i] != NULL) {
            packet = (Packet*) mem_pool.pool[i];
            mem_pool.pool[i] = NULL;
            pthread_mutex_unlock(&mem_pool.lock);
            return packet;
        }
    }

    pthread_mutex_unlock(&mem_pool.lock);

    // No free block found; consider expanding pool or handling the situation
    printf("Memory pool exhausted\n");
    return NULL;
}

// Deallocate packet back to memory pool
void deallocate_packet(Packet* packet) {
    pthread_mutex_lock(&mem_pool.lock);

    if (packet != NULL && mem_pool.free_index < POOL_SIZE) {
        mem_pool.pool[mem_pool.free_index++] = (void*) packet;
    }

    pthread_mutex_unlock(&mem_pool.lock);
}

// Fill payload with a pattern based on packet ID and timestamp
void fill_packet_payload(Packet* packet) {
    if (packet == NULL || packet->payload == NULL) return;

    for (uint32_t i = 0; i < packet->payload_length; ++i) {
        packet->payload[i] = (unsigned char)((packet->packet_id + packet->timestamp + i) % 256);
    }
}

// Create a new packet with given ID and timestamp
Packet* create_packet(uint32_t id, int64_t ts) {
    Packet* packet = allocate_packet();
    if (packet == NULL) return NULL;

    // Initialize fields
    packet->packet_id = id;
    packet->timestamp = ts;
    packet->payload_length = 512; // Assume fixed payload size for simplicity
    packet->payload = ((unsigned char*) packet) + sizeof(Packet);

    fill_packet_payload(packet);

    return packet;
}

// Monitor current memory usage and allocated packets count
void monitor_memory_usage() {
    int free_blocks = POOL_SIZE - mem_pool.free_index;
    printf("Memory Usage: %d/%d blocks in use\n", free_blocks, POOL_SIZE);
}

int main() {
    init_memory_pool();

    // Example usage
    Packet* packet1 = create_packet(1, 1234567890L);
    monitor_memory_usage();

    deallocate_packet(packet1);
    monitor_memory_usage();

    return 0;
}
```

### Key Points:
- **Memory Pool**: Manages a pool of preallocated memory blocks to minimize dynamic allocation overhead.
- **Thread Safety**: Uses mutexes to ensure thread-safe operations on the memory pool.
- **Packet Initialization**: Populates packet fields and fills payload with data derived from ID and timestamp.
- **Monitoring**: Provides a function to track current memory usage.']

