    size_t key_size = sizeof(int) * (n / 2);
    size_t record_count = n; // Assuming maximum number of records is equal to n
    size_t record_size = sizeof(record) * record_count;

    if (offset_size + key_size + record_size > MAX_MEMORY) {
        return -1; // Error: memory limit exceeded
    }

    offsets = malloc(offset_size);
    keys = malloc(key_size);
    *records = malloc(record_size);

    if (!offsets || !keys || !(*records)) {
        free(offsets); free(keys); free(*records);
        return -2; // Error: allocation failed
    }

    memset(buffer, 0, 1024);

    srand(time(NULL)); // Seed the random number generator

    int min_value = 1;
    int max_value = record_count * 10; // Arbitrary range for uniqueness demonstration
    int* used_values = malloc(sizeof(int) * (max_value - min_value + 1));
    memset(used_values, 0, sizeof(int) * (max_value - min_value + 1));

    int successful_records = 0;

    for (int i = 0; i < record_count; ++i) {
        int unique_value_found = 0;

        while (!unique_value_found) {
            int random_value = rand() % (max_value - min_value + 1) + min_value;

            if (!used_values[random_value]) {
                used_values[random_value] = 1;
                (*records)[i].value = random_value;
                unique_value_found = 1;
                successful_records++;
            } else {
                // If we can't find a unique value, break out and adjust the count
                if (successful_records == record_count) {
                    free(used_values);
                    return -3; // Error: couldn't generate enough unique values
                }
            }
        }

        // Break early to prevent exceeding memory constraints on value uniqueness.
        if ((offset_size + key_size + sizeof(record) * successful_records) > MAX_MEMORY) {
            break;
        }
    }

    free(used_values);
    return successful_records; // Return the number of successfully initialized records
}
