        free(buffer);
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Helper function to check for uniqueness in an array
    int is_unique(int* arr, int len, int value) {
        for (int i = 0; i < len; ++i) {
            if (arr[i] == value) return 0;
        }
        return 1;
    }

    // Fill keys with unique values
    int key_index = 0;
    while (key_index < key_count) {
        int new_key = minValue + rand() % (maxValue - minValue + 1);
        if (is_unique(keys, key_index, new_key)) {
            keys[key_index++] = new_key;
        }
    }

    // Fill records with unique values
    int record_index = 0;
    while (record_index < num_records) {
        int new_value = minValue + rand() % (maxValue - minValue + 1);
        if (is_unique(keys, key_count, new_value)) { // Also check against keys for uniqueness
            records[record_index++].value = new_value;
        }
    }

    // Clean up resources
    free(buffer);
    free(offsets);
    free(keys);
    free(records);

    return record_index; // Number of successfully initialized records
}
