#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit: 1MB
#define RANDOM_MIN 0
#define RANDOM_MAX 100

typedef struct {
    int value;
} record;

// Function prototypes
void* allocate_memory(long offset_count, int key_count);
void initialize_records(record *records, size_t count);
int calculate_total_size(size_t long_size, size_t int_size, size_t record_size, size_t record_count);
void log_memory_usage(size_t used_memory);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Main function to allocate memory and initialize records
void* allocate_memory(long offset_count, int key_count) {
    size_t long_size = sizeof(long) * offset_count;
    size_t int_size = sizeof(int) * key_count;
    size_t record_count = 100; // Example record count
    size_t record_size = sizeof(record);

    size_t total_size = calculate_total_size(long_size, int_size, record_size, record_count);

    if (total_size > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory allocation error: Exceeds maximum memory usage.\n");
        return NULL;
    }

    long *offsets = malloc(long_size);
    int *keys = malloc(int_size);
    record *records = malloc(record_size * record_count);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation error: Failed to allocate memory.\n");
        free(offsets); // Free any allocated memory before returning
        free(keys);
        free(records);
        return NULL;
    }

    initialize_records(records, record_count);

    log_memory_usage(total_size);

    pthread_mutex_lock(&mutex);
    // Thread-safe operations on records can be added here.
    pthread_mutex_unlock(&mutex);

    return (void*)malloc(sizeof(long*) * 3 + sizeof(int*) + sizeof(record*) +
                        offsets - (long*)offsets + keys - (int*)keys + 
                        records - (record*)records);
}

// Initialize records with random values
void initialize_records(record *records, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
