['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void* safe_malloc(size_t size, const char* description) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory for %s\n", description);
    }
    return ptr;
}

void log_message(const char* message) {
    printf("%s\n", message);
}

record* allocate_records_contiguous(int num_records, int min_value, int max_value, size_t alignment, const char* pool_name) {
    if (min_value > max_value) {
        fprintf(stderr, "Invalid range: min_value > max_value\n");
        return NULL;
    }

    // Calculate aligned size
    size_t record_size = sizeof(record);
    size_t aligned_record_size = ((record_size + alignment - 1) / alignment) * alignment;

    // Attempt to allocate memory with alignment (using memalign for simplicity)
    void* ptr = NULL;
    int attempts = 3;
    while (attempts-- > 0 && (ptr = memalign(alignment, num_records * aligned_record_size)) == NULL) {
        log_message("Retrying allocation...");
    }

    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate contiguous memory for records\n");
        return NULL;
    }

    record* records = (record*)ptr;

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    log_message("Successfully allocated contiguous memory for records");
    return records;
}

record* allocate_records_individual(int num_records, int min_value, int max_value, const char* pool_name) {
    if (min_value > max_value) {
        fprintf(stderr, "Invalid range: min_value > max_value\n");
        return NULL;
    }

    record** records = safe_malloc(num_records * sizeof(record*), "array of pointers to individual records");

    if (records == NULL) {
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        int attempts = 3;
        while (attempts-- > 0 && (records[i] = safe_malloc(sizeof(record), "individual record")) == NULL) {
            log_message("Retrying allocation for individual record...");
        }

        if (records[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for individual record %d\n", i);

            // Free previously allocated records
            while (--i >= 0) {
                free(records[i]);
            }
            free(records);
            return NULL;
        }

        // Initialize record with random value
        srand(time(NULL) + i);  // Ensure different seeds per iteration
        records[i]->value = min_value + rand() % (max_value - min_value + 1);
    }

    log_message("Successfully allocated individual memory for records");
    return records;
}

void free_records(record* records, int num_records, int contiguous) {
    if (records == NULL) {
        return;
    }

    if (contiguous) {
        free(records);
    } else {
        for (int i = 0; i < num_records; ++i) {
            free(records[i]);
        }
        free(records);
    }

    log_message("Successfully freed memory for records");
}

void allocate_data(int num_offsets, int num_keys, int num_records, int min_value, int max_value, int contiguous, size_t alignment, const char* pool_name) {
    if (num_offsets < 0 || num_keys < 0 || num_records < 0) {
        fprintf(stderr, "Invalid input: negative number of offsets, keys or records\n");
        return;
    }

    long* offsets = safe_malloc(num_offsets * sizeof(long), "array of offsets");
    int* keys = safe_malloc(num_keys * sizeof(int), "array of keys");

    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for offsets or keys\n");
        return;
    }

    record* records = contiguous 
        ? allocate_records_contiguous(num_records, min_value, max_value, alignment, pool_name)
        : allocate_records_individual(num_records, min_value, max_value, pool_name);

    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    // Use the allocated data...

    // Free allocated memory
    free(records);
    free_records(records, num_records, contiguous);
    free(offsets);
    free(keys);

    log_message("Successfully completed operation and freed all resources");
}
```

