// Define the structure for a record
typedef struct {
    int key;
    long offset;
    double timestamp;
} Record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int manage_records(int *keys, long *offsets, Record **records, size_t max_keys, size_t max_offsets) {
    if (keys == NULL || offsets == NULL || records == NULL) {
        log_error("Null pointer provided to the function.");
        return 0;
    }

    // Allocate memory for records
    *records = (Record *)malloc(max_keys * max_offsets * sizeof(Record));
    if (*records == NULL) {
        log_error("Failed to allocate memory for records array.");
        return 0;
    }

    size_t num_records = 0;
    time_t current_time;

    // Populate the records
    for (size_t i = 0; i < max_keys && num_records < max_offsets; ++i) {
        if (keys[i] <= 0 || keys[i] > 100000) continue; // Ensure key is within range

        for (size_t j = 0; j < max_offsets && num_records < max_keys; ++j) {
            if (offsets[j] < 0 || offsets[j] > 1000000) continue; // Ensure offset is within range

            (*records)[num_records].key = keys[i];
            (*records)[num_records].offset = offsets[j];

            current_time = time(NULL);
            while ((current_time - ((int)current_time)) != 0.0) { // Get whole number timestamp
                current_time = time(NULL);
            }
            (*records)[num_records].timestamp = (double)current_time;

            // Modify offset by adding key value
            (*records)[num_records].offset += keys[i];

            num_records++;
        }
    }

    return (int)num_records;
}

void free_resources(Record *records) {
