#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char *name;
    size_t index;
} data_point;

typedef struct {
    double *floats;
    char **strings;
    data_point **data_points;
    size_t count_floats;
    size_t count_strings;
    size_t count_data_points;
} csv_data;

void free_csv_data(csv_data *csv) {
    if (csv->floats) free(csv->floats);
    if (csv->strings) {
        for (size_t i = 0; i < csv->count_strings; ++i)
            free(csv->strings[i]);
        free(csv->strings);
    }
    if (csv->data_points) {
        for (size_t i = 0; i < csv->count_data_points; ++i) {
            free(csv->data_points[i]->name);
            free(csv->data_points[i]);
        }
        free(csv->data_points);
    }
}

int read_csv_file(const char *filename, csv_data *csv) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char line[1024];
    size_t floats_capacity = 10;
    size_t strings_capacity = 10;
    size_t data_points_capacity = 10;

    csv->floats = malloc(floats_capacity * sizeof(double));
    csv->strings = malloc(strings_capacity * sizeof(char *));
    csv->data_points = malloc(data_points_capacity * sizeof(data_point *));

    if (!csv->floats || !csv->strings || !csv->data_points) {
        free_csv_data(csv);
        fclose(file);
        return -1;
    }

    csv->count_floats = 0;
    csv->count_strings = 0;
    csv->count_data_points = 0;

    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        size_t field_count = 0;

        while (token) {
            if (field_count == 0) { // Double
                double value = atof(token);
                if (csv->count_floats >= floats_capacity) {
                    floats_capacity *= 2;
                    csv->floats = realloc(csv->floats, floats_capacity * sizeof(double));
                    if (!csv->floats) break;
                }
                csv->floats[csv->count_floats++] = value;
            } else if (field_count == 1) { // String
                size_t len = strlen(token);
                char *str = malloc((len + 1) * sizeof(char));
                if (!str) break;

                strncpy(str, token, len);
                str[len] = '\0';

                if (csv->count_strings >= strings_capacity) {
                    strings_capacity *= 2;
                    csv->strings = realloc(csv->strings, strings_capacity * sizeof(char *));
                    if (!csv->strings) break;
                }
                csv->strings[csv->count_strings++] = str;
            } else { // Data point
                data_point *dp = malloc(sizeof(data_point));
                if (!dp) break;

                dp->value = atof(token);
                token = strtok(NULL, ",");
                size_t len = strlen(token);
                dp->name = malloc((len + 1) * sizeof(char));
                if (!dp->name) {
                    free(dp);
                    break;
                }
                strncpy(dp->name, token, len);
                dp->name[len] = '\0';

                token = strtok(NULL, ",");
                dp->index = (token) ? strtoull(token, NULL, 10) : 0;

                if (csv->count_data_points >= data_points_capacity) {
                    data_points_capacity *= 2;
                    csv->data_points = realloc(csv->data_points, data_points_capacity * sizeof(data_point *));
                    if (!csv->data_points) break;
                }
                csv->data_points[csv->count_data_points++] = dp;

            }
            token = strtok(NULL, ",");
            field_count++;
        }

        // Break if allocation failed
        if (field_count < 3) {
            free_csv_data(csv);
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    csv_data csv;
    int result = read_csv_file(argv[1], &csv);
    if (result != 0) {
        fprintf(stderr, "Error reading CSV file.\n");
        return EXIT_FAILURE;
    }

    // Example usage of the data
    for (size_t i = 0; i < csv.count_floats; ++i)
        printf("Float: %f\n", csv.floats[i]);

    for (size_t i = 0; i < csv.count_strings; ++i)
        printf("String: %s\n", csv.strings[i]);

    for (size_t i = 0; i < csv.count_data_points; ++i) {
        data_point *dp = csv.data_points[i];
        printf("Data Point - Value: %f, Name: %s, Index: %zu\n", dp->value, dp->name, dp->index);
    }

    free_csv_data(&csv);
    return EXIT_SUCCESS;
}
```

