#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_SIZE 8192

typedef struct {
    int key;
    long offset;
    int processing_status; // Example metadata for tracking processing status
} Record;

// Mutex for thread safety during logging and record allocation
pthread_mutex_t lock;

int allocate_records(int n, int min_key, int max_key, char *temp_buffer) {
    if (min_key > max_key || n <= 0 || !temp_buffer) return -1;

    pthread_mutex_init(&lock, NULL);

    // Calculate the size of one record
    size_t record_size = sizeof(Record);
    int available_records = MAX_MEMORY_SIZE / record_size;

    // Determine how many records we can actually allocate given the memory constraint
    n = (n > available_records) ? available_records : n;

