                unique_found = 1;

                records[i].key = candidate_key;
                records[i].offset = (long)(rand() % 100000); // Example offset
                records[i].processing_status = 0; // Initialize processing status

                success_count++;
            }
        }

        if (success_count == n) break;
    }

    if (success_count < n) {
        pthread_mutex_lock(&lock);
        snprintf(temp_buffer, MAX_MEMORY_SIZE, "First record to fail unique key: index %d, available range [%d, %d]",
                 success_count, min_key, max_key - 1);
        pthread_mutex_unlock(&lock);
    }

    // Clean up
    free(records);
    pthread_mutex_destroy(&lock);

    return success_count;
}

