['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_LIMIT 1024 * 1024 // Define memory limit (e.g., 1MB)
#define CACHE_SIZE 256           // Cache size for frequently accessed records

typedef struct {
    int value;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record record;
    struct Node* next;
} Node;

// Hash table structure for caching
typedef struct {
    Node** buckets;
    unsigned int capacity;
    pthread_mutex_t lock;
} Cache;

Cache cache;

unsigned int hash(int key, unsigned int capacity) {
    return key % capacity;
}

Node* create_node(long offset, int key, Record record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->offset = offset;
    new_node->key = key;
    new_node->record = record;
    new_node->next = NULL;
    return new_node;
}

void init_cache(unsigned int capacity) {
    cache.buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!cache.buckets) {
        perror("Failed to allocate memory for cache buckets");
        exit(EXIT_FAILURE);
    }
    cache.capacity = capacity;
    pthread_mutex_init(&cache.lock, NULL);
}

void free_cache() {
    Node *current, *temp;
    for (unsigned int i = 0; i < cache.capacity; ++i) {
        current = cache.buckets[i];
        while (current != NULL) {
            temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(cache.buckets);
    pthread_mutex_destroy(&cache.lock);
}

void cache_record(int key, Record record) {
    unsigned int index = hash(key, cache.capacity);
    Node* new_node = create_node(0, key, record);

    pthread_mutex_lock(&cache.lock);
    new_node->next = cache.buckets[index];
    cache.buckets[index] = new_node;
    pthread_mutex_unlock(&cache.lock);
}

Record* get_record_from_cache(int key) {
    unsigned int index = hash(key, cache.capacity);

    pthread_mutex_lock(&cache.lock);
    Node* current = cache.buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&cache.lock);
            return &current->record;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache.lock);

    return NULL; // Record not found in cache
}

void* allocate_memory_and_initialize(void* args) {
    long memory_allocated = 0;
    int max_values, range_min, range_max;

    // Example parameters (can be adjusted as needed)
    max_values = 10000; // Max number of records
    range_min = 1;
    range_max = 100;

    srand(time(NULL));

    long* offsets = (long*)malloc(max_values * sizeof(long));
    int* keys = (int*)malloc(max_values * sizeof(int));
    Record* records = (Record*)malloc(max_values * sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < max_values && memory_allocated + sizeof(long) + sizeof(int) + sizeof(Record) <= MEMORY_LIMIT; ++i) {
        offsets[i] = i * 10; // Example offset logic
        keys[i] = rand() % 100;
        records[i].value = range_min + rand() % (range_max - range_min + 1);

        cache_record(keys[i], records[i]);

        memory_allocated += sizeof(long) + sizeof(int) + sizeof(Record);
    }

    printf("Memory allocated: %ld bytes\n", memory_allocated);

    // Free allocated memory after usage
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    init_cache(CACHE_SIZE);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, allocate_memory_and_initialize, NULL) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    free_cache();

    return 0;
}
```

This code snippet implements a memory management strategy with dynamic allocation and caching. It utilizes mutexes for thread safety when accessing the cache. The `cache_record` function adds records to the cache, while `get_record_from_cache` retrieves them based on keys. Memory is allocated dynamically for offsets, keys, and records arrays within a specified limit, ensuring efficient use of resources. This setup allows for scalability and integration with larger systems.']

