// Structure to hold aggregated data
typedef struct {
    double sum;
    size_t count;
} AggregateData;

// Callback type for custom line processing
typedef void (*LineProcessCallback)(const char* line, AggregateData* agg);

// Function prototype
void processFilesAndAggregateData(int argc, char *argv[], LineProcessCallback callback);

// Helper function to check if a file is readable
int isReadableFile(const char *filePath) {
    struct stat st;
    return (stat(filePath, &st) == 0 && S_ISREG(st.st_mode) && (st.st_mode & S_IRUSR));
}

// Function to process files and aggregate data
void processFilesAndAggregateData(int argc, char *argv[], LineProcessCallback callback) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [file2 ...]\n", argv[0]);
        return;
    }

    AggregateData *data = malloc(sizeof(AggregateData));
    if (!data) {
        perror("Failed to allocate memory for aggregate data");
        exit(EXIT_FAILURE);
    }
    data->sum = 0.0;
    data->count = 0;

    regex_t regex;
    const char *pattern = "\\b-?\\d+\\.?\\d*\\b";
    if (regcomp(&regex, pattern, REG_EXTENDED) != 0) {
        fprintf(stderr, "Failed to compile regex\n");
        free(data);
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i < argc; ++i) {
        if (!isReadableFile(argv[i])) {
            fprintf(stderr, "Warning: File '%s' is not readable or does not exist.\n", argv[i]);
            continue;
        }

        FILE *file = fopen(argv[i], "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        char buffer[4096];
        while (fgets(buffer, sizeof(buffer), file)) {
            callback(buffer, data);
            regmatch_t match;
            if (regexec(&regex, buffer, 1, &match, 0) == 0) {
                double value = atof(buffer + match.rm_so);
                data->sum += value;
                data->count++;
            }
        }

        fclose(file);
    }

    regfree(&regex);

    // Generate summary report
    if (data->count > 0) {
        double average = data->sum / data->count;
        printf("Total count: %zu\n", data->count);
        printf("Sum: %.2f\n", data->sum);
        printf("Average: %.2f\n", average);
    } else {
        printf("No numerical data found.\n");
    }

    free(data);
}

// Example line processing callback function
void exampleLineProcessCallback(const char* line, AggregateData* agg) {
    // Custom processing logic can be added here
    // For now, we simply pass the line to regex for number extraction
}

int main(int argc, char *argv[]) {
    processFilesAndAggregateData(argc, argv, exampleLineProcessCallback);
    return 0;
}
