    double current_value;
    char unique_id[50];
    int version_number;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

typedef struct {
    RecordArray record_array;
    pthread_rwlock_t cache_lock;
    Record *cache[CACHE_SIZE];
    size_t cache_count;
} DataProcessor;

Record *initialize_record(int id, const char *data_type, double default_value, const char *unique_id) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->id = id;
    time(&record->timestamp);
    strcpy(record->data_type, data_type);
    record->default_value = default_value;
    record->current_value = default_value;
    strncpy(record->unique_id, unique_id, sizeof(record->unique_id) - 1);
    record->version_number = 0;

    return record;
}

void resize_record_array(RecordArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    array->records = realloc(array->records, new_capacity * sizeof(Record));
    if (!array->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->lock);
}

void add_record(DataProcessor *processor, Record *record) {
    pthread_mutex_lock(&processor->record_array.lock);
    if (processor->record_array.count == processor->record_array.capacity) {
        resize_record_array(&processor->record_array, processor->record_array.capacity * 2);
    }
    processor->record_array.records[processor->record_array.count++] = *record;
    pthread_mutex_unlock(&processor->record_array.lock);
}

void parse_json_file(const char *filename, DataProcessor *processor) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    struct json_object *parsed_json;
    struct json_object *json_records;
    size_t n_records, i;

    parsed_json = json_object_from_file(filename);
    json_object_object_get_ex(parsed_json, "records", &json_records);

    n_records = json_object_array_length(json_records);
    for (i = 0; i < n_records; i++) {
        struct json_object *record_obj;
        record_obj = json_object_array_get_idx(json_records, i);

        int id;
        double default_value;
        char unique_id[50];

        json_object_object_get_ex(record_obj, "id", &json_id);
        json_object_get_int(json_id, &id);

        json_object_object_get_ex(record_obj, "default_value", &json_default_value);
        json_object_get_double(json_default_value, &default_value);

        json_object_object_get_ex(record_obj, "unique_id", &json_unique_id);
        strncpy(unique_id, json_string_value(json_unique_id), sizeof(unique_id));

        Record *record = initialize_record(id, "double", default_value, unique_id);
        if (record) add_record(processor, record);
    }

    fclose(file);
}

void process_data(DataProcessor *processor) {
    // Placeholder for data processing logic
}

void cleanup(DataProcessor *processor) {
    pthread_mutex_lock(&processor->record_array.lock);
    free(processor->record_array.records);
    pthread_mutex_unlock(&processor->record_array.lock);

    pthread_rwlock_destroy(&processor->cache_lock);
    pthread_mutex_destroy(&processor->record_array.lock);
}

int main(int argc, char **argv) {
