#define GROWTH_FACTOR 2
#define SENTINEL -1

typedef struct {
    int value;
    char key[256];
    long* offset_ptr;
} Record;

void secure_random(int* min, int* max, int* result);
int callback(Record* record);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long* allocate_long_array(size_t initial_size) {
    return (long*)malloc(initial_size * sizeof(long));
}

int* dynamic_int_array(size_t* size, size_t growth_factor) {
    *size = INITIAL_SIZE;
    int* array = malloc(*size * sizeof(int));
    return array;
}

Record* initialize_records(size_t size) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    for (size_t i = 0; i < size; ++i) {
        secure_random((int[]){1, 100}, &records[i].value);
        snprintf(records[i].key, sizeof(records[i].key), "Key%d", i);
        records[i].offset_ptr = malloc(sizeof(long));
    }
    return records;
}

void resize_int_array(int** array, size_t* current_size, size_t growth_factor) {
    pthread_mutex_lock(&lock);
    *current_size *= growth_factor;
    int* new_array = realloc(*array, (*current_size) * sizeof(int));
    if (new_array == NULL) {
        perror("Failed to resize integer array");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    pthread_mutex_unlock(&lock);
}

int read_integers(int** keys, size_t* current_size, size_t growth_factor) {
    int value;
    while (scanf("%d", &value) == 1 && value != SENTINEL) {
        if ((*current_size) >= *size) {
            resize_int_array(keys, current_size, growth_factor);
        }
        (*keys)[(*current_size)++] = value;
    }
    return *current_size;
}

int find_max(int* keys, size_t count) {
    int max_value = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
        if (keys[i] > max_value) {
            max_value = keys[i];
        }
    }
    return max_value;
}

void free_resources(long* long_array, size_t long_size,
                    int* int_array, Record* records, size_t record_size) {
    free(long_array);
    for (size_t i = 0; i < record_size; ++i) {
        free(records[i].offset_ptr);
    }
    free(records);
    free(int_array);
}

void processRecordsAndFindMax(size_t initial_long_size, 
                              size_t growth_factor, 
                              size_t records_size,
                              void (*callback_func)(Record*)) {

    long* long_array = allocate_long_array(initial_long_size);

    size_t int_array_size;
    int* keys = dynamic_int_array(&int_array_size, growth_factor);

    Record* records = initialize_records(records_size);
    for (size_t i = 0; i < records_size; ++i) {
        if (callback_func != NULL) {
            callback_func(&records[i]);
        }
    }

    size_t keys_count = read_integers(&keys, &int_array_size, growth_factor);

    int max_value = find_max(keys, keys_count);
    printf("Maximum integer value: %d\n", max_value);

    free_resources(long_array, initial_long_size,
                   keys, records, records_size);
}

// Example secure random function
void secure_random(int* range, int* result) {
    // Use a more secure method if available; here's a placeholder.
    *result = rand() % (range[1] - range[0]) + range[0];
}

int main() {
    processRecordsAndFindMax(INITIAL_SIZE, GROWTH_FACTOR, INITIAL_SIZE, callback);
    return 0;
}
