typedef struct {
    time_t timestamp;
    uint64_t log_id;
    double latency;
} logEntry;

// Function pointer type for callback processing each log entry
typedef void (*log_entry_callback)(const logEntry*);

pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t resize_condition = PTHREAD_COND_INITIALIZER;

logEntry* initialize_log_array(size_t initial_size) {
    logEntry* array = (logEntry*)malloc(initial_size * sizeof(logEntry));
    if (!array) {
        perror("Failed to allocate memory for log entries");
        exit(EXIT_FAILURE);
    }
    return array;
}

void resize_log_array(logEntry** array, size_t* current_capacity, size_t new_capacity) {
    pthread_mutex_lock(&array_mutex);

    *array = (logEntry*)realloc(*array, new_capacity * sizeof(logEntry));
    if (!*array) {
        perror("Failed to reallocate memory for log entries");
        exit(EXIT_FAILURE);
    }

    *current_capacity = new_capacity;
    pthread_cond_signal(&resize_condition); // Notify any waiting threads that resize is done
    pthread_mutex_unlock(&array_mutex);
}

void free_log_array(logEntry* array) {
    free(array);
}

void process_logs_and_aggregate_metrics(size_t initial_size, log_entry_callback callback) {
    size_t current_capacity = initial_size;
    size_t entry_count = 0;
    logEntry* logs = initialize_log_array(current_capacity);

    while (1) { // Loop to read entries until EOF or error
        pthread_mutex_lock(&array_mutex);

        if (entry_count >= current_capacity) {
            resize_log_array(&logs, &current_capacity, current_capacity * 2); // Double the capacity
        }

        logEntry* entry = &logs[entry_count];

        if (scanf("%ld %lu %lf", &(entry->timestamp), &(entry->log_id), &(entry->latency)) != 3) {
            break; // Exit loop on read error or EOF
        }

        if (callback) {
            logEntry entry_copy = *entry;
            callback(&entry_copy);
        }

        ++entry_count;
        pthread_mutex_unlock(&array_mutex);
    }

    free_log_array(logs); // Free the allocated memory for logs
}

// Example of a simple callback function
