['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef enum { STRING_TYPE, INTEGER_TYPE, BOOLEAN_TYPE } ValueType;

typedef struct {
    char name[50];
    ValueType value_type;
    union {
        char *string_value;
        int integer_value;
        _Bool boolean_value;
    };
    union {
        char *default_string_value;
        int default_integer_value;
        _Bool default_boolean_value;
    };
    char dns_address[100]; // Optional
} Preference;

typedef struct {
    int value;
    int min, max;  // Range for the integer value
} Record;

typedef struct {
    Preference *preferences;
    Record *records;
    size_t preference_count;
    size_t record_count;
    size_t capacity;
    pthread_mutex_t lock;
    void (*callback)(Preference *, Record *);
} SystemState;

void initializeSystem(SystemState *state, void (*cb)(Preference *, Record *)) {
    state->preference_count = 0;
    state->record_count = 0;
    state->capacity = INITIAL_SIZE;

    state->preferences = malloc(state->capacity * sizeof(Preference));
    state->records = malloc(state->capacity * sizeof(Record));

    if (state->preferences == NULL || state->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memset(state->preferences, 0, state->capacity * sizeof(Preference));
    memset(state->records, 0, state->capacity * sizeof(Record));

    pthread_mutex_init(&state->lock, NULL);

    if (cb != NULL) {
        for (size_t i = 0; i < state->capacity; ++i) {
            cb(&state->preferences[i], &state->records[i]);
        }
    }
}

void resizeIfNeeded(SystemState *state) {
    pthread_mutex_lock(&state->lock);

    if ((state->preference_count == state->capacity) || 
        (state->record_count == state->capacity)) {

        size_t new_capacity = state->capacity * 2;

        Preference *new_preferences = realloc(state->preferences, new_capacity * sizeof(Preference));
        Record *new_records = realloc(state->records, new_capacity * sizeof(Record));

        if (new_preferences != NULL && new_records != NULL) {
            state->preferences = new_preferences;
            state->records = new_records;

            memset(&state->preferences[state->preference_count], 0,
                   (new_capacity - state->preference_count) * sizeof(Preference));
            memset(&state->records[state->record_count], 0, 
                   (new_capacity - state->record_count) * sizeof(Record));

            state->capacity = new_capacity;
        } else {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&state->lock);
}

void addPreference(SystemState *state, Preference pref) {
    resizeIfNeeded(state);

    pthread_mutex_lock(&state->lock);

    if (strlen(pref.name) >= sizeof(pref.name)) {
        fprintf(stderr, "Preference name too long\n");
        pthread_mutex_unlock(&state->lock);
        return;
    }

    strncpy(state->preferences[state->preference_count].name, pref.name, sizeof(pref.name));
    state->preferences[state->preference_count].value_type = pref.value_type;

    switch (pref.value_type) {
        case STRING_TYPE:
            if (pref.string_value != NULL)
                state->preferences[state->preference_count].string_value =
                    strdup(pref.string_value);
            else
                state->preferences[state->preference_count].default_string_value =
                    strdup(pref.default_string_value);
            break;

        case INTEGER_TYPE:
            state->preferences[state->preference_count].integer_value = pref.integer_value;
            break;

        case BOOLEAN_TYPE:
            state->preferences[state->preference_count].boolean_value = pref.boolean_value;
            break;
    }

    strncpy(state->preferences[state->preference_count].dns_address, pref.dns_address,
            sizeof(pref.dns_address));

    ++state->preference_count;

    if (state->callback != NULL) {
        state->callback(&state->preferences[state->preference_count - 1], NULL);
    }

    pthread_mutex_unlock(&state->lock);
}

void addRecord(SystemState *state, Record rec) {
    resizeIfNeeded(state);

    pthread_mutex_lock(&state->lock);

    if (rec.value < rec.min || rec.value > rec.max) {
        fprintf(stderr, "Record value out of range\n");
        pthread_mutex_unlock(&state->lock);
        return;
    }

    state->records[state->record_count] = rec;

    ++state->record_count;

    if (state->callback != NULL) {
        state->callback(NULL, &state->records[state->record_count - 1]);
    }

    pthread_mutex_unlock(&state->lock);
}

void cleanupSystem(SystemState *state) {
    for (size_t i = 0; i < state->preference_count; ++i) {
        if (state->preferences[i].value_type == STRING_TYPE &&
            state->preferences[i].string_value != NULL) {
            free(state->preferences[i].string_value);
        }
    }

    free(state->preferences);
    free(state->records);

    pthread_mutex_destroy(&state->lock);
}

void managePreferencesAndDataProcessing(void (*cb)(Preference *, Record *)) {
    SystemState state;
    initializeSystem(&state, cb);

    // Example usage
    Preference pref = { "theme", STRING_TYPE, NULL, "light", "", "" };
    addPreference(&state, pref);

    Record rec = { 42, 0, 100 };
    addRecord(&state, rec);

    cleanupSystem(&state);
}
