#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>

typedef enum { STRING_TYPE, INTEGER_TYPE, BOOLEAN_TYPE } ValueType;

typedef struct {
    char *name;
    ValueType type;
    void *defaultValue;
    void *currentValue;
    char *dnsAddress;
} Preference;

#define INITIAL_SIZE 10

typedef struct {
    Preference *preferences;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PreferencesManager;

PreferencesManager* initPreferencesManager(size_t minSize, size_t maxSize) {
    if (minSize > maxSize || minSize == 0) return NULL;

    PreferencesManager *manager = malloc(sizeof(PreferencesManager));
    if (!manager) return NULL;

    manager->preferences = calloc(maxSize, sizeof(Preference));
    if (!manager->preferences) {
        free(manager);
        return NULL;
    }

    manager->capacity = maxSize;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resizePreferencesArray(PreferencesManager *manager, size_t newSize) {
    if (newSize > manager->capacity) {
        Preference *temp = realloc(manager->preferences, newSize * sizeof(Preference));
        if (!temp) return; // Handle memory allocation failure
        manager->preferences = temp;
        manager->capacity = newSize;
    }
}

void addPreference(PreferencesManager *manager, const char *name, ValueType type, void *defaultValue, void *currentValue, const char *dnsAddress) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resizePreferencesArray(manager, manager->capacity * 2);
    }

    Preference *pref = &manager->preferences[manager->count++];
    pref->name = strdup(name);
    pref->type = type;
    pref->defaultValue = malloc(sizeof(*(defaultValue))); // Assuming simple types for now
    memcpy(pref->defaultValue, defaultValue, sizeof(*defaultValue));
    pref->currentValue = currentValue ? malloc(sizeof(*(currentValue))) : NULL;
    if (pref->currentValue) {
        memcpy(pref->currentValue, currentValue, sizeof(*(currentValue)));
    }
    pref->dnsAddress = dnsAddress ? strdup(dnsAddress) : NULL;

    pthread_mutex_unlock(&manager->lock);
}

void *resolveHostname(const char *hostname) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return NULL;
    }

    char ipstr[INET6_ADDRSTRLEN];
    void *ip;

    for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            ip = &(ipv4->sin_addr);
            inet_ntop(AF_INET, ip, ipstr, sizeof(ipstr));
        } else if (p->ai_family == AF_INET6) { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            ip = &(ipv6->sin6_addr);
            inet_ntop(AF_INET6, ip, ipstr, sizeof(ipstr));
        }
    }

    freeaddrinfo(res);

    char *resolvedAddress = strdup(ipstr);
    if (!resolvedAddress) {
        return NULL;
    }

    return resolvedAddress;
}

void freePreferencesManager(PreferencesManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->preferences[i].name);
        free(manager->preferences[i].defaultValue);
        free(manager->preferences[i].currentValue);
        free(manager->preferences[i].dnsAddress);
    }

    free(manager->preferences);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    PreferencesManager *manager = initPreferencesManager(10, 100);

    if (!manager) {
        fprintf(stderr, "Failed to initialize preferences manager.\n");
        return EXIT_FAILURE;
    }

    // Example preference addition
    int defaultValueInt = 42;
    int currentValueInt = 24;
    addPreference(manager, "theme", INTEGER_TYPE, &defaultValueInt, &currentValueInt, NULL);

    char *resolvedAddress = resolveHostname("example.com");
    if (resolvedAddress) {
        printf("Resolved Address: %s\n", resolvedAddress);
        free(resolvedAddress);
    } else {
        fprintf(stderr, "Failed to resolve hostname.\n");
    }

    freePreferencesManager(manager);
    return EXIT_SUCCESS;
}
