use std::env;
use std::fs::{self, DirBuilder};
use std::io::{self, BufRead, stdin};
use std::sync::{Arc, Mutex};
use tokio::task;
use reqwest::Client;

struct Record {
    key: String,
    value: i32,
    data_ptr: *mut i64,
}

async fn fetch_data_from_source(client: &Client, source_url: &str) -> Result<Vec<i32>, Box<dyn std::error::Error>> {
    let response = client.get(source_url).send().await?;
    let body = response.text().await?;
    // Simulate parsing the response into i32 values
    Ok(body.chars().filter_map(|c| c.to_digit(10)).map(|d| d as i32).collect())
}

fn create_directory(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    DirBuilder::new().create(dir_name)?;
    println!("Created directory: {}", dir_name);
    Ok(())
}

async fn processAndAggregateData() -> Result<i32, Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    let source_url = args.get(1).unwrap_or(&String::from("http://example.com/api/data")).as_str();

    let client = Client::new();

    // Fetch data asynchronously
    let data_future = fetch_data_from_source(&client, source_url);

    let records: Vec<Record> = Arc::new(Mutex::new(vec![])).clone();
    let processed_records = task::spawn(async move {
        match data_future.await {
            Ok(data) => {
                for (i, &value) in data.iter().enumerate() {
                    // Validation can be done here
                    if value >= 0 { // Example validation condition
                        let key = format!("record_{}", i);
                        let mut record_data = Box::new(42); // Arbitrary initial long value
                        let ptr = Box::into_raw(record_data);

                        Arc::get_mut(&mut records).unwrap().lock().unwrap().push(Record {
                            key,
                            value,
                            data_ptr: *ptr,
                        });
                    }
                }
            },
            Err(e) => eprintln!("Error fetching data: {}", e),
        }
    });

    let _ = processed_records.await;

    // Read integers from stdin
    let mut max_value = i32::MIN;
    let stdin_lock = stdin();

    for line in stdin_lock.lock().lines() {
        if let Ok(num_str) = line {
            if let Ok(value) = num_str.parse::<i32>() {
                max_value = std::cmp::max(max_value, value);
            }
        }
    }

    println!("Maximum integer from input: {}", max_value);

    // Memory cleanup
    for record in Arc::try_unwrap(records).ok()?.into_inner().unwrap() {
        unsafe {
            if !record.data_ptr.is_null() {
                Box::from_raw(record.data_ptr); // Reclaim memory safely
            }
        }
    }

    let env_var = env::var("NEW_DIR_NAME").map_err(|_| "Environment variable NEW_DIR_NAME not set")?;
    create_directory(&env_var)?;

    Ok(max_value)
}

#[tokio::main]
async fn main() {
    if let Err(e) = processAndAggregateData().await {
        eprintln!("An error occurred: {}", e);
    }
}
