    if (value != NULL) {
        sscanf(line, "%lf", value);
    }
}

int openFileWithRetries(const char *path) {
    int fd = -1;
    for (int i = 0; i < MAX_RETRIES; ++i) {
        fd = open(path, O_RDONLY);
        if (fd != -1) return fd;
        // Implement exponential backoff or sleep
        usleep(100000); // Sleep for 100ms before retrying
    }
    return fd;
}

AggregateData* createAggregateData(size_t initialCapacity) {
    AggregateData *agg = malloc(sizeof(AggregateData));
    agg->data = calloc(initialCapacity, sizeof(int));
    agg->capacity = initialCapacity;
    agg->count = 0;
    return agg;
}

void resizeAggregateData(AggregateData *agg) {
    size_t newCapacity = agg->capacity * 2;
    int *newData = realloc(agg->data, newCapacity * sizeof(int));
    if (newData) {
        agg->data = newData;
        agg->capacity = newCapacity;
    }
}

void addData(AggregateData *agg, int value) {
    if (agg->count == agg->capacity) resizeAggregateData(agg);
    agg->data[agg->count++] = value;
}

double calculateMean(const AggregateData *agg) {
    double sum = 0.0;
    for (size_t i = 0; i < agg->count; ++i) {
        sum += agg->data[i];
    }
    return agg->count > 0 ? sum / agg->count : 0.0;
}

double calculateVariance(const AggregateData *agg, double mean) {
    double variance = 0.0;
    for (size_t i = 0; i < agg->count; ++i) {
        variance += pow(agg->data[i] - mean, 2);
    }
    return agg->count > 1 ? variance / (agg->count - 1) : 0.0;
}

void processFilesAndAggregateData(int argc, char *argv[], ProcessLineCallback lineProcessor) {
    AggregateData *aggregate = createAggregateData(10);

    for (int i = 1; i < argc; ++i) {
        int fd = openFileWithRetries(argv[i]);
        if (fd == -1) {
            fprintf(stderr, "Error: Unable to access file %s\n", argv[i]);
            continue;
        }

        char buffer[1024];
        double value;

        while (read(fd, buffer, sizeof(buffer)) > 0) {
            const char *line = strtok(buffer, "\n");
            while (line != NULL) {
                lineProcessor(line, &value);
                if (isfinite(value)) {
                    addData(aggregate, (int)value);
                }
                line = strtok(NULL, "\n");
            }
        }

        close(fd);
    }

    double mean = calculateMean(aggregate);
    double variance = calculateVariance(aggregate, mean);

    printf("Summary Report:\n");
    printf("Count: %zu\n", aggregate->count);
    printf("Sum: %.2f\n", mean * aggregate->count);
    printf("Mean: %.2f\n", mean);
    printf("Variance: %.2f\n", variance);

    free(aggregate->data);
    free(aggregate);
}
