        pool->size += size;
    }
    pthread_mutex_unlock(&mutex);
    return block;
}

void free_mem_pool(MemPool* pool) {
    if (!pool) return;
    free(pool->data);
    free(pool);
}

void managePreferencesAndRecords(int max_records, int total_record_size, PostInitCallback post_init_cb, unsigned int seed) {
