        if (strncmp(input, "quit", 4) == 0) {
            pthread_mutex_unlock(&mutex);
            break;
        }

        size_t newsize = bufsize + strlen(input) + 1;
        buffer = realloc(buffer, newsize);
        if (!buffer) continue; // Handle realloc failure gracefully

        memcpy(&buffer[bufsize], input, strlen(input) + 1);
        bufsize = newsize;
        pthread_mutex_unlock(&mutex);

        log_message("Read and stored input");
    }

    // Call post-initialization callback
    if (post_init_cb) {
        post_init_cb(prefs, records);
    }

    free(buffer);
