    CacheManager cache_manager;

    initializeResourceManager(&resource_manager);
    pthread_rwlock_init(&cache_manager.rwlock, NULL);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, logProcessingThread, argv[1])) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Wait for the thread to finish processing
    pthread_join(thread_id, NULL);

    // Clean up resources
    pthread_mutex_destroy(&resource_manager.lock);
    pthread_rwlock_destroy(&cache_manager.rwlock);

    printf("Log processing completed.\n");

    return EXIT_SUCCESS;
}
