        return NULL;
    }

    const char *offsets_size_str = json_string_value(json_object_get(root, "offsets_size"));
    const char *keys_size_str = json_string_value(json_object_get(root, "keys_size"));

    if (!offsets_size_str || !keys_size_str) {
        fprintf(stderr, "Invalid configuration: missing required fields.\n");
        json_decref(root);
        return NULL;
    }

    size_t offsets_size = strtoul(offsets_size_str, NULL, 10);
    size_t keys_size = strtoul(keys_size_str, NULL, 10);

    if (offsets_size == 0 || keys_size == 0) {
        fprintf(stderr, "Invalid configuration: array sizes must be positive.\n");
        json_decref(root);
        return NULL;
    }

    long *file_offsets = allocate_offsets_array(offsets_size);
    int *keys = allocate_keys_array(keys_size);

    if (!file_offsets || !keys) {
        free(file_offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed.\n");
        json_decref(root);
        return NULL;
    }

    record *records = allocate_records_array(keys_size, keys);
    if (!records) {
        free(file_offsets);
        free(keys);
        json_decref(root);
        return NULL;
    }

    json_decref(root);
    return records;  // Caller must handle cleanup of allocated memory
}

long* allocate_offsets_array(size_t size) {
    long *array = (long *)malloc(size * sizeof(long));
    if (!array) return NULL;

    for (size_t i = 0; i < size; ++i) {
        array[i] = rand() % (1 << 30); // Example initialization
    }

    return array;
}

int* allocate_keys_array(size_t size) {
    int *array = (int *)malloc(size * sizeof(int));
    if (!array) return NULL;

    for (size_t i = 0; i < size; ++i) {
        int key;
        do {
            key = rand() % (1 << 16); // Example range
        } while ((i > 0 && find_in_array(array, key, i)) != -1);
        array[i] = key;
    }

    return array;
}

record* allocate_records_array(size_t size, const int *keys) {
    record *array = (record *)malloc(size * sizeof(record));
    if (!array) return NULL;

    for (size_t i = 0; i < size; ++i) {
        array[i].id = keys[i];
        array[i].file_offset = rand() % (1 << 30); // Example initialization
        array[i].status = 'A';  // Example status
    }

    return array;
}

int find_in_array(const int *array, int value, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (array[i] == value) {
            return i;
        }
    }
    return -1;
}
