#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for item
typedef struct Item {
    char *name;
    int quantity;
    struct Item *parent;
} Item;

// Function pointer type for callback
typedef void (*ItemCallback)(Item *);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Memory pool (example allocation of 1024 bytes, aligned to cache line)
#define POOL_SIZE 1024
char memoryPool[POOL_SIZE];
size_t poolOffset = 0;

// Utility function for allocating from the memory pool
void* poolAlloc(size_t size) {
    if (poolOffset + size > POOL_SIZE) return NULL;
    void *ptr = &memoryPool[poolOffset];
    poolOffset += size;
    return ptr;
}

// Initialize item structure and link to parent probabilistically
Item* initItem(const char* name, int quantity, Item** items, int numItems, float parentProbability, ItemCallback callback) {
    Item *item = (Item*)poolAlloc(sizeof(Item));
    if (!item) return NULL;

    item->name = strdup(name);
    item->quantity = quantity;
    item->parent = NULL;

    // Determine parent based on probability
    for (int i = 0; i < numItems; ++i) {
        if ((float)rand() / RAND_MAX < parentProbability) {
            item->parent = items[i];
            break;
        }
    }

    // Invoke callback function safely
    if (callback) {
        pthread_mutex_lock(&mutex);
        callback(item);
        pthread_mutex_unlock(&mutex);
    }

    return item;
}

// Cleanup memory allocated from pool and other resources
void cleanupItems(Item **items, int numItems) {
    for (int i = 0; i < numItems; ++i) {
        free(items[i]->name);
        items[i] = NULL;
    }
    pthread_mutex_destroy(&mutex);
}

// Process integers to find the largest integer from standard input
void processIntegers() {
    int num, maxNum = INT_MIN;

    while (scanf("%d", &num) == 1) {
        if (num > maxNum) {
            maxNum = num;
        }
    }

    printf("Largest Integer: %d\n", maxNum);
}

void manageDynamicItemListAndProcessIntegers() {
    // Example strings and quantities
    const char *names[] = {"ItemA", "ItemB", "ItemC"};
    int quantities[] = {10, 20, 30};
    size_t numItems = sizeof(names) / sizeof(char*);

    Item **items = (Item**)malloc(numItems * sizeof(Item*));
    if (!items) return;

    // Initialize items
    for (size_t i = 0; i < numItems; ++i) {
        float parentProbability = 0.5f; // Example probability
        items[i] = initItem(names[i], quantities[i], items, i, parentProbability, NULL);
    }

    // Process integers from standard input
    processIntegers();

    // Cleanup
    cleanupItems(items, numItems);
    free(items);
}

int main() {
    manageDynamicItemListAndProcessIntegers();
    return 0;
}
