#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PARAMS 1000

typedef struct {
    char *key;
    char *value;
} ConfigParam;

typedef struct {
    ConfigParam params[MAX_PARAMS];
    size_t count;
    pthread_rwlock_t lock;
} ConfigManager;

void init_config_manager(ConfigManager *manager) {
    manager->count = 0;
    pthread_rwlock_init(&manager->lock, NULL);
}

int add_config_param(ConfigManager *manager, const char *key, const char *value) {
    pthread_rwlock_wrlock(&manager->lock);

    if (manager->count >= MAX_PARAMS) {
        fprintf(stderr, "Maximum number of configuration parameters reached.\n");
        pthread_rwlock_unlock(&manager->lock);
        return -1;
    }

    manager->params[manager->count].key = strdup(key);
    manager->params[manager->count].value = strdup(value);

    if (!manager->params[manager->count].key || !manager->params[manager->count].value) {
        fprintf(stderr, "Failed to allocate memory for configuration parameter.\n");
        free(manager->params[manager->count].key);
        free(manager->params[manager->count].value);
        pthread_rwlock_unlock(&manager->lock);
        return -1;
    }

    manager->count++;
    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

char *get_config_param(const ConfigManager *manager, const char *key) {
    pthread_rwlock_rdlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->params[i].key, key) == 0) {
            pthread_rwlock_unlock(&manager->lock);
            return manager->params[i].value;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return NULL;
}

void update_config_param(ConfigManager *manager, const char *key, const char *new_value) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->params[i].key, key) == 0) {
            free(manager->params[i].value);
            manager->params[i].value = strdup(new_value);
            pthread_rwlock_unlock(&manager->lock);
            return;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
}

void cleanup_config_manager(ConfigManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->params[i].key);
        free(manager->params[i].value);
    }

    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_performance_metrics(size_t count) {
    printf("Performance Metrics: Total configuration parameters = %zu\n", count);
}

int main() {
    ConfigManager manager;
    init_config_manager(&manager);

    add_config_param(&manager, "server_address", "192.168.1.1");
    add_config_param(&manager, "log_level", "DEBUG");

    char *value = get_config_param(&manager, "log_level");
    if (value) {
        printf("Log Level: %s\n", value);
    }

    update_config_param(&manager, "log_level", "INFO");
    value = get_config_param(&manager, "log_level");
    if (value) {
        printf("Updated Log Level: %s\n", value);
    }

    log_performance_metrics(manager.count);

    cleanup_config_manager(&manager);
    return 0;
}
```

