#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// External library for secure random string generation
extern char* generate_secure_random_string(size_t length, unsigned int seed);

typedef struct {
    time_t timestamp;
    char* data_payload;
    unsigned int metadata_flags;
} Event;

typedef struct {
    size_t capacity;
    size_t count;
    Event** events;
} DataStream;

typedef void (*EventCallback)(Event*);

typedef struct {
    size_t stream_capacity;
    size_t stream_count;
    pthread_mutex_t mutex;
    DataStream** streams;
    unsigned int seed;
    EventCallback callback;
} StreamManager;

void initialize_stream_manager(StreamManager* manager, unsigned int initial_capacity, unsigned int seed, EventCallback cb) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->stream_capacity = initial_capacity;
    manager->stream_count = 0;
    manager->streams = malloc(sizeof(DataStream*) * initial_capacity);
    if (!manager->streams) {
        fprintf(stderr, "Failed to allocate memory for streams\n");
        exit(EXIT_FAILURE);
    }
    memset(manager->streams, 0, sizeof(DataStream*) * initial_capacity);
    manager->seed = seed;
    manager->callback = cb;
}

void resize_stream_array(StreamManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    size_t new_capacity = manager->stream_capacity * 2;
    DataStream** new_streams = realloc(manager->streams, sizeof(DataStream*) * new_capacity);
    if (!new_streams) {
        fprintf(stderr, "Failed to reallocate memory for streams\n");
        exit(EXIT_FAILURE);
    }
    memset(new_streams + manager->stream_capacity, 0, sizeof(DataStream*) * (new_capacity - manager->stream_capacity));
    manager->streams = new_streams;
    manager->stream_capacity = new_capacity;
    pthread_mutex_unlock(&manager->mutex);
}

void add_data_stream(StreamManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->stream_count == manager->stream_capacity) {
        resize_stream_array(manager);
    }
    DataStream* stream = malloc(sizeof(DataStream));
    if (!stream) {
        fprintf(stderr, "Failed to allocate memory for data stream\n");
        exit(EXIT_FAILURE);
    }
    stream->capacity = 10;
    stream->count = 0;
    stream->events = malloc(sizeof(Event*) * stream->capacity);
    if (!stream->events) {
        free(stream);
        fprintf(stderr, "Failed to allocate memory for events\n");
        exit(EXIT_FAILURE);
    }
    manager->streams[manager->stream_count++] = stream;
    pthread_mutex_unlock(&manager->mutex);
}

void add_event_to_stream(StreamManager* manager, size_t stream_index, const char* payload) {
    pthread_mutex_lock(&manager->mutex);
    if (stream_index >= manager->stream_count) {
        fprintf(stderr, "Invalid stream index\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    DataStream* stream = manager->streams[stream_index];
    if (stream->count == stream->capacity) {
        size_t new_capacity = stream->capacity * 2;
        Event** new_events = realloc(stream->events, sizeof(Event*) * new_capacity);
        if (!new_events) {
            fprintf(stderr, "Failed to reallocate memory for events\n");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        stream->events = new_events;
        stream->capacity = new_capacity;
    }

    Event* event = malloc(sizeof(Event));
    if (!event) {
        fprintf(stderr, "Failed to allocate memory for event\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    event->timestamp = time(NULL);
    event->data_payload = strdup(payload);
    event->metadata_flags = 0; // Set appropriate flags

    if (manager->callback) {
        manager->callback(*event);
    }

    stream->events[stream->count++] = event;
    pthread_mutex_unlock(&manager->mutex);
}

void flush_streams_to_storage(StreamManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->stream_count; ++i) {
        DataStream* stream = manager->streams[i];
        for (size_t j = 0; j < stream->count; ++j) {
            Event* event = stream->events[j];
            // Simulate storing the event
            printf("Flushing: %s at %ld\n", event->data_payload, event->timestamp);
            free(event->data_payload);
            free(event);
        }
        free(stream->events);
    }
    pthread_mutex_unlock(&manager->mutex);
}

void free_stream_manager(StreamManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->stream_count; ++i) {
        DataStream* stream = manager->streams[i];
        for (size_t j = 0; j < stream->count; ++j) {
            Event* event = stream->events[j];
            free(event->data_payload);
            free(event);
        }
        free(stream->events);
        free(stream);
    }
    free(manager->streams);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void manageDataStreamsAndProcessEvents(unsigned int initial_capacity, unsigned int seed, EventCallback cb) {
    StreamManager manager;
    initialize_stream_manager(&manager, initial_capacity, seed, cb);

    for (size_t i = 0; i < 5; ++i) {
        add_data_stream(&manager);
        char* payload = generate_secure_random_string(16, manager.seed + i);
        add_event_to_stream(&manager, i, payload);
        free(payload);
    }

    flush_streams_to_storage(&manager);

    free_stream_manager(&manager);
}

// Example callback function
void example_callback(Event event) {
    // Custom processing logic
}

int main() {
    manageDataStreamsAndProcessEvents(2, 12345, example_callback);
    return 0;
}
