#define INITIAL_STREAM_SIZE 10
#define STREAM_GROWTH_FACTOR 2
#define PAYLOAD_LENGTH 16
#define RECORD_INITIAL_CAPACITY 50
#define RANDOM_INT_MIN -1000
#define RANDOM_INT_MAX 1000

typedef struct {
    time_t timestamp;
    char payload[PAYLOAD_LENGTH + 1];
    int metadata_flags;
} Event;

typedef struct {
    size_t count;
    size_t capacity;
    Event *events;
} DataStream;

typedef struct {
    int value;
    char key[64];
    long *data_pointer;
