// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void seedRandom(int seed) {
    srand(seed);
}

char* generateRandomString(size_t length, int seed) {
    static const char charset[] =
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (seed != 0) {
        srand(seed); // Seed only once for reproducibility
    }

    char *random_string = malloc(length + 1);
    if (!random_string) {
        perror("Failed to allocate memory for random string");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        random_string[i] = charset[key];
    }

    random_string[length] = '\0';
    return random_string;
}

void initDataStream(DataStream *stream, size_t initial_capacity) {
    stream->count = 0;
    stream->capacity = initial_capacity;
    stream->events = malloc(initial_capacity * sizeof(Event));
    if (!stream->events) {
        perror("Failed to allocate memory for data streams");
        exit(EXIT_FAILURE);
    }
}

void resizeDataStream(DataStream *stream) {
    size_t new_capacity = stream->capacity * STREAM_GROWTH_FACTOR;
    Event *new_events = realloc(stream->events, new_capacity * sizeof(Event));
    if (!new_events) {
        perror("Failed to reallocate memory for data streams");
        exit(EXIT_FAILURE);
    }
    stream->events = new_events;
    stream->capacity = new_capacity;
}

void freeDataStream(DataStream *stream) {
    free(stream->events);
}

time_t getLatestTimestamp(const DataStream *stream) {
    if (stream->count == 0) return 0;

    time_t latest_timestamp = stream->events[0].timestamp;
    for (size_t i = 1; i < stream->count; i++) {
        if (stream->events[i].timestamp > latest_timestamp) {
            latest_timestamp = stream->events[i].timestamp;
        }
    }

    return latest_timestamp;
}

