        // Example: Flush to file or database
        printf("Flushing Data Stream %zu with %zu events\n", i, streams[i].count);
        // Reset the count after flushing
        streams[i].count = 0;
    }
}

void handleDataAndProcessRecords(int random_seed) {
    size_t stream_count = INITIAL_STREAM_SIZE;
    DataStream *streams = malloc(stream_count * sizeof(DataStream));
    if (!streams) {
        perror("Failed to allocate memory for data streams");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < stream_count; i++) {
        initDataStream(&streams[i], INITIAL_STREAM_SIZE);
    }

