data_structures* create_data_structures(size_t offset_count, size_t key_count,
                                        int min_value, int max_value) {
    if (offset_count <= 0 || key_count <= 0 || min_value > max_value) {
        return NULL;
    }

    data_structures *ds = malloc_pool(sizeof(data_structures));
    ds->offsets = malloc_pool(offset_count * sizeof(long));
    ds->keys = malloc_pool(key_count * sizeof(int));
    ds->record_list = malloc_pool(key_count * sizeof(record*));

    for (size_t i = 0; i < key_count; ++i) {
        ds->record_list[i] = malloc_pool(sizeof(record));
        ds->record_list[i]->value = rand() % (max_value - min_value + 1) + min_value;
        ds->record_list[i]->size = DEFAULT_RECORD_SIZE;

        // Initialize hash table
        if (!ds->hash_table) {
            ds->hash_table = initialize_hash_table(key_count);
        }
    }

    return ds;
}

hashtable* initialize_hash_table(size_t initial_capacity) {
    hashtable *ht = malloc_pool(sizeof(hashtable));
    ht->keys = NULL; // Will be allocated dynamically based on load
    ht->records = NULL; // Corresponding records
    ht->internal_data = NULL;
    ht->capacity = initial_capacity;

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(hashtable *ht) {
    if (ht) {
        free(ht->keys);
        for (size_t i = 0; i < ht->capacity; ++i) {
            if (ht->records[i]) {
                free(ht->records[i]);
            }
        }
        free(ht->records);
        pthread_mutex_destroy(&ht->lock);
        free_pool(ht);
    }
}

int hash_function(int key, size_t capacity) {
    return key % capacity;
}

void* malloc_pool(size_t size) {
    void *ptr = malloc(size); // For simplicity, using standard malloc
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_pool(void *ptr) {
    free(ptr);
