// Dynamic resizing function
void resize_array(void **array, size_t *capacity, size_t current_size, size_t element_size) {
    size_t new_capacity = (*capacity > 0 ? *capacity * 2 : 1);
    void *new_array = realloc(*array, new_capacity * element_size);
    if (new_array == NULL && *capacity != 0) {
        perror("Failed to resize array");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

// Initialize system state
void initialize_system(SystemState *state, size_t initial_pref_count, size_t initial_record_count, CallbackFunction callback) {
    state->preferences = malloc(initial_pref_count * sizeof(Preference));
    if (!state->preferences) {
        perror("Failed to allocate memory for preferences");
        exit(EXIT_FAILURE);
    }

    state->pref_capacity = initial_pref_count;
    state->pref_count = 0;

    state->records = malloc(initial_record_count * sizeof(Record));
    if (!state->records) {
        free(state->preferences);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    state->record_capacity = initial_record_count;
    state->record_count = 0;

    pthread_mutex_init(&state->pref_lock, NULL);
    pthread_mutex_init(&state->record_lock, NULL);

    state->callback = callback;
}

// Add preference to the system
void add_preference(SystemState *state, Preference pref) {
    pthread_mutex_lock(&state->pref_lock);

    if (state->pref_count == state->pref_capacity) {
        resize_array((void**)&state->preferences, &state->pref_capacity, state->pref_count, sizeof(Preference));
    }

    strncpy(state->preferences[state->pref_count].name, pref.name, sizeof(pref.name) - 1);
    state->preferences[state->pref_count].type = pref.type;
    strncpy(state->preferences[state->pref_count].default_value, pref.default_value, sizeof(pref.default_value) - 1);
    strncpy(state->preferences[state->pref_count].current_value, pref.current_value, sizeof(pref.current_value) - 1);
    strncpy(state->preferences[state->pref_count].dns_address, pref.dns_address, sizeof(pref.dns_address) - 1);

    state->pref_count++;

    if (state->callback) {
        state->callback(&state->preferences[state->pref_count - 1], NULL);
    }

    pthread_mutex_unlock(&state->pref_lock);
}

// Add record to the system
void add_record(SystemState *state, Record rec) {
    pthread_mutex_lock(&state->record_lock);

    if (rec.value < rec.min_range || rec.value > rec.max_range) {
        fprintf(stderr, "Record value out of range\n");
        pthread_mutex_unlock(&state->record_lock);
        return;
    }

    if (state->record_count == state->record_capacity) {
        resize_array((void**)&state->records, &state->record_capacity, state->record_count, sizeof(Record));
    }

    state->records[state->record_count].value = rec.value;
    state->records[state->record_count].min_range = rec.min_range;
    state->records[state->record_count].max_range = rec.max_range;

    state->record_count++;

    if (state->callback) {
        state->callback(NULL, &state->records[state->record_count - 1]);
    }

    pthread_mutex_unlock(&state->record_lock);
}

// Clean up system state
void cleanup_system(SystemState *state) {
    free(state->preferences);
    free(state->records);

    pthread_mutex_destroy(&state->pref_lock);
    pthread_mutex_destroy(&state->record_lock);
}

// Example callback function
void example_callback(Preference* pref, Record* rec) {
