                       int rand_min, int rand_max, RecordCallback callback) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize offsets
    offsets = malloc(offset_size * sizeof(long));
    if (!offsets) goto cleanup;

    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = custom_increment_pattern(i);
