    for (int i = 0; i < key_size; ++i) {
        keys[i] = i;
    }

    // Allocate and initialize records
    records = calloc(record_size, sizeof(Record));
    if (!records) goto cleanup;

    for (size_t i = 0; i < record_size; ++i) {
        pthread_mutex_lock(&lock);

        // Randomly generate an integer within the specified range
        int random_value = rand() % (rand_max - rand_min + 1) + rand_min;

        records[i].id = random_value;

