        // Allocate memory for the long value pointer
        long *value_ptr = malloc(sizeof(long));
        if (!value_ptr) goto cleanup;

        *value_ptr = random_value; // Example assignment
        records[i].value_ptr = value_ptr;

        pthread_mutex_unlock(&lock);

        // Invoke callback if provided
        if (callback) {
            callback(&records[i], i);
        }
    }

    pthread_mutex_destroy(&lock);
    return;

cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (size_t i = 0; i < record_size; ++i) {
            if (records[i].key_str) free(records[i].key_str);
