typedef struct Metadata {
    char name[64];
    double value;
} Metadata;

typedef struct Event {
    time_t timestamp;
    char *message;
    Metadata *metadata_ptr;
} Event;

typedef struct StatNode {
    int count;
    char description[128];
    time_t last_update;
    struct StatNode* next;
} StatNode;

// Function prototypes
void initializeDataStructure(unsigned long size, unsigned long (*customIncrement)(unsigned long), void (*eventCallback)(Event*, int));
Metadata *allocateAndInitializeMetadata(size_t name_length);
Event *initializeEvents(size_t num_events, Metadata *metadata_array, size_t metadata_size);
StatNode* insertStat(StatNode* head, const char* description, time_t timestamp);
void processEventCallback(Event *event, int index);

typedef struct DataStructure {
    unsigned long id[MAX_ID_SIZE];
    Metadata metadata[MDATA_SIZE];
    Event events[NUM_EVENTS];
    StatNode *stats_head;
} DataStructure;

pthread_mutex_t id_lock = PTHREAD_MUTEX_INITIALIZER;

// Main function to initialize the data structure
void initializeDataStructure(unsigned long size, unsigned long (*customIncrement)(unsigned long), void (*eventCallback)(Event*, int)) {
    pthread_mutex_lock(&id_lock);
    for (unsigned long i = 0; i < size; ++i) {
        id[i] = customIncrement(i); // Apply the custom increment logic
    }
    pthread_mutex_unlock(&id_lock);

    Metadata *metadata_array = allocateAndInitializeMetadata(MDATA_SIZE * sizeof(char));
    memcpy(dataStructure.metadata, metadata_array, MDATA_SIZE * sizeof(Metadata));
    free(metadata_array);

    Event *events = initializeEvents(NUM_EVENTS, dataStructure.metadata, MDATA_SIZE);
    if (eventCallback != NULL) {
        for (size_t i = 0; i < NUM_EVENTS; ++i) {
            eventCallback(&dataStructure.events[i], i);
        }
    }

    dataStructure.stats_head = NULL;
}

Metadata *allocateAndInitializeMetadata(size_t name_length) {
    Metadata *metadata_array = malloc(MDATA_SIZE * sizeof(Metadata));
    for (size_t i = 0; i < MDATA_SIZE; ++i) {
        snprintf(metadata_array[i].name, sizeof(metadata_array[i].name), "Meta_%lu", i);
        metadata_array[i].value = (double)i;
    }
    return metadata_array;
}

Event *initializeEvents(size_t num_events, Metadata *metadata_array, size_t metadata_size) {
    Event *events = malloc(num_events * sizeof(Event));
    for (size_t i = 0; i < num_events; ++i) {
        events[i].timestamp = time(NULL);

        char message[256];
        snprintf(message, sizeof(message), "Event %lu: %s", dataStructure.id[i % metadata_size], metadata_array[i % metadata_size].name);
        events[i].message = strdup(message);

        events[i].metadata_ptr = &metadata_array[i % metadata_size];
    }
    return events;
}

StatNode* insertStat(StatNode* head, const char* description, time_t timestamp) {
    StatNode *new_node = malloc(sizeof(StatNode));
    if (!new_node) {
        perror("Failed to allocate memory for stat node");
        exit(EXIT_FAILURE);
    }

    strncpy(new_node->description, description, sizeof(new_node->description) - 1);
    new_node->count = 0;
    new_node->last_update = timestamp;
    new_node->next = head;

    return new_node;
}

void processEventCallback(Event *event, int index) {
    printf("Processing event %d: %s\n", index, event->message);
}
