```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>
#include <zlib.h>

typedef enum { TYPE_STRING, TYPE_INT, TYPE_FLOAT } ResourceType;
typedef struct {
    char *name;
    ResourceType type;
    union {
        char *stringValue;
        int intValue;
        float floatValue;
    } defaultVal, currVal;
    char *id;
    int version;
} Resource;

typedef struct {
    double value;
} DataChunk;

typedef struct CacheNode {
    void *data;
    size_t key;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *head;
    pthread_mutex_t lock;
} Cache;

// Global resources and data chunks
Resource **resources = NULL;
DataChunk **dataChunks = NULL;
size_t resourceCount = 0, dataChunkCount = 0;
pthread_mutex_t resourcesLock = PTHREAD_MUTEX_INITIALIZER;
Cache cache = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function declarations
void initResourceManager();
void shutdownResourceManager();
void addResource(const char *name, ResourceType type, const void *defaultValue, const char *id);
void updateResourceValue(const char *resourceId, const void *newValue);
DataChunk* createDataChunk(double value);
void validateDataChunk(DataChunk *chunk);
void resizeResources(size_t newCount);
void resizeDataChunks(size_t newCount);
void cacheResource(Resource *res);
void evictCache();
int detectFileFormat(const char *filename);
void parseLogFile(const char *filename);
void processLogEntry(const char *entry, int formatType);
void aggregateCalculations();
void sendToExternalService();

// Custom memory allocator
void* customAlloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void customFree(void *ptr) {
    free(ptr);
}

// Initialize ResourceManager
void initResourceManager() {
    resources = (Resource **)customAlloc(sizeof(Resource *));
    dataChunks = (DataChunk **)customAlloc(sizeof(DataChunk *));
    resourceCount = 0;
    dataChunkCount = 0;
}

// Shutdown ResourceManager
void shutdownResourceManager() {
    for (size_t i = 0; i < resourceCount; ++i) {
        customFree(resources[i]->name);
        switch (resources[i]->type) {
            case TYPE_STRING: customFree(resources[i]->defaultVal.stringValue); break;
            case TYPE_INT: break;
            case TYPE_FLOAT: break;
        }
        customFree(resources[i]->id);
        customFree(resources[i]);
    }
    customFree(resources);

    for (size_t i = 0; i < dataChunkCount; ++i) {
        customFree(dataChunks[i]);
    }
    customFree(dataChunks);
}

// Add a new Resource
void addResource(const char *name, ResourceType type, const void *defaultValue, const char *id) {
    pthread_mutex_lock(&resourcesLock);

    size_t newSize = resourceCount + 1;
    resources = (Resource **)customRealloc(resources, sizeof(Resource *) * newSize);
    resources[resourceCount] = (Resource *)customAlloc(sizeof(Resource));
    resources[resourceCount]->name = strdup(name);
    resources[resourceCount]->type = type;

    switch (type) {
        case TYPE_STRING:
            resources[resourceCount]->defaultVal.stringValue = strdup((const char *)defaultValue);
            break;
        case TYPE_INT:
            resources[resourceCount]->defaultVal.intValue = *(int *)defaultValue;
            break;
        case TYPE_FLOAT:
            resources[resourceCount]->defaultVal.floatValue = *(float *)defaultValue;
            break;
    }

    resources[resourceCount]->currVal = resources[resourceCount]->defaultVal; // Copy default as current
    resources[resourceCount]->id = strdup(id);
    resources[resourceCount]->version = 1;

    pthread_mutex_unlock(&resourcesLock);

    resourceCount++;
}

// Update Resource Value
void updateResourceValue(const char *resourceId, const void *newValue) {
    pthread_mutex_lock(&resourcesLock);
    for (size_t i = 0; i < resourceCount; ++i) {
        if (strcmp(resources[i]->id, resourceId) == 0) {
            switch (resources[i]->type) {
                case TYPE_STRING:
                    customFree(resources[i]->currVal.stringValue);
                    resources[i]->currVal.stringValue = strdup((const char *)newValue);
                    break;
                case TYPE_INT:
                    resources[i]->currVal.intValue = *(int *)newValue;
                    break;
                case TYPE_FLOAT:
                    resources[i]->currVal.floatValue = *(float *)newValue;
                    break;
            }
            resources[i]->version++;
            pthread_mutex_unlock(&resourcesLock);
            return;
        }
    }
    pthread_mutex_unlock(&resourcesLock);
}

// Create a Data Chunk
DataChunk* createDataChunk(double value) {
    DataChunk *chunk = (DataChunk *)customAlloc(sizeof(DataChunk));
    chunk->value = value;
    validateDataChunk(chunk);

    pthread_mutex_lock(&resourcesLock);
    size_t newSize = dataChunkCount + 1;
    dataChunks = (DataChunk **)customRealloc(dataChunks, sizeof(DataChunk *) * newSize);
    dataChunks[dataChunkCount] = chunk;
    pthread_mutex_unlock(&resourcesLock);

    dataChunkCount++;
    return chunk;
}

// Validate Data Chunk
void validateDataChunk(DataChunk *chunk) {
    if (isnan(chunk->value)) {
        fprintf(stderr, "Invalid value in data chunk\n");
        exit(EXIT_FAILURE);
    }
}

// Resize Resources Array
void resizeResources(size_t newCount) {
    resources = (Resource **)customRealloc(resources, sizeof(Resource *) * newCount);
}

// Resize Data Chunks Array
void resizeDataChunks(size_t newCount) {
    dataChunks = (DataChunk **)customRealloc(dataChunks, sizeof(DataChunk *) * newCount);
}

// Cache a Resource
void cacheResource(Resource *res) {
    pthread_mutex_lock(&cache.lock);
    CacheNode *node = (CacheNode *)customAlloc(sizeof(CacheNode));
    node->data = res;
    size_t key = hashFunction(res->id); // Assume hashFunction is implemented

    node->next = cache.head;
    cache.head = node;

    pthread_mutex_unlock(&cache.lock);
}

// Evict Cache
void evictCache() {
    pthread_mutex_lock(&cache.lock);
    if (cache.head != NULL) {
        CacheNode *node = cache.head;
        cache.head = node->next;
        customFree(node->data);
        customFree(node);
    }
    pthread_mutex_unlock(&cache.lock);
}

// Detect File Format
int detectFileFormat(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    unsigned char buffer[4];
    fread(buffer, 1, sizeof(buffer), file);

    fclose(file);

    if (memcmp(buffer, "\x7B\x7D", 2) == 0 || memcmp(buffer, "\xEF\xBB\xBF{", 3) == 0) {
        return JSON_FORMAT;
    } else if (buffer[0] == '\xEF' && buffer[1] == '\xBB' && buffer[2] == '\xBF') {
        return CSV_FORMAT; // Detect BOM for UTF-8
    }
    return BINARY_FORMAT;
}

// Parse Log File
void parseLogFile(const char *filename) {
    int formatType = detectFileFormat(filename);
    if (formatType < 0) {
        fprintf(stderr, "Unsupported file format\n");
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen(filename, "r");
    if (!file) return;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        processLogEntry(buffer, formatType);
    }

    fclose(file);

    aggregateCalculations();
}

// Process Log Entry
