    int minRange;
    int maxRange;
} Record;

typedef void (*CallbackFunction)(void *);

// Dynamic array structure
typedef struct {
    void **data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} DynamicArray;

DynamicArray *createDynamicArray(size_t initialCapacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (void **)malloc(initialCapacity * sizeof(void *));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int resizeDynamicArray(DynamicArray *array, size_t newCapacity) {
    if (!array || newCapacity <= array->capacity) return -1;

    void **newData = (void **)realloc(array->data, newCapacity * sizeof(void *));
    if (!newData) return -1;

    array->data = newData;
    array->capacity = newCapacity;
    return 0;
}

int addElementToDynamicArray(DynamicArray *array, void *element) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity && resizeDynamicArray(array, array->capacity * 2) != 0) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->data[array->size++] = element;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

Preference *createPreference(const char *name, ValueType type, const char *defaultValue, int categoryIdentifier) {
    Preference *pref = (Preference *)malloc(sizeof(Preference));
    if (!pref) return NULL;

    pref->name = strdup(name);
    pref->type = type;
    pref->defaultValue = strdup(defaultValue);
    pref->currentValue = strdup(defaultValue);
    pref->categoryIdentifier = categoryIdentifier;

