    return name && strlen(name) > 0;
}

int validatePreferenceValue(ValueType type, const char *value) {
    switch (type) {
        case TYPE_STRING:
            return value && strlen(value) > 0;
        case TYPE_INTEGER:
            return value && strspn(value, "0123456789") == strlen(value);
        case TYPE_BOOLEAN:
            return value && (strcmp(value, "true") == 0 || strcmp(value, "false") == 0);
        default:
