    }
}

void managePreferencesAndDataProcessing(size_t prefSize, size_t recordSize, CallbackFunction callback) {
    DynamicArray *preferences = createDynamicArray(prefSize);
    DynamicArray *records = createDynamicArray(recordSize);

    if (!preferences || !records) {
        // Handle error
        return;
    }

    for (size_t i = 0; i < prefSize; ++i) {
        Preference *pref = createPreference("defaultPref", TYPE_STRING, "defaultValue", i);
        if (callback) callback(pref);
        addElementToDynamicArray(preferences, pref);
    }

    for (size_t i = 0; i < recordSize; ++i) {
        Record *record = createRecord(0, -100, 100); // Example range
        if (callback) callback(record);
        addElementToDynamicArray(records, record);
    }

    // Simulate processing and cleanup
    for (size_t i = 0; i < preferences->size; ++i) {
        freePreference((Preference *)preferences->data[i]);
    }
    for (size_t i = 0; i < records->size; ++i) {
        freeRecord((Record *)records->data[i]);
    }

    free(preferences->data);
    pthread_mutex_destroy(&preferences->lock);
    free(preferences);

    free(records->data);
    pthread_mutex_destroy(&records->lock);
    free(records);
}

// Example callback function
void exampleCallback(void *element) {
