    if (!res) {
        fprintf(stderr, "Memory allocation failed for new resource\n");
        exit(EXIT_FAILURE);
    }

    res->client_id = client_id ? strdup(client_id) : NULL;
    res->access_level = access_level ? strdup(access_level) : NULL;
    res->usage_limit = usage_limit;
    return res;
}

void set_resource_properties(Resource *res, const char *type, int allocation_status,
                             int current_usage) {
