        int intValue;
        bool boolValue;
    };
    union {
        char *defaultValueString;
        int defaultValueInt;
        bool defaultValueBool;
    };
} Preference;

#define INITIAL_SIZE 10
#define RESIZE_FACTOR 2

typedef void (*PreferenceInitCallback)(Preference *);

typedef struct {
    Preference *preferences;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    PreferenceInitCallback initCallback;
} PreferenceManager;

void resizePreferences(PreferenceManager *manager) {
    manager->capacity *= RESIZE_FACTOR;
    manager->preferences = realloc(manager->preferences, sizeof(Preference) * manager->capacity);
}

void initializePreferences(PreferenceManager *manager, size_t minSize, size_t maxSize) {
    pthread_mutex_lock(&manager->lock);

    if (minSize > manager->capacity) {
        while (manager->capacity < minSize && manager->capacity <= maxSize / RESIZE_FACTOR) {
            resizePreferences(manager);
        }
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->initCallback) {
            manager->initCallback(&manager->preferences[i]);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void addPreference(PreferenceManager *manager, const char *name, ValueType type, void *defaultValue) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resizePreferences(manager);
    }

    Preference *pref = &manager->preferences[manager->count++];
    pref->name = strdup(name);
    pref->type = type;

    switch (type) {
        case STRING:
            pref->defaultValueString = strdup((char *)defaultValue);
            pref->stringValue = strdup(pref->defaultValueString);
            break;
        case INTEGER:
            pref->defaultValueInt = *(int *)defaultValue;
            pref->intValue = pref->defaultValueInt;
            break;
        case BOOLEAN:
            pref->defaultValueBool = *(bool *)defaultValue;
            pref->boolValue = pref->defaultValueBool;
            break;
    }

    pthread_mutex_unlock(&manager->lock);
}

void manageUserPreferences(size_t minSize, size_t maxSize, PreferenceInitCallback callback) {
    PreferenceManager manager = { .capacity = INITIAL_SIZE, .count = 0 };
    manager.initCallback = callback;

    if (posix_memalign((void **)&manager.preferences, 16, sizeof(Preference) * manager.capacity)) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    initializePreferences(&manager, minSize, maxSize);

    pthread_mutex_init(&manager.lock, NULL);
    char inputBuffer[256];

    while (true) {
        printf("Enter preference (or 'exit' to finish): ");
        if (!fgets(inputBuffer, sizeof(inputBuffer), stdin)) break;
        if (strncmp(inputBuffer, "exit", 4) == 0) break;

        // Basic parsing logic for demonstration; should be expanded with robust error checking
        char *name = strtok(inputBuffer, ",");
        ValueType type;
        char *valueStr = strtok(NULL, ",");

        if (!name || !valueStr) continue;

        // Determine value type and add preference (simplified)
        int intValue;
        bool isBool = (strcmp(valueStr, "true") == 0 || strcmp(valueStr, "false") == 0);
        ValueType valueType = STRING;

        if (isBool) {
            valueType = BOOLEAN;
            bool boolValue = (strcmp(valueStr, "true") == 0);
            addPreference(&manager, name, valueType, &boolValue);
        } else if (sscanf(valueStr, "%d", &intValue) == 1) {
            valueType = INTEGER;
            addPreference(&manager, name, valueType, &intValue);
        } else {
            addPreference(&manager, name, valueType, valueStr);
        }
    }

    pthread_mutex_destroy(&manager.lock);

    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.preferences[i].name);
        if (manager.preferences[i].type == STRING) {
            free(manager.preferences[i].stringValue);
            free(manager.preferences[i].defaultValueString);
        }
    }

    free(manager.preferences);
}
