data_point* initializeDataPoints(FILE *file, int *num_points) {
    size_t chunk_size = 1024;
    data_point *points = NULL;
    int capacity = 0;

    if (!file) return NULL;

    points = malloc(chunk_size * sizeof(data_point));
    if (!points) {
        perror("Failed to allocate memory for data points");
        freeMemory(NULL, NULL, points, *num_points);
        exit(EXIT_FAILURE);
    }

    capacity = chunk_size;
    int count = 0;

    while (fscanf(file, "%lf %255s %zu", &points[count].value,
                  points[count].string, &points[count].index) == 3) {

        if (++count >= capacity) {
            capacity *= 2;
            data_point *new_points = realloc(points, capacity * sizeof(data_point));
            if (!new_points) {
                perror("Failed to resize memory for data points");
                freeMemory(NULL, NULL, points, *num_points);
                exit(EXIT_FAILURE);
            }
            points = new_points;
        }

        // Ensure no null bytes are missing in string
        for (int i = 0; i < MAX_STRING_LENGTH; ++i) {
            if (points[count].string[i] == '\0') break;
            if (i == MAX_STRING_LENGTH - 1) {
                fprintf(stderr, "String exceeds maximum length\n");
                freeMemory(NULL, NULL, points, *num_points);
                exit(EXIT_FAILURE);
            }
        }
    }

    *num_points = count;

    return points;
}

metadata* initializeMetadata(FILE *file, int *num_metadata) {
    size_t chunk_size = 1024;
    metadata *meta = NULL;
    int capacity = 0;

    if (!file) return NULL;

    meta = malloc(chunk_size * sizeof(metadata));
    if (!meta) {
        perror("Failed to allocate memory for metadata");
        freeMemory(NULL, NULL, NULL, 0);
        exit(EXIT_FAILURE);
    }

    capacity = chunk_size;
    int count = 0;

    while (fscanf(file, "%ld %d", &meta[count].offset, &meta[count].key) == 2) {

        if (++count >= capacity) {
            capacity *= 2;
            metadata *new_meta = realloc(meta, capacity * sizeof(metadata));
            if (!new_meta) {
                perror("Failed to resize memory for metadata");
                freeMemory(NULL, NULL, NULL, 0);
                exit(EXIT_FAILURE);
            }
            meta = new_meta;
        }
    }

    *num_metadata = count;

    return meta;
}

