    size_t size;
    pthread_mutex_t lock;
} RecordsCollection;

RecordsCollection* create_collection(size_t initial_capacity) {
    RecordsCollection *collection = malloc(sizeof(RecordsCollection));
    collection->records = malloc(initial_capacity * sizeof(Record *));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void resize_collection_if_needed(RecordsCollection *collection) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) return; // Handle allocation failure
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
}

void add_record(RecordsCollection *collection, int value, const char *key, unsigned long seed) {
    pthread_mutex_lock(&collection->lock);
    resize_collection_if_needed(collection);

    Record *record = malloc(sizeof(Record));
    record->value = value; // Assuming a function to generate 'value' using 'seed'
    record->key = strdup(key); // Duplicate the string for storage
    record->pointer = malloc(sizeof(long));
    *(record->pointer) = 0;

    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->lock);
}

void free_record(Record *record) {
    if (record) {
        free(record->key);
        free(record->pointer);
        free(record);
    }
}

void free_collection(RecordsCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        free_record(collection->records[i]);
    }

    free(collection->records);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int find_max_value(RecordsCollection *collection) {
    int max_value = INT_MIN;
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i]->value > max_value) {
            max_value = collection->records[i]->value;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return max_value;
}

