#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "external_file_lib.h" // Placeholder for external library

typedef int (*transform_func_t)(const char *);

// Structure to manage file data and transformations
typedef struct {
    FILE *file;
    char **buffer;
    size_t buffer_size;
    size_t capacity;
} FileData;

// Thread-safe queue node
typedef struct Node {
    int value;
    struct Node *next;
} Node;

// Global error message
char g_error_message[256] = {0};

// Function prototypes
void processFileSequence(const char **input_files, const char *output_file, transform_func_t transform);
static void initializeFileData(FileData *fd, const char *filename);
static void readFileLines(FileData *fd);
static int transformLine(const char *line, transform_func_t transform);
static void writeOutputFile(int *data, size_t data_count, const char *filename);
static void freeResources(FileData *fd, Node **head);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void processFileSequence(const char **input_files, int num_input_files, const char *output_file, transform_func_t transform) {
    FileData *file_data_arr = malloc(num_input_files * sizeof(FileData));
    Node *head = NULL;
    Node *tail = NULL;

    if (!file_data_arr) {
        snprintf(g_error_message, sizeof(g_error_message), "Memory allocation failed for file data array.");
        goto cleanup;
    }

    // Initialize and read lines from each input file
    for (int i = 0; i < num_input_files; ++i) {
        initializeFileData(&file_data_arr[i], input_files[i]);
        if (!file_data_arr[i].buffer) {
            snprintf(g_error_message, sizeof(g_error_message), "Failed to read lines from %s.", input_files[i]);
            goto cleanup;
        }
    }

    // Process each line and apply transformation
    for (int i = 0; i < num_input_files; ++i) {
        size_t line_count = file_data_arr[i].buffer_size;
        for (size_t j = 0; j < line_count; ++j) {
            int value = transformLine(file_data_arr[i].buffer[j], transform);
            if (value != -1) { // Assuming -1 is returned for invalid inputs
                pthread_mutex_lock(&mutex);
                Node *new_node = malloc(sizeof(Node));
                if (!new_node) {
                    snprintf(g_error_message, sizeof(g_error_message), "Memory allocation failed for node.");
                    pthread_mutex_unlock(&mutex);
                    goto cleanup;
                }
                new_node->value = value;
                new_node->next = NULL;
                if (tail) {
                    tail->next = new_node;
                } else {
                    head = new_node;
                }
                tail = new_node;
                pthread_mutex_unlock(&mutex);
            }
        }
    }

    // Write transformed data to output file
    writeOutputFile(head, 0, output_file);

cleanup:
    freeResources(file_data_arr, &head);
    if (g_error_message[0]) {
        fprintf(stderr, "Error: %s\n", g_error_message);
    }
}

static void initializeFileData(FileData *fd, const char *filename) {
    fd->file = external_fopen(filename, "r"); // Using external library
    if (!fd->file) {
        snprintf(g_error_message, sizeof(g_error_message), "Could not open file %s", filename);
        return;
    }
    readFileLines(fd);
}

static void readFileLines(FileData *fd) {
    fd->buffer = malloc(10 * sizeof(char *));
    if (!fd->buffer) {
        snprintf(g_error_message, sizeof(g_error_message), "Memory allocation failed for line buffer.");
        external_fclose(fd->file); // Using external library
        return;
    }
    fd->capacity = 10;
    fd->buffer_size = 0;

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getdelim(&line, &len, '\n', fd->file)) != -1) {
        if (fd->buffer_size == fd->capacity) {
            fd->capacity *= 2;
            char **new_buffer = realloc(fd->buffer, fd->capacity * sizeof(char *));
            if (!new_buffer) {
                snprintf(g_error_message, sizeof(g_error_message), "Memory reallocation failed for line buffer.");
                free(line);
                external_fclose(fd->file); // Using external library
                return;
            }
            fd->buffer = new_buffer;
        }
        fd->buffer[fd->buffer_size] = strndup(line, read - 1);
        if (!fd->buffer[fd->buffer_size]) {
            snprintf(g_error_message, sizeof(g_error_message), "Memory allocation failed for line data.");
            free(line);
            external_fclose(fd->file); // Using external library
            return;
        }
        fd->buffer_size++;
    }
    free(line);
    if (ferror(fd->file)) {
        snprintf(g_error_message, sizeof(g_error_message), "Error reading file.");
    }
    external_fclose(fd->file); // Using external library
}

static int transformLine(const char *line, transform_func_t transform) {
    return transform ? transform(line) : -1;
}

static void writeOutputFile(Node *head, size_t data_count, const char *filename) {
    FILE *output_file = external_fopen(filename, "w"); // Using external library
    if (!output_file) {
        snprintf(g_error_message, sizeof(g_error_message), "Could not open output file %s", filename);
        return;
    }

    Node *current = head;
    while (current) {
        fprintf(output_file, "%d\n", current->value);
        data_count++;
        current = current->next;
    }
    external_fclose(output_file); // Using external library
}

static void freeResources(FileData *fd_arr, Node **head) {
    for (int i = 0; fd_arr[i].buffer; ++i) {
        for (size_t j = 0; j < fd_arr[i].buffer_size; ++j) {
            free(fd_arr[i].buffer[j]);
        }
        free(fd_arr[i].buffer);
    }
    free(fd_arr);

    Node *current = *head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
}
