void handleError(const char* msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

long* allocateLong(size_t size, const char* errorMsg) {
    void *ptr = calloc(size, sizeof(long));
    if (!ptr) {
        handleError(errorMsg);
    }
    return ptr;
}

int* allocateInt(size_t size, const char* errorMsg) {
    void *ptr = calloc(size, sizeof(int));
    if (!ptr) {
        handleError(errorMsg);
    }
    return ptr;
}

record* allocateRecord(size_t size, const char* errorMsg) {
    record *recs = calloc(size, sizeof(record));
    if (!recs) {
        handleError(errorMsg);
    }
    for (size_t i = 0; i < size; ++i) {
        recs[i].long_ptr = allocateLong(1, "Failed to allocate long");
    }
    return recs;
}

void findMax(const int *array, size_t size, int *max) {
    if (size == 0) return;
    *max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > *max) {
            *max = array[i];
        }
    }
}

void processRecordsAndFindMax(size_t recordSize, unsigned int seed, void (*callback)(const record*)) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = allocateLong(recordSize, "Failed to allocate offsets");
    int *keys = allocateInt(recordSize, "Failed to allocate keys");

    srand(seed);
    record *records = allocateRecord(recordSize, "Failed to allocate records");

    for (size_t i = 0; i < recordSize; ++i) {
        offsets[i] = i;
        keys[i] = i;
        records[i].value = rand() % 100 + 1;

        if (callback) {
            callback(&records[i]);
        }
    }

    size_t intArraySize = 10;
    int *integers = allocateInt(intArraySize, "Failed to allocate integers");
    size_t count = 0;

    while (1) {
        pthread_mutex_lock(&lock);
        if (count == intArraySize) {
            intArraySize *= 2;
            integers = realloc(integers, intArraySize * sizeof(int));
            if (!integers) {
                handleError("Failed to resize integers array");
            }
        }

        int input;
        if (scanf("%d", &input) != 1 || ferror(stdin)) {
            break; // Handle unexpected input gracefully
        }

        if (input == -1) break;

        integers[count++] = input;
        pthread_mutex_unlock(&lock);
    }

    int max = 0;
    findMax(integers, count, &max);

    printf("The maximum integer is: %d\n", max);

    if (count > 10000 && count % 1000 == 0) {
        char errorLog[256];
        snprintf(errorLog, sizeof(errorLog), "Processed %zu integers.\n", count);
        va_list args;
        va_start(args, errorLog);
        vfprintf(stderr, errorLog, args);
        va_end(args);
    }

    free(offsets);
    free(keys);
    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i].long_ptr);
    }
    free(records);
    free(integers);

    pthread_mutex_destroy(&lock);
}
