#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "secure_random.h" // External library for secure random number generation
#include "timestamp.h"     // External library for timestamp functions

typedef struct {
    char *name;
    int priority;
    char *status;
    time_t deadline;
} Task;

typedef void (*TaskCallback)(const Task*);

typedef struct {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    int seed;
    TaskCallback callback;
} TaskManager;

void log_task_info(const Task *task);

Task* create_task(const char *name, int priority, const char *status, time_t deadline) {
    Task *task = malloc(sizeof(Task));
    if (!task) return NULL;

    task->name = strdup(name);
    task->priority = priority;
    task->status = strdup(status);
    task->deadline = deadline;

    if (!task->name || !task->status) {
        free(task->name);
        free(task->status);
        free(task);
        return NULL;
    }

    return task;
}

void destroy_task(Task *task) {
    if (task) {
        free(task->name);
        free(task->status);
        free(task);
    }
}

int initialize_task_manager(TaskManager *manager, size_t initial_capacity, int seed) {
    if (!manager) return -1;

    manager->tasks = malloc(initial_capacity * sizeof(Task*));
    if (!manager->tasks) return -1;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->seed = seed;
    pthread_mutex_init(&manager->mutex, NULL);

    secure_random_set_seed(seed);
    for (size_t i = 0; i < initial_capacity; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "Task%d", i + 1);

        int priority = secure_random(1, 100); // Secure random number between 1 and 100
        time_t deadline = timestamp_now() + (secure_random(1, 100) * 86400); // Random future deadline

        Task *task = create_task(name, priority, "Pending", deadline);
        if (!task) {
            for (size_t j = 0; j < i; ++j) {
                destroy_task(manager->tasks[j]);
            }
            free(manager->tasks);
            pthread_mutex_destroy(&manager->mutex);
            return -1;
        }

        manager->tasks[i] = task;
        log_task_info(task); // Log the task name and its priority
    }

    return 0;
}

void resize_tasks(TaskManager *manager, size_t new_capacity) {
    Task **new_tasks = realloc(manager->tasks, new_capacity * sizeof(Task*));
    if (!new_tasks) return;

    manager->tasks = new_tasks;
    manager->capacity = new_capacity;
}

int add_task(TaskManager *manager, const char *name, time_t deadline) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        resize_tasks(manager, manager->capacity * 2);
        if (!manager->tasks) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }

    int priority = secure_random(1, 100);
    Task *task = create_task(name, priority, "Pending", deadline);

    if (!task) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->tasks[manager->count++] = task;
    log_task_info(task);

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int remove_task(TaskManager *manager, const char *name) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->tasks[i]->name, name) == 0) {
            destroy_task(manager->tasks[i]);
            memmove(&manager->tasks[i], &manager->tasks[i + 1],
                    (manager->count - i - 1) * sizeof(Task*));
            manager->count--;

            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1;
}

void update_task_status(TaskManager *manager, int (*priority_rule)(int), char *(*status_rule)(time_t)) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        Task *task = manager->tasks[i];

        if (priority_rule(task->priority)) {
            char *new_status = status_rule(task->deadline);

            free(task->status);
            task->status = new_status;

            printf("Task %s updated to status: %s\n", task->name, task->status);

            if (manager->callback) {
                manager->callback(task);
            }
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void free_task_manager(TaskManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        destroy_task(manager->tasks[i]);
    }

    free(manager->tasks);
    pthread_mutex_destroy(&manager->mutex);
}

void log_task_info(const Task *task) {
    printf("Task %s assigned priority: %d\n", task->name, task->priority);
}

int main() {
    TaskManager manager;
    if (initialize_task_manager(&manager, 10, 12345)) {
        fprintf(stderr, "Failed to initialize task manager\n");
        return EXIT_FAILURE;
    }

    add_task(&manager, "Task11", timestamp_now() + 100000);

    int priority_rule(int priority) { return priority > 50; }
    char* status_rule(time_t deadline) {
        time_t now = timestamp_now();
        if (deadline - now < 86400) return "Urgent";
        return "High";
    }

    update_task_status(&manager, priority_rule, status_rule);

    remove_task(&manager, "Task1");

    free_task_manager(&manager);
    return EXIT_SUCCESS;
}
```

This C code implements a flexible task management system with dynamic array handling, secure random number generation for priorities, logging of tasks, and concurrent access handling using mutexes. It uses an external library for secure random numbers and timestamps. The system allows dynamic addition, removal, and updating of tasks based on user-defined rules, and includes error handling and cleanup mechanisms.']

