    // Rotate: rename current log and create new one
    char old_name[256];
    snprintf(old_name, sizeof(old_name), "%s.old", "log.txt");
    if (rename("log.txt", old_name) != 0) perror("Failed to rotate log file");

    config->file = fopen("log.txt", "a");

    // Compress the rotated file if required
    if (config->compress_after_rotation) {
        char command[512];
        snprintf(command, sizeof(command), "gzip %s", old_name);
        system(command);  // Simple compression, not production-safe; handle errors in real use
    }
}

void log_message(LoggerConfig *config, const char *message) {
    pthread_mutex_lock(&record_lock);

    if (ftell(config->file) >= config->rotation_size) {
        rotate_and_compress_log(config);
    }

    fprintf(config->file, "%s\n", message);
    fflush(config->file);

    pthread_mutex_unlock(&record_lock);
}

Status initialize_records(Record **records, size_t num_records, size_t max_string_length,
                          int key_min, int key_max, LoggerConfig *logger) {
    if (num_records == 0 || max_string_length == 0 || logger->file == NULL) return ALLOCATION_FAILURE;

    pthread_mutex_lock(&record_lock);

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "Initializing %zu records with string length up to %zu", num_records, max_string_length);
    log_message(logger, log_buffer);

    *records = malloc(num_records * sizeof(Record));
    if (!*records) {
        pthread_mutex_unlock(&record_lock);
        return ALLOCATION_FAILURE;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].data = malloc(max_string_length + 1);
        if (!(*records)[i].data) {
            // Free all previously allocated data and records
            while (i > 0) {
                free((*records)[--i].data);
            }
            free(*records);
            *records = NULL;
            pthread_mutex_unlock(&record_lock);
            return ALLOCATION_FAILURE;
        }

        (*records)[i].key = key_min + rand() % (key_max - key_min + 1);
        snprintf(log_buffer, sizeof(log_buffer), "Record %zu: Key %d", i + 1, (*records)[i].key);
        log_message(logger, log_buffer);

        // Initialize string data and timestamp
        strcpy((*records)[i].data, "");  // Zero-initialize
        (*records)[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&record_lock);

    snprintf(log_buffer, sizeof(log_buffer), "Successfully initialized records");
    log_message(logger, log_buffer);

    return SUCCESS;
}

void free_records(Record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].data);
    }
    free(records);
}
