void parse_csv(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    // Dynamic allocation for varying data sizes
    double *doubleArray = NULL;
    point *pointArray = NULL;
    enum status *statusArray = NULL;

    size_t doubleCount = 0, pointCount = 0, statusCount = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Tokenize the CSV line
        const char *token = strtok(line, ",");

        while (token) {
            if (double sscanf(token, "%lf", &(*(double *)malloc(sizeof(double)))) == 1) {
                doubleArray = realloc(doubleArray, (doubleCount + 1) * sizeof(double));
                doubleArray[doubleCount++] = atof(token);
            } else if (sscanf(token, "%f,%f", &(((point *)malloc(sizeof(point)))->x), &(((point *)malloc(sizeof(point)))->y)) == 2) {
                pointArray = realloc(pointArray, (pointCount + 1) * sizeof(point));
                pointArray[pointCount++] = *(point *)malloc(sizeof(point)); // Assumes valid coordinates
            } else if (strcmp(token, "STATUS_OK") == 0) {
                statusArray = realloc(statusArray, (statusCount + 1) * sizeof(enum status));
                statusArray[statusCount++] = STATUS_OK;
            } else if (strcmp(token, "STATUS_ERROR") == 0) {
                statusArray = realloc(statusArray, (statusCount + 1) * sizeof(enum status));
                statusArray[statusCount++] = STATUS_ERROR;
            }

            token = strtok(NULL, ",");
        }
    }

    fclose(file);

    // Validate and handle the memory allocation
    if (!doubleArray || !pointArray || !statusArray) {
        fprintf(stderr, "Error allocating memory for data structures\n");
        free(doubleArray);
        free(pointArray);
        free(statusArray);
        return;
    }

    // Process the arrays as needed (example: print)
    for (size_t i = 0; i < doubleCount; ++i) {
        printf("Double %zu: %f\n", i, doubleArray[i]);
    }

    for (size_t i = 0; i < pointCount; ++i) {
        printf("Point %zu: (%f, %f)\n", i, pointArray[i].x, pointArray[i].y);
    }

    for (size_t i = 0; i < statusCount; ++i) {
        printf("Status %zu: %d\n", i, statusArray[i]);
    }

    // Free allocated memory
    free(doubleArray);
    free(pointArray);
    free(statusArray);
}
