// Thread-safe allocation functions
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long* allocate_and_initialize_offsets(size_t num_records) {
    long *offsets = (long *) safe_malloc(num_records * sizeof(long));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand();
    }
    return offsets;
}

int* allocate_and_initialize_keys(int min_val, int max_val, size_t num_records) {
    int range = max_val - min_val + 1;
    int *keys = (int *) safe_malloc(num_records * sizeof(int));
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = rand() % range + min_val;
    }
    return keys;
}

Record** allocate_and_initialize_records(size_t num_records, size_t string_size) {
    Record **records = (Record **) safe_malloc(num_records * sizeof(Record *));
    for (size_t i = 0; i < num_records; ++i) {
        records[i] = (Record *) safe_malloc(sizeof(Record));
        records[i]->value = rand();
        records[i]->name = (char *) safe_malloc(string_size);
        snprintf(records[i]->name, string_size, "Record %zu", i);
        records[i]->event_ref = NULL; // Will be set later
    }
    return records;
}

Event* allocate_and_initialize_events(size_t num_records) {
    Event *events = (Event *) safe_malloc(num_records * sizeof(Event));
    for (size_t i = 0; i < num_records; ++i) {
        events[i].timestamp = time(NULL);
        events[i].status_flag = rand() % 2;
    }
    return events;
}

