    pthread_mutex_init(&lock, NULL);

    long *offsets = allocate_and_initialize_offsets(num_records);
    int *keys = allocate_and_initialize_keys(min_key_val, max_key_val, num_records);
    Record **records1 = allocate_and_initialize_records(num_records, string_size);
    Record **records2 = allocate_and_initialize_records(num_records, string_size);
    Event *events = allocate_and_initialize_events(num_records);

    // Link records to events
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_records; ++i) {
        records1[i]->event_ref = &events[i];
        records2[i]->event_ref = &events[i];
    }
    pthread_mutex_unlock(&lock);

    // Simulate work
    printf("Data structures initialized.\n");

    // Cleanup
    pthread_mutex_destroy(&lock);
    free(offsets);
    free(keys);
    for (size_t i = 0; i < num_records; ++i) {
        free(records1[i]->name);
        free(records1[i]);
        free(records2[i]->name);
        free(records2[i]);
    }
    free(records1);
    free(records2);
    free(events);
}

