    Status status;
    LogEntry entry;

    while (fscanf(file, "%lf\n%f %f\n%d\n%ld %d %f %f\n", &value, &point.x, &point.y, &status,
                  &entry.timestamp, &entry.status, &entry.point.x, &entry.point.y) == 8) {
        pthread_mutex_lock(&manager->lock);

        manager->doubles = realloc(manager->doubles, (manager->num_doubles + 1) * sizeof(double));
        manager->doubles[manager->num_doubles++] = value;

        manager->points = realloc(manager->points, (manager->num_points + 1) * sizeof(Point));
        manager->points[manager->num_points++] = point;

        manager->statuses = realloc(manager->statuses, (manager->num_statuses + 1) * sizeof(Status));
        manager->statuses[manager->num_statuses++] = status;

        manager->log_entries = realloc(manager->log_entries, (manager->num_log_entries + 1) * sizeof(LogEntry));
        entry.point = point;
        manager->log_entries[manager->num_log_entries++] = entry;

        pthread_mutex_unlock(&manager->lock);
    }
}

void manage_memory(FILE *file) {
    MemoryManager manager;
    init_memory_manager(&manager);

    if (!file) return;

    char buffer[CHUNK_SIZE];
    while (fgets(buffer, CHUNK_SIZE, file)) {
        process_chunk(file, &manager);
    }

    free_memory_manager(&manager);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    manage_memory(file);
    fclose(file);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Management**: Uses `realloc` to dynamically adjust memory size.
- **Thread Safety**: Utilizes a mutex lock to ensure thread safety during concurrent access.
- **Chunk Processing**: Processes data in chunks to optimize performance and reduce memory usage.
- **Error Handling**: Checks for file opening errors and handles malformed entries gracefully.
- **Resource Cleanup**: Ensures all allocated memory is freed upon completion.']

