    time_t timestamp;
    size_t size;
} metadata;

// Global structures for storing data
char **string_storage = NULL;
record **records_storage = NULL;
category **categories_storage = NULL;
metadata **metadata_storage = NULL;

// Mutexes for thread safety
pthread_mutex_t string_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t record_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t category_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t metadata_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void *memory_manager(void *arg);
int parse_json_file(const char *file_path);

// Thread function to manage memory for a specific data structure
void *memory_manager(void *arg) {
    const char *json_data = (const char *)arg;
    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    size_t string_count = 0, record_count = 0, category_count = 0, metadata_count = 0;

    // Count the number of elements to allocate memory
    json_array_foreach(root, _, item) {
        const char *type = json_string_value(json_object_get(item, "type"));

        if (strcmp(type, "string") == 0) {
            string_count++;
        } else if (strcmp(type, "record") == 0) {
            record_count++;
        } else if (strcmp(type, "category") == 0) {
            category_count++;
        } else if (strcmp(type, "metadata") == 0) {
            metadata_count++;
        }
    }

    // Allocate memory for each data structure
    pthread_mutex_lock(&string_mutex);
    string_storage = realloc(string_storage, sizeof(char *) * string_count);
    pthread_mutex_unlock(&string_mutex);

    pthread_mutex_lock(&record_mutex);
    records_storage = realloc(records_storage, sizeof(record *) * record_count);
    pthread_mutex_unlock(&record_mutex);

    pthread_mutex_lock(&category_mutex);
    categories_storage = realloc(categories_storage, sizeof(category) * category_count);
    pthread_mutex_unlock(&category_mutex);

    pthread_mutex_lock(&metadata_mutex);
    metadata_storage = realloc(metadata_storage, sizeof(metadata *) * metadata_count);
    pthread_mutex_unlock(&metadata_mutex);

    // Parse and store data
    size_t i = 0;
    json_array_foreach(root, index, item) {
        const char *type = json_string_value(json_object_get(item, "type"));

        if (strcmp(type, "string") == 0) {
            pthread_mutex_lock(&string_mutex);
            string_storage[i] = strdup(json_string_value(json_object_get(item, "value")));
            pthread_mutex_unlock(&string_mutex);
            i++;
        } else if (strcmp(type, "record") == 0) {
            record *r = malloc(sizeof(record));
            r->id = json_integer_value(json_object_get(item, "id"));
            r->name = strdup(json_string_value(json_object_get(item, "name")));
            r->value = json_number_value(json_object_get(item, "value"));

            pthread_mutex_lock(&record_mutex);
            records_storage[i] = r;
            pthread_mutex_unlock(&record_mutex);
            i++;
        } else if (strcmp(type, "category") == 0) {
            category *c = malloc(sizeof(category));
            *c = json_integer_value(json_object_get(item, "value"));

            pthread_mutex_lock(&category_mutex);
            categories_storage[index] = *c;
            pthread_mutex_unlock(&category_mutex);
        } else if (strcmp(type, "metadata") == 0) {
            metadata *m = malloc(sizeof(metadata));
            m->timestamp = json_integer_value(json_object_get(item, "timestamp"));
            m->size = json_integer_value(json_object_get(item, "size"));

            pthread_mutex_lock(&metadata_mutex);
            metadata_storage[index] = m;
            pthread_mutex_unlock(&metadata_mutex);
        }
    }

    json_decref(root);
    return NULL;
}

// Function to parse JSON file and manage memory
int parse_json_file(const char *file_path) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long length = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *buffer = malloc(length + 1);
    if (!buffer) {
        fprintf(stderr, "Memory allocation error\n");
        fclose(fp);
        return -1;
    }

    fread(buffer, 1, length, fp);
    buffer[length] = '\0';
    fclose(fp);

    pthread_t thread_id;
    int result = pthread_create(&thread_id, NULL, memory_manager, (void *)buffer);
    if (result != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(result));
        free(buffer);
        return -1;
    }

    pthread_join(thread_id, NULL);
    free(buffer);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <json_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int result = parse_json_file(argv[1]);
    if (result != 0) {
        return EXIT_FAILURE;
    }

    // Clean up allocated memory
    for (size_t i = 0; string_storage && string_storage[i]; ++i) {
        free(string_storage[i]);
    }
    free(string_storage);

    for (size_t i = 0; records_storage && records_storage[i]; ++i) {
        free(records_storage[i]->name);
        free(records_storage[i]);
    }
    free(records_storage);

    free(categories_storage);
    for (size_t i = 0; metadata_storage && metadata_storage[i]; ++i) {
        free(metadata_storage[i]);
    }
    free(metadata_storage);

    return EXIT_SUCCESS;
}
```

This code provides a multi-threaded approach to parsing and managing memory for JSON data. It uses the `jansson` library for JSON parsing, which is efficient and well-suited for handling large files. The function ensures thread safety using mutexes and handles potential errors gracefully.']

