// Thread-safe queue operations
void enqueue_record(record_t *record) {
    pthread_mutex_lock(&mutex);

    queue_node_t *new_node = malloc(sizeof(queue_node_t));
    if (!new_node) return;

    new_node->record = record;
    new_node->next = NULL;

    if (tail) tail->next = new_node;
    else head = new_node;

    tail = new_node;

    pthread_mutex_unlock(&mutex);
}

record_t *dequeue_record() {
    pthread_mutex_lock(&mutex);

    if (!head) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    queue_node_t *old_head = head;
    record_t *record = old_head->record;
    head = head->next;

    if (!head) tail = NULL;

    free(old_head);
    pthread_mutex_unlock(&mutex);

    return record;
}

// Main function for testing
int main() {
    initialize_data_structures(100, 50, 42);

    // Simulate concurrent processing (example)
    enqueue_record((record_t *)malloc(sizeof(record_t)));
    dequeue_record();

    return 0;
}
