            return setting->value.intValue >= 0 && setting->value.intValue <= 100; // Example range
        case TYPE_STRING:
            return strlen(setting->value.stringValue) > 0; // Non-empty string
        case TYPE_BOOL:
            return true; // Always valid for bool
    }
    return false;
}

void freeSettings(Setting* settings, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (settings[i].type == TYPE_STRING && settings[i].value.stringValue) {
            free(settings[i].value.stringValue);
        }
        if (settings[i].description) {
            free((void*)settings[i].description);
        }
    }
    free(settings);
}

// Example usage
int main() {
    Setting* settings = NULL;
    size_t count = 10000;

    initializeSettings(&settings, count, validateSetting, NULL, 12345);

    // Use settings...

    freeSettings(settings, count);
    return 0;
}
