void initialize_data(int num_records, int key_range_min, int key_range_max,
                     const char **prefixes, const char **suffixes, size_t num_prefixes,
                     size_t num_suffixes, void (*callback)(record*, char*)) {

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free_data(offsets, keys, NULL, NULL, num_records);
        exit(ERROR_MEMORY_ALLOCATION);
    }

    record *records = malloc(num_records * sizeof(record));
    char **string_keys = malloc(num_records * sizeof(char*));

    if (!records || !string_keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free_data(offsets, keys, records, string_keys, num_records);
        exit(ERROR_MEMORY_ALLOCATION);
    }

    // Seed for random number generation
    unsigned long seed = 12345; // Example fixed seed for reproducibility

    // Initialize offsets and keys with sequential numbers starting from 0
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = (long)i;
        keys[i] = i;

        records[i].value = random_number_generate_thread_safe(&seed, key_range_min, key_range_max);

        // Generate string key with prefixes and suffixes
        char *key_str = generate_string_key(prefixes, suffixes, num_prefixes, num_suffixes, &seed);

        // Allocate memory for the record's components
        records[i].ptr_long = malloc(sizeof(long));
        if (!records[i].ptr_long) {
            fprintf(stderr, "Memory allocation failed\n");
            free_data(offsets, keys, records, string_keys, num_records);
            exit(ERROR_MEMORY_ALLOCATION);
        }

        *records[i].ptr_long = offsets[i];

        // Duplicate the key_str for persistent storage
        records[i].ptr_string_key = strdup(key_str);
        if (!records[i].ptr_string_key) {
            fprintf(stderr, "Memory allocation failed\n");
            free(records[i].ptr_long); // Clean up previously allocated memory
            free_data(offsets, keys, records, string_keys, num_records);
            exit(ERROR_MEMORY_ALLOCATION);
        }

        // Store the key_str pointer for cleanup
        string_keys[i] = key_str;

        // Execute callback function if provided
        if (callback) {
            pthread_mutex_lock(&mutex); // Ensure thread safety during callback execution
            callback(&records[i], records[i].ptr_string_key);
            pthread_mutex_unlock(&mutex);
        }
    }

    // Further logic to use the initialized data can be added here

    // Cleanup
    free_data(offsets, keys, records, string_keys, num_records);
}

int random_number_generate_thread_safe(void *seed_ptr, int min, int max) {
    unsigned long seed = *(unsigned long *)seed_ptr;

    // Using a simple thread-safe RNG example from an external library
    return (random_number_library_rng(seed) % (max - min + 1)) + min;
}

char* generate_string_key(const char **prefixes, const char **suffixes, size_t num_prefixes,
                          size_t num_suffixes, void *seed_ptr) {

    unsigned long seed = *(unsigned long *)seed_ptr;
    int random_index_prefix = random_number_generate_thread_safe(&seed, 0, num_prefixes - 1);
    int random_index_suffix = random_number_generate_thread_safe(&seed, 0, num_suffixes - 1);

    char *result = malloc(256); // Adjust size as needed for the combined key
    if (!result) {
        return NULL;
    }

    snprintf(result, 256, "%s%d%s", prefixes[random_index_prefix], 
             random_number_generate_thread_safe(&seed, 0, 9999), suffixes[random_index_suffix]);

    return result;
}
