        if (table->entries[i]) {
            free(table->entries[i]->point);
            free(table->entries[i]);
        }
    }
    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

circular_buffer* createCircularBuffer() {
    circular_buffer* buffer = malloc(sizeof(circular_buffer));
    if (!buffer) exit(EXIT_FAILURE);

    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void freeCircularBuffer(circular_buffer* buffer) {
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
