```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DEPTH 10

typedef enum { DIRECTORY, FILE } NodeType;

typedef struct Node {
    char *name;
    NodeType type;
    union {
        struct Directory* dir;
        char* data;
    };
    size_t capacity;
} Node;

typedef struct Directory {
    Node node;
    Node** children;
    size_t child_count;
    size_t max_children;
} Directory;

pthread_mutex_t fs_lock = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(char *name, NodeType type) {
    Node* n = malloc(sizeof(Node));
    if (!n) return NULL;

    n->name = strdup(name);
    n->type = type;
    n->capacity = 0;

    if (type == DIRECTORY) {
        Directory* d = malloc(sizeof(Directory));
        if (!d) { free(n); return NULL; }
        d->node = *n;
        d->children = NULL;
        d->child_count = 0;
        d->max_children = 10; // Initial capacity
        n->dir = d;
    } else {
        n->data = NULL;
    }

    return n;
}

Directory* create_root_directory(size_t initial_capacity) {
    Directory* root = malloc(sizeof(Directory));
    if (!root) return NULL;

    root->node = *(create_node("root", DIRECTORY));
    root->children = malloc(initial_capacity * sizeof(Node*));
    if (!root->children) { free(root); return NULL; }

    root->child_count = 0;
    root->max_children = initial_capacity;

    return root;
}

int add_child(Directory* dir, Node* child, size_t max_depth, int current_depth) {
    if (current_depth >= max_depth) return -1;

    pthread_mutex_lock(&fs_lock);

    if (dir->child_count == dir->max_children) {
        size_t new_capacity = dir->max_children * 2;
        Node** new_children = realloc(dir->children, new_capacity * sizeof(Node*));
        if (!new_children) { pthread_mutex_unlock(&fs_lock); return -1; }
        dir->children = new_children;
        dir->max_children = new_capacity;
    }

    for (size_t i = 0; i < dir->child_count; ++i) {
        if (strcmp(dir->children[i]->name, child->name) == 0) {
            pthread_mutex_unlock(&fs_lock);
            return -1; // Duplicate name
        }
    }

    dir->children[dir->child_count++] = child;
    pthread_mutex_unlock(&fs_lock);

    return 0;
}

void traverse_directory(Directory* dir, int (*callback)(Node*)) {
    for (size_t i = 0; i < dir->child_count; ++i) {
        Node* node = dir->children[i];
        if (callback(node) == 0 && node->type == DIRECTORY) {
            traverse_directory(node->dir, callback);
        }
    }
}

int rename_node(Directory* dir, char *old_name, char *new_name) {
    pthread_mutex_lock(&fs_lock);

    for (size_t i = 0; i < dir->child_count; ++i) {
        if (strcmp(dir->children[i]->name, old_name) == 0) {
            free(dir->children[i]->name);
            dir->children[i]->name = strdup(new_name);

            pthread_mutex_unlock(&fs_lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&fs_lock);
    return -1; // Not found
}

void free_fs(Node* node, int depth) {
    if (!node) return;

    if (node->type == DIRECTORY) {
        Directory* dir = node->dir;
        for (size_t i = 0; i < dir->child_count; ++i) {
            free_fs(dir->children[i], depth + 1);
        }
        free(dir->children);
        free(node->name);
        free(dir);
    } else {
        free(node->data);
        free(node->name);
    }

    free(node);
}

void* pause_operations(void* arg) {
    // Implement a thread-safe pause/resume mechanism
    return NULL;
}

int main() {
    Directory* root = create_root_directory(10);

    if (!root) {
        fprintf(stderr, "Failed to initialize file system.\n");
        return 1;
    }

    Node* file1 = create_node("file1.txt", FILE);
    Node* dir1 = create_node("dir1", DIRECTORY);

    add_child(root->node.dir, file1, MAX_DEPTH, 0);
    add_child(root->node.dir, dir1, MAX_DEPTH, 0);

    traverse_directory(root->node.dir, [](Node* node) -> int {
        printf("%s\n", node->name);
        return 1;
    });

    rename_node(root->node.dir, "file1.txt", "renamed_file1.txt");

    free_fs(&root->node, 0);

    pthread_mutex_destroy(&fs_lock);
    return 0;
}
```

