#define MAX_RECORDS 10000000
#define HASH_TABLE_SIZE 100003 // A prime number close to sqrt(MAX_RECORDS)

// Function prototypes
long hash_function(int key);
void initialize_data_structures(long **offsets, int *keys, Record **records1, Record **records2, int **metadata, HashTable **hash_table);
void populate_arrays(long *offsets, int *keys, Record *records1, Record *records2, size_t record_count);
void free_resources(HashTable *hash_table, long *offsets, int *keys, Record *records1, Record *records2, int *metadata);

long hash_function(int key) {
    return (key % HASH_TABLE_SIZE);
}

void initialize_data_structures(long **offsets, int *keys, Record **records1, Record **records2, int **metadata, HashTable **hash_table) {
    size_t record_count = MAX_RECORDS;

    // Allocate memory
    *offsets = calloc(record_count, sizeof(long));
    *keys = calloc(record_count, sizeof(int));
    *records1 = calloc(record_count, sizeof(Record));
    *records2 = calloc(record_count, sizeof(Record));
    *metadata = calloc(record_count, sizeof(int));

    // Initialize hash table
    *hash_table = (HashTable*)malloc(sizeof(HashTable));
    (*hash_table)->buckets = calloc(HASH_TABLE_SIZE, sizeof(Node*));
    (*hash_table)->bucket_count = HASH_TABLE_SIZE;
    pthread_mutex_init(&(*hash_table)->lock, NULL);

    populate_arrays(*offsets, *keys, *records1, *records2, record_count);
}

void populate_arrays(long *offsets, int *keys, Record *records1, Record *records2, size_t record_count) {
    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        offsets[i] = rand() % 1000000;
        do {
            keys[i] = rand();
        } while (keys[i] == 0); // Ensure non-zero keys

        records1[i].value = rand() % 10000;
        records2[i].value = rand() % 10000;

        records1[i].offset_ptr = &offsets[i];
        records2[i].offset_ptr = &offsets[i];

        records1[i].key_ptr = &keys[i];
        records2[i].key_ptr = &keys[i];

        int metadata_index = rand() % record_count;
        records1[i].metadata_ptr = &((*(int**)records1)[metadata_index]);
        records2[i].metadata_ptr = &((*(int**)records2)[metadata_index]);

        // Initialize reference count
        records1[i].ref_count = 0;
        records2[i].ref_count = 0;

        long hash_index = hash_function(keys[i]);
        pthread_mutex_lock(&hash_table->lock);
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->key = keys[i];
        new_node->record = records1[i]; // Assume we insert the first record
        new_node->next = hash_table->buckets[hash_index];
        hash_table->buckets[hash_index] = new_node;
        pthread_mutex_unlock(&hash_table->lock);
    }
}

void free_resources(HashTable *hash_table, long *offsets, int *keys, Record *records1, Record *records2, int *metadata) {
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* current = hash_table->buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(hash_table->buckets);
    pthread_mutex_destroy(&hash_table->lock);
    free(hash_table);

    free(offsets);
    free(keys);
    free(records1);
    free(records2);
    free(metadata);
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    Record *records1 = NULL, *records2 = NULL;
    int *metadata = NULL;
    HashTable *hash_table = NULL;

    initialize_data_structures(&offsets, &keys, &records1, &records2, &metadata, &hash_table);

    // Simulate operations...

    free_resources(hash_table, offsets, keys, records1, records2, metadata);

    return 0;
}
