#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct Record {
    int integer;
    long *long_ptr;
    int *int_ptr;
} Record;

typedef struct Node {
    uint64_t key;
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

typedef struct MemoryPool {
    void* base;
    size_t total_size;
    size_t block_size;
    void* current_pos;
    pthread_mutex_t lock;
} MemoryPool;

// Custom hash function
uint64_t custom_hash(uint64_t key, size_t capacity) {
    return (key * 0x9e3779b97f4a7c15ULL) >> (64 - (sizeof(size_t) * 8)) % capacity;
}

// Initialize memory pool
void* init_memory_pool(size_t total_size, size_t block_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->base = malloc(total_size);
    pool->total_size = total_size;
    pool->block_size = block_size;
    pool->current_pos = pool->base;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Allocate memory from pool
void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_pos + pool->block_size > pool->base + pool->total_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Out of memory
    }
    void* block = pool->current_pos;
    memset(block, 0, pool->block_size);
    pool->current_pos += pool->block_size;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Initialize hash table
HashTable* init_hash_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(capacity, sizeof(Node*));
    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Insert record into hash table
int insert_record(HashTable* table, uint64_t key, Record record) {
    size_t index = custom_hash(key, table->capacity);
    Node* node = malloc(sizeof(Node));
    if (!node) return -1; // Memory allocation failure

    node->key = key;
    node->record = record;
    node->next = NULL;

    pthread_mutex_lock(&table->lock);
    Node** current = &table->buckets[index];
    while (*current) {
        if ((*current)->key == key) {
            free(node); // Key already exists
            pthread_mutex_unlock(&table->lock);
            return -1;
        }
        current = &(*current)->next;
    }
    *current = node;
    pthread_mutex_unlock(&table->lock);

    return 0; // Success
}

// Update record in hash table
int update_record(HashTable* table, uint64_t key, int new_value) {
    size_t index = custom_hash(key, table->capacity);
    pthread_mutex_lock(&table->lock);
    Node* current = table->buckets[index];
    while (current) {
        if (current->key == key) {
            current->record.integer = new_value;
            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return -1; // Record not found
}

// Serialize hash table to file
int serialize_hash_table(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            fwrite(&node->key, sizeof(node->key), 1, file);
            fwrite(&node->record.integer, sizeof(node->record.integer), 1, file);
            long value;
            if (node->record.long_ptr) value = *node->record.long_ptr;
            else value = 0;
            fwrite(&value, sizeof(value), 1, file);
            int value_int;
            if (node->record.int_ptr) value_int = *node->record.int_ptr;
            else value_int = 0;
            fwrite(&value_int, sizeof(value_int), 1, file);
            node = node->next;
        }
    }
    pthread_mutex_unlock(&table->lock);

    fclose(file);
    return 0; // Success
}

// Deserialize hash table from file
int deserialize_hash_table(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    uint64_t key;
    Record record;
    long value_long;
    int value_int;

    pthread_mutex_lock(&table->lock);
    while (fread(&key, sizeof(key), 1, file)) {
        fread(&record.integer, sizeof(record.integer), 1, file);
        fread(&value_long, sizeof(value_long), 1, file);
        long* long_ptr = allocate_from_pool(table); // Assuming a pool is passed
        if (!long_ptr) {
            pthread_mutex_unlock(&table->lock);
            fclose(file);
            return -1; // Memory allocation failure
        }
        *long_ptr = value_long;
        record.long_ptr = long_ptr;

        fread(&value_int, sizeof(value_int), 1, file);
        int* int_ptr = allocate_from_pool(table); // Assuming a pool is passed
        if (!int_ptr) {
            free(long_ptr);
            pthread_mutex_unlock(&table->lock);
            fclose(file);
            return -1; // Memory allocation failure
        }
        *int_ptr = value_int;
        record.int_ptr = int_ptr;

        insert_record(table, key, record);
    }
    pthread_mutex_unlock(&table->lock);

    fclose(file);
    return 0; // Success
}

// Free memory pool and hash table
void free_memory_pool(MemoryPool* pool) {
    free(pool->base);
    free(pool);
}

void free_hash_table(HashTable* table) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp->record.long_ptr);
            free(temp->record.int_ptr);
            free(temp);
        }
    }
    pthread_mutex_unlock(&table->lock);
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
