// Assuming secure random number generation library is included
extern int secure_random_int(int min, int max);

typedef struct {
    int value;
    char *key;
    long *ptr;
} record;

typedef struct {
    int weight;
    int type;
} edge;

void free_resources(long *offsets, int *keys, record *records, int records_count, 
                    edge *edges, int edges_count, int *input_numbers, int input_size) {
    for (int i = 0; i < records_count; ++i) {
        if (records[i].key) free(records[i].key);
        if (records[i].ptr) free(records[i].ptr);
    }
    free(offsets);
    free(keys);
    free(records);
    free(edges);
    free(input_numbers);
