void *processGraphAndFindMax(void *args) {
    struct {
        int offset_size;
        int key_size;
        int min_records, max_records;
        int min_edges, max_edges;
        void (*callback)(record *, edge *);
    } *params = (struct { ...; }) args;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = malloc(params->offset_size * sizeof(long));
    int *keys = malloc(params->key_size * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed\n");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (int i = 0; i < params->offset_size; ++i) offsets[i] = i;
    for (int i = 0; i < params->key_size; ++i) keys[i] = i;

    int records_count = secure_random_int(params->min_records, params->max_records);
    record *records = malloc(records_count * sizeof(record));

    if (!records) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    int edges_count = secure_random_int(params->min_edges, params->max_edges);
    edge *edges = malloc(edges_count * sizeof(edge));

    if (!edges) {
        printf("Memory allocation failed\n");
        free(records);
        free(offsets);
        free(keys);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (int i = 0; i < records_count; ++i) {
        pthread_mutex_lock(&lock);

        records[i].value = secure_random_int(1, 100); // Example range
        size_t key_length = strlen("key") + 1;
        records[i].key = malloc(key_length);
        snprintf(records[i].key, key_length, "key_%d", i);

        records[i].ptr = malloc(sizeof(long));
        if (!records[i].ptr) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&lock);
            free_resources(offsets, keys, records, records_count, edges, edges_count, NULL, 0);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
        *(records[i].ptr) = secure_random_int(1, 100); // Example range

        if (params->callback) params->callback(&records[i], NULL);

        pthread_mutex_unlock(&lock);
    }

    for (int i = 0; i < edges_count; ++i) {
        pthread_mutex_lock(&lock);

        edges[i].weight = secure_random_int(1, 50); // Example range
        edges[i].type = secure_random_int(1, 10);   // Example range

        if (params->callback) params->callback(NULL, &edges[i]);

        pthread_mutex_unlock(&lock);
    }

    int input_size = 0;
    int *input_numbers = NULL;

    while (1) {
        int num;
        if (!scanf("%d", &num) || num == -1) break;

        input_numbers = realloc(input_numbers, (input_size + 1) * sizeof(int));
        if (!input_numbers) {
            printf("Memory allocation failed\n");
            free_resources(offsets, keys, records, records_count, edges, edges_count, NULL, 0);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
        input_numbers[input_size++] = num;
    }

    // Example: Print numbers
    for (int i = 0; i < input_size; ++i) {
        printf("%d\n", input_numbers[i]);
    }

    free_resources(offsets, keys, records, records_count, edges, edges_count, input_numbers, input_size);
    pthread_mutex_destroy(&lock);

    return NULL;
}
