#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1000

typedef struct {
    int value;
    int key;
    long offset;
} Record;

void handle_invalid_input() {
    fprintf(stderr, "Invalid input: Please ensure the size is a positive integer within limits.\n");
    exit(EXIT_FAILURE);
}

long weighted_random_int(double* weights, double total_weight) {
    double r = ((double)rand() / RAND_MAX) * total_weight;
    for (int i = 0; i < sizeof(weights)/sizeof(weights[0]); ++i) {
        if (r <= weights[i]) return i + 1;
        r -= weights[i];
    }
    return -1; // Should not happen
}

void manage_memory_allocation_and_initialization(int size, int offset_sum_limit) {
    if (size < 1 || size > MAX_ARRAY_SIZE) handle_invalid_input();

    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    Record *records = malloc(size * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation for records failed.\n");
        exit(EXIT_FAILURE);
    }

    double weights[] = {0.1, 0.2, 0.3, 0.4}; // Example weights
    double total_weight = 1.0;

    long offset_sum = 0;
    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % 1000; // Random key generation
        offsets[i] = (rand() % 10) + 1; // Random offset generation

        if ((offset_sum += offsets[i]) > offset_sum_limit) {
            fprintf(stderr, "Offset sum limit exceeded.\n");
            free(offsets);
            free(keys);
            free(records);
            exit(EXIT_FAILURE);
        }

        records[i].value = weighted_random_int(weights, total_weight);
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Example access pattern for data locality
    for (int i = 0; i < size; ++i) {
        printf("Record %d: Value=%d, Key=%d, Offset=%ld\n", i + 1, 
               records[i].value, records[i].key, records[i].offset);
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int user_size = 500; // Example size input from user
    int offset_sum_limit = 1000; // Configurable limit

    manage_memory_allocation_and_initialization(user_size, offset_sum_limit);

    return 0;
}
