        entries[i].length = (*message_lengths)[i];
        entries[i].timestamp = time(NULL); // Use system time as example
        entries[i].unique_id = rand();     // Random unique ID for demonstration

        total_size += entries[i].length;
    }

    // Step 4: Validate Bandwidth Limit
    if (total_size > MAX_BANDWIDTH) {
        fprintf(stderr, "Total message size exceeds bandwidth limit.\n");
        return NULL;
    }

    // Step 5 and 6 are beyond basic memory management. They involve higher-level design strategies.

    // Cleanup Mechanism - Ensure allocated resources are freed properly
    if (entries == NULL) { 
        for (size_t i = 0; i < total_messages; ++i) {
            free((*message_contents)[i]);
        }
        free(*message_lengths);
        free(*message_contents);
    }

    return entries;
}

