typedef struct MemoryPool {
    size_t size;
    void *memory;
    size_t offset;
} MemoryPool;

void initializeMemoryPool(MemoryPool *pool, size_t size) {
    pool->size = size;
    pool->memory = malloc(size);
    pool->offset = 0;
}

bool allocateFromPool(MemoryPool *pool, size_t size, void **ptr) {
    if (pool->offset + size > pool->size)
        return false;

    *ptr = (char*)pool->memory + pool->offset;
    pool->offset += size;
    return true;
}

void freeMemoryPool(MemoryPool *pool) {
    free(pool->memory);
    pool->memory = NULL;
}

