        metadatas[i].last_modified = current_time;
        metadatas[i].active_status = 1;

        log_lifecycle_event("Created", &records[i]);
    }

    // Periodically clean up inactive records
    cleanup_inactive_records(records, metadatas, size, max_age_seconds);

