int initialize_data_structure(size_t offset_size, size_t key_size, size_t record_size, 
                              int min_rand_value, int max_rand_value, unsigned long seed, 
                              void (*callback)(Record*), const char *config_file) {
    if (offset_size <= 0 || key_size <= 0 || record_size <= 0) return -1;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t metadata_size = record_size; // Assume same size for simplicity

    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));
    Record* records = malloc(record_size * sizeof(Record));
    time_t* timestamps = malloc(record_size * sizeof(time_t));
    char** metadata = malloc(metadata_size * sizeof(char*));

    if (!offsets || !keys || !records || !timestamps || !metadata) {
        handle_error("Memory allocation failed");
        free(offsets); offsets = NULL;
        free(keys); keys = NULL;
        free(records); records = NULL;
        free(timestamps); timestamps = NULL;
        for (size_t i = 0; i < metadata_size && metadata[i]; ++i) {
            free(metadata[i]);
        }
        free(metadata);
        return -1;
    }

    srand(seed); // Initialize random number generator
    secure_rng_init(seed);

    for (size_t i = 0; i < offset_size; ++i) offsets[i] = i;
    for (size_t i = 0; i < key_size; ++i) keys[i] = i;

    char cache[512];
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = secure_rng_range(min_rand_value, max_rand_value);
        snprintf(records[i].string_key, sizeof(records[i].string_key), "key_%zu", i);
        records[i].dynamic_pointer = malloc(sizeof(long));
        if (!records[i].dynamic_pointer) {
            handle_error("Memory allocation failed for dynamic_pointer");
            free(records[i].dynamic_pointer); // Safeguard
            continue;
        }
        *records[i].dynamic_pointer = 0;  // Initialize to zero

        timestamps[i] = time(NULL);
        snprintf(cache, sizeof(cache), "metadata_%zu", i);
        metadata[i] = strdup(cache);

        if (callback) callback(&records[i]);

        pthread_mutex_lock(&mutex);
        printf("Record %zu initialized with value: %d\n", i, records[i].value);
        pthread_mutex_unlock(&mutex);
    }

    // Deferred cleanup mechanism (stub)
    void deferred_cleanup() {
        free(offsets); offsets = NULL;
        free(keys); keys = NULL;
        for (size_t i = 0; i < record_size; ++i) {
            if (records[i].dynamic_pointer) {
                free(records[i].dynamic_pointer);
                records[i].dynamic_pointer = NULL;
            }
        }
        free(records); records = NULL;
        free(timestamps); timestamps = NULL;
        for (size_t i = 0; i < metadata_size; ++i) {
            if (metadata[i]) {
                free(metadata[i]);
                metadata[i] = NULL;
            }
        }
        free(metadata);
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}

