typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    long* offsets;
    int* keys;
    record** records;
    metadata** metadatas;
    int* status_flags;
} dynamic_collection;

#define MAX_AGE 3600 // seconds

void set_seed(unsigned int seed) {
    srand(seed);
}

long secure_random_long(long min, long max) {
    return rand() % (max - min + 1) + min;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

dynamic_collection* init_dynamic_collection(size_t size, unsigned int seed, void (*callback)(record*)) {
    dynamic_collection* dc = malloc(sizeof(dynamic_collection));
    if (!dc) {
        log_error("Failed to allocate memory for collection");
        return NULL;
    }

    pthread_mutex_init(&dc->lock, NULL);
    dc->count = 0;
    dc->capacity = size;

    // Allocate arrays
    dc->offsets = malloc(size * sizeof(long));
    dc->keys = malloc(size * sizeof(int));
    dc->records = malloc(size * sizeof(record*));
    dc->metadatas = malloc(size * sizeof(metadata*));
    dc->status_flags = malloc(size * sizeof(int));

    if (!dc->offsets || !dc->keys || !dc->records || !dc->metadatas || !dc->status_flags) {
        log_error("Memory allocation failed for arrays");
        free(dc);
        return NULL;
    }

    // Initialize seed
    set_seed(seed);

    // Populate offsets and keys
    for (size_t i = 0; i < size; ++i) {
        dc->offsets[i] = i;
        dc->keys[i] = i;

        // Allocate and initialize records
        record* rec = malloc(sizeof(record));
        if (!rec) {
            log_error("Failed to allocate memory for record");
            return NULL;
        }
        rec->value = secure_random_long(1, 100);
        rec->key = strdup("example_key"); // Replace with actual key logic
        rec->data_ptr = NULL; // Initialize data pointer as needed
        rec->ref_count = 0;

        metadata* meta = malloc(sizeof(metadata));
        if (!meta) {
            log_error("Failed to allocate memory for metadata");
            free(rec);
            return NULL;
        }
        time(&meta->created_at);
        meta->updated_at = meta->created_at;
        meta->active_status = 1; // Initially active
        meta->version_number = 1;

        dc->records[i] = rec;
        dc->metadatas[i] = meta;
        dc->status_flags[i] = 0; // Not being processed

        if (callback) {
            callback(rec);
        }
    }

    return dc;
}

void cleanup_inactive_records(dynamic_collection* dc, time_t now) {
    pthread_mutex_lock(&dc->lock);

    for (size_t i = 0; i < dc->count; ++i) {
        if (difftime(now, dc->metadatas[i]->updated_at) > MAX_AGE && dc->metadatas[i]->active_status == 1) {
            dc->metadatas[i]->active_status = 0;
            free(dc->records[i]);
            free(dc->metadatas[i]);
        }
    }

    pthread_mutex_unlock(&dc->lock);
}

void destroy_dynamic_collection(dynamic_collection* dc) {
    if (!dc) return;

    pthread_mutex_lock(&dc->lock);

    for (size_t i = 0; i < dc->count; ++i) {
        free(dc->records[i]->key);
        free(dc->records[i]);
        free(dc->metadatas[i]);
    }

    free(dc->offsets);
    free(dc->keys);
    free(dc->records);
    free(dc->metadatas);
    free(dc->status_flags);

    pthread_mutex_unlock(&dc->lock);
    pthread_mutex_destroy(&dc->lock);
    free(dc);
}

void example_callback(record* rec) {
    // Example processing logic
    printf("Processing record with value: %d\n", rec->value);
}
