        // Process events...

        if (/* termination condition */) break;
    }

    for (int i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }
}

// File format detection function
FileFormat detect_file_format(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) handle_error("Failed to open file");

    // Check the first few bytes for format signatures
    char signature[5];
    fread(signature, 1, sizeof(signature), file);

    if (strncmp(signature, "{", 1) == 0) {
        fclose(file);
        return JSON;
    } else if (signature[0] == ',' || signature[0] == ' ') {
        fseek(file, 0, SEEK_SET); // Reset for CSV check
        char line[MAX_LINE_LENGTH];
        fgets(line, sizeof(line), file);
        if (strchr(line, ',') != NULL) {
            fclose(file);
            return CSV;
        }
    } else {
        fclose(file);
        return BINARY; // Assume binary otherwise
    }

    handle_error("Unknown file format");
    return JSON; // Default fallback
}

// Logging function
void log_message(const char* message) {
    printf("[LOG] %s\n", message);
}

// Error handling
void handle_error(const char* error_msg) {
    fprintf(stderr, "Error: %s\n", error_msg);
    exit(EXIT_FAILURE);
}

// Dynamic resizing functions
Resource** resize_resources(Resource** resources, size_t* capacity, size_t new_capacity) {
    Resource** resized = realloc(resources, new_capacity * sizeof(Resource*));
    if (!resized) handle_error("Memory allocation failed for resources");

    *capacity = new_capacity;
    return resized;
}

DataChunk** resize_chunks(DataChunk** chunks, size_t* capacity, size_t new_capacity) {
    DataChunk** resized = realloc(chunks, new_capacity * sizeof(DataChunk*));
    if (!resized) handle_error("Memory allocation failed for data chunks");

    *capacity = new_capacity;
    return resized;
}

// Cache management
Cache* initialize_cache(size_t initial_capacity) {
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) handle_error("Failed to allocate memory for cache");

    cache->resources = malloc(initial_capacity * sizeof(Resource*));
    if (!cache->resources) {
        free(cache);
        handle_error("Memory allocation failed for resource array");
    }

    cache->capacity = initial_capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void cache_resource(Cache* cache, Resource* resource) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count == cache->capacity) {
        cache->resources = resize_resources(cache->resources, &cache->capacity, cache->capacity * 2);
    }

    for (size_t i = 0; i < cache->count; ++i) {
        if (cache->resources[i]->unique_id == resource->unique_id) {
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }

    cache->resources[cache->count++] = resource;
    pthread_mutex_unlock(&cache->lock);
}

Resource* get_cached_resource(Cache* cache, int unique_id) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->count; ++i) {
        if (cache->resources[i]->unique_id == unique_id) {
            Resource* resource = cache->resources[i];
            pthread_mutex_unlock(&cache->lock);
            return resource;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void evict_cache(Cache* cache) {
    // Implement a simple eviction policy, e.g., FIFO or LRU
    pthread_mutex_lock(&cache->lock);

    if (cache->count > 0) {
        free(cache->resources[0]);
        memmove(cache->resources, &cache->resources[1], (cache->count - 1) * sizeof(Resource*));
        cache->count--;
    }

    pthread_mutex_unlock(&cache->lock);
}

// Event processing function
void* process_event(void* arg) {
    EventSource* source = (EventSource*)arg;
    DataChunk chunk;

    // Ingest and validate event...

    sem_post(&event_semaphore);

    return NULL;
}
