            nodes[i].data->items[j]->index = rand() % 100;
            nodes[i].data->items[j]->value = (Value*)malloc(sizeof(Value));
            nodes[i].data->items[j]->value->number = ((double)rand() / RAND_MAX) * 100.0;
            snprintf(nodes[i].data->items[j]->value->str, sizeof(nodes[i].data->items[j]->value->str), "value_%d", j);
        }
    }

    // Initialize offset and key arrays
    size_t offsetSize = numNodes;
    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    int* keys = (int*)malloc(recordSize * sizeof(int));

    for (size_t i = 0; i < offsetSize; ++i) {
        offsets[i] = i;
    }

    for (size_t i = 0; i < recordSize; ++i) {
        keys[i] = rand() % 100;
    }

    // Initialize records
    Record* records = (Record*)malloc(recordSize * sizeof(Record));
    size_t numRecords = rand() % (maxNumRecords - minNumRecords + 1) + minNumRecords;

    for (size_t i = 0; i < numRecords && i < recordSize; ++i) {
        records[i].valuePtr = (long*)malloc(sizeof(long));
        *records[i].valuePtr = rand() % 100;
    }

    // Initialize vertices
    Vertex* vertices = (Vertex*)malloc(vertexSize * sizeof(Vertex));
    size_t numVertices = rand() % (maxNumVertices - minNumVertices + 1) + minNumVertices;

    for (size_t i = 0; i < numVertices && i < vertexSize; ++i) {
        vertices[i].id = i;
        vertices[i].degree = rand() % 10; // Random degree between 0 and 9
        vertices[i].neighbors = (int*)malloc(vertices[i].degree * sizeof(int));
        for (int j = 0; j < vertices[i].degree; ++j) {
            vertices[i].neighbors[j] = rand() % numVertices;
        }
        vertices[i].neighborCount = vertices[i].degree;
    }

    // Initialize edges
    size_t edgeSize = 2 * numVertices; // Arbitrary number of edges, can be adjusted as needed
    Edge* edges = (Edge*)malloc(edgeSize * sizeof(Edge));
    for (size_t i = 0; i < edgeSize && i < vertexSize * 2; ++i) {
        edges[i].fromVertex = rand() % numVertices;
        edges[i].toVertex = rand() % numVertices;
        edges[i].weight = ((double)rand() / RAND_MAX) * 10.0;
