    while (scanf("%d", &intArray[numIntegers]) == 1) {
        ++numIntegers;

        // Resize the array if necessary
        if (numIntegers >= intArraySize) {
            intArraySize *= 2;
            intArray = (int*)realloc(intArray, intArraySize * sizeof(int));
