    findAndPrintLargestInteger(intArray, numIntegers);

    // Free allocated memory
    for (size_t i = 0; i < numNodes; ++i) {
        for (int j = 0; j < nodes[i].data->numItems; ++j) {
            free(nodes[i].data->items[j]->value);
            free(nodes[i].data->items[j]);
        }
        free(nodes[i].data->items);
        free(nodes[i].data);
    }

    free(nodes);

    free(offsets);
    free(keys);

    for (size_t i = 0; i < numRecords && i < recordSize; ++i) {
        free(records[i].valuePtr);
    }
    free(records);

    for (size_t i = 0; i < numVertices && i < vertexSize; ++i) {
        free(vertices[i].neighbors);
    }
    free(vertices);

    free(edges);
    free(intArray);
}
