} LogEntriesArray;

void parseAndProcessLogFiles(const char *log_directory, LogCallback custom_callback) {
    // Step 1: Initialize metadata array
    LogFileInfo *metadata_array = NULL;
    size_t metadata_count = 0;
    pthread_mutex_t metadata_lock = PTHREAD_MUTEX_INITIALIZER;

    // Simulate fetching log files from a directory
    const char *log_files[] = {"log1.txt", "log2.txt"};
    size_t num_logs = sizeof(log_files) / sizeof(log_files[0]);

    for (size_t i = 0; i < num_logs; ++i) {
        pthread_mutex_lock(&metadata_lock);

        // Check if metadata already exists
        int found = 0;
        for (size_t j = 0; j < metadata_count; ++j) {
            if (strcmp(metadata_array[j].file_path, log_files[i]) == 0) {
                found = 1;
                break;
            }
        }

        if (!found) {
            // Update metadata array
            LogFileInfo *new_metadata_array = realloc(metadata_array, sizeof(LogFileInfo) * (metadata_count + 1));
            if (!new_metadata_array) {
                perror("Failed to allocate memory for metadata");
                continue;
            }
            metadata_array = new_metadata_array;

            metadata_array[metadata_count].file_path = strdup(log_files[i]);
            get_file_metadata(log_files[i], &metadata_array[metadata_count].last_modified, &metadata_array[metadata_count].file_size);
            ++metadata_count;
        }

        pthread_mutex_unlock(&metadata_lock);
    }

    // Step 2: Allocate memory for log entries array
    LogEntriesArray log_entries = {NULL, 0, 10};
    pthread_mutex_init(&log_entries.lock, NULL);

    // Step 3: Implement error handling and file I/O
    for (size_t i = 0; i < num_logs; ++i) {
        FILE *file = fopen(log_files[i], "r");
        if (!file) {
            perror("Failed to open log file");
            continue;
        }

        char line[512];
        while (fgets(line, sizeof(line), file)) {
            pthread_mutex_lock(&log_entries.lock);

            // Resize array if necessary
            if (log_entries.count >= log_entries.capacity) {
                size_t new_capacity = log_entries.capacity * 2;
                LogEntry **new_entries_array = realloc(log_entries.entries, sizeof(LogEntry *) * new_capacity);
                if (!new_entries_array) {
                    perror("Failed to allocate memory for log entries");
                    pthread_mutex_unlock(&log_entries.lock);
                    continue;
                }
                log_entries.entries = new_entries_array;
                log_entries.capacity = new_capacity;
            }

            // Parse log entry
            LogEntry *entry = malloc(sizeof(LogEntry));
            if (!entry) {
                perror("Failed to allocate memory for log entry");
                pthread_mutex_unlock(&log_entries.lock);
                continue;
            }
            sscanf(line, "%lu %[^\n] %15s", &entry->timestamp, entry->message, entry->category);

            // Step 4: Execute custom callback
            if (custom_callback) {
                custom_callback(entry);
            }

            log_entries.entries[log_entries.count++] = entry;
            pthread_mutex_unlock(&log_entries.lock);
        }
        fclose(file);
    }

    // Step 9: Detect anomalies
    for (size_t i = 0; i < log_entries.count; ++i) {
        LogEntry *entry = log_entries.entries[i];
        if (strcmp(entry->category, "ERROR") == 0) {
            printf("Anomaly detected: %s\n", entry->message);
        }
    }

    // Step 10: Free allocated memory
    for (size_t i = 0; i < log_entries.count; ++i) {
        free(log_entries.entries[i]);
    }
    free(log_entries.entries);

    for (size_t i = 0; i < metadata_count; ++i) {
        free(metadata_array[i].file_path);
    }
    free(metadata_array);

    pthread_mutex_destroy(&metadata_lock);
    pthread_mutex_destroy(&log_entries.lock);
}

// Example custom callback function
void exampleCallback(LogEntry *entry) {
    printf("Processing entry: %s\n", entry->message);
}

int main() {
    parseAndProcessLogFiles("/path/to/logs", exampleCallback);
    return 0;
}
