int processRecordsAndFindMax(size_t offset_size, size_t key_size, size_t record_size,
                             long int random_min, long int random_max,
                             void (*callback)(record *), pthread_mutex_t *lock) {

    if (!lock || !*lock) return -1;

    long *offsets = (long *)malloc(offset_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return -1;
    }

    int *keys = (int *)malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return -1;
    }

    record *records = (record *)malloc(record_size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -1;
    }

    for (size_t i = 0; i < offset_size; ++i) offsets[i] = (long)i;
    for (size_t i = 0; i < key_size; ++i) keys[i] = (int)i;

    pthread_mutex_lock(lock);
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = secure_random_long(random_min, random_max);
        snprintf(records[i].key, sizeof(records[i].key), "Key-%zu", i);
        records[i].offset_ptr = malloc(sizeof(long));
        if (!records[i].offset_ptr) {
            fprintf(stderr, "Memory allocation failed for record offset pointer.\n");
            freeRecords(records, i); // Free only allocated part.
            pthread_mutex_unlock(lock);
            return -1;
        }
        *records[i].offset_ptr = offsets[i % offset_size]; // Example reuse.

        if (callback) callback(&records[i]);
    }
    pthread_mutex_unlock(lock);

    int *input_numbers = NULL;
    size_t input_count = 0, capacity = 10;
    input_numbers = malloc(capacity * sizeof(int));
    if (!input_numbers) {
        freeRecords(records, record_size);
        fprintf(stderr, "Memory allocation failed for input numbers.\n");
        return -1;
    }

    int number;
    while (scanf("%d", &number) && number != -1) {
        if (input_count >= capacity) {
            capacity *= 2;
            input_numbers = realloc(input_numbers, capacity * sizeof(int));
            if (!input_numbers) {
                freeRecords(records, record_size);
                fprintf(stderr, "Memory reallocation failed for input numbers.\n");
                return -1;
            }
        }
        input_numbers[input_count++] = number;
    }

    findMax(input_numbers, input_count);

    freeRecords(records, record_size);
    free(keys);
    free(offsets);
    free(input_numbers);

    return 0;
}

int main() {
    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed.\n");
        return -1;
    }

    processRecordsAndFindMax(100, 50, 10, 0, 100, NULL, &lock);
    pthread_mutex_destroy(&lock);

    return 0;
}
