import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.HashMap;
import java.util.Random;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.Consumer;

public class TrafficAnalyzer {

    private static final int MAX_PACKET_SIZE = 1500; // Example max packet size
    private long[] timestamp;
    private int[] packetLength;
    private String[] protocolIdentifier;
    private ByteBuffer[] packetData;
    private ConcurrentLinkedQueue<ByteBuffer> incomingPackets = new ConcurrentLinkedQueue<>();
    private Random random;

    public TrafficAnalyzer(int arraySize, long seed) {
        this.timestamp = new long[arraySize];
        this.packetLength = new int[arraySize];
        this.protocolIdentifier = new String[arraySize];
        this.packetData = new ByteBuffer[arraySize];
        this.random = new Random(seed);

        initializeArrays();
    }

    private void initializeArrays() {
        for (int i = 0; i < timestamp.length; i++) {
            timestamp[i] = System.currentTimeMillis(); // Example timestamp
            packetLength[i] = random.nextInt(MAX_PACKET_SIZE) + 1;
            protocolIdentifier[i] = "HTTP"; // Example protocol
            ByteBuffer buffer = ByteBuffer.allocate(packetLength[i]);
            random.nextBytes(buffer.array());
            packetData[i] = buffer;
        }
    }

    public void processStreamingDataAndAnalyzeTraffic(String host, int port, Consumer<ByteBuffer> callback) {
        try (AsynchronousServerSocketChannel serverChannel = AsynchronousServerSocketChannel.open()) {
            serverChannel.bind(new InetSocketAddress(host, port));
            System.out.println("Server started on " + host + ":" + port);

            while (true) {
                serverChannel.accept(serverChannel, new CompletionHandler<>() {
                    @Override
                    public void completed(AsynchronousSocketChannel clientChannel, Object attachment) {
                        receiveData(clientChannel);
                        serverChannel.accept(serverChannel, this); // Accept next connection
                    }

                    @Override
                    public void failed(Throwable exc, Object attachment) {
                        System.err.println("Failed to accept a connection: " + exc.getMessage());
                    }
                });
            }
        } catch (IOException e) {
            System.err.println("Server error: " + e.getMessage());
        }
    }

    private void receiveData(AsynchronousSocketChannel clientChannel) {
        ByteBuffer buffer = ByteBuffer.allocate(MAX_PACKET_SIZE);

        clientChannel.read(buffer, null, new CompletionHandler<>() {
            @Override
            public void completed(Integer bytesRead, Object attachment) {
                if (bytesRead != -1) {
                    buffer.flip();
                    incomingPackets.add(buffer);

                    // Invoke the callback with processed packet data
                    if (callback != null) {
                        ByteBuffer packetCopy = ByteBuffer.allocate(bytesRead);
                        buffer.flip(); // Reset position for read
                        packetCopy.put(buffer);
                        packetCopy.flip();

                        callback.accept(packetCopy);
                    }

                    buffer.clear();
                    receiveData(clientChannel); // Continue reading
                } else {
                    try {
                        clientChannel.close();
                    } catch (IOException e) {
                        System.err.println("Error closing channel: " + e.getMessage());
                    }
                }
            }

            @Override
            public void failed(Throwable exc, Object attachment) {
                System.err.println("Read error: " + exc.getMessage());
                try {
                    clientChannel.close();
                } catch (IOException e) {
                    System.err.println("Error closing channel on failure: " + e.getMessage());
                }
            }
        });
    }

    public TrafficStatistics calculateStatistics() {
        long totalPackets = incomingPackets.size();
        int totalLength = 0;
        HashMap<String, Integer> protocolCount = new HashMap<>();

        for (ByteBuffer packet : incomingPackets) {
            totalLength += packet.remaining(); // Assuming length is remaining bytes
            String protocol = "HTTP"; // Example extraction logic
            protocolCount.put(protocol, protocolCount.getOrDefault(protocol, 0) + 1);
        }

        double averagePacketSize = totalPackets > 0 ? (double) totalLength / totalPackets : 0.0;
        String mostFrequentProtocol = protocolCount.entrySet().stream()
                .max((e1, e2) -> Integer.compare(e1.getValue(), e2.getValue()))
                .map(Map.Entry::getKey)
                .orElse("Unknown");

        return new TrafficStatistics(totalPackets, averagePacketSize, mostFrequentProtocol);
    }

    public static class TrafficStatistics {
        private final long totalPackets;
        private final double averagePacketSize;
        private final String mostFrequentProtocol;

        public TrafficStatistics(long totalPackets, double averagePacketSize, String mostFrequentProtocol) {
            this.totalPackets = totalPackets;
            this.averagePacketSize = averagePacketSize;
            this.mostFrequentProtocol = mostFrequentProtocol;
        }

        @Override
        public String toString() {
            return "TrafficStatistics{" +
                    "totalPackets=" + totalPackets +
                    ", averagePacketSize=" + averagePacketSize +
                    ", mostFrequentProtocol='" + mostFrequentProtocol + '\'' +
                    '}';
        }
    }

    public static void main(String[] args) {
        TrafficAnalyzer analyzer = new TrafficAnalyzer(100, 12345L);
        analyzer.processStreamingDataAndAnalyzeTraffic("localhost", 8080, packet -> {
            System.out.println("Packet processed: " + packet.remaining() + " bytes");
        });

        // Simulate periodic statistics calculation
        try {
            Thread.sleep(5000); // Wait for some data to be collected
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        TrafficStatistics stats = analyzer.calculateStatistics();
        System.out.println(stats);
    }
}
```

