            exit(EXIT_FAILURE);
        }

        records[i]->value = generate_random(1, 100); // Example range
        snprintf(records[i]->key, sizeof(records[i]->key), "Key_%d", i);

        records[i]->offset_ptr = malloc(sizeof(long));
        if (!records[i]->offset_ptr) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        *(records[i]->offset_ptr) = generate_random(1000, 2000); // Example range

        if (custom_callback) custom_callback(records[i], NULL);
    }

    printf("Enter integers (enter -1 to stop):\n");
    while (1) {
        long value;
        scanf("%ld", &value);

        if (value == -1) break;

        pthread_mutex_lock(&lock);
        if (input_count >= input_capacity) {
            input_capacity *= 2;
            input = resize_array(&input, input_count, input_capacity);
