        if (input[i] > max_value) max_value = input[i];
    }

    printf("Maximum integer entered: %ld\n", max_value);

    free_resources(&records, &keys, offsets, &input);
    pthread_mutex_destroy(&lock);
}

int main() {
    processRecordsAndFindMax(12345, callback);
    return 0;
}
