['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Structure definition for a record
typedef struct {
    double value;
    char key[256];
    double *dynamicValue;
} Record;

// Function to generate secure random numbers
double generateRandomDouble(unsigned int seed) {
    srand(seed);
    return (double)(rand() / ((double)RAND_MAX + 1));
}

// Function prototypes for performance metrics
void calculateMetrics(double *timestamps, size_t count, double *average, double *median, double *stdDev);

// Callback type definition
typedef void (*ProcessRecordCallback)(Record *);

// Thread-safe mechanism using mutex
pthread_mutex_t lock;

// The main function handling file data and computing metrics
void handleFileDataAndComputeMetrics(const char *filePath, unsigned int seed, ProcessRecordCallback callback) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    double *timestamps = NULL;
    size_t timestampCount = 0;
    size_t timestampCapacity = 10;

    timestamps = (double *)malloc(timestampCapacity * sizeof(double));
    if (!timestamps) {
        perror("Memory allocation failed for timestamps");
        fclose(file);
        return;
    }

    double tempTimestamp;
    while (fscanf(file, "%lf", &tempTimestamp) == 1) {
        if (timestampCount >= timestampCapacity) {
            timestampCapacity *= 2;
            double *newTimestamps = realloc(timestamps, timestampCapacity * sizeof(double));
            if (!newTimestamps) {
                perror("Memory reallocation failed for timestamps");
                free(timestamps);
                fclose(file);
                return;
            }
            timestamps = newTimestamps;
        }
        timestamps[timestampCount++] = tempTimestamp;
    }

    fclose(file);

    double average, median, stdDev;
    calculateMetrics(timestamps, timestampCount, &average, &median, &stdDev);
    printf("Average: %lf\nMedian: %lf\nStandard Deviation: %lf\n", average, median, stdDev);

    // Initialize record data
    size_t recordCapacity = 10;
    Record *records = (Record *)malloc(recordCapacity * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records");
        free(timestamps);
        return;
    }

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < timestampCount; ++i) {
        if (i >= recordCapacity) {
            recordCapacity *= 2;
            Record *newRecords = realloc(records, recordCapacity * sizeof(Record));
            if (!newRecords) {
                perror("Memory reallocation failed for records");
                free(records);
                free(timestamps);
                pthread_mutex_unlock(&lock);
                return;
            }
            records = newRecords;
        }

        double randomValue = generateRandomDouble(seed + i);

        records[i].value = randomValue;
        snprintf(records[i].key, sizeof(records[i].key), "Record_%zu", i);
        records[i].dynamicValue = (double *)malloc(sizeof(double));
        if (!records[i].dynamicValue) {
            perror("Memory allocation failed for dynamic value");
            free(records);
            free(timestamps);
            pthread_mutex_unlock(&lock);
            return;
        }

        *records[i].dynamicValue = randomValue;

        // Call the callback function if provided
        if (callback != NULL) {
            callback(&records[i]);
        }
    }

    pthread_mutex_unlock(&lock);

    for (size_t i = 0; i < timestampCount; ++i) {
        free(records[i].dynamicValue);
    }

    free(records);
    free(timestamps);
}

void calculateMetrics(double *timestamps, size_t count, double *average, double *median, double *stdDev) {
    if (count == 0) return;

    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += timestamps[i];
    }

    *average = sum / count;

    // Sort the array for median calculation
    qsort(timestamps, count, sizeof(double), (__compar_fn_t)strcmp);

    if (count % 2 == 0) {
        *median = (timestamps[count / 2 - 1] + timestamps[count / 2]) / 2;
    } else {
        *median = timestamps[count / 2];
    }

    double varianceSum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        varianceSum += (timestamps[i] - *average) * (timestamps[i] - *average);
    }

    *stdDev = sqrt(varianceSum / count);
}

