    if (!records || current_records >= max_records) {
        size_t new_size = current_records ? current_records * 2 : 1;
        if (new_size > max_records) new_size = max_records;

        records = (Record *) realloc(records, new_size * sizeof(Record));
        for (size_t i = current_records; i < new_size; ++i) {
            records[i].value = 0;
            records[i].key = NULL;
