    if (numRecords <= 0 || maxStrLen <= 0 || minInt > maxInt) return NULL;

    Record *head = NULL;
    Record **currentPtr = &head;

    for (size_t i = 0; i < numRecords; ++i) {
        Record *newRecord = malloc(sizeof(Record));
        if (!newRecord) {
            // Handle memory allocation failure
            while (*currentPtr) {
                Record *temp = (*currentPtr)->next;
                free((*currentPtr)->data);
                free(*currentPtr);
                *currentPtr = temp;
            }
            return NULL;  // Return NULL to indicate an error in initialization
        }

        newRecord->data = malloc(maxStrLen + 1); // Allocate memory for string and null terminator
        if (!newRecord->data) {
            // Handle memory allocation failure
            free(newRecord);
            while (*currentPtr) {
                Record *temp = (*currentPtr)->next;
                free((*currentPtr)->data);
                free(*currentPtr);
                *currentPtr = temp;
            }
            return NULL;  // Return NULL to indicate an error in initialization
        }

        newRecord->number = rand() % (maxInt - minInt + 1) + minInt;
        snprintf(newRecord->data, maxStrLen + 1, "Record_%zu", i + 1);
        newRecord->next = NULL;

        *currentPtr = newRecord; // Link the newly created record
        currentPtr = &newRecord->next;
    }

    return head;
}

