```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 10
#define MAX_POOL_SIZE 100
#define PORT_MAX 65535

typedef enum {
    STATUS_IDLE,
    STATUS_ACTIVE
} ConnectionStatus;

typedef struct {
    char ip_address[16];
    int port;
    ConnectionStatus status;
} Connection;

typedef struct {
    Connection *connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionPool;

void initialize_pool(ConnectionPool *pool) {
    pool->capacity = INITIAL_POOL_SIZE;
    pool->size = 0;
    pool->connections = (Connection *)malloc(pool->capacity * sizeof(Connection));
    if (!pool->connections) {
        fprintf(stderr, "Failed to allocate memory for connection pool\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void free_pool(ConnectionPool *pool) {
    free(pool->connections);
    pthread_mutex_destroy(&pool->lock);
}

int add_connection(ConnectionPool *pool, const char *ip_address, int port) {
    if (pthread_mutex_lock(&pool->lock) != 0) {
        return -1;
    }

    if (pool->size >= pool->capacity && pool->capacity < MAX_POOL_SIZE) {
        size_t new_capacity = pool->capacity * 2;
        Connection *new_connections = (Connection *)realloc(pool->connections, new_capacity * sizeof(Connection));
        if (!new_connections) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }

    if (pool->size < pool->capacity) {
        strncpy(pool->connections[pool->size].ip_address, ip_address, sizeof(pool->connections[pool->size].ip_address) - 1);
        pool->connections[pool->size].port = port;
        pool->connections[pool->size].status = STATUS_IDLE;
        pool->size++;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void set_connection_active(ConnectionPool *pool, int index) {
    if (pthread_mutex_lock(&pool->lock) != 0) {
        return;
    }
    if (index >= 0 && index < pool->size) {
        pool->connections[index].status = STATUS_ACTIVE;
    }
    pthread_mutex_unlock(&pool->lock);
}

void set_connection_idle(ConnectionPool *pool, int index) {
    if (pthread_mutex_lock(&pool->lock) != 0) {
        return;
    }
    if (index >= 0 && index < pool->size) {
        pool->connections[index].status = STATUS_IDLE;
    }
    pthread_mutex_unlock(&pool->lock);
}

int find_idle_connection(ConnectionPool *pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->connections[i].status == STATUS_IDLE) {
            return i;
        }
    }
    return -1;
}

void garbage_collect(ConnectionPool *pool) {
    if (pthread_mutex_lock(&pool->lock) != 0) {
        return;
    }

    size_t new_size = 0;
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->connections[i].status == STATUS_ACTIVE) {
            if (new_size != i) {
                pool->connections[new_size] = pool->connections[i];
            }
            new_size++;
        }
    }

    pool->size = new_size;
    pthread_mutex_unlock(&pool->lock);
}

void *connection_initializer(void *arg) {
    // Custom initialization logic can be added here
    return NULL;
}

int main() {
    ConnectionPool pool;
    initialize_pool(&pool);

    add_connection(&pool, "192.168.1.1", 8080);
    int index = find_idle_connection(&pool);
    if (index != -1) {
        set_connection_active(&pool, index);
    }

    garbage_collect(&pool);
    free_pool(&pool);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The connection pool uses a mutex to ensure thread safety when modifying the pool.
- **Dynamic Resizing**: The pool can grow dynamically up to a maximum size, reallocating memory as needed.
- **Garbage Collection**: Inactive connections are reclaimed to optimize memory usage.
- **Connection Management**: Functions to add, activate, and idle connections are provided.
- **Initialization Callback**: A placeholder for custom connection initialization logic is included.

This code provides a foundation for managing network connections in a distributed microservices architecture. Adjustments may be needed based on specific application requirements or performance considerations.']

