#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    char *data;
    float value;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

TreeNode* createNode(const char *str, float val) {
    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for node.\n");
        return NULL;
    }

    node->data = (char *)malloc(strlen(str) + 1);
    if (!node->data) {
        free(node);
        fprintf(stderr, "Memory allocation failed for node data.\n");
        return NULL;
    }
    strcpy(node->data, str);

    node->value = val;
    node->left = node->right = NULL;

    return node;
}

void freeTree(TreeNode *root) {
    if (!root) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root->data);
    free(root);
}

TreeNode* initializeTree(int numNodes, int maxLength, float minVal, float maxVal) {
    if (numNodes <= 0 || maxLength <= 0) return NULL;

    TreeNode *root = createNode("Root", (minVal + maxVal) / 2.0);
    if (!root) return NULL;

    TreeNode **nodes = malloc(numNodes * sizeof(TreeNode *));
    if (!nodes) {
        freeTree(root);
        fprintf(stderr, "Memory allocation failed for node array.\n");
        return NULL;
    }

    nodes[0] = root;
    int index = 1;

    while (index < numNodes && index > 0) {
        TreeNode *current = nodes[--index];
        if (current->left == NULL) {
            char buffer[maxLength + 1];
            snprintf(buffer, maxLength + 1, "Node%03d", index);
            current->left = createNode(buffer, minVal + ((float)rand() / RAND_MAX) * (maxVal - minVal));
            if (!current->left) break;
            nodes[index] = current->left;
        }
        if (index < numNodes && current->right == NULL) {
            char buffer[maxLength + 1];
            snprintf(buffer, maxLength + 1, "Node%03d", index);
            current->right = createNode(buffer, minVal + ((float)rand() / RAND_MAX) * (maxVal - minVal));
            if (!current->right) break;
            nodes[index++] = current->right;
        }
    }

    free(nodes);
    return root;
}

void traverseAndReport(TreeNode *root) {
    if (!root) return;

    printf("Node: %s, Value: %.2f\n", root->data, root->value);

    if (root->left) {
        printf("  Left Child:\n");
        traverseAndReport(root->left);
    }
    if (root->right) {
        printf("  Right Child:\n");
        traverseAndReport(root->right);
    }
}

int main() {
    int numNodes = 10;
    int maxLength = 20;
    float minVal = 0.0f, maxVal = 100.0f;

    TreeNode *tree = initializeTree(numNodes, maxLength, minVal, maxVal);
    if (tree) {
        traverseAndReport(tree);
        freeTree(tree);
    }

    return 0;
}
```

### Key Considerations:
- **Memory Management**: The code ensures all allocations are checked for failure. Memory is freed recursively to avoid leaks.
- **Error Handling**: Graceful handling of allocation failures with appropriate error messages.
- **Performance**: Efficient tree traversal and initialization, balancing between memory usage and processing speed.
- **Scalability**: Designed to handle a variable number of nodes, with careful management of dynamic memory.
- **Maintainability**: Clear structure and separation of concerns make the code easier to maintain and extend.']

