#include <pthread.h>

#define SUCCESS 0
#define ALLOCATION_ERROR 1
#define INVALID_INPUT -1

typedef struct {
    int index;
    char *key_name;
    long *offset_ptr;
} Record;

int initialize_database(int size, long offset_range_min, long offset_range_max,
                        void (*callback)(Record*), int thread_safe) {
    if (size <= 0 || callback == NULL) return INVALID_INPUT;

    long *offset_array = (long *)malloc(size * sizeof(long));
    int *key_array = (int *)malloc(size * sizeof(int));

    if (!offset_array || !key_array) return ALLOCATION_ERROR;

    for (int i = 0; i < size; ++i) {
        offset_array[i] = i;
        key_array[i] = i;
    }

    Record *records = (Record *)malloc(size * sizeof(Record));
    if (!records) {
        free(offset_array);
        free(key_array);
        return ALLOCATION_ERROR;
    }

    pthread_mutex_t mutex;
    if (thread_safe) {
        pthread_mutex_init(&mutex, NULL);
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < size; ++i) {
        records[i].index = i;

        char key_buffer[32];
        snprintf(key_buffer, sizeof(key_buffer), "key_%d", i);
        records[i].key_name = strdup(key_buffer);

        long *offset_value = malloc(sizeof(long));
        if (!offset_value) {
            free(offset_array);
            free(key_array);
            for (int j = 0; j < i; ++j) {
                free(records[j].key_name);
                free(records[j].offset_ptr);
            }
            free(records);
            return ALLOCATION_ERROR;
        }

        *offset_value = offset_range_min + rand() % (offset_range_max - offset_range_min + 1);

        if (thread_safe) {
            pthread_mutex_lock(&mutex);
        }

        records[i].offset_ptr = offset_value;

        callback(&records[i]);

        if (thread_safe) {
            pthread_mutex_unlock(&mutex);
        }
    }

    if (thread_safe) {
        pthread_mutex_destroy(&mutex);
    }

    free(offset_array);
    free(key_array);

    return SUCCESS;
}

void record_callback(Record *record) {
    printf("Record %d initialized with key: %s and offset: %ld\n",
           record->index, record->key_name, *(record->offset_ptr));
}

int main() {
    int size = 10;
    long offset_min = 0;
    long offset_max = 100;

    if (initialize_database(size, offset_min, offset_max, record_callback, 1) != SUCCESS) {
        fprintf(stderr, "Failed to initialize the database.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
