#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "secure_random_lib.h" // Placeholder for external secure random library

// Define error codes
#define SUCCESS 0
#define ERR_MEMORY_ALLOCATION -1
#define ERR_INVALID_INPUT -2

typedef struct {
    int index;
    char *key;
    long *offset;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    pthread_mutex_t lock;
    int thread_safe;
} Table;

// Function declarations
int create_table(Table *table, size_t initial_capacity, int thread_safe);
int initialize_record(Record *record, const char *key_prefix, long offset_value, void (*callback)(Record *));
void destroy_table(Table *table);

int create_table(Table *table, size_t initial_capacity, int thread_safe) {
    if (!table || initial_capacity == 0) return ERR_INVALID_INPUT;

    table->records = malloc(initial_capacity * sizeof(Record*));
    if (!table->records) return ERR_MEMORY_ALLOCATION;

    memset(table->records, 0, initial_capacity * sizeof(Record*));

    table->capacity = initial_capacity;
    pthread_mutex_init(&table->lock, NULL);
    table->thread_safe = thread_safe;

    return SUCCESS;
}

int initialize_record(Table *table, size_t index, const char *key_prefix, long offset_value, void (*callback)(Record *)) {
    if (!table || !key_prefix || index >= table->capacity) return ERR_INVALID_INPUT;

    Record *record = malloc(sizeof(Record));
    if (!record) return ERR_MEMORY_ALLOCATION;

    record->index = index;
    record->key = malloc(strlen(key_prefix) + 10); // Assuming suffix length
    if (!record->key) {
        free(record);
        return ERR_MEMORY_ALLOCATION;
    }

    snprintf(record->key, strlen(key_prefix) + 10, "%s_%d", key_prefix, secure_random_generate()); // Secure random for uniqueness

    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        free(record->key);
        free(record);
        return ERR_MEMORY_ALLOCATION;
    }

    *record->offset = offset_value;

    if (callback) callback(record);

    if (table->thread_safe) pthread_mutex_lock(&table->lock);
    table->records[index] = record;
    if (table->thread_safe) pthread_mutex_unlock(&table->lock);

    return SUCCESS;
}

void destroy_table(Table *table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i]) {
            free(table->records[i]->key);
            free(table->records[i]->offset);
            free(table->records[i]);
        }
    }

    free(table->records);
    pthread_mutex_destroy(&table->lock);
}

// Example callback function
void example_callback(Record *record) {
    printf("Initialized record with index: %d, key: %s\n", record->index, record->key);
}
