int findMax(const int *array, size_t arraySize) {
    if (!array || arraySize == 0) return INT_MIN;

    int max = array[0];
    for (size_t i = 1; i < arraySize; ++i) {
        if (array[i] > max) max = array[i];
    }
    return max;
}

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node* appendNode(Node *head, int value) {
    Node *newNode = malloc(sizeof(Node));
    if (!newNode) handleError("Failed to allocate memory for new node");

    newNode->value = value;
    newNode->next = NULL;

    if (head == NULL) return newNode;

    Node *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;

    return head;
}

void freeNodeList(Node *head) {
    while (head) {
        Node *temp = head;
        head = head->next;
        free(temp);
    }
}

void processRecordsAndFindMax(size_t recordCount, int valueRangeMin, int valueRangeMax, unsigned int seed, void (*callback)(const Record*)) {
