        inputList = appendNode(inputList, input);
    }

    // Step 10: Find max in key array
    int maxKey = findMax(keys, keyArraySize);

    // Free resources
    pthread_mutex_destroy(&lock);
    free(offsets);
    free(keys);
    freeRecords(records, recordCount);
    freeNodeList(inputList);
}

// Example callback function
