#include <pthread.h>

typedef enum { INFO, WARNING, ERROR } LogLevel;

typedef struct {
    char *message;
    time_t timestamp;
    LogLevel logLevel;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogEntriesArray;

// Function prototypes
void initializeLogArrays(LogEntriesArray *logEntries, const char *timestampFormat);
void resizeLogEntriesArray(LogEntriesArray *logEntries, size_t newCapacity);
void freeLogEntries(LogEntriesArray *logEntries);
char* formatTimestamp(const time_t timestamp, const char *format);

void parseAndProcessLogs(const char *timestampFormat) {
    LogEntriesArray logEntries;
    pthread_mutex_init(&logEntries.lock, NULL);
    initializeLogArrays(&logEntries, timestampFormat);

    // Simulate processing log entries from multiple sources
    while (1) {
        time_t current_time = time(NULL);
        LogLevel level = INFO;  // Example level, this would be parsed from logs

        pthread_mutex_lock(&logEntries.lock);
        if (logEntries.count == logEntries.capacity) {
            resizeLogEntriesArray(&logEntries, logEntries.capacity * 2);
        }

        LogEntry *newEntry = malloc(sizeof(LogEntry));
        newEntry->timestamp = current_time;
        newEntry->message = strdup("Sample log message");
        newEntry->logLevel = level;

        logEntries.entries[logEntries.count++] = newEntry;
        pthread_mutex_unlock(&logEntries.lock);

        // Simulate delay for demonstration purposes
        sleep(1);
    }

    freeLogEntries(&logEntries);
    pthread_mutex_destroy(&logEntries.lock);
}

void initializeLogArrays(LogEntriesArray *logEntries, const char *timestampFormat) {
    logEntries->capacity = 10;
    logEntries->count = 0;

    logEntries->entries = malloc(logEntries->capacity * sizeof(LogEntry*));
    for (size_t i = 0; i < logEntries->capacity; ++i) {
        time_t timestamp = time(NULL);
        char *formattedTimestamp = formatTimestamp(timestamp, timestampFormat);

        LogEntry *entry = malloc(sizeof(LogEntry));
        entry->timestamp = timestamp;
        entry->message = strdup("Initialized Entry");
        entry->logLevel = INFO;

        logEntries->entries[i] = entry;
    }
}

void resizeLogEntriesArray(LogEntriesArray *logEntries, size_t newCapacity) {
    LogEntry **newEntries = realloc(logEntries->entries, newCapacity * sizeof(LogEntry*));
    if (!newEntries) {
        perror("Failed to resize array");
        freeLogEntries(logEntries);
        exit(EXIT_FAILURE);
    }
    logEntries->entries = newEntries;
    logEntries->capacity = newCapacity;
}

void freeLogEntries(LogEntriesArray *logEntries) {
    pthread_mutex_lock(&logEntries->lock);

    for (size_t i = 0; i < logEntries->count; ++i) {
        if (logEntries->entries[i]) {
            free(logEntries->entries[i]->message);
            free(logEntries->entries[i]);
        }
    }

    free(logEntries->entries);

    pthread_mutex_unlock(&logEntries->lock);
}

char* formatTimestamp(const time_t timestamp, const char *format) {
    struct tm *timeinfo = localtime(&timestamp);
    char buffer[80];
    strftime(buffer, sizeof(buffer), format, timeinfo);
    return strdup(buffer);
}
