    *tasks = allocate_tasks(*capacity);
    if (!*tasks) {
        fprintf(stderr, "Failed to allocate initial task memory\n");
        exit(EXIT_FAILURE);
    }
}

void add_task(Task **tasks, size_t *size, const char *name, Callback pre_callback, Callback post_callback) {
    if (pre_callback) pre_callback(NULL);

    if (*size >= *capacity) {
        size_t new_capacity = *capacity * GROWTH_FACTOR;
        Task *new_tasks = (Task*)realloc(*tasks, new_capacity * sizeof(Task));

        if (!new_tasks) {
            fprintf(stderr, "Failed to reallocate task memory\n");
            free_tasks(*tasks);
            exit(EXIT_FAILURE);
        }
        *tasks = new_tasks;
        for (size_t i = *size; i < new_capacity; ++i) {
            (*tasks)[i].status = TASK_PENDING;
            secure_random_generate((*tasks)[i].priority, MIN_PRIORITY, MAX_PRIORITY);
        }
        *capacity = new_capacity;
    }

    strncpy((*tasks)[*size].name, name, sizeof((*tasks)[*size].name) - 1);
    (*tasks)[*size].status = TASK_PENDING;

    if (post_callback) post_callback(&(*tasks)[*size]);

    ++(*size);
}

void update_task_status(Task *tasks, size_t size, const char *name, TaskStatus new_status) {
    for (size_t i = 0; i < size; ++i) {
        if (strcmp(tasks[i].name, name) == 0) {
            tasks[i].status = new_status;
            break;
        }
    }
}

void free_tasks(Task *tasks) {
    if (tasks) {
        free(tasks);
    }
}

void report_task_summary(const Task *tasks, size_t size) {
    int active_count = 0, completed_count = 0, pending_count = 0;

    for (size_t i = 0; i < size; ++i) {
        switch (tasks[i].status) {
            case TASK_ACTIVE: ++active_count; break;
            case TASK_COMPLETED: ++completed_count; break;
            case TASK_PENDING: ++pending_count; break;
        }
    }

    printf("Active Tasks: %d\n", active_count);
    printf("Completed Tasks: %d\n", completed_count);
    printf("Pending Tasks: %d\n", pending_count);
}

