['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { ACTIVE, COMPLETED, PENDING } TaskStatus;

typedef struct {
    char name[256];
    int priority;
    TaskStatus status;
} Task;

typedef enum { STRING_TYPE, INT_TYPE, BOOL_TYPE } PreferenceType;

typedef struct {
    char name[256];
    PreferenceType type;
    void *defaultValue;
    void *currentValue;
} UserPreference;

typedef struct {
    Task **tasks;
    size_t task_count;
    size_t task_capacity;
    pthread_mutex_t task_lock;
} TaskList;

typedef struct {
    UserPreference **preferences;
    size_t preference_count;
    size_t preference_capacity;
    pthread_mutex_t pref_lock;
} PreferenceList;

typedef void (*Callback)(const char*);

TaskList* init_task_list(size_t initial_size, Callback pre_add, Callback post_add);
UserPreference* create_preference(const char *name, PreferenceType type, void *default_value);
PreferenceList* init_preference_list(size_t initial_size, Callback pre_update, Callback post_update);

void add_task(TaskList *task_list, const char *name, TaskStatus status, Callback pre_add, Callback post_add);
void update_preference(PreferenceList *pref_list, const char *name, void *new_value, Callback pre_update, Callback post_update);
void free_resources(TaskList *task_list, PreferenceList *pref_list);

void report_task_status(const TaskList *task_list);
void report_preferences(const PreferenceList *pref_list);

int main() {
    // Example usage
    TaskList *task_list = init_task_list(10, NULL, NULL);
    PreferenceList *pref_list = init_preference_list(5, NULL, NULL);

    add_task(task_list, "Task 1", PENDING, NULL, NULL);
    UserPreference *preference = create_preference("Volume", INT_TYPE, (void*)75);
    update_preference(pref_list, preference->name, (void*)80, NULL, NULL);

    report_task_status(task_list);
    report_preferences(pref_list);

    free_resources(task_list, pref_list);
    return 0;
}

TaskList* init_task_list(size_t initial_size, Callback pre_add, Callback post_add) {
    TaskList *list = malloc(sizeof(TaskList));
    list->tasks = calloc(initial_size, sizeof(Task *));
    list->task_count = 0;
    list->task_capacity = initial_size;
    pthread_mutex_init(&list->task_lock, NULL);

    // Set up secure random generator with a custom seed
    srand(time(NULL));

    return list;
}

UserPreference* create_preference(const char *name, PreferenceType type, void *default_value) {
    UserPreference *preference = malloc(sizeof(UserPreference));
    strncpy(preference->name, name, sizeof(preference->name));
    preference->type = type;

    switch (type) {
        case STRING_TYPE:
            preference->defaultValue = strdup(default_value);
            break;
        case INT_TYPE:
            preference->defaultValue = malloc(sizeof(int));
            *(int *)preference->defaultValue = *(int *)default_value;
            break;
        case BOOL_TYPE:
            preference->defaultValue = malloc(sizeof(int)); // assuming boolean as int
            *(int *)preference->defaultValue = *(int *)default_value;
            break;
    }

    preference->currentValue = preference->defaultValue;

    return preference;
}

PreferenceList* init_preference_list(size_t initial_size, Callback pre_update, Callback post_update) {
    PreferenceList *list = malloc(sizeof(PreferenceList));
    list->preferences = calloc(initial_size, sizeof(UserPreference *));
    list->preference_count = 0;
    list->preference_capacity = initial_size;
    pthread_mutex_init(&list->pref_lock, NULL);

    return list;
}

void add_task(TaskList *task_list, const char *name, TaskStatus status, Callback pre_add, Callback post_add) {
    if (task_list->task_count >= task_list->task_capacity) {
        size_t new_capacity = task_list->task_capacity * 2;
        Task **new_tasks = realloc(task_list->tasks, new_capacity * sizeof(Task *));
        if (!new_tasks) {
            fprintf(stderr, "Failed to allocate memory for tasks\n");
            return;
        }
        memset(new_tasks + task_list->task_capacity, 0, (new_capacity - task_list->task_capacity) * sizeof(Task *));
        task_list->tasks = new_tasks;
        task_list->task_capacity = new_capacity;
    }

    pthread_mutex_lock(&task_list->task_lock);
    if (pre_add) pre_add("Adding Task");

    Task *task = malloc(sizeof(Task));
    strncpy(task->name, name, sizeof(task->name));
    task->priority = rand() % 100; // Example priority generation
    task->status = status;

    task_list->tasks[task_list->task_count++] = task;

    if (post_add) post_add("Added Task");
    pthread_mutex_unlock(&task_list->task_lock);
}

void update_preference(PreferenceList *pref_list, const char *name, void *new_value, Callback pre_update, Callback post_update) {
    pthread_mutex_lock(&pref_list->pref_lock);
    if (pre_update) pre_update("Updating Preference");

    for (size_t i = 0; i < pref_list->preference_count; ++i) {
        UserPreference *preference = pref_list->preferences[i];
        if (strcmp(preference->name, name) == 0) {
            switch (preference->type) {
                case STRING_TYPE:
                    free((char *)preference->currentValue);
                    preference->currentValue = strdup(new_value);
                    break;
                case INT_TYPE:
                    *(int *)preference->currentValue = *(int *)new_value;
                    break;
                case BOOL_TYPE:
                    *(int *)preference->currentValue = *(int *)new_value;
                    break;
            }
            if (post_update) post_update("Updated Preference");
            pthread_mutex_unlock(&pref_list->pref_lock);
            return;
        }
    }

    fprintf(stderr, "Preference not found: %s\n", name);
    pthread_mutex_unlock(&pref_list->pref_lock);
}

void free_resources(TaskList *task_list, PreferenceList *pref_list) {
    for (size_t i = 0; i < task_list->task_count; ++i) {
        if (task_list->tasks[i]) {
            free(task_list->tasks[i]);
        }
    }
    free(task_list->tasks);
    pthread_mutex_destroy(&task_list->task_lock);
    free(task_list);

    for (size_t i = 0; i < pref_list->preference_count; ++i) {
        UserPreference *preference = pref_list->preferences[i];
        if (preference) {
            switch (preference->type) {
                case STRING_TYPE:
                    free((char *)preference->currentValue);
                    break;
                case INT_TYPE:
                case BOOL_TYPE:
                    free(preference->currentValue);
                    break;
            }
            free(preference);
        }
    }
    free(pref_list->preferences);
    pthread_mutex_destroy(&pref_list->pref_lock);
    free(pref_list);
}

