} Task;

// Dynamic task list
typedef struct {
    Task *tasks;
    size_t capacity;
    size_t count;
    double growth_factor;  // Configurable growth factor for resizing
    void (*pre_add_callback)(void *);
    void (*post_add_callback)(void *);
} TaskList;

// Function prototypes
TaskList* init_task_list(size_t initial_capacity, double growth_factor);
int add_task(TaskList *task_list, const char *name, int min_priority, int max_priority, unsigned long seed);
