// Initialize a task list with the given capacity and growth factor
TaskList* init_task_list(size_t initial_capacity, double growth_factor) {
    TaskList *list = (TaskList *)malloc(sizeof(TaskList));
    if (!list) return NULL;

    list->tasks = (Task *)calloc(initial_capacity, sizeof(Task));
    if (!list->tasks) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    list->growth_factor = growth_factor;
    list->pre_add_callback = NULL;
    list->post_add_callback = NULL;

    return list;
}

// Add a task to the task list
int add_task(TaskList *task_list, const char *name, int min_priority, int max_priority, unsigned long seed) {
    if (!task_list || !name) return -1;

    // Execute pre-add callback if set
    if (task_list->pre_add_callback) {
        task_list->pre_add_callback(NULL);
    }

    // Resize the task list if necessary
    if (task_list->count >= task_list->capacity) {
        size_t new_capacity = (size_t)(task_list->capacity * task_list->growth_factor);
        Task *new_tasks = (Task *)realloc(task_list->tasks, new_capacity * sizeof(Task));
        if (!new_tasks) return -1;

        task_list->tasks = new_tasks;
        task_list->capacity = new_capacity;
    }

    // Set the task properties
    Task *task = &task_list->tasks[task_list->count];
    strncpy(task->name, name, sizeof(task->name));
    task->priority = generate_random_number(min_priority, max_priority, &seed);
    task->status = TASK_PENDING;

    // Increment the task count
    task_list->count++;

    // Execute post-add callback if set
    if (task_list->post_add_callback) {
        task_list->post_add_callback(NULL);
    }

    return 0;
}

// Free all allocated memory for the task list
void free_task_list(TaskList *task_list) {
    if (!task_list) return;

    free(task_list->tasks);
    free(task_list);
}

// Set the pre-add callback function
void set_pre_add_callback(TaskList *task_list, void (*callback)(void *)) {
    if (task_list) task_list->pre_add_callback = callback;
}

// Set the post-add callback function
void set_post_add_callback(TaskList *task_list, void (*callback)(void *)) {
    if (task_list) task_list->post_add_callback = callback;
}

// Generate a random number within a range using an external library or custom seed
int generate_random_number(int min, int max, unsigned long *seed) {
    // Using the C standard library for randomness; replace with secure RNG as needed
    srand(*seed);
    int num = (rand() % (max - min + 1)) + min;
    *seed = rand();  // Update seed
    return num;
}

// Example usage
