double generateRandomDouble(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

void resizeInputArray(metric ***input, size_t *currentSize, size_t newSize) {
    pthread_mutex_lock(&metricMutex);

    metric **newArray = realloc(*input, newSize * sizeof(metric *));
    if (!newArray) {
        fprintf(stderr, "Memory allocation failed during resize\n");
        exit(EXIT_FAILURE);
    }
    *input = newArray;

    for (size_t i = *currentSize; i < newSize; ++i) {
        metric *m = malloc(sizeof(metric));
        if (!m) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previous allocations in case of failure
            while (*currentSize > 0) {
                free((*input)[--(*currentSize)]);
            }
            free(newArray);
            pthread_mutex_unlock(&metricMutex);
            exit(EXIT_FAILURE);
        }
        m->value = rand() % MAX_METRIC_ID;
        snprintf(m->stringID, sizeof(m->stringID), "Metric_%d", (int)m->value);
        m->dynamicValuePtr = malloc(sizeof(double));
        if (!m->dynamicValuePtr) {
            fprintf(stderr, "Memory allocation failed\n");
            free(m);
            // Free previous allocations in case of failure
            while (*currentSize > 0) {
                free((*input)[--(*currentSize)]);
            }
            free(newArray);
            pthread_mutex_unlock(&metricMutex);
            exit(EXIT_FAILURE);
        }
        *m->dynamicValuePtr = generateRandomDouble(0.0, 100.0);
        (*input)[i] = m;
    }
    *currentSize = newSize;

    pthread_mutex_unlock(&metricMutex);
}

void callback(metric *m) {
    printf("Callback processing metric %d with value %.2f\n", m->value, *(m->dynamicValuePtr));
}

void freeResources(metric **input, size_t currentSize) {
    for (size_t i = 0; i < currentSize; ++i) {
        if (input[i]) {
            free(input[i]->dynamicValuePtr);
            free(input[i]);
        }
    }
    free(input);
}

double calculateAverage(double *values, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += values[i];
    }
    return count > 0 ? sum / count : 0.0;
}

double findMaximum(double *values, size_t count) {
    if (count == 0) return -1.0;
    double max = values[0];
    for (size_t i = 1; i < count; ++i) {
        if (values[i] > max) {
            max = values[i];
        }
    }
    return max;
}

void parseAndAggregateMetrics(size_t metricArraySize, size_t resizeIncrement, unsigned int seed) {
    double *timestamps = malloc(metricArraySize * sizeof(double));
    int *metricIDs = malloc(metricArraySize * sizeof(int));

    if (!timestamps || !metricIDs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    time_t currentTime = time(NULL);

    pthread_mutex_lock(&timestampMutex);
    for (size_t i = 0; i < metricArraySize; ++i) {
        timestamps[i] = difftime(currentTime + i, currentTime);
        metricIDs[i] = i;
    }
    pthread_mutex_unlock(&timestampMutex);

    size_t currentInputSize = INITIAL_SIZE;
    metric **input = malloc(INITIAL_SIZE * sizeof(metric *));
    if (!input) {
        fprintf(stderr, "Memory allocation failed\n");
        free(timestamps);
        free(metricIDs);
        exit(EXIT_FAILURE);
    }

    resizeInputArray(&input, &currentInputSize, currentInputSize);

    for (size_t i = 0; i < metricArraySize; ++i) {
        if (i >= currentInputSize) {
            resizeInputArray(&input, &currentInputSize, currentInputSize + resizeIncrement);
        }

        callback(input[i]);
    }

    double *values = malloc(currentInputSize * sizeof(double));
    if (!values) {
        fprintf(stderr, "Memory allocation failed\n");
        freeResources(input, currentInputSize);
        free(timestamps);
        free(metricIDs);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < currentInputSize; ++i) {
        values[i] = *(input[i]->dynamicValuePtr);
    }

    double average = calculateAverage(values, currentInputSize);
    double maximum = findMaximum(values, currentInputSize);

    printf("Average: %.2f\n", average);
    printf("Maximum: %.2f\n", maximum);

    free(values);
    freeResources(input, currentInputSize);
    free(timestamps);
    free(metricIDs);
}

int main() {
    parseAndAggregateMetrics(50, 10, 12345);
    return 0;
}
