void resizeLogsArray() {
    pthread_mutex_lock(&lock);
    if (current_size == capacity) {
        size_t new_capacity = capacity ? capacity * 2 : INITIAL_SIZE;
        logs = realloc(logs, new_capacity * sizeof(logEntry));
        if (!logs) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        capacity = new_capacity;
    }
    pthread_mutex_unlock(&lock);
}

void initializeLogs() {
    pthread_mutex_init(&lock, NULL);
    logs = malloc(INITIAL_SIZE * sizeof(logEntry));
    if (!logs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    capacity = INITIAL_SIZE;
    current_size = 0;

    for (size_t i = 0; i < INITIAL_SIZE; ++i) {
        logs[i].timestamp = time(NULL);
        logs[i].sourceID = i + 1;
        strcpy(logs[i].message, "");
    }
}

void freeLogs() {
    pthread_mutex_lock(&lock);
    free(logs);
    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

int processLogEntry(const char* line) {
    if (!secureParseLog(line, &logs[current_size])) {
        fprintf(stderr, "Warning: Malformed log entry\n");
        return 0;
    }

    resizeLogsArray();
    logs[current_size].timestamp = time(NULL); // Update timestamp to current
    pthread_mutex_lock(&lock);
    if (callback) {
        callback(&logs[current_size]);
    }
    current_size++;
    pthread_mutex_unlock(&lock);

    return 1;
}

void parseAndAggregateLogs(int (*user_callback)(const logEntry*)) {
    initializeLogs();
    callback = user_callback;

    char line[512];
    while (fgets(line, sizeof(line), stdin)) {
        processLogEntry(line);
    }

    freeLogs();
}
