// Circular buffer for log entries
#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    logEntry **entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LogBuffer;

// Initialize log buffer
void initializeLogBuffer(LogBuffer *buffer) {
    buffer->entries = malloc(INITIAL_BUFFER_SIZE * sizeof(logEntry *));
    if (!buffer->entries) {
        perror("Failed to allocate log buffer");
        exit(EXIT_FAILURE);
    }
    buffer->count = 0;
    buffer->capacity = INITIAL_BUFFER_SIZE;
    pthread_mutex_init(&buffer->lock, NULL);
}

// Resize the circular buffer
void resizeLogBuffer(LogBuffer *buffer) {
    size_t new_capacity = buffer->capacity * 2;
    logEntry **new_entries = realloc(buffer->entries, new_capacity * sizeof(logEntry *));
    if (!new_entries) {
        perror("Failed to resize log buffer");
        exit(EXIT_FAILURE);
    }
    buffer->entries = new_entries;
    buffer->capacity = new_capacity;
}

// Add a log entry to the circular buffer
void addLogEntry(LogBuffer *buffer, logEntry *entry) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count == buffer->capacity) {
        resizeLogBuffer(buffer);
    }
    buffer->entries[buffer->count++] = entry;
    pthread_mutex_unlock(&buffer->lock);
}

// Aggregate metrics
void aggregateMetrics(logEntry **log_entries, size_t count, float *avg_latency, float *total_throughput, float *error_rate_percentage) {
