            total_latency += *entry->metrics.latency;
            total_throughput += *entry->metrics.throughput;
            total_errors += *entry->metrics.error_rate;
        }
    }

    *avg_latency = (count > 0) ? (total_latency / count) : 0.0;
    *total_throughput = total_throughput;
    *error_rate_percentage = (count > 0) ? (total_errors / count * 100) : 0.0;
}

// Free log entry
void freeLogEntry(logEntry *entry) {
    if (--entry->ref_count == 0) {
        free(entry->message);
        free(entry->metrics.latency);
        free(entry->metrics.throughput);
        free(entry->metrics.error_rate);
        free(entry);
    }
}

