// Function to resize the linked list when needed
void ensureCapacity() {
    pthread_rwlock_wrlock(&rwlock);

    if (currentSize >= head->capacity) {
        LogNode* newNode = createNewNode(head->capacity * 2);
        if (!newNode) {
            pthread_rwlock_unlock(&rwlock);
            return;
        }
        newNode->next = head;
        head = newNode;

        // Move current entries to the new node
        memmove(newNode->entries, head->entries + head->capacity - (head->capacity / 2), 
                (head->capacity / 2) * sizeof(logEntry));
    }

    pthread_rwlock_unlock(&rwlock);
}

// Function to add a log entry
void addLogEntry(const char* timestampStr, const char* sourceIDStr, const char* message) {
    ensureCapacity();

    pthread_rwlock_wrlock(&rwlock);

    LogNode* current = head;
    while (current->next != NULL) {
        current = current->next;
    }

    logEntry* entry = &current->entries[current->capacity - 1];
    entry->timestamp = time(NULL); // Use parsed timestamp if available
    entry->sourceID = atoi(sourceIDStr);
    strncpy(entry->message, message, sizeof(entry->message) - 1);

    currentSize++;

    pthread_rwlock_unlock(&rwlock);
}

// Callback function type
typedef void (*LogCallback)(logEntry* entry);

// Main function to parse and aggregate logs
void parseAndAggregateLogs(LogCallback callback) {
    char line[512];
    while (fgets(line, sizeof(line), stdin)) {
        // Parse the log entry from input line
        char timestampStr[64], sourceIDStr[16], message[256];
        if (sscanf(line, "%63[^:]:%15s:%255[^\n]", timestampStr, sourceIDStr, message) == 3) {
            addLogEntry(timestampStr, sourceIDStr, message);

            // Invoke callback if provided
            if (callback != NULL) {
                pthread_rwlock_rdlock(&rwlock);
                LogNode* current = head;
                while (current->next != NULL) {
                    current = current->next;
                }
                for (size_t i = 0; i < current->capacity && currentSize > 0; i++) {
                    callback(&current->entries[i]);
                    currentSize--;
                }
                pthread_rwlock_unlock(&rwlock);
            }
        } else {
            fprintf(stderr, "Warning: Malformed log entry ignored.\n");
        }
    }

    // Free all allocated memory
    while (head) {
        LogNode* temp = head;
        head = head->next;
        free(temp->entries);
        free(temp);
    }
}

// Example callback function
void exampleCallback(logEntry* entry) {
    printf("Processed log: %s, Source: %d\n", entry->message, entry->sourceID);
}

int main() {
    // Initialize the first node
    head = createNewNode(initialCapacity);

    if (!head) {
        fprintf(stderr, "Failed to initialize memory.\n");
        return EXIT_FAILURE;
    }

    parseAndAggregateLogs(exampleCallback);
    return 0;
}
