        records[i].value = randomValue;
        snprintf(records[i].key, sizeof(records[i].key), "Key_%zu", i);

        records[i].ptrValue = malloc(sizeof(long));
        if (!records[i].ptrValue) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                freeRecord(&records[j]);
            }
            free(records);
            return;
        }

        *(records[i].ptrValue) = (long)randomValue;

        pthread_mutex_unlock(&lock);

        logMemoryEvent("Allocated", records[i].ptrValue, sizeof(long));

        if (callback) {
            callback(&records[i]);
        }
    }

    int *inputNumbers = NULL;
    size_t capacity = 0;
    size_t count = 0;

    while (1) {
        int number;
        scanf("%d", &number);

        if (number == -1) break;

        if (count >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            inputNumbers = realloc(inputNumbers, capacity * sizeof(int));

            if (!inputNumbers) {
                printf("Memory reallocation failed.\n");
                free(offsets);
                free(keys);
                for (size_t i = 0; i < numRecords; ++i) {
                    freeRecord(&records[i]);
                }
                free(records);
                return;
