        inputNumbers[count++] = number;
    }

    if (count > 0) {
        int maxNumber = findMax(inputNumbers, count);
        printf("Maximum value from user input: %d\n", maxNumber);
    } else {
        printf("No valid numbers entered.\n");
    }

    free(inputNumbers);

    for (size_t i = 0; i < numRecords; ++i) {
        freeRecord(&records[i]);
    }

    logMemoryEvent("Freed", records, numRecords * sizeof(record));
    free(records);
    logMemoryEvent("Freed", offsets, offsetSize * sizeof(long));
    free(offsets);
    logMemoryEvent("Freed", keys, keySize * sizeof(int));
    free(keys);

    pthread_mutex_destroy(&lock);
}
