void processNodeCallback(dataNode* node);

// Synchronization
pthread_mutex_t treeMutex = PTHREAD_MUTEX_INITIALIZER;

dataNode* initializeDataNodes(size_t size, float seed) {
    pthread_mutex_lock(&treeMutex);

    dataNode* nodes = (dataNode*)malloc(size * sizeof(dataNode));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&treeMutex);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        nodes[i].value = generateSecureRandomFloat(seed + i);
        snprintf(nodes[i].identifier, MAX_STRING_SIZE, "Node_%zu", i);
        nodes[i].childNode = (i < size - 1) ? &nodes[i + 1] : NULL;
    }

    pthread_mutex_unlock(&treeMutex);
    return nodes;
}

void freeDataTree(dataNode* root) {
    if (!root) return;

    freeDataTree(root->childNode);
    free(root);
}

void addDataNode(dataNode** root, int parentIndex, float value, const char* identifier) {
    pthread_mutex_lock(&treeMutex);

    dataNode* newNode = (dataNode*)malloc(sizeof(dataNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&treeMutex);
        return;
    }

    newNode->value = generateSecureRandomFloat(value);
    strncpy(newNode->identifier, identifier, MAX_STRING_SIZE - 1);
    newNode->identifier[MAX_STRING_SIZE - 1] = '\0';
    newNode->childNode = NULL;

    if (parentIndex < 0 || !(*root)) {
        *root = newNode;
    } else {
        dataNode* parent = findNodeByIndex(*root, parentIndex);
        if (parent) {
            while (parent->childNode) {
                parent = parent->childNode;
            }
            parent->childNode = newNode;
        }
    }

    pthread_mutex_unlock(&treeMutex);
}

void traverseTree(dataNode* node, void (*callback)(dataNode*)) {
    if (!node || !callback) return;

    callback(node);

    traverseTree(node->childNode, callback);
}

dataNode* findNodeByIndex(dataNode* root, int index) {
    if (!root) return NULL;
    static int current = 0;

    if (current == index) return root;

    dataNode* result = findNodeByIndex(root->childNode, index);
    current++;
    return result ? result : NULL;
}

float generateSecureRandomFloat(float seed) {
    // Placeholder for secure random number generation
    return (rand() / (float)RAND_MAX) * seed;
}

void processNodeCallback(dataNode* node) {
    if (!node) return;

    printf("Processing Node: %s, Value: %.2f\n", node->identifier, node->value);
}

int main() {
    size_t initialSize = 5;
    float seed = 42.0;

    dataNode* root = initializeDataNodes(initialSize, seed);

    if (root) {
        traverseTree(root, processNodeCallback);

        addDataNode(&root, 2, seed + 1.0f, "New_Node");

        traverseTree(root, processNodeCallback);
        freeDataTree(root);
    }

    return 0;
}
