// Mutex for thread safety
pthread_mutex_t tree_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the tree
dataNode* initialize_tree(size_t size, unsigned int seed, void (*process_callback)(dataNode*)) {
    if (size == 0) return NULL;

    pthread_mutex_lock(&tree_mutex);

    dataNode *root = malloc(sizeof(dataNode));
    if (!root) {
        perror("Failed to allocate root node");
        pthread_mutex_unlock(&tree_mutex);
        return NULL;
    }

    secure_random_init(seed); // Initialize the random generator with a seed

    for (size_t i = 0; i < size; ++i) {
        dataNode *node = malloc(sizeof(dataNode));
        if (!node) {
            perror("Failed to allocate node");
            // Free previously allocated nodes
            while (root != NULL) {
                dataNode *temp = root;
                root = root->childNode;
                free(temp);
            }
            pthread_mutex_unlock(&tree_mutex);
            return NULL;
        }

        node->value = secure_random_float();  // Use the external library for random float generation
        snprintf(node->identifier, sizeof(node->identifier), "Node_%zu", i);

        if (process_callback) {
            process_callback(*node);  // Process each node with the callback function
        }

        dataNode *current = root;
        while (current->childNode != NULL) {
            current = current->childNode;
        }
        current->childNode = node;
    }

    pthread_mutex_unlock(&tree_mutex);
    return root;
}

// Function to traverse the tree in depth-first manner
void traverse_tree(dataNode *root, void (*traversal_callback)(dataNode*)) {
    if (!root) return;

    pthread_mutex_lock(&tree_mutex);

    dataNode *stack[1024];
    size_t top = 0;
    stack[top++] = root;

    while (top > 0) {
        dataNode *node = stack[--top];
        traversal_callback(*node);

        if (node->childNode != NULL) {
            stack[top++] = node->childNode;
        }
    }

    pthread_mutex_unlock(&tree_mutex);
}

// Function to add nodes dynamically
void add_nodes(dataNode **root, size_t count, unsigned int seed, void (*process_callback)(dataNode*)) {
    if (count == 0 || !root) return;

    pthread_mutex_lock(&tree_mutex);

    secure_random_init(seed); // Reinitialize with a new seed

    dataNode *current = *root;
    while (current->childNode != NULL) {
        current = current->childNode;
    }

    for (size_t i = 0; i < count; ++i) {
        dataNode *node = malloc(sizeof(dataNode));
        if (!node) {
            perror("Failed to allocate node");
            pthread_mutex_unlock(&tree_mutex);
            return;
        }

        node->value = secure_random_float();
        snprintf(node->identifier, sizeof(node->identifier), "Node_%zu", i);

        if (process_callback) {
            process_callback(*node);
        }

        current->childNode = node;
        current = node;
    }

    pthread_mutex_unlock(&tree_mutex);
}

// Function for periodic data integrity checks
void check_integrity(dataNode *root, void (*repair_callback)(dataNode*)) {
    if (!root) return;

    pthread_mutex_lock(&tree_mutex);

    // Example of a simple consistency check
    if (root->value < 0) {
        printf("Inconsistency detected at root\n");
        if (repair_callback) repair_callback(*root);
    }

    dataNode *current = root;
    while (current != NULL) {
        if (current->childNode && current->childNode->value < 0) {
            printf("Inconsistency detected in child node\n");
            if (repair_callback) repair_callback(*(current->childNode));
        }
        current = current->childNode;
    }

    pthread_mutex_unlock(&tree_mutex);
}

// Main function to demonstrate usage
int main() {
    dataNode *root = initialize_tree(5, 12345, NULL);

    // Example traversal callback
    void print_node(dataNode node) {
        printf("Value: %f, Identifier: %s\n", node.value, node.identifier);
    }

    traverse_tree(root, print_node);

    add_nodes(&root, 3, 67890, NULL);

    check_integrity(root, NULL);

    // Free the tree
    dataNode *current = root;
    while (current != NULL) {
        dataNode *temp = current;
        current = current->childNode;
        free(temp);
    }

    return 0;
}
