#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// External library for secure random number generation
#include "secure_random.h"

#define MAX_ID_LENGTH 50

typedef struct dataNode {
    float value;
    char id[MAX_ID_LENGTH];
    struct dataNode *childNode;
} dataNode;

typedef void (*processCallback)(dataNode *);

pthread_mutex_t treeMutex = PTHREAD_MUTEX_INITIALIZER;
atomic_int nodeCount = 0;

// Initialize the dataNodes with specified size
dataNode* initializeDataNodes(int initialSize, unsigned int seed) {
    pthread_mutex_lock(&treeMutex);

    if (initialSize <= 0) {
        fprintf(stderr, "Initial size must be greater than zero.\n");
        pthread_mutex_unlock(&treeMutex);
        return NULL;
    }

    dataNode *nodes = malloc(initialSize * sizeof(dataNode));
    if (!nodes) {
        perror("Failed to allocate memory for nodes");
        pthread_mutex_unlock(&treeMutex);
        return NULL;
    }

    secure_random_init(seed);

    for (int i = 0; i < initialSize; ++i) {
        nodes[i].value = secure_random_float(); // Using an external library function
        snprintf(nodes[i].id, MAX_ID_LENGTH, "Node%d", i);
        nodes[i].childNode = (i < initialSize - 1) ? &nodes[i + 1] : NULL;
    }

    pthread_mutex_unlock(&treeMutex);
    return nodes;
}

// Add a new node to the tree
void addDataNode(dataNode **head, processCallback callback) {
    pthread_mutex_lock(&treeMutex);

    int currentCount = atomic_fetch_add(&nodeCount, 1);

    dataNode *newNode = malloc(sizeof(dataNode));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        atomic_fetch_sub(&nodeCount, 1);
        pthread_mutex_unlock(&treeMutex);
        return;
    }

    newNode->value = secure_random_float();
    snprintf(newNode->id, MAX_ID_LENGTH, "Node%d", currentCount);
    newNode->childNode = NULL;

    if (*head == NULL) {
        *head = newNode;
    } else {
        dataNode *current = *head;
        while (current->childNode != NULL) {
            current = current->childNode;
        }
        current->childNode = newNode;
    }

    if (callback) {
        callback(newNode);
    }

    pthread_mutex_unlock(&treeMutex);
}

// Traverse the tree
void traverseTree(dataNode *node, void (*processFunc)(dataNode *)) {
    while (node != NULL) {
        processFunc(node);
        traverseTree(node->childNode, processFunc);
        node = /* mechanism to find next sibling if needed */;
    }
}

// Free the dataNodes
void freeDataNodes(dataNode **head) {
    pthread_mutex_lock(&treeMutex);

    while (*head != NULL) {
        dataNode *temp = (*head)->childNode;
        free(*head);
        *head = temp;
    }

    atomic_store(&nodeCount, 0);

    pthread_mutex_unlock(&treeMutex);
}

// Example callback function
void exampleCallback(dataNode *node) {
    printf("Processing node: %s with value %.2f\n", node->id, node->value);
}

int main() {
    dataNode *nodes = initializeDataNodes(10, 12345);
    if (!nodes) return EXIT_FAILURE;

    addDataNode(&nodes, exampleCallback);

    traverseTree(nodes, exampleCallback);

    freeDataNodes(&nodes);
    pthread_mutex_destroy(&treeMutex);

    return EXIT_SUCCESS;
}
```

