#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_POOL_SIZE 1024 * 1024  // 1MB memory pool
#define BLOCK_SIZE sizeof(long)       // Block size for memory pool

typedef struct {
    int value;
    char key[256];
    long* dynamic_long;
} record;

typedef void (*record_callback)(record*);

typedef struct MemoryPool {
    unsigned char data[MEMORY_POOL_SIZE];
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

static MemoryPool mem_pool = {{0}, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool() {
    pthread_mutex_lock(&mem_pool.lock);
    mem_pool.offset = 0;
    pthread_mutex_unlock(&mem_pool.lock);
}

void* memory_allocate(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mem_pool.lock);
        return NULL; // Pool is exhausted
    }
    void* ptr = &mem_pool.data[mem_pool.offset];
    mem_pool.offset += size;
    pthread_mutex_unlock(&mem_pool.lock);
    return ptr;
}

void cleanup_memory_pool() {
    pthread_mutex_destroy(&mem_pool.lock);
}

long random_range(long min, long max) {
    // Simple PRNG using rand for demonstration; replace with a secure RNG in production
    return (rand() % (max - min + 1)) + min;
}

