        cleanup_memory_pool();
        return -1; // Memory allocation failed
    }

    // Initialize offsets array
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }

    // Initialize keys array
    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = i;
    }

    // Seed the random number generator for reproducibility, if a seed value is provided elsewhere.
    // srand(seed_value);

    // Initialize records array
    for (size_t i = 0; i < records_size; ++i) {
        records[i].value = random_range(record_value_min, record_value_max);
