#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// External library headers (Assumed to be available)
#include "secure_rand.h"  // For secure_random()
#include "logger.h"       // For log_error(), log_info()

typedef struct {
    int value;
    char *key;
    long *long_ptr;
    time_t timestamp;
    _Bool flag;
    char event[50];
    int priority;
} Record;

// Function prototypes
