void process_record_callback(const Record *record);
void free_resources(Record **records, size_t num_records);

// Global lock for thread safety
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(Record **records, size_t num_records, int min_val, int max_val, unsigned seed) {
    pthread_mutex_lock(&record_lock);

    // Memory allocation
    *records = (Record *)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        log_error("Memory allocation for records failed");
        pthread_mutex_unlock(&record_lock);
        return;
    }

    secure_random_set_seed(seed);  // Set seed for reproducible results

    char default_event[] = "Default Event";
    int priority_value = 5;  // Default priority value

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = secure_random(min_val, max_val);

        (*records)[i].key = (char *)malloc(20 * sizeof(char));
        if ((*records)[i].key == NULL) {
            log_error("Memory allocation for key failed");
            free_resources(*records, i);
            pthread_mutex_unlock(&record_lock);
            return;
        }
        snprintf((*records)[i].key, 20, "Key_%zu", i);

        (*records)[i].long_ptr = (long *)malloc(sizeof(long));
        if ((*records)[i].long_ptr == NULL) {
            log_error("Memory allocation for long pointer failed");
            free((*records)[i].key);
            free_resources(*records, i);
            pthread_mutex_unlock(&record_lock);
            return;
        }

        (*records)[i].timestamp = time(NULL);
        strcpy((*records)[i].event, default_event);
        (*records)[i].flag = 1; // Default flag
        (*records)[i].priority = priority_value;

        process_record_callback(&(*records)[i]);
    }

    pthread_mutex_unlock(&record_lock);
}

void process_record_callback(const Record *record) {
    if (record == NULL) return;

    log_info("Processing record with value: %d", record->value);

    // Example of additional processing logic
    if (record->priority > 5) {
        log_error("High priority detected in processing");
    }
}

void free_resources(Record **records, size_t num_records) {
    if (!records || !*records) return;

    for (size_t i = 0; i < num_records; ++i) {
        if ((*records)[i].key != NULL) {
            free((*records)[i].key);
        }
        if ((*records)[i].long_ptr != NULL) {
            free((*records)[i].long_ptr);
        }
    }

    free(*records);
    *records = NULL;
}

// Example of usage
int main() {
    Record *records = NULL;
    initialize_records(&records, 10, 0, 100, 12345);

    // Use records...

    free_resources(&records, 10); // Clean up

    return 0;
}
