#include <pthread.h>
#include <stdint.h>

#define INITIAL_SIZE 10
#define MEMORY_LIMIT_MB (100 * 1024 * 1024) // Default memory limit: 100 MB

typedef struct {
    int value;
} Record;

typedef struct Node {
    int key;
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    size_t max_memory_usage;
} StorageSystem;

StorageSystem* create_system(size_t max_memory_usage) {
    StorageSystem* system = (StorageSystem*)malloc(sizeof(StorageSystem));
    if (!system) return NULL;

    system->head = NULL;
    system->size = 0;
    pthread_mutex_init(&system->lock, NULL);
    system->max_memory_usage = max_memory_usage;

    return system;
}

void destroy_system(StorageSystem* system) {
    if (system) {
        Node* current = system->head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&system->lock);
        free(system);
    }
}

void check_memory_usage(StorageSystem* system, size_t new_size) {
    if ((new_size + sizeof(Node)) * 1024 > system->max_memory_usage) {
        fprintf(stderr, "Memory limit exceeded!\n");
        exit(EXIT_FAILURE); // Handle more gracefully in a real application
    }
}

void add_record(StorageSystem* system, int key, Record record) {
    pthread_mutex_lock(&system->lock);

    Node** ptr = &system->head;
    while (*ptr && (*ptr)->key != key) {
        ptr = &(*ptr)->next;
    }

    if (!*ptr) { // Key not found
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for a new record.\n");
            pthread_mutex_unlock(&system->lock);
            return;
        }

        check_memory_usage(system, system->size + 1);

        *ptr = new_node;
        (*ptr)->key = key;
        (*ptr)->record = record;
        (*ptr)->next = NULL;
        system->size++;
    } else {
        (*ptr)->record = record; // Update existing
    }

    pthread_mutex_unlock(&system->lock);
}

Record* get_record(StorageSystem* system, int key) {
    pthread_mutex_lock(&system->lock);

    Node* current = system->head;
    while (current && current->key != key) {
        current = current->next;
    }

    Record* record = NULL;
    if (current) {
        record = &current->record;
    }

    pthread_mutex_unlock(&system->lock);
    return record;
}

void serialize_system(StorageSystem* system, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&system->lock);

    Node* current = system->head;
    while (current) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->record.value, sizeof(int), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&system->lock);
    fclose(file);
}

void deserialize_system(StorageSystem* system, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&system->lock);

    Node** ptr = &system->head;
    while (fread(ptr, sizeof(Node), 1, file)) { // Read one node at a time
        *ptr = (Node*)malloc(sizeof(Node));
        if (!*ptr) {
            fprintf(stderr, "Failed to allocate memory for deserialized record.\n");
            break;
        }

        fread(&(*ptr)->key, sizeof(int), 1, file);
        fread(&(*ptr)->record.value, sizeof(int), 1, file);

        ptr = &((*ptr)->next);
    }

    system->size = ptr - &(system->head); // Calculate size

    pthread_mutex_unlock(&system->lock);
    fclose(file);
}

void set_memory_limit(StorageSystem* system, size_t new_limit) {
    pthread_mutex_lock(&system->lock);

    system->max_memory_usage = new_limit;

    pthread_mutex_unlock(&system->lock);
}

int main() {
    StorageSystem* sys = create_system(MEMORY_LIMIT_MB);

    Record rec1 = {42};
    add_record(sys, 1, rec1);

    Record* rec = get_record(sys, 1);
    if (rec) {
        printf("Record: %d\n", rec->value);
    }

    serialize_system(sys, "data.bin");
    destroy_system(sys);

    sys = create_system(MEMORY_LIMIT_MB);
    deserialize_system(sys, "data.bin");

    set_memory_limit(sys, 200 * 1024 * 1024); // Increase memory limit

    destroy_system(sys);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: Uses a linked list to handle dynamic growth.
- **Thread Safety**: Utilizes `pthread_mutex_t` for concurrency control.
- **Memory Monitoring**: Checks total allocated memory against a predefined limit, with exit handling on exceedance.
- **Serialization/Deserialization**: Handles file I/O for saving/loading data.
- **Configuration Management**: Allows changing the maximum allowed memory usage dynamically.']

