    size_t size;
    pthread_mutex_t lock;
} collection;

int compare_int(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

long get_random_range(long min, long max) {
    return rand() % (max - min + 1) + min;
}

void initialize_rng() {
    srand(time(NULL));
}

collection* create_collection(size_t size, long offset_min, long offset_max, int key_min, int key_max) {
    if (size == 0 || offset_min >= offset_max || key_min >= key_max)
        return NULL;

    collection *coll = malloc(sizeof(collection));
    if (!coll)
        return NULL;

    coll->records = malloc(size * sizeof(record));
    coll->offsets = malloc(size * sizeof(long));
    coll->keys = malloc(size * sizeof(int));

    if (!coll->records || !coll->offsets || !coll->keys) {
        free(coll->records);
        free(coll->offsets);
        free(coll->keys);
        free(coll);
        return NULL;
    }

    pthread_mutex_init(&coll->lock, NULL);
    coll->size = size;

    for (size_t i = 0; i < size; ++i) {
        int key = get_random_range(key_min, key_max);
        int value = get_random_range(1, 100); // Adjust range as needed

        while (1) {
            pthread_mutex_lock(&coll->lock);

            int unique_key = 1;
            for (size_t j = 0; j < i; ++j) {
                if (key == coll->keys[j]) {
                    unique_key = 0;
                    break;
                }
            }

            if (unique_key) {
                coll->keys[i] = key;
                coll->records[i].key = key;
                coll->records[i].value = value;

                long offset = get_random_range(offset_min, offset_max);
                int unique_offset = 1;
                for (size_t j = 0; j < i; ++j) {
                    if (offset == coll->offsets[j]) {
                        unique_offset = 0;
                        break;
                    }
                }

                if (unique_offset) {
                    coll->offsets[i] = offset;
                    pthread_mutex_unlock(&coll->lock);
                    break;
                }
            } else {
                key = get_random_range(key_min, key_max);
            }

            pthread_mutex_unlock(&coll->lock);
        }
    }

    qsort(coll->keys, size, sizeof(int), compare_int);

    return coll;
}

void cleanup_collection(collection *coll) {
    if (coll) {
        free(coll->records);
        free(coll->offsets);
        free(coll->keys);
        pthread_mutex_destroy(&coll->lock);
        free(coll);
    }
}

int main() {
    initialize_rng();

    size_t collection_size = 10;
    long offset_min = 0, offset_max = 100;
    int key_min = 1, key_max = 50;

    collection *my_collection = create_collection(collection_size, offset_min, offset_max, key_min, key_max);

    if (!my_collection) {
        fprintf(stderr, "Failed to create collection\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < my_collection->size; ++i) {
        printf("Record %zu: Key = %d, Value = %d, Offset = %ld\n", 
               i, my_collection->records[i].key, my_collection->records[i].value, my_collection->offsets[i]);
    }

    cleanup_collection(my_collection);

    return EXIT_SUCCESS;
}
