#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    double number;
    char *text;
    int identifier;
} data_entry;

// Structure for managing memory allocation results and CURL context
struct MemoryAllocation {
    double* doublesArray;
    char** stringsArray;
    data_entry* entriesArray;
};

size_t write_callback(void* buffer, size_t size, size_t nmemb, void* userp) {
    // Cast the user pointer to our struct to pass back data
    struct MemoryAllocation *mem_alloc = (struct MemoryAllocation*)userp;

    // Allocate memory for incoming data if necessary
    char* data = realloc(mem_alloc->stringsArray[0], size * nmemb + 1);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 0;
    }

    memcpy(data + strlen(mem_alloc->stringsArray[0]), buffer, size * nmemb);
    data[size * nmemb] = '\0';
    mem_alloc->stringsArray[0] = data;

    return size * nmemb;
}

void free_memory(struct MemoryAllocation* mem_alloc, int entry_count) {
    if (mem_alloc->doublesArray) free(mem_alloc->doublesArray);
    for (int i = 0; i < entry_count; ++i) {
        if (mem_alloc->entriesArray[i].text) free(mem_alloc->entriesArray[i].text);
    }
    if (mem_alloc->stringsArray[0]) free(mem_alloc->stringsArray[0]);
    if (mem_alloc->entriesArray) free(mem_alloc->entriesArray);
}

int fetch_data_from_http(struct MemoryAllocation* mem_alloc, const char* url, int entry_count) {
    CURL *curl;
    CURLcode res;

    // Initialize CURL
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL\n");
        return -1;
    }

    // Set URL and write callback function
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)mem_alloc);

    // Implement retry logic with up to 3 attempts
    int attempts = 0;
    while (++attempts <= 3) {
        res = curl_easy_perform(curl);

        if (res == CURLE_OK) break;

        fprintf(stderr, "CURL failed: %s\n", curl_easy_strerror(res));
    }

    // Cleanup CURL
    curl_easy_cleanup(curl);

    return res != CURLE_OK ? -1 : 0;
}

int manage_memory_and_initialize(const char* url, int entry_count) {
    struct MemoryAllocation mem_alloc = {0};

