['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import threading

#define MAX_ATTEMPTS 3

typedef struct Node {
    char *key;
    double value;
    struct Node *next;
} Node;

typedef struct Cache {
    Node **buckets;
    size_t capacity;
    pthread_mutex_t *locks;
} Cache;

unsigned long custom_hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

Cache* create_cache(size_t capacity) {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!cache->buckets) {
        free(cache);
        return NULL;
    }

    cache->locks = (pthread_mutex_t*)malloc(capacity * sizeof(pthread_mutex_t));
    if (!cache->locks) {
        free(cache->buckets);
        free(cache);
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i)
        pthread_mutex_init(&cache->locks[i], NULL);

    return cache;
}

int insert_cache(Cache *cache, const char *key, double value) {
    unsigned long index = custom_hash(key) % cache->capacity;
    pthread_mutex_lock(&cache->locks[index]);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&cache->locks[index]);
        return -1;
    }

    new_node->key = strdup(key);
    new_node->value = value;

    if (!cache->buckets[index]) {
        cache->buckets[index] = new_node;
    } else {
        Node *current = cache->buckets[index];
        while (current->next)
            current = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&cache->locks[index]);
    return 0;
}

double* retrieve_cache(Cache *cache, const char *key) {
    unsigned long index = custom_hash(key) % cache->capacity;
    pthread_mutex_lock(&cache->locks[index]);

    Node *current = cache->buckets[index];
    while (current) {
        if (strcmp(current->key, key) == 0) {
            double *value = &current->value;
            pthread_mutex_unlock(&cache->locks[index]);
            return value;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->locks[index]);
    return NULL;
}

int delete_cache(Cache *cache, const char *key) {
    unsigned long index = custom_hash(key) % cache->capacity;
    pthread_mutex_lock(&cache->locks[index]);

    Node *current = cache->buckets[index];
    Node *prev = NULL;

    while (current) {
        if (strcmp(current->key, key) == 0) {
            if (prev)
                prev->next = current->next;
            else
                cache->buckets[index] = current->next;

            free(current->key);
            free(current);

            pthread_mutex_unlock(&cache->locks[index]);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&cache->locks[index]);
    return -1;
}

void cleanup_cache(Cache *cache) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        Node *current = cache->buckets[i];
        while (current) {
            Node *temp = current;
            current = current->next;
            free(temp->key);
            free(temp);
        }
    }

    free(cache->buckets);
    for (size_t i = 0; i < cache->capacity; ++i)
        pthread_mutex_destroy(&cache->locks[i]);

    free(cache->locks);
    free(cache);
}

void* attempt_allocate(size_t size, int *attempt) {
    void *ptr = malloc(size);
    if (!ptr && (*attempt)++ < MAX_ATTEMPTS) {
        sleep(1); // wait before retrying
        return attempt_allocate(size, attempt);
    }
    return ptr;
}
```']

