```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    time_t timestamp;
    int processed;
} metadata;

typedef struct {
    long *offsets;
    int *keys;
    size_t offset_count;
    size_t key_count;
    record *records;
    metadata *metadatas;
    size_t record_count;
    size_t initialized_record_count;
} data_structure;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_data_structure(data_structure *ds, size_t total_memory_limit, int min_value, int max_value) {
    pthread_mutex_lock(&lock);

    if (total_memory_limit < sizeof(size_t) * 4 + sizeof(long) + sizeof(int)) {
        pthread_mutex_unlock(&lock);
        return -1; // Insufficient memory limit for basic structure
    }

    size_t remaining_memory = total_memory_limit;

    ds->offset_count = 10;
    ds->key_count = 10;

    remaining_memory -= (sizeof(long) * ds->offset_count + sizeof(int) * ds->key_count);

    if (remaining_memory < sizeof(record) || remaining_memory < sizeof(metadata)) {
        pthread_mutex_unlock(&lock);
        return -1; // Insufficient memory for records or metadata
    }

    ds->record_count = 100;
    size_t record_memory_size = sizeof(record) * ds->record_count + sizeof(metadata) * ds->record_count;

    if (remaining_memory < record_memory_size) {
        pthread_mutex_unlock(&lock);
        return -1; // Insufficient memory for records and metadata
    }

    ds->offsets = malloc(sizeof(long) * ds->offset_count);
    ds->keys = malloc(sizeof(int) * ds->key_count);

    if (!ds->offsets || !ds->keys) {
        free(ds->offsets);
        free(ds->keys);
        pthread_mutex_unlock(&lock);
        return -1; // Memory allocation failure
    }

    ds->records = malloc(record_memory_size);
    ds->metadatas = (metadata *)((char *)ds->records + sizeof(record) * ds->record_count);

    if (!ds->records || !ds->metadatas) {
        free(ds->offsets);
        free(ds->keys);
        pthread_mutex_unlock(&lock);
        return -1; // Memory allocation failure
    }

    srand(time(NULL));

    int last_value = min_value - 1;
    for (size_t i = 0; i < ds->record_count; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (value == last_value);

        ds->records[i].value = value;
        ds->metadatas[i].timestamp = time(NULL);
        ds->metadatas[i].processed = 0;

        last_value = value;
    }

    // Sorting records by their values
    for (size_t i = 1; i < ds->record_count; ++i) {
        record key = ds->records[i];
        metadata key_meta = ds->metadatas[i];
        size_t j = i;

        while (j > 0 && ds->records[j - 1].value > key.value) {
            ds->records[j] = ds->records[j - 1];
            ds->metadatas[j] = ds->metadatas[j - 1];
            --j;
        }

        ds->records[j] = key;
        ds->metadatas[j] = key_meta;
    }

    ds->initialized_record_count = ds->record_count;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void free_data_structure(data_structure *ds) {
    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_lock` and `pthread_mutex_unlock` to ensure thread safety.
- **Memory Allocation**: Checks memory availability before allocating, ensuring limits are respected.
- **Error Handling**: Returns `-1` on failure due to insufficient memory or allocation errors.
- **Random Value Generation**: Ensures no two consecutive records have the same value.
- **Sorting**: Implements a simple insertion sort for sorting records by their values. Adjust complexity based on actual needs.

This code is designed to be part of a larger system, handling potential delays and ensuring minimal wait times through efficient checks and operations.']

