    adjustLogLevel(LOG_LEVEL_WARNING);

    logMessage(LOG_LEVEL_DEBUG, "This is a debug message");
    logMessage(LOG_LEVEL_ERROR, "An error occurred");

    cleanup();
    return 0;
}
