void* initialize_and_sort_records(size_t num_records, long max_offset_memory,
                                  int min_key_value, int max_key_value,
                                  int min_record_value, int max_record_value) {
    pthread_mutex_lock(&lock);

    size_t offset_size = sizeof(long) * num_records;
    size_t key_size = sizeof(int) * num_records;
    size_t record_size = sizeof(record) * num_records;

    if (offset_size + key_size + record_size > max_offset_memory) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    long* offsets = malloc(offset_size);
    int* keys = malloc(key_size);
    record* records = malloc(record_size);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand(time(NULL));

