['```c
#include <stdio.h>
#include <stdlib.h>
import threading

typedef struct {
    time_t timestamp;
    int message_id;
    int priority_level;
} Message;

typedef struct Metadata {
    _Bool processed_flag;
} Metadata;

struct MessageNode {
    Message data;
    Metadata meta;
    struct MessageNode* next;
};

typedef struct {
    char* username;
    int session_id;
    struct MessageNode* messages_head;
} UserSession;

typedef struct {
    UserSession* sessions;
    size_t num_sessions;
    size_t max_allocated_bytes;
    pthread_mutex_t lock; // for thread-safety
} SessionManager;

// Utility function to create a new message node
struct MessageNode* create_message_node(Message msg, _Bool processed) {
    struct MessageNode* node = (struct MessageNode*)malloc(sizeof(struct MessageNode));
    if (!node) return NULL;

    node->data = msg;
    node->meta.processed_flag = processed;
    node->next = NULL;

    return node;
}

// Function to add a message to a user session
_Bool add_message_to_session(SessionManager* manager, int session_id, Message new_msg) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_sessions; ++i) {
        UserSession* session = &manager->sessions[i];
        if (session->session_id == session_id) {
            struct MessageNode** current = &(session->messages_head);

            while (*current) {
                // Check memory limit
                size_t new_size = sizeof(struct MessageNode*) + 
                                  sizeof(struct MessageNode) +
                                  sizeof(Message) + 
                                  sizeof(Metadata);

                if ((manager->max_allocated_bytes - new_size) < 0) {
                    pthread_mutex_unlock(&manager->lock);
                    return _Bool(0); // Failed to add due to memory constraints
                }

                manager->max_allocated_bytes -= new_size;
                current = &((*current)->next);
            }

            struct MessageNode* new_node = create_message_node(new_msg, 0);
            if (!new_node) {
                pthread_mutex_unlock(&manager->lock);
                return _Bool(0); // Memory allocation failed
            }

            *current = new_node;
            pthread_mutex_unlock(&manager->lock);
            return _Bool(1); // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return _Bool(0); // Session not found
}

// Function to initialize session manager with memory constraints
SessionManager* init_session_manager(size_t num_sessions, size_t max_memory) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);

    // Estimate memory usage per session and messages space
    size_t estimated_per_session_size = sizeof(UserSession);
    manager->max_allocated_bytes = max_memory - (estimated_per_session_size * num_sessions);

    manager->sessions = (UserSession*)malloc(num_sessions * estimated_per_session_size);
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->num_sessions = num_sessions;

    for (size_t i = 0; i < num_sessions; ++i) {
        manager->sessions[i].username = strdup("default_user"); // Or fetch dynamically
        manager->sessions[i].session_id = i; // or assign unique IDs
        manager->sessions[i].messages_head = NULL;
    }

    return manager;
}

// Function to free session manager and all associated memory
void free_session_manager(SessionManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_sessions; ++i) {
        struct MessageNode* current = manager->sessions[i].messages_head;

        while (current) {
            struct MessageNode* temp = current;
            current = current->next;

