typedef enum { PENDING, COMPLETED } TaskStatus;

typedef struct {
    char description[256];
    time_t deadline;
    TaskStatus status;
} Task;

typedef struct {
    Task *tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TaskList;

// Callback type for custom processing
typedef void (*TaskCallback)(Task *);

// Function prototypes
int init_task_list(TaskList *list, size_t size, unsigned int seed, TaskCallback callback);
void free_task_list(TaskList *list);
size_t filter_tasks_by_status(const TaskList *list, TaskStatus status, Task **output);

static time_t generate_default_deadline(unsigned int seed) {
    // Use the external library to set a secure deadline
    return set_secure_deadline(seed);
}

int init_task_list(TaskList *list, size_t size, unsigned int seed, TaskCallback callback) {
    if (!list) return -1;

    pthread_mutex_init(&list->lock, NULL);

    list->tasks = (Task *)malloc(size * sizeof(Task));
    if (!list->tasks) {
        fprintf(stderr, "Memory allocation failed for task list.\n");
        return -1;
    }

    list->capacity = size;
    list->count = 0;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < size; ++i) {
        snprintf(list->tasks[i].description, sizeof(list->tasks[i].description), "Default Task %zu", i + 1);
        list->tasks[i].deadline = generate_default_deadline(seed);
        list->tasks[i].status = PENDING;

        if (callback) callback(&list->tasks[i]);
    }
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void free_task_list(TaskList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->tasks);
    list->tasks = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

size_t filter_tasks_by_status(const TaskList *list, TaskStatus status, Task **output) {
    if (!list || !output) return 0;

    size_t count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i].status == status) {
            output[count++] = &list->tasks[i];
        }
    }

    return count;
}

// Example callback function
void set_initial_priority(Task *task) {
    // Custom processing, e.g., setting priority based on deadline
}

int main() {
    TaskList list;
    if (init_task_list(&list, 10, 42, set_initial_priority) != 0) {
        return EXIT_FAILURE;
    }

    Task *filtered_tasks = malloc(list.count * sizeof(Task *));
    size_t pending_count = filter_tasks_by_status(&list, PENDING, filtered_tasks);

    printf("Pending tasks: %zu\n", pending_count);
    free(filtered_tasks);

    free_task_list(&list);
    return EXIT_SUCCESS;
}
