#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// External random number generator function prototype (dummy for illustration)
extern int external_rand(int min, int max);

typedef struct {
    int value;
    char key[256];
    long *pointer;
} record;

typedef void (*record_callback)(record*);

void initialize_data(long* offset, size_t offset_size,
                     int* keys, size_t keys_size,
                     record** records, size_t records_size,
                     size_t rows, size_t cols,
                     int rand_min, int rand_max,
                     unsigned int seed,
                     record_callback callback) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Seed the random number generator
    srand(seed);

    // Initialize offset array
    for (size_t i = 0; i < offset_size; ++i) {
        if (!pthread_mutex_trylock(&lock)) {
            offset[i] = i;
            pthread_mutex_unlock(&lock);
        }
    }

    // Initialize keys array
    for (size_t i = 0; i < keys_size; ++i) {
        if (!pthread_mutex_trylock(&lock)) {
            keys[i] = i;
            pthread_mutex_unlock(&lock);
        }
    }

    records[0] = malloc(rows * cols * sizeof(record));
    if (!records[0]) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        goto cleanup;
    }

    // Initialize record array
    for (size_t i = 0; i < rows * cols; ++i) {
        record* rec = &records[0][i];

        if (!pthread_mutex_trylock(&lock)) {
            int random_value = external_rand(rand_min, rand_max);
            snprintf(rec->key, sizeof(rec->key), "random_string_%zu", i);

            // Generate a random string
            for (size_t j = 0; j < strlen(rec->key); ++j) {
                rec->key[j] = 'a' + (rand() % 26);
            }

            rec->value = random_value;

            long* ptr = malloc(sizeof(long));
            if (!ptr) {
                fprintf(stderr, "Memory allocation failed for record pointer.\n");
                goto cleanup_partial;
            }
            *ptr = random_value;
            rec->pointer = ptr;

            // Invoke callback
            if (callback) {
                callback(rec);
            }

            pthread_mutex_unlock(&lock);
        } else {
            fprintf(stderr, "Mutex lock failed during record initialization.\n");
            goto cleanup_partial;
        }
    }

cleanup_partial:
    for (size_t i = 0; i < i; ++i) {
        free(records[0][i].pointer);
    }
    free(records[0]);

cleanup:
    pthread_mutex_destroy(&lock);

    // Free all allocated memory
    if (offset) free(offset);
    if (keys) free(keys);
    if (records && records[0]) free(records[0]);
}

// Example callback function
void example_callback(record* rec) {
    printf("Callback: record value = %d, key = %s\n", rec->value, rec->key);
}

int main() {
    size_t offset_size = 100;
    size_t keys_size = 100;
    size_t records_rows = 10;
    size_t records_cols = 10;

    long* offsets = malloc(offset_size * sizeof(long));
    int* key_array = malloc(keys_size * sizeof(int));
    record** rec_array = malloc(sizeof(record*));

    initialize_data(offsets, offset_size,
                    key_array, keys_size,
                    rec_array, 1,
                    records_rows, records_cols,
                    0, 100,
                    42,
                    example_callback);

    free(offsets);
    free(key_array);
    if (rec_array) {
        free(rec_array[0]);
        free(rec_array);
    }

    return 0;
}
```

