int addProfile(UserProfile* profiles, size_t* currentSize, size_t maxCapacity,
               const char* username, const char* email, int isActive,
               regex_t* emailRegex, void (*callback)(UserProfile*), 
               pthread_mutex_t* mutex);
void destroyProfiles(UserProfile* profiles, size_t size);
int validateEmail(const char* email, regex_t* emailRegex);

// Global variables for persistence (simple in-memory storage)
#define MAX_PROFILES 1024
UserProfile globalProfiles[MAX_PROFILES];
size_t currentGlobalSize = 0;
pthread_mutex_t globalMutex;

// Implementation of the createProfiles function
UserProfile* createProfiles(size_t size) {
    UserProfile* profiles = malloc(sizeof(UserProfile) * size);
    if (!profiles) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        profiles[i].username = NULL;
        profiles[i].email = NULL;
        profiles[i].isActive = 0;
    }

    // Initialize a simple mutex for thread safety
    pthread_mutex_init(&globalMutex, NULL);

    return profiles;
}

// Implementation of the addProfile function
int addProfile(UserProfile* profiles, size_t* currentSize, size_t maxCapacity,
               const char* username, const char* email, int isActive,
               regex_t* emailRegex, void (*callback)(UserProfile*),
               pthread_mutex_t* mutex) {
    if (!profiles || !username || !email || *currentSize >= maxCapacity)
        return -1;

    // Lock the mutex for thread safety
    pthread_mutex_lock(mutex);

    // Check for unique username and validate email
    for (size_t i = 0; i < *currentSize; ++i) {
        if (strcmp(profiles[i].username, username) == 0) {
            pthread_mutex_unlock(mutex);
            return -2; // Username must be unique
        }
    }

    if (!validateEmail(email, emailRegex)) {
        pthread_mutex_unlock(mutex);
        return -3; // Invalid email format
    }

    UserProfile newProfile;
    newProfile.username = strdup(username);
    newProfile.email = strdup(email);
    newProfile.isActive = isActive;

    profiles[*currentSize] = newProfile;

    if (callback) {
        callback(&profiles[*currentSize]);
    }

    ++(*currentSize);

    pthread_mutex_unlock(mutex);
    return 0;
}

// Implementation of the destroyProfiles function
void destroyProfiles(UserProfile* profiles, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(profiles[i].username);
        free(profiles[i].email);
    }
    free(profiles);

    pthread_mutex_destroy(&globalMutex);
}

// Implementation of the validateEmail function
int validateEmail(const char* email, regex_t* emailRegex) {
    return regexec(emailRegex, email, 0, NULL, 0) == 0;
}

// Function to filter profiles based on status
UserProfile* filterProfilesByStatus(UserProfile* profiles, size_t size, int isActive, size_t* resultSize) {
    UserProfile* result = malloc(sizeof(UserProfile) * size);
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    *resultSize = 0;

    for (size_t i = 0; i < size; ++i) {
        if (profiles[i].isActive == isActive) {
            result[(*resultSize)++] = profiles[i];
        }
    }

    // Resize the result array to actual size
    UserProfile* resizedResult = realloc(result, sizeof(UserProfile) * (*resultSize));
    if (!resizedResult) {
        free(result);
        return NULL;
    }

    return resizedResult;
}

// Function for persistence (simple in-memory storage)
void saveProfiles() {
    pthread_mutex_lock(&globalMutex);

    // Here you would implement logic to persist data,
    // e.g., writing to a file or using an in-memory database.

    pthread_mutex_unlock(&globalMutex);
}
