    ERROR,
    CRITICAL
} SeverityLevel;

// Log entry structure
typedef struct LogEntry {
    time_t timestamp;
    SeverityLevel severity;
    char *message;
    struct LogEntry *next; // For linked list
} LogEntry;

// Function pointer for custom processing of log entries
typedef void (*LogCallback)(LogEntry *);

// External library function for secure random number generation
extern unsigned int secure_random(void);

// Linked list structure to store log entries
