                         LogCallback callback, LogList *log_list);
LogEntry* create_log_entry(time_t timestamp, SeverityLevel severity, const char *message);
void free_log_list(LogList *log_list);

// Main function to parse and process logs
void parseAndProcessLogs(const char *filename, size_t max_entries, unsigned int seed,
                         LogCallback callback, LogList *log_list) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    // Initialize the random number generator
    srand(seed);

    // Initialize linked list and mutex
    log_list->head = NULL;
    pthread_mutex_init(&log_list->lock, NULL);

    char buffer[1024];
    time_t timestamp;
    SeverityLevel severity;
    const char *message;

    while (fgets(buffer, sizeof(buffer), file) && max_entries > 0) {
        // Parse the log entry from the buffer
        if (sscanf(buffer, "%ld %d %[^\n]", &timestamp, (int *)&severity, message) == 3) {
            // Apply custom processing callback if provided
            if (callback) {
                LogEntry *entry = create_log_entry(timestamp, severity, message);
                if (!entry) continue; // Handle memory allocation failure gracefully

                // Process the log entry with the callback
                callback(entry);

                // Add to linked list in a thread-safe manner
                pthread_mutex_lock(&log_list->lock);
                entry->next = log_list->head;
                log_list->head = entry;
                max_entries--;
                pthread_mutex_unlock(&log_list->lock);
            }
        }
    }

    fclose(file);
}

// Function to create a new log entry
LogEntry* create_log_entry(time_t timestamp, SeverityLevel severity, const char *message) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    entry->severity = severity;
    entry->message = strdup(message);
    entry->next = NULL;

    if (!entry->message) {
        free(entry);
        return NULL;
    }

    return entry;
}

// Function to free all allocated memory in the log list
void free_log_list(LogList *log_list) {
    pthread_mutex_lock(&log_list->lock);

    LogEntry *current = log_list->head;
    while (current) {
        LogEntry *next = current->next;
        free(current->message);
        free(current);
        current = next;
    }

    log_list->head = NULL;
    pthread_mutex_unlock(&log_list->lock);
    pthread_mutex_destroy(&log_list->lock);
}
