#include <string.h>
#include <pthread.h>

typedef struct {
    char *timestamp;
    char *severity;
    char *message;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node* next;
} ListNode;

typedef struct {
    ListNode* head;
    size_t count;
    pthread_mutex_t lock;
} LogList;

typedef void (*PreprocessCallback)(char*);

LogList* create_log_list() {
    LogList* log_list = malloc(sizeof(LogList));
    if (log_list) {
        log_list->head = NULL;
        log_list->count = 0;
        pthread_mutex_init(&log_list->lock, NULL);
    }
    return log_list;
}

void destroy_log_entry(LogEntry* entry) {
    free(entry->timestamp);
    free(entry->severity);
    free(entry->message);
    free(entry);
}

void add_log_entry(LogList* log_list, LogEntry* entry) {
    pthread_mutex_lock(&log_list->lock);

    ListNode* new_node = malloc(sizeof(ListNode));
    if (new_node) {
        new_node->entry = *entry;
        new_node->next = log_list->head;
        log_list->head = new_node;
        log_list->count++;
    }

    pthread_mutex_unlock(&log_list->lock);
}

void free_log_list(LogList* log_list) {
    ListNode* current = log_list->head;
    while (current) {
        ListNode* next = current->next;
        destroy_log_entry(&current->entry);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&log_list->lock);
    free(log_list);
}

void parseAndProcessLogs(const char* filename, PreprocessCallback preprocess) {
