        sscanf(buffer, "%ms %ms %[^\n]", &entry.timestamp, &entry.severity, &entry.message);

        if (preprocess) {
            preprocess(entry.message);
        }

        add_log_entry(log_list, &entry);
    }

    fclose(file);

    // Process log entries for statistics or other purposes
    ListNode* current = log_list->head;
    while (current) {
        // Example: Print each entry's severity and message
        printf("Severity: %s, Message: %s\n", current->entry.severity, current->entry.message);
        current = current->next;
    }

    free_log_list(log_list);
}

void example_preprocess(char* message) {
    // Custom preprocessing logic, e.g., trimming whitespace
    char* end = message + strlen(message) - 1;
    while (end > message && *end == ' ') {
        *end-- = '\0';
    }
}

int main() {
    parseAndProcessLogs("server.log", example_preprocess);
    return 0;
}
