['Below is an implementation of the `parseAndProcessLogs` function in C that handles log file parsing and statistical analysis, ensuring thread safety and efficient memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_DEBUG
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel severity;
    char *message;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
} LogQueue;

typedef struct {
    int info_count;
    int warning_count;
    int error_count;
    int debug_count;
    double avg_duration_info;
    double avg_duration_warning;
    double avg_duration_error;
    double avg_duration_debug;
} LogStats;

LogQueue log_queue = {NULL, PTHREAD_MUTEX_INITIALIZER};
LogStats stats = {0};

void enqueue_log(LogEntry *entry) {
    pthread_mutex_lock(&log_queue.lock);
    entry->next = log_queue.head;
    log_queue.head = entry;
    pthread_mutex_unlock(&log_queue.lock);
}

LogEntry* dequeue_log() {
    LogEntry *entry;
    pthread_mutex_lock(&log_queue.lock);
    if (log_queue.head) {
        entry = log_queue.head;
        log_queue.head = entry->next;
    } else {
        entry = NULL;
    }
    pthread_mutex_unlock(&log_queue.lock);
    return entry;
}

void parseAndProcessLogs(const char *filename, LogLevel min_severity) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t last_timestamp[4] = {0};
    int count[4] = {0};

    while (1) {
        LogEntry *entry = malloc(sizeof(LogEntry));
        if (!entry) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            return;
        }

        char buffer[256];
        if (fscanf(file, "%ld %d %[^\n]\n", &entry->timestamp, (int*)&entry->severity, buffer) != 3) {
            free(entry);
            break;
        }

        entry->message = strdup(buffer);

        if (entry->severity < min_severity) {
            free(entry->message);
            free(entry);
            continue;
        }

        enqueue_log(entry);

        int idx = entry->severity - LOG_INFO;
        stats.count[idx]++;
        count[idx]++;

        double duration = 0.0;
        if (last_timestamp[idx]) {
            duration = difftime(entry->timestamp, last_timestamp[idx]);
        }
        stats.avg_duration_info += duration / count[0];
        stats.avg_duration_warning += duration / count[1];
        stats.avg_duration_error += duration / count[2];
        stats.avg_duration_debug += duration / count[3];

        last_timestamp[idx] = entry->timestamp;
    }

    fclose(file);
}

void free_log_queue() {
    LogEntry *entry, *tmp;
    while ((entry = dequeue_log())) {
        tmp = entry;
        free(entry->message);
        entry = entry->next;
        free(tmp);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log_file> [min_severity]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    LogLevel min_severity = LOG_INFO;

    if (argc > 2) {
        int severity_level;
        if (sscanf(argv[2], "%d", &severity_level) == 1 && severity_level >= LOG_INFO && severity_level <= LOG_DEBUG) {
            min_severity = (LogLevel)severity_level;
        }
    }

    parseAndProcessLogs(filename, min_severity);
    free_log_queue();

    return EXIT_SUCCESS;
}
```

