#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    PREFERENCE_TYPE_STRING,
    PREFERENCE_TYPE_INTEGER,
    PREFERENCE_TYPE_BOOLEAN
} PreferenceValueType;

typedef struct {
    char *name;
    PreferenceValueType value_type;
    void *default_value;
    void *current_value;
    char *dns_address; // Only applicable if DNS is relevant for a preference
} Preference;

#define INITIAL_SIZE 10
#define CACHE_SIZE 5

typedef struct {
    Preference *preferences;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PreferenceManager;

typedef void (*PreferenceCallback)(Preference *);

// Utility function to perform DNS resolution (mocked for this example)
int resolve_dns(const char *hostname, char *dns_address) {
    // Mock DNS resolution
    if (strcmp(hostname, "example.com") == 0) {
        strcpy(dns_address, "93.184.216.34");
        return 0;
    }
    return -1; // Indicate failure
}

void initialize_preferences(PreferenceManager *manager, size_t min_size, size_t max_size) {
    pthread_mutex_lock(&manager->lock);

    if (min_size > manager->capacity || manager->count == 0) {
        size_t new_capacity = (manager->capacity < INITIAL_SIZE) ? INITIAL_SIZE : manager->capacity * 2;
        if (new_capacity < min_size) new_capacity = min_size;

        Preference *new_preferences = realloc(manager->preferences, new_capacity * sizeof(Preference));
        if (!new_preferences) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->preferences = new_preferences;
        manager->capacity = new_capacity;
    }

    for (size_t i = manager->count; i < min_size && i < max_size; ++i) {
        manager->preferences[i].name = NULL;
        manager->preferences[i].value_type = PREFERENCE_TYPE_STRING;
        manager->preferences[i].default_value = strdup("default");
        manager->preferences[i].current_value = manager->preferences[i].default_value;
        manager->preferences[i].dns_address = NULL;

        char dns[INET6_ADDRSTRLEN];
        if (resolve_dns(manager->preferences[i].name, dns) == 0) {
            manager->preferences[i].dns_address = strdup(dns);
        }
    }

    manager->count = min_size;
    pthread_mutex_unlock(&manager->lock);
}

void add_user_preference(PreferenceManager *manager, const char *input_line, PreferenceCallback callback) {
    if (strcmp(input_line, "exit") == 0) return;

    char name[256], value[256];
    int type;
    if (sscanf(input_line, "%255[^:]:%d:%255s", name, &type, value) != 3) {
        fprintf(stderr, "Invalid input format\n");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        initialize_preferences(manager, manager->count + 1, manager->capacity * 2);
    }

    Preference *pref = &manager->preferences[manager->count++];
    pref->name = strdup(name);
    pref->value_type = type;

    switch (type) {
        case PREFERENCE_TYPE_STRING:
            free(pref->current_value);
            pref->current_value = strdup(value);
            break;
        case PREFERENCE_TYPE_INTEGER: {
            int *int_val = malloc(sizeof(int));
            if (!int_val || sscanf(value, "%d", int_val) != 1) {
                fprintf(stderr, "Invalid integer value\n");
                free(int_val);
                break;
            }
            free(pref->current_value);
            pref->current_value = int_val;
            break;
        }
        case PREFERENCE_TYPE_BOOLEAN: {
            if (strcmp(value, "true") == 0 || strcmp(value, "false") == 0) {
                bool *bool_val = malloc(sizeof(bool));
                *bool_val = (strcmp(value, "true") == 0);
                free(pref->current_value);
                pref->current_value = bool_val;
            } else {
                fprintf(stderr, "Invalid boolean value\n");
            }
            break;
        }
    }

    if (callback) callback(pref);

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_preferences(PreferenceManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->preferences[i].name);
        if (manager->preferences[i].value_type == PREFERENCE_TYPE_STRING)
            free(manager->preferences[i].current_value);
        else
            free(manager->preferences[i].current_value);

        free(manager->preferences[i].dns_address);
    }

    free(manager->preferences);
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    PreferenceManager manager = { .preferences = NULL, .capacity = 0, .count = 0 };
    pthread_mutex_init(&manager.lock, NULL);

    char input_line[512];
    while (fgets(input_line, sizeof(input_line), stdin)) {
        add_user_preference(&manager, input_line, NULL);
    }

    cleanup_preferences(&manager);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```']

