typedef struct {
    char *key;
    int id;
    char **values;
} Record;

typedef struct {
    Record **records;
    size_t row_count;
    size_t column_count;
    pthread_mutex_t lock;
} DataTable;

// Initialize data table
DataTable* init_data_table(size_t rows, size_t cols) {
    DataTable *table = malloc(sizeof(DataTable));
    table->row_count = rows;
    table->column_count = cols;
    table->records = calloc(rows, sizeof(Record *));
    pthread_mutex_init(&table->lock, NULL);

    for (size_t i = 0; i < rows; ++i) {
        table->records[i] = malloc(cols * sizeof(Record));
        for (size_t j = 0; j < cols; ++j) {
            table->records[i][j].key = strdup("default_key");
            table->records[i][j].id = -1;
            table->records[i][j].values = calloc(cols, sizeof(char *));
            for (size_t k = 0; k < cols; ++k) {
                table->records[i][j].values[k] = strdup("default_value");
            }
        }
    }
    return table;
}

// Add record
void add_record(DataTable *table, size_t index, const char *key, int id, char **field_values) {
    pthread_mutex_lock(&table->lock);
    if (index < table->row_count) {
        Record *record = &table->records[index][0];
        free(record->key);
        record->key = strdup(key);
        record->id = id;
        for (size_t i = 0; i < table->column_count; ++i) {
            free(record->values[i]);
            record->values[i] = field_values ? strdup(field_values[i]) : strdup("default_value");
        }
    }
    pthread_mutex_unlock(&table->lock);
}

// Remove record
void remove_record(DataTable *table, size_t index) {
    pthread_mutex_lock(&table->lock);
    if (index < table->row_count) {
        Record *record = &table->records[index][0];
        free(record->key);
        for (size_t i = 0; i < table->column_count; ++i) {
            free(record->values[i]);
        }
        free(record->values);
    }
    pthread_mutex_unlock(&table->lock);
}

// Update record
void update_record(DataTable *table, size_t index, const char *key, int id, char **field_values) {
    pthread_mutex_lock(&table->lock);
    if (index < table->row_count) {
        Record *record = &table->records[index][0];
        free(record->key);
        record->key = strdup(key);
        record->id = id;
        for (size_t i = 0; i < table->column_count; ++i) {
            free(record->values[i]);
            record->values[i] = field_values ? strdup(field_values[i]) : strdup("default_value");
        }
    }
    pthread_mutex_unlock(&table->lock);
}

// Search records by key or ID
void search_records(DataTable *table, const char *key, int id) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
        Record *record = &table->records[i][0];
        if ((key && strstr(record->key, key)) || (id == record->id)) {
            printf("Found: Key=%s, ID=%d\n", record->key, record->id);
        }
    }
    pthread_mutex_unlock(&table->lock);
}

// Log modifications
void log_modification(const char *message) {
    // Simple logging mechanism
    printf("Log: %s\n", message);
}

// Serialize data table to file
void serialize_data_table(DataTable *table, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
        Record *record = &table->records[i][0];
        fprintf(file, "%s,%d,", record->key, record->id);
        for (size_t j = 0; j < table->column_count; ++j) {
            fprintf(file, "%s", record->values[j]);
            if (j < table->column_count - 1) fprintf(file, ",");
        }
        fputc('\n', file);
    }
    pthread_mutex_unlock(&table->lock);
    fclose(file);
}

// Deserialize data table from file
void deserialize_data_table(DataTable *table, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    pthread_mutex_lock(&table->lock);
    char line[1024];
    size_t i = 0;
    while (fgets(line, sizeof(line), file)) {
        if (i >= table->row_count) break;
        Record *record = &table->records[i][0];

        // Parse key and ID
        char *token = strtok(line, ",");
        record->key = strdup(token);
        token = strtok(NULL, ",");
        record->id = atoi(token);

        // Parse field values
        for (size_t j = 0; j < table->column_count; ++j) {
            token = strtok(NULL, ",\n");
            free(record->values[j]);
            record->values[j] = strdup(token);
        }
        i++;
    }
    pthread_mutex_unlock(&table->lock);
    fclose(file);
}

// Free data table
void free_data_table(DataTable *table) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
        Record *record = &table->records[i][0];
        free(record->key);
        for (size_t j = 0; j < table->column_count; ++j) {
            free(record->values[j]);
        }
        free(record->values);
    }
    free(table->records);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    DataTable *table = init_data_table(10, 3);

    char *field_values[] = {"value1", "value2", "value3"};
    add_record(table, 0, "key1", 123, field_values);

    search_records(table, "key1", -1);
    serialize_data_table(table, "data.txt");
    deserialize_data_table(table, "data.txt");

    free_data_table(table);
    return 0;
}
