```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_MEMORY 8192 // 8KB limit

typedef struct {
    int key;
    long offset;
    char status; // Metadata for processing status
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    FILE *log_file;
} DataTable;

// Function prototypes
DataTable* initialize_table(size_t initial_capacity, void (*init_func)(Record *));
void add_record(DataTable *table, int key, long offset, char status);
int remove_record(DataTable *table, int key);
void update_record(DataTable *table, int key, long offset, char status);
void iterate_forward(const DataTable *table, void (*callback)(const Record *));
void iterate_reverse(const DataTable *table, void (*callback)(const Record *));
Record* search_record_by_key(const DataTable *table, int partial_key);
Record* search_record_by_offset(const DataTable *table, long partial_offset);

// Logging utility
static void log_action(DataTable *table, const char *action) {
    if (table->log_file) {
        fprintf(table->log_file, "%s\n", action);
        fflush(table->log_file);
    }
}

// Initialize table with specified capacity and custom init function
DataTable* initialize_table(size_t initial_capacity, void (*init_func)(Record *)) {
    DataTable *table = malloc(sizeof(DataTable));
    if (!table) return NULL;

    size_t record_size = sizeof(Record);
    if (record_size * initial_capacity > MAX_MEMORY) {
        fprintf(stderr, "Memory limit exceeded\n");
        free(table);
        return NULL;
    }

    table->records = calloc(initial_capacity, record_size);
    if (!table->records) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->count = 0;

    // Open log file
    table->log_file = fopen("data_table.log", "a");
    if (!table->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        free(table->records);
        free(table);
        return NULL;
    }

    // Initialize records with custom function or default values
    for (size_t i = 0; i < initial_capacity; ++i) {
        if (init_func) {
            init_func(&table->records[i]);
        } else {
            table->records[i].key = -1; // Default uninitialized value
            table->records[i].offset = 0;
            table->records[i].status = '\0';
        }
    }

    log_action(table, "Table initialized");
    return table;
}

// Add a record to the table
void add_record(DataTable *table, int key, long offset, char status) {
    if (table->count >= table->capacity) {
        size_t new_capacity = table->capacity * 2;
        if (sizeof(Record) * new_capacity > MAX_MEMORY) return;

        Record *new_records = realloc(table->records, new_capacity * sizeof(Record));
        if (!new_records) return;

        table->records = new_records;
        table->capacity = new_capacity;
    }

    for (size_t i = 0; i < table->count; ++i) {
        if (table->records[i].key == key) return; // Key must be unique
    }

    Record *new_record = &table->records[table->count++];
    new_record->key = key;
    new_record->offset = offset;
    new_record->status = status;

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Added record: Key=%d, Offset=%ld", key, offset);
    log_action(table, log_msg);
}

// Remove a record by key
int remove_record(DataTable *table, int key) {
    for (size_t i = 0; i < table->count; ++i) {
        if (table->records[i].key == key) {
            memmove(&table->records[i], &table->records[i + 1],
                    (table->count - i - 1) * sizeof(Record));
            table->count--;
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Removed record: Key=%d", key);
            log_action(table, log_msg);
            return 0; // Success
        }
    }
    return -1; // Record not found
}

// Update an existing record
void update_record(DataTable *table, int key, long offset, char status) {
    for (size_t i = 0; i < table->count; ++i) {
        if (table->records[i].key == key) {
            table->records[i].offset = offset;
            table->records[i].status = status;

            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Updated record: Key=%d", key);
            log_action(table, log_msg);
            return;
        }
    }
}

// Iterate forward over the records
void iterate_forward(const DataTable *table, void (*callback)(const Record *)) {
    for (size_t i = 0; i < table->count; ++i) {
        callback(&table->records[i]);
    }
}

// Iterate reverse over the records
void iterate_reverse(const DataTable *table, void (*callback)(const Record *)) {
    for (int i = table->count - 1; i >= 0; --i) {
        callback(&table->records[i]);
    }
}

// Search record by partial key match
Record* search_record_by_key(const DataTable *table, int partial_key) {
    for (size_t i = 0; i < table->count; ++i) {
        if ((table->records[i].key & partial_key) == partial_key) {
            return &table->records[i];
        }
    }
    return NULL;
}

// Search record by partial offset match
Record* search_record_by_offset(const DataTable *table, long partial_offset) {
    for (size_t i = 0; i < table->count; ++i) {
        if ((table->records[i].offset & partial_offset) == partial_offset) {
            return &table->records[i];
        }
    }
    return NULL;
}

// Cleanup function
void cleanup_table(DataTable *table) {
    if (table) {
        free(table->records);
        fclose(table->log_file);
        free(table);
    }
}
