#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

// External library for secure random number generation
extern int secure_random_int(int min, int max);

typedef struct {
    int timestamp;
    int status_flag;
    struct Record* record;
} Event;

typedef struct {
    int random_value;
    char key[256];
    long* dynamic_long;
    Event* event;
} Record;

// Define a memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    void* blocks;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (!pool) return NULL;

    pthread_mutex_lock(&pool->lock);
    void* block = pool->blocks; // Simplified allocation logic
    pool->blocks += pool->block_size;
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->blocks);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

void initialize_data_structure(long offset[], int key[], size_t num_offsets, Record** records, Event** events, size_t num_records, int min_rand_val, int max_rand_val, void (*callback)(Record*, Event*)) {
    if (!records || !events) return;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    MemoryPool* pool = create_memory_pool(sizeof(Record), num_records);

    // Initialize offset and key arrays
    for (size_t i = 0; i < num_offsets; ++i) {
        offset[i] = i;
        key[i] = i;
    }

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = (Record*)allocate_from_pool(pool);
        Event* event = (Event*)allocate_from_pool(pool);

        if (!record || !event) {
            printf("Memory allocation failed at iteration %zu\n", i);
            continue;
        }

        record->random_value = secure_random_int(min_rand_val, max_rand_val);
        snprintf(record->key, sizeof(record->key), "Key_%zu", i);
        record->dynamic_long = (long*)malloc(sizeof(long));
        if (!record->dynamic_long) {
            printf("Failed to allocate dynamic long at iteration %zu\n", i);
            continue;
        }
        *record->dynamic_long = 0;

        event->timestamp = time(NULL);
        event->status_flag = 1;
        event->record = record;

        record->event = event;

        if (callback) {
            callback(record, event);
        }

        records[i] = record;
        events[i] = event;
    }

    free_memory_pool(pool);

    // Verify memory deallocation
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]) {
            if (records[i]->dynamic_long) free(records[i]->dynamic_long);
            free(records[i]);
        }
        free(events[i]);
    }

    printf("All allocated memory has been properly released.\n");
}

void process_record(Record* record, Event* event) {
    printf("Processing Record: %s, Random Value: %d\n", record->key, record->random_value);
    printf("Event Timestamp: %d, Status Flag: %d\n", event->timestamp, event->status_flag);
}

int main() {
    size_t num_offsets = 10;
    long offset[num_offsets];
    int key[num_offsets];

    size_t num_records = 5;
    Record* records[num_records];
    Event* events[num_records];

    initialize_data_structure(offset, key, num_offsets, records, events, num_records, 0, 100, process_record);

    return 0;
}
```

### Key Points:
- **Memory Pool**: A simple memory pool is used for efficient allocation.
- **Concurrency**: Mutex locks ensure thread safety during allocations.
- **Error Handling**: Logs errors when allocations fail.
- **Callback Functionality**: Allows custom processing of records and events.
- **Resource Management**: Ensures all allocated memory is freed.']

