#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *imsi;
    int id;
    char **nasMessageSequenceNumber;
} DataRow;

typedef struct {
    DataRow **rows;
    size_t row_count;
    size_t col_count;
    pthread_rwlock_t lock;
} DataTable;

void init_data_table(DataTable *table, size_t rows, size_t cols) {
    table->row_count = rows;
    table->col_count = cols;
    table->rows = malloc(rows * sizeof(DataRow*));
    pthread_rwlock_init(&table->lock, NULL);

    for (size_t i = 0; i < rows; ++i) {
        table->rows[i] = malloc(cols * sizeof(DataRow));
        for (size_t j = 0; j < cols; ++j) {
            table->rows[i][j].imsi = strdup("default_imsi");
            table->rows[i][j].id = -1;
            table->rows[i][j].nasMessageSequenceNumber = malloc(10 * sizeof(char*));
            for (size_t k = 0; k < 10; ++k) {
                table->rows[i][j].nasMessageSequenceNumber[k] = strdup("default_value");
            }
        }
    }
}

void free_data_table(DataTable *table) {
    pthread_rwlock_wrlock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
        for (size_t j = 0; j < table->col_count; ++j) {
            free(table->rows[i][j].imsi);
            for (size_t k = 0; k < 10; ++k) {
                free(table->rows[i][j].nasMessageSequenceNumber[k]);
            }
            free(table->rows[i][j].nasMessageSequenceNumber);
        }
        free(table->rows[i]);
    }
    free(table->rows);
    pthread_rwlock_destroy(&table->lock);
}

void add_record(DataTable *table, const char *imsi, int id) {
    pthread_rwlock_wrlock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
        if (table->rows[i][0].id == -1) { // Find an empty slot
            DataRow *new_row = &table->rows[i][0];
            new_row->imsi = strdup(imsi);
            new_row->id = id;
            break;
        }
    }
    pthread_rwlock_unlock(&table->lock);
}

void update_record(DataTable *table, const char *imsi, int new_id) {
    pthread_rwlock_wrlock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
        DataRow *row = &table->rows[i][0];
        if (strcmp(row->imsi, imsi) == 0) {
            row->id = new_id;
            break;
        }
    }
    pthread_rwlock_unlock(&table->lock);
}

void remove_record(DataTable *table, const char *imsi) {
    pthread_rwlock_wrlock(&table->lock);
    for (size_t i = 0; i < table->row_count; ++i) {
