    for (size_t i = table->row_count; i-- > 0;) {
        DataRow *row = &table->rows[i][0];
        printf("Reverse Iteration - IMSI: %s, ID: %d\n", row->imsi, row->id);
    }
    pthread_rwlock_unlock(&table->lock);
}

