size_t readIntegers(int **array, size_t initialSize) {
    *array = malloc(initialSize * sizeof(int));
    if (!*array) return 0;

    size_t count = 0;
    while (1) {
        int input;
        if (scanf("%d", &input) != 1 || input == -1) break; // Sentinel value

        if (count >= initialSize) {
            initialSize *= 2;
            *array = realloc(*array, initialSize * sizeof(int));
            if (!*array) return count;  // Return current size on failure
        }

        (*array)[count++] = input;
    }

    // Shrink to fit the actual number of elements
    *array = realloc(*array, count * sizeof(int));

    return count;
}

int findMaxInteger(const int *array, size_t size) {
    if (!array || size == 0) return -1;

    int maxVal = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > maxVal) {
            maxVal = array[i];
        }
    }

    return maxVal;
}

