distributed_cache_manager_t* distributedCacheManager(size_t initial_capacity, size_t buffer_size) {
    distributed_cache_manager_t *manager = (distributed_cache_manager_t *)malloc(sizeof(distributed_cache_manager_t));
    manager->entries = (cache_entry_t *)calloc(initial_capacity, sizeof(cache_entry_t));
    manager->capacity = initial_capacity;

    rand_init(time(NULL)); // Seed with current time for reproducibility

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&manager->entries[i].lock, NULL);
        manager->entries[i].key = strdup("default_key");
        manager->entries[i].value = strdup("default_value");
        manager->entries[i].expiration_timestamp = time(NULL) + 3600; // Default expiration of 1 hour
        manager->entries[i].buffer_size = buffer_size;
        manager->entries[i].buffer = (char *)malloc(buffer_size);
        memset(manager->entries[i].buffer, 0, buffer_size);
        manager->entries[i].identifier = rand_get();
    }

    pthread_mutex_init(&manager->global_lock, NULL);

    // Statistical tests for random number generator quality
    statistical_tests();

    return manager;
}

void cache_entry_callback(distributed_cache_manager_t *manager, size_t index, cache_callback_t callback) {
    if (index < manager->capacity) {
        cache_entry_t *entry = &manager->entries[index];
        pthread_mutex_lock(&entry->lock);
        callback(entry); // Custom processing
        pthread_mutex_unlock(&entry->lock);
    }
}

void free_cache(distributed_cache_manager_t *manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        pthread_mutex_destroy(&manager->entries[i].lock);
        if (manager->entries[i].key) free(manager->entries[i].key);
        if (manager->entries[i].value) free(manager->entries[i].value);
        if (manager->entries[i].buffer) free(manager->entries[i].buffer);
    }
    pthread_mutex_destroy(&manager->global_lock);
    free(manager->entries);
    free(manager);
}

void cleanup_on_exit(distributed_cache_manager_t *manager) {
    // Set up signal handlers to call this function on exit
    atexit(() => free_cache(manager));
}

#ifdef __cplusplus
}
#endif

