#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long *offset;
    int key;
} record;

record* read_offsets_and_keys(const char *offsets_filename, const char *keys_filename, size_t *num_records) {
    FILE *file;
    long *offsets = NULL;
    int *keys = NULL;
    size_t offsets_size = 0, keys_size = 0;

    // Read and validate offsets.txt
    file = fopen(offsets_filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", offsets_filename);
        return NULL;
    }

    while (fscanf(file, "%ld", &offsets_size) == 1) {
        if (offsets_size < 0 || offsets_size > LONG_MAX) {
            fprintf(stderr, "Invalid offset value found in %s\n", offsets_filename);
            fclose(file);
            return NULL;
        }

        long *temp = realloc(offsets, offsets_size * sizeof(long));
        if (!temp) {
            fprintf(stderr, "Memory allocation error for offsets array\n");
            free(offsets);
            fclose(file);
            return NULL;
        }
        offsets = temp;
    }

    if (ferror(file)) {
        fprintf(stderr, "Error reading %s\n", offsets_filename);
        free(offsets);
        fclose(file);
        return NULL;
    }

    fclose(file);

    // Read and validate keys.txt
    file = fopen(keys_filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", keys_filename);
        free(offsets);
        return NULL;
    }

    int temp_key;
    while (fscanf(file, "%d", &temp_key) == 1) {
        if (temp_key <= 0) {
            fprintf(stderr, "Invalid key value found in %s\n", keys_filename);
            fclose(file);
            free(offsets);
            return NULL;
        }

        int *temp = realloc(keys, keys_size * sizeof(int));
        if (!temp) {
            fprintf(stderr, "Memory allocation error for keys array\n");
            free(keys);
            free(offsets);
            fclose(file);
            return NULL;
        }
        keys = temp;
        keys[keys_size++] = temp_key;
    }

    if (ferror(file)) {
        fprintf(stderr, "Error reading %s\n", keys_filename);
        free(keys);
        free(offsets);
        fclose(file);
        return NULL;
    }

    fclose(file);

    // Create records
    *num_records = offsets_size < keys_size ? offsets_size : keys_size;

    record *records = malloc(*num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation error for records array\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < *num_records; ++i) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Free temporary arrays
    free(offsets);
    free(keys);

    return records;
}

int main() {
    size_t num_records;
    record *records = read_offsets_and_keys("offsets.txt", "keys.txt", &num_records);

    if (records) {
        printf("Number of records: %zu\n", num_records);

        for (size_t i = 0; i < num_records; ++i) {
            printf("Record %zu - Offset: %ld, Key: %d\n", i, *records[i].offset, records[i].key);
        }

        free(records);
    }

    return 0;
}
