#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_MEMORY_SIZE (2 * 1024 * 1024) // 2 MB
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 100

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
    pthread_mutex_t lock;
} DataContainer;

int compare_int(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

void free_resources(DataContainer *container) {
    if (container->offsets) free(container->offsets);
    if (container->keys) free(container->keys);
    if (container->records) free(container->records);
    pthread_mutex_destroy(&container->lock);
}

Record* get_record_with_key(DataContainer *container, int key) {
    pthread_mutex_lock(&container->lock);
    for (size_t i = 0; i < container->size; ++i) {
        if (container->keys[i] == key) {
            pthread_mutex_unlock(&container->lock);
            return &container->records[i];
        }
    }
    pthread_mutex_unlock(&container->lock);
    return NULL;
}

DataContainer* initialize_data_container(int *initial_keys, size_t num_initial_keys) {
    if (num_initial_keys > MAX_RECORDS || sizeof(long) * MAX_RECORDS + sizeof(int) * MAX_RECORDS + sizeof(Record) * MAX_RECORDS > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Exceeded maximum record or memory constraints.\n");
        return NULL;
    }

    DataContainer *container = malloc(sizeof(DataContainer));
    if (!container) {
        perror("Failed to allocate DataContainer");
        return NULL;
    }

    container->offsets = malloc(sizeof(long) * num_initial_keys);
    container->keys = malloc(sizeof(int) * num_initial_keys);
    container->records = malloc(sizeof(Record) * num_initial_keys);

    if (!container->offsets || !container->keys || !container->records) {
        free_resources(container);
        fprintf(stderr, "Failed to allocate memory for arrays.\n");
        return NULL;
    }

    memcpy(container->keys, initial_keys, sizeof(int) * num_initial_keys);

    // Deduplicate keys
    qsort(container->keys, num_initial_keys, sizeof(int), compare_int);

    size_t unique_count = 1;
    for (size_t i = 1; i < num_initial_keys; ++i) {
        if (container->keys[i] != container->keys[unique_count - 1]) {
            container->keys[unique_count++] = container->keys[i];
        }
    }

    // Initialize records
    srand(time(NULL));
    for (size_t i = 0; i < unique_count; ++i) {
        container->records[i].value = rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1) + INT_RANGE_MIN;
        container->offsets[i] = (long)i * sizeof(Record); // Example offset
    }

    container->size = unique_count;
    pthread_mutex_init(&container->lock, NULL);

    return container;
}

int main() {
    int initial_keys[] = {5, 3, 8, 3, 1, 9};
    size_t num_initial_keys = sizeof(initial_keys) / sizeof(initial_keys[0]);

    DataContainer *container = initialize_data_container(initial_keys, num_initial_keys);
    if (container) {
        Record* record = get_record_with_key(container, 5);
        if (record) {
            printf("Record with key 5: %d\n", record->value);
        } else {
            printf("Key not found.\n");
        }

        free_resources(container);
    }
    return 0;
}
