#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_OFFSETS_CAPACITY 1000
#define INITIAL_KEYS_CAPACITY 1000
#define RECORD_SIZE 10

typedef struct {
    long *offset;
    int key_value;
} record;

void log_memory_usage(size_t allocated, const char *message) {
    printf("%s: %zu bytes\n", message, allocated);
}

long* read_offsets(const char *filename, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open offsets.txt");
        exit(EXIT_FAILURE);
    }

    long *offsets = malloc(INITIAL_OFFSETS_CAPACITY * sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed for offsets array");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    size_t capacity = INITIAL_OFFSETS_CAPACITY;
    *count = 0;

    while (fscanf(file, "%ld", &offsets[*count]) == 1) {
        if (*count >= capacity - 1) {
            capacity *= 2;
            offsets = realloc(offsets, capacity * sizeof(long));
            if (!offsets) {
                perror("Memory reallocation failed for offsets array");
                fclose(file);
                exit(EXIT_FAILURE);
            }
        }
        if (offsets[*count] < 0) {
            fprintf(stderr, "Invalid negative offset encountered: %ld\n", offsets[*count]);
            free(offsets);
            fclose(file);
            exit(EXIT_FAILURE);
        }
        (*count)++;
    }

    log_memory_usage(capacity * sizeof(long), "Offsets array memory usage");
    fclose(file);

    return offsets;
}

int* read_keys(const char *filename, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open keys.txt");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(INITIAL_KEYS_CAPACITY * sizeof(int));
    if (!keys) {
        perror("Memory allocation failed for keys array");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    size_t capacity = INITIAL_KEYS_CAPACITY;
    *count = 0;

    while (fscanf(file, "%d", &keys[*count]) == 1) {
        if (*count >= capacity - 1) {
            capacity *= 2;
            keys = realloc(keys, capacity * sizeof(int));
            if (!keys) {
                perror("Memory reallocation failed for keys array");
                fclose(file);
                exit(EXIT_FAILURE);
            }
        }
        if (keys[*count] <= 0) {
            fprintf(stderr, "Invalid non-positive key encountered: %d\n", keys[*count]);
            free(keys);
            fclose(file);
            exit(EXIT_FAILURE);
        }
        (*count)++;
    }

    log_memory_usage(capacity * sizeof(int), "Keys array memory usage");
    fclose(file);

    return keys;
}

record* create_records_array(long *offsets, int *keys, size_t offset_count, size_t key_count, size_t record_size, int min_val, int max_val) {
    if (key_count > offset_count) {
        fprintf(stderr, "Number of keys exceeds number of offsets\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Initialize random seed

    record *records = malloc(record_size * sizeof(record));
    if (!records) {
        perror("Memory allocation failed for records array");
        exit(EXIT_FAILURE);
    }

    log_memory_usage(record_size * sizeof(record), "Records array memory usage");

    for (size_t i = 0; i < record_size && i < key_count; ++i) {
        records[i].offset = &offsets[i];
        records[i].key_value = keys[i];

        // Simulate string key and random number generation
        char *str_key = malloc(20); // Example size for string key storage
        if (!str_key) {
            perror("Memory allocation failed for string key");
            free(records);
            exit(EXIT_FAILURE);
        }

        snprintf(str_key, 20, "key_%zu", i); // Create a simple string key

        records[i].random_value = rand() % (max_val - min_val + 1) + min_val;
    }

    return records;
}

void processAndManageRecords(const char *offsets_filename, const char *keys_filename) {
    size_t offset_count, key_count;

    long *offsets = read_offsets(offsets_filename, &offset_count);
    int *keys = read_keys(keys_filename, &key_count);

    record *records = create_records_array(offsets, keys, offset_count, key_count, RECORD_SIZE, 0, 100);

    // Example usage: Print records
    for (size_t i = 0; i < RECORD_SIZE && i < key_count; ++i) {
        printf("Record %zu - Offset: %ld, Key Value: %d, Random Value: %d\n", 
               i, *records[i].offset, records[i].key_value, records[i].random_value);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    processAndManageRecords("offsets.txt", "keys.txt");
    return 0;
}
