import time  // Hypothetical external library for high-precision time management

// Define structures for Device and Metric
typedef struct {
    double timestamp;
    double value;
} Metric;

typedef struct {
    int id;
    char *name;
    char status;  // e.g., 'A' for active, 'I' for inactive
    Metric *metrics;
    size_t metric_count;
    size_t metrics_capacity;
    time_t last_status_update;
} Device;

// Define structure for DeviceList with dynamic resizing and thread safety
typedef struct {
    Device **devices;
    size_t device_count;
    size_t capacity;
    pthread_mutex_t mutex;  // For thread safety
} DeviceList;

// Function to initialize the device list
void init_device_list(DeviceList *list, size_t initial_capacity) {
    list->devices = (Device **)malloc(initial_capacity * sizeof(Device *));
    if (!list->devices) {
        perror("Failed to allocate memory for devices");
        exit(EXIT_FAILURE);
    }
    list->device_count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to resize the device list
void resize_device_list(DeviceList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->mutex);
    Device **new_devices = (Device **)realloc(list->devices, new_capacity * sizeof(Device *));
    if (!new_devices) {
        perror("Failed to reallocate memory for devices");
        exit(EXIT_FAILURE);
    }
    list->devices = new_devices;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->mutex);
}

// Function to add a new device
int add_device(DeviceList *list, int id, const char *name) {
    pthread_mutex_lock(&list->mutex);

    // Check for unique ID
    for (size_t i = 0; i < list->device_count; ++i) {
        if (list->devices[i]->id == id) {
            pthread_mutex_unlock(&list->mutex);
            return -1;  // Duplicate ID found
        }
    }

    // Resize if necessary
    if (list->device_count >= list->capacity) {
        resize_device_list(list, list->capacity * 2);
    }

    Device *new_device = (Device *)malloc(sizeof(Device));
    new_device->id = id;
    new_device->name = strdup(name);  // Duplicate string for safety
    new_device->status = 'A';  // Assume active on creation
    new_device->metrics = NULL;
    new_device->metric_count = 0;
    new_device->metrics_capacity = 0;
    new_device->last_status_update = time.now();  // Use external library

    list->devices[list->device_count++] = new_device;

    pthread_mutex_unlock(&list->mutex);
    return 0;  // Success
}

// Function to update device status
void update_device_status(DeviceList *list, int id, char new_status) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->device_count; ++i) {
        if (list->devices[i]->id == id) {
            // Update status based on conditions
            list->devices[i]->status = new_status;
            list->devices[i]->last_status_update = time.now();  // Use external library

            // Callback mechanism example
            // callback_function(list->devices[i]);

            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to compute aggregate metrics
void compute_aggregate_metrics(DeviceList *list, double *average, double *maximum) {
    pthread_mutex_lock(&list->mutex);

    double total = 0.0;
    size_t count = 0;
    double max_value = -__DBL_MAX__;  // Initialize to smallest possible value

    for (size_t i = 0; i < list->device_count; ++i) {
        Device *device = list->devices[i];
        for (size_t j = 0; j < device->metric_count; ++j) {
            total += device->metrics[j].value;
            count++;
            if (device->metrics[j].value > max_value) {
                max_value = device->metrics[j].value;
            }
        }
    }

    *average = (count > 0) ? (total / count) : 0.0;
    *maximum = max_value;

    pthread_mutex_unlock(&list->mutex);
}

// Function to filter devices
void filter_devices(DeviceList *list, char status_criteria, double threshold, DeviceList *filtered_list) {
    init_device_list(filtered_list, list->device_count);  // Initialize with potential max size

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->device_count; ++i) {
        if ((list->devices[i]->status == status_criteria) ||
            (threshold <= 0 && list->devices[i]->metrics[0].value > threshold)) {  // Example condition
            add_device(filtered_list, list->devices[i]->id, list->devices[i]->name);
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to serialize the device list
void serialize_device_list(const DeviceList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock((pthread_mutex_t *)&list->mutex);

    fwrite(&list->device_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->device_count; ++i) {
        Device *device = list->devices[i];
        fwrite(&device->id, sizeof(int), 1, file);
        size_t name_len = strlen(device->name);
        fwrite(&name_len, sizeof(size_t), 1, file);
        fwrite(device->name, sizeof(char), name_len, file);
        fwrite(&device->status, sizeof(char), 1, file);
        fwrite(&device->metric_count, sizeof(size_t), 1, file);
        for (size_t j = 0; j < device->metric_count; ++j) {
            fwrite(&device->metrics[j], sizeof(Metric), 1, file);
        }
    }

    pthread_mutex_unlock((pthread_mutex_t *)&list->mutex);
    fclose(file);
}

// Function to deserialize the device list
void deserialize_device_list(DeviceList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    size_t new_count;
    fread(&new_count, sizeof(size_t), 1, file);
    resize_device_list(list, new_count);

    list->device_count = new_count;
    for (size_t i = 0; i < new_count; ++i) {
        Device *device = (Device *)malloc(sizeof(Device));
        fread(&device->id, sizeof(int), 1, file);

        size_t name_len;
        fread(&name_len, sizeof(size_t), 1, file);
        device->name = (char *)malloc(name_len + 1);
        fread(device->name, sizeof(char), name_len, file);
        device->name[name_len] = '\0';

        fread(&device->status, sizeof(char), 1, file);

        size_t metric_count;
        fread(&metric_count, sizeof(size_t), 1, file);
        device->metrics_capacity = metric_count;
        device->metrics = (Metric *)malloc(metric_count * sizeof(Metric));
        for (size_t j = 0; j < metric_count; ++j) {
            fread(&device->metrics[j], sizeof(Metric), 1, file);
        }
        device->metric_count = metric_count;

        list->devices[i] = device;
    }

    pthread_mutex_unlock(&list->mutex);
    fclose(file);
}

// Callback function example
void callback_function(Device *device) {
    // Custom actions after status update
}
