        char *s_value;
    } default_value;
} ConfigSetting;

typedef void (*Callback)(ConfigSetting*);

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize configuration settings
void init_config_settings(ConfigSetting **names, ConfigType **types,
                          union {
                              int *i_values;
                              float *f_values;
                              char ***s_values;
                          } *default_values,
                          size_t num_configs, Callback callback) {
    pthread_mutex_lock(&config_lock);

    if (num_configs > MAX_CONFIGS) {
        fprintf(stderr, "Error: Number of configurations exceeds maximum allowed.\n");
        pthread_mutex_unlock(&config_lock);
        return;
    }

    *names = malloc(num_configs * sizeof(ConfigSetting));
    *types = malloc(num_configs * sizeof(ConfigType));

    if (!*names || !*types) {
        perror("Memory allocation failed for names or types.");
        free(*names); free(*types);
        pthread_mutex_unlock(&config_lock);
        return;
    }

    default_values->i_values = calloc(num_configs, sizeof(int));
    default_values->f_values = calloc(num_configs, sizeof(float));
    default_values->s_values = malloc(num_configs * sizeof(char*));

    if (!default_values->i_values || !default_values->f_values || 
        !default_values->s_values) {
        perror("Memory allocation failed for default values.");
        free(*names); free(*types);
        free(default_values->i_values); free(default_values->f_values);
        free(default_values->s_values);
        pthread_mutex_unlock(&config_lock);
        return;
    }

    // Example predefined configurations
    const char *predefined_names[] = {"timeout", "retry_interval", "host"};
    ConfigType predefined_types[] = {INT, FLOAT, STRING};

    for (size_t i = 0; i < num_configs && i < sizeof(predefined_names)/sizeof(char*); ++i) {
        (*names)[i].name = strdup(predefined_names[i]);
        (*types)[i] = predefined_types[i];

        switch ((*types)[i]) {
            case INT:
                default_values->i_values[i] = 0;
                break;
            case FLOAT:
                default_values->f_values[i] = 0.0f;
                break;
            case STRING:
                default_values->s_values[i] = strdup("localhost");
                break;
        }

        (*names)[i].type = (*types)[i];

        switch ((*names)[i].type) {
            case INT: (*names)[i].default_value.i_value = default_values->i_values[i]; break;
            case FLOAT: (*names)[i].default_value.f_value = default_values->f_values[i]; break;
            case STRING: 
                if (default_values->s_values[i]) {
                    free((*names)[i].default_value.s_value);
                }
                (*names)[i].default_value.s_value = default_values->s_values[i];
                break;
        }

        // Callback invocation
        if (callback) callback(&(*names)[i]);
    }

    pthread_mutex_unlock(&config_lock);
}

// Function to safely update a configuration setting
void update_config_setting(ConfigSetting *configs, size_t index, union {
    int i_value;
    float f_value;
    char *s_value;
} new_value, ConfigType type) {

    pthread_mutex_lock(&config_lock);

    if (index >= MAX_CONFIGS || !configs[index].name) {
        fprintf(stderr, "Error: Invalid configuration index.\n");
        pthread_mutex_unlock(&config_lock);
        return;
    }

    switch(type) {
        case INT:
            configs[index].default_value.i_value = new_value.i_value;
            break;
        case FLOAT:
            configs[index].default_value.f_value = new_value.f_value;
            break;
        case STRING:
            free(configs[index].default_value.s_value);
            configs[index].default_value.s_value = strdup(new_value.s_value);
            break;
    }

    pthread_mutex_unlock(&config_lock);
}

// Example callback function
void example_callback(ConfigSetting *setting) {
    printf("Initialized setting: %s of type %d\n", setting->name, setting->type);
}
