```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    double timestamp;
    double value;
} Metric;

typedef struct {
    int device_id;
    char name[256];
    char last_known_status[50];
    Metric *metrics;
    size_t metrics_count;
} Device;

typedef struct {
    Device **devices;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double resize_threshold; // Fraction of capacity when to trigger resizing
} DeviceList;

void initialize_device_list(DeviceList *list, size_t initial_capacity) {
    list->devices = malloc(initial_capacity * sizeof(Device*));
    if (!list->devices) {
        perror("Failed to allocate memory for devices");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->resize_threshold = 0.75; // Default threshold
}

void resize_device_list(DeviceList *list) {
    pthread_mutex_lock(&list->lock);

    if ((double)list->count / list->capacity >= list->resize_threshold) {
        size_t new_capacity = list->capacity * 2;
        Device **new_devices = realloc(list->devices, new_capacity * sizeof(Device*));
        if (!new_devices) {
            perror("Failed to reallocate memory for devices");
            exit(EXIT_FAILURE);
        }
        list->devices = new_devices;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
}

int add_device(DeviceList *list, int device_id, const char *name, const char *status) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->devices[i]->device_id == device_id) {
            printf("Device ID %d already exists.\n", device_id);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    resize_device_list(list);

    Device *new_device = malloc(sizeof(Device));
    if (!new_device) {
        perror("Failed to allocate memory for new device");
        exit(EXIT_FAILURE);
    }
    new_device->device_id = device_id;
    strncpy(new_device->name, name, sizeof(new_device->name) - 1);
    strncpy(new_device->last_known_status, status, sizeof(new_device->last_known_status) - 1);
    new_device->metrics = NULL;
    new_device->metrics_count = 0;

    list->devices[list->count++] = new_device;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_device_status(DeviceList *list, int device_id, const char *new_status) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->devices[i]->device_id == device_id) {
            strncpy(list->devices[i]->last_known_status, new_status, sizeof(list->devices[i]->last_known_status) - 1);
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_and_compute_aggregates(DeviceList *list) {
    double total_value = 0.0;
    double max_value = -__DBL_MAX__;
    size_t metric_count = 0;

    for (size_t i = 0; i < list->count; ++i) {
        for (size_t j = 0; j < list->devices[i]->metrics_count; ++j) {
            total_value += list->devices[i]->metrics[j].value;
            if (list->devices[i]->metrics[j].value > max_value) {
                max_value = list->devices[i]->metrics[j].value;
            }
            metric_count++;
        }
    }

    double average_value = metric_count ? total_value / metric_count : 0.0;
    printf("Average value: %f, Max value: %f\n", average_value, max_value);
}

void filter_devices_by_status(DeviceList *list, const char *status) {
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->devices[i]->last_known_status, status) == 0) {
            printf("Device ID %d: %s\n", list->devices[i]->device_id, list->devices[i]->name);
        }
    }
}

void free_device_list(DeviceList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->devices[i]->metrics);
        free(list->devices[i]);
    }

    free(list->devices);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    DeviceList device_list;
    initialize_device_list(&device_list, INITIAL_CAPACITY);

    add_device(&device_list, 1, "Device A", "Active");
    update_device_status(&device_list, 1, "Inactive");

    iterate_and_compute_aggregates(&device_list);
    filter_devices_by_status(&device_list, "Inactive");

    free_device_list(&device_list);
    return 0;
}
```

