#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef void (*ProcessCallback)(Record*);

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordList;

static inline void handleError(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

// Helper function to find the maximum integer in a list of records
int findMax(RecordList* recordList) {
    if (recordList == NULL || recordList->head == NULL) return INT_MIN;

    int maxVal = recordList->head->data.value;
    Node* current = recordList->head;

    pthread_mutex_lock(&recordList->lock);
    while (current != NULL) {
        if (current->data.value > maxVal) {
            maxVal = current->data.value;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&recordList->lock);

    return maxVal;
}

// Initialize a RecordList
RecordList* initRecordList() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) handleError("Failed to allocate memory for RecordList");

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Free a RecordList
void freeRecordList(RecordList* recordList) {
    if (!recordList) return;

    Node* current = recordList->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&recordList->lock);
    free(recordList);
}

// Add a new record to the list
void addRecord(RecordList* recordList, int value) {
    if (!recordList) return;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) handleError("Failed to allocate memory for new node");

    newNode->data.value = value;
    newNode->next = NULL;

    pthread_mutex_lock(&recordList->lock);
    newNode->next = recordList->head;
    recordList->head = newNode;
    pthread_mutex_unlock(&recordList->lock);
}

// Process records with a callback
void processRecords(RecordList* recordList, ProcessCallback callback) {
    if (!callback || !recordList) return;

    Node* current = recordList->head;
    while (current != NULL) {
        callback(&(current->data));
        current = current->next;
    }
}

// Example processing function
void printRecord(Record* record) {
    printf("Processing record with value: %d\n", record->value);
}

// Main function to manage records and find the max
int processRecordsAndFindMax() {
    RecordList* recordList = initRecordList();

    // Simulate adding initial records from an external data source.
    addRecord(recordList, 5);
    addRecord(recordList, 10);

    // Read additional user-defined records via command-line input
    int value;
    printf("Enter integer values (Ctrl-D to end):\n");
    while (scanf("%d", &value) == 1) {
        addRecord(recordList, value);
    }

    // Process each record with a callback
    processRecords(recordList, printRecord);

    // Find and return the maximum integer in the dataset
    int maxVal = findMax(recordList);
    printf("Maximum value found: %d\n", maxVal);

    // Free all allocated memory safely
    freeRecordList(recordList);

    return maxVal;
}

int main() {
    processRecordsAndFindMax();
    return 0;
}
