```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define structures
typedef struct {
    int value;
    char identifier[32];
    long *dynamic_data;
} record;

typedef struct {
    double value;
    char identifier[32];
    double *dynamic_data;
} metric;

// Function prototypes
void secure_random_int_range(int *value, int min, int max);
void secure_random_double_range(double *value, double min, double max);

// Thread-safe array resizing with custom strategy
long* resize_array(long *array, size_t current_size, size_t new_size) {
    long *new_array = realloc(array, new_size * sizeof(long));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    for (size_t i = current_size; i < new_size; ++i) {
        new_array[i] = i;
    }
    return new_array;
}

// Function to process records and aggregate metrics
void processRecordsAndAggregateMetrics(size_t record_count, size_t metric_count,
                                       void (*record_callback)(record *), 
                                       void (*metric_callback)(metric *)) {

    pthread_mutex_t offset_lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize arrays with specific sizes
    long *offset = malloc(10 * sizeof(long));  // Initial allocation
    if (!offset) {
        perror("Failed to allocate memory for offset");
        exit(EXIT_FAILURE);
    }

    int *key = malloc(record_count * sizeof(int));
    double *timestamp = malloc(record_count * sizeof(double));
    int *metricID = malloc(metric_count * sizeof(int));

    size_t current_offset_size = 10;
    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&offset_lock);
        if (i >= current_offset_size) {
            offset = resize_array(offset, current_offset_size, current_offset_size * 2);
            current_offset_size *= 2;
        }
        pthread_mutex_unlock(&offset_lock);

        key[i] = i + 1;  // Fill with sequential numbers
        timestamp[i] = (double)i;  // Simple timestamps starting from 0

        if (i == record_count - 1) {  // Resize once at the end to minimize reallocations
            offset = resize_array(offset, current_offset_size, i + 1);
        }
    }

    for (size_t j = 0; j < metric_count; ++j) {
        metricID[j] = j + 1;
    }

    // Allocate and initialize record array
    record *records = malloc(record_count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize metric array
    metric *metrics = malloc(metric_count * sizeof(metric));
    if (!metrics) {
        perror("Failed to allocate memory for metrics");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < record_count; ++i) {
        secure_random_int_range(&records[i].value, 1, 100);
        snprintf(records[i].identifier, sizeof(records[i].identifier), "Record_%zu", i);
        records[i].dynamic_data = malloc(sizeof(long));
        if (!records[i].dynamic_data) {
            perror("Failed to allocate dynamic data for record");
            exit(EXIT_FAILURE);
        }
        *records[i].dynamic_data = offset[i];

        if (record_callback) {
            record_callback(&records[i]);
        }
    }

    for (size_t j = 0; j < metric_count; ++j) {
        secure_random_double_range(&metrics[j].value, 1.0, 100.0);
        snprintf(metrics[j].identifier, sizeof(metrics[j].identifier), "Metric_%zu", j);
        metrics[j].dynamic_data = malloc(sizeof(double));
        if (!metrics[j].dynamic_data) {
            perror("Failed to allocate dynamic data for metric");
            exit(EXIT_FAILURE);
        }
        *metrics[j].dynamic_data = timestamp[j % record_count];

        if (metric_callback) {
            metric_callback(&metrics[j]);
        }
    }

    // Cleanup
    free(offset);
    free(key);
    free(timestamp);
    free(metricID);
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].dynamic_data);
    }
    free(records);

    for (size_t j = 0; j < metric_count; ++j) {
        free(metrics[j].dynamic_data);
    }
    free(metrics);

    pthread_mutex_destroy(&offset_lock);
}

// Example secure random number generation functions
void secure_random_int_range(int *value, int min, int max) {
    *value = rand() % (max - min + 1) + min;
}

void secure_random_double_range(double *value, double min, double max) {
    *value = ((double)rand() / RAND_MAX) * (max - min) + min;
}

// Example callback functions
void record_callback_example(record *r) {
    printf("Processing record: %s with value %d\n", r->identifier, r->value);
}

void metric_callback_example(metric *m) {
    printf("Processing metric: %s with value %.2f\n", m->identifier, m->value);
}
