#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char key[256];
    double weight;
    long *dynamicVar;
} record;

typedef struct {
    record **records;
    size_t count;
} graph_node;

typedef struct {
    graph_node *vertices;
    size_t vertexCount;
    graph_node **edges;
    size_t edgeCount;
    pthread_mutex_t mutex;
} graph;

typedef struct {
    int direction;
    double typeWeight;
} property;

typedef struct {
    graph_node *startVertex;
    graph_node *endVertex;
    property prop;
} edge;

typedef void (*init_callback)(record *);
typedef void (*add_vertex_edge_callback)(graph *, graph_node *, edge *);

void secure_random_int(int min, int max) {
    if (min > max) return;

    srand((unsigned)time(NULL));
    rand(); // discard first value
    int num = min + rand() % ((max - min) + 1);
}

void initialize_graph(graph *g, size_t offsetSize, size_t keySize, size_t weightSize,
                      init_callback recordInit, add_vertex_edge_callback vertexEdgeAdd) {
    pthread_mutex_init(&g->mutex, NULL);

    g->vertices = malloc(sizeof(graph_node) * keySize);
    g->edges = malloc(sizeof(graph_node *) * weightSize);
    g->vertexCount = 0;
    g->edgeCount = 0;

    if (!g->vertices || !g->edges) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Initialize offset, key, and weight arrays
    long *offsets = malloc(sizeof(long) * offsetSize);
    int *keys = malloc(sizeof(int) * keySize);
    double *weights = malloc(sizeof(double) * weightSize);

    if (!offsets || !keys || !weights) {
        perror("Failed to allocate memory for graph properties");
        free(g->vertices);
        free(g->edges);
        pthread_mutex_destroy(&g->mutex);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < offsetSize; ++i)
        offsets[i] = i;

    for (size_t i = 0; i < keySize; ++i) {
        keys[i] = i;
        graph_node *node = &g->vertices[g->vertexCount++];

        node->records = malloc(sizeof(record *) * 5); // Example fixed size
        node->count = 0;

        if (!node->records) {
            perror("Failed to allocate memory for records");
            free(offsets);
            free(keys);
            free(weights);
            free(g->vertices);
            free(g->edges);
            pthread_mutex_destroy(&g->mutex);
            exit(EXIT_FAILURE);
        }

        secure_random_int(1, 100); // Example range

        record *rec = malloc(sizeof(record));
        if (!rec) {
            perror("Failed to allocate memory for record");
            continue;
        }

        rec->value = (int)(rand() % 101);
        snprintf(rec->key, sizeof(rec->key), "RecordKey%d", (int)i);
        rec->weight = weights[i % weightSize];
        rec->dynamicVar = malloc(sizeof(long));
        if (!rec->dynamicVar) {
            perror("Failed to allocate memory for dynamic variable");
            free(rec);
            continue;
        }
        *(rec->dynamicVar) = offsets[i % offsetSize];

        node->records[node->count++] = rec;

        if (recordInit)
            recordInit(rec);

    }

    // Adding edges
    for (size_t i = 0; i < weightSize; ++i) {
        edge *e = malloc(sizeof(edge));
        if (!e) {
            perror("Failed to allocate memory for edge");
            continue;
        }

        e->startVertex = &g->vertices[i % keySize];
        e->endVertex = &g->vertices[(i + 1) % keySize];

        secure_random_int(0, 1);
        e->prop.direction = i % 2; // Example: 0 or 1
        e->prop.typeWeight = weights[i];

        g->edges[g->edgeCount++] = (graph_node *)e;

        if (vertexEdgeAdd)
            vertexEdgeAdd(g, e->startVertex, *g->edges);
    }

    free(offsets);
    free(keys);
    free(weights);

    printf("Graph initialized with %zu vertices and %zu edges.\n", g->vertexCount, g->edgeCount);
}

void cleanup_graph(graph *g) {
    pthread_mutex_lock(&g->mutex);

    for (size_t i = 0; i < g->vertexCount; ++i) {
        graph_node *node = &g->vertices[i];
        for (size_t j = 0; j < node->count; ++j) {
            record *rec = node->records[j];
            free(rec->dynamicVar);
            free(rec);
        }
        free(node->records);
    }

    for (size_t i = 0; i < g->edgeCount; ++i) {
        edge *e = (edge *)g->edges[i];
        pthread_mutex_unlock(&g->mutex);
        free(e); // Assuming no additional allocations within edges
    }

    free(g->vertices);
    free(g->edges);
    pthread_mutex_unlock(&g->mutex);
    pthread_mutex_destroy(&g->mutex);
}

int main() {
    graph g;
    initialize_graph(&g, 100, 50, 30, NULL, NULL);

    // Use the graph...

    cleanup_graph(&g);
    return 0;
}
```

