#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int fd;
    size_t bufferSize;
    char* buffer;
    pthread_mutex_t mutex;
} FileDescriptor;

typedef struct {
    void (*callback)(FileDescriptor*);
    // Add more metadata if needed
} Metadata;

void initializeFileDescriptors(FileDescriptor* fds, size_t numFds, size_t initialBufferSize);
void* processFileThread(void* arg);
void resizeBuffer(char** buffer, size_t* bufferSize, size_t increment);

void handleFileOperationsAndProcessData(size_t numFiles, size_t initialBufferSize,
                                        void (*callback)(FileDescriptor*)) {
    FileDescriptor fds[numFiles];
    Metadata metadata = { callback };

    // Initialize file descriptors
    initializeFileDescriptors(fds, numFiles, initialBufferSize);

    pthread_t threads[numFiles];
    for (size_t i = 0; i < numFiles; ++i) {
        if (pthread_create(&threads[i], NULL, processFileThread, &fds[i])) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < numFiles; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup resources
    for (size_t i = 0; i < numFiles; ++i) {
        pthread_mutex_destroy(&fds[i].mutex);
        free(fds[i].buffer);
        close(fds[i].fd);
    }
}

void initializeFileDescriptors(FileDescriptor* fds, size_t numFds, size_t initialBufferSize) {
    for (size_t i = 0; i < numFds; ++i) {
        pthread_mutex_init(&fds[i].mutex, NULL);
        fds[i].bufferSize = initialBufferSize;

        fds[i].fd = open("datafile", O_RDWR | O_CREAT, 0644);
        if (fds[i].fd == -1) {
            perror("Failed to open file");
            exit(EXIT_FAILURE);
        }

        // Allocate and initialize buffer
        fds[i].buffer = malloc(initialBufferSize);
        if (!fds[i].buffer) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < initialBufferSize; ++j) {
            fds[i].buffer[j] = 'A' + (j % 26); // Fill with sequential data
        }
    }
}

void* processFileThread(void* arg) {
    FileDescriptor* fd = (FileDescriptor*)arg;

    pthread_mutex_lock(&fd->mutex);
    // Simulate file operations and processing
    size_t writtenBytes = write(fd->fd, fd->buffer, fd->bufferSize);
    if (writtenBytes != fd->bufferSize) {
        perror("Failed to write to file");
        pthread_mutex_unlock(&fd->mutex);
        return NULL;
    }

    // Resize buffer as part of processing
    resizeBuffer(&fd->buffer, &fd->bufferSize, 1024);

    // Invoke callback for post-processing
    if (metadata.callback) {
        metadata.callback(fd);
    }

    pthread_mutex_unlock(&fd->mutex);
    return NULL;
}

void resizeBuffer(char** buffer, size_t* bufferSize, size_t increment) {
    size_t newBufferSize = *bufferSize + increment;
    char* newBuffer = realloc(*buffer, newBufferSize);
    if (!newBuffer) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = *bufferSize; i < newBufferSize; ++i) {
        (*buffer)[i] = 'A' + ((i % 26));
    }

    *buffer = newBuffer;
    *bufferSize = newBufferSize;
}
