#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct data_node {
    double *temperature_ptr;
    char *location;
    struct data_node *next;
} data_node;

// Utility function for error checking after malloc calls.
void check_malloc(void *ptr, const char *msg) {
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", msg);
        exit(EXIT_FAILURE);
    }
}

// Function to initialize random number generator
void init_random(int seed) {
    srand(seed);
}

// Generate a random double in the given range [min, max]
double generate_random_double(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

data_node* create_circular_linked_list(size_t size, double *temperature_array, char **location_array) {
    data_node *head = NULL;
    for (size_t i = 0; i < size; ++i) {
        // Allocate memory for a new node
        data_node *new_node = malloc(sizeof(data_node));
        check_malloc(new_node, "Failed to allocate memory for new node");

        // Assign temperature pointer and location
        new_node->temperature_ptr = &temperature_array[i];
        new_node->location = strdup(location_array[i]);
        check_malloc(new_node->location, "Failed to duplicate location string");

        // Insert the new node into the circular linked list
        if (!head) {
            head = new_node;
            new_node->next = new_node;  // Circular link to itself initially
        } else {
            data_node *last = head;
            while (last->next != head) {
                last = last->next;
            }
            last->next = new_node;
            new_node->next = head;
        }
    }
    return head;
}

void free_circular_linked_list(data_node *head) {
    if (!head) return;

    data_node *current = head;
    do {
        data_node *temp = current;
        current = current->next;
        free(temp->location);
        free(temp);
    } while (current != head);
}

void initialize_system(size_t num_temperatures, double min_temp, double max_temp, int seed) {
    if (num_temperatures <= 0) return;

    // Initialize temperature array
    double *temperature_array = malloc(num_temperatures * sizeof(double));
    check_malloc(temperature_array, "Failed to allocate memory for temperature array");

    // Fill temperatures with random values within the specified range
    init_random(seed);
    for (size_t i = 0; i < num_temperatures; ++i) {
        temperature_array[i] = generate_random_double(min_temp, max_temp);
    }

    // Initialize location array
    char **location_array = malloc((num_temperatures - 1) * sizeof(char *));
    check_malloc(location_array, "Failed to allocate memory for location array");

    for (size_t i = 0; i < num_temperatures - 1; ++i) {
        // Allocate and fill each string with an alphabetic character
        location_array[i] = malloc(2); // One char + null terminator
        check_malloc(location_array[i], "Failed to allocate memory for location string");

        // Fill the string with a sequential letter from 'A'
        snprintf(location_array[i], 2, "%c", 'A' + i);
    }

    // Create circular linked list
    data_node *head = create_circular_linked_list(num_temperatures - 1, temperature_array, location_array);

    // Example: Traversal of the circular linked list
    if (head) {
        data_node *current = head;
        do {
            printf("Temperature at %s: %.2f\n", current->location, *(current->temperature_ptr));
            current = current->next;
        } while (current != head);
    }

    // Free allocated memory
    free_circular_linked_list(head);
    for (size_t i = 0; i < num_temperatures - 1; ++i) {
        free(location_array[i]);
    }
    free(location_array);
    free(temperature_array);
}

int main() {
    size_t num_temperatures;
    double min_temp, max_temp;
    int seed;

    // Example user input
    printf("Enter number of temperature readings: ");
    scanf("%zu", &num_temperatures);

    printf("Enter minimum temperature range: ");
    scanf("%lf", &min_temp);

    printf("Enter maximum temperature range: ");
    scanf("%lf", &max_temp);

    printf("Enter random seed: ");
    scanf("%d", &seed);

    initialize_system(num_temperatures, min_temp, max_temp, seed);

    return 0;
}
