} entry;

void log_error(const char *message) {
    // Simple logging mechanism for memory allocation errors
    fprintf(stderr, "Error: %s\n", message);
}

entry* initialize_entries(int num_values, unsigned int seed, double range_min, double range_max) {
    srand(seed);

    if (num_values <= 0) return NULL;

    double *values = (double *)malloc(num_values * sizeof(double));
    if (!values) {
        log_error("Failed to allocate memory for values");
        return NULL;
    }

    char **labels = (char **)malloc((num_values / 3) * sizeof(char *));
    if (!labels) {
        free(values);
        log_error("Failed to allocate memory for labels");
        return NULL;
    }

    entry *entries = (entry *)malloc(num_values * sizeof(entry));
    if (!entries) {
        free(labels);
        free(values);
        log_error("Failed to allocate memory for entries");
        return NULL;
    }

    // Initialize values with unique random numbers
    int used_indices[num_values];
    memset(used_indices, 0, num_values * sizeof(int));

    for (int i = 0; i < num_values; ++i) {
        double value;
        do {
            value = range_min + ((double)rand() / RAND_MAX) * (range_max - range_min);
        } while (!used_indices[(int)(value * 100)]) && !used_indices[i]);

        values[i] = value;
        used_indices[i] = 1;

        entries[i].value_ptr = &values[i];
        entries[i].timestamp = time(NULL);

        if (i < num_values / 3) {
            char label[MAX_LABEL_LENGTH];
            snprintf(label, MAX_LABEL_LENGTH, "Label_%d", i);
            labels[i] = (char *)malloc((strlen(label) + 1) * sizeof(char));
            if (!labels[i]) {
                free(values);
                for (int j = 0; j < i; ++j) {
                    free(labels[j]);
                }
                free(labels);
                free(entries);
                log_error("Failed to allocate memory for label");
                return NULL;
            }
            strcpy(labels[i], label);
            entries[i].label = labels[i];
        } else {
            entries[i].label = NULL;
        }
    }

    // Free unused label pointers
    for (int i = num_values / 3; i < num_values; ++i) {
        if (labels[i]) {
            free(labels[i]);
        }
    }

    return entries;
}

void deallocate_entries(entry *entries, int num_values) {
    if (!entries) return;

    char **labels = (char **)malloc((num_values / 3) * sizeof(char *));

    for (int i = 0; i < num_values / 3 && labels[i]; ++i) {
        free(labels[i]);
    }

    free(entries);
}
