#define MAX_LINE_LENGTH 4096

typedef struct {
    char *text;
    size_t length;
} LineData;

typedef struct {
    FILE **file_descriptors;
    int num_files;
    pthread_mutex_t lock;
} FileProcessor;

typedef void (*LineCallback)(const LineData*);

int openFiles(FileProcessor *fp, const char **filenames) {
    fp->file_descriptors = (FILE **)malloc(fp->num_files * sizeof(FILE *));
    if (!fp->file_descriptors) return -1;

    for (int i = 0; i < fp->num_files; ++i) {
        FILE *fd = fopen(filenames[i], "r");
        if (!fd) {
            // Handle error and cleanup
            while (--i >= 0) fclose(fp->file_descriptors[i]);
            free(fp->file_descriptors);
            return -1;
        }
        fp->file_descriptors[i] = fd;
    }

    pthread_mutex_init(&fp->lock, NULL);
    return 0;
}

void closeFiles(FileProcessor *fp) {
    for (int i = 0; i < fp->num_files; ++i) fclose(fp->file_descriptors[i]);
    free(fp->file_descriptors);
    pthread_mutex_destroy(&fp->lock);
}

LineData* readLine(FILE *fd, size_t *length) {
    char *line = malloc(MAX_LINE_LENGTH);
    if (!line) return NULL;

    *length = fread(line, 1, MAX_LINE_LENGTH - 1, fd);
    if (*length > 0 && line[*length - 1] != '\n') {
        // Handle case where a single read does not get the complete line
        free(line);
        return NULL;
    }

    line[*length] = '\0';
    LineData *data = malloc(sizeof(LineData));
    if (!data) {
        free(line);
        return NULL;
    }

    data->text = line;
    data->length = *length - 1; // Exclude newline
    return data;
}

void processAndProcessFiles(const char **filenames, int num_files, LineCallback callback) {
    FileProcessor fp;
    fp.num_files = num_files;

    if (openFiles(&fp, filenames)) {
        fprintf(stderr, "Failed to open files\n");
        return;
    }

    size_t common_prefix_length = MAX_LINE_LENGTH;
    char common_prefix[MAX_LINE_LENGTH] = {0};

    for (int i = 0; i < fp.num_files; ++i) {
        FILE *fd = fp.file_descriptors[i];
        while (!feof(fd)) {
            size_t length;
            LineData *line_data = readLine(fd, &length);
            if (!line_data) break;

            pthread_mutex_lock(&fp.lock);
            if (callback) callback(*line_data);

            for (size_t j = 0; j < common_prefix_length && j < line_data->length; ++j) {
                if (common_prefix[j] != line_data->text[j]) {
                    common_prefix_length = j;
                    break;
                }
            }

            pthread_mutex_unlock(&fp.lock);

            free(line_data->text);
            free(line_data);
        }
    }

    printf("Longest Common Prefix: %.*s\n", (int)common_prefix_length, common_prefix);

    closeFiles(&fp);
}

void exampleCallback(const LineData *line_data) {
    // Example processing function
    printf("Processed line: %.*s\n", (int)line_data->length, line_data->text);
}
