void resizeArray(int **array, size_t *current_size, size_t new_size) {
    int *new_array = realloc(*array, new_size * sizeof(int));
    handleAllocationError(new_array, "Failed to reallocate integer array.");
    memset(&new_array[*current_size], 0, (new_size - *current_size) * sizeof(int));
    *array = new_array;
    *current_size = new_size;
}

