    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    return max_val;
}

void processAndManageRecords(unsigned int seed) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize offset and key arrays
    size_t offsets_size = DEFAULT_SIZE, keys_size = DEFAULT_SIZE;
    long *offsets = malloc(offsets_size * sizeof(long));
    handleAllocationError(offsets, "Failed to allocate memory for offsets.");

    int *keys = malloc(keys_size * sizeof(int));
    handleAllocationError(keys, "Failed to allocate memory for keys.");

    for (size_t i = 0; i < DEFAULT_SIZE; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate records
    size_t records_capacity = DEFAULT_SIZE;
    Record *records = malloc(records_capacity * sizeof(Record));
    handleAllocationError(records, "Failed to allocate memory for records.");

    for (size_t i = 0; i < records_capacity; ++i) {
        snprintf(records[i].key, KEY_LENGTH, "Key_%zu", i);
        records[i].offset_ptr = malloc(sizeof(long));
        handleAllocationError(records[i].offset_ptr, "Failed to allocate memory for offset pointer.");
        *(records[i].offset_ptr) = offsets[i];

        pthread_mutex_lock(&mutex);
        records[i].value = secureRandom(1, 100, &seed);
        pthread_mutex_unlock(&mutex);

        processRecord(&records[i], i);
    }

    // Read integers from standard input
    int *input_numbers = malloc(DEFAULT_SIZE * sizeof(int));
    handleAllocationError(input_numbers, "Failed to allocate memory for input numbers.");
    size_t current_size = 0;

    printf("Enter integers (-1 to stop):\n");
    while (1) {
        int num;
        scanf("%d", &num);

        if (num == -1) break;

        pthread_mutex_lock(&mutex);
        resizeArray(&input_numbers, &current_size, current_size + 1);
        input_numbers[current_size++] = num;
        pthread_mutex_unlock(&mutex);
    }

    printf("Maximum integer from input: %d\n", findMax(input_numbers, current_size));

    // Clean up
    free(input_numbers);

    clearRecords(&records, &records_capacity);

    free(offsets);
    free(keys);

    pthread_mutex_destroy(&mutex);
}

int main() {
    processAndManageRecords(12345);  // Example seed value for reproducibility
    return 0;
}
