    list->capacity = 10;
    list->count = 0;
    list->records = malloc(list->capacity * sizeof(Record *));
    if (!list->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void resizeRecordList(RecordList *list) {
    size_t newCapacity = list->capacity + 10;
    Record **newRecords = realloc(list->records, newCapacity * sizeof(Record *));
    if (!newRecords) {
        perror("Failed to reallocate memory for records");
        exit(EXIT_FAILURE);
    }
    memset(newRecords + list->capacity, 0, 10 * sizeof(Record *));
    list->records = newRecords;
    list->capacity = newCapacity;
}

void addRecord(RecordList *list, Record *record, Callback callback) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resizeRecordList(list);
    }

    list->records[list->count++] = record;

    if (callback) {
        callback(record, list->count - 1);
    }

    pthread_mutex_unlock(&list->lock);
}

