    record->intValue = intValue;
    record->key = strdup(key);
    record->dynamicLong = malloc(sizeof(long));
    if (!record->dynamicLong) {
        free(record->key);
        free(record);
        perror("Failed to allocate memory for dynamic long");
        exit(EXIT_FAILURE);
    }
    *record->dynamicLong = generateDynamicLong();
    return record;
}

