#include <time.h>

#define INITIAL_SIZE 10
#define KEY_STRING_LEN 20
#define RANDOM_RANGE 100

typedef struct {
    int value;
    char key[KEY_STRING_LEN];
    long *dynamic_ptr;
} record_t;

void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

long* resize_long_array(long **array, size_t current_size, size_t new_size) {
    if (new_size == 0) return NULL;
    long *temp = realloc(*array, sizeof(long) * new_size);
    if (!temp) handle_error("Failed to reallocate memory for offset array");
    return temp;
}

int* resize_int_array(int **array, size_t current_size, size_t new_size) {
    if (new_size == 0) return NULL;
    int *temp = realloc(*array, sizeof(int) * new_size);
    if (!temp) handle_error("Failed to reallocate memory for key array");
    return temp;
}

record_t* resize_record_array(record_t **array, size_t current_size, size_t new_size) {
    if (new_size == 0) return NULL;
    record_t *temp = realloc(*array, sizeof(record_t) * new_size);
    if (!temp) handle_error("Failed to reallocate memory for records array");
    return temp;
}

void initialize_arrays(long **offsets, int **keys, size_t *size) {
    *offsets = malloc(sizeof(long) * (*size));
    *keys = malloc(sizeof(int) * (*size));
    if (!*offsets || !*keys) handle_error("Failed to allocate initial memory");

    for (size_t i = 0; i < *size; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = i;
    }
}

void initialize_records(record_t **records, size_t size) {
    *records = malloc(sizeof(record_t) * size);
    if (!*records) handle_error("Failed to allocate memory for records");

    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = rand() % RANDOM_RANGE;
        snprintf((*records)[i].key, KEY_STRING_LEN, "Key%d", i);
        (*records)[i].dynamic_ptr = malloc(sizeof(long));
        if (!(*records)[i].dynamic_ptr) handle_error("Failed to allocate dynamic pointer");
    }
}

void process_record(record_t *record, void (*callback)(record_t*)) {
    if (callback) callback(record);
}

void free_resources(long *offsets, int *keys, record_t *records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].dynamic_ptr);
    }
    free(offsets);
    free(keys);
    free(records);
}

void processAndAggregateRecords(void (*callback)(record_t*)) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = NULL;
    int *keys = NULL;
    size_t current_size = INITIAL_SIZE;
    record_t *records = NULL;

    initialize_arrays(&offsets, &keys, &current_size);
    initialize_records(&records, current_size);

    srand(time(NULL));

    for (size_t i = 0; i < current_size; ++i) {
        pthread_mutex_lock(&lock);
        process_record(&records[i], callback);
        pthread_mutex_unlock(&lock);
    }

    int *input_array = malloc(sizeof(int));
    if (!input_array) handle_error("Failed to allocate memory for input array");

    size_t input_count = 0;
    int value;

    while (1) {
        printf("Enter an integer (-1 to stop): ");
        scanf("%d", &value);

        if (value == -1) break;

        pthread_mutex_lock(&lock);
        if (input_count >= current_size) {
            input_array = realloc(input_array, sizeof(int) * (current_size *= 2));
            if (!input_array) handle_error("Failed to reallocate memory for input array");
        }
        input_array[input_count++] = value;
        pthread_mutex_unlock(&lock);
    }

    long largest = -1;
    for (size_t i = 0; i < input_count; ++i) {
        if (input_array[i] > largest) largest = input_array[i];
    }

    printf("Largest integer: %ld\n", largest);

    free(input_array);
    pthread_mutex_destroy(&lock);
    free_resources(offsets, keys, records, current_size);
}
