        return;
    }
    for (i = 0; i < node_size; ++i) {
        nodes[i].data = secure_random(1, 100); // Assume range [1, 100]
    }

    // Linked list of entries
    entry *head = NULL;

    for (i = 0; i < priority_size; ++i) {
        entry *new_entry = (entry *)malloc(sizeof(entry));
        if (!new_entry) {
            perror("Failed to allocate memory for entry");
            break;
        }

        snprintf(new_entry->key, sizeof(new_entry->key), "Key_%d_%d", priorities[i], nodes[i % node_size].data);
        new_entry->node_ptr = &nodes[i % node_size];
        new_entry->ref_count = 0;
        new_entry->next = NULL;

        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = new_entry;
        } else {
            entry *temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_entry;
        }
        pthread_mutex_unlock(&lock);

        // Callback mechanism for post-initialization
        if (new_entry->ref_count == 0) { // Simulate access pattern
            new_entry->ref_count++;
        }
    }

    // Function to free all allocated memory safely
    void cleanup(entry *head, int node_size, int priority_size) {
        pthread_mutex_lock(&lock);
        entry *current = head;
        while (current != NULL) {
            entry *temp = current;
            current = current->next;
            if (temp->ref_count < 5) { // Example criteria
                free(temp);
            }
        }
        free(nodes);
        free(priorities);
        pthread_mutex_unlock(&lock);
    }

    cleanup(head, node_size, priority_size);

    // Log usage statistics
    printf("Memory allocation patterns: nodes=%d, priorities=%d\n", node_size, priority_size);
}

int main() {
    initialize_memory(10, 5, 42); // Example usage
    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex to ensure thread safety during modifications of the linked list.
- **Memory Management**: Memory is allocated for priorities and nodes. Entries are dynamically created and linked together.
- **Callback Mechanism**: A simple callback mechanism updates reference counts based on simulated access patterns.
- **Error Handling**: Basic error handling with `perror` is implemented to diagnose memory allocation failures.
- **Cleanup Function**: Ensures all allocated memory is freed, considering a minimum access count threshold for selective freeing.
- **Logging**: Logs basic usage statistics.']

