void free_list(dynamic_list *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->items[i].dynamic_long_ptr);
    }
    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void append_to_list(dynamic_list *list, record new_record) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        list->items = (record *)realloc(list->items, new_capacity * sizeof(record));
        list->capacity = new_capacity;
    }
    list->items[list->count++] = new_record;
    pthread_mutex_unlock(&list->lock);
}

void manageDynamicResources() {
    // Initialize arrays
    size_t long_offset_size = 10;
    size_t key_array_size = 10;

    long *long_offsets = allocate_long_array(long_offset_size);
    int *keys = (int *)malloc(key_array_size * sizeof(int));

    for (size_t i = 0; i < long_offset_size; ++i) {
        long_offsets[i] = i;
    }

    for (size_t i = 0; i < key_array_size; ++i) {
        keys[i] = i;
    }

    // Create dynamic list
    dynamic_list *record_list = create_list(10);

    // Process input stream
    int input;
    while (1) {
        if (scanf("%d", &input) != 1 || input == -1) {
            break; // Break on sentinel or invalid input
        }

        // Create a new record
        record rec;
        rec.value = input;

        snprintf(rec.key, sizeof(rec.key), "key_%d", input);
        rec.dynamic_long_ptr = (long *)malloc(sizeof(long));
        *rec.dynamic_long_ptr = input * 2; // Example initialization

        append_to_list(record_list, rec);

        // Find max value in the list
        int max_value = findMax(keys, record_list->count);
        printf("Current max value: %d\n", max_value);
    }

    // Free allocated resources
    free(long_offsets);
    free(keys);
    free_list(record_list);
}

long* allocate_long_array(size_t size) {
    return (long*)malloc(size * sizeof(long));
}

int findMax(const int *arr, size_t size) {
    if (size == 0) return -1; // Assume sentinel value as invalid input
    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

int main() {
    manageDynamicResources();
    return 0;
}
