                fprintf(stderr, "Memory reallocation failed for transactions\n");
                free(vertices);
                free(edges);
                free(transactions);
                return;
            }
            transactions = newTransactions;
        }

        // Process each transaction
        processTransaction(&transactions[transactionCount - 1]);
    }

    // Clean up resources
