    char messageType[10]; // data, control, error
    size_t defaultPayloadSize;
    char currentState[20];
    unsigned long transactionId;
    uint8_t *messageBuffer;
    size_t messageBufferSize;
} ProtocolSession;

// Queue structure for adaptive queueing mechanism
typedef struct {
    ProtocolSession **sessions;
    int front;
    int rear;
    int capacity;
    pthread_mutex_t lock;
} SessionQueue;

// Function declarations
void initializeSession(ProtocolSession *session, int sessionId);
void resizeMessageBuffer(ProtocolSession *session, size_t newSize);
int queueSession(SessionQueue *queue, ProtocolSession *session);
ProtocolSession* dequeueSession(SessionQueue *queue);
void handlePacket(const uint8_t *packetHeader, size_t headerSize);
void sendAnalyticsData();
void cleanup();

// Main program
int main() {
    // Initialize session queue
    SessionQueue sessionQueue;
    pthread_mutex_init(&sessionQueue.lock, NULL);
    sessionQueue.sessions = malloc(10 * sizeof(ProtocolSession*));
    sessionQueue.front = 0;
    sessionQueue.rear = -1;
    sessionQueue.capacity = 10;

    // Simulate packet processing
