['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// User-defined data structure
typedef struct {
    int integer;
    float floating_point;
    time_t timestamp;
} Data;

// Node for the hash table
typedef struct Node {
    char *key;
    void *value;
    struct Node *next;
} Node;

// Hash table entry with a lock for thread safety
typedef struct Entry {
    pthread_mutex_t mutex;
    Node *head;
} Entry;

#define TABLE_SIZE 1024

// High-performance hash function (example using djb2)
unsigned long hash_djb2(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash % TABLE_SIZE;
}

// Key-value store structure
typedef struct KeyValueStore {
    Entry *table;
    pthread_mutex_t global_mutex;
} KeyValueStore;

// Function prototypes
KeyValueStore* create_store();
void destroy_store(KeyValueStore *store);
int insert(KeyValueStore *store, const char *key, void *value);
void* lookup(KeyValueStore *store, const char *key, void *(*default_value_fn)(void));
int delete_key(KeyValueStore *store, const char *key);
void iterate_store(const KeyValueStore *store, int (*predicate_fn)(const char *, void *));
void serialize_store(const KeyValueStore *store, const char *filename);
KeyValueStore* deserialize_store(const char *filename);

// Create a new key-value store
KeyValueStore* create_store() {
    KeyValueStore *store = malloc(sizeof(KeyValueStore));
    if (!store) return NULL;

    store->table = calloc(TABLE_SIZE, sizeof(Entry));
    if (!store->table) {
        free(store);
        return NULL;
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&store->table[i].mutex, NULL);
    }

    pthread_mutex_init(&store->global_mutex, NULL);

    return store;
}

// Destroy the key-value store
void destroy_store(KeyValueStore *store) {
    if (!store) return;

    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node *current = store->table[i].head;
        while (current) {
            Node *next = current->next;
            free(current->key);
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&store->table[i].mutex);
    }

    free(store->table);

    pthread_mutex_destroy(&store->global_mutex);
    free(store);
}

// Insert a key-value pair into the store
int insert(KeyValueStore *store, const char *key, void *value) {
    if (!store || !key || !value) return -1;

    unsigned long index = hash_djb2(key);

    pthread_mutex_lock(&store->table[index].mutex);

    Node **current = &(store->table[index].head);
    while (*current) {
        if (strcmp((*current)->key, key) == 0) {
            // Key already exists, update value
            free((*current)->value);
            (*current)->value = value;
            pthread_mutex_unlock(&store->table[index].mutex);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&store->table[index].mutex);
        return -1; // Memory allocation failed
    }

    new_node->key = strdup(key);
    if (!new_node->key) {
        free(new_node);
        pthread_mutex_unlock(&store->table[index].mutex);
        return -1; // Memory allocation failed
    }

    new_node->value = value;
    new_node->next = NULL;

    *current = new_node;

    pthread_mutex_unlock(&store->table[index].mutex);

    return 0; // Success
}

// Lookup a key in the store
void* lookup(KeyValueStore *store, const char *key, void *(*default_value_fn)(void)) {
    if (!store || !key) return NULL;

    unsigned long index = hash_djb2(key);

    pthread_mutex_lock(&store->table[index].mutex);

    Node *current = store->table[index].head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            void *value = current->value;
            pthread_mutex_unlock(&store->table[index].mutex);
            return value;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&store->table[index].mutex);

    // Key not found, return default value
    return default_value_fn ? default_value_fn() : NULL;
}

// Delete a key from the store
int delete_key(KeyValueStore *store, const char *key) {
    if (!store || !key) return -1;

    unsigned long index = hash_djb2(key);

    pthread_mutex_lock(&store->table[index].mutex);

    Node **current = &(store->table[index].head);
    while (*current) {
        if (strcmp((*current)->key, key) == 0) {
            Node *to_delete = *current;
            *current = to_delete->next;

            free(to_delete->key);
            free(to_delete->value);
            free(to_delete);

            pthread_mutex_unlock(&store->table[index].mutex);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&store->table[index].mutex);

    return -1; // Key not found
}

// Iterate over the store with an optional predicate function
void iterate_store(const KeyValueStore *store, int (*predicate_fn)(const char *, void *)) {
    if (!store) return;

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&store->table[i].mutex);

        Node *current = store->table[i].head;
        while (current) {
            if (!predicate_fn || predicate_fn(current->key, current->value)) {
                printf("Key: %s, Value: %p\n", current->key, current->value);
            }
            current = current->next;
        }

        pthread_mutex_unlock(&store->table[i].mutex);
    }
}

// Serialize the store to a file
void serialize_store(const KeyValueStore *store, const char *filename) {
    if (!store || !filename) return;

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&store->table[i].mutex);

        Node *current = store->table[i].head;
        while (current) {
            size_t key_len = strlen(current->key) + 1;
            fwrite(&key_len, sizeof(size_t), 1, file);
            fwrite(current->key, sizeof(char), key_len, file);

            // Assuming the value is a pointer to Data
            fwrite(current->value, sizeof(Data), 1, file);

            current = current->next;
        }

        pthread_mutex_unlock(&store->table[i].mutex);
    }

    fclose(file);
}

// Deserialize the store from a file
KeyValueStore* deserialize_store(const char *filename) {
    if (!filename) return NULL;

    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    KeyValueStore *store = create_store();
    if (!store) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&store->table[i].mutex);

        while (1) {
            size_t key_len;
            fread(&key_len, sizeof(size_t), 1, file);
            if (feof(file)) break;

            char *key = malloc(key_len);
            if (!key) {
                destroy_store(store);
                fclose(file);
                return NULL; // Memory allocation failed
            }

            fread(key, sizeof(char), key_len, file);

            Data *data = malloc(sizeof(Data));
            if (!data) {
                free(key);
                destroy_store(store);
                fclose(file);
                return NULL; // Memory allocation failed
            }

            fread(data, sizeof(Data), 1, file);

            insert(store, key, data);

            free(key);
        }

        pthread_mutex_unlock(&store->table[i].mutex);
    }

    fclose(file);
    return store;
}

// Example default value function
Data* default_data_value() {
    Data *data = malloc(sizeof(Data));
    if (data) {
        data->integer = 0;
        data->floating_point = 0.0f;
        data->timestamp = time(NULL);
    }
    return data;
}
