}

// Implementation of functions
void initializeOffsetArray(OffsetArray* offset_array, size_t initial_size) {
    pthread_mutex_init(&offset_array->lock, NULL);
    offset_array->offsets = (long*)malloc(initial_size * sizeof(long));
    if (!offset_array->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    offset_array->offset_size = initial_size;
}

void resizeOffsetArray(OffsetArray* offset_array, size_t new_size) {
    pthread_mutex_lock(&offset_array->lock);
    long* new_offsets = (long*)realloc(offset_array->offsets, new_size * sizeof(long));
    if (!new_offsets) {
        fprintf(stderr, "Failed to reallocate memory for offsets: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    offset_array->offsets = new_offsets;
    offset_array->offset_size = new_size;
    pthread_mutex_unlock(&offset_array->lock);
}

void freeOffsetArray(OffsetArray* offset_array) {
    pthread_mutex_lock(&offset_array->lock);
    free(offset_array->offsets);
    pthread_mutex_unlock(&offset_array->lock);
    pthread_mutex_destroy(&offset_array->lock);
}

void initializeKeyArray(KeyArray* key_array, size_t initial_size) {
    pthread_mutex_init(&key_array->lock, NULL);
    key_array->keys = (int*)malloc(initial_size * sizeof(int));
    if (!key_array->keys) {
        fprintf(stderr, "Failed to allocate memory for keys: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    key_array->key_size = initial_size;
}

void resizeKeyArray(KeyArray* key_array, size_t new_size) {
    pthread_mutex_lock(&key_array->lock);
    int* new_keys = (int*)realloc(key_array->keys, new_size * sizeof(int));
    if (!new_keys) {
        fprintf(stderr, "Failed to reallocate memory for keys: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    key_array->keys = new_keys;
    key_array->key_size = new_size;
    pthread_mutex_unlock(&key_array->lock);
}

void freeKeyArray(KeyArray* key_array) {
    pthread_mutex_lock(&key_array->lock);
    free(key_array->keys);
    pthread_mutex_unlock(&key_array->lock);
    pthread_mutex_destroy(&key_array->lock);
}

void initializeLinkedList(LinkedList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

void insertRecord(LinkedList* list, int value, const char* identifier, size_t position) {
    pthread_mutex_lock(&list->lock);

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for record: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    strncpy(new_record->identifier, identifier, sizeof(new_record->identifier) - 1);
    new_record->next = NULL;

    if (position == 0 || !list->head) {
        new_record->next = list->head;
        list->head = new_record;
    } else {
        Record* current = list->head;
        for (size_t i = 0; i < position - 1 && current->next; ++i) {
            current = current->next;
        }
        new_record->next = current->next;
        current->next = new_record;
    }

    pthread_mutex_unlock(&list->lock);
}

void deleteRecordByIndex(LinkedList* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        fprintf(stderr, "List is empty\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Record** current = &list->head;
    for (size_t i = 0; i < index && *current; ++i) {
        current = &(*current)->next;
    }

    if (*current) {
        Record* to_delete = *current;
        *current = to_delete->next;
        free(to_delete);
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }

    pthread_mutex_unlock(&list->lock);
}

void deleteRecordByValue(LinkedList* list, int value) {
    pthread_mutex_lock(&list->lock);

    Record** current = &list->head;
    while (*current && (*current)->value != value) {
        current = &(*current)->next;
    }

    if (*current) {
        Record* to_delete = *current;
        *current = to_delete->next;
        free(to_delete);
    } else {
        fprintf(stderr, "Record with value %d not found\n", value);
    }

    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
