#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Metadata {
    char author[256];
    time_t timestamp;
    int revision;
} Metadata;

typedef struct ConfigVersion {
    char *key;
    char *value;
    Metadata metadata;
    struct ConfigVersion *next;
} ConfigVersion;

typedef struct RepoNode {
    char *key;
    ConfigVersion *versions;
    pthread_mutex_t lock;
} RepoNode;

typedef struct VersionedConfigRepo {
    RepoNode **nodes;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
    int (*compare_keys)(const char *, const char *);
} VersionedConfigRepo;

// Forward declarations
void init_repo(VersionedConfigRepo *repo, size_t initial_capacity, int (*compare_keys)(const char *, const char *));
void free_repo(VersionedConfigRepo *repo);
int insert_config(VersionedConfigRepo *repo, const char *key, const char *value, const Metadata *metadata);
const ConfigVersion* lookup_latest(const VersionedConfigRepo *repo, const char *key, const char **default_value);
int delete_version(VersionedConfigRepo *repo, const char *key, int revision);
void iterate_versions(const VersionedConfigRepo *repo, const char *key, void (*callback)(const ConfigVersion *, void *), void *context);
void serialize_repo(const VersionedConfigRepo *repo, const char *filename);
int deserialize_repo(VersionedConfigRepo *repo, const char *filename);

// Function implementations
void init_repo(VersionedConfigRepo *repo, size_t initial_capacity, int (*compare_keys)(const char *, const char *)) {
    repo->nodes = calloc(initial_capacity, sizeof(RepoNode *));
    if (!repo->nodes) {
        perror("Failed to allocate memory for repository nodes");
        exit(EXIT_FAILURE);
    }
    repo->capacity = initial_capacity;
    repo->count = 0;
    pthread_rwlock_init(&repo->rwlock, NULL);
    repo->compare_keys = compare_keys ? compare_keys : strcmp;
}

void free_repo(VersionedConfigRepo *repo) {
    for (size_t i = 0; i < repo->capacity; ++i) {
        RepoNode *node = repo->nodes[i];
        if (node) {
            pthread_mutex_lock(&node->lock);
            ConfigVersion *version = node->versions;
            while (version) {
