    int* stream_data = NULL;
    size_t current_size = 0, capacity = 10;

    while (scanf("%d", &stream_data[current_size]) != EOF) {
        if (current_size + 1 >= capacity) {
            capacity *= 2;
            stream_data = realloc(stream_data, capacity * sizeof(int));
            if (!stream_data) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        ++current_size;
    }

    // Find max in streamed data
    int max_value = findMax(stream_data, current_size);

    printf("Maximum value: %d\n", max_value);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(stream_data);

    pthread_mutex_unlock(&lock);
}

