void processRecordsAndFindMax(size_t offset_size, size_t key_size, size_t record_size,
                              long (*external_random_func)(unsigned int), unsigned int seed,
                              void (*callback)(record *), const char *log_file) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    FILE *log_fp = fopen(log_file, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return;
    }

    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(log_fp, "Memory allocation failure for offsets or keys\n");
        if (log_fp) fclose(log_fp);
        return;
    }

    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = (long)i;
    }
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = (int)i;
    }

    record *records = malloc(record_size * sizeof(record));
    if (!records) {
        fprintf(log_fp, "Memory allocation failure for records\n");
        free(offsets);
        free(keys);
        if (log_fp) fclose(log_fp);
        return;
    }

    // Seed the random number generator
    srand(seed);

    for (size_t i = 0; i < record_size; ++i) {
        pthread_mutex_lock(&lock);

        records[i].value = external_random_func(seed) % 1000; // Random value within range [0, 999]

        snprintf(records[i].key, sizeof(records[i].key), "Record_%zu", i);

        records[i].dynamic_long_ptr = malloc(sizeof(long));
        if (!records[i].dynamic_long_ptr) {
            fprintf(log_fp, "Memory allocation failure for dynamic_long_ptr at record %zu\n", i);
            pthread_mutex_unlock(&lock);
            continue;
        }
        *records[i].dynamic_long_ptr = external_random_func(seed);

        if (callback != NULL) {
            callback(&records[i]);
        }

        pthread_mutex_unlock(&lock);
    }

    // Reading integers from standard input and finding the maximum
    int *input_array = malloc(10 * sizeof(int));
    size_t current_size = 0;
    const size_t initial_capacity = 10;

    printf("Enter integers (end with -1):\n");

    while (1) {
        int num;
        if (scanf("%d", &num) != 1 || num == -1) break;

        if (current_size >= input_array ? input_array->capacity : current_size + 1) {
            size_t new_capacity = current_size > 0 ? 2 * current_size : initial_capacity;
            int *new_array = realloc(input_array, new_capacity * sizeof(int));
            if (!new_array) {
                fprintf(log_fp, "Memory reallocation failure for input array\n");
                free(offsets);
                free(keys);
                free(records);
                if (log_fp) fclose(log_fp);
                return;
            }
            input_array = new_array;
        }

        input_array[current_size++] = num;
    }

    int max_value = findMax(input_array, current_size);
    printf("The largest integer is: %d\n", max_value);

    free(offsets);
    free(keys);
    for (size_t i = 0; i < record_size; ++i) {
        free(records[i].dynamic_long_ptr);
    }
    free(records);
    free(input_array);
    fclose(log_fp);
    pthread_mutex_destroy(&lock);
}
