#define MEASUREMENT_SIZE 10
#define TAG_SIZE 20
#define DATA_SIZE 5
#define RANGE_MIN 0.0
#define RANGE_MAX 100.0

typedef struct {
    double value;
    char tag[TAG_SIZE];
    double *pointerToValue;
} Data;

double calculateAverage(double *array, size_t length) {
    if (length == 0) return NAN;

    double sum = 0.0;
    for (size_t i = 0; i < length; ++i) {
        sum += array[i];
    }
    return sum / length;
}

void processAndAggregateData(uint32_t seed, void (*callback)(double)) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    double measurement[MEASUREMENT_SIZE];
    char tag[TAG_SIZE][TAG_SIZE] = { "Tag0", "Tag1", "Tag2", "Tag3", "Tag4", 
                                     "Tag5", "Tag6", "Tag7", "Tag8", "Tag9" };

    // Initialize measurements
    for (int i = 0; i < MEASUREMENT_SIZE; ++i) {
        measurement[i] = i;
    }

    Data *dataArray = malloc(DATA_SIZE * sizeof(Data));
    if (!dataArray) {
        fprintf(stderr, "Memory allocation failed for data array\n");
        return;
    }

    for (int i = 0; i < DATA_SIZE; ++i) {
        dataArray[i].pointerToValue = malloc(sizeof(double));
        if (!dataArray[i].pointerToValue) {
            fprintf(stderr, "Memory allocation failed for pointer to value\n");
            free(dataArray);
            return;
        }

        double randomValue;
        if (RAND_bytes((unsigned char*)&randomValue, sizeof(randomValue)) != 1) {
            fprintf(stderr, "Random number generation failed\n");
            *dataArray[i].pointerToValue = RANGE_MIN; // default value
        } else {
            randomValue = ((double)randomValue / UINT64_MAX) * (RANGE_MAX - RANGE_MIN) + RANGE_MIN;
            *(dataArray[i].pointerToValue) = randomValue;
        }

        strcpy(dataArray[i].tag, tag[i % MEASUREMENT_SIZE]);
        dataArray[i].value = randomValue;

        if (callback) {
            callback(randomValue);
        }
    }

    pthread_mutex_lock(&mutex);

    double *inputNumbers = NULL;
    size_t capacity = 0, length = 0;

    printf("Enter floating-point numbers (enter -1.0 to finish):\n");

    while (1) {
        double input;
        if (scanf("%lf", &input) != 1 || input == -1.0) break;

        if (length >= capacity) {
            size_t newCapacity = capacity == 0 ? 2 : capacity * 2;
            double *newNumbers = realloc(inputNumbers, newCapacity * sizeof(double));
            if (!newNumbers) {
                fprintf(stderr, "Memory allocation failed during resizing\n");
                free(inputNumbers);
                pthread_mutex_unlock(&mutex);
                return;
            }
            inputNumbers = newNumbers;
            capacity = newCapacity;
        }

        inputNumbers[length++] = input;
    }

    double average = calculateAverage(inputNumbers, length);

    if (!isnan(average)) {
        printf("Average: %f\n", average);
    } else {
        printf("No valid numbers were entered.\n");
    }

    free(inputNumbers);

    for (int i = 0; i < DATA_SIZE; ++i) {
        free(dataArray[i].pointerToValue);
    }
    free(dataArray);

    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);
}

void sampleCallback(double value) {
    printf("Processing data point: %f\n", value);
}
