#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    time_t timestamp;
    char level[10];
    char message[256];
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} LogBuffer;

LogBuffer* createLogBuffer() {
    LogBuffer *buffer = malloc(sizeof(LogBuffer));
    buffer->entries = malloc(INITIAL_BUFFER_SIZE * sizeof(LogEntry));
    buffer->count = 0;
    buffer->capacity = INITIAL_BUFFER_SIZE;
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void resizeLogBuffer(LogBuffer *buffer) {
    size_t new_capacity = buffer->capacity * 2;
    LogEntry *new_entries = realloc(buffer->entries, new_capacity * sizeof(LogEntry));
    if (new_entries) {
        buffer->entries = new_entries;
        buffer->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        perror("Failed to resize log buffer");
        exit(EXIT_FAILURE);
    }
}

void addLogEntry(LogBuffer *buffer, LogEntry entry) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == buffer->capacity) {
        resizeLogBuffer(buffer);
    }
    buffer->entries[buffer->count++] = entry;
    pthread_mutex_unlock(&buffer->mutex);
}

void freeLogBuffer(LogBuffer *buffer) {
    free(buffer->entries);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}

time_t generateTimestamp(unsigned int seed) {
    srand(seed ^ time(NULL));
    return time(NULL) + rand() % 100;
}

int processAndAggregateLogData(void (*aggregateMetrics)(const LogBuffer*)) {
