    while (fgets(line, sizeof(line), stdin_stream)) {
        if (line[strlen(line) - 1] == '\n') {
            line[strlen(line) - 1] = '\0';
        }

        LogEntry entry;
        sscanf(line, "%ld %s %[^\n]", &entry.timestamp, entry.level, entry.message);
        if (entry.timestamp == 0) { // Placeholder timestamp
            entry.timestamp = generateTimestamp(seed++);
        }

        addLogEntry(buffer, entry);

        // Aggregate metrics periodically or based on some condition
        aggregateMetrics(buffer);
    }

    freeLogBuffer(buffer);
    return 0;
}

void exampleAggregateMetrics(const LogBuffer *buffer) {
    // Example aggregation: count entries by log level
    int info_count = 0, warning_count = 0, error_count = 0;

    for (size_t i = 0; i < buffer->count; ++i) {
        if (strcmp(buffer->entries[i].level, "INFO") == 0) {
            info_count++;
        } else if (strcmp(buffer->entries[i].level, "WARNING") == 0) {
            warning_count++;
        } else if (strcmp(buffer->entries[i].level, "ERROR") == 0) {
            error_count++;
        }
    }

    printf("INFO: %d, WARNING: %d, ERROR: %d\n", info_count, warning_count, error_count);
}

int main() {
    processAndAggregateLogData(exampleAggregateMetrics);
    return 0;
}
