typedef struct {
    char *data;
    int value;
} record;

typedef enum { FILE_LOGGING, IN_MEMORY_LOGGING } log_mode_t;

typedef struct {
    log_mode_t mode;
    union {
        FILE* file;
        char* memory_log;
    };
} logger_t;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int retry_limit = 3;

// Function prototypes
void initialize_logger(logger_t *logger, log_mode_t mode);
void log_message(logger_t *logger, const char *message);
void filter_data(record *data, size_t length);
void persist_to_database(const record *records, size_t length);
void process_with_third_party_service(const record *record);

// Mock implementation for third-party service integration
void mock_third_party_process(const record *record) {
    printf("Processing with third party: %s\n", record->data);
}

int managingAndPersistingDynamicData(size_t data_size) {
    pthread_mutex_lock(&mutex);

    // Dynamic memory allocation
    long *offsets = malloc(data_size * sizeof(long));
    int *keys = malloc(data_size * sizeof(int));
    record *records = malloc(data_size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize memory
    memset(offsets, 0, data_size * sizeof(long));
    memset(keys, 0, data_size * sizeof(int));

    for (size_t i = 0; i < data_size; ++i) {
        records[i].data = malloc(50); // Example fixed size allocation for simplicity
        if (!records[i].data) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        snprintf(records[i].data, 50, "Data_%zu_%d", i, rand() % 1000);
        records[i].value = rand() % 1000;

        offsets[i] = (long)i * sizeof(record);
        keys[i] = i; // Example simple key assignment
    }

    logger_t logger;
    initialize_logger(&logger, FILE_LOGGING);

    log_message(&logger, "Data initialized");

    filter_data(records, data_size);

    persist_to_database(records, data_size);

    for (size_t i = 0; i < data_size; ++i) {
        process_with_third_party_service(&records[i]);
    }

    // Cleanup
    if (logger.mode == FILE_LOGGING && logger.file) fclose(logger.file);
    else if (logger.memory_log) free(logger.memory_log);

    for (size_t i = 0; i < data_size; ++i) {
        free(records[i].data);
    }
    free(records);
    free(keys);
    free(offsets);

    pthread_mutex_unlock(&mutex);

    return 0;
}

void initialize_logger(logger_t *logger, log_mode_t mode) {
    logger->mode = mode;
    if (mode == FILE_LOGGING) {
        logger->file = fopen("log.txt", "w");
        if (!logger->file) perror("Failed to open file for logging");
    } else if (mode == IN_MEMORY_LOGGING) {
        logger->memory_log = malloc(1024 * sizeof(char));
        if (!logger->memory_log) fprintf(stderr, "Memory allocation failed\n");
