// Function to process records and log events
void processRecordsAndLogEvents(size_t num_records, size_t events_per_record,
                                int min_value, int max_value, unsigned int seed,
                                int log_fd) {
    long *offsets = NULL;
    int *keys = NULL;
    record **records1 = NULL;
    record **records2 = NULL;
    event ***events = NULL;

    if (num_records == 0 || events_per_record == 0) return;

    // Initialize secure random generator
    secure_random_init(seed);

    pthread_mutex_lock(&lock);
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records1 = malloc(num_records * sizeof(record *));
    records2 = malloc(num_records * sizeof(record *));
    events = malloc(num_records * sizeof(event **));

    if (!offsets || !keys || !records1 || !records2 || !events) {
        logError(log_fd, "Memory allocation failed");
        goto cleanup;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records1[i] = malloc(sizeof(record));
        records2[i] = malloc(sizeof(record));
        events[i] = malloc(events_per_record * sizeof(event *));

        if (!records1[i] || !records2[i] || !events[i]) {
            logError(log_fd, "Memory allocation failed");
            goto cleanup;
        }

        int value = secure_random_int(min_value, max_value);
        records1[i]->value = malloc(sizeof(int));
        records2[i]->value = malloc(sizeof(int));

        if (!records1[i]->value || !records2[i]->value) {
            logError(log_fd, "Memory allocation failed");
            goto cleanup;
        }

        *records1[i]->value = value;
        *records2[i]->value = secure_random_int(min_value, max_value);

        records1[i]->ref_count = 0;
        records2[i]->ref_count = 0;

        for (size_t j = 0; j < events_per_record; ++j) {
            events[i][j] = malloc(sizeof(event));
            if (!events[i][j]) {
                logError(log_fd, "Memory allocation failed");
                goto cleanup;
            }
            // Initialize event with a random timestamp and status flag
            events[i][j]->timestamp = secure_random_long();
            events[i][j]->status_flag = secure_random_int(0, 1);
        }

        offsets[i] = secure_random_long();
        keys[i] = secure_random_int(INT_MIN, INT_MAX);
    }

    pthread_mutex_unlock(&lock);

cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records1) {
        for (size_t i = 0; i < num_records; ++i) {
            if (records1[i]) {
                if (records1[i]->value) free(records1[i]->value);
                free(records1[i]);
            }
        }
        free(records1);
    }

    if (records2) {
        for (size_t i = 0; i < num_records; ++i) {
            if (records2[i]) {
                if (records2[i]->value) free(records2[i]->value);
                free(records2[i]);
            }
        }
        free(records2);
    }

    if (events) {
        for (size_t i = 0; i < num_records; ++i) {
            if (events[i]) {
                for (size_t j = 0; j < events_per_record; ++j) {
                    if (events[i][j]) free(events[i][j]);
                }
                free(events[i]);
            }
        }
        free(events);
    }

    // Read integers from standard input and find the largest integer
    int *array = NULL;
    size_t array_size = 0, capacity = 10;

    array = malloc(capacity * sizeof(int));
    if (!array) {
        logError(log_fd, "Memory allocation failed for input array");
        return;
    }

    printf("Enter integers (-1 to end):\n");

    while (1) {
        int num;
        scanf("%d", &num);

        if (num == -1) break;

        if (array_size >= capacity) {
            capacity *= 2;
            int *new_array = realloc(array, capacity * sizeof(int));
            if (!new_array) {
                logError(log_fd, "Memory reallocation failed for input array");
                free(array);
                return;
            }
            array = new_array;
        }

        array[array_size++] = num;
    }

    if (array_size > 0) {
        int max_value = findMax(array, array_size);
        printf("Largest integer: %d\n", max_value);
    }

    free(array);
}

// Main function to demonstrate the usage
