typedef struct {
    time_t timestamp;
    uint32_t packetId;
} packetEvent;

typedef struct {
    uint64_t totalByteCount;
    uint32_t totalPacketCount;
    double overallAveragePacketSize;
} connectionSummary;

// Define a structure to hold dynamic arrays
struct MetricsData {
    flowMetrics *flows;
    packetEvent **packetEvents;
    size_t numFlows;
    size_t packetsPerFlow[INITIAL_FLOW_COUNT];
};

pthread_mutex_t metricsMutex = PTHREAD_MUTEX_INITIALIZER;

void logError(const char *message, int fd) {
    dprintf(fd, "%s\n", message);
}

void freeMetricsData(struct MetricsData *data) {
    for (size_t i = 0; i < data->numFlows; ++i) {
        free(data->packetEvents[i]);
    }
    free(data->packetEvents);
    free(data->flows);
}

int resizeFlowArray(struct MetricsData *data, size_t newSize) {
    flowMetrics *newFlows = realloc(data->flows, newSize * sizeof(flowMetrics));
    if (!newFlows) {
        return -1;
    }

    packetEvent **newPacketEvents = realloc(data->packetEvents, newSize * sizeof(packetEvent *));
    if (!newPacketEvents) {
        free(newFlows);
        return -1;
    }

    for (size_t i = data->numFlows; i < newSize; ++i) {
        newPacketEvents[i] = NULL; // Initialize pointers to NULL
    }

    data->flows = newFlows;
    data->packetEvents = newPacketEvents;
    data->numFlows = newSize;

    return 0;
}

void aggregateMetrics(struct MetricsData *data, connectionSummary *summary) {
    pthread_mutex_lock(&metricsMutex);

    summary->totalByteCount = 0;
    summary->totalPacketCount = 0;

    for (size_t i = 0; i < data->numFlows; ++i) {
        flowMetrics *fm = &data->flows[i];
        uint32_t packetCnt = fm->packetCount;
        if (packetCnt > 0) {
            summary->totalByteCount += fm->byteCount;
            summary->totalPacketCount += packetCnt;

            if (summary->totalPacketCount > 0) {
                summary->overallAveragePacketSize =
                    ((double)(fm->byteCount / fm->packetCount)) * 
                    ((double)packetCnt / (double)summary->totalPacketCount);
            }
        }
    }

    pthread_mutex_unlock(&metricsMutex);
}

void parseAndAggregateMetrics(int errorLogFd) {
    struct MetricsData metrics;
    connectionSummary summary = {0};

    // Initialize dynamic arrays
    metrics.numFlows = INITIAL_FLOW_COUNT;
    metrics.flows = malloc(metrics.numFlows * sizeof(flowMetrics));
    if (!metrics.flows) {
        logError("Failed to allocate memory for flows", errorLogFd);
        return;
    }

    metrics.packetEvents = calloc(metrics.numFlows, sizeof(packetEvent *));
    if (!metrics.packetEvents) {
        free(metrics.flows);
        logError("Failed to allocate memory for packet events", errorLogFd);
        return;
    }

    // Initialize packet counts per flow
    memset(metrics.packetsPerFlow, INITIAL_PACKETS_PER_FLOW, metrics.numFlows * sizeof(size_t));

    // Placeholder variables for parsing headers
    uint32_t packetId;
    time_t timestamp;

    while (scanf("%u %ld", &packetId, &timestamp) == 2) {
        pthread_mutex_lock(&metricsMutex);

        size_t flowIndex = highPerformanceRandomGenerator((uint32_t *)&flowIndex);
        if (flowIndex >= metrics.numFlows) {
            // Resize array if necessary
            if (resizeFlowArray(&metrics, metrics.numFlows * 2) != 0) {
                logError("Failed to resize flow array", errorLogFd);
                break;
            }
            flowIndex = highPerformanceRandomGenerator((uint32_t *)&flowIndex);
        }

        // Get or allocate packet event array
        if (!metrics.packetEvents[flowIndex]) {
            size_t pktCntPerFlow = metrics.packetsPerFlow[flowIndex];
            metrics.packetEvents[flowIndex] = malloc(pktCntPerFlow * sizeof(packetEvent));
            if (!metrics.packetEvents[flowIndex]) {
                logError("Failed to allocate memory for packet events", errorLogFd);
                break;
            }
        }

        // Check and resize per-flow packet array if necessary
        uint32_t pktCount = metrics.flows[flowIndex].packetCount;
        if (pktCount >= metrics.packetsPerFlow[flowIndex]) {
            size_t newPktSize = metrics.packetsPerFlow[flowIndex] * 2;
            packetEvent *newEvents = realloc(metrics.packetEvents[flowIndex], newPktSize * sizeof(packetEvent));
            if (!newEvents) {
                logError("Failed to resize packet events array", errorLogFd);
                break;
            }
            metrics.packetsPerFlow[flowIndex] = newPktSize;
            metrics.packetEvents[flowIndex] = newEvents;
        }

        // Populate the packet event
        metrics.packetEvents[flowIndex][pktCount].packetId = packetId;
        metrics.packetEvents[flowIndex][pktCount].timestamp = timestamp;

        // Update flow metrics (example logic)
        metrics.flows[flowIndex].byteCount += 100;  // Placeholder for byte count increment
        ++metrics.flows[flowIndex].packetCount;

        pthread_mutex_unlock(&metricsMutex);
    }

    aggregateMetrics(&metrics, &summary);

    freeMetricsData(&metrics);

    printf("Total Byte Count: %llu\n", summary.totalByteCount);
    printf("Total Packet Count: %u\n", summary.totalPacketCount);
    printf("Overall Average Packet Size: %.2f\n", summary.overallAveragePacketSize);
}
