int handleDynamicDataAndIO(const char *filename) {
    pthread_mutex_init(&mutex, NULL);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("File not found or cannot be opened.");
        return -1;
    }

    dataset_size = 0;
    size_t capacity = 1024;

    dataset = malloc(capacity * sizeof(record));
    if (!dataset) {
        log_error("Memory allocation failed for dataset.");
        fclose(file);
        pthread_mutex_destroy(&mutex);
        return -1;
    }

    int read_success;
    record temp_record;

    while ((read_success = fread(&temp_record, sizeof(int), 1, file)) > 0) {
        if (dataset_size == capacity) {
            capacity *= 2;
            dataset = realloc(dataset, capacity * sizeof(record));
            if (!dataset) {
                log_error("Memory reallocation failed for dataset.");
                fclose(file);
                pthread_mutex_destroy(&mutex);
                return -1;
            }
        }

        temp_record.value = rand() % RAND_RANGE_MAX;

        fread(temp_record.key, KEY_SIZE, 1, file);

        temp_record.data_ptr = malloc(sizeof(long));
        if (!temp_record.data_ptr) {
            log_error("Memory allocation failed for data_ptr.");
            fclose(file);
            pthread_mutex_destroy(&mutex);
            return -1;
        }

        fread(temp_record.data_ptr, sizeof(long), 1, file);

        pthread_mutex_lock(&mutex);
        dataset[dataset_size++] = temp_record;
        processed_records++;
        pthread_mutex_unlock(&mutex);
    }

    if (ferror(file)) {
        log_error("Error reading from file.");
    }

    fclose(file);

    for (size_t i = 0; i < dataset_size; ++i) {
        free(dataset[i].data_ptr);
    }
    free(dataset);

    pthread_mutex_destroy(&mutex);

    return processed_records == MAX_RECORDS ? SUCCESSFUL_PROCESSING_INDICATOR : processed_records;
}
