    int *keys = malloc(10 * sizeof(int));
    if (!offsets || !keys) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    initializeArrays(offsets, keys, 10);

    size_t recordCount = rand() % (maxRecords - minRecords + 1) + minRecords;
    record **records = malloc(recordCount * sizeof(record*));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < recordCount; ++i) {
        records[i] = createRecord();
        if (!records[i]) {
            perror("Failed to allocate record");
            exit(EXIT_FAILURE);
        }
    }

    size_t edgeCount = rand() % (maxEdges - minEdges + 1) + minEdges;
    edge *edges = malloc(edgeCount * sizeof(edge));
    if (!edges) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < edgeCount; ++i) {
        edges[i] = createEdge();
    }

    size_t vertexCount = rand() % (maxVertices - minVertices + 1) + minVertices;
    vertex **vertices = malloc(vertexCount * sizeof(vertex*));
    if (!vertices) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
