    for (size_t i = 0; i < vertexCount; ++i) {
        vertices[i] = createVertex();
        if (!vertices[i]) {
            perror("Failed to allocate vertex");
            exit(EXIT_FAILURE);
        }
    }

    size_t queryCount = rand() % (maxQueries - minQueries + 1) + minQueries;
    query *queriesHead = NULL, *queriesTail = NULL;

    for (size_t i = 0; i < queryCount; ++i) {
        query *q = createQuery();
        if (!q) {
            perror("Failed to allocate query");
            exit(EXIT_FAILURE);
        }
        q->next = NULL;
        if (!queriesHead) {
            queriesHead = q;
        } else {
            queriesTail->next = q;
        }
        queriesTail = q;
    }

    int *inputNumbers = NULL;
    size_t inputCount = 0, capacity = 10;

    while (1) {
        int num;
        if (scanf("%d", &num) != 1 || num == -1) break;

        if (inputCount >= capacity) {
            capacity *= 2;
            int *temp = realloc(inputNumbers, capacity * sizeof(int));
            if (!temp) {
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }
            inputNumbers = temp;
        }

        inputNumbers[inputCount++] = num;
    }

    // Free allocated memory
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i]->key);
        free(records[i]->dataPointer);
        free(records[i]);
    }
    free(records);

    for (size_t i = 0; i < vertexCount; ++i) {
        for (size_t j = 0; j < vertices[i]->labelCount; ++j) {
            free(vertices[i]->labels[j]);
        }
        free(vertices[i]->labels);
        free(vertices[i]);
    }
    free(vertices);

    query *q = queriesHead;
    while (q) {
        query *next = q->next;
        free(q->queryString);
        free(q);
        q = next;
    }

    free(inputNumbers);
    free(offsets);
    free(keys);
    free(edges);
}
