void log(const char* message) {
    printf("%s\n", message);
}

// Helper to free memory
void free_resources(record **records, int num_records, long *offset, int offset_size, int *keys, size_t keys_size) {
    if (records != NULL) {
        for (int i = 0; i < num_records; ++i) {
            free(records[i]->key);
            free(records[i]->pointer_to_long);
            free(records[i]);
        }
        free(*records);
    }
    if (offset != NULL) free(offset);
    if (keys != NULL) free(keys);
}

// Function to handle records
void processAndProcessRecords(int num_records, int offset_size, int keys_size, long min_random, long max_random,
                              unsigned int seed, void (*callback)(record*)) {

    // Initialize arrays for offsets and keys
    long *offset = malloc(offset_size * sizeof(long));
    if (!offset) { 
        log("Failed to allocate memory for offset array");
        return; 
    }
    for (int i = 0; i < offset_size; ++i) {
        offset[i] = i;
    }

    int *keys = malloc(keys_size * sizeof(int));
    if (!keys) { 
        log("Failed to allocate memory for keys array");
        free(offset);
        return; 
    }
    for (int i = 0; i < keys_size; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records
    record **records = malloc(num_records * sizeof(record*));
    if (!records) { 
        log("Failed to allocate memory for records array");
        free(offset);
        free(keys);
        return; 
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; ++i) {
        record *rec = malloc(sizeof(record));
        if (!rec) { 
            log("Failed to allocate memory for a single record");
            free_resources(&records, i, &offset, offset_size, keys, keys_size);
            return; 
        }

        // Initialize the random seed
        srand(seed + i);

        rec->value = (int)secure_random(min_random, max_random);
        size_t key_len = 10;
        rec->key = malloc(key_len * sizeof(char));
        if (!rec->key) { 
            log("Failed to allocate memory for record's key");
            free(rec);
            free_resources(&records, i, &offset, offset_size, keys, keys_size);
            return; 
        }
        snprintf(rec->key, key_len, "Key_%d", rec->value);

        pthread_mutex_lock(&mutex);
        rec->pointer_to_long = malloc(sizeof(long));
        if (!rec->pointer_to_long) { 
            log("Failed to allocate memory for record's pointer to long");
            free(rec->key);
            free(rec);
            free_resources(&records, i, &offset, offset_size, keys, keys_size);
            pthread_mutex_unlock(&mutex);
            return; 
        }
        rec->pointer_to_long[0] = (long)i;
        pthread_mutex_unlock(&mutex);

        records[i] = rec;

        // Call the custom callback function
        if (callback) {
            (*callback)(rec);
        }
    }

    int *input_numbers = NULL;
    size_t input_size = 0;

    // Read integers from stdin and dynamically resize the array as needed
    while (scanf("%d", &input_numbers[0]) == 1) {
        if (input_size == 0 || input_size == cap[input_size - 1]) {
            int *new_input_numbers;
            size_t new_size = (input_size == 0 ? 4 : input_size * 2);
            new_input_numbers = realloc(input_numbers, new_size * sizeof(int));
            if (!new_input_numbers) {
                log("Failed to resize memory for integer inputs");
                break;
            }
            input_numbers = new_input_numbers;
        }

        pthread_mutex_lock(&mutex);
        input_numbers[input_size++] = input_numbers[0];
        pthread_mutex_unlock(&mutex);
    }

    // Find and print the maximum value
    int max_value = ((int (*)())findMax)(input_numbers, input_size);
    if (max_value == -1) {
        log("Failed to find the maximum integer");
    } else {
        printf("Maximum integer: %d\n", max_value);
    }

    // Free all allocated resources
    free_resources(&records, num_records, &offset, offset_size, keys, keys_size);

    if (input_numbers != NULL) {
        free(input_numbers);
    }
}

// Secure random number generation function (mock implementation)
