                              Record **records, size_t recordCount,
                              DataChunk **dataChunks, size_t chunkCount,
                              void (*recordCallback)(int), void (*chunkCallback)(int));

void initializeOffsetAndKey(int *offset, int *key) {
    for (int i = 0; i < OFFSET_SIZE; ++i) offset[i] = i;
    for (int i = 0; i < KEY_SIZE; ++i) key[i] = i;
}

void initializeFileMetadata(FileMetadata *metadata, long seed) {
    setRandomSeed(seed);
    time_t currentTime;
    srand((unsigned int)time(NULL) + seed);

    for (int i = 0; i < FILE_COUNT; ++i) {
        snprintf(metadata[i].fileName, sizeof(metadata[i].fileName), "file_%d.txt", i);
        metadata[i].fileSize = rand() % 1024;
        currentTime = time(NULL) + rand();
        metadata[i].timestamp = currentTime;
    }
}

Record* allocateRecords(size_t size, int minVal, int maxVal, long seed, void (*callback)(int)) {
    setRandomSeed(seed);
    Record *records = (Record *)malloc(size * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
        if (callback) callback(i);
    }
    return records;
}

DataChunk* allocateDataChunks(size_t count, void (*callback)(int)) {
    DataChunk *chunks = (DataChunk *)malloc(count * sizeof(DataChunk));
    if (!chunks) return NULL;

    for (size_t i = 0; i < count; ++i) {
        chunks[i].position = i;
        for (int j = 0; j < CHUNK_SIZE; ++j)
            chunks[i].data[j] = (j % 2 == 0) ? 0 : 1;

        if (callback) callback(i);
    }
    return chunks;
}

void freeResources(Record *records, DataChunk *dataChunks) {
    free(records);
    free(dataChunks);
}

void setRandomSeed(long seed) {
    srand(seed);
}

void processRecordsAndMetadata(int *offset, int *key, FileMetadata *metadata,
                              Record **records, size_t recordCount,
                              DataChunk **dataChunks, size_t chunkCount,
                              void (*recordCallback)(int), void (*chunkCallback)(int)) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize offset and key
    initializeOffsetAndKey(offset, key);

    // Initialize file metadata
    long seed = 12345; // Custom seed for reproducibility
    initializeFileMetadata(metadata, seed);

    // Allocate records with random values
    *records = allocateRecords(recordCount, 1, 1000, seed, recordCallback);
    if (!*records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    // Allocate data chunks
    *dataChunks = allocateDataChunks(chunkCount, chunkCallback);
    if (!*dataChunks) {
        free(*records);
        fprintf(stderr, "Failed to allocate memory for data chunks\n");
        return;
    }
}

int main() {
    int offset[OFFSET_SIZE], key[KEY_SIZE];
    FileMetadata metadata[FILE_COUNT];

    Record *records = NULL;
    DataChunk *dataChunks = NULL;

    processRecordsAndMetadata(offset, key, metadata,
                              &records, RECORD_SIZE,
