#define BASE_SESSION_ID 1000
#define SESSION_POOL_SIZE 1024

typedef struct {
    char *sessionID;
    char ip[16];
    time_t lastAccessTime;
    void *userProfile;
} SessionLogEntry;

typedef struct {
    char username[50];
    char email[100];
    char role[20];
} UserProfile;

typedef struct {
    SessionLogEntry entries[SESSION_POOL_SIZE];
    int currentID;
    pthread_mutex_t lock;
    int rollingReset;
} SessionManager;

typedef void (*SessionCallback)(void *data);

// Function to initialize the session manager
int manageUserSessions(SessionManager *manager, size_t cacheSize, unsigned int seed, 
                       SessionCallback preInitCB, SessionCallback postInitCB) {
    if (!manager || !preInitCB || !postInitCB) return -1;

    // Initialize mutex
    pthread_mutex_init(&manager->lock, NULL);

    manager->currentID = BASE_SESSION_ID;
    manager->rollingReset = 0; // No rolling reset by default

    for (int i = 0; i < SESSION_POOL_SIZE; ++i) {
        manager->entries[i].sessionID = NULL;
        manager->entries[i].ip[0] = '\0';
        manager->entries[i].lastAccessTime = 0;
        manager->entries[i].userProfile = NULL;
    }

    // Allocate and initialize user metadata cache
    UserProfile *userCache = (UserProfile *)malloc(cacheSize * sizeof(UserProfile));
    if (!userCache) {
        return -1; // Memory allocation failure
    }

    for (size_t i = 0; i < cacheSize; ++i) {
        memset(&userCache[i], 0, sizeof(UserProfile));
    }

    // Invoke pre-initialization callback
    preInitCB(userCache);

    // Initialize session IDs with seed
    srand(seed);
    for (int i = 0; i < SESSION_POOL_SIZE; ++i) {
        manager->entries[i].sessionID = (char *)malloc(20 * sizeof(char));
        if (!manager->entries[i].sessionID) {
            return -1; // Memory allocation failure
        }

        snprintf(manager->entries[i].sessionID, 20, "%u", BASE_SESSION_ID + i + rand());
    }

    // Invoke post-initialization callback
    postInitCB(userCache);

    free(userCache);
    return 0;
}

// Function to generate a new session ID
char *generateSessionID(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    char *sessionID = NULL;
    for (int i = 0; i < SESSION_POOL_SIZE; ++i) {
        if (!manager->entries[i].sessionID || manager->rollingReset) {
            sessionID = manager->entries[i].sessionID;
            snprintf(sessionID, 20, "%u", BASE_SESSION_ID + manager->currentID);
            manager->currentID++;
            if (manager->currentID >= SESSION_POOL_SIZE + BASE_SESSION_ID) {
                manager->currentID = BASE_SESSION_ID; // Reset
                manager->rollingReset = 1;
            }
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return sessionID;
}

// Function to free all allocated resources
void cleanupSessionManager(SessionManager *manager) {
    if (!manager) return;

    for (int i = 0; i < SESSION_POOL_SIZE; ++i) {
        if (manager->entries[i].sessionID) {
            free(manager->entries[i].sessionID);
        }
    }

    pthread_mutex_destroy(&manager->lock);
}

// Example callback functions
void preInitCallback(void *data) {
    // Custom logic before initialization
}

void postInitCallback(void *data) {
    // Custom logic after initialization
}

int main() {
    SessionManager manager;
    manageUserSessions(&manager, 100, 42, preInitCallback, postInitCallback);

    char *newSessionID = generateSessionID(&manager);
    if (newSessionID) {
        printf("New session ID: %s\n", newSessionID);
    }

    cleanupSessionManager(&manager);

    return 0;
}
