// Secure random number generation using external library (e.g., OpenSSL)
int secure_random_int(int min, int max) {
    // Example with OpenSSL's RAND_bytes function for demonstration purposes.
    unsigned int result;
    if (RAND_bytes((unsigned char*)&result, sizeof(result)) != 1) {
        fprintf(stderr, "Error generating random number\n");
        exit(EXIT_FAILURE);
    }
    return min + (result % (max - min + 1));
}

// Helper function to find the maximum integer in an array
int findMax(int *arr, size_t n) {
    int max = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

