typedef void (*RecordCallback)(Record *);

void processRecordsAndFindMax(size_t numOffsets, size_t numKeys, size_t numRecords, RecordCallback callback) {
    // Initialize arrays with error handling
    long *offsets = (long *)calloc(numOffsets, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    int *keys = (int *)calloc(numKeys, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    Record *records = (Record *)malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(keys);
        free(offsets);
        return;
    }

    // Fill offsets and keys with sequential numbers
    for (size_t i = 0; i < numOffsets; ++i) {
        offsets[i] = i;
    }
    for (size_t i = 0; i < numKeys; ++i) {
        keys[i] = i;
    }

    // Initialize records with random values and dynamic long pointers
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = secure_random_int(1, 100);
        snprintf(records[i].stringKey, sizeof(records[i].stringKey), "key_%zu", i);
        records[i].dynamicLong = malloc(sizeof(long));
        if (!records[i].dynamicLong) {
            fprintf(stderr, "Failed to allocate memory for dynamic long\n");
            // Cleanup already allocated resources
            for (size_t j = 0; j < i; ++j) {
                free(records[j].dynamicLong);
            }
            free(records);
            free(keys);
            free(offsets);
            return;
        }
    }

    // Apply callback to each record if provided
    if (callback) {
        for (size_t i = 0; i < numRecords; ++i) {
            callback(&records[i]);
        }
    }

    // Read integers from standard input and find the maximum value
    size_t currentSize = 10;
    int *inputNumbers = malloc(currentSize * sizeof(int));
    if (!inputNumbers) {
        fprintf(stderr, "Failed to allocate memory for input numbers\n");
        for (size_t i = 0; i < numRecords; ++i) {
            free(records[i].dynamicLong);
        }
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    size_t count = 0;
    int number;
    printf("Enter integers (end with -1):\n");
    while (scanf("%d", &number) == 1 && number != -1) {
        if (count >= currentSize) {
            currentSize *= 2;
            inputNumbers = realloc(inputNumbers, currentSize * sizeof(int));
            if (!inputNumbers) {
                fprintf(stderr, "Failed to reallocate memory for input numbers\n");
                free(records);
                free(keys);
                free(offsets);
                return;
            }
        }
        inputNumbers[count++] = number;
    }

    int maxNumber = findMax(inputNumbers, count);
    printf("Maximum integer entered: %d\n", maxNumber);

    // Cleanup
    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i].dynamicLong);
    }
    free(records);
    free(keys);
    free(offsets);
    free(inputNumbers);
}

// Example callback function
void exampleCallback(Record *record) {
    printf("Processing record with value: %d\n", record->value);
}

int main() {
    // Seed the random number generator for OpenSSL (if used)
    srand(time(NULL));
    processRecordsAndFindMax(5, 5, 10, exampleCallback);
    return 0;
}
