// External library header for random number generation
extern int external_random_number(int min, int max);

typedef struct Dependency {
    size_t index;
    struct Dependency *next;
} Dependency;

typedef struct Record {
    int value;
    char key[256];
    long *dynamic_long;
    uint64_t timestamp;
    bool flag;
    Dependency *dependencies;
} Record;

void free_dependencies(Dependency *head) {
    while (head != NULL) {
        Dependency *temp = head;
        head = head->next;
        free(temp);
    }
}

void free_records(Record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].dynamic_long != NULL) {
            free(records[i].dynamic_long);
        }
        free_dependencies(records[i].dependencies);
    }
    free(records);
}

