        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = external_random_number(1, 100);
        snprintf(records[i].key, sizeof(records[i].key), "Key_%d", keys[i]);
        records[i].dynamic_long = malloc(sizeof(long));
        if (!records[i].dynamic_long) {
            fprintf(stderr, "Memory allocation failed\n");
            free_records(records, i);
            free(offsets);
            free(keys);
            return;
