        *(records[i].dynamic_long) = external_random_number(1, 1000);

        records[i].timestamp = time(NULL);
        records[i].flag = external_random_number(0, 1) != 0;

        // Initialize dependencies
        Dependency *head = NULL;
        Dependency **current = &head;
        size_t dep_count = external_random_number(1, 5);
        for (size_t j = 0; j < dep_count; ++j) {
            Dependency *new_dep = malloc(sizeof(Dependency));
