            new_dep->next = NULL;
            *current = new_dep;
            current = &new_dep->next;
        }

        pthread_mutex_lock(&lock);
        records[i].dependencies = head;
        pthread_mutex_unlock(&lock);

        if (callback) {
            callback(&records[i]);
        }
    }

    // Find max value
