    unsigned long seed = time(NULL);

    if (table_init(&table, 10, 0.0, 100.0, seed, example_callback) == 0) {
        // Use the table
        table_free(&table);
    } else {
        fprintf(stderr, "Failed to initialize table.\n");
    }

    return 0;
}
