            free(system->offsets);
            free(system->keys);
            free(system->records);
            free(system->events);
            pthread_mutex_destroy(&system->mutex);
            free(system);
            return NULL;
        }

        *rec->timestamp_ptr = system->timestamp_lib.get_timestamp(); // Use external lib
        system->records[i] = rec;

        system->events[i] = *rec->timestamp_ptr;
    }

    return system;
}

void destroy_log_system(log_system_t* system) {
    if (!system) return;

    pthread_mutex_lock(&system->mutex);
    for (size_t i = 0; i < system->num_entries; ++i) {
        free(system->records[i]->timestamp_ptr);
        free(system->records[i]);
    }
