    free(system->keys);
    free(system->records);
    free(system->events);
    pthread_mutex_unlock(&system->mutex);

    system->random_lib.cleanup(); // Clean up external library
    system->timestamp_lib.cleanup();

    pthread_mutex_destroy(&system->mutex);
    free(system);
}

void log_entry(log_system_t* system, size_t entry_index) {
    if (!system || entry_index >= system->num_entries) return;

