// Custom allocator structure for memory reuse
typedef struct {
    size_t size;
    void* buffer;
    size_t used_size;
    // Additional fields for memory management
} MemoryPool;

MemoryPool create_memory_pool(size_t size) {
    MemoryPool pool = {size, malloc(size), 0};
    if (!pool.buffer) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    return pool;
}

void* custom_alloc(MemoryPool* pool, size_t requested_size) {
    pthread_mutex_lock(&pool->lock);
    if (requested_size + pool->used_size <= pool->size) {
        void* ptr = (char*)pool->buffer + pool->used_size;
        pool->used_size += requested_size;
        pthread_mutex_unlock(&pool->lock);
        return ptr;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;  // Allocation failed
}

void free_memory_pool(MemoryPool* pool) {
    free(pool->buffer);
    pool->buffer = NULL;
}

Row pseudo_random_row(size_t seed, int index) {
    srand48(seed + index);  // Custom RNG for longer period
    Row row;
    row.primary_key = (long)index;
    snprintf(row.string_value, sizeof(row.string_value), "Value%ld", row.primary_key);
    row.numerical_data = drand48() * 100.0;  // Range [0, 100)
    return row;
}

