    MemoryPool pool = create_memory_pool(row_count * sizeof(Row));
    table.rows = custom_alloc(&pool, row_count * sizeof(Row));

    if (!table.rows) {
        free_memory_pool(&pool);
        fprintf(stderr, "Failed to allocate rows\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < row_count; ++i) {
        Row row = pseudo_random_row(seed, i);
        memcpy((char*)table.rows + i * sizeof(Row), &row, sizeof(Row));

        // Invoke callback if provided
        #ifdef CUSTOM_CALLBACK
        custom_callback(&table.rows[i]);
        #endif
    }

    return table;
}

#ifdef CUSTOM_CALLBACK
