} Record;

// External library function for secure random number generation
extern int secure_random_int(int min, int max);

// Custom callback function type
typedef void (*RecordCallback)(Record *);

// Function to initialize records
int initializeRecords(long **offsets, int size_offsets, int **keys, int size_keys,
                      Record **records, int size_records, unsigned long seed,
                      RecordCallback callback) {

    // Initialize mutex for thread safety
    static pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL)) {
        fprintf(stderr, "Mutex init failed\n");
        return -1;  // Mutex initialization failure
    }

    // Seed the random number generator
    srand(seed);

    // Allocate memory for offsets and keys
    *offsets = malloc(size_offsets * sizeof(long));
    if (!*offsets) {
        perror("Failed to allocate memory for offsets");
        pthread_mutex_destroy(&lock);
        return -1;
    }

    *keys = malloc(size_keys * sizeof(int));
    if (!*keys) {
        perror("Failed to allocate memory for keys");
        free(*offsets);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    // Initialize offsets and keys
    for (int i = 0; i < size_offsets && i < size_keys; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = i;
    }

    // Allocate memory for records
    *records = malloc(size_records * sizeof(Record));
    if (!*records) {
        perror("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    // Initialize records
    for (int i = 0; i < size_records; ++i) {
        (*records)[i].value = secure_random_int(1, 100);  // Example range

        // Allocate memory for key and data pointer
        pthread_mutex_lock(&lock);
        (*records)[i].key = malloc(50 * sizeof(char));  // Assume max key length is 49 + null terminator
        if (!(*records)[i].key) {
            perror("Failed to allocate memory for record key");
            free(*offsets);
            free(*keys);
            free(*records);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return -1;
        }

        (*records)[i].dataPointer = malloc(sizeof(long));
        if (!(*records)[i].dataPointer) {
            perror("Failed to allocate memory for record data pointer");
            free((*records)[i].key);
            free(*offsets);
            free(*keys);
            free(*records);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return -1;
        }
        pthread_mutex_unlock(&lock);

        // Set key to a default value
        snprintf((*records)[i].key, 50, "Record_%d", i);

        // Invoke the callback function if provided
        if (callback) {
            callback(&(*records)[i]);
        }
    }

    // Free mutex lock as it's no longer needed after initialization
    pthread_mutex_destroy(&lock);

    return 0;  // Success
}

// Function to free allocated memory
void cleanup(long *offsets, int size_offsets, int *keys, int size_keys,
             Record *records, int size_records) {
    if (offsets) free(offsets);
    if (keys) free(keys);

    for (int i = 0; i < size_records; ++i) {
        if (records[i].key) free(records[i].key);
        if (records[i].dataPointer) free(records[i].dataPointer);
    }

    if (records) free(records);
}
