#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ConfigNode {
    char key[32];
    char value[64];
    struct ConfigNode* children;
    struct ConfigNode* next;
} ConfigNode;

// External library function prototype for generating unique identifiers
extern void generate_unique_id(char* id, size_t size);

// Callback function type definition
typedef void (*Callback)(ConfigNode*);

// Thread safety lock
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a node with error handling and callback invocation
ConfigNode* init_config_node(int level, int index, char* seed, Callback callback) {
    ConfigNode* node = (ConfigNode*)malloc(sizeof(ConfigNode));
    if (!node) return NULL;

    snprintf(node->key, sizeof(node->key), "section%ds%d", level, index);

    if (seed) {
        generate_unique_id((char*)node->value, sizeof(node->value));
    } else {
        snprintf(node->value, sizeof(node->value), "default_value_%d", index);
    }

    node->children = NULL;
    node->next = NULL;

    // Invoke callback if provided
    if (callback) {
        callback(node);
    }

    return node;
}

// Function to create a hierarchical configuration system
ConfigNode* create_config_system(int levels, int nodes_per_level, char* seed, Callback callback) {
    pthread_mutex_lock(&config_lock);

    ConfigNode** current_level = (ConfigNode**)malloc(levels * sizeof(ConfigNode*));
    if (!current_level) {
        pthread_mutex_unlock(&config_lock);
        return NULL;
    }

    for (int i = 0; i < levels; ++i) {
        int nodes_count = (i == 0) ? 1 : nodes_per_level;

        for (int j = 0; j < nodes_count; ++j) {
            ConfigNode* node = init_config_node(i, j, seed, callback);
            if (!node) {
                // Free previously allocated nodes on failure
                while (current_level[i - 1]) {
                    ConfigNode* temp = current_level[i - 1];
                    current_level[i - 1] = temp->next;
                    free(temp);
                }
                free(current_level);
                pthread_mutex_unlock(&config_lock);
                return NULL;
            }

            if (i == 0) {
                current_level[i] = node;
            } else {
                ConfigNode* parent = current_level[i - 1];
                while (parent->next) {
                    parent = parent->next;
                }
                parent->next = node;
            }

            node->next = NULL;

            if (!current_level[i]) {
                current_level[i] = node;
            } else {
                ConfigNode* temp = current_level[i];
                while (temp->next) {
                    temp = temp->next;
                }
                temp->next = node;
            }
        }

        // Link children
        for (int j = 0; j < nodes_count; ++j) {
            if (current_level[i]) {
                ConfigNode* parent = current_level[i];
                for (int k = 0; k < nodes_per_level && parent; ++k, parent = parent->next) {
                    if (!parent->children) {
                        parent->children = init_config_node(i + 1, k, seed, callback);
                        if (!parent->children) {
                            // Free children on failure
                            while (current_level[i]) {
                                ConfigNode* temp = current_level[i];
                                current_level[i] = temp->next;
                                free(temp);
                            }
                            pthread_mutex_unlock(&config_lock);
                            return NULL;
                        }
                    } else {
                        parent->children = init_config_node(i + 1, k, seed, callback);
                        if (!parent->children) {
                            // Free children on failure
                            ConfigNode* child_temp = parent->children;
                            while (child_temp) {
                                ConfigNode* temp = child_temp;
                                child_temp = child_temp->next;
                                free(temp);
                            }
                            pthread_mutex_unlock(&config_lock);
                            return NULL;
                        }
                        ConfigNode* child = parent->children;
                        while (child->next) {
                            child = child->next;
                        }
                    }
                }
            }
        }
    }

    pthread_mutex_unlock(&config_lock);
    return current_level[0];
}

// Function to free all allocated memory
void free_config_system(ConfigNode* root) {
    if (!root) return;

    ConfigNode* temp;
    while (root) {
        temp = root->next;

        // Free children recursively
        if (root->children) {
            free_config_system(root->children);
        }

        free(root);
        root = temp;
    }
}

// Example callback function
void example_callback(ConfigNode* node) {
    printf("Initialized node: %s -> %s\n", node->key, node->value);
}

int main() {
    ConfigNode* config_root = create_config_system(3, 2, "seed123", example_callback);

    // Simulate usage

    free_config_system(config_root);

    return 0;
}
```

