#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MINIMAL_RECORD_SIZE (sizeof(int) + sizeof(char*) + sizeof(long*))
#define RANDOM_RANGE 100

typedef struct {
    int value;
    char *key;
    long *offset;
} Record;

typedef void (*CallbackFunc)(Record *);

int initialize_arrays(long *offsets, int *keys, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;
        keys[i] = i;

        if (offsets[i] != i || keys[i] != i)
            return -1; // Integrity check failed
    }
    return 0; // Success
}

void randomize_record(Record *record, int seed) {
    srand(seed);
    record->value = rand() % RANDOM_RANGE;
}

void initialize_records(Record **records, size_t count, CallbackFunc callback, int reduced_memory_mode) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    *records = (Record *)calloc(count, sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&lock);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        char key_buffer[32];

        snprintf(key_buffer, sizeof(key_buffer), "Key_%zu", i);

        (*records)[i].key = strdup(reduced_memory_mode ? "Shared_Key" : key_buffer);
        if ((*records)[i].key == NULL) {
            fprintf(stderr, "Memory allocation failed for key\n");
            pthread_mutex_lock(&lock);
            // Cleanup logic here
            for (size_t j = 0; j < i; ++j)
                free((*records)[j].key);
            free(*records);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return;
        }

        (*records)[i].offset = malloc(sizeof(long));
        if ((*records)[i].offset == NULL) {
            fprintf(stderr, "Memory allocation failed for offset\n");
            pthread_mutex_lock(&lock);
            // Cleanup logic here
            free((*records)[i].key);
            for (size_t j = 0; j < i; ++j)
                free((*records)[j].key);
            free(*records);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return;
        }

        randomize_record(&(*records)[i], i);

        if (callback != NULL) {
            callback(&(*records)[i]);
        }
    }

    pthread_mutex_destroy(&lock);
}

void record_callback(Record *record) {
    // Example processing
    printf("Processing Record: Value=%d, Key=%s\n", record->value, record->key);
}

int main() {
    size_t array_size = 10;
    long *offset_array = (long *)malloc(array_size * sizeof(long));
    int *key_array = (int *)malloc(array_size * sizeof(int));

    if (initialize_arrays(offset_array, key_array, array_size) != 0) {
        fprintf(stderr, "Array initialization failed\n");
        free(offset_array);
        free(key_array);
        return EXIT_FAILURE;
    }

    size_t record_count = 5;
    Record *records;

    initialize_records(&records, record_count, record_callback, 0);

    // Clean up
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].key);
        free(records[i].offset);
    }
    free(records);

    free(offset_array);
    free(key_array);

    return EXIT_SUCCESS;
}
