typedef struct {
    char *log_message;
    int priority_level;
    long timestamp;
} Event;

#define MAX_LOG_MESSAGE_SIZE 256

// Function to initialize an array of events
Event* initialize_events(size_t num_events, size_t message_size, const char **log_messages, int *priorities, long *timestamps) {
    if (message_size == 0 || log_messages == NULL || priorities == NULL || timestamps == NULL) {
        return NULL;
    }

    // Validate the buffer sizes
    if (message_size > MAX_LOG_MESSAGE_SIZE) {
        fprintf(stderr, "Error: Log message size exceeds maximum limit.\n");
        return NULL;
    }

    Event *events = malloc(num_events * sizeof(Event));
    if (!events) {
        perror("Failed to allocate memory for events");
        return NULL;
    }

    for (size_t i = 0; i < num_events; ++i) {
        // Allocate buffer for log messages
        events[i].log_message = malloc(message_size);
        if (!events[i].log_message) {
            perror("Failed to allocate memory for log message");
            free(events);  // Free previously allocated memory
            return NULL;
        }

        // Ensure the log message fits in the provided buffer
        strncpy(events[i].log_message, log_messages[i], message_size - 1);
        events[i].log_message[message_size - 1] = '\0';

        events[i].priority_level = priorities[i];
        events[i].timestamp = timestamps[i];
    }

    return events;
}

// Function to free the allocated memory for events
void free_events(Event *events, size_t num_events) {
    if (events == NULL) {
        return;
    }

    for (size_t i = 0; i < num_events; ++i) {
        free(events[i].log_message);
    }

    free(events);
}

