    size_t num_events = sizeof(log_messages) / sizeof(log_messages[0]);

    // Initialize events with predefined log messages
    Event *events = initialize_events(num_events, MAX_LOG_MESSAGE_SIZE, log_messages, priorities, timestamps);

    if (events == NULL) {
        return EXIT_FAILURE;
    }

    // Use the events...

    // Free allocated memory to prevent leaks
    free_events(events, num_events);

    return 0;
}
```

