```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

RecordList* initialize_record_list(size_t initial_capacity) {
    RecordList* list = malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->capacity = initial_capacity;
    list->count = 0;
    list->records = calloc(initial_capacity, sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_record_list(RecordList* list, size_t new_capacity) {
    Record *new_records = realloc(list->records, new_capacity * sizeof(Record));
    if (!new_records) return;

    list->records = new_records;
    list->capacity = new_capacity;
}

int add_record(RecordList* list, long offset, int key, int value) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    if (list->count >= list->capacity) {
        resize_record_list(list, list->capacity * 2);
        if (list->capacity / 2 != list->count) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Resize failed
        }
    }

    size_t index = list->count++;
    list->records[index] = (Record){offset, key, value};

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_record_value(RecordList* list, int key, int min_val, int max_val) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            srand(time(NULL)); // Seed with current time
            list->records[i].value = min_val + rand() % (max_val - min_val + 1);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Key not found
}

void serialize_record_list(RecordList* list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->records, sizeof(Record), list->count, file);

    fclose(file);
}

void record_list_callback(int (*callback)(int key, int value), RecordList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        callback(list->records[i].key, list->records[i].value);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_record_list(RecordList* list) {
    free(list->records);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

### Notes:
- **Thread Safety**: The `pthread_mutex_t` lock is used to ensure thread safety during modifications.
- **Dynamic Resizing**: The record list is resized dynamically when needed, using the `realloc` function.
- **Serialization**: Records are serialized in a binary format for efficient storage and retrieval.
- **Random Value Update**: A simple random number generator seeds with time, updating each record's value within specified limits.
- **Error Handling**: Basic error handling is implemented; however, further enhancements can be made as needed.

