void processAndLogEvents(size_t num_records, size_t events_per_record,
                         int min_value, int max_value, unsigned int seed,
                         int log_fd) {

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    long *timestamps = malloc(num_records * sizeof(long));
    int *event_ids = malloc(num_records * sizeof(int));
    event_t **events_array = malloc(num_records * sizeof(event_t *));

    if (!timestamps || !event_ids || !events_array) {
        dprintf(log_fd, "Memory allocation failed\n");
        free(timestamps);
        free(event_ids);
        free(events_array);
        return;
    }

