        pthread_mutex_lock(&lock);

        timestamps[i] = rand() % 1000000000L;
        event_ids[i] = min_value + (rand() % (max_value - min_value + 1));
        events_array[i] = malloc(events_per_record * sizeof(event_t));

        if (!events_array[i]) {
            dprintf(log_fd, "Memory allocation failed\n");
            free(timestamps);
            free(event_ids);
            for (size_t j = 0; j < i; ++j) {
                free(events_array[j]);
            }
            free(events_array);
            pthread_mutex_unlock(&lock);
            return;
        }

        const char *messages[] = {"Start", "Processing", "End", "Error"};

        for (size_t j = 0; j < events_per_record; ++j) {
            snprintf(events_array[i][j].message, MAX_MESSAGE_SIZE,
                     "%s Event %zu", messages[j % 4], j);
            events_array[i][j].priority = rand() % 10;
            events_array[i][j].timestamp = timestamps[i];
        }

        pthread_mutex_unlock(&lock);
    }

    size_t capacity = 8;
    int *numbers = malloc(capacity * sizeof(int));
    size_t count = 0;

    if (!numbers) {
        dprintf(log_fd, "Memory allocation failed\n");
        free(timestamps);
        free(event_ids);
        for (size_t i = 0; i < num_records; ++i) {
            free(events_array[i]);
        }
        free(events_array);
        return;
    }

    int number;

    while (1) {
        pthread_mutex_lock(&lock);

        if (scanf("%d", &number) != 1 || number == SENTINEL) {
            break;
        }

        if (count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                dprintf(log_fd, "Memory reallocation failed\n");
                pthread_mutex_unlock(&lock);
                free(timestamps);
                free(event_ids);
                for (size_t i = 0; i < num_records; ++i) {
                    free(events_array[i]);
                }
                free(events_array);
                return;
            }
        }

        numbers[count++] = number;

        pthread_mutex_unlock(&lock);
    }

    int *max_val_ptr = findMax(numbers, count);

    if (max_val_ptr) {
        printf("The largest integer is: %d\n", (int)(intptr_t)(*max_val_ptr));
    } else {
        printf("No valid integers were provided.\n");
    }

    free(max_val_ptr);
    free(numbers);

    for (size_t i = 0; i < num_records; ++i) {
        free(events_array[i]);
    }
    free(events_array);
    free(timestamps);
    free(event_ids);
}
