#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum buffer size for labels to prevent overflow issues.
#define MAX_LABEL_SIZE 64

typedef struct {
    double value;
    char label[MAX_LABEL_SIZE];
    time_t timestamp;
} Metric;

typedef struct {
    Metric *metrics;
    size_t count;
    size_t capacity;
    double rolling_sum;
    double rolling_square_sum;
    size_t window_size;
} MetricsCollection;

// Function to initialize the metrics collection
MetricsCollection* init_metrics_collection(size_t initial_capacity, size_t window_size) {
    if (initial_capacity == 0 || window_size == 0) return NULL;

    MetricsCollection *collection = malloc(sizeof(MetricsCollection));
    if (!collection) return NULL;

    collection->metrics = calloc(initial_capacity, sizeof(Metric));
    if (!collection->metrics) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->rolling_sum = 0.0;
    collection->rolling_square_sum = 0.0;
    collection->window_size = window_size;

    return collection;
}

// Function to add a metric
int add_metric(MetricsCollection *collection, double value, const char *label) {
    if (collection == NULL || label == NULL || strlen(label) >= MAX_LABEL_SIZE)
        return -1;

    time_t current_time = time(NULL);

    // Resize array if necessary
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Metric *new_metrics = realloc(collection->metrics, new_capacity * sizeof(Metric));
        if (!new_metrics) return -1;

        collection->metrics = new_metrics;
        collection->capacity = new_capacity;
    }

    // Add the metric
    Metric *metric = &collection->metrics[collection->count++];
    metric->value = value;
    strncpy(metric->label, label, MAX_LABEL_SIZE);
    metric->timestamp = current_time;

    // Update rolling statistics
    if (collection->count > collection->window_size) {
        // Remove the oldest metric's effect from rolling sums
        Metric *oldest_metric = &collection->metrics[collection->count - collection->window_size - 1];
        collection->rolling_sum -= oldest_metric->value;
        collection->rolling_square_sum -= oldest_metric->value * oldest_metric->value;
    }

    // Add the new metric's effect to rolling sums
    collection->rolling_sum += value;
    collection->rolling_square_sum += value * value;

    return 0;
}

// Function to calculate rolling average and standard deviation
int get_rolling_stats(MetricsCollection *collection, double *average, double *std_deviation) {
    if (collection == NULL || average == NULL || std_deviation == NULL)
        return -1;

    size_t valid_count = collection->count < collection->window_size ? collection->count : collection->window_size;
    if (valid_count == 0) {
        *average = 0.0;
        *std_deviation = 0.0;
        return 0;
    }

    *average = collection->rolling_sum / valid_count;

    double mean_square = collection->rolling_square_sum / valid_count;
    double variance = mean_square - (*average) * (*average);
    if (variance < 0) variance = 0; // Guard against numerical issues

    *std_deviation = sqrt(variance);

    return 0;
}

// Function to free the metrics collection
void free_metrics_collection(MetricsCollection *collection) {
    if (collection != NULL) {
        free(collection->metrics);
        free(collection);
    }
}
