#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "uuid/uuid.h"

#define OFFSET_SIZE 100
#define KEY_SIZE 100
#define RECORD_SIZE 100
#define EVENT_SIZE 100
#define METADATA_SIZE 100
#define ERROR_BUFFER_SIZE 10

typedef struct {
    int value;
    char string_key[50];
    long* dynamic_long;
    time_t timestamp;
    time_t metadata_timestamp;
} Record;

typedef struct {
    long offset_values[OFFSET_SIZE];
    int key_values[KEY_SIZE];
    Record records[RECORD_SIZE];
    time_t event_timestamps[EVENT_SIZE];
    char metadata_tags[METADATA_SIZE][37]; // UUID is 36 characters + null terminator
    pthread_mutex_t lock;
} DataStructures;

typedef void (*RecordInitCallback)(const Record*, const char*, time_t);

void log_error(const char* message, int* error_log, int* log_index) {
    if (log_index < ERROR_BUFFER_SIZE) {
        fprintf(stderr, "%s\n", message);
        strncpy(error_log[*log_index], message, 256);
        (*log_index)++;
    }
}

int generate_uuid(char* uuid_str) {
    uuid_t uuid;
    uuid_generate_random(uuid);
    char* p = (char*)uuid_to_string(uuid, NULL);
    strncpy(uuid_str, p, 37); // Copy UUID string to buffer
    free(p);
    return 0;
}

void initialize_data_structures(DataStructures* data,
                                int random_range_min,
                                int random_range_max,
                                unsigned long seed,
                                RecordInitCallback callback) {
    pthread_mutex_lock(&data->lock);

    int error_log[ERROR_BUFFER_SIZE];
    int log_index = 0;

    // Initialize offset, key, and event with sequential numbers
    for (int i = 0; i < OFFSET_SIZE && i < EVENT_SIZE; ++i) {
        data->offset_values[i] = i;
        data->key_values[i] = i;
        time(&data->event_timestamps[i]);
        if (i > 0 && data->event_timestamps[i] <= data->event_timestamps[i - 1]) {
            data->event_timestamps[i]++;
        }
    }

    // Initialize records and metadata
    srand(seed);
    for (int i = 0; i < RECORD_SIZE; ++i) {
        Record* record = &data->records[i];
        record->value = rand() % (random_range_max - random_range_min + 1) + random_range_min;
        snprintf(record->string_key, sizeof(record->string_key), "key_%d", i);

        // Allocate and initialize dynamic_long
        record->dynamic_long = malloc(sizeof(long));
        if (!record->dynamic_long) {
            log_error("Failed to allocate memory for dynamic_long.", error_log, &log_index);
            pthread_mutex_unlock(&data->lock);
            return;
        }
        *record->dynamic_long = (long)i;

        // Set metadata timestamp and UUID
        record->metadata_timestamp = data->event_timestamps[i % EVENT_SIZE];
        generate_uuid(data->metadata_tags[i]);

        if (callback) {
            callback(record, data->metadata_tags[i], record->metadata_timestamp);
        }
    }

    pthread_mutex_unlock(&data->lock);
}

void cleanup_data_structures(DataStructures* data) {
    for (int i = 0; i < RECORD_SIZE; ++i) {
        free(data->records[i].dynamic_long);
    }
}

// Example callback function
void example_callback(const Record* record, const char* metadata, time_t event_timestamp) {
    printf("Record initialized with value: %d, metadata: %s, timestamp: %ld\n",
           record->value, metadata, (long)event_timestamp);
}

int main() {
    DataStructures data = {0};
    pthread_mutex_init(&data.lock, NULL);

    initialize_data_structures(&data, 1, 100, 42, example_callback);
    cleanup_data_structures(&data);

    pthread_mutex_destroy(&data.lock);
    return 0;
}
