#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char stringKey[256];
    long *timestampPtr;
} record;

typedef struct {
    long offsets[1000];
    int keys[1000];
    record records[1000];
    time_t event[1000];
} logEntry;

typedef struct dataNode {
    float floatValue;
    struct dataNode **childNodes;
    size_t numChildren;
    struct dataNode *parent;
} dataNode;

#define INITIAL_CHILDREN 4
#define MAX_LOG_ENTRIES 1000000

pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;
dataNode *rootDataNode = NULL;
logEntry *logSystem[MAX_LOG_ENTRIES];
size_t logIndex = 0;

void initializeLogEntry(logEntry *entry, size_t index) {
    for (size_t i = 0; i < 1000; ++i) {
        entry->offsets[i] = i + index * 1000;
        entry->keys[i] = i + index * 1000;
        entry->records[i].value = rand() % 100;
        snprintf(entry->records[i].stringKey, sizeof(entry->records[i].stringKey), "key_%zu_%zu", index, i);
        entry->records[i].timestampPtr = malloc(sizeof(long));
        *(entry->records[i].timestampPtr) = time(NULL);
        entry->event[i] = time(NULL);
    }
}

void freeLogEntry(logEntry *entry) {
    for (size_t i = 0; i < 1000; ++i) {
        free(entry->records[i].timestampPtr);
    }
}

logEntry* allocateLogEntry(size_t index) {
    pthread_mutex_lock(&memoryMutex);
    if (index >= MAX_LOG_ENTRIES) {
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    logEntry *entry = malloc(sizeof(logEntry));
    if (!entry) {
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    initializeLogEntry(entry, index);
    logSystem[index] = entry;
    logIndex++;
    pthread_mutex_unlock(&memoryMutex);

    return entry;
}

void freeLogSystem() {
    for (size_t i = 0; i < logIndex; ++i) {
        if (logSystem[i]) {
            freeLogEntry(logSystem[i]);
            free(logSystem[i]);
        }
    }
}

dataNode* createDataNode(float value, dataNode *parent, size_t numChildren) {
    pthread_mutex_lock(&memoryMutex);

    dataNode *node = malloc(sizeof(dataNode));
    if (!node) {
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    node->floatValue = value;
    node->childNodes = calloc(numChildren, sizeof(dataNode *));
    node->numChildren = numChildren;
    node->parent = parent;

    pthread_mutex_unlock(&memoryMutex);

    return node;
}

void freeDataNodes(dataNode *node) {
    if (!node) return;

    for (size_t i = 0; i < node->numChildren; ++i) {
        freeDataNodes(node->childNodes[i]);
    }

    free(node->childNodes);
    free(node);
}

void depthFirstTraversal(dataNode *node, void (*callback)(dataNode *)) {
    if (!node || !callback) return;

    callback(node);

    for (size_t i = 0; i < node->numChildren; ++i) {
        depthFirstTraversal(node->childNodes[i], callback);
    }
}

void initializeRoot(float initialValue, float (*randomFloatGenerator)(unsigned int *seed), unsigned int *seed) {
    rootDataNode = createDataNode(initialValue, NULL, INITIAL_CHILDREN);
    if (!rootDataNode) {
        fprintf(stderr, "Failed to allocate root data node.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < INITIAL_CHILDREN; ++i) {
        float value = randomFloatGenerator(seed);
        rootDataNode->childNodes[i] = createDataNode(value, rootDataNode, INITIAL_CHILDREN);
        if (!rootDataNode->childNodes[i]) {
            fprintf(stderr, "Failed to allocate child data node.\n");
            exit(EXIT_FAILURE);
        }
    }
}

float generateRandomFloat(unsigned int *seed) {
    float fract = rand_r(seed) / (float)RAND_MAX;
    return fract;
}

void processNode(dataNode *node) {
    printf("Processing node with value: %f\n", node->floatValue);
}

int main() {
    srand(time(NULL));
    unsigned int seed = 12345;

    initializeRoot(0.0, generateRandomFloat, &seed);

    depthFirstTraversal(rootDataNode, processNode);

    freeDataNodes(rootDataNode);

    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        allocateLogEntry(i);
    }

    freeLogSystem();

    return 0;
}
