    if (size == 0) return INT_MIN; // No elements
    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void processRecordsAndFindMax(size_t offsetSize, size_t keySize, size_t recordSize, unsigned int seed,
                              void (*callback)(record *), int initialInputArraySize) {

    setSeed(seed);

    long *offsets = malloc(offsetSize * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation for offsets failed\n");
        return;
    }

    int *keys = malloc(keySize * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation for keys failed\n");
        return;
    }

    record *records = malloc(recordSize * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Memory allocation for records failed\n");
        return;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < offsetSize; ++i) {
        offsets[i] = i;
    }

    for (size_t i = 0; i < keySize; ++i) {
        keys[i] = i;
    }

    // Initialize records with random values and pointers
    for (size_t i = 0; i < recordSize; ++i) {
        records[i].value = rand() % 100 + 1; // Random number between 1 and 100
        snprintf(records[i].key, sizeof(records[i].key), "Key_%zu", i);
        records[i].ptr = malloc(sizeof(long));
        if (!records[i].ptr) {
            fprintf(stderr, "Memory allocation for record pointer failed\n");
            return;
        }
        *(records[i].ptr) = offsets[i % offsetSize];
    }

    // Callback processing
    if (callback) {
        for (size_t i = 0; i < recordSize; ++i) {
            callback(&records[i]);
        }
    }

    int *inputArray = malloc(initialInputArraySize * sizeof(int));
    size_t currentSize = initialInputArraySize;
    size_t count = 0;

    if (!inputArray) {
        fprintf(stderr, "Memory allocation for input array failed\n");
        return;
    }

    printf("Enter integers (enter -1 to stop):\n");

    while (1) {
        int num;
        scanf("%d", &num);

        if (num == -1) break;

        if (count >= currentSize) {
            size_t newSize = currentSize * 2;
            if (newSize < count + 1) {
                fprintf(stderr, "Integer overflow in input array resizing\n");
                free(inputArray);
                return;
            }

            int *temp = realloc(inputArray, newSize * sizeof(int));
            if (!temp) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(inputArray);
                return;
            }
            inputArray = temp;
            currentSize = newSize;
        }

        inputArray[count++] = num;
    }

    int maxVal = findMax(inputArray, count);

    printf("The largest integer is: %d\n", maxVal);

    // Cleanup
    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i].ptr);
    }
    free(records);
    free(keys);
    free(offsets);
    free(inputArray);
}
