    int largest = records[0].value;
    for (int i = 1; i < recordCount; ++i) {
        if (records[i].isValid && records[i].value > largest) {
            largest = records[i].value;
        }
    }

    pthread_mutex_unlock(&recordsLock);

    return (void *)(intptr_t)largest;
}

void processUserPreferencesAndDataRecords(void (*callback)(void)) {
    // Read integers from standard input
    int n, value;
    printf("Enter the number of integers: ");
    if (scanf("%d", &n) != 1) {
        perror("Failed to read integer count");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; ++i) {
        printf("Enter integer %d: ", i + 1);
        if (scanf("%d", &value) != 1 || !validateInteger(value)) {
            perror("Invalid input or failed to read integer");
            exit(EXIT_FAILURE);
        }
        addRecord(value, callback);
    }

    int *largest = findLargestInteger();
    printf("The largest integer is: %d\n", (intptr_t)largest);

    // Add preferences and records as needed
    char *tags[] = {"tag1", "tag2"};
    addPreference("theme", STRING, "light", NULL, 2, tags, callback);
}

int main() {
    processUserPreferencesAndDataRecords(NULL);
    return 0;
}
