- Initialization and dynamic resizing of the preferences array.
- Secure input handling with validation.
- Thread safety using mutexes for preference management.
- A callback mechanism for custom processing during initialization.']

['Below is a C implementation for `dynamicNetworkManager` following your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char ipAddress[16];
    int port;
    time_t lastActivity;
} Node;

typedef struct Request {
    void *data; // Placeholder for user-defined data
    struct Request *next;
} Request;

typedef struct {
    long *offsets;
    int *keys;
    Node **nodes;
    size_t nodeCount;
    size_t maxNodes;
    pthread_mutex_t nodeMutex;

    Request **requests;
    size_t requestCount;
    size_t maxRequests;
    pthread_mutex_t requestMutex;

    int *inputNumbers;
    size_t inputCount;
} NetworkManager;

void setRandomNodeProperties(Node *node, int minPort, int maxPort) {
    sprintf(node->ipAddress, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    node->port = (rand() % (maxPort - minPort + 1)) + minPort;
    node->lastActivity = time(NULL);
}

void initializeNetworkManager(NetworkManager *manager, size_t offsetSize, size_t keySize,
                             int minNodes, int maxNodes, int minRequests, int maxRequests) {

    manager->offsets = (long *)calloc(offsetSize, sizeof(long));
    manager->keys = (int *)calloc(keySize, sizeof(int));

    for (size_t i = 0; i < offsetSize; ++i)
        manager->offsets[i] = (long)i;

    for (size_t i = 0; i < keySize; ++i)
        manager->keys[i] = (int)i;

    size_t nodeSize = minNodes;
    manager->nodes = (Node **)calloc(nodeSize, sizeof(Node *));
    manager->nodeCount = 0;
    manager->maxNodes = maxNodes;
    pthread_mutex_init(&manager->nodeMutex, NULL);

    size_t requestSize = minRequests;
    manager->requests = (Request **)calloc(requestSize, sizeof(Request *));
    manager->requestCount = 0;
    manager->maxRequests = maxRequests;
    pthread_mutex_init(&manager->requestMutex, NULL);

    manager->inputNumbers = NULL;
    manager->inputCount = 0;

    srand(time(NULL)); // Seed random number generator
}

void addNode(NetworkManager *manager, void (*callback)(Node*)) {
    pthread_mutex_lock(&manager->nodeMutex);

    if (manager->nodeCount >= manager->maxNodes) {
        size_t newSize = manager->maxNodes ? manager->maxNodes * 2 : 8;
        Node **newArray = realloc(manager->nodes, newSize * sizeof(Node *));

        if (!newArray) {
            fprintf(stderr, "Failed to allocate memory for nodes\n");
            pthread_mutex_unlock(&manager->nodeMutex);
            return;
        }

        memset(newArray + manager->maxNodes, 0, (newSize - manager->maxNodes) * sizeof(Node *));
        manager->nodes = newArray;
        manager->maxNodes = newSize;
    }

    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for node\n");
        pthread_mutex_unlock(&manager->nodeMutex);
        return;
    }

    setRandomNodeProperties(node, 1024, 65535);

    manager->nodes[manager->nodeCount++] = node;

    if (callback)
        callback(node);

    pthread_mutex_unlock(&manager->nodeMutex);
}

void addRequest(NetworkManager *manager) {
    pthread_mutex_lock(&manager->requestMutex);

    if (manager->requestCount >= manager->maxRequests) {
        size_t newSize = manager->maxRequests ? manager->maxRequests * 2 : 8;
        Request **newArray = realloc(manager->requests, newSize * sizeof(Request *));

        if (!newArray) {
            fprintf(stderr, "Failed to allocate memory for requests\n");
            pthread_mutex_unlock(&manager->requestMutex);
            return;
        }

        memset(newArray + manager->maxRequests, 0, (newSize - manager->maxRequests) * sizeof(Request *));
        manager->requests = newArray;
        manager->maxRequests = newSize;
    }

    Request *request = (Request *)malloc(sizeof(Request));
    if (!request) {
        fprintf(stderr, "Failed to allocate memory for request\n");
        pthread_mutex_unlock(&manager->requestMutex);
        return;
    }

    request->data = NULL; // Initialize with actual data as needed
    request->next = NULL;

    manager->requests[manager->requestCount++] = request;

    pthread_mutex_unlock(&manager->requestMutex);
}

void addInputNumber(NetworkManager *manager, int number) {
    if (manager->inputNumbers == NULL) {
        manager->inputNumbers = malloc(10 * sizeof(int));
    } else if (manager->inputCount >= manager->maxInputs) {
        size_t newSize = manager->maxInputs ? manager->maxInputs * 2 : 10;
        int *newArray = realloc(manager->inputNumbers, newSize * sizeof(int));

        if (!newArray) {
            fprintf(stderr, "Failed to allocate memory for input numbers\n");
            return;
        }

        manager->inputNumbers = newArray;
    }

    manager->inputNumbers[manager->inputCount++] = number;
}

void readInputNumbers(NetworkManager *manager) {
    int number;
    while (scanf("%d", &number) == 1 && number != -1) {
        addInputNumber(manager, number);
    }

    if (ferror(stdin)) {
        fprintf(stderr, "Error reading input\n");
    }
}

void freeNetworkManager(NetworkManager *manager) {
    for (size_t i = 0; i < manager->nodeCount; ++i)
        free(manager->nodes[i]);

    free(manager->nodes);
    pthread_mutex_destroy(&manager->nodeMutex);

    for (size_t i = 0; i < manager->requestCount; ++i)
        free(manager->requests[i]);

    free(manager->requests);
    pthread_mutex_destroy(&manager->requestMutex);

    if (manager->inputNumbers) {
        free(manager->inputNumbers);
    }

    free(manager->offsets);
    free(manager->keys);
}

int main() {
