enum { SUCCESS, ALLOCATION_FAILED };

int manage_dynamic_memory(size_t n, size_t max_memory_kb) {
    // Calculate memory requirements in kilobytes
    size_t long_size = sizeof(long);
    size_t int_size = sizeof(int);
    size_t record_size = sizeof(record);

    size_t total_memory_kb = (n * (long_size + 2 * int_size + record_size)) / KB;

    if (total_memory_kb > max_memory_kb) {
        fprintf(stderr, "Warning: Maximum memory limit exceeded. Reducing allocation.\n");

        // Reduce n to fit within the memory limit
        size_t reduced_n = (max_memory_kb * KB) / (long_size + 2 * int_size + record_size);
        total_memory_kb = (reduced_n * (long_size + 2 * int_size + record_size)) / KB;

        if (total_memory_kb > max_memory_kb) {
            fprintf(stderr, "Error: Cannot allocate memory within constraints. Exiting.\n");
            return ALLOCATION_FAILED;
        }

        n = reduced_n;
    }

    // Allocate memory for offsets
    long *offsets = malloc(n * sizeof(long));
    if (!offsets) return ALLOCATION_FAILED;

    // Allocate memory for keys
    int *keys = malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return ALLOCATION_FAILED;
    }

    // Allocate and initialize records
    record *records = calloc(n, sizeof(record));  // calloc initializes to zero
    if (!records) {
        free(offsets);
        free(keys);
        return ALLOCATION_FAILED;
    }

    srand((unsigned int)time(NULL)); // Initialize random number generator
    for (size_t i = 0; i < n; ++i) {
        records[i].value = rand() % 1000 + 1;
    }

    printf("Memory allocated successfully with reduced size: %zu\n", n);

    // Free all dynamically allocated memory
    free(offsets);
    free(keys);
    free(records);

    return SUCCESS;
}

int main() {
    const size_t max_memory_kb = 50; // Set maximum allowed memory in kilobytes
    if (manage_dynamic_memory(1000, max_memory_kb) == ALLOCATION_FAILED) {
        fprintf(stderr, "Failed to manage dynamic memory\n");
    }

    return 0;
}
