} RecordManager;

// Function prototypes
void initializeRandomRange(int min, int max);
int getRandomInRange(void);

// Initialize random number generator with a range
static void setRandomRange(int min, int max) {
    srand((unsigned int)time(NULL));
    if (min >= max) {
        fprintf(stderr, "Invalid random range.\n");
        exit(EXIT_FAILURE);
    }
}

void initializeRecords(RecordManager *manager, size_t count, int keyBase, long offsetBase, int randMin, int randMax) {
    manager->count = count;

    // Allocate memory
    manager->offsets = (long *)malloc(count * sizeof(long));
    manager->keys = (int *)malloc(count * sizeof(int));
    manager->records = (record *)malloc(count * sizeof(record));

    if (!manager->offsets || !manager->keys || !manager->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize random range
    setRandomRange(randMin, randMax);

    for (size_t i = 0; i < count; ++i) {
        manager->offsets[i] = offsetBase + i;
        manager->keys[i] = keyBase + i;
        manager->records[i].value = getRandomInRange();
    }
}

// Get a random integer in the set range
int getRandomInRange(void) {
    static int min, max; // Private fields
    return min + rand() % (max - min + 1);
}

void freeRecords(RecordManager *manager) {
    if (manager->offsets) {
        free(manager->offsets);
        manager->offsets = NULL;
    }
    if (manager->keys) {
        free(manager->keys);
        manager->keys = NULL;
    }
    if (manager->records) {
        free(manager->records);
        manager->records = NULL;
    }
}

void printRecords(const RecordManager *manager) {
