#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_HASH_SIZE 1024

typedef struct UserSession {
    int userId;
    int subscriptionId;
    char *sessionToken;
    struct UserSession *next;
} UserSession;

typedef struct HashNode {
    int key;
    UserSession *session;
    struct HashNode *next;
} HashNode;

typedef struct SessionManager {
    HashNode **hashTable;
    pthread_mutex_t lock;
    size_t hashSize;
    size_t numSessions;
} SessionManager;

UserSession* create_user_session(int userId, int subscriptionId, const char *token) {
    UserSession *session = (UserSession*)malloc(sizeof(UserSession));
    session->userId = userId;
    session->subscriptionId = subscriptionId;
    session->sessionToken = strdup(token);
    session->next = NULL;
    return session;
}

void free_user_session(UserSession *session) {
    if (session) {
        free(session->sessionToken);
        free(session);
    }
}

unsigned int hash(int userId, size_t hashSize) {
    return userId % hashSize;
}

SessionManager* initialize_manager(size_t initialHashSize) {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->hashSize = initialHashSize;
    manager->numSessions = 0;

    manager->hashTable = (HashNode**)calloc(manager->hashSize, sizeof(HashNode*));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_hash_table(SessionManager *manager) {
    size_t oldSize = manager->hashSize;
    HashNode **oldHashTable = manager->hashTable;

    manager->hashSize *= 2;
    manager->hashTable = (HashNode**)calloc(manager->hashSize, sizeof(HashNode*));

    for (size_t i = 0; i < oldSize; ++i) {
        HashNode *node = oldHashTable[i];
        while (node) {
            size_t newIndex = hash(node->key, manager->hashSize);
            HashNode *nextNode = node->next;

            node->next = manager->hashTable[newIndex];
            manager->hashTable[newIndex] = node;

            node = nextNode;
        }
    }

    free(oldHashTable);
}

void add_session(SessionManager *manager, UserSession *session) {
    pthread_mutex_lock(&manager->lock);

    if ((float)manager->numSessions / manager->hashSize > 0.7) {
        resize_hash_table(manager);
    }

    size_t index = hash(session->userId, manager->hashSize);
    HashNode *node = (HashNode*)malloc(sizeof(HashNode));
    node->key = session->userId;
    node->session = session;
    node->next = manager->hashTable[index];
    manager->hashTable[index] = node;

    manager->numSessions++;

    pthread_mutex_unlock(&manager->lock);
}

UserSession* get_session(SessionManager *manager, int userId) {
    size_t index = hash(userId, manager->hashSize);

    HashNode *node = manager->hashTable[index];
    while (node) {
        if (node->key == userId) {
            return node->session;
        }
        node = node->next;
    }

    return NULL;
}

void cleanup_sessions(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->hashSize; ++i) {
        HashNode **node = &manager->hashTable[i];
        while (*node) {
            HashNode *nextNode = (*node)->next;
            if ((*node)->session && /* condition to check session expiry */) {
                free_user_session((*node)->session);
                free(*node);
            }
            *node = nextNode;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_manager(SessionManager *manager) {
    cleanup_sessions(manager);

    for (size_t i = 0; i < manager->hashSize; ++i) {
        HashNode *node = manager->hashTable[i];
        while (node) {
            HashNode *nextNode = node->next;
            free_user_session(node->session);
            free(node);
            node = nextNode;
        }
    }

    free(manager->hashTable);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int findMax(int *arr, size_t size) {
    if (size == 0) return INT_MIN; // or handle error

    int maxVal = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > maxVal) {
            maxVal = arr[i];
        }
    }

    return maxVal;
}

void sessionManager() {
    SessionManager *manager = initialize_manager(INITIAL_HASH_SIZE);

    // Example user sessions
    UserSession *session1 = create_user_session(123, 456, "token123");
    add_session(manager, session1);

    UserSession *retrievedSession = get_session(manager, 123);
    if (retrievedSession) {
        printf("Retrieved session for userId: %d\n", retrievedSession->userId);
    }

    // Cleanup
    destroy_manager(manager);

    // Reading integers from standard input and finding the maximum
    int *intArray = NULL;
    size_t capacity = 0, size = 0;

    while (1) {
        int value;
        if (scanf("%d", &value) != 1) break; // Exit on non-integer

        if (value == -1) break; // Sentinel value to exit loop

        if (size >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            intArray = realloc(intArray, capacity * sizeof(int));
            if (!intArray) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
        }

        intArray[size++] = value;
    }

    int maxVal = findMax(intArray, size);
    printf("Largest integer: %d\n", maxVal);

    free(intArray);
}
