void manage_dynamic_allocation(long n, size_t max_memory_kb) {
    // Constants for memory sizes
    const size_t long_size = sizeof(long);
    const size_t int_size = sizeof(int);
    const size_t record_size = sizeof(record);

    // Calculate maximum allowable memory in bytes
    const size_t max_memory_bytes = max_memory_kb * 1024;

    // Track allocated pointers and their descriptions
    void* allocations[] = {NULL, NULL, NULL};
    char* allocation_descriptions[] = {"offsets", "keys", "records"};

    // Allocate offsets
    if (n > 0) {
        size_t required_memory_offsets = n * long_size;
        if (required_memory_offsets + max_memory_bytes > max_memory_bytes) {
            log_event("Memory limit exceeded for offsets, adjusting...");
            n = max_memory_kb * 1024 / long_size; // Adjust `n` to fit in memory
        }
        allocations[0] = allocate_memory(n * long_size, allocation_descriptions[0]);
    }

    // Allocate keys with fallback mechanism
    if (n > 0) {
        size_t required_memory_keys = n * int_size;
        if ((required_memory_offsets + required_memory_keys) > max_memory_bytes) {
            log_event("Memory limit exceeded for keys, adjusting...");
            n = (max_memory_kb * 1024 - required_memory_offsets) / int_size; // Adjust `n` to fit in memory
        }
        allocations[1] = allocate_memory(n * int_size, allocation_descriptions[1]);
    }

    // Allocate records with random numbers
    if (n > 0) {
        size_t required_memory_records = n * record_size;
        if ((required_memory_offsets + required_memory_keys + required_memory_records) > max_memory_bytes) {
            log_event("Memory limit exceeded for records, adjusting...");
            n = (max_memory_kb * 1024 - (required_memory_offsets + required_memory_keys)) / record_size; // Adjust `n` to fit in memory
        }
        allocations[2] = allocate_memory(n * record_size, allocation_descriptions[2]);
    }

    // Populate records with random numbers
    if (allocations[2]) {
        unsigned int seed = time(NULL);  // Initialize the seed for randomness
        record* rec_array = (record*) allocations[2];

        for (long i = 0; i < n; ++i) {
            rec_array[i].value = generate_random(1, 1000, &seed);
        }
    }

    // Monitor and log memory usage
    size_t total_memory_used = n * long_size + n * int_size + n * record_size;
    if (total_memory_used > max_memory_bytes * 0.9) { // If over 90% used
        log_event("Memory usage is close to the limit.");
    }

    // Free less frequently accessed data structures if needed
    if (total_memory_used > max_memory_bytes) {
        log_event("Total memory exceeded, freeing less critical allocations...");
        free_memory(allocations, 2);  // Example: Free offsets and keys first
        n = (max_memory_kb * 1024 - (required_memory_records)) / record_size;
        allocations[0] = allocations[1] = NULL;
    }

    // Log final memory usage
    log_event("Final memory allocation completed.");
}

// Helper functions

void* allocate_memory(size_t size, const char* desc) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate %zu bytes for %s\n", size, desc);
        return NULL;
    }
    log_event("Allocated");
    return ptr;
}

int generate_random(int min, int max, unsigned int *seed) {
    srand(*seed); // Seed the random number generator
    int rnd = rand() % (max - min + 1) + min; 
    *seed += 1;   // Update seed to avoid repeated numbers in tight loops
    return rnd;
}

void free_memory(void **ptrs, int count) {
