#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Custom data entry structure
typedef struct {
    double value;
    char identifier[2]; // 1 char + null terminator
} data_entry;

// Configuration structure for dynamic resizing and processing
typedef struct {
    size_t initial_size;
    float growth_factor;
    int rebuild_threshold;
    int (*decode_base64)(const char *, char **); // Function pointer to decode Base64
} config_t;

// Error codes
#define SUCCESS 0
#define ERROR_ALLOCATION_FAILED 1
#define ERROR_DECODE_FAILURE 2
#define ERROR_INVALID_CONNECTION -1

// Mutex for thread safety
pthread_mutex_t lock;

// Helper function prototypes
void *malloc_checked(size_t size);
int handle_error(const char *message);

// Function to manage and process data
int manageAndProcessData(config_t config, const char *encoded_data) {
    long *offsets = malloc_checked(sizeof(long) * config.initial_size);
    int *keys = malloc_checked(sizeof(int) * config.initial_size);
    data_entry *data_entries = malloc_checked(sizeof(data_entry) * config.initial_size);

    if (!offsets || !keys || !data_entries) {
        return handle_error("Memory allocation failed");
    }

    // Dynamic resizing and processing logic
    size_t current_size = config.initial_size;
    char *decoded_data = NULL;

    int decode_result = config.decode_base64(encoded_data, &decoded_data);
    if (decode_result != 0) {
        free(offsets); free(keys); free(data_entries);
        return handle_error("Base64 decoding failed");
    }

    // Simulating data processing
    for (size_t i = 0; i < current_size; ++i) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 1000;

        pthread_mutex_lock(&lock);
        data_entries[i].value = ((double)rand()) / RAND_MAX * 100.0;
        data_entries[i].identifier[0] = 'A' + (rand() % 26);
        data_entries[i].identifier[1] = '\0';
        pthread_mutex_unlock(&lock);

        if (i >= current_size - config.rebuild_threshold) {
            // Handle dynamic resizing
            size_t new_size = current_size * config.growth_factor;
            long *new_offsets = realloc_checked(offsets, sizeof(long) * new_size);
            int *new_keys = realloc_checked(keys, sizeof(int) * new_size);
            data_entry *new_data_entries = realloc_checked(data_entries, sizeof(data_entry) * new_size);

            if (!new_offsets || !new_keys || !new_data_entries) {
                free(offsets); free(keys); free(data_entries); free(decoded_data);
                return handle_error("Dynamic resizing failed");
            }

            offsets = new_offsets;
            keys = new_keys;
            data_entries = new_data_entries;
            current_size = new_size;
        }
    }

    // Validate connection and callback
    if (!decoded_data || strcmp(decoded_data, "InvalidTitle") == 0) {
        free(offsets); free(keys); free(data_entries); free(decoded_data);
        return handle_error("Invalid connection or title");
    }

    free(offsets); free(keys); free(data_entries); free(decoded_data);
    return SUCCESS;
}

// Helper function to read integers and find the largest
void readIntegersAndFindLargest() {
    int *numbers = NULL;
    size_t count = 0, capacity = 10;

    numbers = malloc_checked(sizeof(int) * capacity);

    printf("Enter integers (end with -1):\n");
    while (1) {
        if (scanf("%d", &numbers[count]) != 1) {
            handle_error("Invalid input");
        }

        if (numbers[count] == -1) break;

        pthread_mutex_lock(&lock);
        if (++count >= capacity) {
            capacity *= 2;
            int *new_numbers = realloc_checked(numbers, sizeof(int) * capacity);
            if (!new_numbers) {
                free(numbers);
                handle_error("Reallocation failed");
            }
            numbers = new_numbers;
        }
        pthread_mutex_unlock(&lock);
    }

    // Find largest integer
    int max_number = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
        if (numbers[i] > max_number) {
            max_number = numbers[i];
        }
    }

    printf("Largest number is: %d\n", max_number);
    free(numbers);
}

