Config *get_configuration(const char *file_path) {
    pthread_rwlock_rdlock(&cache_lock);
    if (cache && (time(NULL) - cache->last_updated < CACHE_EXPIRATION_TIME)) {
        Config *cached_config = malloc(sizeof(Config));
        memcpy(cached_config, &cache->config, sizeof(Config));
        pthread_rwlock_unlock(&cache_lock);
        return cached_config;
    }
    pthread_rwlock_unlock(&cache_lock);

    // Load from file or external API if necessary.
    pthread_rwlock_wrlock(&cache_lock);

