    if (result != 0) {
        free(new_config);
        if (fetch_from_external_api(new_config) != 0) {
            fprintf(stderr, "Failed to fetch configuration from API.\n");
            pthread_rwlock_unlock(&cache_lock);
            return NULL;
        }
    }

    // Update cache
    if (!cache) {
        cache = malloc(sizeof(CacheEntry));
        pthread_mutex_init(&cache->lock, NULL);
    }

    pthread_mutex_lock(&cache->lock);
    memcpy(&cache->config, new_config, sizeof(Config));
    cache->last_updated = time(NULL);
    free(new_config);

    pthread_mutex_unlock(&cache->lock);
    pthread_rwlock_unlock(&cache_lock);

    return malloc(sizeof(Config));
