#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_USERS 1000
#define RECORD_SIZE 10
#define EMAIL_LENGTH 256

typedef struct {
    char email[EMAIL_LENGTH];
    int id;
} User;

typedef struct {
    int value;
    char key[64];
    long *dynamicValue;
} Record;

typedef struct {
    User users[MAX_USERS];
    Record records[RECORD_SIZE];
    int userCount;
    int recordSize;
    pthread_mutex_t lock;
    void (*callback)(const char*);
    FILE* logFile;
} Registry;

static unsigned int seed = 42; // Seed for reproducibility

// Initialize memory pool (example with fixed size)
void initMemoryPool() {
    srand(seed);
}

// Function to normalize email using external library
int validateAndNormalizeEmail(char *email) {
    // Placeholder for email validation logic
    return 1;
}

// Add a user account
int addUser(Registry *registry, const char* username, const char* email) {
    pthread_mutex_lock(&registry->lock);

    if (registry->callback)
        registry->callback("Attempting to add user");

    // Check for unique ID and normalized email
    for (int i = 0; i < registry->userCount; ++i) {
        if (!strcmp(registry->users[i].email, email)) {
            pthread_mutex_unlock(&registry->lock);
            return -1;
        }
    }

    if (!validateAndNormalizeEmail((char *)email)) {
        pthread_mutex_unlock(&registry->lock);
        return -1;
    }

    User newUser;
    strcpy(newUser.email, email);
    newUser.id = registry->userCount + 1;

    registry->users[registry->userCount++] = newUser;

    if (registry->callback)
        registry->callback("User added successfully");

    pthread_mutex_unlock(&registry->lock);

    return 0;
}

// Update a user account
int updateUser(Registry *registry, int userId, const char* newEmail) {
    pthread_mutex_lock(&registry->lock);

    if (registry->callback)
        registry->callback("Attempting to update user");

    for (int i = 0; i < registry->userCount; ++i) {
        if (registry->users[i].id == userId) {
            if (!validateAndNormalizeEmail((char *)newEmail)) {
                pthread_mutex_unlock(&registry->lock);
                return -1;
            }

            strcpy(registry->users[i].email, newEmail);

            if (registry->callback)
                registry->callback("User updated successfully");

            break;
        }
    }

    pthread_mutex_unlock(&registry->lock);

    return 0;
}

// Delete a user account
int deleteUser(Registry *registry, int userId) {
    pthread_mutex_lock(&registry->lock);

    if (registry->callback)
        registry->callback("Attempting to delete user");

    for (int i = 0; i < registry->userCount; ++i) {
        if (registry->users[i].id == userId) {
            memmove(&registry->users[i], &registry->users[i + 1],
                    sizeof(User) * (--registry->userCount - i));

            if (registry->callback)
                registry->callback("User deleted successfully");

            break;
        }
    }

    pthread_mutex_unlock(&registry->lock);

    return 0;
}

// Add a record
int addRecord(Registry *registry, int userId) {
    pthread_mutex_lock(&registry->lock);

    if (registry->recordSize >= RECORD_SIZE)
        return -1;

    Record newRecord;
    newRecord.value = rand() % 100; // Random value in range [0, 99]
    snprintf(newRecord.key, sizeof(newRecord.key), "Key_%d", registry->recordSize);
    newRecord.dynamicValue = malloc(sizeof(long));

    if (!newRecord.dynamicValue) {
        pthread_mutex_unlock(&registry->lock);
        return -1;
    }

    *newRecord.dynamicValue = rand() % 1000; // Random long value in range [0, 999]

    registry->records[registry->recordSize++] = newRecord;

    if (registry->callback)
        registry->callback("Record added successfully");

    pthread_mutex_unlock(&registry->lock);

    return 0;
}

// Delete a record
int deleteRecord(Registry *registry, int recordIndex) {
    pthread_mutex_lock(&registry->lock);

    if (recordIndex >= registry->recordSize)
        return -1;

    free(registry->records[recordIndex].dynamicValue);

    memmove(&registry->records[recordIndex], &registry->records[recordIndex + 1],
            sizeof(Record) * (--registry->recordSize - recordIndex));

    if (registry->callback)
        registry->callback("Record deleted successfully");

    pthread_mutex_unlock(&registry->lock);

    return 0;
}

// Logging mechanism
void logMessage(const char* message, Registry* registry) {
    if (!registry || !registry->logFile)
        return;

    fprintf(registry->logFile, "%s\n", message);
    fflush(registry->logFile);
}

// Initialize the registry system
Registry* initRegistry(void (*callback)(const char*)) {
    Registry *registry = malloc(sizeof(Registry));
    if (!registry) return NULL;

    memset(registry->users, 0, sizeof(User) * MAX_USERS);
    memset(registry->records, 0, sizeof(Record) * RECORD_SIZE);

    registry->userCount = 0;
    registry->recordSize = 0;

    pthread_mutex_init(&registry->lock, NULL);
    initMemoryPool();

    registry->callback = callback;
    registry->logFile = fopen("registry.log", "a");

    return registry;
}

// Cleanup resources
void freeRegistry(Registry *registry) {
    if (!registry) return;

    for (int i = 0; i < registry->recordSize; ++i)
        free(registry->records[i].dynamicValue);

    fclose(registry->logFile);
    pthread_mutex_destroy(&registry->lock);

    free(registry);
}

// Example callback function
void exampleCallback(const char* message) {
    printf("Callback: %s\n", message);
}

int main() {
    Registry *registry = initRegistry(exampleCallback);

    if (!registry)
        return -1;

    // Example usage:
    addUser(registry, "user1@example.com");
    addRecord(registry, 1);

    deleteUser(registry, 1);
    deleteRecord(registry, 0);

    freeRegistry(registry);

    return 0;
}
