    memory_pool mp;
    init_memory_pool(&mp, sizeof(record), record_count);

    if (!mp.pool) {
        perror("Failed to initialize memory pool");
        free(offset);
        free(key);
        return;
    }

    pthread_mutex_lock(&mutex);

    // Allocate and initialize records array with random values
    record* records = (record*)malloc(record_count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&mutex);
        free_memory_pool(&mp.pool);
        free(offset);
        free(key);
        return;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = custom_random(min_range, max_range);
    }

