        int num;
        if (scanf("%d", &num) != 1)
            break; // End of input

        if (num == sentinel)
            break;

        pthread_mutex_lock(&mutex);

        size_t new_size = input_size + 1;
        int* temp = realloc(inputs, new_size * sizeof(int));
        if (!temp && input_size < MAX_RETRIES) {
            perror("Failed to reallocate memory for inputs");
            pthread_mutex_unlock(&mutex);
            free_memory_pool(&mp.pool);
            free(records);
            free(offset);
            free(key);
            return;
        }

        inputs = temp;
        if (inputs)
            inputs[input_size++] = num;

        pthread_mutex_unlock(&mutex);
    }

    // Find and print the largest integer
    int max_value = -1 * INT_MAX;
    for (size_t i = 0; i < input_size; ++i) {
        if (inputs[i] > max_value)
            max_value = inputs[i];
    }

    printf("The largest integer is: %d\n", max_value);

    // Cleanup
    free(inputs);
    free(records);
    free_memory_pool(&mp.pool);
    free(offset);
    free(key);
}

int main() {
    processRecordsAndFindMax(10, 5, 20, 0, 100, NULL);
    return 0;
}
```

