Message* read_messages(size_t* count) {
    char buffer[256];
    *count = 0;
    Message** messages = NULL;

    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (buffer[0] == '\n') break;  // Sentinel value

        size_t length = strlen(buffer);
        if (length > 0 && buffer[length - 1] == '\n') {
            buffer[--length] = '\0';  // Remove newline character
        }

        *count += 1;
        messages = realloc(messages, *count * sizeof(Message*));
        if (!messages) {
            perror("Memory reallocation failed");
            exit(EXIT_FAILURE);
        }

        Message* message = (Message*)malloc(sizeof(Message));
        if (!message) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        message->message = strdup(buffer);
        message->severity_level = secure_random(1, 10);  // Example severity range
        message->timestamp = time(NULL);

        messages[*count - 1] = message;
    }

    return messages;
}

