    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        process_message(input_messages[i], NULL); // No callback provided
        pthread_mutex_unlock(&lock);
    }

    find_max_severity(input_messages, count);

    free_resources(messages, initial_size);
    free_resources((Message**)input_messages, count);

    pthread_mutex_destroy(&lock);
}

int main() {
