        exit(EXIT_FAILURE);
    }

    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    int extraSamplesCount = 0;

    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    const char* sampleFormatNames[] = {"undefined", "unsigned integer", "signed integer", "IEEE floating point"};
    uint16 sampleFormat;
    if (TIFFGetFieldDefaulted(tiff, TIFFTAG_SAMPLEFORMAT, &sampleFormat)) {
        fprintf(stderr, "Error getting sample format.\n");
        TIFFClose(tiff);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    unsigned char extraSamplesInfo[256];
    extraSamplesCount = 0;
    if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamplesInfo)) {
        while (extraSamplesInfo[extraSamplesCount] != 0) {
            extraSamplesCount++;
        }
    }

    ImageData imageDetails = {bitsPerSample, samplesPerPixel, extraSamplesCount};
    imageDetails.extraSamplesInfo = malloc(extraSamplesCount * sizeof(unsigned char));
    if (!imageDetails.extraSamplesInfo) {
        TIFFClose(tiff);
        fclose(file);
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    memcpy(imageDetails.extraSamplesInfo, extraSamplesInfo, extraSamplesCount);

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)stringToHash, strlen(stringToHash), hash);

    ProcessedData processedData = {imageDetails, *hash};

    TIFFClose(tiff);
    fclose(file);

    return processedData;
}
