#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <pthread.h>

// Define a structure for point
typedef struct {
    float x;
    float y;
} Point;

// Dynamic array structure with automatic resizing
typedef struct {
    void *data;
    size_t element_size;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} DynamicArray;

// Function to create a dynamic array
DynamicArray* create_dynamic_array(size_t initial_capacity, size_t element_size) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->data = malloc(initial_capacity * element_size);
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->element_size = element_size;
    arr->capacity = initial_capacity;
    arr->length = 0;
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

// Function to resize the dynamic array
int resize_dynamic_array(DynamicArray* arr, size_t new_capacity) {
    void *new_data = realloc(arr->data, new_capacity * arr->element_size);
    if (!new_data) return -1;

    arr->data = new_data;
    arr->capacity = new_capacity;
    return 0;
}

// Function to add an element to the dynamic array
int add_to_dynamic_array(DynamicArray* arr, void* element) {
    pthread_mutex_lock(&arr->lock);

    if (arr->length == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        int result = resize_dynamic_array(arr, new_capacity);
        if (result != 0) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation failed
        }
    }

    memcpy((char*)arr->data + (arr->length * arr->element_size), element, arr->element_size);
    arr->length++;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Function to calculate the distance between two points
float calculate_distance(Point* p1, Point* p2) {
    float dx = p1->x - p2->x;
    float dy = p1->y - p2->y;
    return sqrtf(dx * dx + dy * dy);
}

// Function to calculate distances for all pairs of points
void calculate_all_distances(DynamicArray* points, DynamicArray* distances) {
    pthread_mutex_lock(&distances->lock);

    for (size_t i = 0; i < points->length; ++i) {
        Point* p1 = (Point*)((char*)points->data + i * points->element_size);

        for (size_t j = i + 1; j < points->length; ++j) {
            if (distances->length == distances->capacity) {
                size_t new_capacity = distances->capacity * 2;
                int result = resize_dynamic_array(distances, new_capacity);
                if (result != 0) {
                    pthread_mutex_unlock(&distances->lock);
                    return; // Memory allocation failed
                }
            }

            Point* p2 = (Point*)((char*)points->data + j * points->element_size);
            float distance = calculate_distance(p1, p2);

            add_to_dynamic_array(distances, &distance); // Store as double
        }
    }

    pthread_mutex_unlock(&distances->lock);
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    if (arr) {
        if (arr->data) free(arr->data);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

// Example usage of API
int main() {
    DynamicArray *points = create_dynamic_array(10, sizeof(Point));
    if (!points) return -1; // Handle allocation error

    DynamicArray *distances = create_dynamic_array(10, sizeof(double));
    if (!distances) {
        free_dynamic_array(points);
        return -1; // Handle allocation error
    }

    Point new_point = { .x = 1.0f, .y = 2.0f };
    add_to_dynamic_array(points, &new_point);

    calculate_all_distances(points, distances);

    for (size_t i = 0; i < distances->length; ++i) {
        double distance = ((double*)distances->data)[i];
        printf("Distance: %f\n", distance);
    }

    free_dynamic_array(points);
    free_dynamic_array(distances);

    return 0;
}
```

### Key Features:

1. **Dynamic Array Management**: Implemented `DynamicArray` to manage automatic resizing of arrays, handling growth efficiently.
2. **Concurrency**: Utilized mutexes (`pthread_mutex_t`) for thread-safe operations on dynamic arrays.
3. **Memory Allocation Error Handling**: Included checks and graceful exits when memory allocation fails.
4. **Performance Optimization**: Used efficient algorithms for distance calculation and array operations.
5. **API Usability**: Provided functions to add points, calculate distances, and manage resources.

This code serves as a foundation that can be extended with additional features like integration with external libraries or distributed systems for scalability.']

