    char ipAddress[16];
    char filePath[256];
    time_t timestamp;
    int cacheHit;
    struct Request* next;
} request;

// Define directory structure
typedef struct Directory {
    char name[256];
    time_t lastModified;
    int permissions;
    struct Directory* left;
    struct Directory* right;
} directory;

// Hash table entry for file metadata
typedef struct HashTableEntry {
    char filePath[256];
    fileMeta metadata;
    struct HashTableEntry* next;
} hashTableEntry;

// Function prototypes
void manageFileAccessAndCache(void (*callback)(fileMeta*, request*));
void resizeFileMetaArray(fileMeta** array, size_t* currentSize);
hashTableEntry* createHashTable(size_t initialCapacity);
void addFileMetadata(hashTableEntry* table, const char* filePath, fileMeta metadata);
request* processRequest(const char* line);
void freeResources(fileMeta* fileMetaArray, hashTableEntry* hashTable, request* requests, directory* directories);

// Global variables for synchronization
sem_t resourceSemaphore;
pthread_mutex_t mutex;

int main() {
    manageFileAccessAndCache(NULL); // Example usage with no callback
    return 0;
}

void manageFileAccessAndCache(void (*callback)(fileMeta*, request*)) {
    sem_init(&resourceSemaphore, 0, 1);
    pthread_mutex_init(&mutex, NULL);

    size_t fileMetaSize = 10; // Initial size for fileMeta array
    fileMeta* fileMetaArray = malloc(fileMetaSize * sizeof(fileMeta));
    if (!fileMetaArray) {
        fprintf(stderr, "Memory allocation failed for fileMeta array\n");
        return;
    }

    // Initialize fileMeta array with dummy data
    for (size_t i = 0; i < fileMetaSize; ++i) {
        fileMetaArray[i].fileSize = rand() % 1000 + 1;
        fileMetaArray[i].lastModified = time(NULL) - (rand() % 10000);
        fileMetaArray[i].refCount = 0;
    }

    size_t hashTableCapacity = 20; // Initial capacity for hash table
    hashTableEntry* hashTable = createHashTable(hashTableCapacity);

    // Populate hash table with file metadata
    for (size_t i = 0; i < fileMetaSize; ++i) {
        char filePath[256];
        snprintf(filePath, sizeof(filePath), "/file%d", i);
        addFileMetadata(hashTable, filePath, fileMetaArray[i]);
    }

    request* headRequest = NULL;
    char line[512];

    // Process incoming requests
    while (fgets(line, sizeof(line), stdin)) {
        if (strcmp(line, "END\n") == 0) break;

        sem_wait(&resourceSemaphore);
        pthread_mutex_lock(&mutex);

        request* newRequest = processRequest(line);
        if (newRequest) {
            newRequest->next = headRequest;
            headRequest = newRequest;
        }

        pthread_mutex_unlock(&mutex);
        sem_post(&resourceSemaphore);

        if (callback) {
            callback(fileMetaArray, headRequest);
        }
    }

    // Free resources
    freeResources(fileMetaArray, hashTable, headRequest, NULL);

    sem_destroy(&resourceSemaphore);
    pthread_mutex_destroy(&mutex);
}

void resizeFileMetaArray(fileMeta** array, size_t* currentSize) {
    size_t newSize = *currentSize * 2;
    fileMeta* newArray = realloc(*array, newSize * sizeof(fileMeta));
    if (newArray) {
        for (size_t i = *currentSize; i < newSize; ++i) {
            newArray[i].fileSize = rand() % 1000 + 1;
            newArray[i].lastModified = time(NULL) - (rand() % 10000);
            newArray[i].refCount = 0;
        }
        *array = newArray;
        *currentSize = newSize;
    } else {
        fprintf(stderr, "Memory allocation failed during resize\n");
    }
}

hashTableEntry* createHashTable(size_t initialCapacity) {
    hashTableEntry* table = calloc(initialCapacity, sizeof(hashTableEntry));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }
    return table;
}

void addFileMetadata(hashTableEntry* table, const char* filePath, fileMeta metadata) {
    size_t index = strlen(filePath) % 20; // Simple hash function
    hashTableEntry* entry = &table[index];
    while (entry->next) {
        if (strcmp(entry->filePath, filePath) == 0) return;
        entry = entry->next;
    }
    strcpy(entry->filePath, filePath);
    entry->metadata = metadata;
    entry->next = malloc(sizeof(hashTableEntry));
    entry->next->next = NULL;
}

request* processRequest(const char* line) {
    request* req = malloc(sizeof(request));
    if (!req) return NULL;

    if (sscanf(line, "%15[^ ] %255s", req->ipAddress, req->filePath) != 2) {
        free(req);
        return NULL;
    }

    req->timestamp = time(NULL);
    req->cacheHit = rand() % 2; // Random cache hit/miss for simulation
    req->next = NULL;

    return req;
}

void freeResources(fileMeta* fileMetaArray, hashTableEntry* hashTable, request* requests, directory* directories) {
    if (fileMetaArray) free(fileMetaArray);

    for (size_t i = 0; i < 20; ++i) { // Assuming fixed size for simplicity
        hashTableEntry* entry = &hashTable[i];
        while (entry) {
            hashTableEntry* toFree = entry;
            entry = entry->next;
            free(toFree);
        }
    }
    if (hashTable) free(hashTable);

    while (requests) {
        request* toFree = requests;
        requests = requests->next;
        free(toFree);
    }

    // Free directories if implemented
}
