// Initialize hash table
HashTable* init_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->size = size;
    table->table = calloc(size, sizeof(Node *));
    if (!table->table) {
        free(table);
        perror("Failed to allocate memory for hash table buckets");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Insert resource into hash table
int insert_resource(HashTable *table, int resource_id, Resource *resource) {
    unsigned int index = hash_function(resource_id, table->size);

    pthread_mutex_lock(&table->lock);
    Node *node = create_node(resource_id, resource);
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Error
    }

    node->next = table->table[index];
    table->table[index] = node;

    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}

// Iterate and print resources
void iterate_and_print_resources(const HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node *node = table->table[i];
        while (node) {
            printf("Resource ID: %d, Pool Size: %zu, Timeout: %d ms\n",
                   node->data->resource_id,
                   node->data->pool_size,
                   node->data->timeout_ms);
            // Adjust pool size based on network conditions
            adjust_pool_size(node->data);

            node = node->next;
        }
    }
}

// Free all resources
void free_resources(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node *node = table->table[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            free(temp->data);
            free(temp);
        }
    }
    free(table->table);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Main function
