    size_t max_resources = 10; // Example: maximum number of resources
    HashTable *resource_table = init_hash_table(max_resources);

    // Define some resource configurations
    Resource http_resource = {1, 100, 3000, NULL};
    Resource websocket_resource = {2, 50, 5000, NULL};

    if (insert_resource(resource_table, http_resource.resource_id, &http_resource) != 0 ||
