// Define the job structure
typedef struct Job {
    time_t timestamp;
    int id;
    char *description;
    void (*callback)(struct Job *);
    int priority;

    struct Job *prev, *next;
} Job;

// Node for custom allocator's free list management
typedef struct AllocatorNode {
    size_t size;
    struct AllocatorNode *next;
} AllocatorNode;

AllocatorNode *freeList = NULL;
pthread_mutex_t allocatorMutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initializeJobs();
Job* createJob(int id, const char *description, void (*callback)(Job *), int priority);
void insertJob(Job **head, Job *newJob);
void printJobs(Job *head);
void freeAllJobs(Job *head);
AllocatorNode* allocateMemory(size_t size);
void freeMemory(void *ptr);

// Example callback function
void exampleCallback(Job *job) {
    printf("Processing job ID: %d\n", job->id);
}

int main() {
    initializeJobs();

    // Additional application logic...

    return 0;
}

void initializeJobs() {
    Job *head = NULL;

    // Populate with predefined jobs
    insertJob(&head, createJob(1, "Job 1 description", exampleCallback, 5));
    insertJob(&head, createJob(2, "Job 2 description", exampleCallback, 3));
    insertJob(&head, createJob(3, "Job 3 description", exampleCallback, 10));

    // Print jobs
    printJobs(head);

    // Free all jobs and resources
    freeAllJobs(head);
}

Job* createJob(int id, const char *description, void (*callback)(Job *), int priority) {
    Job *job = (Job*)allocateMemory(sizeof(Job));
    if (!job) return NULL;

    job->id = id;
    job->timestamp = time(NULL) + 60; // Example timestamp
    job->description = strdup(description);
    job->callback = callback;
    job->priority = priority;
    job->prev = job->next = NULL;

    return job;
}

void insertJob(Job **head, Job *newJob) {
    if (!*head) {
        *head = newJob;
        return;
    }

    // Insert based on priority (higher priority first)
    for (Job *current = *head; current != NULL; current = current->next) {
        if (newJob->priority > current->priority) {
            newJob->next = current;
            newJob->prev = current->prev;

            if (current->prev) current->prev->next = newJob;
            else *head = newJob;

            current->prev = newJob;
            return;
        }
    }

    // Append at the end if no higher priority found
    Job *last = *head;
    while (last->next) last = last->next;
    last->next = newJob;
    newJob->prev = last;
}

void printJobs(Job *head) {
    for (Job *current = head; current != NULL; current = current->next) {
        printf("Job ID: %d, Description: %s, Scheduled Time: %ld, Priority: %d\n",
               current->id, current->description, current->timestamp, current->priority);
    }
}

void freeAllJobs(Job *head) {
    while (head) {
        Job *next = head->next;
        free(head->description);
        freeMemory(head);
        head = next;
    }
}

AllocatorNode* allocateMemory(size_t size) {
    pthread_mutex_lock(&allocatorMutex);

    AllocatorNode **current = &freeList;
    while (*current) {
        if ((*current)->size >= size) {
            AllocatorNode *node = *current;
            *current = node->next;
            pthread_mutex_unlock(&allocatorMutex);
            return (void*)node;
        }
        current = &(*current)->next;
    }

    void *ptr = malloc(size + sizeof(AllocatorNode));
    if (!ptr) {
        pthread_mutex_unlock(&allocatorMutex);
        return NULL;
    }

    pthread_mutex_unlock(&allocatorMutex);

    ((AllocatorNode *)ptr)->size = size;
    ((AllocatorNode *)ptr)->next = NULL;

    return ptr;
}

void freeMemory(void *ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&allocatorMutex);

    AllocatorNode *node = (AllocatorNode*)ptr;
    node->next = freeList;
    freeList = node;

    pthread_mutex_unlock(&allocatorMutex);
}
