    records[record_count].value = value;
    strncpy(records[record_count].key, key, MAX_KEY_LENGTH - 1);
    records[record_count].dynamic_long_ptr = malloc(sizeof(long));
    if (!records[record_count].dynamic_long_ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    *records[record_count].dynamic_long_ptr = (long)value; // Example initialization

    if (value > max_value) {
        max_value = value;
    }

    record_count++;

    pthread_mutex_unlock(&lock);
}

