    int tid = *(int *)arg;
    printf("Thread %d processing...\n", tid);

    pthread_mutex_lock(&lock);

    if (record_count > 0) {
        record_callback(process_callback)(records[record_count - 1]);
    }

    pthread_mutex_unlock(&lock);

    sem_post(&semaphore);  // Signal semaphore when done

    return NULL;
}

