    int maxValue = findMax(inputArray, inputCount);
    printf("Maximum integer: %d\n", maxValue);

    sem_t semaphore;
    loadConfigAndInitializeSemaphore(&semaphore, semaphoreInitialValue);

    pthread_t threads[MAX_THREADS];
    for (unsigned int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, manageSharedResource, &semaphore)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (unsigned int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);

    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i].dynamicLongPtr);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    processRecordsAndFindMax(42, 10);
    return 0;
}
```

### Key Aspects:
- **Memory Allocation**: Allocates and initializes arrays for offsets, keys, and records. Handles memory allocation failures.
