typedef struct {
    int value;
    char *key;
    long *ptr;
} Record;

typedef void (*Callback)(Record *);

typedef struct {
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    unsigned seed; // For random number generation
    Callback customProcessing;
    size_t allocations;
    size_t totalMemoryUsage;
} RecordManager;

// Thread-safe RNG function
int secure_random(int min, int max, unsigned *seed) {
    *seed ^= (*seed << 21);
    *seed ^= *seed >> 35;
    *seed ^= *seed << 4;
    return min + ((*seed % (max - min + 1)) & RAND_MAX);
}

// Helper function to find the maximum value
int findMax(int *arr, size_t size) {
    if (!size) return INT_MIN; // Edge case: empty array

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Initialize the record manager
void initRecordManager(RecordManager *manager, size_t initialCapacity, unsigned seed,
                       int minValue, int maxValue, Callback callback) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->records = malloc(initialCapacity * sizeof(Record *));
    if (!manager->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initialCapacity;
    manager->size = 0;
    manager->seed = seed;
    manager->customProcessing = callback;

    // Allocate and initialize records
    for (size_t i = 0; i < initialCapacity; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->records[i] = record;
        record->value = secure_random(minValue, maxValue, &manager->seed);
        record->key = strdup("default_key"); // Example key
        record->ptr = malloc(sizeof(long));
        if (!record->ptr) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        *(record->ptr) = 0; // Initialize pointer value

        manager->allocations++;
        manager->totalMemoryUsage += sizeof(Record *) + sizeof(Record) + strlen(record->key) + 1 + sizeof(long);

        if (manager->customProcessing) {
            manager->customProcessing(record);
        }

        ++manager->size;
    }
}

// Callback example
void customProcess(Record *record) {
    // Custom processing logic for each record
    *(record->ptr) = record->value; // Example operation
}

// Function to add a new record dynamically
void addRecord(RecordManager *manager, int value, const char *key, long lValue) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        Record **newRecords = realloc(manager->records, newCapacity * sizeof(Record *));
        if (!newRecords) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memset(newRecords + manager->capacity, 0, (newCapacity - manager->capacity) * sizeof(Record *));
        manager->records = newRecords;
        manager->capacity = newCapacity;

        manager->allocations++;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    record->key = strdup(key);
    record->ptr = malloc(sizeof(long));
    *(record->ptr) = lValue;

    manager->records[manager->size++] = record;
    manager->allocations++;
    manager->totalMemoryUsage += sizeof(Record *) + sizeof(Record) + strlen(record->key) + 1 + sizeof(long);

    if (manager->customProcessing) {
        manager->customProcessing(record);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to free all memory
void freeAllRecords(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        Record *record = manager->records[i];
        if (record) {
            free(record->key);
            free(record->ptr);
            free(record);
            manager->allocations--;
            manager->totalMemoryUsage -= sizeof(Record *) + sizeof(Record) + strlen(record->key) + 1 + sizeof(long);
        }
    }

    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
}

// Function to process records and find max value in dynamic array
void processRecordsAndFindMax(size_t initialCapacity, unsigned seed,
                              int minValue, int maxValue) {

    RecordManager manager;
    initRecordManager(&manager, initialCapacity, seed, minValue, maxValue, customProcess);

    printf("Enter integers (enter -1 to stop):\n");
    int input = 0;
    while (input != -1) {
        scanf("%d", &input);
        if (input == -1) break;

        addRecord(&manager, input, "dynamic_key", input * 2); // Example long value
    }

    // Find max in dynamic array (assuming values are stored sequentially)
    int maxVal = INT_MIN;
    for (size_t i = 0; i < manager.size; ++i) {
        Record *record = manager.records[i];
        if (record->value > maxVal) {
            maxVal = record->value;
        }
    }

    printf("Maximum value: %d\n", maxVal);

    // Free allocated memory
    freeAllRecords(&manager);

    // Print allocations and total memory usage for debugging
    printf("Total allocations: %zu, Total Memory Usage: %zu bytes\n",
           manager.allocations, manager.totalMemoryUsage);
}

int main() {
    processRecordsAndFindMax(10, time(NULL), 1, 100); // Example parameters
    return 0;
}
