        new_records[i] = NULL;
    }

    manager->records = new_records;
    manager->capacity = new_capacity;

    if (manager->logging_enabled) {
        printf("Resized records to capacity %zu\n", new_capacity);
    }

    return 0;
}

void log_memory_usage(RecordManager *manager) {
    size_t used_memory = sizeof(RecordManager) +
                         manager->count * sizeof(Record *) +
                         manager->allocation_count * (sizeof(Record) + sizeof(char*) + sizeof(long*));

    if (manager->logging_enabled) {
        printf("Memory Usage: %zu bytes\n", used_memory);
    }
}

void process_record_callback(RecordManager *manager, RecordCallback callback) {
    for (size_t i = 0; i < manager->count; ++i) {
        pthread_mutex_lock(&manager->lock);
        if (callback && manager->records[i]) {
            callback(manager->records[i]);
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

void processRecordsAndFindMax(size_t initial_capacity, unsigned long seed, int logging_enabled) {
    RecordManager manager;
    pthread_mutex_init(&manager.lock, NULL);
    initialize_random(seed);

    manager.records = malloc(initial_capacity * sizeof(Record *));
    if (!manager.records) return;

    manager.capacity = initial_capacity;
    manager.count = 0;
    manager.allocation_count = 0;
    manager.total_memory_usage = sizeof(RecordManager) + initial_capacity * sizeof(Record *);
    manager.logging_enabled = logging_enabled;

    for (size_t i = 0; i < initial_capacity; ++i) {
        char key[16];
        snprintf(key, sizeof(key), "key_%zu", i);

        Record *record = create_record(key, seed);
        if (!record) return;

        pthread_mutex_lock(&manager.lock);
        manager.records[i] = record;
        ++manager.count;
        ++manager.allocation_count;
        manager.total_memory_usage += sizeof(Record) + strlen(record->key) + 1 + sizeof(long*);
        log_memory_usage(&manager);
        pthread_mutex_unlock(&manager.lock);

        if (manager.capacity <= manager.count) {
            if (resize_records(&manager)) break;
        }
    }

    // Example callback processing
    process_record_callback(&manager, NULL);

    int number;
    while (scanf("%d", &number), number != -1) {
        pthread_mutex_lock(&manager.lock);

        if (manager.capacity <= manager.count) {
            if (resize_records(&manager)) break;
        }

        char key[16];
        snprintf(key, sizeof(key), "key_%zu", manager.count);

        Record *record = create_record(key, seed);
        if (!record) break;

        record->value = number;
        manager.records[manager.count] = record;
        ++manager.count;
        ++manager.allocation_count;
        manager.total_memory_usage += sizeof(Record) + strlen(record->key) + 1 + sizeof(long*);
        log_memory_usage(&manager);

        pthread_mutex_unlock(&manager.lock);
    }

    // Free records
    for (size_t i = 0; i < manager.count; ++i) {
        free_record(manager.records[i]);
    }
    free(manager.records);

    pthread_mutex_destroy(&manager.lock);
}
