typedef enum { STRING, INTEGER, BOOLEAN } ValueType;

typedef struct {
    char name[256];
    ValueType value_type;
    void* default_value;
    void* current_value;
    char translations[3][256]; // e.g., en, es, fr
} Preference;

typedef struct {
    int integer_value;
    char key[256];
    long long_value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    Preference* preferences;
} PreferencesArray;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    Record* records;
} RecordsArray;

void resize_array(void **array, size_t *capacity, size_t *count, size_t element_size) {
    if (*count >= *capacity) {
        *capacity *= 2;
        void* new_array = realloc(*array, *capacity * element_size);
        if (!new_array) {
            perror("Failed to resize array");
            exit(EXIT_FAILURE);
        }
        *array = new_array;
    }
}

PreferencesArray init_preferences(size_t initial_capacity, size_t min_prefs, size_t max_prefs) {
    PreferencesArray pa = {initial_capacity, 0, PTHREAD_MUTEX_INITIALIZER, NULL};
    if (initial_capacity < min_prefs || initial_capacity > max_prefs) {
        fprintf(stderr, "Invalid initial capacity for preferences\n");
        exit(EXIT_FAILURE);
    }
    resize_array((void**)&pa.preferences, &pa.capacity, &pa.count, sizeof(Preference));
    return pa;
}

RecordsArray init_records(size_t initial_capacity) {
    RecordsArray ra = {initial_capacity, 0, PTHREAD_MUTEX_INITIALIZER, NULL};
    resize_array((void**)&ra.records, &ra.capacity, &ra.count, sizeof(Record));
    return ra;
}

bool add_preference(PreferencesArray *pa, Preference pref) {
    pthread_mutex_lock(&pa->lock);
    if (pa->count >= pa->capacity) {
        resize_array((void**)&pa->preferences, &pa->capacity, &pa->count, sizeof(Preference));
    }
    memcpy(&pa->preferences[pa->count++], &pref, sizeof(Preference));
    pthread_mutex_unlock(&pa->lock);
    return true;
}

bool add_record(RecordsArray *ra, Record rec) {
    pthread_mutex_lock(&ra->lock);
    for (size_t i = 0; i < ra->count; ++i) {
        if (ra->records[i].integer_value == rec.integer_value) {
            pthread_mutex_unlock(&ra->lock);
            return false;
        }
    }
    if (ra->count >= ra->capacity) {
        resize_array((void**)&ra->records, &ra->capacity, &ra->count, sizeof(Record));
    }
    memcpy(&ra->records[ra->count++], &rec, sizeof(Record));
    pthread_mutex_unlock(&ra->lock);
    return true;
}

void managePreferencesAndFindMax(size_t min_prefs, size_t max_prefs) {
    PreferencesArray preferences = init_preferences(10, min_prefs, max_prefs);
    RecordsArray records = init_records(10);

    char input[256];
    while (true) {
        printf("Enter preference (name, value type, default_value) or 'exit': ");
        if (!fgets(input, sizeof(input), stdin)) break;
        if (strncmp(input, "exit", 4) == 0) break;

        Preference pref = {0};
        if (sscanf(input, "%255[^,], %d, %[^\n]", pref.name, &pref.value_type, pref.default_value) < 3) {
            fprintf(stderr, "Invalid preference format\n");
            continue;
        }

        add_preference(&preferences, pref);
    }

    srand(time(NULL));
    for (size_t i = 0; i < 100; ++i) { // Add records with unique integer values
        Record rec = {rand() % 1000 + 1, "", rand()};
        if (!add_record(&records, rec)) {
            fprintf(stderr, "Duplicate record value\n");
        }
    }

    printf("Preferences and Records initialized.\n");

    pthread_mutex_destroy(&preferences.lock);
    pthread_mutex_destroy(&records.lock);

    free(preferences.preferences);
    free(records.records);
}
