#define MAX_SENSOR_TYPES 10

typedef struct {
    float value;
    char type;
    uint32_t index;
} sensor_record;

void free_sensor_records(sensor_record **records, size_t count) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}

sensor_record* create_sensor_records(size_t num_records, float min_val, float max_val,
                                     char type_mapping[], pthread_mutex_t *mutex) {
    sensor_record *records = malloc(num_records * sizeof(sensor_record));
    if (!records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(mutex);

        records[i].index = (uint32_t)i;
        records[i].value = min_val + ((float)rand() / RAND_MAX) * (max_val - min_val);

        // Assuming type_mapping is an array of char where each char represents a sensor type
        records[i].type = type_mapping[i % MAX_SENSOR_TYPES];

        pthread_mutex_unlock(mutex);
    }

    return records;
}

int main() {
    const size_t num_records = 1000;
    float min_val = -50.0f, max_val = 150.0f;
    char type_mapping[MAX_SENSOR_TYPES] = {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'};

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    sensor_record *records = create_sensor_records(num_records, min_val, max_val, type_mapping, &mutex);
    if (records) {
        // Use records
        free_sensor_records(&records, num_records);
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
