// Define the custom Entry structure
typedef struct {
    char *key;
    size_t value;
} Entry;

// Function to generate a random number within a given range [min, max]
size_t random_in_range(size_t min, size_t max) {
    return rand() % (max - min + 1) + min;
}

// Implement the allocate_entries function
Entry* allocate_entries(const char **keys, const int *value_ranges, size_t num_keys) {
    if (!keys || !value_ranges || num_keys == 0) {
        return NULL; // Handle null pointers and zero input size gracefully
    }

    Entry *entries = malloc(num_keys * sizeof(Entry));
    if (!entries) {
        return NULL; // Handle memory allocation failure
    }

    for (size_t i = 0; i < num_keys; ++i) {
        entries[i].key = strdup(keys[i]);
        if (!entries[i].key) {
            // Clean up allocated memory in case of failure
            for (size_t j = 0; j < i; ++j) {
                free(entries[j].key);
            }
            free(entries);
            return NULL;
        }

        int range[2] = {value_ranges[2 * i], value_ranges[2 * i + 1]};
        if (range[0] > range[1]) {
            // Handle invalid range
            for (size_t j = 0; j <= i; ++j) {
                free(entries[j].key);
            }
            free(entries);
            return NULL;
        }

        entries[i].value = random_in_range(range[0], range[1]);
    }

    return entries;
}

// Example usage of the function
int main() {
    srand(time(NULL)); // Seed the random number generator

    const char *keys[] = {"key1", "key2", "key3"};
    int value_ranges[] = {10, 20, 30, 40, 50, 60}; // Min and max for each key
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    Entry *entries = allocate_entries(keys, value_ranges, num_keys);

    if (entries) {
        for (size_t i = 0; i < num_keys; ++i) {
            printf("Key: %s, Value: %zu\n", entries[i].key, entries[i].value);
            free(entries[i].key); // Free each key string
        }
        free(entries); // Free the array of entries
    } else {
        fprintf(stderr, "Memory allocation failed or invalid input.\n");
    }

    return 0;
}
