#define MAX_MESSAGES 1000
#define DEFAULT_MESSAGE "Default Message"

typedef struct {
    char *content;
} Message;

typedef struct {
    pthread_mutex_t mutex;
    int count;
    int capacity;
    long *timestamps;
    int *priorities;
    Message *messages;
    long *offsets;
    int *keys;
} MessageQueue;

MessageQueue* initMessageQueue(int seed, void (*initCallback)(void*)) {
    MessageQueue *queue = malloc(sizeof(MessageQueue));
    if (!queue) return NULL;

    pthread_mutex_init(&queue->mutex, NULL);
    queue->count = 0;
    queue->capacity = MAX_MESSAGES;

    // Allocate arrays
    queue->timestamps = malloc(queue->capacity * sizeof(long));
    queue->priorities = malloc(queue->capacity * sizeof(int));
    queue->messages = malloc(queue->capacity * sizeof(Message));
    queue->offsets = malloc(queue->capacity * sizeof(long));
    queue->keys = malloc(queue->capacity * sizeof(int));

    if (!queue->timestamps || !queue->priorities || !queue->messages ||
        !queue->offsets || !queue->keys) {
        freeMessageQueue(queue);
        return NULL;
    }

    // Initialize with sequential numbers and default messages
    secure_random_set_seed(seed);
    for (int i = 0; i < queue->capacity; ++i) {
        queue->timestamps[i] = timestamp_lib_get_current_timestamp();
        queue->priorities[i] = secure_random_int(0, 10);
        queue->messages[i].content = strdup(DEFAULT_MESSAGE);
        queue->offsets[i] = i;
        queue->keys[i] = i;

        if (queue->messages[i].content == NULL) {
            freeMessageQueue(queue);
            return NULL;
        }
    }

    // Custom callback
    if (initCallback) {
        initCallback((void*)queue);
    }

    return queue;
}

void freeMessageQueue(MessageQueue *queue) {
    pthread_mutex_lock(&queue->mutex);

    for (int i = 0; i < queue->capacity; ++i) {
        free(queue->messages[i].content);
    }

    free(queue->timestamps);
    free(queue->priorities);
    free(queue->messages);
    free(queue->offsets);
    free(queue->keys);

    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

void processMessagesAndFindMax(MessageQueue *queue, void (*processCallback)(Message*)) {
    pthread_mutex_lock(&queue->mutex);

    long maxTimestamp = -1;
    for (int i = 0; i < queue->count; ++i) {
        Message msg = queue->messages[i];

        // Process message
        if (processCallback) {
            processCallback(&msg);
        }

        // Find max timestamp
        if (queue->timestamps[i] > maxTimestamp) {
            maxTimestamp = queue->timestamps[i];
        }
    }

    pthread_mutex_unlock(&queue->mutex);

    printf("Max Timestamp: %ld\n", maxTimestamp);
}

int main() {
    MessageQueue *queue = initMessageQueue(42, NULL);
    if (!queue) {
        fprintf(stderr, "Failed to initialize message queue.\n");
        return EXIT_FAILURE;
    }

    processMessagesAndFindMax(queue, NULL);

    freeMessageQueue(queue);
    return EXIT_SUCCESS;
}
```

This code snippet demonstrates a basic implementation of the `processMessagesAndFindMax` function with concurrency support using mutexes. It initializes a message queue and processes messages to find the maximum timestamp, ensuring thread safety and handling memory allocation failures gracefully.']

