    return NULL;
}

void findMax(int *array, size_t size, int *maxValue) {
    if (size == 0) {
        *maxValue = INT_MIN;
        return;
    }
    *maxValue = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > *maxValue) {
            *maxValue = array[i];
        }
    }
}

void freeResources(Record **records, long *offsets, int *keys, size_t recordSize) {
    for (size_t i = 0; i < recordSize; ++i) {
        if (records[i]) {
            free(records[i]->longPtr);
            free(records[i]);
        }
    }
    free(records);
    free(offsets);
    free(keys);
}

int main() {
