    for (size_t i = 0; i < initialRecordSize; ++i) {
        data.records[i] = malloc(sizeof(Record));
    }
    data.offsets = malloc(initialRecordSize * sizeof(long));
    data.keys = malloc(initialRecordSize * sizeof(int));

    initializeArrays(data.offsets, data.keys, initialRecordSize);
    data.recordSize = initialRecordSize;

    pthread_mutex_unlock(&mutex);

    pthread_t thread;
    pthread_create(&thread, NULL, processRecordsAndFindMax, &data);
    pthread_join(thread, NULL);

    pthread_mutex_destroy(&mutex);

    int *integers = malloc(10 * sizeof(int));
    size_t currentSize = 10;
    size_t count = 0;

    while (1) {
        if (count >= currentSize) {
            currentSize *= 2;
            integers = realloc(integers, currentSize * sizeof(int));
        }

        int input;
        scanf("%d", &input);

        if (input == SENTINEL_VALUE) break;

        integers[count++] = input;
    }

    int maxVal;
