#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_MESSAGES 1000
#define DEFAULT_CONTENT_SIZE 256

typedef struct {
    long timestamp;
    int priority;
    char *content;
} Message;

// Global variables for synchronization
pthread_mutex_t queueMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;

void initializeTimestamp(long *timestamp, size_t count, unsigned int seed) {
    srand(seed);
    for (size_t i = 0; i < count; ++i) {
        timestamp[i] = rand();
    }
}

void allocateMessages(Message **messages, size_t count) {
    *messages = malloc(count * sizeof(Message));
    if (*messages == NULL) {
        perror("Failed to allocate messages");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        (*messages)[i].timestamp = 0;
        (*messages)[i].priority = i;
        (*messages)[i].content = malloc(DEFAULT_CONTENT_SIZE * sizeof(char));
        if ((*messages)[i].content == NULL) {
            perror("Failed to allocate message content");
            for (size_t j = 0; j < i; ++j) {
                free((*messages)[j].content);
            }
            free(*messages);
            exit(EXIT_FAILURE);
        }
        strcpy((*messages)[i].content, "default_content");
    }
}

void executeCommandAndProcessMessages(unsigned int seed, void (*processCallback)(Message*)) {
    size_t count = MAX_MESSAGES;
    long *timestamps = malloc(count * sizeof(long));
    if (timestamps == NULL) {
        perror("Failed to allocate timestamps");
        exit(EXIT_FAILURE);
    }

    initializeTimestamp(timestamps, count, seed);

    Message *messages = NULL;
    allocateMessages(&messages, count);

    // Simulate processing messages
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&queueMutex);
        if (processCallback) {
            processCallback(&messages[i]);
        }
        pthread_mutex_unlock(&queueMutex);
    }

    free(timestamps);
    for (size_t i = 0; i < count; ++i) {
        free(messages[i].content);
    }
    free(messages);

    // Example of executing a command
    char *command[] = {"ls", "-l", NULL};
    FILE *file;
    if ((file = fopen("/tmp/test.txt", "r")) == NULL || remove("/tmp/test.txt") != 0) {
        perror("File check/creation failed");
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for child to finish

        FILE *fp = popen(command[0], "r");
        if (!fp) {
            perror("Failed to run command");
            exit(EXIT_FAILURE);
        }

        char buffer[128];
        while (fgets(buffer, sizeof(buffer), fp) != NULL) {
            printf("%s", buffer);
        }
        pclose(fp);

    } else { // Child process
        execvp(command[0], command);
        perror("exec failed");
        exit(EXIT_FAILURE);
    }
}

void exampleProcessCallback(Message *message) {
    message->timestamp += 1;
    strcat(message->content, "_processed");
}

int main() {
    executeCommandAndProcessMessages(42, exampleProcessCallback);
    return 0;
}
```

