#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include "external_parser_library.h"  // Assume this is your external library header

#define MAX_FILES 10
#define BUFFER_SIZE 1024
#define RECORDS_PER_FILE 100

typedef struct {
    double value;
    char identifier[16];
    FILE *file_descriptor;
} Record;

typedef struct {
    double mean;
    double median;
    double stddev;
} StatisticalMetrics;

typedef void (*Callback)(Record *);

pthread_mutex_t metrics_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t error_log_lock = PTHREAD_MUTEX_INITIALIZER;

void processFilesAndAnalyzeData(const char *filenames[], int num_files, Callback callback) {
    if (num_files > MAX_FILES) {
        fprintf(stderr, "Too many files to process.\n");
        return;
    }

    FILE *files[MAX_FILES];
    Record records[MAX_FILES][RECORDS_PER_FILE];
    StatisticalMetrics metrics[num_files];
    char error_log[1024];

    for (int i = 0; i < num_files; ++i) {
        snprintf(records[i][0].identifier, sizeof(records[i][0].identifier), "File_%d", i);

        files[i] = fopen(filenames[i], "r");
        if (!files[i]) {
            pthread_mutex_lock(&error_log_lock);
            snprintf(error_log, sizeof(error_log), "Failed to open file %s: %s\n", filenames[i], strerror(errno));
            fprintf(stderr, "%s", error_log);
            pthread_mutex_unlock(&error_log_lock);
            continue;
        }

        for (int j = 0; j < RECORDS_PER_FILE; ++j) {
            char buffer[BUFFER_SIZE];
            if (!fgets(buffer, BUFFER_SIZE, files[i])) break;

            records[i][j].file_descriptor = files[i];

            // Assume external library function: double parse_double(const char *str);
            records[i][j].value = parse_double(buffer);

            if (callback) {
                callback(&records[i][j]);
            }
        }

        fclose(files[i]);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_mutex_lock(&metrics_lock);

        // Calculate mean
        double sum = 0.0;
        int count = 0;
        for (int j = 0; j < RECORDS_PER_FILE && records[i][j].file_descriptor != NULL; ++j) {
            sum += records[i][j].value;
            count++;
        }
        metrics[i].mean = count ? sum / count : 0.0;

        // Calculate median
        double sorted_values[RECORDS_PER_FILE];
        int valid_count = 0;
        for (int j = 0; j < RECORDS_PER_FILE && records[i][j].file_descriptor != NULL; ++j) {
            sorted_values[valid_count++] = records[i][j].value;
        }
        if (valid_count > 1) {
            qsort(sorted_values, valid_count, sizeof(double), [](const void *a, const void *b) {
                return (*(double *)a - *(double *)b);
            });
            metrics[i].median = valid_count % 2 == 0 ? (sorted_values[valid_count / 2 - 1] + sorted_values[valid_count / 2]) / 2.0
                                                      : sorted_values[valid_count / 2];
        } else {
            metrics[i].median = 0.0;
        }

        // Calculate standard deviation
        double variance_sum = 0.0;
        for (int j = 0; j < valid_count; ++j) {
            double diff = sorted_values[j] - metrics[i].mean;
            variance_sum += diff * diff;
        }
        metrics[i].stddev = valid_count > 1 ? sqrt(variance_sum / (valid_count - 1)) : 0.0;

        pthread_mutex_unlock(&metrics_lock);
    }

    // Example: print metrics
    for (int i = 0; i < num_files; ++i) {
        printf("File %d - Mean: %.2f, Median: %.2f, Stddev: %.2f\n", i, metrics[i].mean, metrics[i].median, metrics[i].stddev);
    }
}

void freeResources(FILE *files[], int num_files) {
    for (int i = 0; i < num_files; ++i) {
        if (files[i]) {
            fclose(files[i]);
        }
    }
}

// Example callback function
void exampleCallback(Record *record) {
    // Custom processing logic, e.g., validation or transformation
}

int main() {
    const char *filenames[] = {"file1.txt", "file2.txt"};
    int num_files = sizeof(filenames) / sizeof(filenames[0]);

    processFilesAndAnalyzeData(filenames, num_files, exampleCallback);

    return 0;
}
```

