```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>

#define MAX_RESOURCE_NAME_LEN 256

typedef enum {
    TYPE_STRING,
    TYPE_INTEGER,
    TYPE_FLOATING_POINT
} ResourceType;

typedef struct Resource {
    char name[MAX_RESOURCE_NAME_LEN];
    ResourceType type;
    union {
        char* stringValue;
        int intValue;
        float floatValue;
    } defaultValue, currentValue;
    unsigned long uniqueId;
    unsigned int version;
} Resource;

typedef struct Chunk {
    double value;
} Chunk;

typedef struct CacheNode {
    void *key;
    void *value;
    struct CacheNode *prev;
    struct CacheNode *next;
} CacheNode;

typedef struct LRUCache {
    size_t capacity;
    CacheNode *head, *tail;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* createLRUCache(size_t capacity) {
    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void putLRUCache(LRUCache *cache, void *key, void *value) {
    pthread_mutex_lock(&cache->lock);

    // Find existing node
    CacheNode *current = cache->head;
    while (current) {
        if (strcmp((char*)current->key, (char*)key) == 0) {
            current->value = value;
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->next;
    }

    // Add new node
    CacheNode *newNode = (CacheNode*)malloc(sizeof(CacheNode));
    newNode->key = key;
    newNode->value = value;
    newNode->prev = NULL;
    newNode->next = cache->head;

    if (cache->head) {
        cache->head->prev = newNode;
    }
    cache->head = newNode;

    if (!cache->tail) {
        cache->tail = newNode;
    }

    // Evict LRU if capacity exceeded
    if ((int)(cache->capacity--) == 0) {
        CacheNode *toDelete = cache->tail;
        cache->tail = toDelete->prev;
        if (cache->tail) {
            cache->tail->next = NULL;
        }
        free(toDelete);
        cache->capacity++;
    }

    pthread_mutex_unlock(&cache->lock);
}

void* getLRUCache(LRUCache *cache, void *key) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *current = cache->head;
    while (current) {
        if (strcmp((char*)current->key, (char*)key) == 0) {
            // Move to front
            if (current != cache->head) {
                if (current->next) current->next->prev = current->prev;
                if (current->prev) current->prev->next = current->next;
                current->prev = NULL;
                current->next = cache->head;
                cache->head->prev = current;
                cache->head = current;
            }
            pthread_mutex_unlock(&cache->lock);
            return current->value;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

typedef struct {
    Resource *resources;
    size_t resourceCount;
    Chunk *chunks;
    size_t chunkCount;
    LRUCache *resourceCache;
} ResourceManager;

ResourceManager* initializeResources(size_t initialResourceCount, size_t initialChunkCount) {
    ResourceManager *manager = (ResourceManager*)malloc(sizeof(ResourceManager));
    manager->resources = (Resource*)calloc(initialResourceCount, sizeof(Resource));
    manager->resourceCount = initialResourceCount;
    manager->chunks = (Chunk*)calloc(initialChunkCount, sizeof(Chunk));
    manager->chunkCount = initialChunkCount;
    manager->resourceCache = createLRUCache(10);
    return manager;
}

int addResource(ResourceManager *manager, const char *name, ResourceType type, void *defaultValue) {
    pthread_mutex_lock(&manager->resources);

    // Resize if necessary
    if (manager->resourceCount == initialResourceCount) {
        size_t newCapacity = manager->resourceCount * 2;
        Resource *newResources = (Resource*)realloc(manager->resources, newCapacity * sizeof(Resource));
        if (!newResources) {
            pthread_mutex_unlock(&manager->resources);
            return -1; // Memory allocation failed
        }
        memset(newResources + initialResourceCount, 0, (newCapacity - initialResourceCount) * sizeof(Resource));
        manager->resources = newResources;
        manager->resourceCount = newCapacity;
    }

    Resource *res = &manager->resources[manager->resourceCount++];
    strncpy(res->name, name, MAX_RESOURCE_NAME_LEN);
    res->type = type;

    switch (type) {
        case TYPE_STRING:
            res->defaultValue.stringValue = strdup((char*)defaultValue);
            break;
        case TYPE_INTEGER:
            res->defaultValue.intValue = *(int*)defaultValue;
            break;
        case TYPE_FLOATING_POINT:
            res->defaultValue.floatValue = *(float*)defaultValue;
            break;
    }

    // Initialize current value to default
    switch (type) {
        case TYPE_STRING:
            res->currentValue.stringValue = strdup(res->defaultValue.stringValue);
            break;
        case TYPE_INTEGER:
            res->currentValue.intValue = res->defaultValue.intValue;
            break;
        case TYPE_FLOATING_POINT:
            res->currentValue.floatValue = res->defaultValue.floatValue;
            break;
    }

    res->uniqueId = rand(); // Simplified unique ID generation
    res->version = 1;

    pthread_mutex_unlock(&manager->resources);
    return 0; // Success
}

int addChunk(ResourceManager *manager, double value) {
    pthread_mutex_lock(&manager->chunks);

    if (manager->chunkCount == initialChunkCount) {
        size_t newCapacity = manager->chunkCount * 2;
        Chunk *newChunks = (Chunk*)realloc(manager->chunks, newCapacity * sizeof(Chunk));
        if (!newChunks) {
            pthread_mutex_unlock(&manager->chunks);
            return -1; // Memory allocation failed
        }
        memset(newChunks + initialChunkCount, 0, (newCapacity - initialChunkCount) * sizeof(Chunk));
        manager->chunks = newChunks;
        manager->chunkCount = newCapacity;
    }

    Chunk *chunk = &manager->chunks[manager->chunkCount++];
    chunk->value = value;

    pthread_mutex_unlock(&manager->chunks);
    return 0; // Success
}

void freeResources(ResourceManager *manager) {
    for (size_t i = 0; i < manager->resourceCount; ++i) {
        Resource *res = &manager->resources[i];
        if (res->type == TYPE_STRING) {
            free(res->defaultValue.stringValue);
            free(res->currentValue.stringValue);
        }
    }
    free(manager->resources);
    free(manager->chunks);
    // Free cache nodes
    CacheNode *current = manager->resourceCache->head;
    while (current) {
        CacheNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->resourceCache->lock);
    free(manager->resourceCache);
    free(manager);
}

void manageDynamicResourcesAndCache() {
    // Example usage
    ResourceManager *manager = initializeResources(10, 10);

    addResource(manager, "exampleString", TYPE_STRING, (void*)"default");
    addChunk(manager, 3.14);

    freeResources(manager);
}
```

This code provides a basic structure for managing dynamic resources and chunks with caching and LRU eviction. It includes error handling and thread safety using mutexes. Adjust the example usage as needed for your application.']

