#include <pthread.h>
#include <openssl/rand.h>

typedef struct {
    int value;
    char stringKey[256];
    long *dynamicPtr;
} record;

// Error logging mechanism
void logError(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Callback function type definition
typedef void (*RecordCallback)(record *);

// Function to find the maximum integer in an array
int findMax(int *arr, size_t size) {
    if (size == 0) return INT_MIN;
    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Thread-safe function to seed the random number generator
void secureSeed() {
    unsigned char seed[32];
    if (RAND_bytes(seed, sizeof(seed)) != 1) {
        logError("Failed to generate random seed");
        exit(EXIT_FAILURE);
    }
    RAND_seed(seed, sizeof(seed));
}

// Function to process records and find max integer from user input
int processRecordsAndFindMax(size_t offsetSize, size_t keySize, size_t recordSize,
                             RecordCallback callback) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    long *offsets = (long *)malloc(offsetSize * sizeof(long));
    int *keys = (int *)malloc(keySize * sizeof(int));
    record *records = (record *)malloc(recordSize * sizeof(record));

    if (!offsets || !keys || !records) {
        logError("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_destroy(&mutex);
        return -1;
    }

    for (size_t i = 0; i < offsetSize; ++i) offsets[i] = i;
    for (size_t i = 0; i < keySize; ++i) keys[i] = i;

    secureSeed();

    for (size_t i = 0; i < recordSize; ++i) {
        records[i].value = RAND() % 100 + 1;
        snprintf(records[i].stringKey, sizeof(records[i].stringKey), "key_%zu", i);
        pthread_mutex_lock(&mutex);
        records[i].dynamicPtr = (long *)malloc(sizeof(long));
        if (!records[i].dynamicPtr) {
            logError("Failed to allocate dynamic pointer");
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j].dynamicPtr);
            }
            free(records);
            pthread_mutex_unlock(&mutex);
            pthread_mutex_destroy(&mutex);
            return -1;
        }
        *records[i].dynamicPtr = i;
        pthread_mutex_unlock(&mutex);

        if (callback) callback(&records[i]);
    }

    int inputSize = 0, capacity = 10;
    int *inputArray = (int *)malloc(capacity * sizeof(int));
    if (!inputArray) {
        logError("Memory allocation failed for input array");
        free(offsets);
        free(keys);
        for (size_t i = 0; i < recordSize; ++i) {
            free(records[i].dynamicPtr);
        }
        free(records);
        pthread_mutex_destroy(&mutex);
        return -1;
    }

    int num;
    while (scanf("%d", &num) == 1) {
        if (inputSize >= capacity) {
            capacity *= 2;
            int *temp = realloc(inputArray, capacity * sizeof(int));
            if (!temp) {
                logError("Memory reallocation failed for input array");
                free(offsets);
                free(keys);
                for (size_t i = 0; i < recordSize; ++i) {
                    free(records[i].dynamicPtr);
                }
                free(records);
                free(inputArray);
                pthread_mutex_destroy(&mutex);
                return -1;
            }
            inputArray = temp;
        }
        inputArray[inputSize++] = num;
    }

    int maxInputValue = findMax(inputArray, inputSize);

    // Free all allocated resources
    free(offsets);
    free(keys);
    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i].dynamicPtr);
    }
    free(records);
    free(inputArray);
    pthread_mutex_destroy(&mutex);

    return maxInputValue;
}
