```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include "uthash.h"
#include "mimalloc.h"

typedef struct {
    int offset;
    int key_int;
    char *key_str;
    long *ref_long;
} Record;

typedef void (*RecordCallback)(Record *);

typedef struct {
    Record **records;
    size_t num_records;
    pthread_mutex_t mutex;
    double checkpoint_interval;
    time_t last_checkpoint_time;
    size_t total_memory_usage;
} DynamicCollection;

void initialize_random() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DynamicCollection *initialize_collection(size_t initial_size, size_t target_records, int key_range_min, int key_range_max, RecordCallback callback) {
    DynamicCollection *collection = mimalloc_calloc(1, sizeof(DynamicCollection));
    if (!collection) return NULL;

    pthread_mutex_init(&collection->mutex, NULL);
    collection->records = mimalloc_malloc(initial_size * sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < target_records; ++i) {
        Record *record = mimalloc_calloc(1, sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        record->offset = i;
        record->key_int = random_int(key_range_min, key_range_max);
        record->key_str = strdup("initial_key"); // Placeholder for UTF-8 string handling
        record->ref_long = mimalloc_malloc(sizeof(long));
        if (!record->ref_long) {
            free(record->key_str);
            free(record);
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        pthread_mutex_lock(&collection->mutex);
        collection->records[i] = record;
        collection->total_memory_usage += sizeof(Record *) + sizeof(Record) + strlen("initial_key") + 1 + sizeof(long);
        pthread_mutex_unlock(&collection->mutex);

        if (callback) {
            callback(record);
        }
    }

    collection->num_records = target_records;

    return collection;
}

void process_record(Record *record) {
    // Custom processing logic
}

void log_initialization(DynamicCollection *collection) {
    time_t now = time(NULL);
    printf("Initialization at %s\n", ctime(&now));
    printf("Allocated memory for %zu records, total usage: %zu bytes\n", collection->num_records, collection->total_memory_usage);
}

void checkpoint(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    if (difftime(time(NULL), collection->last_checkpoint_time) >= collection->checkpoint_interval) {
        printf("Checkpoint at %ld records\n", collection->num_records);
        collection->last_checkpoint_time = time(NULL);
    }
    pthread_mutex_unlock(&collection->mutex);
}

void cleanup(DynamicCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->num_records; ++i) {
        Record *record = collection->records[i];
        if (record) {
            free(record->key_str);
            mimalloc_free(record->ref_long);
            mimalloc_free(record);
        }
    }

    pthread_mutex_destroy(&collection->mutex);
    mimalloc_free(collection->records);
    mimalloc_free(collection);
}

void serialize(DynamicCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&collection->num_records, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->num_records; ++i) {
        Record *record = collection->records[i];
        if (record) {
            fwrite(&record->offset, sizeof(int), 1, file);
            fwrite(&record->key_int, sizeof(int), 1, file);
            size_t len = strlen(record->key_str) + 1;
            fwrite(&len, sizeof(size_t), 1, file);
            fwrite(record->key_str, sizeof(char), len, file);
            fwrite(record->ref_long, sizeof(long), 1, file);
        }
    }

    fclose(file);
}

void deserialize(DynamicCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fread(&collection->num_records, sizeof(size_t), 1, file);

    collection->records = mimalloc_realloc(collection->records, collection->num_records * sizeof(Record *));
    for (size_t i = 0; i < collection->num_records; ++i) {
        Record *record = mimalloc_calloc(1, sizeof(Record));
        if (!record) break;

        fread(&record->offset, sizeof(int), 1, file);
        fread(&record->key_int, sizeof(int), 1, file);

        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        record->key_str = mimalloc_malloc(len * sizeof(char));
        if (!record->key_str) {
            free(record);
            break;
        }
        fread(record->key_str, sizeof(char), len, file);

        record->ref_long = mimalloc_malloc(sizeof(long));
        if (!record->ref_long) {
            free(record->key_str);
            free(record);
            break;
        }
        fread(record->ref_long, sizeof(long), 1, file);

        pthread_mutex_lock(&collection->mutex);
        collection->records[i] = record;
        pthread_mutex_unlock(&collection->mutex);
    }

    fclose(file);
}

int main() {
    size_t initial_size = 100;
    size_t target_records = 50;
    int key_range_min = 0, key_range_max = 100;

    DynamicCollection *collection = initialize_collection(initial_size, target_records, key_range_min, key_range_max, process_record);
    if (!collection) {
        fprintf(stderr, "Failed to initialize collection\n");
        return EXIT_FAILURE;
    }

    log_initialization(collection);

    checkpoint(collection);

    serialize(collection, "data.bin");

    deserialize(collection, "data.bin");

    cleanup(collection);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread safety.
- **Memory Management**: Utilizes `mimalloc` for efficient memory allocation and reallocation.
- **Error Handling**: Checks for memory allocation failures and handles them gracefully.
- **Logging**: Provides basic logging of initialization and checkpointing.
- **Serialization/Deserialization**: Supports saving and loading the data structure to/from a file.
- **Internationalization**: Placeholder for UTF-8 string handling (use libraries like ICU for full support).
- **Checkpointing**: Periodically logs checkpoints based on a time interval.

This code is designed to be extensible and scalable, with considerations for high concurrency and performance.']

