#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define INITIAL_SIZE 10
#define TARGET_RECORDS 1000
#define RANDOM_RANGE_MAX 100

typedef struct {
    size_t offset;
    int integer_key;
    char *string_key;
    long *reference_value;
} Record;

typedef void (*Callback)(Record *);

typedef struct {
    pthread_mutex_t lock;
    Record **records;
    size_t current_size;
    size_t capacity;
    size_t checkpoint_interval;
    Record **checkpoints;
    size_t num_checkpoints;
} DynamicCollection;

// Function to initialize the random number generator
void init_random() {
    srand((unsigned int)time(NULL));
}

// Generates a pseudo-random integer within a specified range
int generate_random(int max_value) {
    return rand() % (max_value + 1);
}

// Thread-safe function to add a record
int add_record(DynamicCollection *collection, Record *record, Callback callback);

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

DynamicCollection* create_collection(size_t initial_size, size_t checkpoint_interval) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = (Record**)malloc(initial_size * sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->current_size = 0;
    collection->capacity = initial_size;
    collection->checkpoint_interval = checkpoint_interval;

    collection->checkpoints = (Record**)calloc(checkpoint_interval, sizeof(Record*));
    if (!collection->checkpoints) {
        free(collection->records);
        free(collection);
        return NULL;
    }

    collection->num_checkpoints = 0;
    log_message("DynamicCollection created successfully.");
    return collection;
}

void destroy_collection(DynamicCollection *collection) {
    pthread_mutex_destroy(&collection->lock);

    for (size_t i = 0; i < collection->current_size; ++i) {
        free(collection->records[i]->string_key);
        free(collection->records[i]->reference_value);
        free(collection->records[i]);
    }
    free(collection->records);

    for (size_t i = 0; i < collection->num_checkpoints; ++i) {
        free(collection->checkpoints[i]);
    }
    free(collection->checkpoints);

    free(collection);
    log_message("DynamicCollection destroyed.");
}

int add_record(DynamicCollection *collection, Record *record, Callback callback) {
    pthread_mutex_lock(&collection->lock);

    if (collection->current_size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            log_message("Memory allocation failed during resize.");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    record->offset = collection->current_size++;
    if (callback) callback(record);

    // Checkpointing
    if (collection->current_size % collection->checkpoint_interval == 0 && 
        collection->num_checkpoints < collection->checkpoint_interval) {
        collection->checkpoints[collection->num_checkpoints++] = malloc(collection->capacity * sizeof(Record*));
        memcpy(collection->checkpoints[collection->num_checkpoints - 1], collection->records, collection->capacity * sizeof(Record*));
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void initialize_records(DynamicCollection *collection, size_t target_records) {
    init_random();

    for (size_t i = 0; i < target_records; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            log_message("Memory allocation failed for a record.");
            continue;
        }

        char string_key[256];
        snprintf(string_key, sizeof(string_key), "Key_%zu", i);
        record->string_key = strdup(string_key);
        record->integer_key = generate_random(RANDOM_RANGE_MAX);

        long *value = (long*)malloc(sizeof(long));
        if (!value) {
            log_message("Memory allocation failed for a reference value.");
            free(record->string_key);
            free(record);
            continue;
        }
        *value = i; // Example value
        record->reference_value = value;

        add_record(collection, record, NULL);
    }

    log_message("Records initialized successfully.");
}

int main() {
    size_t checkpoint_interval = 100;
    DynamicCollection *collection = create_collection(INITIAL_SIZE, checkpoint_interval);

    if (!collection) {
        log_message("Failed to create collection.");
        return EXIT_FAILURE;
    }

    initialize_records(collection, TARGET_RECORDS);
    destroy_collection(collection);
    return EXIT_SUCCESS;
}
```

