void freeSession(ProtocolSession *session) {
    if (session->messageBytes) {
        free(session->messageBytes);
    }
    pthread_mutex_destroy(&session->lock);
}

int createSession(int sessionID, int protocolVersion, MessageType messageType,
                  size_t defaultPayloadSize, const char *currentState) {
    pthread_mutex_lock(&sessionMutex);

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].sessionID == 0) { // Empty slot
            sessions[i].sessionID = sessionID;
            sessions[i].protocolVersion = protocolVersion;
            sessions[i].messageType = messageType;
            sessions[i].defaultPayloadSize = defaultPayloadSize;
            strncpy(sessions[i].currentState, currentState, sizeof(sessions[i].currentState));
            sessions[i].transactionID = rand(); // Random initial ID
            sessions[i].messageBytes = NULL;
            sessions[i].messageLength = 0;

            pthread_mutex_unlock(&sessionMutex);
            return i; // Return session index
        }
    }

    pthread_mutex_unlock(&sessionMutex);
    return -1; // No available slot
}

void resizeMessage(ProtocolSession *session, size_t newSize) {
    if (newSize > session->messageLength) {
        uint8_t *newBytes = realloc(session->messageBytes, newSize);
        if (!newBytes) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        session->messageBytes = newBytes;
        memset(newBytes + session->messageLength, 0, newSize - session->messageLength);
    }
    session->messageLength = newSize;
}

void handleSession(ProtocolSession *session, const uint8_t *data, size_t length) {
    pthread_mutex_lock(&session->lock);

    resizeMessage(session, length);
    memcpy(session->messageBytes, data, length);

    // Simulated processing
    printf("Processed message for session %d\n", session->sessionID);

    pthread_mutex_unlock(&session->lock);
}

void cleanupSessions() {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].sessionID != 0) {
            freeSession(&sessions[i]);
            memset(&sessions[i], 0, sizeof(sessions[i]));
        }
    }
}

