// Function to generate random numbers with caching
int getRandom(int min, int max, unsigned int *seed_cache, size_t cache_size) {
    static pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&rand_mutex);
    if (*seed_cache == 0 || rand() % (cache_size / sizeof(unsigned int)) == 0) {
        *seed_cache = rand();
    }
    int random_number = min + (*seed_cache % (max - min + 1));
    pthread_mutex_unlock(&rand_mutex);

    return random_number;
}

// Function to initialize and process records
void processAndInitializeRecords(long **offsets, size_t offset_size, 
                                int *keys, size_t key_size, Record **records,
                                size_t record_size, unsigned int seed, Callback callback) {

    // Validate inputs
    if (!offsets || !keys || !records || !record_size || !callback)
        return;

    // Initialize offsets and keys with sequential numbers
    for (size_t i = 0; i < offset_size; ++i) {
        long *new_offsets = realloc(*offsets, (i + 1) * sizeof(long));
        if (!new_offsets) {
            fprintf(stderr, "Memory allocation failed for offsets\n");
            goto cleanup;
        }
        (*offsets) = new_offsets;
        (*offsets)[i] = i;
    }

    for (size_t j = 0; j < key_size; ++j) {
        int *new_keys = realloc(keys, (j + 1) * sizeof(int));
        if (!new_keys) {
            fprintf(stderr, "Memory allocation failed for keys\n");
            goto cleanup;
        }
        keys = new_keys;
        keys[j] = j;
    }

    // Initialize records
    *records = malloc(record_size * sizeof(Record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    unsigned int seed_cache = seed ? seed : rand();

    for (size_t k = 0; k < record_size; ++k) {
        pthread_mutex_lock(&mutex);

        Record *new_record = realloc(*records, (k + 1) * sizeof(Record));
        if (!new_record) {
            fprintf(stderr, "Memory allocation failed during records processing\n");
            pthread_mutex_unlock(&mutex);
            goto cleanup;
        }
        (*records) = new_record;

        Record *current_record = &((*records)[k]);
        current_record->value = getRandom(0, 100, &seed_cache, sizeof(seed_cache));
        snprintf(current_record->key, sizeof(current_record->key), "Key_%d", keys[k % key_size]);

        long *offset_value = malloc(sizeof(long));
        if (!offset_value) {
            fprintf(stderr, "Memory allocation failed for offset pointer\n");
            pthread_mutex_unlock(&mutex);
            goto cleanup;
        }
        current_record->offset_ptr = offset_value;
        *current_record->offset_ptr = (*offsets)[k % offset_size];

        // Invoke the callback function
        callback(current_record);

        pthread_mutex_unlock(&mutex);
    }

cleanup:
    // Cleanup logic if needed (free allocated memory)
    free(*offsets);
    free(*records);
}

