#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define DEFAULT_TRANSACTION_AMOUNT 100.0

typedef struct {
    double amount;
    char transactionID[20];
    long *status;
} Transaction;

// Custom pool allocator structure for efficient memory management
typedef struct {
    void **blocks;
    size_t block_size;
    size_t current_index;
    size_t total_blocks;
} PoolAllocator;

PoolAllocator* create_pool(size_t block_size, size_t total_blocks) {
    PoolAllocator *pool = (PoolAllocator*)malloc(sizeof(PoolAllocator));
    if (!pool) return NULL;

    pool->blocks = (void**)calloc(total_blocks, sizeof(void*));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->current_index = 0;
    pool->total_blocks = total_blocks;

    for (size_t i = 0; i < total_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            // Free allocated blocks in case of failure
            for (size_t j = 0; j < i; ++j) free(pool->blocks[j]);
            free(pool->blocks);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

void destroy_pool(PoolAllocator *pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->total_blocks; ++i) {
        free(pool->blocks[i]);
    }

    free(pool->blocks);
    free(pool);
}

void* allocate_from_pool(PoolAllocator *pool) {
    if (pool && pool->current_index < pool->total_blocks) {
        return pool->blocks[pool->current_index++];
    }
    return NULL;
}

typedef void (*TransactionCallback)(Transaction*);

void processTransactions(size_t initial_size, unsigned int seed, TransactionCallback callback) {
    size_t max_transactions = initial_size;
    long *transactionStatusPool = (long*)malloc(max_transactions * sizeof(long));
    if (!transactionStatusPool) {
        fprintf(stderr, "Memory allocation failed for transaction statuses.\n");
        return;
    }

    double *amounts = (double*)malloc(initial_size * sizeof(double));
    char **transactionIDs = (char**)malloc(initial_size * sizeof(char*));

    if (!amounts || !transactionIDs) {
        fprintf(stderr, "Memory allocation failed for transaction data structures.\n");
        free(transactionStatusPool);
        return;
    }

    // Initialize random number generator
    srand(seed);

    PoolAllocator *transactionPool = create_pool(sizeof(Transaction), max_transactions);
    if (!transactionPool) {
        fprintf(stderr, "Memory allocation failed for transaction pool.\n");
        free(amounts);
        free(transactionIDs);
        free(transactionStatusPool);
        return;
    }

    // Populate IDs and amounts
    for (size_t i = 0; i < initial_size; ++i) {
        amounts[i] = DEFAULT_TRANSACTION_AMOUNT + ((double)rand() / RAND_MAX * 100.0);

        transactionIDs[i] = (char*)malloc(20);
        if (!transactionIDs[i]) {
            fprintf(stderr, "Memory allocation failed for transaction ID.\n");
            destroy_pool(transactionPool);
            free(amounts);
            free(transactionStatusPool);
            return;
        }
        snprintf(transactionIDs[i], 20, "%lu", i);

        Transaction *transaction = (Transaction*)allocate_from_pool(transactionPool);
        if (!transaction) {
            fprintf(stderr, "Memory allocation failed for transaction from pool.\n");
            destroy_pool(transactionPool);
            free(amounts);
            free(transactionStatusPool);
            return;
        }

        transaction->amount = amounts[i];
        strncpy(transaction->transactionID, transactionIDs[i], 19);
        transaction->status = &transactionStatusPool[i];

        if (callback) {
            callback(transaction);
        }
    }

    destroy_pool(transactionPool);
    for (size_t i = 0; i < initial_size; ++i) {
        free(transactionIDs[i]);
    }
    free(amounts);
    free(transactionIDs);
    free(transactionStatusPool);
}

// Example usage
void exampleCallback(Transaction *transaction) {
    printf("Processed transaction ID: %s, Amount: %.2f\n", transaction->transactionID, transaction->amount);
}

int main() {
    processTransactions(10, 12345, exampleCallback);
    return 0;
}
