typedef enum {
    LOW,
    MEDIUM,
    HIGH
} priority_level;

typedef struct event {
    time_t timestamp;
    priority_level priority;
    char *description;
    struct event *next;
} event;

typedef struct {
    event *head;
    pthread_mutex_t lock;
    int cache_size;
    char **cache;
    int cache_index;
} event_collection;

event_collection* create_event_collection(int initial_cache_size) {
    event_collection *col = malloc(sizeof(event_collection));
    col->head = NULL;
    pthread_mutex_init(&col->lock, NULL);
    col->cache_size = initial_cache_size;
    col->cache = malloc(initial_cache_size * sizeof(char *));
    col->cache_index = 0;

    for (int i = 0; i < initial_cache_size; i++) {
        col->cache[i] = NULL;
    }
    return col;
}

char* get_cached_string(event_collection *col, const char *str) {
    pthread_mutex_lock(&col->lock);

    for (int i = 0; i < col->cache_index; i++) {
        if (col->cache[i] && strcmp(col->cache[i], str) == 0) {
            pthread_mutex_unlock(&col->lock);
            return col->cache[i];
        }
    }

    char *new_str = strdup(str);
    if (col->cache_index < col->cache_size) {
        col->cache[col->cache_index++] = new_str;
    } else {
        free(new_str); // Cache full, remove from cache
    }

    pthread_mutex_unlock(&col->lock);
    return new_str;
}

void add_event(event_collection *col, time_t timestamp, priority_level priority, const char *description) {
    event *new_event = malloc(sizeof(event));
    new_event->timestamp = timestamp;
    new_event->priority = priority;
    new_event->description = get_cached_string(col, description);
    new_event->next = NULL;

    pthread_mutex_lock(&col->lock);

    if (col->head == NULL) {
        col->head = new_event;
    } else {
        event *current = col->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_event;
    }

    pthread_mutex_unlock(&col->lock);
}

void print_events(event_collection *col) {
    pthread_mutex_lock(&col->lock);

    event *current = col->head;
    while (current != NULL) {
        printf("Timestamp: %ld, Priority: %d, Description: %s\n",
               current->timestamp,
               current->priority,
               current->description);
        current = current->next;
    }

    pthread_mutex_unlock(&col->lock);
}

void free_event_collection(event_collection *col) {
    event *current = col->head;
    while (current != NULL) {
        event *temp = current;
        current = current->next;
        free(temp->description);
        free(temp);
    }

    for (int i = 0; i < col->cache_index; i++) {
        free(col->cache[i]);
    }

    free(col->cache);
    pthread_mutex_destroy(&col->lock);
    free(col);
}
