typedef void (*CallbackFunc)(Record *);

void initialize_rng() {
    srand((unsigned int) time(NULL));
}

int random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

void log_message(const char *message) {
    printf("[%ld] %s\n", time(NULL), message);
}

Record* create_records(size_t record_count, int key_range_min, int key_range_max,
                       CallbackFunc callback) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t offset_size = record_count;
    size_t key_size = record_count;

    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        log_message("Memory allocation failed");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    Record *records = malloc(record_count * sizeof(Record));
    if (!records) {
        log_message("Memory allocation failed");
        free(offsets);
        free(keys);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = random_int(key_range_min, key_range_max);

        snprintf(records[i].key, MAX_STRING_LENGTH, "Key_%zu", i);

        long *long_data = malloc(sizeof(long));
        if (!long_data) {
            log_message("Memory allocation failed for long pointer");
            continue;
        }

        records[i].long_pointer = long_data;

        pthread_mutex_lock(&lock);
        if (callback) callback(&records[i]);
        pthread_mutex_unlock(&lock);
    }

    log_message("Initialization completed");

    pthread_mutex_destroy(&lock);

    return records;
}

void process_record(Record *record) {
    printf("Processing Record: Value=%d, Key=%s\n", record->value, record->key);
}

int main() {
    initialize_rng();

    size_t record_count = 10;
    int key_range_min = 1;
    int key_range_max = 100;

    Record *records = create_records(record_count, key_range_min, key_range_max, process_record);

    if (records) {
        for (size_t i = 0; i < record_count; ++i) {
            free(records[i].long_pointer);
        }
        free(records);
    }

    return 0;
}
