    for (size_t i = 0; i < initial_record_size; ++i) {
        callback(&records[i]);
    }

    // Dynamic resizing logic (user input simulation)
    size_t new_size = initial_record_size * 2;
    record* resized_records = resize_record_array(records, initial_record_size, new_size);
    if (!resized_records) {
        free_resources(offsets, keys, records);
        return -1;
    }

    // Memory cleanup
    free_resources(offsets, keys, resized_records);

    return 0; // Success
}

// Helper functions

void initialize(long* offsets, size_t size) {
    for (size_t i = 0; i < size; ++i) offsets[i] = -1;
}

void fill_sequential(long* array, size_t size, unsigned seed) {
    srand(seed);
    for (size_t i = 0; i < size; ++i) array[i] = i;
}

long* allocate_dynamic_long_array(size_t count) {
    return malloc(count * sizeof(long));
}

record* resize_record_array(record* arr, size_t current_size, size_t new_size) {
    record* temp = realloc(arr, new_size * sizeof(record));
    if (!temp) return NULL;

    for (size_t i = current_size; i < new_size; ++i) {
        pthread_mutex_lock(&mutex);

        // Allocate dynamic long
        temp[i].dynamic_long = allocate_dynamic_long_array(1);
        if (!temp[i].dynamic_long) {
            free_resources(NULL, NULL, arr); // Ensure cleanup on failure
            return NULL;
        }

        // Set random value and key string
        temp[i].value = secure_rand_int(1000); // Hypothetical function
        snprintf(temp[i].key, sizeof(temp[i].key), "Record %zu", i);

        pthread_mutex_unlock(&mutex);
    }
    return temp;
}

void free_resources(long* offsets, int* keys, record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (size_t i = 0; records[i].dynamic_long != NULL; ++i) {
            free(records[i].dynamic_long);
        }
        free(records);
    }
}
