#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *name;
    enum { STRING, INTEGER, BOOLEAN } type;
    union {
        char *str_value;
        int int_value;
        _Bool bool_value;
    };
    char *default_value;
    void *current_value;
    char *dns_address;
} Preference;

typedef struct {
    int value;
    char key[256];
    long *dynamic_long_ptr;
} Record;

void resize_array(void **array, size_t current_size, size_t new_size, size_t element_size) {
    if (new_size > 0) {
        void *new_array = realloc(*array, new_size * element_size);
        if (!new_array) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE); // Handle error as needed
        }
        *array = new_array;
    } else {
        free(*array);
        *array = NULL;
    }
}

void process_record_init(Record *record, int index, long seed) {
    record->value = index;  // Example initialization
    snprintf(record->key, sizeof(record->key), "Key_%d", index);
    record->dynamic_long_ptr = malloc(sizeof(long));
    if (!record->dynamic_long_ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE); // Handle error as needed
    }
    *record->dynamic_long_ptr = seed + index;  // Example initialization with seeding
}

void process_preference_init(Preference *prefs, size_t index, const char *name, enum { STRING, INTEGER, BOOLEAN } type,
                             const char *default_value) {
    prefs[index].name = strdup(name);
    prefs[index].type = type;
    prefs[index].default_value = default_value ? strdup(default_value) : NULL;

    switch (type) {
        case STRING:
            prefs[index].current_value = malloc(strlen(default_value) + 1); // Example allocation
            strcpy((char *)prefs[index].current_value, default_value);
            break;
        case INTEGER:
            prefs[index].int_value = atoi(default_value);
            prefs[index].current_value = &prefs[index].int_value;
            break;
        case BOOLEAN:
            prefs[index].bool_value = (strcmp(default_value, "true") == 0) ? 1 : 0;
            prefs[index].current_value = &prefs[index].bool_value;
            break;
    }
}

void processAndManagePreferences(size_t initial_offset_size, size_t initial_key_size,
                                 size_t initial_record_size, size_t initial_prefs_size,
                                 long seed, void (*record_callback)(Record *, int),
                                 void (*preference_callback)(Preference *, size_t)) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Manage offset list
    long *offsets = malloc(initial_offset_size * sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Manage key array
    int *keys = malloc(initial_key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    size_t offset_count = 0, key_count = 0;
    for (size_t i = 0; i < initial_offset_size || i < initial_key_size; ++i) {
        offsets[offset_count++] = i;
        keys[key_count++] = i;
    }

    // Manage record collection
    Record *records = malloc(initial_record_size * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initial_record_size; ++i) {
        process_record_init(&records[i], i, seed);
        record_callback ? record_callback(&records[i], i) : NULL;
    }

    // Manage preference array
    Preference *preferences = malloc(initial_prefs_size * sizeof(Preference));
    if (!preferences) {
        free(offsets);
        free(keys);
        free(records);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initial_prefs_size; ++i) {
        process_preference_init(preferences, i, "PrefName", STRING, "default_value");
        preference_callback ? preference_callback(&preferences[i], i) : NULL;
    }

    // Example dynamic resizing
    resize_array((void **)&offsets, offset_count, offset_count + 10, sizeof(long));
    resize_array((void **)&keys, key_count, key_count + 10, sizeof(int));
    resize_array((void **)&records, initial_record_size, initial_record_size + 5, sizeof(Record));

    // Cleanup and thread safety
    pthread_mutex_destroy(&lock);

    free(offsets);
    free(keys);
    for (size_t i = 0; i < initial_record_size; ++i) {
        free(records[i].dynamic_long_ptr);
    }
    free(records);

    for (size_t i = 0; i < initial_prefs_size; ++i) {
        free(preferences[i].name);
        if (preferences[i].type == STRING && preferences[i].default_value) {
            free((char *)preferences[i].current_value);
        } else if (preferences[i].type == STRING) {
            free(preferences[i].default_value);
        }
    }
    free(preferences);
}
