```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdatomic.h>

// External library header for secure random number generation
#include "secure_random_lib.h"

#define INITIAL_SIZE 10

typedef struct {
    double value;
    char *key;
    double *number_ptr;
} entry_t;

typedef void (*callback_fn)(entry_t *);

int hash_function(const char *str, size_t table_size) {
    uint64_t hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % table_size;
}

entry_t **initialize_entries(size_t size, double value_range[2], uint64_t seed, callback_fn callback) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    entry_t **entries = malloc(size * sizeof(entry_t *));
    if (!entries) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        return NULL;
    }

    secure_random_set_seed(seed);

    for (size_t i = 0; i < size; ++i) {
        entries[i] = malloc(sizeof(entry_t));
        if (!entries[i]) {
            fprintf(stderr, "Memory allocation failed at index %zu\n", i);
            // Cleanup previously allocated memory
            for (size_t j = 0; j < i; ++j)
                free(entries[j]);
            free(entries);
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        entries[i]->value = secure_random_double(value_range[0], value_range[1]);

        char *key = malloc(20); // Assume keys are at most 19 chars + null terminator
        if (!key) {
            fprintf(stderr, "Memory allocation failed for key at index %zu\n", i);
            free(entries[i]);
            continue; // Try to proceed with next entry
        }

        snprintf(key, 20, "key%zu", i);

        entries[i]->key = strdup(key); // Duplicate string for safety
        if (!entries[i]->key) {
            fprintf(stderr, "Memory allocation failed for key duplication at index %zu\n", i);
            free(entries[i]);
            continue; // Try to proceed with next entry
        }

        double *number_ptr = malloc(sizeof(double));
        if (!number_ptr) {
            fprintf(stderr, "Memory allocation failed for number_ptr at index %zu\n", i);
            free(entries[i]->key);
            free(entries[i]);
            continue;
        }

        entries[i]->number_ptr = number_ptr;

        if (callback)
            callback(entries[i]);
    }

    pthread_mutex_unlock(&lock);

    return entries;
}

void cleanup_entries(entry_t **entries, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (entries[i]) {
            free(entries[i]->key);
            free(entries[i]->number_ptr);
            free(entries[i]);
        }
    }
    free(entries);
}

void resize_entries(entry_t **entries, size_t current_size, size_t new_size, double value_range[2], uint64_t seed) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    entry_t **new_entries = realloc(entries, new_size * sizeof(entry_t *));

    if (!new_entries && new_size > 0) {
        fprintf(stderr, "Memory reallocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    for (size_t i = current_size; i < new_size; ++i) {
        new_entries[i] = malloc(sizeof(entry_t));
        if (!new_entries[i]) {
            fprintf(stderr, "Memory allocation failed at index %zu during resize\n", i);
            cleanup_entries(new_entries, i); // Cleanup existing entries
            free(new_entries);
            pthread_mutex_unlock(&lock);
            return;
        }

        new_entries[i]->value = secure_random_double(value_range[0], value_range[1]);

        char *key = malloc(20);
        if (!key) {
            fprintf(stderr, "Memory allocation failed for key at index %zu during resize\n", i);
            free(new_entries[i]);
            continue;
        }

        snprintf(key, 20, "key%zu", i);

        new_entries[i]->key = strdup(key); 
        if (!new_entries[i]->key) {
            fprintf(stderr, "Memory allocation failed for key duplication at index %zu during resize\n", i);
            free(new_entries[i]);
            continue;
        }

        double *number_ptr = malloc(sizeof(double));
        if (!number_ptr) {
            fprintf(stderr, "Memory allocation failed for number_ptr at index %zu during resize\n", i);
            free(entries[i]->key);
            free(entries[i]);
            continue;
        }

        new_entries[i]->number_ptr = number_ptr;
    }

    *entries = new_entries;
    pthread_mutex_unlock(&lock);
}

int main() {
    double value_range[2] = {0.0, 1.0};
    entry_t **entries = initialize_entries(INITIAL_SIZE, value_range, 12345ULL, NULL);

    if (entries) {
        // Resize operations can be performed here as needed
        resize_entries(entries, INITIAL_SIZE, INITIAL_SIZE * 2, value_range, 67890ULL);

        cleanup_entries(entries, INITIAL_SIZE * 2);
    }

    return 0;
}
```

This code manages a complex data structure, ensures memory management and thread safety with mutexes, integrates secure random number generation, allows for dynamic resizing, and provides callback support. The cleanup function is used to prevent memory leaks by freeing all dynamically allocated resources upon function exit.']

