int manage_memory_allocation(int n, int m, record **datasets) {
    if (n <= 0 || m <= 0) return -1; // Invalid input parameters

    srand(time(NULL)); // Seed for random number generation

    // Arrays to store used identifiers for uniqueness check
    unsigned int *identifiers = malloc(n * sizeof(unsigned int));
    if (!identifiers) {
        fprintf(stderr, "Failed to allocate memory for identifiers\n");
        return -2;
    }

    datasets = malloc(n * sizeof(record *));
    if (!datasets) {
        free(identifiers);
        fprintf(stderr, "Failed to allocate memory for dataset pointers\n");
        return -3;
    }

    long offset_value; // Temporary variable for sum calculation

    for (int i = 0; i < n; ++i) {
        datasets[i] = malloc(sizeof(record));
        if (!datasets[i]) {
            fprintf(stderr, "Failed to allocate memory for dataset %d\n", i);

            // Free previously allocated resources
            while (--i >= 0) free(datasets[i]);
            free(identifiers);
            free(datasets);

            return -4;
        }

        datasets[i]->keys = malloc(m * sizeof(int));
        if (!datasets[i]->keys) {
            fprintf(stderr, "Failed to allocate memory for keys of dataset %d\n", i);

            // Free previously allocated resources
            free(datasets[i]);
            while (--i >= 0) free(datasets[i]);
            free(identifiers);
            free(datasets);

            return -5;
        }

        datasets[i]->sum_offsets = 0;
        offset_value = rand() % (1L << 31); // Random long value for sum calculation

        for (int j = 0; j < m; ++j) {
            datasets[i]->keys[j] = i * m + j + 1; // Ensure distinct keys across all datasets
            datasets[i]->sum_offsets += offset_value;
        }

        unsigned int identifier = rand() % ((unsigned int)(1U << 24)); // Random identifier within range
        while (1) {
            int unique = 1;

            for (int k = 0; k < i; ++k) { // Check uniqueness of the identifier
                if (identifiers[k] == identifier) {
                    unique = 0;
                    break;
                }
            }

            if (unique) {
                datasets[i]->identifier = identifier;
                identifiers[i] = identifier;
                break;
            } else {
                identifier = rand() % ((unsigned int)(1U << 24));
            }
        }
    }

    free(identifiers); // Free the temporary identifiers array
    return 0; // Success
}

// Function to deallocate memory for datasets
void free_datasets(int n, record **datasets) {
    if (!datasets || !n) return;

    for (int i = 0; i < n; ++i) {
        if (datasets[i]) {
            free(datasets[i]->keys);
            free(datasets[i]);
        }
    }

    free(datasets);
}

// Example usage
int main() {
    int n = 10; // Number of datasets
    int m = 5;  // Number of elements per dataset

    record *datasets = NULL;
    int result = manage_memory_allocation(n, m, &datasets);

    if (result == 0) {
        // Use the datasets...
        for (int i = 0; i < n; ++i) {
            printf("Dataset %d: Identifier = %u, Sum of offsets = %ld\n", 
                   i + 1, datasets[i]->identifier, datasets[i]->sum_offsets);
        }
    } else {
        fprintf(stderr, "Error in managing memory allocation with code: %d\n", result);
    }

    free_datasets(n, &datasets); // Ensure all allocated memory is freed
    return 0;
}
