['Below is an implementation in C for managing dynamic memory allocation under various operational constraints described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure definition
typedef struct {
    int* keys;
    long sum;
} record;

// Function to generate random number within a range and check for duplicates using hash table
int generate_unique_random(int min, int max, int* used_values, int n) {
    if (max - min + 1 < n) return -1; // not enough unique numbers

    int value;
    do {
        value = rand() % (max - min + 1) + min;
    } while (used_values[value] == 1);

    used_values[value] = 1;
    return value;
}

// Function to shuffle array
void shuffle_array(int* array, size_t n) {
    if (n > 1) {
        for (size_t i = 0; i < n - 1; i++) {
            size_t j = i + rand() / (RAND_MAX / (n - i) + 1);
            int t = array[j];
            array[j] = array[i];
            array[i] = t;
        }
    }
}

// Custom memory leak detector
void* checked_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long compute_sum(long* array, int m) {
    long sum = 0;
    for (int i = 0; i < m; ++i) {
        sum += array[i];
    }
    return sum;
}

// Main function to manage dynamic memory allocation
int manage_memory(int n, int m, long** offset_arrays, int time_limit_seconds) {
    srand(time(NULL));

    // Allocate memory for records and used_values hash table
    record* records = checked_malloc(n * sizeof(record));
    int* used_values = checked_malloc((m + 1) * sizeof(int)); // max possible key value range

    if (used_values == NULL || records == NULL) {
        free(records);
        free(used_values);
        return -1;
    }

    for (int i = 0; i <= m; ++i) {
        used_values[i] = 0; // Initialize hash table to zero
    }

    time_t start_time = time(NULL);

    for (int i = 0; i < n; ++i) {
        if (offset_arrays[i] == NULL) continue;

        records[i].keys = checked_malloc(m * sizeof(int));
        if (!records[i].keys) goto cleanup;

        // Initialize and shuffle keys
        for (int j = 0; j < m; ++j) {
            records[i].keys[j] = j + 1;
        }
        shuffle_array(records[i].keys, m);

        // Compute sum of offsets
        records[i].sum = compute_sum(offset_arrays[i], m);

        // Generate unique random value for record's 'int' field
        int random_value = generate_unique_random(1, m * n, used_values, n);
        if (random_value == -1) {
            goto cleanup;
        }
    }

    time_t end_time = time(NULL);

    if (difftime(end_time, start_time) > time_limit_seconds) {
        fprintf(stderr, "Execution exceeded the time limit\n");
        goto cleanup;
    }

    // Cleanup and return success
    free(used_values);
    for (int i = 0; i < n; ++i) {
        if (records[i].keys != NULL) {
            free(records[i].keys);
        }
    }
    free(records);

    return 0;

cleanup:
    for (int i = 0; i < n; ++i) {
        if (records[i].keys != NULL) {
            free(records[i].keys);
        }
    }
    free(used_values);
    free(records);

    return -1;
}
