    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize all allocated memory to zero using calloc (or set manually)
    long *temp_offsets = calloc(size, sizeof(long));
    int *temp_keys = calloc(size, sizeof(int));
    Record *temp_records = calloc(size, sizeof(Record));

    if (!temp_offsets || !temp_keys || !temp_records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
