int validate_and_populate_records(record **records, int size_records, long *long_offsets, int *keys, char *log_messages);
void deallocate_memory(long *long_offsets, int size_long, int *keys, int size_keys, record *records, int size_records, char *log_messages);

int main() {
    int log_size = 1024;
    long *long_offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    initialize_arrays(&long_offsets, sizeof(long_offsets)/sizeof(long), &keys, sizeof(keys)/sizeof(int), &log_messages, log_size);

    if (validate_and_populate_records(&records, 100, long_offsets, keys, log_messages) == 0) {
        printf("Records populated successfully.\n");
    }

    deallocate_memory(long_offsets, sizeof(long_offsets)/sizeof(long), keys, sizeof(keys)/sizeof(int), records, 100, log_messages);

    return 0;
}

void initialize_arrays(long **long_offsets, int size_long, int **keys, int size_keys, char **log_messages, int log_size) {
    srand(time(NULL));

    *long_offsets = malloc(size_long * sizeof(long));
    if (!*long_offsets) exit(EXIT_FAILURE);
    for (int i = 0; i < size_long; ++i) (*long_offsets)[i] = rand() % 100000;

    *keys = malloc(size_keys * sizeof(int));
    if (!*keys) exit(EXIT_FAILURE);
    for (int i = 0; i < size_keys; ++i) {
        int key;
        do { key = rand() % 100; } while (key >= size_long || (i > 0 && key == (*keys)[i-1]));
        (*keys)[i] = key;
    }

    *log_messages = malloc(log_size);
    if (!*log_messages) exit(EXIT_FAILURE);
    strcpy(*log_messages, "Initialization complete.\n");
}

int validate_and_populate_records(record **records, int size_records, long *long_offsets, int *keys, char *log_messages) {
    int error_count = 0;
    *records = malloc(size_records * sizeof(record));
    if (!*records) exit(EXIT_FAILURE);

    for (int i = 0; i < size_records; ++i) {
        (*records)[i].value = rand() % 1001;
        (*records)[i].index = i;
        (*records)[i].offset_ptr = &long_offsets[(*records)[i].value];
        (*records)[i].key_ref = &keys[i];

        // Check for duplicate keys
        for (int j = 0; j < i; ++j) {
            if ((*records)[j].key_ref == (*records)[i].key_ref) {
                error_count++;
                sprintf(log_messages + strlen(log_messages), "Duplicate key found at index %d.\n", i);
                break;
            }
        }
    }

    return error_count;
}

void deallocate_memory(long *long_offsets, int size_long, int *keys, int size_keys, record *records, int size_records, char *log_messages) {
    free(long_offsets);
    free(keys);
    free(records);
    free(log_messages);
}
