// Parse configuration from file with comments and nested structures
void parse_config_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Skip comments
        if (line[0] == '#' || line[0] == '\n') continue;

        // Parse configuration settings
        if (strncmp(line, "port=", 5) == 0) {
            global_config.port = atoi(line + 5);
        } else if (strncmp(line, "max_connections=", 16) == 0) {
            global_config.max_connections = atoi(line + 16);
        } else if (strncmp(line, "log_level=", 10) == 0) {
            char *level = line + 10;
            level[strcspn(level, "\n")] = 0; // Remove newline
            free(global_config.log_level);
            global_config.log_level = strdup(level);
        } else if (strncmp(line, "timeout=", 8) == 0) {
            global_config.timeout = atof(line + 8);
        }
    }

    fclose(file);
}

// Parse configuration from command-line arguments
void parse_command_line_args(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        if (strncmp(argv[i], "--port=", 7) == 0) {
            global_config.port = atoi(argv[i] + 7);
        } else if (strncmp(argv[i], "--max_connections=", 18) == 0) {
            global_config.max_connections = atoi(argv[i] + 18);
        } else if (strncmp(argv[i], "--log_level=", 12) == 0) {
            char *level = argv[i] + 12;
            free(global_config.log_level);
            global_config.log_level = strdup(level);
        } else if (strncmp(argv[i], "--timeout=", 10) == 0) {
            global_config.timeout = atof(argv[i] + 10);
        }
    }
}

// Validate configuration settings
int validate_config(Config *config) {
    if (config->port <= 0 || config->port > 65535) return -1;
    if (config->max_connections <= 0) return -2;
    if (strcmp(config->log_level, "DEBUG") != 0 &&
        strcmp(config->log_level, "INFO") != 0 &&
        strcmp(config->log_level, "WARNING") != 0 &&
        strcmp(config->log_level, "ERROR") != 0) return -3;
    if (config->timeout <= 0.0) return -4;

    // Add more validation rules as needed
    return 0; // Success
}

// Reload configuration settings dynamically
void reload_configuration() {
    pthread_mutex_lock(&config_mutex);

    int validation_result = validate_config(&global_config);
    if (validation_result != 0) {
        fprintf(stderr, "Invalid configuration: %d\n", validation_result);
        pthread_mutex_unlock(&config_mutex);
        return;
    }

    config_version++; // Increment version on successful reload
    notify_server_of_changes();

    pthread_mutex_unlock(&config_mutex);
}

// Save current configuration to a file
