    fprintf(file, "port=%d\n", global_config.port);
    fprintf(file, "max_connections=%d\n", global_config.max_connections);
    fprintf(file, "log_level=%s\n", global_config.log_level);
    fprintf(file, "timeout=%.2f\n", global_config.timeout);
    fprintf(file, "# Version: %d\n", config_version);

    fclose(file);
}

