#include <pthread.h>
#include <string.h>
#include <stdint.h>

#define NUM_RECORDS 1000
#define STRING_KEY_SIZE 256
#define LONG_OFFSET_ARRAY_SIZE 100
#define INT_KEYS_ARRAY_SIZE 100

typedef struct {
    int value;
    char key[STRING_KEY_SIZE];
    long *offset_ptr;
} record;

typedef struct {
    void **blocks;
    size_t block_size;
    size_t total_blocks;
    size_t available_blocks;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t block_size, size_t total_blocks) {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->blocks = (void **)malloc(total_blocks * sizeof(void *));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->available_blocks = total_blocks;

    for (size_t i = 0; i < total_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            while (--i >= 0)
                free(pool->blocks[i]);
            free(pool->blocks);
            free(pool);
            return NULL;
        }
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(memory_pool *pool) {
    if (!pool || pool->available_blocks == 0)
        return NULL;

    pthread_mutex_lock(&pool->lock);

    void *block = pool->blocks[--pool->available_blocks];
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void free_memory_pool(memory_pool *pool) {
    for (size_t i = 0; i < pool->total_blocks; ++i)
        free(pool->blocks[i]);
    free(pool->blocks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

