void resizePreferences(Preference **prefs, size_t *currentSize) {
    pthread_mutex_lock(&prefMutex);

    size_t newSize = (*currentSize == 0 ? INITIAL_SIZE : *currentSize * 2);
    if (newSize > MAX_PREF_COUNT) {
        fprintf(stderr, "Exceeded maximum number of preferences.\n");
        exit(EXIT_FAILURE);
    }

    Preference *newPrefs = realloc(*prefs, newSize * sizeof(Preference));
    if (!newPrefs) {
        perror("Failed to resize preference array");
        pthread_mutex_unlock(&prefMutex);
        exit(EXIT_FAILURE);
    }

    memset(newPrefs + *currentSize, 0, (*currentSize) * sizeof(Preference));
    *prefs = newPrefs;
    *currentSize = newSize;

    pthread_mutex_unlock(&prefMutex);
}

void initializePreferences(Preference **prefs, size_t *count, PreferenceCallback callback) {
    pthread_mutex_lock(&prefMutex);

    if (*count < MIN_PREF_COUNT || *count > MAX_PREF_COUNT) {
        fprintf(stderr, "Invalid preference count.\n");
        exit(EXIT_FAILURE);
    }

    if (!*prefs) {
        *prefs = malloc(INITIAL_SIZE * sizeof(Preference));
        if (!*prefs) {
            perror("Failed to allocate memory for preferences");
            pthread_mutex_unlock(&prefMutex);
            exit(EXIT_FAILURE);
        }
        memset(*prefs, 0, INITIAL_SIZE * sizeof(Preference));
    }

    while (*count > *prefs) {
        resizePreferences(prefs, count);
    }

    for (size_t i = 0; i < *count; ++i) {
        (*prefs)[i].name = "default";
        switch ((*prefs)[i].type = STRING_TYPE) { // Default type
            case STRING_TYPE:
                (*prefs)[i].defaultValue.stringValue = strdup("default");
                break;
            case INTEGER_TYPE:
                (*prefs)[i].defaultValue.intValue = 0;
                break;
            case BOOLEAN_TYPE:
                (*prefs)[i].defaultValue.boolValue = _Bool(0);
                break;
        }

        if (callback) {
            callback(&((*prefs)[i]));
        }
    }

    pthread_mutex_unlock(&prefMutex);
}

void addPreference(Preference **prefs, size_t *count, Preference newPref) {
    pthread_mutex_lock(&prefMutex);

    if (*count == 0 || *count >= MAX_PREF_COUNT) {
        fprintf(stderr, "Cannot add more preferences.\n");
        pthread_mutex_unlock(&prefMutex);
        return;
    }

    while (*count >= *prefs) {
        resizePreferences(prefs, count);
    }

    memcpy(&((*prefs)[*count]), &newPref, sizeof(Preference));
    ++(*count);

    pthread_mutex_unlock(&prefMutex);
}

void resolveAndManagePreferences(size_t minCount, size_t maxCount, PreferenceCallback callback) {
    size_t count = 0;
    Preference *preferences = NULL;

    initializePreferences(&preferences, &count, callback);

