        sscanf(line, "%ms %d %m[^;] %d %m[^;]", &pref.name, &pref.type,
               &pref.defaultValue.stringValue, strlen(pref.defaultValue.stringValue),
               (int *)&pref.currentValue.intValue);

        addPreference(&preferences, &count, pref);
    }

    for (size_t i = 0; i < count; ++i) {
        free(preferences[i].defaultValue.stringValue);
    }

    free(preferences);
