typedef struct MemoryPoolNode {
    size_t size;
    void* memory;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode* head;
    pthread_mutex_t lock;
} MemoryPool;

// External library function prototype for random string generation
void generateRandomString(char* buffer, size_t length, unsigned int seed);

EventProcessingCallback processingCallback = NULL;

MemoryPool* createMemoryPool(size_t blockSize, size_t initialBlocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pthread_mutex_init(&pool->lock, NULL);

    pool->head = NULL;
    for (size_t i = 0; i < initialBlocks; ++i) {
        MemoryPoolNode* node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        node->size = blockSize;
        node->memory = malloc(blockSize);
        node->next = pool->head;
        pool->head = node;
    }

    return pool;
}

void* memoryPoolAlloc(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode** current = &pool->head;
    while (*current) {
        if ((*current)->size >= size) {
            void* memory = *current;
            *current = (*current)->next;
            pthread_mutex_unlock(&pool->lock);
            return memory;
        }
        current = &(*current)->next;
    }

    MemoryPoolNode* node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
    node->size = size > 0 ? size : 1; // Avoid zero-size allocation
    node->memory = malloc(node->size);
    node->next = pool->head;
    pool->head = node;

    pthread_mutex_unlock(&pool->lock);
    return node->memory;
}

void memoryPoolFree(MemoryPool* pool, void* ptr) {
    if (!ptr) return;

    MemoryPoolNode* node = (MemoryPoolNode*)ptr;
    pthread_mutex_lock(&pool->lock);

    node->next = pool->head;
    pool->head = node;

    pthread_mutex_unlock(&pool->lock);
}

void resizeDataStreamArray(Event*** dataStreams, size_t* currentSize) {
    size_t newSize = (*currentSize) * 2;
    *dataStreams = realloc(*dataStreams, newSize * sizeof(Event*));

    for (size_t i = *currentSize; i < newSize; ++i) {
        (*dataStreams)[i] = NULL;
    }

    *currentSize = newSize;
}

void processAndManageDataStreams(unsigned int seed, EventProcessingCallback callback) {
    processingCallback = callback;

    size_t numStreams = MAX_STREAMS_INITIAL;
    Event** dataStreams = (Event**)malloc(numStreams * sizeof(Event*));
