['```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Thread-safe dynamic array implementation
typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    long *timestamps;
    int *keys;
    record *records;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initial_capacity;
    array->count = 0;
    array->timestamps = (long *)malloc(initial_capacity * sizeof(long));
    array->keys = (int *)malloc(initial_capacity * sizeof(int));
    array->records = (record *)malloc(initial_capacity * sizeof(record));
}

void resize_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    size_t new_capacity = array->capacity * 2;
    long *new_timestamps = (long *)realloc(array->timestamps, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(array->keys, new_capacity * sizeof(int));
    record *new_records = (record *)realloc(array->records, new_capacity * sizeof(record));

    if (!new_timestamps || !new_keys || !new_records) {
        perror("Failed to resize dynamic array");
        exit(EXIT_FAILURE);
    }

    array->timestamps = new_timestamps;
    array->keys = new_keys;
    array->records = new_records;
    array->capacity = new_capacity;

    pthread_mutex_unlock(&array->lock);
}

void add_record(DynamicArray *array, long timestamp, int key, record rec) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_dynamic_array(array);
    }

    array->timestamps[array->count] = timestamp;
    array->keys[array->count] = key;
    array->records[array->count] = rec;

    array->count++;
    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->timestamps);
    free(array->keys);
    free(array->records);
}

typedef void (*record_callback)(long timestamp, int key, record rec);

void processStreamOfRecords(record_callback callback) {
    DynamicArray array;
    init_dynamic_array(&array, 10); // Initial capacity

    FILE *input_stream = fopen("input.txt", "r"); // Simulated non-blocking input stream
    if (!input_stream) {
        perror("Failed to open input stream");
        exit(EXIT_FAILURE);
    }

    while (1) { // Continuously read from the input stream
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), input_stream) == NULL) break;

        long timestamp;
        int key, value;

        if (sscanf(buffer, "%ld %d", &timestamp, &key) != 2) continue; // Skip malformed inputs

        record rec;
        srand(time(NULL)); // Seed the random number generator
        value = rand() % 1000; // Random value in range [0, 999]
        rec.value = value;

        add_record(&array, timestamp, key, rec);

        if (callback) {
            callback(timestamp, key, rec);
        }
    }

    fclose(input_stream);

    free_dynamic_array(&array);
}

void example_callback(long timestamp, int key, record rec) {
    printf("Timestamp: %ld, Key: %d, Value: %d\n", timestamp, key, rec.value);
}

int main() {
    processStreamOfRecords(example_callback);
    return 0;
}
```

