    size_t blockSize;
    size_t blockCount;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void *memory_pool_alloc(MemoryPool *pool);
void memory_pool_free(MemoryPool *pool, void *ptr);
char *generate_random_string(size_t length, unsigned long seed);

