HostnameCache hostname_cache = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER};
MemoryPool dataStreamPool = {NULL, sizeof(Event*), 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize memory pool
void init_memory_pool(MemoryPool *pool, size_t blockSize, size_t initialBlocks) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->blockSize = blockSize;
    pool->blockCount = initialBlocks;
    pool->pool = malloc(pool->blockSize * pool->blockCount);
}

// Function to allocate memory from the pool
void *memory_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (!pool->pool) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void *ptr = pool->pool;
    pool->pool += pool->blockSize;
    pool->blockCount--;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to free the memory pool
void memory_pool_free(MemoryPool *pool, void *) {
    // Pool is not actually freed per allocation; it's a simple example.
    pthread_mutex_lock(&pool->lock);
    pool->blockCount += (char *)pool->pool - (char *)(void *)pool;
    pthread_mutex_unlock(&pool->lock);
}

// Function to generate random strings
char *generate_random_string(size_t length, unsigned long seed) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char *randomString = malloc(length + 1);

    srand(seed);
    for (size_t i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        randomString[i] = charset[key];
    }
    randomString[length] = '\0';

    return randomString;
}

// Function to resolve hostname
int resolve_hostname(const char *hostname, char *ipAddress) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        strcpy(ipAddress, inet_ntoa(ipv4->sin_addr));
        break;
    }

    freeaddrinfo(res);
    return 0;
}

// Callback function for processing events
void process_event(Event *event) {
    // Example processing logic
    printf("Processing event with timestamp %d\n", event->timestamp);
}

// Main function to handle data streams and transactions
void processDataStreamsAndTransactions(int numStreams, int numTransactionsPerStream, unsigned long seed) {
    pthread_t threads[numStreams];
    Transaction *transactions = malloc(numStreams * sizeof(Transaction));

    for (int i = 0; i < numStreams; i++) {
        transactions[i].events = calloc(numTransactionsPerStream, sizeof(Event *));

        for (int j = 0; j < numTransactionsPerStream; j++) {
            Event *event = malloc(sizeof(Event));
            event->timestamp = j;
            event->dataPayload = generate_random_string(10, seed + i * numTransactionsPerStream + j);
            event->metadataFlags = rand() % 256;

            transactions[i].events[j] = event;

            // Process the event
            process_event(event);
        }

        transactions[i].eventCount = numTransactionsPerStream;
    }

    // Free allocated resources
    for (int i = 0; i < numStreams; i++) {
        for (int j = 0; j < transactions[i].eventCount; j++) {
            free(transactions[i].events[j]->dataPayload);
            free(transactions[i].events[j]);
        }
        free(transactions[i].events);
    }

    free(transactions);
}
