#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STREAMS 1000
#define DATA_PAYLOAD_LENGTH 16
#define RECORD_COUNT 100

typedef struct {
    long timestamp;
    char data_payload[DATA_PAYLOAD_LENGTH + 1];
    int metadata_flags;
} Event;

typedef struct {
    long offset;
    int key;
} Record;

// Memory pool for events
typedef struct {
    size_t block_size;
    size_t capacity;
    void *blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Callback function prototype
typedef void (*EventCallback)(Event *);

// Initialize memory pool
void initMemoryPool(MemoryPool *pool, size_t block_size, size_t initial_capacity) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->capacity = initial_capacity;
    pool->blocks = malloc(block_size * initial_capacity);
}

// Allocate memory from pool
void* allocateFromPool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->blocks || (char*)pool->blocks + (pool->block_size * pool->capacity) == sbrk(0)) {
        size_t new_capacity = pool->capacity * 2;
        char *new_blocks = realloc(pool->blocks, pool->block_size * new_capacity);
        if (!new_blocks) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->blocks = new_blocks;
        pool->capacity = new_capacity;
    }

    void *block = (char*)pool->blocks + (pool->capacity - 1) * pool->block_size;
    pool->capacity--;

    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Free the memory pool
void freeMemoryPool(MemoryPool *pool) {
    if (pool->blocks) {
        free(pool->blocks);
    }
    pthread_mutex_destroy(&pool->lock);
}

// Random string generator using an external library (e.g., OpenSSL)
void generateRandomString(char* buffer, size_t length, unsigned int seed) {
    srand(seed ^ time(NULL));
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (size_t i = 0; i < length; i++) {
        size_t index = rand() % (sizeof(charset) - 1);
        buffer[i] = charset[index];
    }
    buffer[length] = '\0';
}

// Data stream processor
void dataStreamProcessor(unsigned int seed, EventCallback callback) {
    MemoryPool eventPool;
    initMemoryPool(&eventPool, sizeof(Event), 100);

    // Array of pointers to events (data streams)
    Event **streams[MAX_STREAMS];
    size_t num_streams = 0;

    // Record array
    Record *records[RECORD_COUNT];

    for (size_t i = 0; i < RECORD_COUNT; ++i) {
        records[i] = allocateFromPool(&eventPool);
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for record %zu\n", i);
            break;
        }
        records[i]->offset = i * sizeof(Record);
        records[i]->key = rand() % 1000; // Random key between 0 and 999
    }

    while (num_streams < MAX_STREAMS) {
        Event *event = allocateFromPool(&eventPool);
        if (!event) break;

        event->timestamp = num_streams++;
        generateRandomString(event->data_payload, DATA_PAYLOAD_LENGTH, seed);
        event->metadata_flags = rand() % 2; // Random flag

        callback(event);

        streams[num_streams - 1] = &event;
    }

    freeMemoryPool(&eventPool);

    for (size_t i = 0; i < num_streams; ++i) {
        free(streams[i]);
    }
}

// Example event processing callback
void processEvent(Event *event) {
    printf("Processing Event: Timestamp=%ld, Data=%s, Flags=%d\n",
           event->timestamp,
           event->data_payload,
           event->metadata_flags);
}

int main() {
    dataStreamProcessor(12345, processEvent);
    return 0;
}
