    int uniqueKey;
    Data data;
} Record;

// Global synchronization mechanisms
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeValue(Value *value, float number, const char *string) {
    value->number = number;
    strncpy(value->string, string, sizeof(value->string));
}

// Function to allocate and initialize structures
void allocateAndInitializeDataStructures(Record **records,
                                         Entry **entries,
                                         LogEntry **logs) {
    if (pthread_mutex_lock(&lock)) return;

    // Allocate records array
    *records = malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize each record with default values and data structures
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        (*records)[i].uniqueKey = rand() % 100000;

        // Allocate space for elements dynamically based on use case
        size_t elementCount = 10;
        (*records)[i].data.elements = malloc(elementCount * sizeof(Element));
        if ((*records)[i].data.elements == NULL) {
            fprintf(stderr, "Failed to allocate memory for elements\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        (*records)[i].data.elementCount = elementCount;

        // Initialize each element
        for (size_t j = 0; j < elementCount; ++j) {
            Element *element = &(*records)[i].data.elements[j];
            element->index = j;

            Value *value = malloc(sizeof(Value));
            if (value == NULL) {
                fprintf(stderr, "Failed to allocate memory for value\n");
                pthread_mutex_unlock(&lock);
                return;
            }
            initializeValue(value, 0.0f, "default");

            element->valuePtr = value;
        }
    }

    // Allocate entries array
    *entries = malloc(MAX_ENTRIES * sizeof(Entry));
    if (*entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize each entry
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        (*entries)[i].id = rand() % 100000;
        (*entries)[i].timestamp = time(NULL);

        int keyCount = 5;
        (*entries)[i].key_count = keyCount;

        (*entries)[i].keys = malloc(keyCount * sizeof(int));
        if ((*entries)[i].keys == NULL) {
            fprintf(stderr, "Failed to allocate memory for keys\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        for (int j = 0; j < keyCount; ++j) {
            (*entries)[i].keys[j] = rand() % 10000;
        }

        (*entries)[i].values = malloc(keyCount * sizeof(Value *));
        if ((*entries)[i].values == NULL) {
            fprintf(stderr, "Failed to allocate memory for values\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        // Initialize each value
        for (int j = 0; j < keyCount; ++j) {
            Value *value = malloc(sizeof(Value));
            if (value == NULL) {
                fprintf(stderr, "Failed to allocate memory for value\n");
                pthread_mutex_unlock(&lock);
                return;
            }
            initializeValue(value, 1.23f, "example");

            (*entries)[i].values[j] = value;
        }
    }

    // Allocate logs array
    *logs = malloc(MAX_ENTRIES * sizeof(LogEntry));
    if (*logs == NULL) {
        fprintf(stderr, "Failed to allocate memory for logs\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize each log entry with default operations and timestamps
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        strncpy((*logs)[i].operation, "insert", sizeof((*logs)[i].operation));
        (*logs)[i].recordId = rand() % MAX_RECORDS;
        (*logs)[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&lock);

    // For demonstration purposes: logging external service simulation
    printf("Data structures initialized and ready for use.\n");
}

// Example usage of the function (main function)
int main() {
    Record *records = NULL;
    Entry *entries = NULL;
    LogEntry *logs = NULL;

    allocateAndInitializeDataStructures(&records, &entries, &logs);

    // Simulate freeing resources
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        for (size_t j = 0; j < records[i].data.elementCount; ++j) {
            free(records[i].data.elements[j].valuePtr);
        }
        free(records[i].data.elements);
    }
    free(records);

    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        free(entries[i].keys);
        for (int j = 0; j < entries[i].key_count; ++j) {
            free(entries[i].values[j]);
        }
        free(entries[i].values);
    }
    free(entries);

    free(logs);

    return 0;
}
