    int log_id;
    time_t timestamp;
    KeyValue kv_pairs[10]; // Assume a fixed size for simplicity
} Log;

typedef struct {
    Record *records;
    int record_count;
    int record_capacity;
    pthread_mutex_t lock;
} DatabaseManager;

void initializeDatabase(DatabaseManager *db, unsigned int seed) {
    pthread_mutex_init(&db->lock, NULL);
    db->record_count = 0;
    db->record_capacity = MIN_CAPACITY;
    db->records = (Record *)malloc(db->record_capacity * sizeof(Record));

    srand(seed);
    for (int i = 0; i < db->record_capacity; ++i) {
        db->records[i].data.elements[0].index = i;
        db->records[i].data.elements[0].value_ptr = malloc(sizeof(Value));
        db->records[i].data.elements[0].value_ptr->value = rand() % 100.0f;
        snprintf(db->records[i].data.elements[0].value_ptr->name, sizeof(db->records[i].data.elements[0].value_ptr->name), "Value_%d", i);
    }
}

void addRecord(DatabaseManager *db, Record new_record) {
    pthread_mutex_lock(&db->lock);

    if (db->record_count == db->record_capacity) {
        int new_capacity = db->record_capacity * 2;
        if (new_capacity > MAX_CAPACITY) new_capacity = MAX_CAPACITY;

        Record *temp_records = realloc(db->records, new_capacity * sizeof(Record));
        if (!temp_records) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&db->lock);
            return;
        }

        db->records = temp_records;
        db->record_capacity = new_capacity;
    }

    db->records[db->record_count++] = new_record;

    pthread_mutex_unlock(&db->lock);
}

void freeDatabase(DatabaseManager *db) {
    for (int i = 0; i < db->record_count; ++i) {
        free(db->records[i].data.elements[0].value_ptr);
    }
    free(db->records);
    pthread_mutex_destroy(&db->lock);
}

