#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "secure_random_lib.h" // Placeholder for a library providing secure RNG

typedef struct {
    int transactionID;
    time_t timestamp;
    double amount;
    char category[50];
    char status[20];
} Transaction;

typedef void (*TransactionCallback)(const Transaction*);

typedef struct {
    Transaction* transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TransactionPool;

// Helper functions prototypes
void resizeTransactionPool(TransactionPool* pool, size_t newCapacity);
void freeTransactionPool(TransactionPool* pool);

// The main function to process and aggregate transaction stats
void processTransactionsAndAggregateStats(size_t initialCapacity, TransactionCallback callback) {
    if (initialCapacity == 0) return;

    pthread_mutex_init(&pool.lock, NULL);

    TransactionPool pool = {NULL, initialCapacity, 0};
    pool.transactions = malloc(initialCapacity * sizeof(Transaction));
    if (!pool.transactions) {
        perror("Failed to allocate memory for transactions");
        pthread_mutex_destroy(&pool.lock);
        return;
    }

    // Simulate reading and processing concurrent data sources
    for (size_t i = 0; i < 100; ++i) { // Assume we have 100 transactions
        if (pool.count >= pool.capacity) {
            resizeTransactionPool(&pool, pool.capacity * 2);
        }

        Transaction* transaction = &pool.transactions[pool.count];
        secure_random_generate(&transaction->transactionID); // Secure RNG library call
        transaction->timestamp = time(NULL);
        transaction->amount = (double)secure_random_generate() / RAND_MAX * 1000.0;
        snprintf(transaction->category, sizeof(transaction->category), "Category %zu", i % 10);
        snprintf(transaction->status, sizeof(transaction->status), "Status %zu", i % 5);

        if (callback) {
            callback(*transaction);
        }

        pthread_mutex_lock(&pool.lock);
        pool.count++;
        pthread_mutex_unlock(&pool.lock);
    }

    double totalAmount = 0.0;
    double highestTransaction = 0.0;

    pthread_mutex_lock(&pool.lock);
    for (size_t i = 0; i < pool.count; ++i) {
        totalAmount += pool.transactions[i].amount;
        if (pool.transactions[i].amount > highestTransaction) {
            highestTransaction = pool.transactions[i].amount;
        }
    }
    pthread_mutex_unlock(&pool.lock);

    double averageValue = totalAmount / pool.count;

    printf("Total Amount: %.2f\n", totalAmount);
    printf("Average Transaction Value: %.2f\n", averageValue);
    printf("Highest Transaction Amount: %.2f\n", highestTransaction);

    freeTransactionPool(&pool.transactions);
    pthread_mutex_destroy(&pool.lock);
}

// Resize the transaction pool
void resizeTransactionPool(TransactionPool* pool, size_t newCapacity) {
    Transaction* resized = realloc(pool->transactions, newCapacity * sizeof(Transaction));
    if (!resized) {
        perror("Failed to reallocate memory for transactions");
        exit(EXIT_FAILURE); // Or handle error more gracefully
    }
    pool->transactions = resized;
    pool->capacity = newCapacity;
}

// Free all allocated resources in the transaction pool
void freeTransactionPool(Transaction* transactions) {
    if (transactions) {
        free(transactions);
    }
}
