    fwrite(&size, sizeof(size_t), 1, file);
    fwrite(offsets, sizeof(int), size, file);
    for (size_t i = 0; i < size; ++i) {
        size_t len = strlen(keys[i]) + 1;
        fwrite(&len, sizeof(len), 1, file);
        fwrite(keys[i], sizeof(char), len, file);
    }
    fwrite(timestamps, sizeof(long long), size, file);
    fwrite(statuses, sizeof(short), size, file);

    for (size_t i = 0; i < size; ++i) {
        Record *record = records[i];
        int len = strlen(record->key) + 1;
        fwrite(&len, sizeof(len), 1, file);
        fwrite(record->key, sizeof(char), len, file);
        fwrite(&(record->value), sizeof(int), 1, file);
        if (record->long_ptr) {
            long *ptr_val = record->long_ptr;
            fwrite(ptr_val, sizeof(long), 1, file);
        } else {
            long null_val = 0;
            fwrite(&null_val, sizeof(long), 1, file);
        }
        fwrite(&(record->numerical_value), sizeof(double), 1, file);
        fwrite(&(record->data_type), sizeof(short), 1, file);
    }

    fclose(file);
    return 0;
}

// Function to manage the lifecycle of the data structure
