    char **keys;
    long long *timestamps;
    short *statuses;
    Record **records;

    if (initialize_arrays(size, &offsets, &keys, &timestamps, &statuses, &records)) {
        dlclose(random_lib_handle);
        return -1;
    }

    if (populate_records(size, min_val, max_val, random_lib_handle, rand_func_name, seed)) {
        cleanup_resources(offsets, keys, timestamps, statuses, records, size);
        dlclose(random_lib_handle);
        return -1;
    }

    process_records(size, records, processor);

    // Example serialization (adjust path as needed)
