typedef struct {
    int count;
    double sum;
    double average;
    double max;
} Stats;

typedef struct {
    int value;
    long *dynamicVar;
    double numericalValue;
    short dataType;
    Stats stats;
} Record;

// Custom deleter for Record
void recordDeleter(Record *record) {
    if (record->dynamicVar) {
        free(record->dynamicVar);
    }
}

// Aggregates statistics from records
void aggregateStats(Record *records, int size) {
    double sum = 0;
    double max = -INFINITY;
    for (int i = 0; i < size; ++i) {
        sum += records[i].numericalValue;
        if (records[i].numericalValue > max) {
            max = records[i].numericalValue;
        }
    }
    double average = size ? sum / size : 0;

    for (int i = 0; i < size; ++i) {
        records[i].stats.count = 1;
        records[i].stats.sum = records[i].numericalValue;
        records[i].stats.average = average;
        records[i].stats.max = max;
    }
}

// Callback function type
typedef void (*ProcessCallback)(Record *);

void initializeAndProcessRecords(int recordSize, int minVal, int maxVal, unsigned long seed, time_t startTimestamp, ProcessCallback processFunc) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int *offset = (int *)malloc(recordSize * sizeof(int));
    int *key = (int *)malloc(recordSize * sizeof(int));
    time_t *timestamp = (time_t *)malloc(recordSize * sizeof(time_t));
    int *status = (int *)calloc(recordSize, sizeof(int));

    if (!offset || !key || !timestamp || !status) {
        free(offset);
        free(key);
        free(timestamp);
        free(status);
        printf("Memory allocation failed.\n");
        return;
    }

    srand(seed);
    Record *records = (Record *)malloc(recordSize * sizeof(Record));
    if (!records) {
        free(offset);
        free(key);
        free(timestamp);
        free(status);
        printf("Memory allocation for records failed.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    for (int i = 0; i < recordSize; ++i) {
        offset[i] = i;
        key[i] = i;
        timestamp[i] = startTimestamp + i;

        records[i].value = minVal + rand() % (maxVal - minVal + 1);
        records[i].dynamicVar = malloc(sizeof(long));
        if (!records[i].dynamicVar) {
            printf("Memory allocation for dynamicVar failed.\n");
            status[i] = -1;
            continue;
        }
        *(records[i].dynamicVar) = rand();
        records[i].numericalValue = (double)(rand() % 100);
        records[i].dataType = rand() % 10;

        if (processFunc) {
            processFunc(&records[i]);
        }

        status[i] = 0; // Success
    }

    aggregateStats(records, recordSize);

    pthread_mutex_unlock(&lock);

    for (int i = 0; i < recordSize; ++i) {
        if (status[i] == 0) {
            recordDeleter(&records[i]);
        }
    }

    free(offset);
    free(key);
    free(timestamp);
    free(status);
    free(records);

    pthread_mutex_destroy(&lock);
}
