    size_t current_size = 0;
    int retries = 0;

    while (current_size < count && retries < MAX_RETRIES) {
        if (!records)
            records = malloc(INITIAL_SIZE * sizeof(Record));
        else
            records = realloc(records, (current_size + INITIAL_SIZE) * sizeof(Record));

        if (!records) {
            log_performance("Memory allocation failed");
            retries++;
            continue;
