            records[i].value = secure_rand(min_val, max_val);
            callback_function(&records[i]);
            pthread_mutex_unlock(&mutex);
        }
        current_size += INITIAL_SIZE;
    }

    if (current_size < count) {
        free(records);
        log_performance("Failed to allocate all requested records");
        return NULL;
    }

    return records;
}

void free_records(Record *records) {
    free(records);
}

int allocateInitializeAndProcessRecords(int **offset, int **key, size_t offset_size, size_t key_size,
                                        Record ***record_array, size_t record_count, int min_val, int max_val) {

    if (!resize_array(*offset, 0, offset_size)) return -1;
    if (!resize_array(*key, 0, key_size)) return -2;

    *record_array = allocate_records(record_count, min_val, max_val);
    if (*record_array == NULL) return -3;

    log_performance("Memory allocation and initialization completed successfully");

    // Process records here (e.g., find the maximum value)
    int max_value = (*record_array)[0].value;
    for (size_t i = 1; i < record_count; ++i) {
        if ((*record_array)[i].value > max_value) {
            max_value = (*record_array)[i].value;
        }
    }

    printf("Maximum value: %d\n", max_value);

    return 0;
}
```

