#define MAX_RECORDS 1000

record* record_store = NULL;
size_t records_count = 0;
pthread_mutex_t store_mutex = PTHREAD_MUTEX_INITIALIZER;

// Callback function type definition
typedef void (*record_callback)(record*);

// Initialize the record store with specified size and seed for timestamps
int initialize_record_store(size_t size, time_t timestamp_seed, record_callback callback) {
    if (size > MAX_RECORDS || records_count != 0) return -1; // Prevent overflow or reinitialization

    pthread_mutex_lock(&store_mutex);

    record_store = (record*)malloc(sizeof(record) * size);
    if (!record_store) {
        perror("Failed to allocate memory for record store");
        pthread_mutex_unlock(&store_mutex);
        return -1;
    }

    records_count = size;

    // Seed the random number generator for consistent timestamps
    srand((unsigned int)timestamp_seed);

    for (size_t i = 0; i < size; ++i) {
        record_store[i].key = i;
        record_store[i].timestamp = timestamp_seed + rand() % 10000; // Example: Add a random offset

        // Allocate memory for the metric data
        record_store[i].value = (long*)malloc(sizeof(long));
        if (!record_store[i].value) {
            perror("Failed to allocate memory for metric value");
            pthread_mutex_unlock(&store_mutex);
            return -1;
        }

        *record_store[i].value = rand(); // Initialize with random data

        if (callback != NULL) {
            callback(&record_store[i]);
        }
    }

    pthread_mutex_unlock(&store_mutex);
    return 0;
}

// Example of a callback function
void example_callback(record* rec) {
    printf("Record initialized: Key=%d, Timestamp=%ld, Value=%ld\n", 
           rec->key, rec->timestamp, *(rec->value));
}

// Export records to a file in JSON format
int export_records_to_json(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&store_mutex);

    fprintf(file, "[\n");

    for (size_t i = 0; i < records_count; ++i) {
        if (i > 0) fprintf(file, ",\n");
        fprintf(file, "  { \"key\": %d, \"timestamp\": %ld, \"value\": %ld }", 
                record_store[i].key, record_store[i].timestamp, *(record_store[i].value));
    }

    fprintf(file, "\n]");

    pthread_mutex_unlock(&store_mutex);
    fclose(file);

    return 0;
}

// Free allocated resources
void free_record_store() {
    if (record_store == NULL) return;

    pthread_mutex_lock(&store_mutex);

    for (size_t i = 0; i < records_count; ++i) {
        free(record_store[i].value);
    }

    free(record_store);
    record_store = NULL;
    records_count = 0;

    pthread_mutex_unlock(&store_mutex);
}

// Dummy function to simulate interaction with an external service
void interact_with_external_service() {
    // Simulate processing or network latency
}

int main() {
    if (initialize_record_store(100, time(NULL), example_callback) == 0) {
        export_records_to_json("records.json");
        free_record_store();
    }

    return 0;
}
