['Below is an implementation of the described C function. It uses POSIX threads and locks for thread safety, and it assumes availability of external libraries for secure random number generation and logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Placeholder includes for external dependencies
#include "secure_random.h"  // Assume this library provides a function: int secure_rand(int min, int max);
#include "logger.h"         // Assume logging functions are provided here.

typedef struct {
    int value;
    char key[256];
    long *shared_long_ptr;
    time_t timestamp;
} record;

#define MAX_RECORDS 1000

// Global lock for thread safety
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void log_initialization(const char *message) {
    // Placeholder logging function, replace with actual logger calls.
    printf("LOG: %s\n", message);
}

long *allocate_shared_long() {
    long *ptr = (long *)malloc(sizeof(long));
    if (!ptr) {
        perror("Failed to allocate shared long");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_resources(long **offsets, int *keys, record **records, size_t num_records) {
    pthread_mutex_lock(&memory_lock);

    free(*offsets);
    free(*keys);
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]->shared_long_ptr == NULL) {
            records[i]->shared_long_ptr = allocate_shared_long(); // Reuse allocation on failure
        }
        free(records[i]->key);
        free(records[i]);
    }

    free(*records);
    pthread_mutex_unlock(&memory_lock);
}

int is_key_duplicate(const char *key, record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (strcmp(key, records[i]->key) == 0) {
            return 1;
        }
    }
    return 0;
}

void initialize_memory(size_t array_size, size_t record_count, int allow_duplicates,
                       long seed, void (*callback)(record *), const char *file_format) {
    pthread_mutex_lock(&memory_lock);

    // Allocate and initialize offset values and keys
    long *offsets = (long *)malloc(array_size * sizeof(long));
    int *keys = (int *)malloc(array_size * sizeof(int));

    if (!offsets || !keys) {
        perror("Failed to allocate memory for offsets or keys");
        free_resources(&offsets, &keys, NULL, 0);
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    for (size_t i = 0; i < array_size; ++i) {
        offsets[i] = (long)i;
        keys[i] = (int)i;
    }

    // Allocate records
    record *records = (record *)malloc(record_count * sizeof(record));

    if (!records) {
        perror("Failed to allocate memory for records");
        free_resources(&offsets, &keys, NULL, 0);
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    srand48(seed);

    // Initialize each record
    long *shared_long = allocate_shared_long();

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = secure_rand(1, 100); // Example range
        snprintf(records[i].key, sizeof(records[i].key), "key_%zu", i);

        if (!allow_duplicates && is_key_duplicate(records[i].key, records, i)) {
            fprintf(stderr, "Duplicate key found: %s\n", records[i].key);
            continue;
        }

        records[i].shared_long_ptr = shared_long;
        records[i].timestamp = time(NULL);

        log_initialization(records[i].key);

        if (callback) {
            callback(&records[i]);
        }
    }

    // Export to file if needed
    if (file_format && strcmp(file_format, "JSON") == 0) {
        FILE *f = fopen("output.json", "w");
        if (f) {
            fprintf(f, "[\n");
            for (size_t i = 0; i < record_count; ++i) {
                fprintf(f, "\t{\"value\": %d, \"key\": \"%s\", \"timestamp\": %ld}%s\n",
                        records[i].value, records[i].key, records[i].timestamp,
                        (i == record_count - 1) ? "" : ",");
            }
            fprintf(f, "]\n");
            fclose(f);
        }
    }

    // Free allocated resources
    free_resources(&offsets, &keys, &records, record_count);

    pthread_mutex_unlock(&memory_lock);
}
