    int port;
    time_t last_activity;
} node;

typedef struct {
    int value;
} record;

typedef struct request {
    int id;
    struct request *next;
} request;

void callback_node(node *n) {}
void callback_request(request *r) {}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

node* resize_nodes(node *nodes, size_t current_size, size_t new_size) {
    node *new_nodes = realloc(nodes, new_size * sizeof(node));
    if (!new_nodes) return NULL;
    memset(new_nodes + current_size, 0, (new_size - current_size) * sizeof(node));
    return new_nodes;
}

record* resize_records(record *records, size_t current_size, size_t new_size) {
    record *new_records = realloc(records, new_size * sizeof(record));
    if (!new_records) return NULL;
    memset(new_records + current_size, 0, (new_size - current_size) * sizeof(record));
    return new_records;
}

request* resize_requests(request **head, size_t current_size, size_t new_size) {
    request *new_head = realloc(*head, new_size * sizeof(request));
    if (!new_head) return NULL;
    for (size_t i = current_size; i < new_size - 1; i++) {
        new_head[i].next = &new_head[i + 1];
    }
    new_head[new_size - 1].next = NULL;
    *head = new_head;
    return new_head;
}

void dynamicNetworkManager(size_t node_count, size_t request_count) {
    pthread_mutex_lock(&lock);

    long *offsets = malloc(10 * sizeof(long));
    int *keys = malloc(10 * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    for (size_t i = 0; i < 10; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    size_t initial_node_size = node_count > 0 ? node_count : 5;
    size_t initial_request_size = request_count > 0 ? request_count : 5;

    node *nodes = malloc(initial_node_size * sizeof(node));
    record *records = malloc(initial_node_size * sizeof(record));
    request *requests = malloc(initial_request_size * sizeof(request));

    if (!nodes || !records || !requests) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return;
    }

    srand(time(NULL));

    for (size_t i = 0; i < initial_node_size; ++i) {
        snprintf(nodes[i].ip, sizeof(nodes[i].ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        nodes[i].port = rand() % (65536 - 1024) + 1024;
        nodes[i].last_activity = time(NULL);
        callback_node(&nodes[i]);
    }

    for (size_t i = 0; i < initial_node_size; ++i) {
        records[i].value = rand() % 100;
    }

    size_t request_index = 0;
    requests[request_index++].id = 1;

    int input_value, index = 0;
    size_t input_capacity = 10;
    int *input_array = malloc(input_capacity * sizeof(int));

    if (!input_array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    while (scanf("%d", &input_value) == 1 && input_value != -1) {
        if (index >= input_capacity) {
            input_capacity *= 2;
            int *new_array = realloc(input_array, input_capacity * sizeof(int));
            if (!new_array) break;
            input_array = new_array;
        }
        input_array[index++] = input_value;
    }

    printf("Input integers: ");
    for (size_t i = 0; i < index; ++i) {
        printf("%d ", input_array[i]);
    }
    printf("\n");

    free(input_array);
    free(offsets);
    free(keys);

    pthread_mutex_unlock(&lock);
}
