#define MAX_RECORDS 1000

typedef struct {
    int value;
    long *offset_ptr;
} record;

static int allocation_count = 0;
static int deallocation_count = 0;

int allocate_memory(int num_records, long **offset_array, int **key_array, record **record_array) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Requested more records than allowed maximum of %d.\n", MAX_RECORDS);
        return -1;
    }

    // Allocate memory for offset array
    *offset_array = malloc(100 * sizeof(long));
    if (*offset_array == NULL) goto cleanup;

    allocation_count++;

    // Initialize long offset array with random values between -1000 and 1000
    srand((unsigned int)time(NULL)); // Seed the random number generator
    for (int i = 0; i < 100; ++i) {
        (*offset_array)[i] = rand() % 2001 - 1000;
    }

    // Allocate memory for key array and populate with unique values between 1 and 500
    *key_array = malloc(50 * sizeof(int));
    if (*key_array == NULL) goto cleanup;

    allocation_count++;

    int used_keys[501] = {0}; // Track usage of keys to ensure uniqueness
    int keys_assigned = 0;
    while (keys_assigned < 50) {
        int key = rand() % 500 + 1; 
        if (!used_keys[key]) {
            (*key_array)[keys_assigned++] = key;
            used_keys[key] = 1;
        }
    }

    // Sort the keys for efficient retrieval
    qsort(*key_array, 50, sizeof(int), (int(*)(const void*, const void*))strcmp);

    // Allocate memory for record array and initialize values
    *record_array = malloc(num_records * sizeof(record));
    if (*record_array == NULL) goto cleanup;

    allocation_count++;

    for (int i = 0; i < num_records; ++i) {
        (*record_array)[i].value = rand() % 1000 + 1;
        (*record_array)[i].offset_ptr = &((*offset_array)[rand() % 100]);
    }

    return 0;

cleanup:
    // Free any allocated memory in case of an error
    if (*offset_array) {
        free(*offset_array);
        allocation_count--;
    }
    if (*key_array) {
        free(*key_array);
        allocation_count--;
    }
    if (*record_array) {
        free(*record_array);
        allocation_count--;
    }

    deallocation_count += (allocation_count > 0);

    return -1;
}

void free_memory(long *offset_array, int *key_array, record *record_array) {
    if (offset_array) {
        free(offset_array);
        deallocation_count++;
    }
    if (key_array) {
        free(key_array);
        deallocation_count++;
    }
    if (record_array) {
        free(record_array);
        deallocation_count++;
    }
}

int main() {
    long *offset_array = NULL;
    int *key_array = NULL;
    record *record_array = NULL;

    // Example allocation
    if (allocate_memory(500, &offset_array, &key_array, &record_array) == 0) {
        printf("Memory allocated successfully.\n");

        // Use the data structures...

        free_memory(offset_array, key_array, record_array);
    } else {
        fprintf(stderr, "Failed to allocate memory.\n");
    }

    printf("Allocations: %d\n", allocation_count);
    printf("Dealocations: %d\n", deallocation_count);

    return 0;
}
