int generateSecureRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function prototype for the callback function
typedef void (*FileInitCallback)(fileNode*);

void* resizeArray(void* array, size_t currentSize, size_t newSize, size_t elementSize);

void distributedStorageManager(int offsetSize, int keySize, int minFiles, int maxFiles,
                              int fileStatusMin, int fileStatusMax, FileInitCallback callback) {
    // Mutex for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    if (!offsets) exit(EXIT_FAILURE);

    int* keys = (int*)malloc(keySize * sizeof(int));
    if (!keys) {
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize offset and key arrays
    for (int i = 0; i < offsetSize; ++i) offsets[i] = i;
    for (int i = 0; i < keySize; ++i) keys[i] = i;

    int numFiles = generateSecureRandom(minFiles, maxFiles);

    fileNode* files = NULL;
    fileRecord* records = NULL;

    pthread_mutex_lock(&lock);
    files = (fileNode*)malloc(numFiles * sizeof(fileNode));
    if (!files) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }
    records = (fileRecord*)malloc(numFiles * sizeof(fileRecord));
    if (!records) {
        free(files);
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&lock);

    // Initialize fileNode and fileRecord arrays
    for (int i = 0; i < numFiles; ++i) {
        files[i].fileID = i;
        snprintf(files[i].path, sizeof(files[i].path), "/file%d", i);
        files[i].size = generateSecureRandom(1024, 1048576); // 1KB to 1MB
        files[i].modTime = time(NULL);
        files[i].refCount = 0;

        records[i].status = generateSecureRandom(fileStatusMin, fileStatusMax);

        if (callback) {
            callback(&files[i]);
        }
    }

    // Read integers from standard input and store them in a dynamically resizable array
    int* numbers = NULL;
    size_t numSize = 0;

    printf("Enter integers (end with EOF): ");

    while (1) {
        int number;
        if (scanf("%d", &number) != 1) break; // Break on invalid input or EOF

        pthread_mutex_lock(&lock);
        numbers = resizeArray(numbers, numSize, numSize + 1, sizeof(int));
        if (!numbers) {
            fprintf(stderr, "Memory allocation failed\n");
            free(files);
            free(records);
            free(offsets);
            free(keys);
            pthread_mutex_unlock(&lock);
            exit(EXIT_FAILURE);
        }
        numbers[numSize++] = number;
        pthread_mutex_unlock(&lock);
    }

    // Cleanup
    free(numbers);
    free(files);
    free(records);
    free(offsets);
    free(keys);
    pthread_mutex_destroy(&lock);
}

void* resizeArray(void* array, size_t currentSize, size_t newSize, size_t elementSize) {
    void* newArray = realloc(array, newSize * elementSize);
    if (!newArray && newSize > 0) return NULL;
    return newArray;
}
