    int port;
    time_t last_activity;
} node;

typedef struct {
    long offset;
    int key;
    double value;
    int reference_count;
} record;

typedef struct request {
    struct request* next;
    // Additional request fields
} request;

typedef struct {
    int size;
    int capacity;
    record** records;  // Dynamic array of pointers for efficient resizing and access.
    int* keys_used;    // Hash map to track used keys (simple integer index map).
} RecordManager;

RecordManager* initRecordManager(int initial_capacity) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->records = calloc(initial_capacity, sizeof(record*)); // Array of pointers.
    manager->keys_used = calloc(MAX_KEY_SIZE, sizeof(int)); // Simple hash map for key existence.

    if (!manager->records || !manager->keys_used) {
        free(manager);
        return NULL;
    }

    return manager;
}

void freeRecordManager(RecordManager* manager) {
    if (manager) {
        for (int i = 0; i < manager->size; ++i) {
            free(manager->records[i]);
        }
        free(manager->records);
        free(manager->keys_used);
        free(manager);
    }
}

int addRecord(RecordManager* manager, long offset, int key, double value) {
    if (manager->keys_used[key]) return 0; // Key already used.

    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->records = realloc(manager->records, manager->capacity * sizeof(record*));
        if (!manager->records) return -1;
    }

    record* new_record = malloc(sizeof(record));
    if (!new_record) return -1;

    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    new_record->reference_count = 0;

    manager->records[manager->size++] = new_record;
    manager->keys_used[key] = 1; // Mark this key as used.

    return 1;
}

void dynamicNetworkManager(int min_nodes, int max_nodes, int min_requests, int max_requests) {
    if (min_nodes > max_nodes || min_requests > max_requests)
        return;

    srand(time(NULL));

    long* offsets = malloc(min_nodes * sizeof(long));
    int* keys = malloc(min_nodes * sizeof(int));
    node* nodes = malloc(max_nodes * sizeof(node));
    record** records = malloc(sizeof(record*) * max_nodes);
    request** requests = malloc(sizeof(request*) * max_requests);

    RecordManager* record_manager = initRecordManager(100); // Initial capacity for records.
    if (!record_manager) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return;
    }

    int num_nodes = rand() % (max_nodes - min_nodes + 1) + min_nodes;
    int num_requests = rand() % (max_requests - min_requests + 1) + min_requests;

    if (!offsets || !keys || !nodes || !records || !requests) {
        fprintf(stderr, "Memory allocation failed\n");
        freeRecordManager(record_manager);
        return;
    }

    for (int i = 0; i < num_nodes; ++i) {
        offsets[i] = i * 1000;  // Example offset
        keys[i] = rand() % MAX_KEY_SIZE;

        node* current_node = &nodes[i];
        snprintf(current_node->ip_address, sizeof(current_node->ip_address), "%d.%d.%d.%d", 
                 rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        current_node->port = rand() % (65536 - 1024) + 1024;
        current_node->last_activity = time(NULL);

        double value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
        if (addRecord(record_manager, offsets[i], keys[i], value) <= 0) {
            fprintf(stderr, "Failed to add record\n");
            break;
        }
    }

    for (int i = 0; i < num_requests; ++i) {
        requests[i] = malloc(sizeof(request));
        if (!requests[i]) {
            fprintf(stderr, "Memory allocation failed for request\n");
            break;
        }
        requests[i]->next = NULL;
        // Additional request initialization.
    }

    int input_size = 10;
    int* inputs = malloc(input_size * sizeof(int));

    while (scanf("%d", &inputs[0]) != EOF) {
        if (input_size == 1 && scanf("%*[^\n]") == 0) break; // Malformed input check.

        int new_input_size = input_size + 10;
        int* new_inputs = realloc(inputs, new_input_size * sizeof(int));
        if (!new_inputs) break;

        inputs = new_inputs;
        input_size = new_input_size;
    }

    free(inputs);
    free(offsets);
    free(keys);
    for (int i = 0; i < num_requests; ++i) {
        free(requests[i]);
    }
    free(requests);
    free(nodes);
    free(records);
    freeRecordManager(record_manager);
}
