void initialize_arrays(int num_elements, size_t* offsets, size_t* timestamps, char** keys,
                       int* statuses, Record** records);
void generate_data(int seed, int min_val, int max_val, size_t* offsets, char** keys, Record** records);
int validate_keys(char** keys, int num_elements);
