void custom_allocator_init();
void* custom_allocate(size_t size);
void custom_deallocate(void* ptr);
void monitor_memory_usage();

// Callback function prototype
typedef void (*process_record_callback)(Record*);

// Thread safety lock for shared resources
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays(int num_elements, size_t* offsets, size_t* timestamps, char** keys,
                       int* statuses, Record** records) {
    pthread_mutex_lock(&global_lock);

    // Allocate memory for arrays
    offsets = (size_t*)malloc(num_elements * sizeof(size_t));
    timestamps = (size_t*)malloc(num_elements * sizeof(size_t));
    keys = (char**)malloc(num_elements * sizeof(char*));
    statuses = (int*)malloc(num_elements * sizeof(int));
    records = (Record**)malloc(num_elements * sizeof(Record*));

    if (!offsets || !timestamps || !keys || !statuses || !records) {
        // Handle memory allocation failure
        for (int i = 0; i < num_elements; i++) {
            if (keys[i]) free(keys[i]);
        }
        free(offsets);
        free(timestamps);
        free(keys);
        free(statuses);
        free(records);
        pthread_mutex_unlock(&global_lock);
        return;
    }

    // Initialize arrays
    for (int i = 0; i < num_elements; i++) {
        offsets[i] = i;
        timestamps[i] = i;
        keys[i] = NULL; 
        statuses[i] = 1; // Success by default

        records[i] = custom_allocate(sizeof(Record));
        if (!records[i]) {
            statuses[i] = 0; // Initialization failed
        } else {
            records[i]->key = custom_allocate(20 * sizeof(char)); // Example size for key
            if (records[i]->key) strcpy(records[i]->key, "default_key");
            records[i]->pointer = custom_allocate(sizeof(long));
            if (!records[i]->pointer) {
                statuses[i] = 0;
                free(records[i]);
                records[i] = NULL;
            } else {
                records[i]->value = 0;
                records[i]->numerical_value = 0.0;
                records[i]->data_type = 0; 
            }
        }
    }

    pthread_mutex_unlock(&global_lock);
}

void generate_data(int seed, int min_val, int max_val, size_t* offsets, char** keys, Record** records) {
    // Dynamic loading of the external library for secure RNG
    void *rng_lib = dlopen("libsecure_rng.so", RTLD_LAZY);
    if (!rng_lib) {
        fprintf(stderr, "Failed to load RNG library: %s\n", dlerror());
        pthread_mutex_lock(&global_lock);

        // Clean up on loading error
        for (int i = 0; i < sizeof(offsets)/sizeof(size_t); i++) {
            if (records[i]) {
                custom_deallocate(records[i]->pointer);
                custom_deallocate(records[i]);
            }
        }
        pthread_mutex_unlock(&global_lock);

        return;
    }

    // Secure RNG initialization
    void (*secure_random)(int*, int, int) = dlsym(rng_lib, "secure_random");
    if (!secure_random) {
        fprintf(stderr, "Failed to load secure_random function: %s\n", dlerror());
        pthread_mutex_lock(&global_lock);

        for (int i = 0; i < sizeof(offsets)/sizeof(size_t); i++) {
            if (records[i]) {
                custom_deallocate(records[i]->pointer);
                custom_deallocate(records[i]);
            }
        }
        pthread_mutex_unlock(&global_lock);

        dlclose(rng_lib);
        return;
    }

    srand(seed);
    for (int i = 0; i < sizeof(offsets)/sizeof(size_t); i++) {
        if (records[i]) {
            int rand_val;
            secure_random(&rand_val, min_val, max_val);
            records[i]->value = rand_val;

            // Ensure unique keys
            char key_template[20];
            snprintf(key_template, sizeof(key_template), "key_%zu", offsets[i]);
            keys[i] = custom_allocate((strlen(key_template) + 1) * sizeof(char));
            if (keys[i]) {
                strcpy(keys[i], key_template);
            }
        }
    }

    // Validate for duplicate keys
    if (!validate_keys(keys, sizeof(offsets)/sizeof(size_t))) {
        fprintf(stderr, "Duplicate keys found!\n");
    }

    dlclose(rng_lib);
}

int validate_keys(char** keys, int num_elements) {
    int *seen = calloc(num_elements, sizeof(int));
    for (int i = 0; i < num_elements; i++) {
        if (!keys[i]) continue;
        for (int j = 0; j < i; j++) {
            if (!keys[j]) continue;
            if (strcmp(keys[i], keys[j]) == 0) {
                free(seen);
                return 0;
            }
        }
    }
    free(seen);
    return 1;
}

void process_records(Record** records, int num_elements, process_record_callback callback) {
    for (int i = 0; i < num_elements; i++) {
        if (!records[i]) continue;

        // Lock shared resource access
        pthread_mutex_lock(&global_lock);

        if (callback && records[i]->key) {
            callback(records[i]);
        }

        pthread_mutex_unlock(&global_lock);
    }
}

void custom_allocator_init() {
    // Initialize the memory allocator, such as setting up a free list or pools
