#include <pthread.h>

#define MAX_METADATA_SIZE 1024

typedef struct {
    int value;
    char stringKey[256];
    long *dynamicLong;
    time_t timestamp;
    char metadata[MAX_METADATA_SIZE];
} record;

// Function prototypes
void initializeDataStructures(size_t offsetSize, size_t keySize, size_t recordSize, int randomRangeMin, int randomRangeMax, void (*callback)(record *));
int validateSizes(size_t offsetSize, size_t keySize);
long *allocateLong();
char **createMetadataPool(size_t initialSize);
void logMessage(const char *message);

// Global variables for logging
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeDataStructures(size_t offsetSize, size_t keySize, size_t recordSize, int randomRangeMin, int randomRangeMax, void (*callback)(record *)) {
    if (!validateSizes(offsetSize, keySize)) {
        fprintf(stderr, "Invalid sizes provided.\n");
        return;
    }

    long *offset = (long *)malloc(offsetSize * sizeof(long));
    int *key = (int *)malloc(keySize * sizeof(int));

    if (!offset || !key) {
        fprintf(stderr, "Memory allocation failed for offset or key arrays.\n");
        free(offset);
        free(key);
        return;
    }

    for (size_t i = 0; i < offsetSize; ++i) {
        offset[i] = (long)i;
    }
    for (size_t i = 0; i < keySize; ++i) {
        key[i] = (int)i;
    }

    record *records = (record *)malloc(recordSize * sizeof(record));
    char **metadataPool = createMetadataPool(10);

    if (!records || !metadataPool) {
        fprintf(stderr, "Memory allocation failed for records or metadata pool.\n");
        free(offset);
        free(key);
        free(records);
        for (size_t i = 0; i < recordSize; ++i) {
            free(metadataPool[i]);
        }
        free(metadataPool);
        return;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < recordSize; ++i) {
        records[i].value = rand() % (randomRangeMax - randomRangeMin + 1) + randomRangeMin;
        records[i].dynamicLong = allocateLong();
        if (!records[i].dynamicLong) {
            fprintf(stderr, "Memory allocation failed for dynamic long in record.\n");
            break;
        }
        *records[i].dynamicLong = (long)i;
        records[i].timestamp = time(NULL);
        snprintf(records[i].metadata, MAX_METADATA_SIZE, "Metadata %zu", i);

        if (callback) {
            callback(&records[i]);
        }

        logMessage("Record initialized");
    }

    free(offset);
    free(key);
    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i].dynamicLong);
    }
    free(records);
    for (size_t i = 0; i < recordSize; ++i) {
        free(metadataPool[i]);
    }
    free(metadataPool);
}

int validateSizes(size_t offsetSize, size_t keySize) {
    return offsetSize > 0 && keySize > 0;
}

long *allocateLong() {
    long *ptr = (long *)malloc(sizeof(long));
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for long.\n");
    }
    return ptr;
}

char **createMetadataPool(size_t initialSize) {
    char **pool = (char **)malloc(initialSize * sizeof(char *));
    if (!pool) {
        fprintf(stderr, "Memory allocation failed for metadata pool.\n");
        return NULL;
    }

    for (size_t i = 0; i < initialSize; ++i) {
        pool[i] = (char *)malloc(MAX_METADATA_SIZE);
        if (!pool[i]) {
            fprintf(stderr, "Memory allocation failed for metadata entry.\n");
            for (size_t j = 0; j < i; ++j) {
                free(pool[j]);
            }
            free(pool);
            return NULL;
        }
    }

    return pool;
}

void logMessage(const char *message) {
    pthread_mutex_lock(&logMutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&logMutex);
}
