```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MAX_RETRIES 3
#define MAX_INT_VALUE 100

// Function prototypes
void resizeArray(int **array, size_t *currentSize, size_t newSize);
int allocateRecords(int records[], size_t size);
void freeMemory(void *ptrs[], size_t count);

typedef struct {
    int value;
} Record;

typedef void (*Callback)(Record *);

typedef struct {
    int *offsets;
    int *keys;
    float *weights;
    Record *records;
    size_t currentSize;
    size_t recordsSize;
    Callback callback;
} DynamicDataset;

void processDynamicDataset(size_t recordCount, Callback cb) {
    // Initialize dynamic dataset
    DynamicDataset ds = {0};

    // Allocate and initialize arrays with growth strategy
    resizeArray((int **)&ds.offsets, &ds.currentSize, INITIAL_SIZE);
    for (size_t i = 0; i < ds.currentSize; ++i) ds.offsets[i] = i;

    resizeArray((int **)&ds.keys, &ds.currentSize, INITIAL_SIZE);
    for (size_t i = 0; i < ds.currentSize; ++i) ds.keys[i] = i;

    size_t weightsSize = recordCount;
    resizeArray((float **)&ds.weights, &weightsSize, weightsSize);
    memset(ds.weights, 0, weightsSize * sizeof(float));

    // Allocate records with retry mechanism
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (allocateRecords(ds.records, recordCount)) break;
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to allocate memory for records after %d retries.\n", MAX_RETRIES);
        freeMemory((void *[5]){ds.offsets, ds.keys, ds.weights}, 3);
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set callback and initialize records with random values
    ds.callback = cb;
    for (size_t i = 0; i < recordCount; ++i) {
        ds.records[i].value = rand() % MAX_INT_VALUE + 1;

        if (cb != NULL) {
            cb(&ds.records[i]);
        }

        // Collision detection in weights
        while (ds.weights[i] != 0.0f) {
            ds.weights[i] = (float)(rand()) / RAND_MAX;
        }
    }

    // Find maximum value
    int maxValue = ds.records[0].value;
    for (size_t i = 1; i < recordCount; ++i) {
        if (ds.records[i].value > maxValue) {
            maxValue = ds.records[i].value;
        }
    }

    printf("Maximum Value: %d\n", maxValue);

    // Free all allocated memory
    freeMemory((void *[5]){ds.offsets, ds.keys, ds.weights, ds.records}, 4);
}

// Resize array with minimal reallocation strategy (double size)
void resizeArray(int **array, size_t *currentSize, size_t newSize) {
    if (*array == NULL || *currentSize < newSize) {
        size_t newAllocSize = (*currentSize > 0 ? *currentSize : INITIAL_SIZE);
        while (newAllocSize < newSize) newAllocSize *= 2;

        int *temp = realloc(*array, newAllocSize * sizeof(int));
        if (!temp) {
            fprintf(stderr, "Memory reallocation failed.\n");
            exit(EXIT_FAILURE);
        }

        memset(temp + (*currentSize), 0, (newAllocSize - *currentSize) * sizeof(int));

        *array = temp;
        *currentSize = newAllocSize;
    }
}

// Allocate records with retry mechanism
int allocateRecords(Record *records[], size_t size) {
    for (size_t retries = 0; retries < MAX_RETRIES; ++retries) {
        *records = malloc(size * sizeof(Record));
        if (*records != NULL) return 1;
        fprintf(stderr, "Memory allocation failed. Retry %zu/%zu.\n", retries + 1, MAX_RETRIES);
    }
    return 0;
}

// Free allocated memory
void freeMemory(void *ptrs[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (ptrs[i] != NULL) {
            free(ptrs[i]);
            ptrs[i] = NULL;
        }
    }
}

// Example callback function
void validateRecord(Record *record) {
    // Custom processing, e.g., validation or transformation
    printf("Validating record with value: %d\n", record->value);
}
```

