#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    time_t timestamp;
    long *value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record **records;
    pthread_mutex_t lock;
} RecordStore;

#define INITIAL_CAPACITY 1024
#define MAX_RECORDS 10000

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

RecordStore* initialize_record_store(size_t size, int use_seed, long seed_value, void (*callback)(Record*)) {
    if (size > MAX_RECORDS) {
        log_error("Requested size exceeds maximum limit.");
        return NULL;
    }

    RecordStore *store = (RecordStore*)malloc(sizeof(RecordStore));
    if (!store) {
        log_error("Failed to allocate memory for record store.");
        return NULL;
    }

    pthread_mutex_init(&store->lock, NULL);
    store->capacity = INITIAL_CAPACITY > size ? INITIAL_CAPACITY : size;
    store->count = 0;

    store->records = (Record**)malloc(store->capacity * sizeof(Record*));
    if (!store->records) {
        log_error("Failed to allocate memory for records.");
        free(store);
        return NULL;
    }

    srand(seed_value ? seed_value : time(NULL));

    for (size_t i = 0; i < size; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            log_error("Failed to allocate memory for a record.");
            break;
        }

        record->key = (int)i;
        record->timestamp = use_seed ? seed_value + i : time(NULL);
        record->value = (long*)malloc(sizeof(long));
        if (!record->value) {
            free(record);
            log_error("Failed to allocate memory for value.");
            break;
        }
        *record->value = rand(); // Example metric data

        pthread_mutex_lock(&store->lock);
        store->records[store->count++] = record;
        pthread_mutex_unlock(&store->lock);

        if (callback) {
            callback(record);
        }

        if (store->count >= store->capacity) {
            size_t new_capacity = store->capacity * 2;
            Record **new_records = (Record**)realloc(store->records, new_capacity * sizeof(Record*));
            if (!new_records) {
                log_error("Failed to expand record array.");
                break;
            }
            store->records = new_records;
            store->capacity = new_capacity;
        }
    }

    return store;
}

void export_to_file(RecordStore *store, const char *filename, const char *format) {
    FILE *file = fopen(filename, format == "json" ? "w" : "a");
    if (!file) {
        log_error("Failed to open file for writing.");
        return;
    }

    pthread_mutex_lock(&store->lock);
    fprintf(file, "[\n");
    for (size_t i = 0; i < store->count; ++i) {
        Record *record = store->records[i];
        if (format == "json") {
            fprintf(file, "{ \"key\": %d, \"timestamp\": %ld, \"value\": %ld }", record->key, record->timestamp, *(record->value));
        } else { // CSV
            fprintf(file, "%d,%ld,%ld\n", record->key, record->timestamp, *(record->value));
        }
        if (i < store->count - 1) {
            fputc(',', file);
        }
    }
    fprintf(file, "\n]");
    pthread_mutex_unlock(&store->lock);

    fclose(file);
}

void free_record_store(RecordStore *store) {
    if (!store) return;

    pthread_mutex_lock(&store->lock);
    for (size_t i = 0; i < store->count; ++i) {
        Record *record = store->records[i];
        free(record->value);
        free(record);
    }
    free(store->records);
    pthread_mutex_unlock(&store->lock);

    pthread_mutex_destroy(&store->lock);
    free(store);
}

void process_record(Record *record) {
    // Custom processing logic
}

int main() {
    size_t size = 1000;
    RecordStore *store = initialize_record_store(size, 1, time(NULL), process_record);
    if (store) {
        export_to_file(store, "records.json", "json");
        free_record_store(store);
    }
    return 0;
}
```

This code sets up a dynamic record store with the specified requirements, including memory management, error handling, and optional callback processing. It also includes functionality to export records to a file in JSON or CSV format.']

