    free_resources(recordA->keyString ? (char *[num_records]){recordA->keyString} : NULL, num_records);
    free_resources(recordB->keyString ? (char *[num_records]){recordB->keyString} : NULL, num_records);
    free(recordA);
    free(recordB);

    pthread_mutex_unlock(&lock);
}

int main() {
