#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MEMORY_THRESHOLD 1048576 // Example threshold in bytes

typedef struct {
    double value;
    char *str;
} element;

int allocate_pipeline(size_t num_elements, size_t string_size, double rand_min, double rand_max) {
    if (num_elements <= 0 || string_size <= 0) return -1;

    size_t total_memory = sizeof(double) * num_elements +
                          sizeof(char) * num_elements * string_size +
                          sizeof(element *) * num_elements;

    if (total_memory > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory usage exceeds threshold.\n");
        return -2;
    }

    double *numbers = malloc(sizeof(double) * num_elements);
    char **strings = malloc(sizeof(char *) * num_elements);
    element **elements = malloc(sizeof(element *) * num_elements);

    if (!numbers || !strings || !elements) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(numbers); numbers = NULL;
        free(strings); strings = NULL;
        free(elements); elements = NULL;
        return -3;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_elements; ++i) {
        numbers[i] = rand_min + ((rand() / (double)RAND_MAX) * (rand_max - rand_min));

        char *str = malloc(sizeof(char) * string_size);
        if (!str) {
            fprintf(stderr, "Memory allocation for strings failed.\n");
            free(numbers); numbers = NULL;
            free(strings); strings = NULL;
            free(elements); elements = NULL;

            for (size_t j = 0; j < i; ++j) {
                free(strings[j]);
            }
            free(strings);
            return -4;
        }

        snprintf(str, string_size, "String %zu", i);
        strings[i] = str;

        element *e = malloc(sizeof(element));
        if (!e) {
            fprintf(stderr, "Memory allocation for elements failed.\n");
            free(numbers); numbers = NULL;
            free(strings); strings = NULL;
            free(elements); elements = NULL;

            for (size_t j = 0; j <= i; ++j) {
                free(strings[j]);
            }
            free(strings);
            return -5;
        }

        e->value = numbers[i];
        e->str = strings[i];
        elements[i] = e;
    }

    // Cleanup in case of error or normal exit
    for (size_t i = 0; i < num_elements; ++i) {
        free(elements[i]); // This also frees the string pointers within each element
    }
    free(numbers);
    free(strings);
    free(elements);

    return 0;
}

int main() {
    size_t num_elements = 10;
    size_t string_size = 20;
    double rand_min = 1.0, rand_max = 100.0;

    int result = allocate_pipeline(num_elements, string_size, rand_min, rand_max);
    if (result == 0) {
        printf("Pipeline allocation successful.\n");
    } else {
        printf("Pipeline allocation failed with error code: %d\n", result);
    }

    return 0;
}
