#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    int value;
} record_t;

// Global logger settings
int log_level = LOG_LEVEL_INFO;
FILE *log_file = NULL;

void custom_log(int level, const char *format, ...) {
    if (level < log_level) return;

    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);

    fflush(log_file);
}

int validate_and_prepare_keys(const int *keys, size_t key_size, bool *unique_keys) {
    if (key_size == 0 || keys == NULL) return -1;

    // Initialize unique_keys array
    for (size_t i = 0; i < key_size; ++i) unique_keys[i] = true;

    // Check for duplicates
    for (size_t i = 0; i < key_size; ++i) {
        for (size_t j = i + 1; j < key_size; ++j) {
            if (keys[i] == keys[j]) {
                custom_log(LOG_LEVEL_ERROR, "Duplicate key found: %d", keys[i]);
                return -1;
            }
        }
    }

    return 0;
}

int initialize_records(record_t **records, size_t record_count, int min_value, int max_value) {
    if (record_count == 0 || records == NULL) return -1;

    *records = malloc(sizeof(record_t) * record_count);
    if (*records == NULL) {
        custom_log(LOG_LEVEL_ERROR, "Memory allocation failed for records");
        return -1;
    }

    bool values_exist[max_value - min_value + 1] = {false};

