    srand(time(NULL));

    for (size_t i = 0; i < record_count; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (values_exist[value]);

        (*records)[i].value = value;
        values_exist[value] = true;
    }

    custom_log(LOG_LEVEL_INFO, "Initialized %zu records with unique values", record_count);
    return 0;
}

int create_records_array(const int *keys, size_t key_size, const long *offsets, size_t offset_size,
                         record_t ***records_out, int min_value, int max_value) {
    if (key_size <= 0 || keys == NULL || offset_size <= 0 || offsets == NULL ||
        records_out == NULL) return -1;

    bool unique_keys[key_size];
    int validation_status = validate_and_prepare_keys(keys, key_size, unique_keys);
    if (validation_status != 0) return validation_status;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Critical section begins
    pthread_mutex_lock(&lock);

    record_t **records = malloc(sizeof(record_t *));
    if (!records) {
        custom_log(LOG_LEVEL_ERROR, "Memory allocation failed for records pointer");
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    int init_status = initialize_records(records, key_size, min_value, max_value);
    if (init_status != 0) {
        free(records);
        custom_log(LOG_LEVEL_ERROR, "Failed to initialize records");
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    *records_out = records;

    // Critical section ends
    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return 0;
}

int main() {
    log_file = fopen("log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    int keys[] = {1, 2, 3};
    long offsets[] = {0, 10, 20};

    record_t *records = NULL;
    int result = create_records_array(keys, sizeof(keys) / sizeof(keys[0]),
                                      offsets, sizeof(offsets) / sizeof(offsets[0]), &records, 100, 200);

    if (result == 0) {
        for (size_t i = 0; i < sizeof(keys) / sizeof(keys[0]); ++i) {
            printf("Record %zu: Value = %d\n", i + 1, records[i].value);
        }
    } else {
        fprintf(stderr, "Failed to create records array\n");
    }

    free(records);
    fclose(log_file);

    return result == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

