    EVP_cleanup();
    HMAC_CTX_cleanup();
    EC_KEY_free(EC_KEY_new_by_curve_name(NID_X9_62_prime256v1));
}

void generateAuthKey() {
    // Generate authKeyId and authKeyData using OpenSSL
    srand(time(NULL));
    authKeyId = rand(); // Simplified for demonstration purposes

    unsigned char key[32];
    RAND_bytes(key, sizeof(key));
    memcpy(authKeyData, key, sizeof(key));

    printf("Generated Auth Key ID: %llu\n", authKeyId);
}

void addSession(UserSession *session) {
    pthread_mutex_lock(&sessionMutex);

    session->next = sessionList;
    sessionList = session;

    pthread_mutex_unlock(&sessionMutex);
}

void removeSession(uint64_t userId) {
    pthread_mutex_lock(&sessionMutex);

    UserSession **current = &sessionList;
    while (*current) {
        UserSession *entry = *current;
        if (entry->userId == userId) {
            *current = entry->next;
            freeAllSessions(entry);
            break;
        }
        current = &entry->next;
    }

    pthread_mutex_unlock(&sessionMutex);
}

void updateSession(UserSession *session, const char *newToken) {
    pthread_mutex_lock(&sessionMutex);

    strncpy(session->sessionToken, newToken, sizeof(session->sessionToken));
    session->lastActive = time(NULL);

    pthread_mutex_unlock(&sessionMutex);
}

UserSession* findSessionByUserId(uint64_t userId) {
    UserSession *current = sessionList;
    while (current) {
        if (current->userId == userId) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void freeAllSessions(UserSession *session) {
    if (!session) return;

    secureFree(session->record);
    secureFree(session);
}

Record* createRecord(size_t stringKeySize, int intValueRangeMin, int intValueRangeMax) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) return NULL;

    record->intValue = rand() % (intValueRangeMax - intValueRangeMin + 1) + intValueRangeMin;
    record->stringKey = (char *)malloc(stringKeySize);
    if (!record->stringKey) {
        secureFree(record);
        return NULL;
    }
    memset(record->stringKey, 0, stringKeySize);

    unsigned char *longData = (unsigned char *)malloc(sizeof(long));
    if (!longData) {
        secureFree(record->stringKey);
        secureFree(record);
        return NULL;
    }
    RAND_bytes(longData, sizeof(long));
    record->secureLongPtr = (long *)longData;

    return record;
}

void secureFree(void *ptr) {
    if (ptr) free(ptr);
}

// Periodic cleanup function
void* cleanupThread(void *arg) {
    uint64_t timeout = *(uint64_t*)arg;

    while (1) {
        sleep(60); // Run every minute
        cleanupSessions(timeout);
    }

    return NULL;
}

void cleanupSessions(uint64_t timeout) {
    pthread_mutex_lock(&sessionMutex);

    time_t currentTime = time(NULL);
    UserSession **current = &sessionList;
    while (*current) {
        UserSession *entry = *current;
        if (difftime(currentTime, entry->lastActive) > timeout) {
            *current = entry->next;
            freeAllSessions(entry);
        } else {
            current = &entry->next;
        }
    }

    pthread_mutex_unlock(&sessionMutex);
}

// Main function for testing
