    initializeCryptoPrimitives();
    generateAuthKey();

    // Start cleanup thread
    uint64_t sessionTimeout = 3600; // 1 hour timeout
    pthread_t cleanupThreadId;
    pthread_create(&cleanupThreadId, NULL, cleanupThread, &sessionTimeout);

    // Add some test sessions
