    if (foundSession) {
        updateSession(foundSession, "updated_token");
    }

    // Free all sessions before exit
    freeAllSessions(sessionList);

    pthread_cancel(cleanupThreadId);
    pthread_join(cleanupThreadId, NULL);

    return 0;
}
