#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
    char *key;
    long *ptr_long;
    time_t timestamp;
} Record;

// Define log entry structure
typedef struct {
    time_t timestamp;
    unsigned long log_id;
    double latency;
} LogEntry;

// Thread-safe data structure for circular buffer or linked list
typedef struct {
    // Example using a circular buffer approach with dynamic resizing
    Record *records;
    LogEntry *logs;
    size_t record_capacity;
    size_t log_capacity;
    size_t record_count;
    size_t log_count;
    pthread_rwlock_t lock;

    // Circular buffer indices for records and logs
    size_t record_head;
    size_t log_head;
} LogManager;

// Function to initialize the LogManager
void initLogManager(LogManager *manager, size_t initial_record_capacity, size_t initial_log_capacity) {
    manager->records = malloc(sizeof(Record) * initial_record_capacity);
    manager->logs = malloc(sizeof(LogEntry) * initial_log_capacity);
    manager->record_capacity = initial_record_capacity;
    manager->log_capacity = initial_log_capacity;
    manager->record_count = 0;
    manager->log_count = 0;
    manager->record_head = 0;
    manager->log_head = 0;

    pthread_rwlock_init(&manager->lock, NULL);
}

// Function to resize the record or log buffer
void resizeBuffer(void **buffer, size_t *capacity) {
    size_t new_capacity = (*capacity) * 2;
    void *new_buffer = realloc(*buffer, sizeof(Record) * new_capacity);
    if (new_buffer != NULL) {
        *buffer = new_buffer;
        *capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize buffer\n");
        exit(EXIT_FAILURE);
    }
}

// Function to add a log entry in a thread-safe manner
void addLogEntry(LogManager *manager, LogEntry entry) {
    pthread_rwlock_wrlock(&manager->lock);

    if (manager->log_count == manager->log_capacity) {
        resizeBuffer((void **)&manager->logs, &manager->log_capacity);
    }

    size_t index = (manager->log_head + manager->log_count) % manager->log_capacity;
    manager->logs[index] = entry;
    manager->log_count++;

    pthread_rwlock_unlock(&manager->lock);
}

// Function to add a record in a thread-safe manner
void addRecord(LogManager *manager, Record record) {
    pthread_rwlock_wrlock(&manager->lock);

    if (manager->record_count == manager->record_capacity) {
        resizeBuffer((void **)&manager->records, &manager->record_capacity);
    }

    size_t index = (manager->record_head + manager->record_count) % manager->record_capacity;
    manager->records[index] = record;
    manager->record_count++;

    pthread_rwlock_unlock(&manager->lock);
}

// Example custom processing function for a log entry
void processLogEntry(LogEntry *entry, void (*customFunction)(LogEntry *)) {
    if (customFunction != NULL) {
        customFunction(entry);
    }
}

// Example custom processing function for a record
void processRecord(Record *record, void (*customFunction)(Record *)) {
    if (customFunction != NULL) {
        customFunction(record);
    }
}

// Cleanup resources
void cleanupLogManager(LogManager *manager) {
    free(manager->records);
    free(manager->logs);
    pthread_rwlock_destroy(&manager->lock);
}

// Example of using the function to manage logs and records
void manageLogsAndRecords() {
    LogManager manager;
    initLogManager(&manager, 10, 10);

    // Simulate adding log entries and records
    LogEntry entry = {time(NULL), 1, 123.45};
    addLogEntry(&manager, entry);

    Record record = {42, "example", NULL, time(NULL)};
    addRecord(&manager, record);

    // Process logs and records with custom functions
    processLogEntry(&entry, NULL);
    processRecord(&record, NULL);

    cleanupLogManager(&manager);
}

int main() {
    manageLogsAndRecords();
    return 0;
}
