    return max;
}

// Function to load configuration from a JSON file
int loadConfig(const char *filename, int *record_count, int *value_range_min, int *value_range_max, char **mode) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    struct json_object *parsed_json;
    struct json_object *config_obj;

    parsed_json = json_object_from_file(file);
    fclose(file);

    if (!parsed_json) return -2;

    json_object_object_get_ex(parsed_json, "record_count", &config_obj);
    json_object_object_get_ex(parsed_json, "value_range_min", &config_obj);
    json_object_object_get_ex(parsed_json, "value_range_max", &config_obj);
    json_object_object_get_ex(parsed_json, "mode", &config_obj);

    *record_count = (int)json_object_get_int(config_obj);
    *value_range_min = (int)json_object_get_int(config_obj);
    *value_range_max = (int)json_object_get_int(config_obj);
    *mode = strdup(json_object_get_string(config_obj));

    json_object_put(parsed_json);

    return 0;
}

// Thread-safe wrapper to access shared keys
pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;

void safeAccessKeys(int *keys, size_t count, int index, int value) {
    pthread_mutex_lock(&key_mutex);
    if (index < count) {
        keys[index] = value;
    }
    pthread_mutex_unlock(&key_mutex);
}

// Function to process records and find maximum integer
int processRecordsAndFindMax(const char *config_file) {
    int record_count, value_range_min, value_range_max;
    char *mode;

    if (loadConfig(config_file, &record_count, &value_range_min, &value_range_max, &mode)) {
