        fprintf(stderr, "Exceeded maximum memory usage limit\n");
        free(mode);
        return -2;
    }

    int *keys = malloc(record_count * sizeof(int));
    record_t *records = malloc(record_count * sizeof(record_t));

    if (!keys || !records) {
        perror("Memory allocation failed");
        free(keys);
        free(records);
        free(mode);
