    }

    // Simulate reading integers from standard input
    int input_values[record_count];
    printf("Enter %d integers:\n", record_count);
    for (int i = 0; i < record_count; ++i) {
        scanf("%d", &input_values[i]);
    }

    int max_value = findMax(input_values, record_count);

    // Example transformation based on mode
    for (int i = 0; i < record_count; ++i) {
        records[i].value = input_values[i];
        records[i].key = malloc(10);
        snprintf(records[i].key, 10, "Key%d", i);
        records[i].offset = malloc(sizeof(long));
        *records[i].offset = (long)(input_values[i] * input_values[i]); // Example transformation

        safeAccessKeys(keys, record_count, i, input_values[i]);
    }

    printf("Maximum integer: %d\n", max_value);

    // Free allocated memory
    for (int i = 0; i < record_count; ++i) {
        free(records[i].key);
        free(records[i].offset);
    }
    free(keys);
    free(records);
    free(mode);

    return 0;
}

int main() {
    if (processRecordsAndFindMax("config.json") != 0) {
        fprintf(stderr, "Failed to process records\n");
    }
    return 0;
}
