['Below is a C code example that addresses your requirements using a simple lock-based approach for concurrency control. The implementation uses mutexes from `<pthread.h>` for thread safety, dynamic arrays for record storage, and basic memory management functions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t used_memory; // For monitoring memory usage
} Database;

Database* create_database(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_RECORDS)
        return NULL;

    Database *db = malloc(sizeof(Database));
    db->records = malloc(initial_capacity * sizeof(Record));
    db->capacity = initial_capacity;
    db->count = 0;
    db->used_memory = initial_capacity * sizeof(Record);

    pthread_mutex_init(&db->lock, NULL);

    return db;
}

int add_record(Database *db, int key, long offset) {
    if (pthread_mutex_lock(&db->lock)) return -1;

    if (db->count == db->capacity) {
        size_t new_capacity = db->capacity * 2;
        if (new_capacity > MAX_RECORDS) {
            pthread_mutex_unlock(&db->lock);
            return -1; // Capacity exceeded
        }

        Record *new_records = realloc(db->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&db->lock);
            return -1;
        }

        db->records = new_records;
        db->capacity = new_capacity;
        db->used_memory += new_capacity * sizeof(Record);
    }

    Record record = {key, offset};
    db->records[db->count++] = record;

    pthread_mutex_unlock(&db->lock);
    return 0;
}

int get_record(Database *db, int key, long *offset) {
    if (!pthread_mutex_trylock(&db->lock)) {
        for (size_t i = 0; i < db->count; ++i) {
            if (db->records[i].key == key) {
                *offset = db->records[i].offset;
                pthread_mutex_unlock(&db->lock);
                return 0;
            }
        }

        pthread_mutex_unlock(&db->lock);
    }

    return -1; // Record not found
}

void free_database(Database *db) {
    if (pthread_mutex_lock(&db->lock)) return;

    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

size_t get_record_count(Database *db) {
    size_t count;
    if (!pthread_mutex_trylock(&db->lock)) {
        count = db->count;
        pthread_mutex_unlock(&db->lock);
    }

    return count;
}

size_t get_memory_usage(Database *db) {
    size_t used_memory;
    if (!pthread_mutex_trylock(&db->lock)) {
        used_memory = db->used_memory;
        pthread_mutex_unlock(&db->lock);
    }

    return used_memory;
}

// Usage example:
/*
int main() {
    Database *db = create_database(1000);

    add_record(db, 1, 123456789L);
    long offset;
    if (get_record(db, 1, &offset) == 0) {
        printf("Record found: key=1, offset=%ld\n", offset);
    }

    printf("Total records: %zu\n", get_record_count(db));
    printf("Memory usage: %zu bytes\n", get_memory_usage(db));

    free_database(db);
    return 0;
}
*/

```

### Key Points:
- **Concurrency**: Mutexes are used to ensure thread-safe access to the database structure.
- **Dynamic Memory Management**: The `realloc` function is used to resize the records array when needed, ensuring efficient memory use.
- **Memory Usage Monitoring**: A simple counter tracks memory usage, although in a production scenario, more sophisticated monitoring might be required.
- **Fragmentation and Reclamation**: This basic example does not include advanced techniques for fragmentation handling or periodic reclamation, but you could implement these using custom allocators or additional background threads.

This code provides a foundation that can be further optimized and adapted to specific use cases.']

