#include <stdio.h>
#include <stdlib.h>
import stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024
#define BATCH_INTERVAL 10 // seconds

typedef struct {
    time_t timestamp;
    char message[256];
    int importance_level;
} log_entry;

typedef struct {
    float* measurements;
    char* status_codes;
    log_entry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} log_buffer;

log_buffer* init_log_buffer(size_t initial_capacity) {
    log_buffer* buffer = (log_buffer*)malloc(sizeof(log_buffer));
    buffer->measurements = NULL;
    buffer->status_codes = NULL;
    buffer->entries = (log_entry**)calloc(initial_capacity, sizeof(log_entry*));
    buffer->capacity = initial_capacity;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void free_log_buffer(log_buffer* buffer) {
    for (size_t i = 0; i < buffer->count; ++i) {
        free(buffer->entries[i]);
    }
    free(buffer->entries);
    free(buffer->measurements);
    free(buffer->status_codes);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

void resize_log_buffer(log_buffer* buffer, size_t new_capacity) {
    log_entry** new_entries = (log_entry**)realloc(buffer->entries, new_capacity * sizeof(log_entry*));
    if (!new_entries) return; // handle error appropriately
    buffer->entries = new_entries;
    buffer->capacity = new_capacity;
}

void add_log_entry(log_buffer* buffer, const char* message, int importance_level) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count >= buffer->capacity) {
        resize_log_buffer(buffer, buffer->capacity * 2);
    }

    log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
    time(&entry->timestamp);
    strncpy(entry->message, message, sizeof(entry->message) - 1);
    entry->importance_level = importance_level;

    buffer->entries[buffer->count++] = entry;

    pthread_mutex_unlock(&buffer->lock);
}

void log_events(const char** event_descriptions, size_t num_events, int importance_level) {
    static log_buffer* global_log_buffer = NULL;
    if (!global_log_buffer) {
        global_log_buffer = init_log_buffer(10); // initial capacity
    }

    for (size_t i = 0; i < num_events; ++i) {
        add_log_entry(global_log_buffer, event_descriptions[i], importance_level);
    }
}

void* periodic_aggregation(void* arg) {
    log_buffer* buffer = (log_buffer*)arg;

    while (1) {
        pthread_mutex_lock(&buffer->lock);

        if (buffer->count > 0) {
            // Simulate sending logs to an external service
            printf("Aggregating %zu logs\n", buffer->count);

            // Clear log entries after aggregation
            for (size_t i = 0; i < buffer->count; ++i) {
                free(buffer->entries[i]);
            }
            memset(buffer->entries, 0, sizeof(log_entry*) * buffer->capacity);
            buffer->count = 0;
        }

        pthread_mutex_unlock(&buffer->lock);

        sleep(BATCH_INTERVAL); // Sleep for the batch interval
    }

    return NULL;
}

int main() {
    const char* events[] = {"Event 1", "Event 2", "Event 3"};

    pthread_t aggregation_thread;
    pthread_create(&aggregation_thread, NULL, periodic_aggregation, global_log_buffer);

    log_events(events, sizeof(events) / sizeof(events[0]), 1);

    // For demonstration purposes: sleep to allow for periodic aggregation
    sleep(20); 

    free_log_buffer(global_log_buffer);

    return 0;
}
```

This code provides a basic implementation of a multi-threaded logging system in C. It initializes and manages a log buffer, adds log entries with timestamps and importance levels, resizes the buffer when necessary, and periodically aggregates logs using a separate thread. Thread safety is ensured with mutexes to prevent race conditions during concurrent access. This setup includes mechanisms for dynamic memory management, synchronization, and periodic task execution suitable for high-performance applications. Further optimizations like network transmission can be added depending on specific requirements.']

