#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_ENTRIES 1000000

typedef struct {
    time_t timestamp;
    char message[256];
    int importance_level;
} log_entry;

typedef struct {
    log_entry *entries;
    size_t count;
    size_t capacity;
} log_system;

log_system* create_log_system(size_t initial_capacity) {
    log_system *system = (log_system*) malloc(sizeof(log_system));
    if (!system) return NULL;

    system->entries = (log_entry*) malloc(initial_capacity * sizeof(log_entry));
    if (!system->entries) {
        free(system);
        return NULL;
    }

    system->count = 0;
    system->capacity = initial_capacity;
    return system;
}

void resize_log_system(log_system *system, size_t new_capacity) {
    log_entry *new_entries = (log_entry*) realloc(system->entries, new_capacity * sizeof(log_entry));
    if (!new_entries) return;

    system->entries = new_entries;
    system->capacity = new_capacity;
}

int add_log_entry(log_system *system, const char *description, int importance_level) {
    if (system->count == system->capacity) {
        resize_log_system(system, system->capacity * 2);
        if (!system->entries) return -1; // Memory allocation failed
    }

    log_entry *entry = &system->entries[system->count++];
    entry->timestamp = time(NULL);
    strncpy(entry->message, description, sizeof(entry->message) - 1);
    entry->importance_level = importance_level;

    if (system->count > MAX_LOG_ENTRIES) {
        memmove(system->entries, system->entries + 1, 
                (system->capacity - 1) * sizeof(log_entry));
        system->count--;
    }

    return 0;
}

size_t get_log_count(const log_system *system) {
    return system->count;
}

void free_log_system(log_system *system) {
    if (!system) return;

    free(system->entries);
    free(system);
}

// Example usage
int main() {
    log_system *log_sys = create_log_system(100);

    for (int i = 0; i < 105; ++i) { // Simulate adding more entries than initial capacity
        char description[256];
        snprintf(description, sizeof(description), "Event %d", i);
        add_log_entry(log_sys, description, i % 4); // Cyclic importance levels (0-3)
    }

    printf("Total log entries: %zu\n", get_log_count(log_sys));

    free_log_system(log_sys);
    return 0;
}
