#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct MemoryPool {
    size_t block_size;
    void *pool;
    size_t pool_size;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool mem_pool = {0};

void initialize_memory_pool(size_t initial_capacity, size_t block_size) {
    pthread_mutex_init(&mem_pool.lock, NULL);
    mem_pool.block_size = block_size;
    mem_pool.pool_size = initial_capacity * block_size;
    mem_pool.pool = malloc(mem_pool.pool_size);
    if (!mem_pool.pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    mem_pool.used_blocks = 0;
}

void* allocate_record() {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.used_blocks * mem_pool.block_size >= mem_pool.pool_size) {
        size_t new_size = mem_pool.pool_size + mem_pool.block_size;
        void *new_pool = realloc(mem_pool.pool, new_size);
        if (!new_pool) {
            fprintf(stderr, "Failed to resize memory pool\n");
            pthread_mutex_unlock(&mem_pool.lock);
            return NULL;
        }
        mem_pool.pool = new_pool;
        mem_pool.pool_size = new_size;
    }
    void *block = (char*)mem_pool.pool + mem_pool.used_blocks * mem_pool.block_size;
    mem_pool.used_blocks++;
    pthread_mutex_unlock(&mem_pool.lock);
    return block;
}

void deallocate_record(void* record) {
    // Implement as needed, e.g., mark blocks as free in a more complex system
}

typedef struct RecordManager {
    Record **records;
    size_t count;
    size_t capacity;
    int total_keys_sum;
    pthread_mutex_t lock;
} RecordManager;

RecordManager manager = {0};

void initialize_record_manager(size_t initial_capacity) {
    pthread_mutex_init(&manager.lock, NULL);
    manager.capacity = initial_capacity;
    manager.count = 0;
    manager.total_keys_sum = 0;
    manager.records = malloc(initial_capacity * sizeof(Record*));
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&manager.lock);

    if (manager.count == manager.capacity) {
        size_t new_capacity = manager.capacity * 2;
        Record **new_records = realloc(manager.records, new_capacity * sizeof(Record*));
        if (!new_records) {
            fprintf(stderr, "Failed to resize record array\n");
            pthread_mutex_unlock(&manager.lock);
            return;
        }
        manager.records = new_records;
        manager.capacity = new_capacity;
    }

    Record *record = (Record*)allocate_record();
    if (!record) {
        fprintf(stderr, "Allocation failed for a new record\n");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    record->offset = offset;
    record->key = key;
    manager.records[manager.count++] = record;
    manager.total_keys_sum += key;

    pthread_mutex_unlock(&manager.lock);
}

void log_statistics() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, [](void* arg) -> void* {
        while (1) {
            sleep(10);
            pthread_mutex_lock(&manager.lock);

            printf("Records added: %zu\n", manager.count);
            size_t memory_usage = mem_pool.used_blocks * mem_pool.block_size;
            float utilization_percentage = (float)memory_usage / mem_pool.pool_size * 100.0f;

            if (manager.count > 0)
                printf("Average key value: %.2f\n", (float)manager.total_keys_sum / manager.count);

            printf("Total memory usage: %zu bytes\n", memory_usage);
            printf("Memory utilization: %.2f%%\n", utilization_percentage);

            pthread_mutex_unlock(&manager.lock);
        }
        return NULL;
    }, NULL);
}

void export_to_csv(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    pthread_mutex_lock(&manager.lock);

    fprintf(file, "Offset,Key\n");
    for (size_t i = 0; i < manager.count; ++i) {
        Record *record = manager.records[i];
        fprintf(file, "%ld,%d\n", record->offset, record->key);
    }

    pthread_mutex_unlock(&manager.lock);

    fclose(file);
}

void shutdown() {
    free(manager.records);
    free(mem_pool.pool);
}

int main() {
    initialize_memory_pool(10, sizeof(Record));
    initialize_record_manager(5);

    log_statistics();

    add_record(1000, 42);
    add_record(2000, 84);

    export_to_csv("records.csv");

    shutdown();
    return 0;
}
