This is a simplified example; in production, you'd likely need more robust error handling and possibly finer-grained locking for better concurrency.']

['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <chrono>
#include <atomic>
#include <memory>
#include <future>

// Log levels
enum class LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    FATAL
};

// Message format struct
struct LogEntry {
    std::string timestamp;
    LogLevel level;
    std::thread::id thread_id;
    std::string message;

    bool operator<(const LogEntry& other) const {
        return timestamp < other.timestamp;
    }
};

class Logger {
public:
    enum class Mode { SYNCHRONOUS, ASYNCHRONOUS };

private:
    std::atomic<bool> running_;
    std::thread worker_thread_;
    std::mutex queue_mutex_;
    std::condition_variable condition_;
    std::queue<LogEntry> log_queue_;
    Mode mode_;

    // Configuration
    LogLevel current_level_;
    std::string format_;
    std::ofstream log_file_;

public:
    Logger(LogLevel level, const std::string& filename, Mode mode)
        : running_(true), current_level_(level), mode_(mode) {
        log_file_.open(filename, std::ios::out | std::ios::app);
        if (!log_file_) {
            throw std::runtime_error("Failed to open log file");
        }

        // Start the worker thread for asynchronous logging
        if (mode_ == Mode::ASYNCHRONOUS) {
            worker_thread_ = std::thread(&Logger::process_logs, this);
        }
    }

    ~Logger() {
        stop();
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    void setLevel(LogLevel level) {
        current_level_ = level;
    }

    void setFormat(const std::string& format) {
        format_ = format;
    }

    void log(LogLevel level, const std::string& message) {
        if (level < current_level_) return;

        auto now = std::chrono::system_clock::now();
        auto time_t_now = std::chrono::system_clock::to_time_t(now);

        std::stringstream ss;
        ss << std::put_time(std::localtime(&time_t_now), "%Y-%m-%d %X");
        LogEntry entry{ss.str(), level, std::this_thread::get_id(), message};

        if (mode_ == Mode::SYNCHRONOUS) {
            write_log(entry);
        } else {
            {
                std::lock_guard<std::mutex> lock(queue_mutex_);
                log_queue_.push(entry);
            }
            condition_.notify_one();
        }
    }

private:
    void process_logs() {
        while (running_) {
            LogEntry entry;

            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                condition_.wait(lock, [this] { return !log_queue_.empty() || !running_; });

                if (!running_ && log_queue_.empty()) break;

                entry = log_queue_.front();
                log_queue_.pop();
            }

            write_log(entry);
        }
    }

    void write_log(const LogEntry& entry) {
        std::stringstream formatted_message;

        // Customize the message format
        formatted_message << "[" << entry.timestamp << "] "
                          << "[Thread " << entry.thread_id << "] "
                          << "[" << log_level_to_string(entry.level) << "] "
                          << entry.message << "\n";

        if (!log_file_.is_open()) {
            return;
        }

        // Log to file
        log_file_ << formatted_message.str();

        // Simulate resource usage monitoring (simplified)
        monitor_resources();
    }

    std::string log_level_to_string(LogLevel level) const {
        switch(level) {
            case LogLevel::DEBUG:   return "DEBUG";
            case LogLevel::INFO:    return "INFO";
            case LogLevel::WARNING: return "WARNING";
            case LogLevel::ERROR:   return "ERROR";
            case LogLevel::FATAL:   return "FATAL";
            default:                return "UNKNOWN";
        }
    }

    void monitor_resources() {
        // Placeholder for monitoring memory and CPU usage
        std::cout << "Monitoring resources..." << std::endl;
    }

    void stop() {
        running_ = false;
        condition_.notify_one();
    }
};

// Example Usage
int main() {
    Logger logger(LogLevel::DEBUG, "app.log", Logger::Mode::ASYNCHRONOUS);

    logger.setFormat("[%Y-%m-%d %H:%M:%S] [%t] [%L] %m");
    logger.log(LogLevel::INFO, "Application started.");
    std::this_thread::sleep_for(std::chrono::seconds(1));
    logger.log(LogLevel::ERROR, "An error occurred.");

    return 0;
}
```

This implementation provides a scalable and flexible logging framework with support for both synchronous and asynchronous modes. It handles log entries efficiently under high throughput conditions using memory-safe techniques such as thread safety mechanisms. The `Logger` class also supports configurable log levels and message formats, ensuring compatibility with various external data sources and third-party services.']

