    double value;
    long *offsets;
    size_t offset_count;
} Record;

typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t lock;
} DynamicDataProcessor;

DynamicDataProcessor* initialize(int seed, void (*callback)(void), const char *log_file) {
    DynamicDataProcessor *processor = malloc(sizeof(DynamicDataProcessor));
    if (!processor) return NULL;

    pcg64_srandom_r(seed, time(NULL), (unsigned long int)seed);

    pthread_mutex_init(&processor->lock, NULL);
    processor->records = calloc(MAX_RECORDS, sizeof(Record));
    processor->count = 0;

    FILE *log_fp = fopen(log_file, "w");
    if (!log_fp) {
        free(processor->records);
        free(processor);
        return NULL;
    }
    fprintf(log_fp, "Initialized with seed %d\n", seed);

    fclose(log_fp);

    if (callback) callback();

    return processor;
}

void add_record(DynamicDataProcessor *processor, int key, double value, size_t offset_count, const long *offsets) {
    pthread_mutex_lock(&processor->lock);

    Record *record = &processor->records[processor->count++];
    record->key = key;
    record->value = value;
    record->offsets = malloc(offset_count * sizeof(long));
    if (!record->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        pthread_mutex_unlock(&processor->lock);
        return;
    }
    memcpy(record->offsets, offsets, offset_count * sizeof(long));
    record->offset_count = offset_count;

    pthread_mutex_unlock(&processor->lock);
}

int generate_random(int min, int max) {
    pcg64_state_t state;
    pcg64_srandom_r(min + 1, time(NULL), (unsigned long int)min);
    return pcg64_boundedrand_r(min + 1, &state) + min - 1;
}

void update_records(DynamicDataProcessor *processor) {
    pthread_mutex_lock(&processor->lock);

    for (size_t i = 0; i < processor->count; ++i) {
        Record *record = &processor->records[i];
        record->value = generate_random(0, 100);
        // Update offsets if needed
    }

    pthread_mutex_unlock(&processor->lock);
}

void free_resources(DynamicDataProcessor *processor) {
    pthread_mutex_lock(&processor->lock);

    for (size_t i = 0; i < processor->count; ++i) {
        Record *record = &processor->records[i];
        free(record->offsets);
    }

    free(processor->records);
    pthread_mutex_destroy(&processor->lock);
    free(processor);
}

int largest_integer(DynamicDataProcessor *processor) {
    int max_val = INT_MIN;

    pthread_mutex_lock(&processor->lock);

    for (size_t i = 0; i < processor->count; ++i) {
        Record *record = &processor->records[i];
        if ((int)(record->value) > max_val) {
            max_val = (int)(record->value);
        }
    }

    pthread_mutex_unlock(&processor->lock);

    return max_val;
}

int main() {
    DynamicDataProcessor *processor = initialize(42, NULL, "log.txt");
    if (!processor) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
