    for (int i = 0; i < count; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        record->value = secure_random(value_range_min, value_range_max);
        snprintf(record->key, 20, "key_%d", i);
        record->data_ptr = malloc(sizeof(long));
        if (!record->data_ptr) {
            free(record);
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        *record->data_ptr = rand() % 1000;

        // Initialize children
        int num_children = secure_random(0, 3); // Random number of children between 0 and 3
        record->children = malloc(num_children * sizeof(Record*));
        if (!record->children) {
            free(record->data_ptr);
            free(record);
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < num_children; ++j) {
            record->children[j] = malloc(sizeof(Record));
            if (!record->children[j]) {
                for (int k = 0; k < j; ++k) free(record->children[k]);
                free(record->children);
                free(record->data_ptr);
                free(record);
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }

            record->children[j]->value = secure_random(value_range_min, value_range_max);
            snprintf(record->children[j]->key, 20, "child_key_%d", j);
            record->children[j]->data_ptr = malloc(sizeof(long));
            if (!record->children[j]->data_ptr) {
                for (int k = 0; k <= j; ++k) free(record->children[k]);
                free(record->children);
                free(record->data_ptr);
                free(record);
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }
            *record->children[j]->data_ptr = rand() % 1000;
        }

        record_array[i] = record;

        // Process each record with the callback if provided
        if (callback) {
            callback(record);
        }
    }

    pthread_mutex_unlock(&lock);
}

// Function to free all allocated memory
void freeRecords(int count) {
    for (int i = 0; i < count; ++i) {
        Record *record = record_array[i];
        if (!record) continue;

        for (int j = 0; j < secure_random(0, 3); ++j) { // Random number of children
            free(record->children[j]->data_ptr);
            free(record->children[j]);
        }
        free(record->children);
        free(record->data_ptr);
        free(record);
    }
    free(record_array);
}

// Function to read integers and find the maximum using a helper function
int findMax(int *arr, int size) {
    if (size == 0) return INT_MIN;

    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void processAndFindMaxRecord(size_t record_size, void (*callback)(Record *), int value_range_min, int value_range_max) {
    initArrays(record_count);

    pthread_mutex_lock(&lock);
    record_array = malloc(record_size * sizeof(Record*));
    if (!record_array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&lock);

    initRecords(record_size);

