Document* documents = NULL;
size_t doc_count = 0;
size_t capacity = 0;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_documents(size_t initial_capacity) {
    pthread_mutex_lock(&array_lock);
    if (documents == NULL || capacity < initial_capacity) {
        size_t new_capacity = capacity > 0 ? capacity * 2 : initial_capacity;
        Document* new_docs = realloc(documents, new_capacity * sizeof(Document));
        if (!new_docs) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&array_lock);
            return;
        }
        documents = new_docs;
        for (size_t i = capacity; i < new_capacity; ++i) {
            documents[i].document_id = -1;
            documents[i].metadata.title = NULL;
            documents[i].metadata.author = NULL;
            strcpy(documents[i].metadata.creation_date, "");
            strcpy(documents[i].metadata.last_modified_date, "");
            documents[i].content_type = TEXT;
            documents[i].external_storage_ref = NULL;
            documents[i].version = 0;
            pthread_mutex_init(&documents[i].lock, NULL);
        }
        capacity = new_capacity;
    }
    pthread_mutex_unlock(&array_lock);
}

int add_document(int document_id, const char* title, const char* author,
                 const char* creation_date, const char* last_modified_date,
                 ContentType content_type, const char* external_storage_ref) {
    if (title == NULL || author == NULL || creation_date == NULL ||
        last_modified_date == NULL || external_storage_ref == NULL)
        return -1;

    pthread_mutex_lock(&array_lock);
    size_t new_doc_id = doc_count;
    if (new_doc_id >= capacity) {
        initialize_documents(doc_count + 1);
        if (documents[new_doc_id].document_id != -1) {
            pthread_mutex_unlock(&array_lock);
            return -1;
        }
    }

    Document* doc = &documents[new_doc_id];
    pthread_mutex_lock(&doc->lock);

    doc->document_id = document_id;
    doc->metadata.title = strdup(title);
    doc->metadata.author = strdup(author);
    strncpy(doc->metadata.creation_date, creation_date, sizeof(doc->metadata.creation_date) - 1);
    strncpy(doc->metadata.last_modified_date, last_modified_date, sizeof(doc->metadata.last_modified_date) - 1);
    doc->content_type = content_type;
    doc->external_storage_ref = strdup(external_storage_ref);
    doc->version = 1;

    pthread_mutex_unlock(&doc->lock);

    ++doc_count;
    pthread_mutex_unlock(&array_lock);
    return new_doc_id;
}

void free_documents() {
    for (size_t i = 0; i < doc_count; ++i) {
        Document* doc = &documents[i];
        if (doc->document_id != -1) {
            free(doc->metadata.title);
            free(doc->metadata.author);
            free(doc->external_storage_ref);
            pthread_mutex_destroy(&doc->lock);
        }
    }
    free(documents);
    documents = NULL;
    doc_count = 0;
    capacity = 0;
}

// Example usage
int main() {
    initialize_documents(10);

    int doc_id1 = add_document(1, "Doc Title", "Author Name",
                              "2023-01-01", "2023-01-02", TEXT, "ext_ref_1");
    if (doc_id1 != -1) {
        printf("Document added with ID: %d\n", doc_id1);
    }

    free_documents();
    return 0;
}
