void processGraphAndFindMax(size_t offset_size, size_t key_size, 
                            size_t min_records, size_t max_records,
                            size_t min_edges, size_t max_edges,
                            void (*callback)(const record*, const edge*)) {

    // Step 1: Initialize 'offset' and 'key' arrays
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < offset_size && i < key_size; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Step 2: Allocate and initialize 'record' array
    size_t num_records = secure_random(min_records, max_records);
    record *records = malloc(num_records * sizeof(record));

    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = secure_random(1, 100); // Example range
        char key_buffer[16];
        snprintf(key_buffer, sizeof(key_buffer), "Key%zu", i);
        records[i].key = strdup(key_buffer);

        long *dynamic_long_ptr = malloc(sizeof(long));
        if (!dynamic_long_ptr) {
            fprintf(stderr, "Memory allocation failed\n");
            for (size_t j = 0; j <= i; ++j) free(records[j].key);
            free(records);
            free(offsets);
            free(keys);
            return;
        }

        *dynamic_long_ptr = secure_random(1, 100); // Example range
        records[i].dynamic_long_ptr = dynamic_long_ptr;

        if (callback) callback(&records[i], NULL);
    }

    // Step 3: Allocate and initialize 'edge' array
    size_t num_edges = secure_random(min_edges, max_edges);
    edge *edges = malloc(num_edges * sizeof(edge));

    if (!edges) {
        fprintf(stderr, "Memory allocation failed\n");
        for (size_t i = 0; i < num_records; ++i) {
            free(records[i].key);
            free(records[i].dynamic_long_ptr);
        }
        free(records);
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < num_edges; ++i) {
        edges[i].weight = secure_random(1, 50); // Example range
        edges[i].type = 'A' + (secure_random(0, 25) % 26);

        if (callback) callback(NULL, &edges[i]);
    }

    // Step 4: Read integers from standard input into a dynamically allocated array
    int *input_array = NULL;
    size_t current_size = 0;

    while (1) {
        int value;
        if (scanf("%d", &value) != 1 || value == -1) break;

        if (current_size == 0 || current_size <= input_array_capacity) {
            size_t new_capacity = (current_size + 1) * 2;
            int *new_input_array = realloc(input_array, new_capacity * sizeof(int));

            if (!new_input_array) {
                fprintf(stderr, "Memory allocation failed\n");
                free(input_array);
                break;
            }

            input_array = new_input_array;
        }

        input_array[current_size++] = value;
    }

    // Step 5: Free all allocated memory
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].key);
        free(records[i].dynamic_long_ptr);
    }
    free(records);

    free(edges);
    free(input_array);
    free(offsets);
    free(keys);
}
