#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming these are provided by the external library
extern void secure_random_bytes(void *buf, size_t num);
extern int compress_data(const char *src, size_t src_size, char **dest);

typedef struct {
    char *file_path;
    size_t block_size;
    int compression_status;
} data_block;

// Global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_resources(size_t offset_size, char **file_paths, data_block *data_blocks) {
    for (size_t i = 0; i < offset_size; ++i) {
        free(file_paths[i]);
    }
    free(file_paths);
    free(data_blocks);
}

int manageFileStorageAndCompression(size_t max_files, size_t min_blocks, size_t max_blocks,
                                    void (*callback)(data_block *block)) {

    if (max_files == 0 || min_blocks > max_blocks) return -1;

    size_t offset_size = max_files;
    size_t file_path_size = max_files;
    char **file_paths = malloc(file_path_size * sizeof(char *));
    if (!file_paths) return -1;

    for (size_t i = 0; i < file_path_size; ++i) {
        file_paths[i] = malloc(256); // Assuming each path won't exceed 255 chars + null terminator
        if (!file_paths[i]) goto error;
        snprintf(file_paths[i], 256, "file_%zu", i);
    }

    data_block *data_blocks;
    size_t num_blocks = min_blocks; // Start with the minimum number of blocks

    do {
        data_blocks = realloc(data_blocks, num_blocks * sizeof(data_block));
        if (!data_blocks) goto error;

        for (size_t i = 0; i < num_blocks; ++i) {
            pthread_mutex_lock(&lock);
            data_blocks[i].file_path = malloc(strlen(file_paths[i % file_path_size]) + 1);
            if (!data_blocks[i].file_path) {
                pthread_mutex_unlock(&lock);
                goto error;
            }
            strcpy(data_blocks[i].file_path, file_paths[i % file_path_size]);
            data_blocks[i].block_size = rand() % (1024 * 1024); // Random block size up to 1MB
            secure_random_bytes((void *)data_blocks[i].block_path, data_blocks[i].block_size);
            data_blocks[i].compression_status = 0; // Not compressed by default

            if (callback) callback(&data_blocks[i]);

            pthread_mutex_unlock(&lock);
        }
    } while (++num_blocks <= max_blocks);

    return 0;

error:
    free_resources(offset_size, file_paths, data_blocks);
    return -1;
}
