}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Metric *metric = table->buckets[i];
        while (metric) {
            Metric *temp = metric;
            metric = metric->next;
            pthread_mutex_destroy(&temp->lock);
            free(temp);
        }
    }

    free(table->buckets);
    free(table);
}

unsigned long hash(int source_id, size_t capacity) {
    return ((unsigned long)source_id) % capacity;
}

Metric* get_or_create_metric(HashTable *table, int source_id) {
    unsigned long index = hash(source_id, table->capacity);
    Metric *metric = table->buckets[index];

    while (metric) {
        if (metric->source_id == source_id)
            return metric;

        metric = metric->next;
    }

    metric = malloc(sizeof(Metric));
    if (!metric) return NULL;

    pthread_mutex_init(&metric->lock, NULL);
    metric->count = 0;
    metric->sum = 0.0;
    metric->average = 0.0;
    metric->source_id = source_id;
    metric->next = table->buckets[index];

    table->buckets[index] = metric;

    return metric;
}

void aggregate_metric(Metric *metric, double value) {
    pthread_mutex_lock(&metric->lock);
    metric->count++;
    metric->sum += value;
    metric->average = metric->sum / metric->count;
    pthread_mutex_unlock(&metric->lock);
}

typedef void (*Callback)(LogEntry *, Metric *);

void process_log_and_aggregate_metrics(int min_entries, int max_entries, Callback log_entry_callback, Callback metric_update_callback) {
    initialize_timestamps();

    LogEntry *log_entries = malloc(INITIAL_LOG_ENTRY_CAPACITY * sizeof(LogEntry));
    size_t log_entry_count = 0;
    size_t capacity = INITIAL_LOG_ENTRY_CAPACITY;

    HashTable *metrics_table = create_hash_table(HASH_TABLE_INITIAL_CAPACITY);

    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        if (strncmp(line, "END", 3) == 0) break;

        // Simulating log entry parsing
        int source_id = rand() % 100;
        const char *message = "Sample Log Message";
        Timestamp *timestamp = &timestamps[rand() % TIMESTAMP_ARRAY_SIZE];

        if (log_entry_count >= capacity) {
            capacity *= 2;
            log_entries = realloc(log_entries, capacity * sizeof(LogEntry));
            if (!log_entries) break; // Handle reallocation failure
        }

        LogEntry *entry = create_log_entry(source_id, message, timestamp);
        if (!entry) continue;

        log_entries[log_entry_count++] = *entry;

        Metric *metric = get_or_create_metric(metrics_table, source_id);
        if (metric) {
            aggregate_metric(metric, 1.0); // Example metric value

            if (metric_update_callback)
                metric_update_callback(entry, metric);
        }

        free_log_entry(&log_entries[log_entry_count - 1]);

        if (log_entry_callback)
            log_entry_callback(&log_entries[log_entry_count - 1], NULL);

        if (log_entry_count >= max_entries) break;
    }

    // Cleanup
    for (size_t i = 0; i < log_entry_count; ++i) {
        free_log_entry(&log_entries[i]);
    }

    free(log_entries);
    free_hash_table(metrics_table);
}

// Example callback functions
void log_entry_callback(LogEntry *entry, Metric *metric) {
    printf("Processed log entry from source %d: %s\n", entry->source_id, entry->message);
}

void metric_update_callback(LogEntry *entry, Metric *metric) {
    printf("Updated metrics for source %d: count=%d, sum=%.2f, average=%.2f\n",
           metric->source_id, metric->count, metric->sum, metric->average);
}

int main() {
    process_log_and_aggregate_metrics(10, 1000, log_entry_callback, metric_update_callback);
    return 0;
}
