#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct OffsetRecord {
    long offset;
    int key;
} OffsetRecord;

typedef struct RecordNode {
    OffsetRecord data;
    struct RecordNode* next;
} RecordNode;

typedef struct HashTable {
    RecordNode** buckets;
    size_t num_buckets;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} HashTable;

// Function prototypes
HashTable* create_table(size_t num_buckets);
void destroy_table(HashTable* table);
int hash_function(int key, size_t num_buckets);
RecordNode* create_node(long offset, int key);
void insert_record(HashTable* table, long offset, int key);
RecordNode* search_key(HashTable* table, int key);
void delete_record(HashTable* table, int key);

// Create a new hash table
HashTable* create_table(size_t num_buckets) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(num_buckets, sizeof(RecordNode*));
    table->num_buckets = num_buckets;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Destroy the hash table
void destroy_table(HashTable* table) {
    for (size_t i = 0; i < table->num_buckets; ++i) {
        RecordNode* node = table->buckets[i];
        while (node != NULL) {
            RecordNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Hash function
int hash_function(int key, size_t num_buckets) {
    return (key & 0x7FFFFFFF) % num_buckets; // Handle negative keys
}

// Create a new node for the linked list in each bucket
RecordNode* create_node(long offset, int key) {
    RecordNode* node = malloc(sizeof(RecordNode));
    node->data.offset = offset;
    node->data.key = key;
    node->next = NULL;
    return node;
}

// Insert a record into the hash table
void insert_record(HashTable* table, long offset, int key) {
    pthread_mutex_lock(&table->lock);

    int bucket_index = hash_function(key, table->num_buckets);
    RecordNode* new_node = create_node(offset, key);

    // Insert at the head of the linked list in this bucket
    new_node->next = table->buckets[bucket_index];
    table->buckets[bucket_index] = new_node;

    pthread_mutex_unlock(&table->lock);
}

// Search for a record by key
RecordNode* search_key(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    int bucket_index = hash_function(key, table->num_buckets);
    RecordNode* node = table->buckets[bucket_index];

    while (node != NULL && node->data.key != key) {
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return node; // Returns NULL if not found
}

// Delete a record by key
void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    int bucket_index = hash_function(key, table->num_buckets);
    RecordNode *current = table->buckets[bucket_index], 
               *prev = NULL;

    while (current != NULL && current->data.key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Key not found
        pthread_mutex_unlock(&table->lock);
        return;
    }

    if (prev == NULL) { // Node is the first node in the list
        table->buckets[bucket_index] = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&table->lock);
}

int main() {
    HashTable* table = create_table(10);

    insert_record(table, 100L, 1);
    insert_record(table, 200L, 2);

    RecordNode* record = search_key(table, 1);
    if (record != NULL) {
        printf("Found key: %d with offset: %ld\n", record->data.key, record->data.offset);
    }

    delete_record(table, 1);

    destroy_table(table);
    return 0;
}
