#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_SIZE 1000
#define MEMORY_THRESHOLD (1024 * 1024 * 50) // 50 MB threshold for memory usage

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} record;

// Atomic variables to track memory usage and resizing state
_Atomic size_t total_memory_usage = 0;
_Atomic size_t resize_in_progress = 0;

// Mutex for logging
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

size_t get_current_memory_usage() {
    return atomic_load(&total_memory_usage);
}

long* allocate_offsets(size_t size, int max_size) {
    if (size > max_size) {
        log_message("Offset array size exceeds maximum allowed limit.");
        return NULL;
    }

    long* offsets = calloc(size, sizeof(long));
    if (!offsets) {
        log_message("Failed to allocate memory for offset array.");
        return NULL;
    }

    atomic_fetch_add(&total_memory_usage, size * sizeof(long));
    log_message("Allocated and initialized offset array.");
    return offsets;
}

int* allocate_keys(size_t size, int max_size) {
    if (size > max_size) {
        log_message("Key array size exceeds maximum allowed limit.");
        return NULL;
    }

    int* keys = calloc(size, sizeof(int));
    if (!keys) {
        log_message("Failed to allocate memory for key array.");
        return NULL;
    }

    atomic_fetch_add(&total_memory_usage, size * sizeof(int));
    log_message("Allocated and initialized key array.");
    return keys;
}

record* allocate_records(size_t size, size_t max_size, long* offsets, int* keys) {
    if (size > max_size) {
        log_message("Record array size exceeds maximum allowed limit.");
        return NULL;
    }

    record* records = calloc(size, sizeof(record));
    if (!records) {
        log_message("Failed to allocate memory for record array.");
        return NULL;
    }

    atomic_fetch_add(&total_memory_usage, size * sizeof(record));

    // Initialize records
    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < size; ++i) {
        if (i < _Atomic_load(&offsets)) {
            records[i].offset_ptr = &offsets[i];
        } else {
            records[i].offset_ptr = NULL;
        }

        if (i < _Atomic_load(&keys)) {
            records[i].key_ptr = &keys[i];
        } else {
            records[i].key_ptr = NULL;
        }

        records[i].value = rand() % 100; // Example range
    }

    log_message("Allocated and initialized record array.");
    return records;
}

void free_memory(long* offsets, int size_offsets, int* keys, int size_keys, record* records, int size_records) {
    if (offsets) {
        atomic_fetch_sub(&total_memory_usage, size_offsets * sizeof(long));
        free(offsets);
        log_message("Freed offset array.");
    }

    if (keys) {
        atomic_fetch_sub(&total_memory_usage, size_keys * sizeof(int));
        free(keys);
        log_message("Freed key array.");
    }

    if (records) {
        atomic_fetch_sub(&total_memory_usage, size_records * sizeof(record));
        free(records);
        log_message("Freed record array.");
    }
}

void monitor_memory_usage() {
    while (1) {
        sleep(5); // Check every 5 seconds
        size_t current_usage = get_current_memory_usage();

        if (current_usage > MEMORY_THRESHOLD) {
            log_message("Memory usage exceeded threshold!");
        }
    }
}

int main(int argc, char* argv[]) {
    size_t offsets_size = 100; // Example input
    size_t keys_size = 200;    // Example input
    size_t records_size = 50;  // Example input

    long* offsets = allocate_offsets(offsets_size, MAX_SIZE);
    int* keys = allocate_keys(keys_size, MAX_SIZE);

    if (get_current_memory_usage() > MEMORY_THRESHOLD) {
        log_message("Memory usage exceeded threshold before allocation!");
    }

    record* records = allocate_records(records_size, MAX_SIZE, offsets, keys);

    // Monitor memory usage in a separate thread
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void*)monitor_memory_usage, NULL);

    // Simulate work
    sleep(10); // Sleep for demonstration purposes

    free_memory(offsets, offsets_size, keys, keys_size, records, records_size);

    pthread_cancel(monitor_thread);
    return 0;
}
