typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct transaction {
    int id;
    struct transaction *next;
} transaction;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
transaction *head_transaction = NULL;

long *allocate_offsets(size_t size) {
    return (long *)calloc(size, sizeof(long));
}

int *allocate_keys(size_t size) {
    return (int *)calloc(size, sizeof(int));
}

record *initialize_records(size_t size, long *offsets, int *keys) {
    record *records = (record *)malloc(size * sizeof(record));
    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % VALUE_RANGE;
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];
    }

    return records;
}

void add_transaction(int id) {
    pthread_mutex_lock(&lock);
    transaction *new_txn = (transaction *)malloc(sizeof(transaction));
    new_txn->id = id;
    new_txn->next = head_transaction;
    head_transaction = new_txn;
    pthread_mutex_unlock(&lock);
}

void remove_transactions() {
    pthread_mutex_lock(&lock);
    while (head_transaction) {
        transaction *tmp = head_transaction;
        head_transaction = head_transaction->next;
        free(tmp);
    }
    pthread_mutex_unlock(&lock);
}

void log_operation(const char *operation, size_t index) {
    printf("Operation: %s on record index %zu\n", operation, index);
}

void export_data(record *records, size_t size, const char *filename) {
