    int *keys = allocate_keys(record_count);

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return EXIT_FAILURE;
    }

    record *records = initialize_records(record_count, offsets, keys);
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        free_resources(records, offsets, keys);
        return EXIT_FAILURE;
