#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *name;
    char type; // 's' for string, 'i' for integer, 'f' for float/double
    void *defaultValue;
    void *currentValue;
    int uniqueID;
} Resource;

typedef struct {
    double value;
} Chunk;

typedef struct {
    Resource *resources;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ResourceManager;

typedef struct {
    Chunk *chunks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ChunkManager;

void handleDynamicResourceAllocationAndCacheManagement(size_t initialResourceCapacity, size_t initialChunkCapacity);

static void resizeArray(void **array, size_t currentCapacity, size_t newCapacity, size_t elementSize);
static int validateInput(const char *name, const void *value, char type);
static void addResource(ResourceManager *manager, const char *name, char type, const void *defaultValue);
static void addChunk(ChunkManager *chunkManager, double value);

void handleDynamicResourceAllocationAndCacheManagement(size_t initialResourceCapacity, size_t initialChunkCapacity) {
    ResourceManager resourceManager = {NULL, initialResourceCapacity, 0, PTHREAD_MUTEX_INITIALIZER};
    ChunkManager chunkManager = {NULL, initialChunkCapacity, 0, PTHREAD_MUTEX_INITIALIZER};

    // Initialize resources
    resourceManager.resources = malloc(initialResourceCapacity * sizeof(Resource));
    if (!resourceManager.resources) {
        perror("Failed to allocate memory for resources");
        return;
    }
    memset(resourceManager.resources, 0, initialResourceCapacity * sizeof(Resource));

    // Initialize chunks
    chunkManager.chunks = malloc(initialChunkCapacity * sizeof(Chunk));
    if (!chunkManager.chunks) {
        free(resourceManager.resources);
        perror("Failed to allocate memory for chunks");
        return;
    }
    memset(chunkManager.chunks, 0, initialChunkCapacity * sizeof(Chunk));

    // Example: Add a resource
    addResource(&resourceManager, "exampleResource", 's', "defaultValue");

    // Example: Add a chunk
    addChunk(&chunkManager, 3.14);

    // Clean up
    free(resourceManager.resources);
    free(chunkManager.chunks);
}

static void resizeArray(void **array, size_t currentCapacity, size_t newCapacity, size_t elementSize) {
    if (newCapacity > currentCapacity) {
        *array = realloc(*array, newCapacity * elementSize);
        if (!*array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        memset((char *)(*array) + currentCapacity * elementSize, 0, (newCapacity - currentCapacity) * elementSize);
    }
}

static int validateInput(const char *name, const void *value, char type) {
    if (!name || !value) return 0;
    switch (type) {
        case 's': // Validate string
            return name != NULL && strlen(name) > 0;
        case 'i': // Validate integer (dummy check)
        case 'f': // Validate float/double (dummy check)
            return value != NULL; // Implement more specific checks as needed
        default:
            return 0;
    }
}

static void addResource(ResourceManager *manager, const char *name, char type, const void *defaultValue) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resizeArray((void **)&manager->resources, manager->capacity, manager->capacity * 2, sizeof(Resource));
        manager->capacity *= 2;
    }

    Resource resource = { .name = strdup(name), .type = type };
    switch (type) {
        case 's': resource.defaultValue = strdup(defaultValue); break;
        case 'i': resource.defaultValue = malloc(sizeof(int)); *(int *)resource.defaultValue = *(const int *)defaultValue; break;
        case 'f': resource.defaultValue = malloc(sizeof(double)); *(double *)resource.defaultValue = *(const double *)defaultValue; break;
    }
    resource.currentValue = resource.defaultValue;

    manager->resources[manager->count++] = resource;

    pthread_mutex_unlock(&manager->lock);
}

static void addChunk(ChunkManager *chunkManager, double value) {
    pthread_mutex_lock(&chunkManager->lock);

    if (chunkManager->count >= chunkManager->capacity) {
        resizeArray((void **)&chunkManager->chunks, chunkManager->capacity, chunkManager->capacity * 2, sizeof(Chunk));
        chunkManager->capacity *= 2;
    }

    Chunk newChunk = { .value = value };
    chunkManager->chunks[chunkManager->count++] = newChunk;

    pthread_mutex_unlock(&chunkManager->lock);
}
