    char *currentState;
    char *uniqueIdentifier;
    int versionNumber;
} DataStream;

typedef struct {
    DataStream *streams;
    size_t streamCount;
    pthread_mutex_t lock; // For thread safety
} DataProcessingFramework;

// Function to dynamically resize the streams array
int resizeStreams(DataProcessingFramework *framework, size_t newCapacity) {
    pthread_mutex_lock(&framework->lock);

    DataStream *newStreams = realloc(framework->streams, newCapacity * sizeof(DataStream));
    if (newStreams == NULL) {
        pthread_mutex_unlock(&framework->lock);
        return -1;
    }

    framework->streams = newStreams;
    size_t oldCount = framework->streamCount;
    for (size_t i = oldCount; i < newCapacity; ++i) {
        // Initialize new entries as needed
        framework->streams[i].streamName = NULL;
        framework->streams[i].type = TEXT; // Default type, can be adjusted later
        framework->streams[i].defaultValue = NULL;
        framework->streams[i].currentState = "Initialized";
        framework->streams[i].uniqueIdentifier = NULL;
        framework->streams[i].versionNumber = 1;
    }

    framework->streamCount = newCapacity;
    pthread_mutex_unlock(&framework->lock);

    return 0;
}

// Initialize the DataProcessingFramework
int initializeFramework(DataProcessingFramework *framework, size_t initialCapacity) {
    framework->streams = malloc(initialCapacity * sizeof(DataStream));
    if (framework->streams == NULL) {
        return -1; // Memory allocation failed
    }

    framework->streamCount = 0;
    pthread_mutex_init(&framework->lock, NULL);

    return resizeStreams(framework, initialCapacity);
}

// Clean up resources in the DataProcessingFramework
void cleanupFramework(DataProcessingFramework *framework) {
    for (size_t i = 0; i < framework->streamCount; ++i) {
        free(framework->streams[i].streamName);
        free(framework->streams[i].currentState);
        free(framework->streams[i].uniqueIdentifier);
        // Additional cleanup as necessary
    }

    pthread_mutex_destroy(&framework->lock);
    free(framework->streams);
}

